3081	object	SC21	d37cae378925f5d05f1418e228837b63ebd257e2ba915c45dac8d71770b5f4bf	\N	{"refs": [{"path": "GreekOS_Audio_and_Speaking/scenarios/SC21.json", "sha256": "6143cee6096ec8589d42a52e937a1a2b7c143fb44d83427d7d848acb1f5a95c7", "pointer": ""}], "payload": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "NOT_REVIEWED"}, "nodes": [{"node_id": "OPEN", "transitions": [{"to": "TWIST", "condition": "Learner conveys relevant initial request, any semantically suitable wording"}, {"to": "REPAIR", "condition": "Learner asks for repetition or message is unintelligible"}], "assistant_el": "Παίζεις ποδόσφαιρο;", "learner_goal_ru": "Рассказать об интересе к футболу и договориться об игре", "acceptable_examples_el": ["Ναι, παίζω με φίλους το Σάββατο. Εσύ;", "Μου αρέσει το ποδόσφαιρο, αλλά δεν παίζω συχνά."]}, {"node_id": "TWIST", "transitions": [{"to": "NEGOTIATE", "condition": "Learner responds to changed constraint or proposes valid refusal"}, {"to": "REPAIR", "condition": "Learner explicitly asks clarification or ignores changed constraint"}], "assistant_el": "Παίζουμε αύριο στις πέντε. Θέλεις να έρθεις;", "learner_goal_ru": "Реагировать на новое ограничение, не повторить первоначальную просьбу механически", "acceptable_examples_el": ["Ναι. Πού είναι το γήπεδο;"]}, {"node_id": "REPAIR", "transitions": [{"to": "TWIST", "condition": "After one clarification, restate the TWIST line in shorter pieces without supplying the learner answer"}, {"to": "RETRY", "condition": "After two repair loops learner still cannot continue, end with supported retry, no independent mastery"}], "assistant_el": "Να το πω ξανά;", "learner_goal_ru": "Назвать непонятое слово, время, количество или условие", "acceptable_examples_el": ["Μπορείτε να επαναλάβετε την ώρα;", "Δεν κατάλαβα το τελευταίο σημείο."]}, {"node_id": "NEGOTIATE", "transitions": [{"to": "CLOSE", "condition": "Learner confirms a feasible outcome and addresses the challenge"}, {"to": "RETRY", "condition": "Outcome still infeasible or new plausible request outside script, paraphrase constraint once then allow retry"}], "assistant_el": "Δίπλα στο σχολείο. Έχεις μπάλα;", "learner_goal_ru": "Проверить последнюю деталь или предложить допустимый компромисс", "acceptable_examples_el": ["Όχι, αλλά μπορώ να φέρω νερό."]}, {"node_id": "CLOSE", "transitions": [], "assistant_el": "Ωραία, αύριο στις πέντε δίπλα στο σχολείο.", "learner_goal_ru": "Назвал интерес и подтвердил время/место игры; δεν ισχυρίζεται πραγματικό πρόγραμμα клуба.", "acceptable_examples_el": ["Ευχαριστώ!"]}, {"node_id": "RETRY", "transitions": [], "assistant_el": "Ας σταματήσουμε εδώ και ας δούμε ποιο σημείο χρειάζεται διευκρίνιση.", "learner_goal_ru": "Завершить без ложного результата; разобрать одну ошибку и повторить с новыми данными", "acceptable_examples_el": ["Θέλω να δοκιμάσω ξανά."]}], "domain": "Спорт", "rubric": {"scale": "0=не продемонстрировано;1=с помощью;2=самостоятельно; не официальный балл", "language": "Диапазон и точность в пределах уровня; смысл важнее дословного совпадения", "register": "Уместно выбирает вежливость и адресата", "requires": ["evidence_spans", "assistance_level", "confidence", "abstention_reason_if_uncertain"], "interaction": "Отвечает на новую информацию, уточняет и достигает/честно ограничивает результат", "task_success": "Назвал интерес и подтвердил время/место игры; δεν ισχυρίζεται πραγματικό πρόγραμμα клуба.", "pronunciation": "Оценивать только по реально прослушанному аудио; по транскрипту NO_SCORE"}, "status": "DRAFT", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "audio_file": null, "cefr_level": "A1", "entry_node": "OPEN", "hint_limits": {"exam_mode": "Никаких языковых подсказок; допустима организационная реплика без ответа", "practice_mode": "До двух пояснений после запроса; учитывать помощь"}, "scenario_id": "SC21", "facts_policy": "Все имена/суммы/сроки/процедуры — условия учебной роли. Не актуальные правила организаций. Не запрашивать реальные реквизиты.", "script_status": "AUTHORED", "retention_days": [7, 14, 28], "content_version": "0.1.1", "critical_errors": [{"type": "CONTENT_OMISSION", "criterion": "Игнорирует изменившиеся условия, подтверждает невыполнимый результат"}, {"type": "COMPREHENSION", "criterion": "Путает участника, время, сумму или следующий шаг; предварительно исключить ASR ошибку"}], "feedback_policy": {"after_dialogue": "Сначала отметить достигнутый результат; затем максимум3 ошибки: фрагмент → вариант → причина → самокоррекция", "during_free_speech": "Не прерывать мелкими исправлениями, если смысл понятен", "sample_feedback_ru": "Вы подтвердили итог, но не отреагировали на изменённое время. Повторите только новую договорённость.", "speech_recognition_uncertain": "ASR_UNCERTAIN, score withheld, ask repeat; not grammar/pronunciation penalty"}, "original_record": {"domain": "Спорт", "cefr_level": "A1", "provenance": "original_author_designed", "scenario_id": "SC21", "competency_ids": ["A1-V01", "A1-G06"], "validation_status": "requires_greek_teacher_review", "assessment_criteria": "Обе стороны понимают договорённость", "vocabulary_examples": ["ομάδα", "αγώνας", "προπόνηση"], "alignment_source_ids": ["S13", "S14"], "communication_objective": "Рассказать об интересе к футболу и договориться об игре", "conversation_complexity": "2–3 минуты; выбрать место и время", "progression_requirement": "Незнакомый партнёр", "likely_errors_hypotheses": "Спряжение; ударение"}, "branching_status": "AUTHORED", "transfer_task_ru": "Погода меняется: простыми фразами перенести игру на другой день.", "off_script_policy": {"unknown_fact": "Сказать, что нужно уточнить; не выдумывать ответ", "max_repair_loops": 2, "transition_ambiguity": "Prefer clarification; do not penalize ASR uncertainty", "unsafe_real_world_emergency": "Прервать учебную роль и дать уместный реальный ответ", "semantically_valid_unlisted_response": "Accept; examples are not exact keys"}, "learning_objective": "Рассказать об интересе к футболу и договориться об игре", "spoken_eval_status": "NOT_VALIDATED", "audio_review_status": "MISSING_AUDIO", "primary_competencies": ["A1-V01", "A1-G06"]}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3082	object	SC40	a27f8514690bda34947dd2861ada6bd133c4b893dd63a4395223c9bad3a3b956	\N	{"refs": [{"path": "GreekOS_Audio_and_Speaking/scenarios/SC40.json", "sha256": "bc778ec63f3a3124c9d337511a2eed0ee18ea9ffe8b5b96ead9f48fbc6e0fe9a", "pointer": ""}], "payload": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "NOT_REVIEWED"}, "nodes": [{"node_id": "OPEN", "transitions": [{"to": "TWIST", "condition": "Learner conveys relevant initial request, any semantically suitable wording"}, {"to": "REPAIR", "condition": "Learner asks for repetition or message is unintelligible"}], "assistant_el": "Μπορείτε να εξηγήσετε επίσημα την καθυστέρηση και τον τρόπο υποβολής;", "learner_goal_ru": "Управление, различение канала/причины и переход к простому объяснению сохранены.", "acceptable_examples_el": ["Λόγω της βλάβης, υπάρχει καθυστέρηση. Η υποβολή γίνεται μέσω της πλατφόρμας."]}, {"node_id": "TWIST", "transitions": [{"to": "NEGOTIATE", "condition": "Learner responds to changed constraint or proposes valid refusal"}, {"to": "REPAIR", "condition": "Learner explicitly asks clarification or ignores changed constraint"}], "assistant_el": "Ο ενδιαφερόμενος δεν καταλαβαίνει αυτές τις εκφράσεις.", "learner_goal_ru": "Управление, различение канала/причины и переход к простому объяснению сохранены.", "acceptable_examples_el": ["Το σύστημα έχει χαλάσει και χρειάζεται περισσότερος χρόνος. Χρησιμοποιήστε την πλατφόρμα για να στείλετε το έντυπο."]}, {"node_id": "REPAIR", "transitions": [{"to": "TWIST", "condition": "After one clarification, restate the TWIST line in shorter pieces without supplying the learner answer"}, {"to": "RETRY", "condition": "After two repair loops learner still cannot continue, end with supported retry, no independent mastery"}], "assistant_el": "Να το πω ξανά;", "learner_goal_ru": "Уточнить непонятое; при помощи самостоятельное освоение не засчитывать.", "acceptable_examples_el": ["Ναι, παρακαλώ."]}, {"node_id": "NEGOTIATE", "transitions": [{"to": "CLOSE", "condition": "Learner confirms a feasible outcome and addresses the challenge"}, {"to": "RETRY", "condition": "Outcome still infeasible or new plausible request outside script, paraphrase constraint once then allow retry"}], "assistant_el": "Χρειάζεται υπογραφή σύμφωνα με τον κανονισμό. Πώς θα το προσθέσετε;", "learner_goal_ru": "Управление, различение канала/причины и переход к простому объяснению сохранены.", "acceptable_examples_el": ["Σύμφωνα με τον κανονισμό, χρειάζεται υπογραφή. Δηλαδή, πρέπει να υπογράψετε το έντυπο πριν το στείλετε."]}, {"node_id": "CLOSE", "transitions": [], "assistant_el": "Ευχαριστώ. Συμφωνήσαμε.", "learner_goal_ru": "Управление, различение канала/причины и переход к простому объяснению сохранены.", "acceptable_examples_el": ["Ευχαριστώ."]}, {"node_id": "RETRY", "transitions": [], "assistant_el": "Ας δοκιμάσουμε ξανά αργότερα.", "learner_goal_ru": "Уточнить непонятое; при помощи самостоятельное освоение не засчитывать.", "acceptable_examples_el": ["Εντάξει."]}], "domain": "Формальные связи: предлоги и управление", "rubric": {"scale": "0=не продемонстрировано;1=с помощью;2=самостоятельно; не официальный балл", "language": "Диапазон и точность в пределах уровня; смысл важнее дословного совпадения", "register": "Уместно выбирает вежливость и адресата", "requires": ["evidence_spans", "assistance_level", "confidence", "abstention_reason_if_uncertain"], "interaction": "Отвечает на новую информацию, уточняет и достигает/честно ограничивает результат", "task_success": "Управление, различение канала/причины и переход к простому объяснению сохранены.", "pronunciation": "Оценивать только по реально прослушанному аудио; по транскрипту NO_SCORE"}, "status": "DRAFT", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "audio_file": null, "cefr_level": "B2", "entry_node": "OPEN", "hint_limits": {"exam_mode": "Никаких языковых подсказок; допустима организационная реплика без ответа", "practice_mode": "До двух пояснений после запроса; учитывать помощь"}, "scenario_id": "SC40", "source_refs": [{"anchor": "Историческая уровневая тематическая карта; размещение требует эксперта", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Reception, production, interaction; author mapping, not official cut score", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "§8: προθέσεις; λόγιες, σύνθετες конструкции", "source_id": "N408", "checked_on": "2026-10-14", "claim_scope": "Грамматическое/фонетическое правило; задания оригинальные", "evidence_type": "OFFICIAL_SCHOOL_GRAMMAR_NOT_AUTH_SYLLABUS"}, {"anchor": "§4, genitive/accusative lists", "source_id": "N409", "checked_on": "2026-10-14", "claim_scope": "Explicit government of λόγω/εξαιτίας/μέσω and με", "evidence_type": "OFFICIAL_KEG_GRAMMAR_REFERENCE"}], "facts_policy": "Вымышленная учебная роль; пример ответа не обязательный скрипт ученика; параметры роли не актуальные правила учреждения.", "script_status": "AUTHORED", "linked_unit_id": "U-B2-005", "retention_days": [7, 14, 28], "content_version": "0.1.0", "critical_errors": [{"type": "GENITIVE_GOVERNMENT", "criterion": "Проверить соответствующее различие по rubric linked unit; не выводить ошибку из неуверенного ASR."}, {"type": "ACC_AFTER_ME", "criterion": "Проверить соответствующее различие по rubric linked unit; не выводить ошибку из неуверенного ASR."}, {"type": "CHANNEL_CAUSE_CONFUSION", "criterion": "Проверить соответствующее различие по rubric linked unit; не выводить ошибку из неуверенного ASR."}, {"type": "MISSING_ME", "criterion": "Проверить соответствующее различие по rubric linked unit; не выводить ошибку из неуверенного ASR."}, {"type": "REGISTER_OBSCURES_MEANING", "criterion": "Проверить соответствующее различие по rubric linked unit; не выводить ошибку из неуверенного ASR."}, {"type": "UNSUPPORTED_CERTAINTY", "criterion": "Проверить соответствующее различие по rubric linked unit; не выводить ошибку из неуверенного ASR."}], "feedback_policy": {"after_dialogue": "Сначала отметить достигнутый результат; затем максимум3 ошибки: фрагмент → вариант → причина → самокоррекция", "during_free_speech": "Не прерывать мелкими исправлениями, если смысл понятен", "sample_feedback_ru": "Покажите конкретный фрагмент ответа, объясните одно несоответствие цели и предложите самостоятельную повторную попытку с новым содержанием.", "speech_recognition_uncertain": "ASR_UNCERTAIN, score withheld, ask repeat; not grammar/pronunciation penalty"}, "branching_status": "AUTHORED", "transfer_task_ru": "День 28: напишите 3 предложения посетителю библиотеки: задержка из-за ремонта, запрос через сотрудника, согласно правилам нужна карточка. Факты — условия учебной роли.", "off_script_policy": {"unknown_fact": "Сказать, что нужно уточнить; не выдумывать ответ", "max_repair_loops": 2, "transition_ambiguity": "Prefer clarification; do not penalize ASR uncertainty", "unsafe_real_world_emergency": "Прервать учебную роль и дать уместный реальный ответ", "semantically_valid_unlisted_response": "Accept; examples are not exact keys"}, "learning_objective": "Управление, различение канала/причины и переход к простому объяснению сохранены.", "spoken_eval_status": "NOT_VALIDATED", "audio_review_status": "MISSING_AUDIO", "primary_competencies": ["B2-G06"]}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
