3085	object	SC09	dd49ffe2e7334eb91d0dc1501ee6c854fd28d5ea49a6cd18cd2299724c35e733	\N	{"refs": [{"path": "GreekOS_Audio_and_Speaking/scenarios/SC09.json", "sha256": "8d3a119a85ae22a4ecf4c91008985bb181cc17348466f8f737c9f5aa538bd50d", "pointer": ""}], "payload": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "NOT_REVIEWED"}, "nodes": [{"node_id": "OPEN", "transitions": [{"to": "TWIST", "condition": "Learner conveys relevant initial request, any semantically suitable wording"}, {"to": "REPAIR", "condition": "Learner asks for repetition or message is unintelligible"}], "assistant_el": "Για ποιο θέμα περιμένετε;", "learner_goal_ru": "Уточнить окно, очередь и комплект документов", "acceptable_examples_el": ["Θέλω να καταθέσω αυτή την αίτηση. Σε ποιο γραφείο πρέπει να πάω;", "Μπορείτε να μου πείτε ποιο παράθυρο εξυπηρετεί τις αιτήσεις;"]}, {"node_id": "TWIST", "transitions": [{"to": "NEGOTIATE", "condition": "Learner responds to changed constraint or proposes valid refusal"}, {"to": "REPAIR", "condition": "Learner explicitly asks clarification or ignores changed constraint"}], "assistant_el": "Στο παράθυρο τρία. Πρέπει πρώτα να πάρετε αριθμό.", "learner_goal_ru": "Реагировать на новое ограничение, не повторить первоначальную просьбу механически", "acceptable_examples_el": ["Από πού παίρνω αριθμό;"]}, {"node_id": "REPAIR", "transitions": [{"to": "TWIST", "condition": "After one clarification, restate the TWIST line in shorter pieces without supplying the learner answer"}, {"to": "RETRY", "condition": "After two repair loops learner still cannot continue, end with supported retry, no independent mastery"}], "assistant_el": "Να το πω πιο αργά; Ποιο σημείο δεν είναι σαφές;", "learner_goal_ru": "Назвать непонятое слово, время, количество или условие", "acceptable_examples_el": ["Μπορείτε να επαναλάβετε την ώρα;", "Δεν κατάλαβα το τελευταίο σημείο."]}, {"node_id": "NEGOTIATE", "transitions": [{"to": "CLOSE", "condition": "Learner confirms a feasible outcome and addresses the challenge"}, {"to": "RETRY", "condition": "Outcome still infeasible or new plausible request outside script, paraphrase constraint once then allow retry"}], "assistant_el": "Από το μηχάνημα δίπλα στην είσοδο. Έχετε και αντίγραφο της αίτησης;", "learner_goal_ru": "Проверить последнюю деталь или предложить допустимый компромисс", "acceptable_examples_el": ["Όχι. Μπορώ να το φέρω αργότερα ή πρέπει να πάρω νέο αριθμό;"]}, {"node_id": "CLOSE", "transitions": [], "assistant_el": "Ας ρωτήσουμε τον υπεύθυνο πριν περιμένετε άδικα.", "learner_goal_ru": "Проверены окно, очередь и следующий шаг; вымышленные процедуры не подаются как реальные.", "acceptable_examples_el": ["Ευχαριστώ. Θα ακολουθήσω το επόμενο βήμα που συμφωνήσαμε."]}, {"node_id": "RETRY", "transitions": [], "assistant_el": "Ας σταματήσουμε εδώ και ας δούμε ποιο σημείο χρειάζεται διευκρίνιση.", "learner_goal_ru": "Завершить без ложного результата; разобрать одну ошибку и повторить с новыми данными", "acceptable_examples_el": ["Θέλω να δοκιμάσω ξανά."]}], "domain": "Госучреждение", "rubric": {"scale": "0=не продемонстрировано;1=с помощью;2=самостоятельно; не официальный балл", "language": "Диапазон и точность в пределах уровня; смысл важнее дословного совпадения", "register": "Уместно выбирает вежливость и адресата", "requires": ["evidence_spans", "assistance_level", "confidence", "abstention_reason_if_uncertain"], "interaction": "Отвечает на новую информацию, уточняет и достигает/честно ограничивает результат", "task_success": "Проверены окно, очередь и следующий шаг; вымышленные процедуры не подаются как реальные.", "pronunciation": "Оценивать только по реально прослушанному аудио; по транскрипту NO_SCORE"}, "status": "DRAFT", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "audio_file": null, "cefr_level": "A2", "entry_node": "OPEN", "hint_limits": {"exam_mode": "Никаких языковых подсказок; допустима организационная реплика без ответа", "practice_mode": "До двух пояснений после запроса; учитывать помощь"}, "scenario_id": "SC09", "facts_policy": "Все имена/суммы/сроки/процедуры — условия учебной роли. Не актуальные правила организаций. Не запрашивать реальные реквизиты.", "script_status": "AUTHORED", "retention_days": [7, 14, 28], "content_version": "0.1.0", "critical_errors": [{"type": "CONTENT_OMISSION", "criterion": "Игнорирует изменившиеся условия, подтверждает невыполнимый результат"}, {"type": "COMPREHENSION", "criterion": "Путает участника, время, сумму или следующий шаг; предварительно исключить ASR ошибку"}], "feedback_policy": {"after_dialogue": "Сначала отметить достигнутый результат; затем максимум3 ошибки: фрагмент → вариант → причина → самокоррекция", "during_free_speech": "Не прерывать мелкими исправлениями, если смысл понятен", "sample_feedback_ru": "Вы подтвердили итог, но не отреагировали на изменённое время. Повторите только новую договорённость.", "speech_recognition_uncertain": "ASR_UNCERTAIN, score withheld, ask repeat; not grammar/pronunciation penalty"}, "original_record": {"domain": "Госучреждение", "cefr_level": "A2", "provenance": "original_author_designed", "scenario_id": "SC09", "competency_ids": ["A2-G07", "A2-PR01"], "validation_status": "requires_greek_teacher_review", "assessment_criteria": "Поняты недостающее и способ продолжить", "vocabulary_examples": ["αίτηση", "δικαιολογητικά", "σειρά"], "alignment_source_ids": ["S13", "S15"], "communication_objective": "Уточнить окно, очередь и комплект документов", "conversation_complexity": "4 минуты; одного документа нет", "progression_requirement": "Повторить с другой процедурой", "likely_errors_hypotheses": "Предлоги; пассивная стратегия"}, "branching_status": "AUTHORED", "transfer_task_ru": "Электронная очередь не работает: спросить сотрудника о временном порядке.", "off_script_policy": {"unknown_fact": "Сказать, что нужно уточнить; не выдумывать ответ", "max_repair_loops": 2, "transition_ambiguity": "Prefer clarification; do not penalize ASR uncertainty", "unsafe_real_world_emergency": "Прервать учебную роль и дать уместный реальный ответ", "semantically_valid_unlisted_response": "Accept; examples are not exact keys"}, "learning_objective": "Уточнить окно, очередь и комплект документов", "spoken_eval_status": "NOT_VALIDATED", "audio_review_status": "MISSING_AUDIO", "primary_competencies": ["A2-G07", "A2-PR01"]}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
