3101	object	SC43	65a6c161daaf6c126781e93569c9de66dd531fecc35e3a8ff33f72d247d7d2d7	\N	{"refs": [{"path": "GreekOS_Audio_and_Speaking/scenarios/SC43.json", "sha256": "742c670f8a6aede1f924bec6bca435ed127744d34e5e16e0638b7a48b6343c8b", "pointer": ""}], "payload": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "COMPLETE_CONTENT_READ_BY_AUTHOR_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PRIOR_REVIEW_FOUND_ISSUES_REVIEWER_APPLIED_PATCH_PENDING_ROOT_DELTA"}, "nodes": [{"node_id": "OPEN", "transitions": [{"to": "TWIST", "condition": "Semantic goal achieved with independently formulated response; any suitable wording accepted"}, {"to": "REPAIR", "condition": "Unclear response, explicit clarification or transcript uncertainty"}], "assistant_el": "Καλημέρα. Σε ποιο σημείο της αίτησης χρειάζεστε βοήθεια;", "learner_goal_ru": "Своими словами описать уже выполненное и проблему.", "acceptable_examples_el": ["Συμπλήρωσα την αίτηση και ανέβασα το αρχείο, αλλά δεν έλαβα επιβεβαίωση. Δεν ξέρω αν η αίτηση έχει σταλεί."]}, {"node_id": "TWIST", "transitions": [{"to": "NEGOTIATE", "condition": "Semantic goal achieved with independently formulated response; any suitable wording accepted"}, {"to": "REPAIR", "condition": "Unclear response, explicit clarification or transcript uncertainty"}], "assistant_el": "Στην οθόνη εμφανίζεται η λέξη «πρόχειρο» ή η ένδειξη «υποβλήθηκε»;", "learner_goal_ru": "Попросить объяснить неизвестное слово и не угадывать статус.", "acceptable_examples_el": ["Τι σημαίνει εδώ «πρόχειρο»; Στην οθόνη βλέπω αυτή τη λέξη."]}, {"node_id": "NEGOTIATE", "transitions": [{"to": "CLOSE", "condition": "Semantic goal achieved with independently formulated response; any suitable wording accepted"}, {"to": "REPAIR", "condition": "Unclear response, explicit clarification or transcript uncertainty"}], "assistant_el": "«Πρόχειρο» σημαίνει ότι η αίτηση έχει αποθηκευτεί αλλά δεν έχει σταλεί. Στο κάτω μέρος υπάρχει το κουμπί «Υποβολή».", "learner_goal_ru": "Пересказать различие и уточнить действие.", "acceptable_examples_el": ["Άρα το αρχείο έχει αποθηκευτεί, αλλά η αίτηση δεν έχει σταλεί ακόμη. Πρέπει να πατήσω «Υποβολή», σωστά;"]}, {"node_id": "CLOSE", "transitions": [{"to": "DONE", "condition": "Confirmed learner response fulfils final goal and all branch-specific critical facts; evaluate quoted evidence before marking task success"}, {"to": "REPAIR", "condition": "Final answer unclear, learner asks clarification or ASR uncertain; save return_node=CLOSE"}], "assistant_el": "Ναι. Μετά την υποβολή θα εμφανιστεί αριθμός επιβεβαίωσης. Αν δεν εμφανιστεί, επικοινωνήστε ξανά μαζί μας.", "learner_goal_ru": "Сформулировать следующий шаг и условие повторного обращения.", "acceptable_examples_el": ["Θα κάνω την υποβολή και θα ελέγξω αν εμφανίζεται ο αριθμός. Αν δεν εμφανιστεί, θα επικοινωνήσω ξανά."], "awaits_learner_response": true}, {"node_id": "REPAIR", "transitions": [{"to": "OPEN", "guard": {"return_node": "OPEN", "repair_count_lt": 2}, "condition": "Clarification supplied; repair_count<2 and saved return_node==OPEN; repeat only necessary task fact without supplying learner answer"}, {"to": "TWIST", "guard": {"return_node": "TWIST", "repair_count_lt": 2}, "condition": "Clarification supplied; repair_count<2 and saved return_node==TWIST; repeat only necessary task fact without supplying learner answer"}, {"to": "NEGOTIATE", "guard": {"return_node": "NEGOTIATE", "repair_count_lt": 2}, "condition": "Clarification supplied; repair_count<2 and saved return_node==NEGOTIATE; repeat only necessary task fact without supplying learner answer"}, {"to": "CLOSE", "guard": {"return_node": "CLOSE", "repair_count_lt": 2}, "condition": "Clarification supplied; repair_count<2 and saved return_node==CLOSE; repeat only necessary task fact without supplying learner answer"}, {"to": "RETRY", "condition": "Two unsuccessful repairs OR invalid/missing saved return_node; do not guess a target"}], "assistant_el": "Ποιο σημείο θέλετε να πω ξανά;", "learner_goal_ru": "Назвать непонятую часть; повторить факт короче без выдачи ответа.", "acceptable_examples_el": ["Μπορείτε να το πείτε πιο αργά;"]}, {"node_id": "RETRY", "transitions": [], "assistant_el": "Ας κάνουμε μια μικρή παύση. Μπορούμε να δοκιμάσουμε ξανά.", "learner_goal_ru": "Сохранить помощь и причину остановки; не присваивать самостоятельное освоение.", "acceptable_examples_el": ["Ναι, ας δοκιμάσουμε ξανά."]}, {"node_id": "DONE", "terminal": true, "transitions": [], "assistant_el": "Ευχαριστώ. Ολοκληρώσαμε αυτή την άσκηση.", "learner_goal_ru": "Учебная роль завершена; оценка опирается на уже записанный ответ ученика.", "assessment_policy": "No automatic success from reaching this node; use stored assessed learner evidence and branch outcome", "acceptable_examples_el": ["Ευχαριστώ."], "additional_learner_response_required": false}], "domain": "Уточнение цифровой заявки без неизвестного термина", "rubric": {"scale": "0: смысловой результат не достигнут;1: частично/с помощью;2: все условия самостоятельно; не официальный экзаменационный балл", "language": "Диапазон и точность в пределах уровня; смысл важнее дословного совпадения", "register": "Уместно выбирает вежливость и адресата", "requires": ["evidence_spans", "assistance_level", "confidence", "abstention_reason_if_uncertain"], "interaction": "Отвечает на новую информацию, уточняет и достигает/честно ограничивает результат", "task_success": ["Различает сохранение и отправку в условиях роли", "Перефразирует неизвестный статус или запрашивает значение", "Передаёт условие повторного обращения, не объявляет результат заранее"], "pronunciation": "Оценивать только по реально прослушанному аудио; по транскрипту NO_SCORE", "item_specific_criteria": [{"criterion": "Различает сохранение и отправку в условиях роли", "evidence_required": "quote learner turn and task fact", "critical_if_missin