3107	unit	U-A1-001	1032111bd579689cf53d87fcb8c1b726d1b2ac0096be2086c73e028122f7298c	core	{"unit_id": "U-A1-001", "content_hash": "1032111bd579689cf53d87fcb8c1b726d1b2ac0096be2086c73e028122f7298c", "canonical_path": "GreekOS_Academic_Corpus/units/U-A1-001.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A1-001-RUBRIC"], "unit_id": "U-A1-001", "version": "0.1.2", "sections": {"theory": "theory_ru", "practice": ["U-A1-001-I02", "U-A1-001-I03", "U-A1-001-I04", "U-A1-001-I05", "U-A1-001-I06", "U-A1-001-I07"], "reception": ["U-A1-001-I08", "U-A1-001-I09", "U-A1-001-I10", "U-A1-001-I11"], "retention": ["U-A1-001-I15", "U-A1-001-I16", "U-A1-001-I17"], "diagnostic": ["U-A1-001-I01"], "production": ["U-A1-001-I12", "U-A1-001-I13", "U-A1-001-I14"]}, "title_ru": "Представиться и выбрать εσύ или εσείς", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Греческое είμαι соответствует «быть»: είμαι — я, είσαι — ты, είναι — он/она/оно, είμαστε — мы, είστε — вы, είναι — они. В отличие от русского настоящего времени, связку обычно произносят: Είμαι φοιτητής. Окончание уже указывает на участника, поэтому εγώ не обязательно; оно полезно для противопоставления: Εγώ είμαι φοιτητής, η Άννα είναι δασκάλα. С именем в роли подлежащего часто употребляется артикль: ο Νίκος, η Ελένη. Это не переводится словом «этот».\\n\\nС ровесником при неформальном знакомстве возможны εσύ/είσαι. К незнакомому сотруднику или преподавателю уместно начать с εσείς/είστε: это также обычная форма множественного числа. Выбор зависит от отношений, а не только от возраста. Нельзя автоматически заменять каждое «вы» на формальный единственный контекст. Сравните: Εσύ είσαι ο Πέτρος; и Εσείς είστε η κυρία Παππά;\\n\\nОткуда человек: Είμαι από την Ελλάδα. Где живёт: Μένω στη Θεσσαλονίκη. Это разные сведения; не заменяйте автоматически μένω на είμαι. Для профессии после είμαι здесь достаточно существительного: Είμαι δάσκαλος / δασκάλα. Мы не выводим всё склонение из этого урока. Если реплика непонятна, просьба о повторении — успешная стратегия общения: Συγγνώμη, μπορείτε να το πείτε ξανά; Сначала завершите знакомство, затем разберите одну-две ошибки. Полная парадигма прилагательных не является условием начала общения.\\n\\nГотовые формулы знакомства: Με λένε Άννα — меня зовут Анна; Πώς σε λένε; — знакомому; Πώς σας λένε; / Πώς λέγεστε; — вежливый вопрос. Это не полное спряжение λέω/λέγομαι. Μένουμε — мы живём, готовая форма для диагностического задания.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Είμαι η Άννα. Μένω στην Πάτρα.", "Ο Νίκος είναι φοιτητής. Η Ελένη είναι δασκάλα.", "Εσύ είσαι ο Μάριος; — Ναι, εγώ είμαι.", "Καλημέρα σας. Είστε η κυρία Παππά;", "Συγγνώμη, μπορείτε να το πείτε ξανά;"], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A1-001-I15", "U-A1-001-I16", "U-A1-001-I17"], "spontaneous_followup": {"day": 28, "model": "Καλημέρα σας. Με λένε Άννα. Είμαι από τη Ρωσία. Μένω στην Πάτρα. Πώς σας λένε;", "prompt": "Без образца представьтесь новому преподавателю: имя, происхождение, место проживания; задайте вежливый вопрос об имени.", "criteria": ["три факта", "уместная форма обращения", "самостоятельно"], "observed": false}, "hypothesis_not_official": true}, "source_refs": [{"anchor": "PDF5: личность и είμαι; V214 печатные26–41 — независимое тематическое подтверждение", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Overall spoken interaction / sociolinguistic appropriateness, A1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A1-001-I06", "U-A1-001-I07"], "prerequisites": [], "reading_tasks": ["U-A1-001-I08", "U-A1-001-I09"], "transfer_task": "U-A1-001-I14", "writing_tasks": ["U-A1-001-I12"], "competency_ids": ["A1-G05", "A1-PR01", "A1-SI01", "A1-V01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A1-001-I13"], "errors_taxonomy": ["PRAGMATICS_REGISTER", "VERB_TENSE", "CONTENT_OMISSION"], "guided_practice": ["U-A1-001-I02", "U-A1-001-I03", "U-A1-001-I04", "U-A1-001-I05"], "listening_tasks": ["U-A1-001-I10", "U-A1-001-I11"], "learning_outcome": "Представиться с με λένε и είμαι, указав имя и происхождение", "vocabulary_items": [{"lemma": "φοιτητής", "stress": "φοιτητής", "example": "Ο Άρης είναι φοιτητής.", "inflection": "ο φοιτητής, η φοιτήτρια", "meaning_ru": "студент", "collocations": ["είμαι φοιτητής"]}, {"lemma": "μένω", "stress": "μένω", "example": "Μένω στη Θεσσαλονίκη.", "inflection": "μένω, μένεις, μένει", "meaning_ru": "жить", "collocations": ["μένω στην Πάτρα"]}, {"lemma": "όνομα", "stress": "όνομα", "example": "Το όνομά μου είναι Άννα.", "inflection": "το όνομα, τα ονόματα", "meaning_ru": "имя", "collocations": ["το όνομά μου"]}, {"lemma": "συγγνώμη", "stress": "συγγνώμη", "example": "Συγγνώμη, δεν καταλαβαίνω.", "inflection": "формула", "meaning_ru": "извините", "collocations": ["συγγνώμη, μπορείτε…"]}], "soft_prerequisites": ["A1-P01"], "diagnostic_item_ids": ["U-A1-001-I01"], "learning_objectives": ["Представиться с με λένε и είμαι, указав имя и происхождение", "Выбрать εσύ/εσείς по адресату и согласовать форму είμαι", "Самостоятельно представиться новому собеседнику после отсрочки"], "microcompetency_ids": ["U-A1-001-MC01", "U-A1-001-MC02", "U-A1-001-MC03"], "primary_competencies": ["A1-G05", "A1-PR01"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3108	unit	U-A1-002	8997386ce543184553116324c2926d3b78ab670ea24cecfea9ec9bcc7152dafd	core	{"unit_id": "U-A1-002", "content_hash": "8997386ce543184553116324c2926d3b78ab670ea24cecfea9ec9bcc7152dafd", "canonical_path": "GreekOS_Academic_Corpus/units/U-A1-002.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A1-002-RUBRIC"], "unit_id": "U-A1-002", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-A1-002-I02", "U-A1-002-I03", "U-A1-002-I04", "U-A1-002-I05", "U-A1-002-I06"], "reception": ["U-A1-002-I07", "U-A1-002-I08", "U-A1-002-I09", "U-A1-002-I10"], "retention": ["U-A1-002-I14", "U-A1-002-I15", "U-A1-002-I16"], "diagnostic": ["U-A1-002-I01"], "production": ["U-A1-002-I11", "U-A1-002-I12", "U-A1-002-I13"]}, "title_ru": "Кто и кого: ο/τον, η/την, το/το", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Артикль помогает определить род и роль именной группы. Для знакомых лиц в единственном числе сравним ο φίλος → τον φίλο, η φίλη → τη φίλη, το παιδί → το παιδί. В роли подлежащего используется именительный: Ο φίλος βλέπει την Άννα. После переходного βλέπω прямое дополнение получает винительный: Η Άννα βλέπει τον φίλο. У среднего рода именительный и винительный совпадают: Το παιδί βλέπει το λεωφορείο. Поэтому смысл определяется не одной внешней формой, но глаголом и контекстом.\\nВ мужском роде этой модели исчезает конечное -ς: φίλος → φίλο. Это не правило для любого греческого слова, заканчивающегося на -ς. Женское φίλη и среднее παιδί здесь форму не меняют. Выучите артикль вместе с существительным. Имена тоже часто употребляются с артиклем: ο Νίκος → τον Νίκο, η Άννα → την Άννα.\\nВ современной учебной орфографии τον перед мужским существительным сохраняет ν. У την/τη выбор связан со следующим звуком; в этом уроке ключи допускают τη/την там, где требуется педагогическая терпимость, но отмечают орфографию отдельно. Не превращайте мелкую графическую вариацию в доказательство непонимания роли. Минимальная пара Ο Νίκος βλέπει την Άννα / Η Άννα βλέπει τον Νίκο показывает, как меняется участник действия. Сначала назовите, кто действует, затем кого видит; перестановки слов возможны, поэтому простое правило «первое слово всегда подлежащее» неверно.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Ο Νίκος βλέπει την Άννα.", "Η Άννα βλέπει τον Νίκο.", "Το παιδί περιμένει τον φίλο του.", "Βλέπω τη φίλη μου στο πάρκο."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A1-002-I14", "U-A1-002-I15", "U-A1-002-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF5–6", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction A1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A1-002-I05", "U-A1-002-I06"], "prerequisites": ["A1-G05"], "reading_tasks": ["U-A1-002-I07", "U-A1-002-I08"], "transfer_task": "U-A1-002-I13", "writing_tasks": ["U-A1-002-I11"], "competency_ids": ["A1-G01", "A1-G02"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A1-002-I12"], "errors_taxonomy": ["MORPHOLOGY_CASE", "GENDER_AGREEMENT"], "guided_practice": ["U-A1-002-I02", "U-A1-002-I03", "U-A1-002-I04"], "listening_tasks": ["U-A1-002-I09", "U-A1-002-I10"], "learning_outcome": "Различить действующее лицо и прямое дополнение по ο/τον, η/την, το", "vocabulary_items": [{"lemma": "φίλος", "stress": "φίλος", "example": "Περιμένω τον φίλο μου.", "inflection": "ο φίλος, τον φίλο", "meaning_ru": "друг", "collocations": ["βλέπω τον φίλο"]}, {"lemma": "φίλη", "stress": "φίλη", "example": "Η φίλη μου είναι εδώ.", "inflection": "η φίλη, τη φίλη", "meaning_ru": "подруга", "collocations": ["περιμένω τη φίλη"]}, {"lemma": "παιδί", "stress": "παιδί", "example": "Το παιδί είναι στο πάρκο.", "inflection": "το παιδί, τα παιδιά", "meaning_ru": "ребёнок", "collocations": ["το παιδί περιμένει"]}, {"lemma": "βλέπω", "stress": "βλέπω", "example": "Βλέπω τον Πέτρο.", "inflection": "βλέπω, βλέπεις, βλέπει", "meaning_ru": "видеть", "collocations": ["βλέπω την Άννα"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-002-I01"], "learning_objectives": ["Различить действующее лицо и прямое дополнение по ο/τον, η/την, το", "Образовать винительный φίλος→φίλο и употребить его в описании", "Описать новую сцену с ясными ролями участников"], "microcompetency_ids": ["U-A1-002-MC01", "U-A1-002-MC02", "U-A1-002-MC03"], "primary_competencies": ["A1-G01", "A1-G02"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
