3109	unit	U-A1-003	30f83ea2861b2cf8b9b91881d1554403e8d5f98b1d42ef96d7e93dcd646fe726	core	{"unit_id": "U-A1-003", "content_hash": "30f83ea2861b2cf8b9b91881d1554403e8d5f98b1d42ef96d7e93dcd646fe726", "canonical_path": "GreekOS_Academic_Corpus/units/U-A1-003.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A1-003-RUBRIC"], "unit_id": "U-A1-003", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-A1-003-I02", "U-A1-003-I03", "U-A1-003-I04", "U-A1-003-I05", "U-A1-003-I06"], "reception": ["U-A1-003-I07", "U-A1-003-I08", "U-A1-003-I09", "U-A1-003-I10"], "retention": ["U-A1-003-I14", "U-A1-003-I15", "U-A1-003-I16"], "diagnostic": ["U-A1-003-I01"], "production": ["U-A1-003-I11", "U-A1-003-I12", "U-A1-003-I13"]}, "title_ru": "Количество и заказ: один предмет и несколько", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Для покупки нужно различать название товара, количество и цену. В простых моделях ο χυμός → οι χυμοί, η ντομάτα → οι ντομάτες, το μήλο → τα μήλα. Это три конкретные модели, а не универсальное окончание множественного числа. В винительном после θέλω: έναν χυμό, δύο χυμούς; μία ντομάτα, δύο ντομάτες; ένα μήλο, δύο μήλα. Число один согласуется с родом: ένας/μία/ένα; в нашем заказе винительный мужского — έναν.\\nВместо нескольких штук можно попросить вес: ένα κιλό μήλα, μισό κιλό ντομάτες. При этом κιλό называет единицу измерения, а не грамматический род товара. Сравните δύο μήλα и δύο κιλά μήλα: количество товара различается. Вопрос Πόσο κάνει; относится к одному товару или сумме в контексте, Πόσο κάνουν; — к нескольким предметам. Не выводите реальную цену из учебного текста: все цены в этом блоке вымышлены.\\nДесятичную цену можно услышать как δύο ευρώ και πενήντα λεπτά. Проверьте, относится ли она к килограмму или ко всему заказу. Чтение числа без единицы — недостаточное доказательство понимания. После изменения количества переспросите итог: Δύο κιλά, σωστά; и Πόσο κάνουν όλα μαζί;", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Θέλω δύο μήλα.", "Θέλω έναν χυμό και δύο καφέδες.", "Ένα κιλό ντομάτες, παρακαλώ.", "Πόσο κάνουν όλα μαζί;"], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A1-003-I14", "U-A1-003-I15", "U-A1-003-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF5–6", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction A1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A1-003-I05", "U-A1-003-I06"], "prerequisites": ["A1-G01"], "reading_tasks": ["U-A1-003-I07", "U-A1-003-I08"], "transfer_task": "U-A1-003-I13", "writing_tasks": ["U-A1-003-I11"], "competency_ids": ["A1-G03", "A1-V02"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A1-003-I12"], "errors_taxonomy": ["MORPHOLOGY_CASE", "COMPREHENSION"], "guided_practice": ["U-A1-003-I02", "U-A1-003-I03", "U-A1-003-I04"], "listening_tasks": ["U-A1-003-I09", "U-A1-003-I10"], "learning_outcome": "Заказать предметы с числом один и множественным числом", "vocabulary_items": [{"lemma": "μήλο", "stress": "μήλο", "example": "Αγοράζω τρία μήλα.", "inflection": "το μήλο, τα μήλα", "meaning_ru": "яблоко", "collocations": ["δύο μήλα"]}, {"lemma": "χυμός", "stress": "χυμός", "example": "Θέλω έναν χυμό.", "inflection": "ο χυμός, οι χυμοί", "meaning_ru": "сок", "collocations": ["έναν χυμό"]}, {"lemma": "κιλό", "stress": "κιλό", "example": "Μισό κιλό ντομάτες, παρακαλώ.", "inflection": "το κιλό, τα κιλά", "meaning_ru": "килограмм", "collocations": ["μισό κιλό"]}, {"lemma": "λεπτό", "stress": "λεπτό", "example": "Κάνει πενήντα λεπτά.", "inflection": "το λεπτό, τα λεπτά", "meaning_ru": "цент; также минута", "collocations": ["πενήντα λεπτά"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-003-I01"], "learning_objectives": ["Заказать предметы с числом один и множественным числом", "Различить штуки и килограммы и вычислить указанную в тексте сумму", "Исправить неверное количество в реплике продавца"], "microcompetency_ids": ["U-A1-003-MC01", "U-A1-003-MC02", "U-A1-003-MC03"], "primary_competencies": ["A1-G03", "A1-V02"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3110	unit	U-A1-004	b7ee74d3697a7d831c9edccde7ef5bd3a357181bce3fce9ad9423563ec27911e	core	{"unit_id": "U-A1-004", "content_hash": "b7ee74d3697a7d831c9edccde7ef5bd3a357181bce3fce9ad9423563ec27911e", "canonical_path": "GreekOS_Academic_Corpus/units/U-A1-004.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A1-004-RUBRIC"], "unit_id": "U-A1-004", "version": "0.1.2", "sections": {"theory": "theory_ru", "practice": ["U-A1-004-I02", "U-A1-004-I03", "U-A1-004-I04", "U-A1-004-I05", "U-A1-004-I06"], "reception": ["U-A1-004-I07", "U-A1-004-I08", "U-A1-004-I09", "U-A1-004-I10"], "retention": ["U-A1-004-I14", "U-A1-004-I15", "U-A1-004-I16"], "diagnostic": ["U-A1-004-I01"], "production": ["U-A1-004-I11", "U-A1-004-I12", "U-A1-004-I13"]}, "title_ru": "Маршрут и положение: σε, από, με", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Σε обозначает местонахождение или направление в зависимости от глагола: Είμαι στο σχολείο — я в школе; Πηγαίνω στο σχολείο — иду в школу. Предлог сливается с определённым артиклем винительного: σε + το = στο, σε + τον = στον, σε + την = στην. Слово после него выбирается по собственному роду, а не по русскому переводу. Πού; спрашивает место, από πού; — исходную точку, πώς; — способ.\\nΑπό помогает назвать отправление: Έρχομαι από το κέντρο. Με показывает средство в сочетании με το λεωφορείο. Пешком — με τα πόδια. Не путайте номер автобуса и время отправления. В учебном маршруте данные условные и не заменяют актуальное расписание транспорта.\\nΠηγαίνετε ευθεία и στρίψτε δεξιά можно сначала понимать как готовые инструкции, не заявляя полного освоения императива A2. Если маршрут непонятен, попросите один шаг: Πού είναι η στάση; или Μπορείτε να το πείτε πιο αργά; Правильная стратегия — проверить направление, а не угадывать по знакомому названию. Сравните στο κέντρο (к/в центре) и από το κέντρο (из центра).\\n\\nОриентиры: δίπλα σε — рядом; απέναντι από — напротив; μπροστά σε — перед. Σε сливается с артиклем: δίπλα στην πόρτα, μπροστά στο γραφείο. После από артикль отдельно: απέναντι από την τράπεζα. Подготовка: соедините μπροστά + στο γραφείο (ключ μπροστά στο γραφείο); выберите рядом/напротив для δίπλα (рядом). Затем опишите новый ориентир без подсказки.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Πηγαίνω στο κέντρο.", "Έρχομαι από το σχολείο.", "Μένω στην Πάτρα.", "Πηγαίνω με το λεωφορείο."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A1-004-I14", "U-A1-004-I15", "U-A1-004-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF5–6", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction A1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A1-004-I05", "U-A1-004-I06"], "prerequisites": ["A1-G01"], "reading_tasks": ["U-A1-004-I07", "U-A1-004-I08"], "transfer_task": "U-A1-004-I13", "writing_tasks": ["U-A1-004-I11"], "competency_ids": ["A1-G09", "A1-G07"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A1-004-I12"], "errors_taxonomy": ["MORPHOLOGY_CASE", "COMPREHENSION"], "guided_practice": ["U-A1-004-I02", "U-A1-004-I03", "U-A1-004-I04"], "listening_tasks": ["U-A1-004-I09", "U-A1-004-I10"], "learning_outcome": "Различить место/направление с σε и исходную точку с από", "vocabulary_items": [{"lemma": "στάση", "stress": "στάση", "example": "Περιμένω στη στάση.", "inflection": "η στάση, οι στάσεις", "meaning_ru": "остановка", "collocations": ["στη στάση"]}, {"lemma": "κέντρο", "stress": "κέντρο", "example": "Το γραφείο είναι στο κέντρο.", "inflection": "το κέντρο", "meaning_ru": "центр", "collocations": ["στο κέντρο"]}, {"lemma": "λεωφορείο", "stress": "λεωφορείο", "example": "Πηγαίνω με το λεωφορείο.", "inflection": "το λεωφορείο, τα λεωφορεία", "meaning_ru": "автобус", "collocations": ["με το λεωφορείο"]}, {"lemma": "δεξιά", "stress": "δεξιά", "example": "Η στάση είναι δεξιά.", "inflection": "наречие", "meaning_ru": "направо", "collocations": ["στρίβω δεξιά"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-004-I01"], "learning_objectives": ["Различить место/направление с σε и исходную точку с από", "Назвать средство передвижения с με и слитный предлог с артиклем", "Уточнить маршрут после отрицательного ответа"], "microcompetency_ids": ["U-A1-004-MC01", "U-A1-004-MC02", "U-A1-004-MC03"], "primary_competencies": ["A1-G09", "A1-G07"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
