3111	unit	U-A1-005	1163844eadc08788727432ef0b0abc4325c768f7e300582c0e73df1bec0ddf67	core	{"unit_id": "U-A1-005", "content_hash": "1163844eadc08788727432ef0b0abc4325c768f7e300582c0e73df1bec0ddf67", "canonical_path": "GreekOS_Academic_Corpus/units/U-A1-005.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A1-005-RUBRIC"], "unit_id": "U-A1-005", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-A1-005-I02", "U-A1-005-I03", "U-A1-005-I04", "U-A1-005-I05", "U-A1-005-I06"], "reception": ["U-A1-005-I07", "U-A1-005-I08", "U-A1-005-I09", "U-A1-005-I10"], "retention": ["U-A1-005-I14", "U-A1-005-I15", "U-A1-005-I16"], "diagnostic": ["U-A1-005-I01"], "production": ["U-A1-005-I11", "U-A1-005-I12", "U-A1-005-I13"]}, "title_ru": "Настоящее время: что я делаю и что делаем мы", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "В настоящем времени окончание часто показывает действующее лицо, поэтому местоимение можно опустить: Μένω εδώ = Εγώ μένω εδώ. Для модели γράφω: γράφω, γράφεις, γράφει, γράφουμε, γράφετε, γράφουν. Сравните εγώ γράφω и εμείς γράφουμε. Не добавляйте местоимение в каждый ответ автоматически: оно полезно для противопоставления Εγώ μένω εδώ, αλλά η Άννα μένει αλλού.\\nУ некоторых частотных глаголов другая модель ударения и окончаний: μιλάω/μιλώ, μιλάς, μιλάει/μιλά, μιλάμε/μιλούμε, μιλάτε, μιλάνε/μιλούν. В этом блоке используем разговорную серию μιλάω — μιλάς — μιλάει — μιλάμε — μιλάτε — μιλάνε и признаём указанные варианты. Это не полный разбор второго спряжения: например, μπορώ требует отдельного освоения. Не выводите все глаголы из μιλάω.\\nОтрицание δεν ставится перед глаголом: Δεν μένω εδώ. Вопрос может иметь тот же порядок слов, а на письме заканчивается греческим вопросительным знаком ;: Μένεις εδώ; Настоящее описывает и привычку: Κάθε πρωί διαβάζω. Чтобы проверить понимание, измените лицо без изменения действия. Γράφει и γράφεις различаются адресатом, а не временем. В устном задании важна разборчивость окончаний; по одному текстовому ответу нельзя оценить произношение.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Μένω κοντά στο σχολείο.", "Εμείς διαβάζουμε το πρωί.", "Η Νίκη μιλάει ελληνικά.", "Δεν γράφετε τώρα;"], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A1-005-I14", "U-A1-005-I15", "U-A1-005-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF5–6", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction A1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A1-005-I05", "U-A1-005-I06"], "prerequisites": ["A1-G05"], "reading_tasks": ["U-A1-005-I07", "U-A1-005-I08"], "transfer_task": "U-A1-005-I13", "writing_tasks": ["U-A1-005-I11"], "competency_ids": ["A1-G06"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A1-005-I12"], "errors_taxonomy": ["VERB_AGREEMENT", "NEGATION", "ACCENTUATION"], "guided_practice": ["U-A1-005-I02", "U-A1-005-I03", "U-A1-005-I04"], "listening_tasks": ["U-A1-005-I09", "U-A1-005-I10"], "learning_outcome": "Согласовать настоящее γράφω/μένω/μιλάω с лицом", "vocabulary_items": [{"lemma": "γράφω", "stress": "γράφω", "example": "Γράφουμε ένα μήνυμα.", "inflection": "γράφω, γράφεις, γράφει, γράφουμε, γράφετε, γράφουν", "meaning_ru": "писать", "collocations": ["γράφω ένα μήνυμα"]}, {"lemma": "μένω", "stress": "μένω", "example": "Μένουμε κοντά στο σχολείο.", "inflection": "μένω, μένεις, μένει, μένουμε, μένετε, μένουν", "meaning_ru": "жить; оставаться", "collocations": ["μένω κοντά"]}, {"lemma": "μιλάω", "stress": "μιλάω", "example": "Μιλάμε λίγο ελληνικά.", "inflection": "μιλάω, μιλάς, μιλάει, μιλάμε, μιλάτε, μιλάνε", "meaning_ru": "говорить", "collocations": ["μιλάω ελληνικά"]}, {"lemma": "διαβάζω", "stress": "διαβάζω", "example": "Διαβάζει κάθε πρωί.", "inflection": "διαβάζω, διαβάζεις, διαβάζει, διαβάζουμε, διαβάζετε, διαβάζουν", "meaning_ru": "читать; заниматься", "collocations": ["διαβάζω το πρωί"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-005-I01"], "learning_objectives": ["Согласовать настоящее γράφω/μένω/μιλάω с лицом", "Понять, кто выполняет действие в коротком сообщении", "Описать свои и совместные привычные действия"], "microcompetency_ids": ["U-A1-005-MC01", "U-A1-005-MC02", "U-A1-005-MC03"], "primary_competencies": ["A1-G06"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3112	unit	U-A1-006	2c7e5629151f692a2d528d9b9b13294a4f8b8237e07ce87b4a02b93afc5784b1	core	{"unit_id": "U-A1-006", "content_hash": "2c7e5629151f692a2d528d9b9b13294a4f8b8237e07ce87b4a02b93afc5784b1", "canonical_path": "GreekOS_Academic_Corpus/units/U-A1-006.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A1-006-RUBRIC"], "unit_id": "U-A1-006", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-A1-006-I02", "U-A1-006-I03", "U-A1-006-I04", "U-A1-006-I05", "U-A1-006-I06"], "reception": ["U-A1-006-I07", "U-A1-006-I08", "U-A1-006-I09", "U-A1-006-I10"], "retention": ["U-A1-006-I14", "U-A1-006-I15", "U-A1-006-I16"], "diagnostic": ["U-A1-006-I01"], "production": ["U-A1-006-I11", "U-A1-006-I12", "U-A1-006-I13"]}, "title_ru": "Описать нужный предмет и попросить действие", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "В сочетаниях с прилагательным окончание зависит от существительного: ο μικρός φάκελος, η μικρή τσάντα, το μικρό κουτί. В просьбе с θέλω мужской винительный меняется: Θέλω έναν μικρό φάκελο. Женский и средний в этой модели: μια μικρή τσάντα, ένα μικρό κουτί. Во множественном τα μικρά κουτιά относится к нескольким коробкам. Не выбирайте форму прилагательного по русскому роду перевода.\\nΘέλω + предмет сообщает желание: Θέλω ένα κουτί. Θέλω να + глагол сообщает желаемое действие: Θέλω να αγοράσω ένα κουτί. На A1 формы να αγοράσω, να δω, να ρωτήσω осваиваются как ограниченные речевые блоки; полный выбор видовой основы относится к дальнейшему курсу. Μπορώ να δω το κουτί; — просьба разрешить посмотреть. Более вежливое Μπορείτε να το δείξετε; обращено к собеседнику. Не смешивайте могу ли я и можете ли вы.\\nЧтобы уточнить товар, назовите признак: μικρό/μεγάλο, κόκκινο/μπλε. Μπλε в обычном употреблении не изменяется: μια μπλε τσάντα, δύο μπλε τσάντες. Это отдельный пример, а не правило для всех цветов. Если предлагаемый размер не подходит, коротко исправьте просьбу. Важен понятный признак и действие; не требуется безошибочно построить незнакомое склонение.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Θέλω έναν μικρό φάκελο.", "Αυτή η τσάντα είναι μικρή.", "Μπορώ να δω το μεγάλο κουτί;", "Θέλω να αγοράσω μια μπλε τσάντα."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A1-006-I14", "U-A1-006-I15", "U-A1-006-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF5–6", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction A1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A1-006-I05", "U-A1-006-I06"], "prerequisites": ["A1-G01", "A1-G02", "A1-G06"], "reading_tasks": ["U-A1-006-I07", "U-A1-006-I08"], "transfer_task": "U-A1-006-I13", "writing_tasks": ["U-A1-006-I11"], "competency_ids": ["A1-G04", "A1-G12"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A1-006-I12"], "errors_taxonomy": ["ADJECTIVE_AGREEMENT", "REQUEST_FORM", "REFERENCE"], "guided_practice": ["U-A1-006-I02", "U-A1-006-I03", "U-A1-006-I04"], "listening_tasks": ["U-A1-006-I09", "U-A1-006-I10"], "learning_outcome": "Согласовать частотное прилагательное с предметом", "vocabulary_items": [{"lemma": "μικρός", "stress": "μικρός", "example": "Το κουτί είναι μικρό.", "inflection": "μικρός, μικρή, μικρό; маленькие среднего μικρά", "meaning_ru": "маленький", "collocations": ["μικρό κουτί"]}, {"lemma": "μεγάλος", "stress": "μεγάλος", "example": "Η τσάντα είναι μεγάλη.", "inflection": "μεγάλος, μεγάλη, μεγάλο", "meaning_ru": "большой", "collocations": ["μεγάλη τσάντα"]}, {"lemma": "φάκελος", "stress": "φάκελος", "example": "Θέλω έναν φάκελο.", "inflection": "ο φάκελος, τον φάκελο", "meaning_ru": "конверт; папка", "collocations": ["έναν μικρό φάκελο"]}, {"lemma": "κουτί", "stress": "κουτί", "example": "Μπορώ να δω το κουτί;", "inflection": "το κουτί, τα κουτιά", "meaning_ru": "коробка", "collocations": ["ένα μεγάλο κουτί"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-006-I01"], "learning_objectives": ["Согласовать частотное прилагательное с предметом", "Попросить показать предмет через ограниченные блоки θέλω/μπορώ να", "Исправить признак предмета в новой ситуации"], "microcompetency_ids": ["U-A1-006-MC01", "U-A1-006-MC02", "U-A1-006-MC03"], "primary_competencies": ["A1-G04", "A1-G12"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
