3113	unit	U-A1-007	849389e63add2b4cf26193ca445c2b41ae2aa9e6d7593be702ce22f687b4a4c0	core	{"unit_id": "U-A1-007", "content_hash": "849389e63add2b4cf26193ca445c2b41ae2aa9e6d7593be702ce22f687b4a4c0", "canonical_path": "GreekOS_Academic_Corpus/units/U-A1-007.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A1-007-RUBRIC"], "unit_id": "U-A1-007", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-A1-007-I02", "U-A1-007-I03", "U-A1-007-I04", "U-A1-007-I05", "U-A1-007-I06", "U-A1-007-I07", "U-A1-007-I08", "U-A1-007-I19", "U-A1-007-I20"], "reception": ["U-A1-007-I09", "U-A1-007-I10", "U-A1-007-I11", "U-A1-007-I12"], "retention": ["U-A1-007-I16", "U-A1-007-I17", "U-A1-007-I18", "U-A1-007-I22"], "diagnostic": ["U-A1-007-I01"], "production": ["U-A1-007-I13", "U-A1-007-I14", "U-A1-007-I15", "U-A1-007-I21"]}, "title_ru": "Алфавит: от написания к чтению", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "В греческом алфавите 24 буквы. Название буквы нужно для диктовки имени; оно не совпадает со звуком внутри слова. Например, β называется βήτα, но в слове βάζο передаёт [v], а не русское «б». Сначала сравните прописную и строчную форму, затем прочитайте целое слово. Буква σ имеет конечную форму ς: μέσα, κόσμος. Это одна буква, а не два разных звука.\\n\\nПолный справочник пар и названий: Α α άλφα; Β β βήτα; Γ γ γάμμα; Δ δ δέλτα; Ε ε έψιλον; Ζ ζ ζήτα; Η η ήτα; Θ θ θήτα; Ι ι γιώτα; Κ κ κάππα; Λ λ λάμδα; Μ μ μι; Ν ν νι; Ξ ξ ξι; Ο ο όμικρον; Π π πι; Ρ ρ ρο; Σ σ/ς σίγμα; Τ τ ταυ; Υ υ ύψιλον; Φ φ φι; Χ χ χι; Ψ ψ ψι; Ω ω ωμέγα.\\n\\nГласные буквы не означают семь разных гласных звуков: α=[a], ε=[e], η/ι/υ=[i], ο/ω=[o]. Сочетания αι=[e], ει/οι/υι=[i], ου=[u] читаются как одна гласная. В слове παιδί сначала выделите αι, а не читайте α и ι отдельно. Διαλυτικά, две точки, показывают раздельное чтение: Μαΐου — не обычное αι. Ударение над второй буквой сочетания относится ко всему гласному: είναι, ακούω. Систематическая работа с ударением — следующий урок.\\n\\nΜπ в μπαμπάς даёт звонкое [b], ντ в ντομάτα — [d], γκ в γκολ — [g]. Внутри слова у этих сочетаний возможен носовой компонент, а γγ, как в φεγγάρι, также связано со звуком [g]. Не превращайте правило в запрет всех вариантов [mb], [nd], [ŋg]. Ξ читается как [ks], ψ — [ps]; β — [v], ζ — [z], φ — [f]. Для остальных согласных опирайтесь на образец преподавателя; θ, δ, χ, γ подробно отрабатываются отдельно.\\n\\nΑυ и ευ зависят от следующего звука: в αυτό и ευχαριστώ слышим [af], [ef], а в αύριο и ευγενικός — [av], [ev]. Запоминайте пару целых слов, а не механическое правило «перед буквой». Повторяющиеся одинаковые согласные обычно не удваивают длительность: αλλά; γγ рассматривается отдельно.\\n\\nПисьменный ключ проверяет распознавание написания. Он не доказывает правильность произношения. Для речевой попытки запишите имя и несколько слов без чтения модели вслух; преподаватель должен независимо услышать запись. Пока эталонного аудио нет, задания «послушайте» заблокированы, а письменные задания можно выполнять.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Σοφία — η Σοφία, Νίκος — ο Νίκος.", "παιδί: αι → [e]", "είναι: ει → [i], αι → [e]", "που: ου → [u]", "μπαμπάς · ντομάτα · γκολ", "αυτό / αύριο · ευχαριστώ / ευγενικός"], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A1-007-I16", "U-A1-007-I17", "U-A1-007-I18", "U-A1-007-I22"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Историческая уровневая тематическая карта; размещение требует эксперта", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Reception, production, interaction; author mapping, not official cut score", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "§3.2: γράμματα, δίψηφα", "source_id": "N401", "checked_on": "2026-10-14", "claim_scope": "Грамматическое/фонетическое правило; задания оригинальные", "evidence_type": "OFFICIAL_SCHOOL_GRAMMAR_NOT_AUTH_SYLLABUS"}, {"anchor": "Примечания к произношению μπ, ντ, γκ", "source_id": "N403", "checked_on": "2026-10-14", "claim_scope": "Грамматическое/фонетическое правило; задания оригинальные", "evidence_type": "OFFICIAL_SCHOOL_GRAMMAR_NOT_AUTH_SYLLABUS"}], "evidence_map": [{"delayed": ["U-A1-007-I16", "U-A1-007-I22"], "transfer": ["U-A1-007-I13", "U-A1-007-I15"], "source_ids": ["V201", "W322", "N401", "N403"], "prerequisites": [], "mastery_decision": {"rule": "Целевая связь/форма верна в контролируемом задании; самостоятельное применение в новом сообщении и переносе; повтор без подсказок через 7/14/28 дней. Не усреднять критическую смысловую ошибку.", "status": "NOT_ASSESSED", "pronunciation_gate": "ACTUAL_AUDIO_AND_INDEPENDENT_LISTENER_REQUIRED"}, "microcompetency_id": "U-A1-007-MC01", "observable_outcome": "Соотнести 24 прописные и строчные буквы и выделить конечную ς.", "evidence_is_collected": false, "independent_production": ["U-A1-007-I07", "U-A1-007-I19"], "recognition_or_controlled": ["U-A1-007-I01", "U-A1-007-I02", "U-A1-007-I03", "U-A1-007