3114	unit	U-A1-008	4d47cebc64092148c7335584e516887ec0fefc91cabaf613c8a98d3f6beef56b	core	{"unit_id": "U-A1-008", "content_hash": "4d47cebc64092148c7335584e516887ec0fefc91cabaf613c8a98d3f6beef56b", "canonical_path": "GreekOS_Academic_Corpus/units/U-A1-008.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A1-008-RUBRIC"], "unit_id": "U-A1-008", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-A1-008-I02", "U-A1-008-I03", "U-A1-008-I04", "U-A1-008-I05", "U-A1-008-I06", "U-A1-008-I07", "U-A1-008-I08", "U-A1-008-I19", "U-A1-008-I20"], "reception": ["U-A1-008-I09", "U-A1-008-I10", "U-A1-008-I11", "U-A1-008-I12"], "retention": ["U-A1-008-I16", "U-A1-008-I17", "U-A1-008-I18", "U-A1-008-I22"], "diagnostic": ["U-A1-008-I01"], "production": ["U-A1-008-I13", "U-A1-008-I14", "U-A1-008-I15", "U-A1-008-I21", "U-A1-008-I23"]}, "title_ru": "Ударение, гласные и четыре непривычных согласных", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "В греческом пять основных гласных: [a], [e], [i], [o], [u]. Разные написания могут передавать один звук: η, ι, υ, ει, οι, υι относятся к [i]; ο и ω — к [o]. Не переносите русское превращение безударного «о» в «а»: в νερό первый и второй гласные различаются, а в πόσο оба сохраняют качество [o]. Написание учим вместе со словом, поскольку звук [i] сам по себе не подсказывает, какая буква нужна.\\n\\nУдарение выделяет один слог; при обычном написании многосложных слов оно обозначается знаком τόνος. Отсчитываем слоги от конца: в νερό ударный последний, в φίλος — предпоследний, в άνθρωπος — третий с конца. Базовая зона ударения — последние три слога; сочетания с безударными местоимениями могут давать дополнительный знак: το όνομά μου. Это не разрешение произвольно ставить два ударения. Односложные слова обычно без знака, но есть различительные написания, например πού/που и πώς/πως; их употребление будет изучаться отдельно.\\n\\nУдарение различает слова: πότε — «когда», ποτέ — «никогда»; νόμος — «закон», νομός — «административная область» в традиционном термине. Пара μόνος «один, без других» и μονός «нечётный/одинарный» также показывает различие, но грамматика и контекст важны. В этом уроке продуктивно используем прежде всего πότε/ποτέ; остальные пары — иллюстрация, не требование знать административную систему.\\n\\nДля θ и δ воздух проходит между языком и зубами: θ — без голоса, δ — с голосом. Не заменяйте θ на τ и δ на ντ. Приложите пальцы к горлу: при δ ощущается вибрация. Этот приём лишь помогает почувствовать работу голоса и не заменяет проверку слушателем. Примеры: θέλω, δέμα.\\n\\nΧ и γ — также пара без голоса/с голосом, но место сближения зависит от следующего гласного: сравните χαρά, γάλα с χέρι, γέλιο. Перед передними гласными звук образуется более спереди. Γ в γάλα не равно смычному [g] из γκολ. Сначала произносите короткие слова, затем фразы; не добавляйте гласный между согласными. Точная фонетическая оценка возможна только по звуку.\\n\\nАлгоритм самостоятельной работы: обозначить ударный слог; произнести слово; включить его в короткую реплику; записать без подсказки; получить от слушателя запись того, что он услышал. Не считать совпадение текста распознавания доказательством правильного θ или ударения. Пока нет эталонного аудио и проверки записи, слуховое различение и произношение остаются непроверенными.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["νε-ρό · φί-λος · άν-θρω-πος", "Πότε έρχεσαι; — Δεν έρχομαι ποτέ εδώ.", "Θέλω νερό.", "Το δέμα είναι εδώ.", "Έχω γάλα.", "Το χέρι μου. — Ακούω γέλιο."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A1-008-I16", "U-A1-008-I17", "U-A1-008-I18", "U-A1-008-I22"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Историческая уровневая тематическая карта; размещение требует эксперта", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Reception, production, interaction; author mapping, not official cut score", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "§3.1: φωνήεντα, σύμφωνα", "source_id": "N402", "checked_on": "2026-10-14", "claim_scope": "Грамматическое/фонетическое правило; задания оригинальные", "evidence_type": "OFFICIAL_SCHOOL_GRAMMAR_NOT_AUTH_SYLLABUS"}, {"anchor": "§4.3: τόνος", "source_id": "N407", "checked_on": "2026-10-14", "claim_scope": "Грамматическое/фонетическое правило; задания оригинальные", "evidence_type": "OFFICIAL_SCHOOL_GRAMMAR_NOT_AUTH_SYLLABUS"}, {"anchor": "§3.2: гласные сочетания", "source_id": "N401", "checked_on": "2026-10-14", "claim_scope": "Грамматическое/фонетическое правило; задания оригинальные", "evidence_type": "OFFICIAL_SCHOOL_GRAMMAR_NOT_AUTH_SYLLABUS"}], "evidence_map": [{"delayed": ["U-A1-008-I16", "U-A1-008-I22"], "transfer": ["U-A1-008-I13", "U-A1-008-I15"], "source_ids": ["V201", "W322", "N402", "N407", "N401"], "prerequisites": ["A1-P01"], "mastery_decision": {"rule": "Целевая связь/форма верна в контролируемом задании; самостоятельное применение в новом сообщении