3115	unit	U-A1-009	17c6efd1d895fe5aa1c85896463d01d98108aa224a85520c652b0b920626a6a1	core	{"unit_id": "U-A1-009", "content_hash": "17c6efd1d895fe5aa1c85896463d01d98108aa224a85520c652b0b920626a6a1", "canonical_path": "GreekOS_Academic_Corpus/units/U-A1-009.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "DRAFT", "rubrics": ["U-A1-009-RUBRIC"], "unit_id": "U-A1-009", "version": "0.1.2", "sections": {"theory": "theory_ru", "practice": ["U-A1-009-I02", "U-A1-009-I03", "U-A1-009-I04", "U-A1-009-I05", "U-A1-009-I06", "U-A1-009-I07", "U-A1-009-I08", "U-A1-009-I09"], "reception": ["U-A1-009-I10", "U-A1-009-I11", "U-A1-009-I12", "U-A1-009-I13"], "retention": ["U-A1-009-I17", "U-A1-009-I18", "U-A1-009-I19"], "diagnostic": ["U-A1-009-I01"], "production": ["U-A1-009-I14", "U-A1-009-I15", "U-A1-009-I16"]}, "title_ru": "Добавить, противопоставить, объяснить: και, αλλά, γιατί", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Отдельные правильные предложения ещё не объясняют ваш выбор. Сначала решите, какую связь должен услышать собеседник. Και добавляет: Θέλω τσάι και νερό. Можно соединить слова или сообщения. При общем исполнителе не нужно повторять εγώ. Αλλά отмечает ограничение или неожиданное отличие: Θέλω καφέ, αλλά δεν έχω χρήματα. Желание остаётся, но покупка затруднена.\\nΓιατί вводит объяснение: Μένω εδώ γιατί δουλεύω κοντά. Сначала решение, затем причина. Не переставляйте части механически: «работаю рядом, потому что живу здесь» сообщает другую причинную связь. В вопросе Γιατί μένεις εδώ; это «почему?», а в ответе — «потому что». Греческий вопросительный знак похож на точку с запятой. Сначала ответьте коротко, затем полным предложением.\\nПрочитайте две мысли; назовите связь; соедините их; закройте текст и передайте ситуацию своими словами. Один набор фактов иногда допускает разные отношения. Поэтому в закрытых заданиях обозначено намерение; в свободном ответе другая логичная связь принимается, если выполнено условие. Сравните Έχω χρόνο και έρχομαι — добавление; Έχω χρόνο, αλλά μένω σπίτι — контраст; Έρχομαι γιατί έχω χρόνο — объяснение.\\nДостаточно настоящего времени и знакомых отрицательных фраз; δεν подробно тренируется в U-A1-010. Не включайте все три союза в каждую реплику. Успех — когда партнёр понимает ваш выбор, ограничение и причину, а не просто слышит три союза. После упражнения смените место встречи и причину, чтобы проверить перенос.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Η Ελένη διαβάζει και ο Πέτρος γράφει.", "Θέλω νερό και ένα τσάι.", "Το σπίτι είναι μικρό, αλλά είναι ωραίο.", "Μένω σπίτι γιατί είμαι άρρωστη.", "Γιατί φεύγεις; — Γιατί έχω δουλειά.", "Έχω χρόνο, αλλά το καφέ είναι κλειστό."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "delivery": "Use concrete D7 and D28 scenarios in microcompetencies.json alongside closed retrieval; no observed mastery yet", "item_ids": ["U-A1-009-I17", "U-A1-009-I18", "U-A1-009-I19"], "hypothesis_not_official": true, "independent_followup_micro_ids": ["U-A1-009-MC01", "U-A1-009-MC02", "U-A1-009-MC03"]}, "source_refs": [{"anchor": "A1-G11 historical curricular theme only", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "A1 interaction/production, project mapping", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "§5.1 συμπλεκτικοί/αντιθετικοί; §5.2 αιτιολογικές", "source_id": "N404", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}], "active_recall": ["U-A1-009-I08", "U-A1-009-I09"], "prerequisites": ["A1-G05", "A1-G06"], "reading_tasks": ["U-A1-009-I10", "U-A1-009-I11"], "transfer_task": "U-A1-009-I16", "writing_tasks": ["U-A1-009-I14"], "competency_ids": ["A1-G11"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "reconstruction": {"date": "2026-10-15", "basis": "Saved authoring text and review findings in conversation; reconstructed after workspace cleanup; byte identity to lost drafts not claimed", "previous_unsaved_version": "0.1.0"}, "speaking_tasks": ["U-A1-009-I15"], "errors_taxonomy": ["CONNECTOR_RELATION", "CAUSE_DIRECTION", "MISSING_INDEPENDENT_PRODUCTION"], "guided_practice": ["U-A1-009-I02", "U-A1-009-I03", "U-A1-009-I04", "U-A1-009-I05", "U-A1-009-I06", "U-A1-009-I07"], "listening_tasks": ["U-A1-009-I12", "U-A1-009-I13"], "learning_outcome": "Соединить два факта с και и отличить добавление от противопоставления", "mastery_contract": {"audio": "Не оценивается без аудио", "unaided": "Две самостоятельные реплики без модели", "observed": false, "transfer": "Все условия новой ситуации; целевая форма=2, другие критерии≥1", "retention": "D7/D14/D28 без подсказок плюс новая свободная реплика", "controlled": "≥80% целевых форм; смысловая ошибка требует повторного обучения"}, "vocabulary_items": [{"lemma": "κοντά", "stress": "κοντά", "example": "Δουλεύω κοντά.", "inflection": "наречие", "meaning_ru": "рядом", "collocations": ["δουλεύω κοντά"]}, {"lemma": "κλειστός", "stress": "κλειστός", "example": "Το καφέ είναι κλειστό.", "inflection": "κλειστή, κλειστό", "meaning_ru": "закрытый", "collocations": ["είναι κλειστό"]}, {"lemma": "χρόνος", "stress": "χρόνος", "example": "Έχω χρόνο σήμερα.", "inflection": "ο χρόνος", "meaning_ru": "время", "collocations": ["έχω χρόνο"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-009-I01"], "learning_objectives": ["Соединить два факта с και и отличить добавление от противопоставления", "Объяснить выбор с γιατί, сохранив направление причины", "Без образца договориться о встрече: факт, ограничение, причина"], "microcompetency_ids": ["U-A1-009-MC01", "U-A1-009-MC02", "U-A1-009-MC03"], "primary_competencies": ["A1-G11"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3116	unit	U-A1-010	6da3bc2b87db571c57d34ac2192acb05fdd5c227827b6f2ec89b732778a8c77a	core	{"unit_id": "U-A1-010", "content_hash": "6da3bc2b87db571c57d34ac2192acb05fdd5c227827b6f2ec89b732778a8c77a", "canonical_path": "GreekOS_Academic_Corpus/units/U-A1-010.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "DRAFT", "rubrics": ["U-A1-010-RUBRIC"], "unit_id": "U-A1-010", "version": "0.1.3", "sections": {"theory": "theory_ru", "practice": ["U-A1-010-I02", "U-A1-010-I03", "U-A1-010-I04", "U-A1-010-I05", "U-A1-010-I06", "U-A1-010-I07", "U-A1-010-I08", "U-A1-010-I09"], "reception": ["U-A1-010-I10", "U-A1-010-I11", "U-A1-010-I12", "U-A1-010-I13"], "retention": ["U-A1-010-I17", "U-A1-010-I18", "U-A1-010-I19"], "diagnostic": ["U-A1-010-I01"], "production": ["U-A1-010-I14", "U-A1-010-I15", "U-A1-010-I16"]}, "title_ru": "Не делаю и не делай: отрицательная реплика", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Όχι — самостоятельное «нет». При отрицании сообщения с глаголом ставим δε(ν): Δεν έχω χρόνο. Не заменяем это на όχι έχω. Κороткое Όχι допустимо, но адресату часто нужно продолжение: Όχι, δεν είμαι ο Νίκος. Είμαι ο Πέτρος. Отрицание исправляет ошибку, второе предложение даёт верную информацию.\\nЗапрет строится с μη(ν): Μην τρέχεις! — не беги; Μην αργείς! — не опаздывай. Δεν τρέχεις сообщает, что ты не бежишь/не бегаешь; Μην τρέχεις! просит остановить действие. Нельзя ставить μην перед любой утвердительной командой. Здесь запоминаем сочетания μην τρέχεις, μην αργείς, μην περιμένεις, μη μιλάς целиком; полная система повеления и вида — позже. Вежливость зависит от контекста: знакомому добавьте σε παρακαλώ.\\nВ школьном правиле конечное ν сохраняется перед гласной и κ, π, τ, γκ, μπ, ντ, τσ, τζ, ξ, ψ: δεν έχω, δεν ξέρω, μην τρέχεις, но δε μένω, μη μιλάς. Различение функции важнее механического поиска буквы. В более широкой практике встречаются варианты; непривычную, но осмысленную форму направляем на проверку, не автоматически штрафуем.\\nТренируйте отдельно отсутствие, отказ и предупреждение. Прочитайте реплику, назовите намерение и произнесите новую фразу без текста. Затем соедините отказ с причиной из U-A1-009. Полезные формулы: Δεν ξέρω — не знаю; Δεν είμαι έτοιμος/έτοιμη — не готов/готова; Αύριο έχω χρόνο — завтра есть время. В тексте чтения αν означает «ли» после δεν ξέρω; это только рецептивная опора. Успех — понятный отказ с продолжением и запрет, не перепутанный с описанием.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Όχι, δεν έχω χρόνο.", "Δεν είμαι η Μαρία. Είμαι η Ελένη.", "Δεν ξέρω.", "Δε μένω εδώ.", "Μην τρέχεις, σε παρακαλώ.", "Μη μιλάς τώρα, σε παρακαλώ."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "delivery": "Use concrete D7 and D28 scenarios in microcompetencies.json alongside closed retrieval; no observed mastery yet", "item_ids": ["U-A1-010-I17", "U-A1-010-I18", "U-A1-010-I19"], "hypothesis_not_official": true, "independent_followup_micro_ids": ["U-A1-010-MC01", "U-A1-010-MC02", "U-A1-010-MC03"]}, "source_refs": [{"anchor": "A1-G08 historical curricular theme only", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "A1 interaction/production, project mapping", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "§5.2 άρνηση δε(ν)/μη(ν); τελικό ν", "source_id": "N404", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}], "active_recall": ["U-A1-010-I08", "U-A1-010-I09"], "prerequisites": ["A1-G05", "A1-G06", "A1-G11"], "reading_tasks": ["U-A1-010-I10", "U-A1-010-I11"], "transfer_task": "U-A1-010-I16", "writing_tasks": ["U-A1-010-I14"], "competency_ids": ["A1-G08"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "reconstruction": {"date": "2026-10-15", "basis": "Saved authoring text and review findings in conversation; reconstructed after workspace cleanup; byte identity to lost drafts not claimed", "previous_unsaved_version": "0.1.0"}, "speaking_tasks": ["U-A1-010-I15"], "errors_taxonomy": ["NEGATIVE_STATEMENT_VS_PROHIBITION", "OXI_AS_VERBAL_NEGATOR", "FINAL_NU", "REFUSAL_WITHOUT_INFORMATION"], "guided_practice": ["U-A1-010-I02", "U-A1-010-I03", "U-A1-010-I04", "U-A1-010-I05", "U-A1-010-I06", "U-A1-010-I07"], "listening_tasks": ["U-A1-010-I12", "U-A1-010-I13"], "learning_outcome": "Отрицать сообщение с δεν и продолжать ответ после όχι", "mastery_contract": {"audio": "Не оценивается без аудио", "unaided": "Две самостоятельные реплики без модели", "observed": false, "transfer": "Все условия новой ситуации; целевая форма=2, другие критерии≥1", "retention": "D7/D14/D28 без подсказок плюс новая свободная реплика", "controlled": "≥80% целевых форм; смысловая ошибка требует повторного обучения"}, "vocabulary_items": [{"lemma": "περιμένω", "stress": "περιμένω", "example": "Μην περιμένεις εδώ.", "inflection": "περιμένεις", "meaning_ru": "ждать", "collocations": ["μην περιμένεις"]}, {"lemma": "τρέχω", "stress": "τρέχω", "example": "Μην τρέχεις στον δρόμο.", "inflection": "τρέχεις", "meaning_ru": "бежать", "collocations": ["μην τρέχεις"]}, {"lemma": "αργώ", "stress": "αργώ", "example": "Μην αργείς, σε παρακαλώ.", "inflection": "αργείς", "meaning_ru": "опаздывать", "collocations": ["μην αργείς"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-010-I01"], "learning_objectives": ["Отрицать сообщение с δεν и продолжать ответ после όχι", "Различить сообщение и запрет в готовых фразах", "Самостоятельно отказаться, исправить информацию, предупредить"], "microcompetency_ids": ["U-A1-010-MC01", "U-A1-010-MC02", "U-A1-010-MC03"], "primary_competencies": ["A1-G08"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
