171	source_claim	CP08-INHERITED-U-A1-005-I14-01	52dbc59b30639266837c203c8c17446700355191d525cd4f127e976e9bb450d3	\N	{"record": {"claim": "Уровневая тема; не дословный источник авторских фраз", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A1-005-I14-01", "item_ids": ["U-A1-005-I14"], "source_id": "V201", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A1-005-I14.json", "sha256": "d8f9cc12b6ee96d954b9ffc254c6d756124fc0c7151dbf5b00056b65b6a63cd0"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "V201 PDF5–6", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}}, "claim_id": "CP08-INHERITED-U-A1-005-I14-01", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3117	unit	U-A1-011	a95058fa4ad5ba2d78741cf04d2f28b3e80330f1a084e09f0f81bcfc60cf69f6	core	{"unit_id": "U-A1-011", "content_hash": "a95058fa4ad5ba2d78741cf04d2f28b3e80330f1a084e09f0f81bcfc60cf69f6", "canonical_path": "GreekOS_Academic_Corpus/units/U-A1-011.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "DRAFT", "rubrics": ["U-A1-011-RUBRIC"], "unit_id": "U-A1-011", "version": "0.1.2", "sections": {"theory": "theory_ru", "practice": ["U-A1-011-I02", "U-A1-011-I03", "U-A1-011-I04", "U-A1-011-I05", "U-A1-011-I06", "U-A1-011-I07", "U-A1-011-I08", "U-A1-011-I09"], "reception": ["U-A1-011-I10", "U-A1-011-I11", "U-A1-011-I12", "U-A1-011-I13"], "retention": ["U-A1-011-I17", "U-A1-011-I18", "U-A1-011-I19"], "diagnostic": ["U-A1-011-I01"], "production": ["U-A1-011-I14", "U-A1-011-I15", "U-A1-011-I16"]}, "title_ru": "Мои вещи и нужное количество", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Μου после существительного указывает на мою вещь: το βιβλίο μου. Σου — на вещь собеседника: η τσάντα σου. Род вещи меняет артикль и существительное, но не владельца: ο φίλος μου, η φίλη μου, το βιβλίο μου. Τα βιβλία μου — много моих книг; μας означает «наши», то есть меняет владельцев. Рецептивная подсказка для чтения: του — его, της — её, μας — наши, σας — ваши, τους — их.\\nНе ставьте σου перед существительным по русской модели. Для простого называния берём η τσάντα σου. Подчёркнутое противопоставление может использовать δικός/δική/δικό, но здесь достаточно Αυτό είναι το βιβλίο μου, όχι το βιβλίο σου. После слова с ударением на третьем слоге от конца перед односложным притяжательным появляется дополнительное ударение: το τηλέφωνό μου. Значение владельца не меняется; сначала учите сочетание целиком.\\nКоличество относится к вещам: ένας καφές, μία τσάντα, ένα βιβλίο. После θέλω мужской винительный: έναν καφέ. Два: δύο/δυο для всех родов. Три: τρεις καφέδες/τσάντες, но τρία βιβλία. Четыре: τέσσερις καφέδες/τσάντες, но τέσσερα βιβλία. Пять: πέντε βιβλία, без изменения по роду. Не говорим τρία βιβλίο: существительное тоже во множественном.\\nДля вещества полезны λίγο νερό, ένα μπουκάλι νερό, δύο μπουκάλια νερό. Считаем бутылки. В магазине ένα νερό может означать одну порцию/бутылку воды по ситуации, не абстрактную «одну воду». Сначала установите владельца, затем вид и количество предметов. Исправьте ошибку собеседника и проверьте, понял ли он. Для самостоятельной практики поменяйте предметы и числа. Успех — нужные вещи у нужного человека, а не воспроизведение таблицы.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Το βιβλίο μου είναι εδώ.", "Η τσάντα σου είναι μικρή.", "Τα βιβλία μου είναι εδώ.", "Θέλω έναν καφέ και ένα νερό.", "Έχω τρεις τσάντες και τέσσερα βιβλία.", "Το τηλέφωνό μου είναι στην τσάντα μου."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "delivery": "Use concrete D7 and D28 scenarios in microcompetencies.json alongside closed retrieval; no observed mastery yet", "item_ids": ["U-A1-011-I17", "U-A1-011-I18", "U-A1-011-I19"], "hypothesis_not_official": true, "independent_followup_micro_ids": ["U-A1-011-MC01", "U-A1-011-MC02", "U-A1-011-MC03"]}, "source_refs": [{"anchor": "A1-G10 historical curricular theme only", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "A1 interaction/production, project mapping", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "§5.2 κτητικές", "source_id": "N410", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}, {"anchor": "§4.2 απόλυτα αριθμητικά", "source_id": "N411", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}, {"anchor": "§4.3 εγκλιτικά", "source_id": "N407", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}], "active_recall": ["U-A1-011-I08", "U-A1-011-I09"], "prerequisites": ["A1-G01", "A1-G02", "A1-G03"], "reading_tasks": ["U-A1-011-I10", "U-A1-011-I11"], "transfer_task": "U-A1-011-I16", "writing_tasks": ["U-A1-011-I14"], "competency_ids": ["A1-G10"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "reconstruction": {"date": "2026-10-15", "basis": "Saved authoring text and review findings in conversation; reconstructed after workspace cleanup; byte identity to lost drafts not claimed", "previous_unsaved_version": "0.1.0"}, "speaking_tasks": ["U-A1-011-I15"], "errors_taxonomy": ["POSSESSOR_VS_OBJECT_NUMBER", "POSSESSIVE_POSITION", "NUMERAL_GENDER_CASE", "COUNT_UNIT", "ENCLITIC_STRESS"], "guided_practice": ["U-A1-011-I02", "U-A1-011-I03", "U-A1-011-I04", "U-A1-011-I05", "U-A1-011-I06", "U-A1-011-I07"], "listening_tasks": ["U-A1-011-I12", "U-A1-011-I13"], "learning_outcome": "Указать владельца с μου/σου независимо от рода вещи", "mastery_contract": {"audio": "Не оценивается без аудио", "unaided": "Две самостоятельные реплики без модели", "observed": false, "transfer": "Все условия новой ситуации; целевая форма=2, другие критерии≥1", "retention": "D7/D14/D28 без подсказок плюс новая свободная реплика", "controlled": "≥80% целевых форм; смысловая ошибка требует повторного обучения"}, "vocabulary_items": [{"lemma": "τσάντα", "stress": "τσάντα", "example": "Η τσάντα μου είναι εδώ.", "inflection": "η τσάντα, οι τσάντες", "meaning_ru": "сумка", "collocations": ["η τσάντα μου"]}, {"lemma": "μπουκάλι", "stress": "μπουκάλι", "example": "Θέλω δύο μπουκάλια νερό.", "inflection": "το μπουκάλι, τα μπουκάλια", "meaning_ru": "бутылка", "collocations": ["ένα μπουκάλι νερό"]}, {"lemma": "τηλέφωνο", "stress": "τηλέφωνο", "example": "Πού είναι το τηλέφωνό σου;", "inflection": "το τηλέφωνο; το τηλέφωνό μου", "meaning_ru": "телефон", "collocations": ["το τηλέφωνό σου"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-011-I01"], "learning_objectives": ["Указать владельца с μου/σου независимо от рода вещи", "Выбрать один/три/четыре по роду и падежу", "Исправить владельца и количество в новом обмене"], "microcompetency_ids": ["U-A1-011-MC01", "U-A1-011-MC02", "U-A1-011-MC03"], "primary_competencies": ["A1-G10"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3118	unit	U-A1-012	4db5f9c5dc035a236073374ccaf8328d1702b5d7a9df36607dc70faf9d9b4cd1	core	{"unit_id": "U-A1-012", "content_hash": "4db5f9c5dc035a236073374ccaf8328d1702b5d7a9df36607dc70faf9d9b4cd1", "canonical_path": "GreekOS_Academic_Corpus/units/U-A1-012.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A1-012-RUBRIC"], "unit_id": "U-A1-012", "version": "0.1.0", "title_ru": "Знакомство, семья, учёба и интересы", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "В этом уроке вы представляете себя и другого человека, различаете семейные и учебные роли и поддерживаете короткий разговор об интересах. Используйте вымышленные сведения: реальные фамилии, адреса и данные родственников не нужны. Лексика организована по ситуациям, а не как список для заучивания.\\nЗнакомство: Με λένε Άννα / Είμαι η Άννα. В анкете όνομα — имя, επώνυμο — фамилия. Από πού είσαι; спрашивает о происхождении; Πού μένεις; — о нынешнем месте проживания. Είμαι από την Πάτρα, αλλά μένω στην Αθήνα. Не подменяйте эти два факта друг другом. Πώς σε λένε; — готовый вопрос об имени; формы λένε/λέγομαι здесь не требуют освоения всей парадигмы.\\nСемья: η μητέρα μου, ο πατέρας μου, ο αδελφός μου, η αδελφή μου. Принадлежность ставится после существительного, как в U-A1-011. Έχω έναν αδελφό и Ο αδελφός μου είναι μαθητής решают разные задачи: наличие родственника и его описание. Если не хотите говорить о семье, можно описать вымышленного друга. Не предполагаем, что у каждого есть супруг, дети или братья.\\nУчёба и работа: Είμαι μαθητής/μαθήτρια — школьник/школьница; φοιτητής/φοιτήτρια — студент/студентка вуза. Δουλεύω σε καφέ/σε γραφείο указывает место работы, а Είμαι δάσκαλος/δασκάλα — профессию. В нейтральном назывании профессии после είμαι учим готовое Είμαι δασκάλα. В Ο δάσκαλος είναι εδώ артикль называет конкретного человека. Δεν δουλεύω τώρα — допустимый ответ; не нужно придумывать работу. Для школы: το σχολείο, το μάθημα, ο δάσκαλος. Σπουδάζω — учусь в вузе, готовое употребление без новой грамматической цели.\\nИнтересы: Μου αρέσει η μουσική / το ποδόσφαιρο — мне нравится музыка / футбол. Пока используем этот блок с одним названием; множественное μου αρέσουν систематизируется отдельно. Παίζω ποδόσφαιρο — играю; βλέπω ποδόσφαιρο/αγώνες — смотрю. Человек может делать только одно из двух. Не выводите команду, профессию или характер человека из его увлечения. Η ομάδα μου — моя команда; ο αγώνας — матч. Футбол — вариант персонализации: можно заменить его музыкой, чтением или другим знакомым занятием.\\nСтройте разговор из взаимных реплик: представьтесь, ответьте, задайте встречный вопрос, уточните ошибочное предположение. Εσύ; годится как встречный вопрос после понятной темы. Для восстановления общения: Συγγνώμη, πάλι, παρακαλώ. Сначала произнесите 4–6 фраз без текста, затем проверьте, что не перепутали имя, родство, работу и увлечение. Красивый длинный рассказ с неверными фактами не считается выполнением задачи. Скрипт будущей записи пока используется только как чтение; произношение по печатному ответу не оценивается.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Το όνομά μου είναι Άννα.", "Το επώνυμό μου είναι Δήμου.", "Η οικογένειά μου μένει στην Πάτρα.", "Η μητέρα μου δουλεύει εδώ.", "Ο πατέρας μου είναι γιατρός.", "Έχω έναν αδελφό.", "Η αδελφή μου είναι μαθήτρια.", "Είμαι φοιτήτρια στην Αθήνα.", "Η Άννα είναι δασκάλα.", "Είμαι στη δουλειά.", "Δουλεύω σε γραφείο.", "Ακούω μουσική το βράδυ.", "Παίζω ποδόσφαιρο με φίλους.", "Βλέπω έναν αγώνα στην τηλεόραση.", "Η ομάδα μου παίζει σήμερα.", "Παίζω με φίλους."], "review_plan": {"days": [7, 14, 28], "rule": "Новый ответ без модели; после подсказки сохранять assisted, повторить самостоятельно с новыми данными.", "item_ids": ["U-A1-012-I17", "U-A1-012-I18", "U-A1-012-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Παραγωγή γραπτού λόγου; Αναγνώριση ταυτότητας; Κατοικία, διαμονή; Ελεύθερος χρόνος; Επαγγελματικός χώρος", "source_id": "CP06-A1-S01", "checked_on": "2026-10-17", "claim_scope": "A1 functional domains only. No endorsement of GreekOS tasks, durations or mastery thresholds.", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR"}, {"anchor": "headword φοιτητής, feminine φοιτήτρια, main definition", "source_id": "CP06-A1-S02", "checked_on": "2026-10-17", "claim_scope": "University student meaning and feminine headword only", "evidence_type": "PRIMARY_LEXICOGRAPHIC"}, {"anchor": "επώνυμο το; main definition (line141 in retrieved view)", "source_id": "CP06-A1-S04", "checked_on": "2026-10-17", "claim_scope": "Family name sense only; historical social examples not adopted", "evidence_type": "PRIMARY_LEXICOGRAPHIC"}], "active_recall": ["U-A1-012-I08", "U-A1-012-I09"], "prerequisites": ["A1-G05", "A1-G06", "A1-G07", "A1-G10"], "reading_tasks": ["U-A1-012-I10", "U-A1-012-I11"], "transfer_task": "U-A1-012-I16", "writing_tasks": ["U-A1-012-I14"], "competency_ids": ["A1-V01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; no observed learner mastery", "speaking_tasks": ["U-A1-012-I15"], "errors_taxonomy": ["FACT_SUBSTITUTION", "LEXICAL_ROLE_CONFUSION", "REGISTER_MISMATCH", "UNSUPPORTED_INFERENCE", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A1-012-I02", "U-A1-012-I03", "U-A1-012-I04", "U-A1-012-I05", "U-A1-012-I06", "U-A1-012-I07"], "listening_tasks": ["U-A1-012-I12", "U-A1-012-I13"], "reading_text_el": "Με λένε Ελένη. Είμαι από την Πάτρα και μένω στην Αθήνα. Είμαι φοιτήτρια και δουλεύω σε ένα καφέ το Σάββατο. Ο αδελφός μου, ο Πέτρος, είναι μαθητής. Η μητέρα μου είναι γιατρός. Μου αρέσει η μουσική. Παίζω ποδόσφαιρο την Κυριακή με φίλους, αλλά δεν βλέπω ποδόσφαιρο στην τηλεόραση. Ο Πέτρος βλέπει αγώνες, αλλά δεν παίζει.", "learning_outcome": "Представить личность и семейную/учебную роль без подмены фактов", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "transfer": "I16 + новая самостоятельная речь на I17/I19 по item-specific anchors", "controlled": "≥80% закрытых ответов, затем исправление всех смысловых ошибок"}, "vocabulary_items": [{"lemma": "όνομα", "stress": "όνομα", "example": "Το όνομά μου είναι Άννα.", "inflection": "το όνομα", "meaning_ru": "имя", "collocations": ["το όνομά μου"]}, {"lemma": "επώνυμο", "stress": "επώνυμο", "example": "Το επώνυμό μου είναι Δήμου.", "inflection": "το επώνυμο", "meaning_ru": "фамилия", "collocations": ["όνομα και επώνυμο"]}, {"lemma": "οικογένεια", "stress": "οικογένεια", "example": "Η οικογένειά μου μένει στην Πάτρα.", "inflection": "η οικογένεια", "meaning_ru": "семья", "collocations": ["η οικογένειά μου"]}, {"lemma": "μητέρα", "stress": "μητέρα", "example": "Η μητέρα μου δουλεύει εδώ.", "inflection": "η μητέρα", "meaning_ru": "мать", "collocations": ["η μητέρα μου"]}, {"lemma": "πατέρας", "stress": "πατέρας", "example": "Ο πατέρας μου είναι γιατρός.", "inflection": "ο πατέρας", "meaning_ru": "отец", "collocations": ["ο πατέρας μου"]}, {"lemma": "αδελφός", "stress": "αδελφός", "example": "Έχω έναν αδελφό.", "inflection": "ο αδελφός / η αδελφή", "meaning_ru": "брат / сестра", "collocations": ["ο αδελφός μου"]}, {"lemma": "μαθητής", "stress": "μαθητής", "example": "Η αδελφή μου είναι μαθήτρια.", "inflection": "ο μαθητής / η μαθήτρια", "meaning_ru": "ученик / ученица", "collocations": ["είμαι μαθητής"]}, {"lemma": "φοιτητής", "stress": "φοιτητής", "example": "Είμαι φοιτήτρια στην Αθήνα.", "inflection": "ο φοιτητής / η φοιτήτρια", "meaning_ru": "студент / студентка вуза", "collocations": ["είμαι φοιτήτρια"]}, {"lemma": "δάσκαλος", "stress": "δάσκαλος", "example": "Η Άννα είναι δασκάλα.", "inflection": "ο δάσκαλος / η δασκάλα", "meaning_ru": "учитель / учительница", "collocations": ["είμαι δασκάλα"]}, {"lemma": "δουλειά", "stress": "δουλειά", "example": "Είμαι στη δουλειά.", "inflection": "η δουλειά", "meaning_ru": "работа", "collocations": ["στη δουλειά"]}, {"lemma": "γραφείο", "stress": "γραφείο", "example": "Δουλεύω σε γραφείο.", "inflection": "το γραφείο", "meaning_ru": "офис; письменный стол по контексту", "collocations": ["σε γραφείο"]}, {"lemma": "μουσική", "stress": "μουσική", "example": "Ακούω μουσική το βράδυ.", "inflection": "η μουσική", "meaning_ru": "музыка", "collocations": ["ακούω μουσική"]}, {"lemma": "ποδόσφαιρο", "stress": "ποδόσφαιρο", "example": "Παίζω ποδόσφαιρο με φίλους.", "inflection": "το ποδόσφαιρο", "meaning_ru": "футбол", "collocations": ["παίζω ποδόσφαιρο"]}, {"lemma": "αγώνας", "stress": "αγώνας", "example": "Βλέπω έναν αγώνα στην τηλεόραση.", "inflection": "ο αγώνας / οι αγώνες", "meaning_ru": "матч; состязание", "collocations": ["βλέπω έναν αγώνα"]}, {"lemma": "ομάδα", "stress": "ομάδα", "example": "Η ομάδα μου παίζει σήμερα.", "inflection": "η ομάδα", "meaning_ru": "команда", "collocations": ["η ομάδα μου"]}, {"lemma": "φίλος", "stress": "φίλος", "example": "Παίζω με φίλους.", "inflection": "ο φίλος / η φίλη", "meaning_ru": "друг / подруга", "collocations": ["με φίλους"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-012-I01"], "learning_objectives": ["Представить личность и семейную/учебную роль без подмены фактов", "Различить занятие и интерес: работать, учиться, играть и смотреть", "Поддержать взаимный разговор, исправить предположение и перенести лексику на новую личность"], "microcompetency_ids": ["U-A1-012-MC01", "U-A1-012-MC02", "U-A1-012-MC03"], "prerequisite_support": {"A1-G05": "U-A1-001: είμαι/έ