177	source_claim	CP08-INHERITED-U-A1-006-I01-01	db11d2e77ac10f2db811d568e5c09aa0b3c51edaa2a897b820cd12dae9274f15	\N	{"record": {"claim": "Уровневая тема; не дословный источник авторских фраз", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A1-006-I01-01", "item_ids": ["U-A1-006-I01"], "source_id": "V201", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A1-006-I01.json", "sha256": "e9d8f7e9f0cd890b2a152d7029aa572af6fd1d16990dad4047d2e8214d65765e"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "V201 PDF5–6", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}}, "claim_id": "CP08-INHERITED-U-A1-006-I01-01", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3119	unit	U-A1-013	652576e6a8395f73cdae288571254380ac5227010c3dc5da6eed59d4536c1faa	core	{"unit_id": "U-A1-013", "content_hash": "652576e6a8395f73cdae288571254380ac5227010c3dc5da6eed59d4536c1faa", "canonical_path": "GreekOS_Academic_Corpus/units/U-A1-013.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A1-013-RUBRIC"], "unit_id": "U-A1-013", "version": "0.1.2", "title_ru": "Дом, район, транспорт и обычный день", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Цель — описать жильё и ближайшие места так, чтобы другой человек нашёл нужный ориентир, затем рассказать о дороге и обычном дне. Реальный адрес не нужен: все места в заданиях вымышлены. Краткая проверка: умеете ли вы сказать είμαι/μένω, задать Πού…; и соединить σε с артиклем? При затруднении повторите указанные подготовительные уроки.\\nΤο σπίτι — дом или жилище в целом; το διαμέρισμα — квартира. Модель Μένω σε διαμέρισμα описывает тип жилья, Μένω στο κέντρο — район. В описании комнаты используйте το υπνοδωμάτιο, η κουζίνα, το μπάνιο. Το σπίτι έχει μια κουζίνα называет состав жилья; Είμαι στην κουζίνα сообщает, где сейчас человек. Не смешивайте местонахождение и наличие.\\nРаботайте с отношениями между двумя объектами. Δίπλα στο σπίτι — рядом с домом; απέναντι από τον φούρνο — напротив пекарни; μπροστά στο σχολείο — перед школой; κοντά στο κέντρο — недалеко от центра. Последний блок не даёт расстояния в метрах. Если в тексте есть только κοντά, нельзя придумывать «две минуты пешком». Это готовые сочетания на основе уже изученных предлогов, а не новый полный раздел управления. Запоминайте существительное вместе с артиклем: η στάση — στη στάση, το σχολείο — στο σχολείο.\\nΟ φούρνος в описании улицы обычно пекарня, но в кухне может быть духовка. Контекст нужен даже знакомому слову. Η στάση здесь транспортная остановка; другие значения пока не изучаем. Μπροστά στο σχολείο относится к остановке, если именно она названа подлежащим: не переносите это отношение автоматически на дом.\\nМаршрут и транспорт: Πηγαίνω στη δουλειά με το λεωφορείο. Γυρίζω με τα πόδια. Выражение με τα πόδια — пешком, его нельзя переводить как транспортное средство. Утренний и обратный маршрут могут различаться. Πού πηγαίνεις; спрашивает пункт назначения, Πώς πηγαίνεις; — способ. В коротком ответе Με το λεωφορείο достаточно, когда вопрос уже задан.\\nДля распорядка нужны опоры το πρωί, το βράδυ, την Κυριακή. Μαγειρεύω, δουλεύω, γυρίζω — действия; не пытайтесь вывести время каждого из смысла глагола. Соедините 3–5 предложений с και, αλλά. При недостатке информации спросите: Πού ακριβώς; — где именно? Εδώ; — здесь? Повторите ориентир своими словами, чтобы проверить понимание.\\nПрактика проходит от выбора отношения к описанию нового района. При проверке важнее сохранение того, что находится рядом или напротив чего, чем буквальное совпадение с моделью. Сначала самостоятельный ответ, затем сверка. Для переноса изменяются тип жилья, ориентиры и способ поездки. Отложенные задания оценивают новые данные; память текста не заменяет умения. Аудиоскрипт пока не является существующим аудиофайлом.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Μένω σε διαμέρισμα.", "Το σπίτι έχει ένα υπνοδωμάτιο.", "Μαγειρεύω στην κουζίνα.", "Το μπάνιο είναι μικρό.", "Έχει φούρνο στη γειτονιά.", "Αγοράζω ψωμί στον φούρνο.", "Το φαρμακείο είναι απέναντι.", "Περιμένω στη στάση.", "Πηγαίνω με το λεωφορείο.", "Γυρίζω με τα πόδια.", "Δουλεύω το πρωί.", "Μαγειρεύω το βράδυ."], "review_plan": {"days": [7, 14, 28], "rule": "Новый ответ без модели; после подсказки сохранять assisted, повторить самостоятельно с новыми данными.", "item_ids": ["U-A1-013-I17", "U-A1-013-I18", "U-A1-013-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Παραγωγή γραπτού λόγου; Αναγνώριση ταυτότητας; Κατοικία, διαμονή; Ελεύθερος χρόνος; Επαγγελματικός χώρος", "source_id": "CP06-A1-S01", "checked_on": "2026-10-17", "claim_scope": "A1 functional domains only. No endorsement of GreekOS tasks, durations or mastery thresholds.", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR"}, {"anchor": "στάση¹ 1β", "source_id": "CP06-A1-S03", "checked_on": "2026-10-17", "claim_scope": "Transport stop sense only, not political/social senses", "evidence_type": "PRIMARY_LEXICOGRAPHIC"}], "active_recall": ["U-A1-013-I08", "U-A1-013-I09"], "prerequisites": ["A1-G05", "A1-G06", "A1-G07", "A1-G09"], "reading_tasks": ["U-A1-013-I10", "U-A1-013-I11"], "transfer_task": "U-A1-013-I16", "writing_tasks": ["U-A1-013-I14"], "competency_ids": ["A1-V03"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; no observed learner mastery", "speaking_tasks": ["U-A1-013-I15"], "errors_taxonomy": ["FACT_SUBSTITUTION", "LEXICAL_ROLE_CONFUSION", "REGISTER_MISMATCH", "UNSUPPORTED_INFERENCE", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A1-013-I02", "U-A1-013-I03", "U-A1-013-I04", "U-A1-013-I05", "U-A1-013-I06", "U-A1-013-I07"], "listening_tasks": ["U-A1-013-I12", "U-A1-013-I13"], "reading_text_el": "Μένω σε ένα μικρό διαμέρισμα κοντά στο κέντρο. Έχει ένα υπνοδωμάτιο, μια κουζίνα και ένα μπάνιο. Δίπλα στο σπίτι είναι ένας φούρνος. Το φαρμακείο είναι απέναντι από τον φούρνο. Η στάση είναι μπροστά στο σχολείο. Το πρωί πηγαίνω στη δουλειά με το λεωφορείο. Το βράδυ γυρίζω με τα πόδια. Την Κυριακή μένω στο σπίτι και μαγειρεύω.", "learning_outcome": "Назвать жильё, комнаты и ориентиры без домысливания расстояния", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "transfer": "I16 + новая самостоятельная речь на I17/I19 по item-specific anchors", "controlled": "≥80% закрытых ответов, затем исправление всех смысловых ошибок"}, "vocabulary_items": [{"lemma": "διαμέρισμα", "stress": "διαμέρισμα", "example": "Μένω σε διαμέρισμα.", "inflection": "το διαμέρισμα", "meaning_ru": "квартира", "collocations": ["σε διαμέρισμα"]}, {"lemma": "υπνοδωμάτιο", "stress": "υπνοδωμάτιο", "example": "Το σπίτι έχει ένα υπνοδωμάτιο.", "inflection": "το υπνοδωμάτιο", "meaning_ru": "спальня", "collocations": ["ένα υπνοδωμάτιο"]}, {"lemma": "κουζίνα", "stress": "κουζίνα", "example": "Μαγειρεύω στην κουζίνα.", "inflection": "η κουζίνα", "meaning_ru": "кухня", "collocations": ["στην κουζίνα"]}, {"lemma": "μπάνιο", "stress": "μπάνιο", "example": "Το μπάνιο είναι μικρό.", "inflection": "το μπάνιο", "meaning_ru": "ванная", "collocations": ["στο μπάνιο"]}, {"lemma": "γειτονιά", "stress": "γειτονιά", "example": "Έχει φούρνο στη γειτονιά.", "inflection": "η γειτονιά", "meaning_ru": "район рядом с домом", "collocations": ["στη γειτονιά"]}, {"lemma": "φούρνος", "stress": "φούρνος", "example": "Αγοράζω ψωμί στον φούρνο.", "inflection": "ο φούρνος", "meaning_ru": "пекарня; духовка по контексту", "collocations": ["στον φούρνο"]}, {"lemma": "φαρμακείο", "stress": "φαρμακείο", "example": "Το φαρμακείο είναι απέναντι.", "inflection": "το φαρμακείο", "meaning_ru": "аптека", "collocations": ["στο φαρμακείο"]}, {"lemma": "στάση", "stress": "στάση", "example": "Περιμένω στη στάση.", "inflection": "η στάση", "meaning_ru": "остановка", "collocations": ["στη στάση"]}, {"lemma": "λεωφορείο", "stress": "λεωφορείο", "example": "Πηγαίνω με το λεωφορείο.", "inflection": "το λεωφορείο", "meaning_ru": "автобус", "collocations": ["με το λεωφορείο"]}, {"lemma": "πόδια", "stress": "πόδια", "example": "Γυρίζω με τα πόδια.", "inflection": "τα πόδια", "meaning_ru": "ноги; пешком в με τα πόδια", "collocations": ["με τα πόδια"]}, {"lemma": "πρωί", "stress": "πρωί", "example": "Δουλεύω το πρωί.", "inflection": "το πρωί", "meaning_ru": "утро; утром", "collocations": ["το πρωί"]}, {"lemma": "βράδυ", "stress": "βράδυ", "example": "Μαγειρεύω το βράδυ.", "inflection": "το βράδυ", "meaning_ru": "вечер; вечером", "collocations": ["το βράδυ"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-013-I01"], "learning_objectives": ["Назвать жильё, комнаты и ориентиры без домысливания расстояния", "Различить направление, транспорт и время обычного действия", "Объяснить новый маршрут, уточнить место и описать свой день"], "microcompetency_ids": ["U-A1-013-MC01", "U-A1-013-MC02", "U-A1-013-MC03"], "prerequisite_support": {"A1-G05": "U-A1-001: είμαι/έχω", "A1-G06": "U-A1-005: настоящее время", "A1-G07": "U-A1-004: вопросы", "A1-G09": "U-A1-004: предлоги и местоположение; новый пример без модели после повторения."}, "primary_competencies": ["A1-V03"], "learner_data_included": false, "estimated_active_minutes": 65}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3120	unit	U-A1-014	5ccb8c9c162e0b0c26be212977e7c6a94092894b45fe839e708f5ff621a265d4	core	{"unit_id": "U-A1-014", "content_hash": "5ccb8c9c162e0b0c26be212977e7c6a94092894b45fe839e708f5ff621a265d4", "canonical_path": "GreekOS_Academic_Corpus/units/U-A1-014.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A1-014-RUBRIC"], "unit_id": "U-A1-014", "version": "0.1.2", "title_ru": "Читаем объявления, расписания и сообщения", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Этот урок учит читать короткое объявление, расписание и личное сообщение ради действия: выбрать время, найти комнату, ответить другу. Все расписания здесь учебные, они не описывают реальные организации. Перед началом повторите числа и часы, названия дней, вопросы Πότε; Πού; и лексику соседних мест. Неизвестные αίθουσα, είσοδος, δωρεάν объясняются в словаре до самостоятельной проверки.\\nПервое чтение: посмотрите на заголовок и форму текста. В расписании строки обычно связывают день и интервал; в сообщении имя в начале — адресат, подпись в конце — автор. Это полезная стратегия для наших примеров, не универсальный закон всех текстов. Не нужно переводить каждое слово до ответа на вопрос «что это за текст?». Второе чтение: найдите именно нужную строку и перепишите её ключевой факт своими словами.\\nРазличайте событие и часы работы. Βιβλιοθήκη: 09:00–18:00 не означает, что урок идёт девять часов. Μάθημα: 17:00 указывает начало урока, а не закрытие библиотеки. На наших карточках цифровое время дано в 24-часовом формате: 17:00 соответствует στις πέντε το απόγευμα. В живом сообщении «στις πέντε» без контекста может требовать уточнения. Не выбирайте ближайшее число только потому, что оно знакомо.\\nΑνοιχτά и κλειστά на вывесках сообщают об открытии или закрытии. Здесь их узнаём как готовые обозначения. Δωρεάν означает бесплатно; оно не говорит ни об обязательной записи, ни об отсутствии записи. Если об этом ничего нет, честный ответ: Δεν γράφει — не написано. Также не выводите цену напитка из бесплатного входа на занятие.\\nОтделяйте место человека от места мероприятия. Είμαι στο καφέ δίπλα στη βιβλιοθήκη — человек в кафе; урок при этом может быть в библиотеке. Отделяйте время встречи от начала: от фразы «Я здесь с 16:30, урок в 17:00» нельзя заключить, что урок в 16:30. В задании с отсутствующими данными ищите явное подтверждение, а не правдоподобный вариант. Для ответа часто достаточно 2–5 слов; полное предложение допустимо, если не добавляет ложных сведений.\\nПроверка понимания включает действие: коротко сообщить другу подходящий день, время и комнату, объяснить почему неподходящий вариант не годится. Продуктивные задания опираются на прочитанное, но их балл отражает также письменную/устную передачу фактов; ошибки чтения отмечайте отдельно от ошибок формы. Сначала ответьте без ключа, затем укажите строку-доказательство. В отложенной практике будут другие дни, помещения и часы. Будущие слушательские задания не считаются проверенными на слух, пока записи нет.\\nПеред заданиями со временем используйте CP06-CLOCK-BRIDGE: στις εννέα το πρωί — в 09:00; στις τρεις το απόγευμα — в 15:00; μέχρι τις πέντε — до пяти, μετά τις πέντε — после пяти. Если воспользовались подсказкой, отметьте помощь; затем назовите другое время без образца.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Το Σάββατο είναι ανοιχτά.", "Την Κυριακή είναι κλειστά.", "Η είσοδος είναι δωρεάν.", "Το μάθημα είναι δωρεάν.", "Είμαι στην αίθουσα δύο.", "Το μάθημα είναι στη βιβλιοθήκη.", "Έχω ένα μήνυμα.", "Το μάθημα αρχίζει στις πέντε.", "Σήμερα είναι Τρίτη.", "Είναι ανοιχτά μέχρι τις δύο."], "review_plan": {"days": [7, 14, 28], "rule": "Новый ответ без модели; после подсказки сохранять assisted, повторить самостоятельно с новыми данными.", "item_ids": ["U-A1-014-I17", "U-A1-014-I18", "U-A1-014-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Παραγωγή γραπτού λόγου; Αναγνώριση ταυτότητας; Κατοικία, διαμονή; Ελεύθερος χρόνος; Επαγγελματικός χώρος", "source_id": "CP06-A1-S01", "checked_on": "2026-10-17", "claim_scope": "A1 functional domains only. No endorsement of GreekOS tasks, durations or mastery thresholds.", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR"}], "support_refs": ["GreekOS_Academic_Corpus/support/CP06-CLOCK-BRIDGE.json"], "active_recall": ["U-A1-014-I08", "U-A1-014-I09"], "prerequisites": ["A1-G07", "A1-G10", "A1-V03"], "reading_tasks": ["U-A1-014-I10", "U-A1-014-I11"], "transfer_task": "U-A1-014-I16", "writing_tasks": ["U-A1-014-I14"], "competency_ids": ["A1-R01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; no observed learner mastery", "speaking_tasks": ["U-A1-014-I15"], "errors_taxonomy": ["FACT_SUBSTITUTION", "LEXICAL_ROLE_CONFUSION", "REGISTER_MISMATCH", "UNSUPPORTED_INFERENCE", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A1-014-I02", "U-A1-014-I03", "U-A1-014-I04", "U-A1-014-I05", "U-A1-014-I06", "U-A1-014-I07"], "listening_tasks": ["U-A1-014-I12", "U-A1-014-I13"], "reading_text_el": "ΒΙΒΛΙΟΘΗΚΗ ΓΕΙΤΟΝΙΑΣ\\nΔευτέρα–Παρασκευή: 09:00–18:00. Σάββατο: 10:00–14:00. Κυριακή: κλειστά.\\nΜάθημα ελληνικών: Τρίτη, 17:00, αίθουσα 2. Είσοδος δωρεάν.\\nΜήνυμα: Άννα, σήμερα είναι Τρίτη. Είμαι στο καφέ δίπλα στη βιβλιοθήκη. Το μάθημα αρχίζει στις πέντε. Εγώ είμαι εδώ από τις τέσσερις και μισή. Νίκος.", "learning_outcome": "Найти явные день, время, место и условие в коротком объявлении", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "transfer": "I16 + новая самостоятельная речь на I17/I19 по item-specific anchors", "controlled": "≥80% закрытых ответов, затем исправление всех смысловых ошибок"}, "vocabulary_items": [{"lemma": "ανοιχτά", "stress": "ανοιχτά", "example": "Το Σάββατο είναι ανοιχτά.", "inflection": "ανοιχτά", "meaning_ru": "открыто", "collocations": ["είναι ανοιχτά"]}, {"lemma": "κλειστά", "stress": "κλειστά", "example": "Την Κυριακή είναι κλειστά.", "inflection": "κλειστά", "meaning_ru": "закрыто", "collocations": ["είναι κλειστά"]}, {"lemma": "είσοδος", "stress": "είσοδος", "example": "Η είσοδος είναι δωρεάν.", "inflection": "η είσοδος", "meaning_ru": "вход", "collocations": ["είσοδος δωρεάν"]}, {"lemma": "δωρεάν", "stress": "δωρεάν", "example": "Το μάθημα είναι δωρεάν.", "inflection": "δωρεάν", "meaning_ru": "бесплатно", "collocations": ["είναι δωρεάν"]}, {"lemma": "αίθουσα", "stress": "αίθουσα", "example": "Είμαι στην αίθουσα δύο.", "inflection": "η αίθουσα", "meaning_ru": "зал, аудитория", "collocations": ["στην αίθουσα δύο"]}, {"lemma": "βιβλιοθήκη", "stress": "βιβλιοθήκη", "example": "Το μάθημα είναι στη βιβλιοθήκη.", "inflection": "η βιβλιοθήκη", "meaning_ru": "библиотека", "collocations": ["στη βιβλιοθήκη"]}, {"lemma": "μήνυμα", "stress": "μήνυμα", "example": "Έχω ένα μήνυμα.", "inflection": "το μήνυμα", "meaning_ru": "сообщение", "collocations": ["ένα μήνυμα"]}, {"lemma": "αρχίζει", "stress": "αρχίζει", "example": "Το μάθημα αρχίζει στις πέντε.", "inflection": "αρχίζω / αρχίζει", "meaning_ru": "начинается", "collocations": ["το μάθημα αρχίζει"]}, {"lemma": "σήμερα", "stress": "σήμερα", "example": "Σήμερα είναι Τρίτη.", "inflection": "σήμερα", "meaning_ru": "сегодня", "collocations": ["σήμερα είναι Τρίτη"]}, {"lemma": "μέχρι", "stress": "μέχρι", "example": "Είναι ανοιχτά μέχρι τις δύο.", "inflection": "μέχρι", "meaning_ru": "до", "collocations": ["μέχρι τις δύο"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-014-I01"], "learning_objectives": ["Найти явные день, время, место и условие в коротком объявлении", "Различить автора и адресата, расписание и событие, факт и отсутствие данных", "Передать прочитанное в самостоятельном ответе и действовать по новому сообщению"], "microcompetency_ids": ["U-A1-014-MC01", "U-A1-014-MC02", "U-A1-014-MC03"], "prerequisite_support": {"A1-G07": "U-A1-004: вопросы где/когда", "A1-G10": "U-A1-011: принадлежность и изученные числительные. Для часов: GreekOS_Academic_Corpus/support/CP06-CLOCK-BRIDGE.json; не предполагать, что часы изучены в уроке алфавита.", "A1-V03": "U-A1-013: библиотека, район, ориентиры; vocabulary bridge supplied"}, "primary_competencies": ["A1-R01"], "learner_data_included": false, "estimated_active_minutes": 65}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
