183	source_claim	CP08-INHERITED-U-A1-006-I04-01	820c819e00058d627caf840f8874b1b4c35dbfeb32373b57a7c7bf2257e99cf7	\N	{"record": {"claim": "Уровневая тема; не дословный источник авторских фраз", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A1-006-I04-01", "item_ids": ["U-A1-006-I04"], "source_id": "V201", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A1-006-I04.json", "sha256": "cbeae1a2a3ab8ef3f1cf4f50b6941a5aa45eda983433496ccce28ebed4c97a83"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "V201 PDF5–6", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}}, "claim_id": "CP08-INHERITED-U-A1-006-I04-01", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3121	unit	U-A1-015	f3347c84720f84ea4e49afa826405c0c7900d6056e48319772c307a08e33a812	core	{"unit_id": "U-A1-015", "content_hash": "f3347c84720f84ea4e49afa826405c0c7900d6056e48319772c307a08e33a812", "canonical_path": "GreekOS_Academic_Corpus/units/U-A1-015.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A1-015-RUBRIC"], "unit_id": "U-A1-015", "version": "0.1.2", "title_ru": "Заполняем карточку и пишем короткую записку", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Вы научитесь заполнять простую карточку и писать короткую записку человеку, который должен найти вас или предмет. Используйте вымышленные сведения. Реальные телефон, адрес, фамилия и документ не нужны. Перед началом нужны вопросы об имени, принадлежность μου/σου, настоящее время и обозначения места/часов из предыдущих уроков. Проверка I01 возвращает к имени и фамилии; при трудностях повторите U-A1-012.\\nВ карточке одно поле — один факт. Όνομα означает имя, επώνυμο — фамилию, πόλη — город, γλώσσα — язык. Для вымышленной Ελένη Δήμου: Όνομα: Ελένη; Επώνυμο: Δήμου. В поле города достаточно Πάτρα. Полное предложение полезно в сообщении: Μένω στην Πάτρα. Не переносите ответ о происхождении в поле нынешнего города, если эти города различаются. Название страны не заменяет город. Не заполняйте отсутствующий телефон выдуманным номером: в этой учебной карточке такого поля нет.\\nЗаписка должна позволять адресату действовать. Обращение в начале показывает, кому вы пишете; подпись в конце — кто пишет. Для наших заданий достаточно простого Γεια σου! либо имени. Изучаем готовые обращения Μαρία, Ελένη; другие формы имён проверяйте отдельно. Затем напишите, где вы сейчас, до какого часа и где нужная вещь. Например: Μαρία, είμαι στη βιβλιοθήκη μέχρι τις έξι. Το βιβλίο σου είναι στο τραπέζι. Ελένη. Подпись не заменяет обращение: перепутанные роли меняют смысл.\\nВыбирайте сведения по цели. «Я в библиотеке до шести» не означает «встречаемся в шесть». Μέχρι τις έξι — конец указанного периода, στις έξι — отдельное время. Не добавляйте будущую встречу, если её нет в условии. Το βιβλίο σου относится к книге адресата, το βιβλίο μου — автора. Повторите предлоги: στο τραπέζι, στη βιβλιοθήκη, στο σπίτι. Переносите точное отношение: на столе не значит рядом со столом.\\nСтройте короткий текст из уже освоенных моделей, а не переводите сложное русское предложение слово за словом. Είμαι…; Το βιβλίο είναι…; Δεν είμαι…; Μένω… достаточны для поставленной задачи. Соединение και уместно, когда добавляет второй факт; αλλά — когда противопоставляет. Время и имена можно сначала выписать отдельно, но итоговую отложенную попытку делайте без образца. Небольшие различия порядка слов не ошибка, если факты и отношения сохранены.\\nПеред отправкой проверьте четыре вещи: адресат и подпись различимы; место и время не перепутаны; принадлежность вещи правильная; все требуемые факты присутствуют. Сначала оцените выполнение задачи, потом формы. Рекомендуемый объём помогает практиковаться, но лишнее слово само по себе не обнуляет ответ. В свободном задании допустим другой корректный текст, а модель не является единственным ключом. После обратной связи перепишите записку для нового адресата и нового места. Это проверяет перенос, а не запоминание.\\nУстная практика нужна для связи письма с общением: продиктуйте вымышленные данные, уточните непонятный факт, затем составьте собственную записку. Пока записи нет, I12/I13 — только подготовленные задания к будущему аудио. Их нельзя оценивать как аудирование, если показан сценарий.\\nПеред заданиями со временем используйте CP06-CLOCK-BRIDGE: στις εννέα το πρωί — в 09:00; στις τρεις το απόγευμα — в 15:00; μέχρι τις πέντε — до пяти, μετά τις πέντε — после пяти. Если воспользовались подсказкой, отметьте помощь; затем назовите другое время без образца.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Συμπληρώνω το δελτίο.", "Αυτό είναι το δελτίο συμμετοχής.", "Μένω στην Πάτρα.", "Μιλάω ελληνικά.", "Γράφω ένα μήνυμα στη Μαρία.", "Συμπληρώνω το όνομα.", "Το βιβλίο είναι στο τραπέζι.", "Είμαι εδώ μέχρι τις έξι."], "review_plan": {"days": [7, 14, 28], "rule": "Новый ответ без модели; после подсказки сохранять assisted, повторить самостоятельно с новыми данными.", "item_ids": ["U-A1-015-I17", "U-A1-015-I18", "U-A1-015-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Παραγωγή γραπτού λόγου; Αναγνώριση ταυτότητας; Κατοικία, διαμονή; Ελεύθερος χρόνος; Επαγγελματικός χώρος", "source_id": "CP06-A1-S01", "checked_on": "2026-10-18", "claim_scope": "A1 functional domains only. No endorsement of GreekOS tasks, durations or mastery thresholds.", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR"}, {"anchor": "επώνυμο το; main definition (line141 in retrieved view)", "source_id": "CP06-A1-S04", "checked_on": "2026-10-18", "claim_scope": "Family name sense only; historical social examples not adopted", "evidence_type": "PRIMARY_LEXICOGRAPHIC"}], "support_refs": ["GreekOS_Academic_Corpus/support/CP06-CLOCK-BRIDGE.json"], "active_recall": ["U-A1-015-I08", "U-A1-015-I09"], "prerequisites": ["A1-G05", "A1-G07", "A1-G09", "A1-G10", "A1-V01", "A1-R01"], "reading_tasks": ["U-A1-015-I10", "U-A1-015-I11"], "transfer_task": "U-A1-015-I16", "writing_tasks": ["U-A1-015-I14"], "competency_ids": ["A1-W01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; no observed learner mastery", "speaking_tasks": ["U-A1-015-I15"], "errors_taxonomy": ["FACT_SUBSTITUTION", "LEXICAL_ROLE_CONFUSION", "REGISTER_MISMATCH", "UNSUPPORTED_INFERENCE", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A1-015-I02", "U-A1-015-I03", "U-A1-015-I04", "U-A1-015-I05", "U-A1-015-I06", "U-A1-015-I07"], "listening_tasks": ["U-A1-015-I12", "U-A1-015-I13"], "reading_text_el": "Δελτίο συμμετοχής\\nΌνομα: Ελένη\\nΕπώνυμο: Δήμου\\nΠόλη: Πάτρα\\nΓλώσσα: ελληνικά\\n\\nΜαρία, σήμερα δεν είμαι στο σπίτι. Είμαι στη βιβλιοθήκη μέχρι τις έξι. Το βιβλίο σου είναι στο τραπέζι. Ελένη.", "learning_outcome": "Заполнить поля имени, фамилии, города и языка по заданным сведениям", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "transfer": "I16 + новая самостоятельная речь на I17/I19 по item-specific anchors", "controlled": "≥80% закрытых ответов, затем исправление всех смысловых ошибок"}, "vocabulary_items": [{"lemma": "δελτίο", "stress": "δελτίο", "example": "Συμπληρώνω το δελτίο.", "inflection": "το δελτίο", "meaning_ru": "бланк, карточка", "collocations": ["δελτίο συμμετοχής"]}, {"lemma": "συμμετοχή", "stress": "συμμετοχή", "example": "Αυτό είναι το δελτίο συμμετοχής.", "inflection": "η συμμετοχή", "meaning_ru": "участие", "collocations": ["δελτίο συμμετοχής"]}, {"lemma": "πόλη", "stress": "πόλη", "example": "Μένω στην Πάτρα.", "inflection": "η πόλη", "meaning_ru": "город", "collocations": ["στην πόλη"]}, {"lemma": "γλώσσα", "stress": "γλώσσα", "example": "Μιλάω ελληνικά.", "inflection": "η γλώσσα", "meaning_ru": "язык", "collocations": ["ελληνική γλώσσα"]}, {"lemma": "γράφω", "stress": "γράφω", "example": "Γράφω ένα μήνυμα στη Μαρία.", "inflection": "γράφω / γράφεις", "meaning_ru": "писать", "collocations": ["γράφω μήνυμα"]}, {"lemma": "συμπληρώνω", "stress": "συμπληρώνω", "example": "Συμπληρώνω το όνομα.", "inflection": "συμπληρώνω / συμπληρώνεις", "meaning_ru": "заполнять", "collocations": ["συμπληρώνω το δελτίο"]}, {"lemma": "τραπέζι", "stress": "τραπέζι", "example": "Το βιβλίο είναι στο τραπέζι.", "inflection": "το τραπέζι", "meaning_ru": "стол", "collocations": ["στο τραπέζι"]}, {"lemma": "μέχρι", "stress": "μέχρι", "example": "Είμαι εδώ μέχρι τις έξι.", "inflection": "μέχρι", "meaning_ru": "до", "collocations": ["μέχρι τις έξι"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-015-I01"], "learning_objectives": ["Заполнить поля имени, фамилии, города и языка по заданным сведениям", "Передать место, время и принадлежность вещи без подмены фактов", "Самостоятельно написать и устно уточнить короткую записку в новом контексте"], "microcompetency_ids": ["U-A1-015-MC01", "U-A1-015-MC02", "U-A1-015-MC03"], "prerequisite_support": {"A1-G05": "U-A1-001: είμαι/έχω", "A1-G07": "U-A1-004: вопросы", "A1-G09": "U-A1-004: предлоги и местоположение; новый пример без модели после повторения.", "A1-G10": "U-A1-011: принадлежность и изученные числительные. Для часов: GreekOS_Academic_Corpus/support/CP06-CLOCK-BRIDGE.json; не предполагать, что часы изучены в уроке алфавита.", "A1-R01": "U-A1-014: автор, адресат, время", "A1-V01": "U-A1-012: имя/фамилия/город"}, "primary_competencies": ["A1-W01"], "learner_data_included": false, "estimated_active_minutes": 65}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3122	unit	U-A1-016	41d5d6a4d67f22473addcf1bdd24d00c77bb810eb0e67244fa8c4162b3cd6d40	core	{"unit_id": "U-A1-016", "content_hash": "41d5d6a4d67f22473addcf1bdd24d00c77bb810eb0e67244fa8c4162b3cd6d40", "canonical_path": "GreekOS_Academic_Corpus/units/U-A1-016.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A1-016-RUBRIC"], "unit_id": "U-A1-016", "version": "0.1.1", "title_ru": "Знакомство и простая покупка: спросить, уточнить, завершить", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Задача урока — начать короткий разговор и выполнить простую покупку, сохраняя количество, предмет и цену. Это две связанные, но разные функции: в знакомстве мы обмениваемся личной информацией, в магазине договариваемся о конкретном действии. Не нужно сначала произносить длинный рассказ о себе, чтобы попросить воду. Перед началом проверьте вопросы из U-A1-004 и числа из U-A1-003: Πώς σε λένε; Πόσο κάνει; ένα, δύο, τρία, τέσσερα. Если путаются количество и цена, сначала используйте карточки с отдельными полями «товар / количество / цена», затем уберите карточки.\\nДля знакомства с ровесником: Γεια σου! Με λένε Άννα. Εσένα; Встречный вопрос уместен, когда тема уже ясна. Сотруднику, которого вы не знаете, для этой практики выбираем Γεια σας или Καλημέρα. Готовые пары σε/σας и σου/σας меняют обращение: Πώς σε λένε; — Πώς σας λένε; Δεν καταλαβαίνω — не понимаю. Не объявляем один вариант единственным допустимым во всей Греции: отношения, возраст и обстановка влияют на выбор. В заданиях адресат задан прямо; оцениваем выполнение конкретной роли, а не личность говорящего.\\nВ магазине начните с предмета и количества: Ένα νερό, παρακαλώ. Δύο χυμούς, παρακαλώ. Эти две формы здесь учим как готовые сочетания; полная парадигма существительного не требуется. Для уточнения наличия: Έχετε νερό; Для цены одного выбранного товара: Πόσο κάνει; Для общей стоимости заказа: Πόσο κάνουν όλα μαζί; В коротком заказе название товара с παρακαλώ само по себе может быть достаточной просьбой; не требуем обязательно длинную форму Θα ήθελα. Вводим её как необязательный вежливый готовый блок: Θα ήθελα ένα νερό, παρακαλώ. Это не урок условного наклонения.\\nОтличайте вопрос продавца от нового заказа. Ένα ή δύο; просит выбрать количество. Μικρό ή μεγάλο; — размер. Κρύο ή όχι; — холодный напиток или нет. Если вы не расслышали число, нельзя уверенно подтверждать случайный вариант. Скажите Πάλι, παρακαλώ или Πιο αργά, παρακαλώ; затем повторите услышанное как вопрос: Τρία ευρώ; В этой практике одно повторение допустимо и считается успешным восстановлением общения, но чтение готовой реплики с экрана отмечается как помощь.\\nИсправление должно называть правильный факт. Όχι δύο, ένα, παρακαλώ исправляет количество. Όχι χυμό, νερό, παρακαλώ исправляет предмет. Простое Όχι не сообщает, что именно требуется. Если товара нет, можно выбрать предложенную замену или отказаться: Όχι, ευχαριστώ. Не предполагаем, что покупатель обязан согласиться. Завершение: Ευχαριστώ. Γεια σας. Задания не требуют передачи реальных платёжных данных или совершения покупки.\\nТренируйтесь сначала по ролям, затем меняйте товар, количество и собеседника. Один участник знает, какой товар отсутствует; второй узнаёт это только в разговоре. Проверяем не запомненную последовательность, а способность заметить несовпадение и уточнить. Успешный результат — продавец и покупатель одинаково понимают итоговый заказ. Произношение и понимание на слух оцениваются только по реальному звуку; пока запись отсутствует, транскрипт пригоден для чтения, но балл за аудирование заблокирован.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Γεια σας!", "Με λένε Μαρία. Εσένα;", "Ένα νερό, παρακαλώ.", "Δύο χυμούς, παρακαλώ.", "Πόσο κάνει;", "Πόσο κάνουν όλα μαζί;", "Έχετε νερό;", "Πάλι, παρακαλώ.", "Πιο αργά, παρακαλώ.", "Όχι δύο, ένα, παρακαλώ.", "Όχι, ευχαριστώ.", "Ευχαριστώ. Γεια σας!"], "review_plan": {"days": [7, 14, 28], "rule": "Новый ответ без модели; после подсказки сохранять assisted, повторить самостоятельно с новыми данными.", "item_ids": ["U-A1-016-I17", "U-A1-016-I18", "U-A1-016-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Ειδικοί Εκπαιδευτικοί Στόχοι, L86–88; Παραγωγή προφορικού λόγου, L105–107", "source_id": "CP06-A1-S01", "checked_on": "2026-10-20", "claim_scope": "Functional scope only; no institutional endorsement of original tasks, thresholds, language forms or CEFR mediation descriptor.", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR_REINSPECTED"}], "active_recall": ["U-A1-016-I08", "U-A1-016-I09"], "prerequisites": ["A1-G07", "A1-V02"], "reading_tasks": ["U-A1-016-I10", "U-A1-016-I11"], "transfer_task": "U-A1-016-I16", "writing_tasks": ["U-A1-016-I14"], "competency_ids": ["A1-SI01"], "coverage_claim": "AUTHORED_DRAFT_PARTIAL_MACRO; speaking acoustic evidence and full source audit pending", "speaking_tasks": ["U-A1-016-I15", "U-A1-016-I20"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION", "FACT_SUBSTITUTION", "PRAGMATICS_REGISTER", "ASR_UNCERTAIN", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A1-016-I02", "U-A1-016-I03", "U-A1-016-I04", "U-A1-016-I05", "U-A1-016-I06", "U-A1-016-I07"], "listening_tasks": ["U-A1-016-I12", "U-A1-016-I13"], "reading_text_el": "Πωλήτρια: Καλημέρα!\\nΆννα: Καλημέρα. Ένα νερό και δύο χυμούς, παρακαλώ.\\nΠωλήτρια: Έχουμε μόνο έναν χυμό.\\nΆννα: Εντάξει. Ένα νερό και έναν χυμό. Πόσο κάνουν όλα μαζί;\\nΠωλήτρια: Τρία ευρώ.\\nΆννα: Τρία ευρώ;\\nΠωλήτρια: Ναι.\\nΆννα: Ευχαριστώ. Γεια σας!", "learning_outcome": "Начать знакомство и ответить на простой вопрос", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "transfer": "Unprompted I16 and new D7/D28 with facts preserved, assistance logged", "controlled": "All meaning-changing errors corrected; ≥80% is project heuristic, not official threshold"}, "vocabulary_items": [{"lemma": "το νερό", "stress": "το νερό", "example": "Ένα νερό, παρακαλώ.", "inflection": "το νερό → ένα νερό / δύο νερά", "meaning_ru": "вода", "collocations": ["Ένα νερό, παρακαλώ."]}, {"lemma": "ο χυμός", "stress": "ο χυμός", "example": "Έναν χυμό, παρακαλώ.", "inflection": "ο χυμός → έναν χυμό / δύο χυμούς", "meaning_ru": "сок", "collocations": ["Έναν χυμό, παρακαλώ."]}, {"lemma": "όλα μαζί", "stress": "όλα μαζί", "example": "Πόσο κάνουν όλα μαζί;", "inflection": "Устойчивое сочетание в этой функции", "meaning_ru": "всё вместе", "collocations": ["Πόσο κάνουν όλα μαζί;"]}, {"lemma": "πάλι", "stress": "πάλι", "example": "Πάλι, παρακαλώ.", "inflection": "Неизменяемое наречие", "meaning_ru": "снова", "collocations": ["Πάλι, παρακαλώ."]}, {"lemma": "μικρό / μεγάλο", "stress": "μικρό / μεγάλο", "example": "Μικρό ή μεγάλο;", "inflection": "μικρό/μεγάλο: средний род единственного; μικρά/μεγάλα: множественное", "meaning_ru": "маленькое / большое", "collocations": ["Μικρό ή μεγάλο;"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-016-I01"], "learning_objectives": ["Начать знакомство и ответить на простой вопрос", "Согласовать предмет, количество и цену простой покупки", "Восстановить понимание и самостоятельно изменить заказ"], "microcompetency_ids": ["U-A1-016-MC01", "U-A1-016-MC02", "U-A1-016-MC03"], "prerequisite_support": {"A1-G07": "U-A1-004; entry I01 asks price. If confused, distinguish πού/πόσο then retry with new product.", "A1-V02": "U-A1-003; rehearse1–4 and ευρώ; if quantities fail use labelled cards before independent retry."}, "primary_competencies": ["A1-SI01"], "learner_data_included": false, "estimated_active_minutes": 70}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
