189	source_claim	CP08-INHERITED-U-A1-006-I07-01	16a3e4262258b6ccdac3e6196e171fd05595725c4ae0d27a82d4fa3361bb5843	\N	{"record": {"claim": "Уровневая тема; не дословный источник авторских фраз", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A1-006-I07-01", "item_ids": ["U-A1-006-I07"], "source_id": "V201", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A1-006-I07.json", "sha256": "2796bdd6089b0437964b755a3124114937af449a1c66ac9b7163cef1b820512a"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "V201 PDF5–6", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}}, "claim_id": "CP08-INHERITED-U-A1-006-I07-01", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3123	unit	U-A1-017	4acf8f7a56a649c615dd3b4d4274c694f277464bb46497732d016d751f098203	core	{"unit_id": "U-A1-017", "content_hash": "4acf8f7a56a649c615dd3b4d4274c694f277464bb46497732d016d751f098203", "canonical_path": "GreekOS_Academic_Corpus/units/U-A1-017.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A1-017-RUBRIC"], "unit_id": "U-A1-017", "version": "0.1.1", "title_ru": "Короткое описание себя и привычного дня", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "В этом уроке вы создаёте короткое устное описание себя и обычного дня. Цель — понятная последовательность знакомых фактов, а не длинное выступление или выученная биография. Используйте вымышленную личность; настоящие адреса, телефон и сведения родственников не нужны. Проверка входа: различите Είμαι δάσκαλος (роль), μένω στην Πάτρα (проживание), δουλεύω το πρωί (действие). При ошибках вернитесь к настоящему времени в U-A1-005 и личной лексике U-A1-012, затем опишите нового человека.\\nПостройте описание из четырёх смысловых опор: кто я; где живу и чем занимаюсь; что обычно делаю утром и вечером; что мне нравится. Имя можно назвать Με λένε Άννα или Είμαι η Άννα. Είμαι από την Αθήνα описывает происхождение, а μένω στην Πάτρα — нынешний город. Один факт не отменяет другой. Не добавляйте происхождение, если карточка его не содержит.\\nДля обычного дня используем уже изученное настоящее: δουλεύω, διαβάζω, ακούω, βλέπω, παίζω. В данном уроке το πρωί и το βράδυ задают повторяющуюся часть дня; σήμερα обозначает именно сегодня. Фраза Σήμερα δεν δουλεύω не означает, что человек никогда не работает. Вместо обычного расписания можно честно сказать Δεν δουλεύω τώρα, если это относится к вашей вымышленной роли. Новые выражения по времени вводятся как готовые блоки: μετά τη δουλειά — после работы; το Σάββατο — в субботу. Из них не следует конкретный час.\\nСвязь между фразами можно показать и простыми словами. Και соединяет совместимые сведения: Δουλεύω και σπουδάζω. Αλλά подчёркивает контраст: Μου αρέσει το ποδόσφαιρο, αλλά δεν παίζω. Это не противоречие: человек может смотреть матчи. Μου αρέσει η μουσική и ακούω μουσική тоже не полностью одинаковые факты: первое — предпочтение, второе — действие. Если требуется назвать оба, произнесите оба. Не требуем сложных союзов ради красивого текста.\\nПеред речью можно выписать четыре ключевых слова, но не готовые предложения. Затем уберите опоры и говорите 30–45 секунд: время здесь ориентир, а не экзаменационный норматив. Короткие паузы и самостоятельное исправление допустимы. Если вы сказали неверный город, исправьте именно его: Όχι στην Αθήνα, στην Πάτρα. Повторение одной фразы пять раз не выполняет пять разных условий. После описания ответьте на один неожиданный уточняющий вопрос, например Τι κάνεις το βράδυ;.\\nСлушатель проверяет факты, а затем форму: понятно ли, кто человек, где живёт, что делает и что любит? Он не должен угадывать недостающие сведения. Произношение нельзя оценить по текстовому ответу; транскрипт показывает только содержание. Незнакомое слово можно заменить знакомым подходящим выражением. При подсказке отмечайте assisted; затем повторите с новой ролью без модели. В D7/D28 меняются город, работа и распорядок, чтобы проверить перенос, а не память рассказа.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Με λένε Σοφία.", "Είμαι από τον Βόλο.", "Μένω στην Πάτρα.", "Είμαι δασκάλα.", "Το πρωί δουλεύω.", "Μετά τη δουλειά διαβάζω.", "Το βράδυ ακούω μουσική.", "Μου αρέσει το ποδόσφαιρο, αλλά δεν παίζω.", "Σήμερα δεν δουλεύω.", "Όχι στην Αθήνα, στην Πάτρα."], "review_plan": {"days": [7, 14, 28], "rule": "Новый ответ без модели; после подсказки сохранять assisted, повторить самостоятельно с новыми данными.", "item_ids": ["U-A1-017-I17", "U-A1-017-I18", "U-A1-017-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Παραγωγή προφορικού λόγου, L105–107", "source_id": "CP06-A1-S01", "checked_on": "2026-10-20", "claim_scope": "Functional scope only; no institutional endorsement of original tasks, thresholds, language forms or CEFR mediation descriptor.", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR_REINSPECTED"}], "active_recall": ["U-A1-017-I08", "U-A1-017-I09"], "prerequisites": ["A1-G06", "A1-V01"], "reading_tasks": ["U-A1-017-I10", "U-A1-017-I11"], "transfer_task": "U-A1-017-I16", "writing_tasks": ["U-A1-017-I14"], "competency_ids": ["A1-SP01"], "coverage_claim": "AUTHORED_DRAFT_PARTIAL_MACRO; speaking acoustic evidence and full source audit pending", "speaking_tasks": ["U-A1-017-I15", "U-A1-017-I20"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION", "FACT_SUBSTITUTION", "PRAGMATICS_REGISTER", "ASR_UNCERTAIN", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A1-017-I02", "U-A1-017-I03", "U-A1-017-I04", "U-A1-017-I05", "U-A1-017-I06", "U-A1-017-I07"], "listening_tasks": ["U-A1-017-I12", "U-A1-017-I13"], "reading_text_el": "Με λένε Σοφία. Είμαι από τον Βόλο, αλλά μένω στην Πάτρα. Είμαι δασκάλα. Το πρωί δουλεύω στο σχολείο. Μετά τη δουλειά διαβάζω στο σπίτι. Το βράδυ ακούω μουσική. Μου αρέσει το ποδόσφαιρο, αλλά δεν παίζω. Βλέπω αγώνες το Σάββατο. Σήμερα δεν δουλεύω.", "learning_outcome": "Представить личность, город и занятие без подмены фактов", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "transfer": "Unprompted I16 and new D7/D28 with facts preserved, assistance logged", "controlled": "All meaning-changing errors corrected; ≥80% is project heuristic, not official threshold"}, "vocabulary_items": [{"lemma": "το πρωί", "stress": "το πρωί", "example": "Το πρωί διαβάζω.", "inflection": "Готовое обстоятельственное сочетание времени", "meaning_ru": "утром", "collocations": ["Το πρωί διαβάζω."]}, {"lemma": "το βράδυ", "stress": "το βράδυ", "example": "Το βράδυ δουλεύω.", "inflection": "Готовое обстоятельственное сочетание времени", "meaning_ru": "вечером", "collocations": ["Το βράδυ δουλεύω."]}, {"lemma": "μετά τη δουλειά", "stress": "μετά τη δουλειά", "example": "Μετά τη δουλειά ακούω μουσική.", "inflection": "Готовое сочетание; η δουλειά → τη δουλειά", "meaning_ru": "после работы", "collocations": ["Μετά τη δουλειά ακούω μουσική."]}, {"lemma": "σήμερα", "stress": "σήμερα", "example": "Σήμερα δεν δουλεύω.", "inflection": "Неизменяемое наречие", "meaning_ru": "сегодня", "collocations": ["Σήμερα δεν δουλεύω."]}, {"lemma": "αλλά", "stress": "αλλά", "example": "Μου αρέσει το ποδόσφαιρο, αλλά δεν παίζω.", "inflection": "Неизменяемый союз", "meaning_ru": "но", "collocations": ["Μου αρέσει το ποδόσφαιρο, αλλά δεν παίζω."]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-017-I01"], "learning_objectives": ["Представить личность, город и занятие без подмены фактов", "Связать действия обычного дня и предпочтения простыми фразами", "Самостоятельно описать новую роль и исправить ошибку"], "microcompetency_ids": ["U-A1-017-MC01", "U-A1-017-MC02", "U-A1-017-MC03"], "prerequisite_support": {"A1-G06": "U-A1-005: настоящее; I01 входная проверка первого лица; при ошибке повторить два глагола с новым субъектом", "A1-V01": "U-A1-012: личность и интересы; I02 различает происхождение/проживание"}, "primary_competencies": ["A1-SP01"], "learner_data_included": false, "estimated_active_minutes": 70}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3124	unit	U-A1-018	3f7fd1faab0cca4b782f6df65f4ae67fef57fb03603e2db8f13632db28005d2c	core	{"unit_id": "U-A1-018", "content_hash": "3f7fd1faab0cca4b782f6df65f4ae67fef57fb03603e2db8f13632db28005d2c", "canonical_path": "GreekOS_Academic_Corpus/units/U-A1-018.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A1-018-RUBRIC"], "unit_id": "U-A1-018", "version": "0.1.1", "title_ru": "Передать другу время и место встречи", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Медиация здесь означает простое посредничество: вы читаете короткое сообщение и передаёте другу нужные время и место. Не нужно переводить каждое слово или объяснять сложную грамматику. Важно сохранить сведения источника и ясно показать, чего источник не сообщает. Используем только учебные события и вымышленных людей. Перед началом проверьте чтение объявления в U-A1-014 и умение уточнить непонятное в U-A1-016.\\nСначала определите задачу друга. Анна спрашивает «Когда и где встреча?» — значит, нужны день, время и место, а не все сведения о погоде или занятиях автора. Выпишите три поля: день / время / место. Время 18:00 передаём как στις έξι το απόγευμα или στις 18:00. Если 09:00 указано явно, нельзя превратить его в вечер. В заданиях без контекста утро/вечер может быть неизвестным: при недостатке данных спросите, а не выбирайте сами.\\nОтделяйте встречу от подготовки. «Είμαι στο καφέ από τις πέντε. Η συνάντηση είναι στις έξι» означает, что автор в кафе с пяти, но встреча в шесть. Так же часы работы библиотеки не обязательно совпадают с мероприятием. Передавая адресату факт, назовите само событие: Η συνάντηση είναι την Τρίτη στις έξι. Так меньше риска, что число относится к другому действию.\\nСохраняйте отношения места. Μπροστά στη βιβλιοθήκη — перед библиотекой, όχι μέσα — не внутри. Δίπλα στο καφέ — рядом с кафе, не обязательно в кафе. Если номер комнаты не указан, нельзя придумать его ради полноты. Прямой ответ Δεν γράφει την αίθουσα сообщает предел знания. Чтобы уточнить, используйте Πού ακριβώς; Σε ποια αίθουσα; Последняя фраза вводится целиком как просьба назвать комнату, без новой парадигмы ποιος.\\nСледите за отправителем и адресатом. В нашем сообщении «Άννα, ... Νίκος» Никос пишет Анне. При передаче третьему человеку достаточно Ο Νίκος γράφει… или Η συνάντηση είναι…; необязательно превращать весь текст в косвенную речь. Не говорите «я буду там», если это обещал автор, а не вы. Проще прямо назвать участника: Ο Νίκος είναι στο καφέ. В упражнениях разрешена передача по-русски для проверки понимания, но там, где указано по-гречески, требуется самостоятельная греческая фраза.\\nЕсли пришло явное исправление, передавайте последнее подтверждённое условие и объясняйте изменение: Όχι την Τρίτη, την Τετάρτη. Старое время не сохраняется автоматически, если новая строка задаёт другое. Если два сообщения противоречат друг другу без явного исправления, уточните; не выдавайте догадку за решение. Слова из задания «исправление» или «новое подтверждение» важны для выбора версии.\\nРаботайте в две попытки: сначала прочитайте и передайте без готовой модели; потом сравните три поля с исходником. Попросите друга повторить ключевые сведения и исправьте только расхождение. Балл за содержание отделяется от балла за язык: правильные цифры с небольшими языковыми ошибками могут сохранить смысл, но неверный день в безупречной фразе проваливает задачу. В D7/D28 используются новые объявления, включая пропущенное поле. Аудиоверсия возможна только после записи и проверки звука.\\nОпора для половины часа: 16:30 — στις τέσσερις και μισή το απόγευμα; 17:30 — στις πέντε και μισή το απόγευμα. Здесь και μισή означает ещё половину часа после названного часа. Перед D7 потренируйте на другом времени, например18:30 — στις έξι και μισή το απόγευμα, затем уберите образец. В письменной передаче допустимо сохранить точные цифры: στις16:30; это сохраняет содержание, но само по себе не доказывает умение устно назвать половину часа.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Η συνάντηση είναι την Τρίτη.", "Στις έξι το απόγευμα.", "Μπροστά στη βιβλιοθήκη, όχι μέσα.", "Ο Νίκος είναι στο καφέ.", "Πού ακριβώς;", "Σε ποια αίθουσα;", "Δεν γράφει την αίθουσα.", "Όχι την Τρίτη, την Τετάρτη.", "Στο ίδιο μέρος."], "review_plan": {"days": [7, 14, 28], "rule": "Новый ответ без модели; после подсказки сохранять assisted, повторить самостоятельно с новыми данными.", "item_ids": ["U-A1-018-I17", "U-A1-018-I18", "U-A1-018-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Γενικός Εκπαιδευτικός Στόχος, L83–84; Κατανόηση γραπτού λόγου, L98–100; Παραγωγή προφορικού λόγου,L105", "source_id": "CP06-A1-S01", "checked_on": "2026-10-20", "claim_scope": "Functional scope only; no institutional endorsement of original tasks, thresholds, language forms or CEFR mediation descriptor.", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR_REINSPECTED"}], "active_recall": ["U-A1-018-I08", "U-A1-018-I09"], "prerequisites": ["A1-R01", "A1-SI01"], "reading_tasks": ["U-A1-018-I10", "U-A1-018-I11"], "transfer_task": "U-A1-018-I16", "writing_tasks": ["U-A1-018-I14"], "competency_ids": ["A1-M01"], "coverage_claim": "AUTHORED_DRAFT_PARTIAL_MACRO; speaking acoustic evidence and full source audit pending", "speaking_tasks": ["U-A1-018-I15", "U-A1-018-I20"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION", "FACT_SUBSTITUTION", "PRAGMATICS_REGISTER", "ASR_UNCERTAIN", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A1-018-I02", "U-A1-018-I03", "U-A1-018-I04", "U-A1-018-I05", "U-A1-018-I06", "U-A1-018-I07"], "listening_tasks": ["U-A1-018-I12", "U-A1-018-I13"], "reading_text_el": "Άννα, η συνάντηση είναι την Τρίτη στις 18:00 μπροστά στη βιβλιοθήκη. Δεν είναι μέσα στο κτίριο. Εγώ είμαι στο καφέ δίπλα στη βιβλιοθήκη από τις 17:30. Νίκος.\\nΝέο μήνυμα — διόρθωση: Η συνάντηση είναι την Τετάρτη στις 18:00, στο ίδιο μέρος. Νίκος.", "learning_outcome": "Извлечь день, время и место из простого сообщения", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "transfer": "Unprompted I16 and new D7/D28 with facts preserved, assistance logged", "controlled": "All meaning-changing errors corrected; ≥80% is project heuristic, not official threshold"}, "vocabulary_items": [{"lemma": "η συνάντηση", "stress": "η συνάντηση", "example": "Η συνάντηση είναι στις έξι.", "inflection": "η συνάντηση → τη συνάντηση", "meaning_ru": "встреча", "collocations": ["Η συνάντηση είναι στις έξι."]}, {"lemma": "μπροστά", "stress": "μπροστά", "example": "Μπροστά στο μουσείο.", "inflection": "Неизменяемое наречие; μπροστά σε + место", "meaning_ru": "перед", "collocations": ["Μπροστά στο μουσείο."]}, {"lemma": "μέσα", "stress": "μέσα", "example": "Δεν είναι μέσα.", "inflection": "Неизменяемое наречие; μέσα σε + место", "meaning_ru": "внутри", "collocations": ["Δεν είναι μέσα."]}, {"lemma": "το ίδιο μέρος", "stress": "το ίδιο μέρος", "example": "Η συνάντηση είναι στο ίδιο μέρος.", "inflection": "το μέρος → στο ίδιο μέρος", "meaning_ru": "то же место", "collocations": ["Η συνάντηση είναι στο ίδιο μέρος."]}, {"lemma": "η διόρθωση", "stress": "η διόρθωση", "example": "Νέο μήνυμα: διόρθωση.", "inflection": "η διόρθωση → τη διόρθωση", "meaning_ru": "исправление", "collocations": ["Νέο μήνυμα: διόρθωση."]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-018-I01"], "learning_objectives": ["Извлечь день, время и место из простого сообщения", "Передать нужные сведения без подмены автора и без домысливания", "Уточнить пропуск или исправление и проверить понимание друга"], "microcompetency_ids": ["U-A1-018-MC01", "U-A1-018-MC02", "U-A1-018-MC03"], "prerequisite_support": {"A1-R01": "U-A1-014: объявления; I01 входная проверка времени; при ошибке отделить часы работы от события", "A1-SI01": "U-A1-016 раньше в этой партии; I02/I06 проверяют уточнение; сначала восстановить понимание, затем новая попытка"}, "primary_competencies": ["A1-M01"], "learner_data_included": false, "estimated_active_minutes": 70}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
