195	source_claim	CP08-INHERITED-U-A1-006-I10-01	c6b4274fc2b4f50974026e41cb77545d9387c096faa3f0ef082ce919bdb23e39	\N	{"record": {"claim": "Уровневая тема; не дословный источник авторских фраз", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A1-006-I10-01", "item_ids": ["U-A1-006-I10"], "source_id": "V201", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A1-006-I10.json", "sha256": "cd449f384a8feeba61d4c754aaa58b618a75523da393c3647a02801ac3714492"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "V201 PDF5–6", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}}, "claim_id": "CP08-INHERITED-U-A1-006-I10-01", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3125	unit	U-A1-019	05428d6a65954916f8bfbc28e347aa16968a9bec9522d5b3808b3804ec738e64	core	{"unit_id": "U-A1-019", "content_hash": "05428d6a65954916f8bfbc28e347aa16968a9bec9522d5b3808b3804ec738e64", "canonical_path": "GreekOS_Academic_Corpus/units/U-A1-019.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "COMPLETE_NOT_INDEPENDENT", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A1-019-RUBRIC"], "unit_id": "U-A1-019", "version": "0.1.0", "title_ru": "Понять знакомый вопрос и ответить по существу", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Сначала определите, какую информацию просит собеседник. Πώς σε λένε; — имя, Πού μένεις; — место проживания, Από πού είσαι; — происхождение, Τι δουλειά κάνεις; — работа. Похожая тема не делает ответы взаимозаменяемыми: Μένω στην Πάτρα отвечает о проживании, а Είμαι από τη Γεωργία — о происхождении. Перед уроком проверьте слова о семье, городе и занятиях. Если они незнакомы, вернитесь к A1-V01, затем выполните другой входной вопрос без подсказки.\\nПри первом прослушивании ищите вопросительное слово и знакомую тему. При втором — конкретный факт. Не пытайтесь переводить каждый звук; короткий ответ Στην Πάτρα допустим, если вопрос ясен. Но ответ на Πού μένεις; словом Ναι не передаёт место. Вопрос Μένεις στην Πάτρα; допускает Ναι или Όχι и уточнение. Эти два типа вопросов требуют разных ответов.\\nНе принимайте услышанную реплику за факт о себе. Вы отвечаете из карточки роли, а не повторяете последнюю реплику. Карточка может говорить «происхождение — Кипр; проживание — Афины»: Είμαι από την Κύπρο. Μένω στην Αθήνα. В учебной практике используйте вымышленные сведения. Не требуется сообщать настоящий адрес или профессию.\\nСлушайте отрицание и исправление до конца: Δεν μένω στην Αθήνα. Μένω στην Πάτρα. Первое названное место не обязательно правильный ответ. Если пропущено ключевое слово, попросите повторить: Πάλι, παρακαλώ. Πιο αργά, παρακαλώ. Для проверки: Στην Πάτρα; Реплика уточнения лучше уверенного неверного ответа. Одно повторение фиксируется отдельно от показа готового ответа.\\nПорядок практики: знакомый вопрос с выбором функции → короткий ответ без вариантов → исправление ложного факта → беседа с новым человеком. В аудировании текст закрыт до завершения попытки; затем сравните услышанное с транскриптом и назовите именно пропущенный фрагмент. Чтение транскрипта помогает учиться, но не доказывает понимание звука. Пока аудио отсутствует, доступна только текстовая подготовка, а аудио-оценка заблокирована.\\nВ самостоятельной беседе отвечайте на новый вопрос, а не воспроизводите заученный монолог. Критерии: ответ относится к нужному полю, сохраняет факт роли, понятен адресату. Полное предложение полезно для закрепления, но не является единственным допустимым вариантом. Через семь и двадцать восемь дней используйте другие имена и города; запишите, нужна ли была помощь.", "cefr_level": "A1", "time_basis": "AUTHOR_PLANNING_ESTIMATE_NOT_PILOTED", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Πώς σε λένε;", "Πού μένεις;", "Από πού είσαι;", "Μένεις στην Αθήνα;", "Δεν μένω στην Αθήνα. Μένω στην Πάτρα.", "Πιο αργά, παρακαλώ."], "review_plan": {"days": [7, 28], "rule": "New stimulus, no model shown before attempt; assistance recorded; corrected answer alone is not independent retention", "item_ids": ["U-A1-019-I14", "U-A1-019-I15"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Κατανόηση προφορικού λόγου, paragraphs 1–