3126	unit	U-A1-020	e1bf134269f2c1dcff392a3825002eb9a8635a319679f0428b2bc65be26db226	core	{"unit_id": "U-A1-020", "content_hash": "e1bf134269f2c1dcff392a3825002eb9a8635a319679f0428b2bc65be26db226", "canonical_path": "GreekOS_Academic_Corpus/units/U-A1-020.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "COMPLETE_NOT_INDEPENDENT", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A1-020-RUBRIC"], "unit_id": "U-A1-020", "version": "0.1.0", "title_ru": "Числа, время и простые объявления", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "В объявлении заранее определите, что нужно для действия: номер, время, место или цена. Одно и то же число может быть номером автобуса или часом. В «Το λεωφορείο δώδεκα φεύγει στις τρεις» δώδεκα — номер, τρεις — время. Слова рядом с числом важнее догадки по первому услышанному числу. На входе повторите числа A1-V02. Все расписания урока вымышлены и не являются информацией о реальном транспорте.\\nЧасы: στις τρεις — в три; στις τρεις και μισή — в половине четвёртого; στις τέσσερις παρά τέταρτο — без четверти четыре. Для этого урока используем именно эти готовые формы. Различайте χρόνο события и номер места: αίθουσα δύο — аудитория два. Если в записи не сказано πρωί или απόγευμα и контекст не помогает, не добавляйте утро/вечер от себя. В заданиях, где нужен формат 24 часа, часть суток дана явно.\\nСлушайте всё сообщение до конца: «Όχι στην αίθουσα δύο. Στην αίθουσα τρία» отменяет первоначальное место. «Σήμερα» ограничивает изменение сегодняшним днём; не переносите его на постоянное расписание. Составьте короткую заметку: событие — время — место — изменение. Записывать цифрами допустимо: это снижает нагрузку на письмо, но не должно менять смысл.\\nДля проверки услышанного используйте «Στις τρεις;», «Στην αίθουσα δύο;». Если вы не расслышали, «Τι ώρα;» запрашивает время, «Πού;» — место. Переспрос должен касаться пропущенного поля. Отдельно проверяйте цену одного предмета и общую сумму. «Δύο ευρώ το ένα» не означает, что два предмета стоят два евро.\\nПервое прослушивание — определить событие; второе — заполнить поля. Пауза для ответа допустима, но искусственное выделение правильного числа голосом запрещено в записи. После попытки разрешается открыть транскрипт и объяснить, что отличало правильный вариант от отвлекающего. До записи задания считаются подготовленными текстами, а не выполненным аудированием.\\nЗаключительная задача — передать объявление другому человеку, которому нужны только время и место. Не добавляйте неизвестную причину изменения. Успешное воспроизведение сегодня проверяется снова через неделю и четыре недели на другом сообщении, иначе мы измерим память конкретного ключа.", "cefr_level": "A1", "time_basis": "AUTHOR_PLANNING_ESTIMATE_NOT_PILOTED", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Το λεωφορείο δώδεκα φεύγει στις τρεις.", "Στις τρεις και μισή.", "Στις τέσσερις παρά τέταρτο.", "Σήμερα, στην αίθουσα τρία.", "Δύο ευρώ το ένα.", "Τι ώρα αρχίζει;"], "review_plan": {"days": [7, 28], "rule": "New stimulus, no model shown before attempt; assistance recorded; corrected answer alone is not independent retention", "item_ids": ["U-A1-020-I13", "U-A1-020-I14"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Κατανόηση προφορικού λόγου, paragraphs 1–4 (retrieval lines91–95)", "source_id": "CP08-A1", "checked_on": "2026-10-21", "claim_scope": "Bounded descriptor or phonological principle only; original examples, lesson sequence, rubrics and thresholds are not official"}], "active_recall": ["U-A1-020-I08"], "prerequisites": ["A1-V02"], "reading_tasks": ["U-A1-020-I09"], "transfer_task": "U-A1-020-I12", "writing_tasks": [], "assessment_map": [{"kind": "short", "item_id": "U-A1-020-I01", "objective": "Различить номер и время", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-A1-020-I02", "objective": "Различить номер и время", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_short", "item_id": "U-A1-020-I03", "objective": "Различить номер и время", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-A1-020-I04", "objective": "Различить номер и время", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-A1-020-I05", "objective": "Различить номер и время", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_short", "item_id": "U-A1-020-I06", "objective": "Извлечь исправленную информацию", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "mcq", "item_id": "U-A1-020-I07", "objective": "Извлечь исправленную информацию", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "short", "item_id": "U-A1-020-I08", "objective": "Извлечь исправленную информацию", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "read_mcq", "item_id": "U-A1-020-I09", "objective": "Извлечь исправленную информацию", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-A1-020-I10", "objective": "Извлечь исправленную информацию", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "speak", "item_id": "U-A1-020-I11", "objective": "Передать нужные поля и уточнить неизвестное", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-A1-020-I12", "objective": "Передать нужные поля и уточнить неизвестное", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_short", "item_id": "U-A1-020-I13", "objective": "Передать нужные поля и уточнить неизвестное", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-A1-020-I14", "objective": "Передать нужные поля и уточнить неизвестное", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}], "competency_ids": ["A1-L02"], "coverage_claim": "TEXT_ROUTE_AUTHORED_AUDIO_AND_INDEPENDENT_QA_BLOCKED", "speaking_tasks": ["U-A1-020-I11"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION", "FACT_SUBSTITUTION", "ASR_UNCERTAIN", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A1-020-I02", "U-A1-020-I03", "U-A1-020-I04", "U-A1-020-I05", "U-A1-020-I06", "U-A1-020-I07", "U-A1-020-I09"], "listening_tasks": ["U-A1-020-I02", "U-A