3127	unit	U-A2-001	f39f7193ff3d003c976194a5efaa83170aa29f3e9cd3bb4182b19cedcbc62317	core	{"unit_id": "U-A2-001", "content_hash": "f39f7193ff3d003c976194a5efaa83170aa29f3e9cd3bb4182b19cedcbc62317", "canonical_path": "GreekOS_Academic_Corpus/units/U-A2-001.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A2-001-RUBRIC"], "unit_id": "U-A2-001", "version": "0.1.2", "sections": {"theory": "theory_ru", "practice": ["U-A2-001-I02", "U-A2-001-I03", "U-A2-001-I04", "U-A2-001-I05", "U-A2-001-I06", "U-A2-001-I07"], "reception": ["U-A2-001-I08", "U-A2-001-I09", "U-A2-001-I10", "U-A2-001-I11"], "retention": ["U-A2-001-I15", "U-A2-001-I16", "U-A2-001-I17"], "diagnostic": ["U-A2-001-I01"], "production": ["U-A2-001-I12", "U-A2-001-I13", "U-A2-001-I14"]}, "title_ru": "Одно завершённое событие: ενεργητικός αόριστος", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Αόριστος представляет событие целиком: Χτες αγόρασα ένα εισιτήριο. Это не обязательно короткое действие: Δούλεψα εκεί δύο χρόνια тоже может описывать законченный отрезок. Слова χτες и πέρσι помогают понять время, но сами по себе не определяют выбор вида во всех контекстах. В этом уроке ситуации специально заданы как целостные завершённые события. Систематическое сравнение с παρατατικός оставлено A2 в U-A2-008.\\n\\nЧастотная активная модель: αγόρασα, αγόρασες, αγόρασε, αγοράσαμε, αγοράσατε, αγόρασαν. Ударение нужно учить вместе с формой, а не сохранять механически из настоящего. В некоторых глаголах появляется начальное έ-: γράφω → έγραψα, но γράψαμε. Нельзя добавлять έ- к любому глаголу. Другие формы меняют основу: πηγαίνω → πήγα, βλέπω → είδα, παίρνω → πήρα. Заучиваем их в коротких сообщениях.\\n\\nОтрицание перед глаголом: Δεν πήγα στο γραφείο. Вопрос не требует отдельного вспомогательного глагола: Πότε πήγες; Сравните Κάθε μέρα αγοράζω ψωμί (обычная практика) и Χτες αγόρασα ψωμί (одно событие). Подлежащее часто понятно по окончанию. В рассказе сначала обозначьте время и событие, затем следствие: Χτες αγόρασα μια λάμπα, αλλά δεν λειτουργεί. Это языковая учебная ситуация, а не утверждение о правилах возврата товаров.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Χτες αγόρασα ένα εισιτήριο.", "Η Άννα έγραψε ένα μήνυμα.", "Πήγαμε στο μουσείο το Σάββατο.", "Δεν είδα τον Νίκο χτες.", "Κάθε μέρα παίρνω το λεωφορείο. Χτες πήρα ταξί."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A2-001-I15", "U-A2-001-I16", "U-A2-001-I17"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF7: активный аорист; не переносить систематический imperfect с B1", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Sustained monologue describing experience / correspondence, A2", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A2-001-I06", "U-A2-001-I07"], "prerequisites": ["A1-G06"], "reading_tasks": ["U-A2-001-I08", "U-A2-001-I09"], "transfer_task": "U-A2-001-I14", "writing_tasks": ["U-A2-001-I12"], "competency_ids": ["A2-G03", "A2-SP01", "A2-W01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A2-001-I13"], "errors_taxonomy": ["VERB_TENSE", "ORTHOGRAPHY_ACCENT", "CONTENT_OMISSION"], "guided_practice": ["U-A2-001-I02", "U-A2-001-I03", "U-A2-001-I04", "U-A2-001-I05"], "listening_tasks": ["U-A2-001-I10", "U-A2-001-I11"], "learning_outcome": "Образовать частотный активный аорист в заданном лице", "vocabulary_items": [{"lemma": "αγοράζω", "stress": "αγοράζω", "example": "Αγόρασα δύο εισιτήρια.", "inflection": "αόριστος αγόρασα", "meaning_ru": "покупать", "collocations": ["αγοράζω εισιτήριο"]}, {"lemma": "γράφω", "stress": "γράφω", "example": "Έγραψα στη Μαρία.", "inflection": "αόριστος έγραψα", "meaning_ru": "писать", "collocations": ["γράφω μήνυμα"]}, {"lemma": "πηγαίνω", "stress": "πηγαίνω", "example": "Πήγα στο μουσείο.", "inflection": "αόριστος πήγα", "meaning_ru": "идти/ехать", "collocations": ["πηγαίνω στο μουσείο"]}, {"lemma": "απόδειξη", "stress": "απόδειξη", "example": "Έχω την απόδειξη μαζί μου.", "inflection": "η απόδειξη, οι αποδείξεις", "meaning_ru": "чек", "collocations": ["έχω την απόδειξη"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A2-001-I01"], "learning_objectives": ["Образовать частотный активный аорист в заданном лице", "Понять последовательность отдельных завершённых событий", "Самостоятельно рассказать о завершённой покупке и её результате"], "microcompetency_ids": ["U-A2-001-MC01", "U-A2-001-MC02", "U-A2-001-MC03"], "primary_competencies": ["A2-G03"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3128	unit	U-A2-002	4df871cdd1591fe968599038602bd7b45eeac6f317d5e93557d7c072822f0de3	core	{"unit_id": "U-A2-002", "content_hash": "4df871cdd1591fe968599038602bd7b45eeac6f317d5e93557d7c072822f0de3", "canonical_path": "GreekOS_Academic_Corpus/units/U-A2-002.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A2-002-RUBRIC"], "unit_id": "U-A2-002", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-A2-002-I02", "U-A2-002-I03", "U-A2-002-I04", "U-A2-002-I05", "U-A2-002-I06"], "reception": ["U-A2-002-I07", "U-A2-002-I08", "U-A2-002-I09", "U-A2-002-I10"], "retention": ["U-A2-002-I14", "U-A2-002-I15", "U-A2-002-I16"], "diagnostic": ["U-A2-002-I01"], "production": ["U-A2-002-I11", "U-A2-002-I12", "U-A2-002-I13"]}, "title_ru": "Планы и просьбы: θα и να с совершенной основой", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Θα + личная форма передаёт будущее, а να после θέλω, μπορώ, πρέπει вводит желаемое, возможное или необходимое действие. Здесь учимся представить действие целиком: θα γράψω, θέλω να γράψω, πρέπει να στείλω. Формы пишутся без прошедшей аугментации: έγραψα, но θα γράψω; έστειλα, но να στείλω. Это не механическое удаление первого слога любого аориста: нерегулярные основы учатся отдельно, πήγα → θα πάω.\\nСравните Θέλω να κλείσω ένα ραντεβού (хочу записаться) и Θα κλείσω ένα ραντεβού (сообщаю о плане). Отрицание зависит от конструкции: Δεν θα πάω; Θέλω να μην αργήσω. Частое Не могу выражается Δεν μπορώ να… — отрицание относится к возможности. Μην не заменяет δεν перед любым глаголом.\\nВ A1 такие просьбы могли быть готовыми формулами. Этот урок систематизирует выбор основы для нескольких частотных глаголов; полное видовое противопоставление и сложные случаи не считаются закрытыми. Если сотрудник сообщает ограничение, измените план: Μπορώ να έρθω την Τρίτη; Это учебная ролевая ситуация, не обещание доступности реальной услуги.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Θα γράψω ένα μήνυμα.", "Θέλω να κλείσω ένα ραντεβού.", "Δεν μπορώ να έρθω αύριο.", "Πρέπει να στείλουμε την αίτηση."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A2-002-I14", "U-A2-002-I15", "U-A2-002-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF7–8", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction A2", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A2-002-I05", "U-A2-002-I06"], "prerequisites": ["A2-G03", "A1-G12"], "reading_tasks": ["U-A2-002-I07", "U-A2-002-I08"], "transfer_task": "U-A2-002-I13", "writing_tasks": ["U-A2-002-I11"], "competency_ids": ["A2-G05", "A2-G06"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A2-002-I12"], "errors_taxonomy": ["VERB_ASPECT", "VERB_TENSE", "SYNTAX"], "guided_practice": ["U-A2-002-I02", "U-A2-002-I03", "U-A2-002-I04"], "listening_tasks": ["U-A2-002-I09", "U-A2-002-I10"], "learning_outcome": "Выразить единичный план через θα и совершенную основу", "vocabulary_items": [{"lemma": "κλείνω", "stress": "κλείνω", "example": "Θέλω να κλείσω ραντεβού.", "inflection": "έκλεισα; θα κλείσω", "meaning_ru": "записывать/закрывать", "collocations": ["κλείνω ραντεβού"]}, {"lemma": "έρχομαι", "stress": "έρχομαι", "example": "Μπορώ να έρθω την Τρίτη.", "inflection": "ήρθα; θα έρθω", "meaning_ru": "приходить", "collocations": ["έρχομαι την Τρίτη"]}, {"lemma": "αίτηση", "stress": "αίτηση", "example": "Θα στείλω την αίτηση.", "inflection": "η αίτηση, οι αιτήσεις", "meaning_ru": "заявление", "collocations": ["στέλνω αίτηση"]}, {"lemma": "ραντεβού", "stress": "ραντεβού", "example": "Το ραντεβού είναι αύριο.", "inflection": "το ραντεβού; неизменяемое", "meaning_ru": "встреча по записи", "collocations": ["κλείνω ραντεβού"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A2-002-I01"], "learning_objectives": ["Выразить единичный план через θα и совершенную основу", "Построить просьбу с να и отрицание с μην", "Изменить план после нового ограничения собеседника"], "microcompetency_ids": ["U-A2-002-MC01", "U-A2-002-MC02", "U-A2-002-MC03"], "primary_competencies": ["A2-G05", "A2-G06"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
