3129	unit	U-A2-003	3fd734ee13247fc8d2cf258e704aa7bf1c5dcb59b51f792e29dcdaf1a27037a2	core	{"unit_id": "U-A2-003", "content_hash": "3fd734ee13247fc8d2cf258e704aa7bf1c5dcb59b51f792e29dcdaf1a27037a2", "canonical_path": "GreekOS_Academic_Corpus/units/U-A2-003.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A2-003-RUBRIC"], "unit_id": "U-A2-003", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-A2-003-I02", "U-A2-003-I03", "U-A2-003-I04", "U-A2-003-I05", "U-A2-003-I06"], "reception": ["U-A2-003-I07", "U-A2-003-I08", "U-A2-003-I09", "U-A2-003-I10"], "retention": ["U-A2-003-I14", "U-A2-003-I15", "U-A2-003-I16"], "diagnostic": ["U-A2-003-I01"], "production": ["U-A2-003-I11", "U-A2-003-I12", "U-A2-003-I13"]}, "title_ru": "Кому принадлежит вещь: родительный", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Родительный помогает назвать владельца: το βιβλίο του φίλου, η τσάντα της φίλης, το δωμάτιο του παιδιού. Артикль владельца становится του/της/του. У мужского -ος в нашей модели родительный -ου: ο φίλος → του φίλου. У женского -η появляется -ς: η φίλη → της φίλης. У среднего παιδί — παιδιού с перемещением ударения. Не переносите эту модель автоматически на все существительные.\\nКороткие μου/σου/του/της после существительного тоже выражают принадлежность: το κινητό μου. Ударение и место важны; формы полноценного местоимения δικός вводятся в другом блоке. Вопрос Ποιανού είναι; может задаваться о владельце. В ответе Это телефон Марии: Είναι το κινητό της Μαρίας.\\nНе путайте владельца с предметом: в το κλειδί του γραφείου грамматический род του определяется словом γραφείο, а не κλειδί. Частотные объявления о потерянной вещи требуют сообщить описание и осторожно проверить владельца; в учебной роли не запрашиваются реальные банковские или паспортные данные.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Αυτό είναι το βιβλίο του φίλου μου.", "Η τσάντα της Μαρίας είναι εδώ.", "Το δωμάτιο του παιδιού είναι μικρό.", "Ποιανού είναι αυτό το κινητό;"], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A2-003-I14", "U-A2-003-I15", "U-A2-003-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF7–8", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction A2", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A2-003-I05", "U-A2-003-I06"], "prerequisites": ["A1-G01", "A1-G02"], "reading_tasks": ["U-A2-003-I07", "U-A2-003-I08"], "transfer_task": "U-A2-003-I13", "writing_tasks": ["U-A2-003-I11"], "competency_ids": ["A2-G01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A2-003-I12"], "errors_taxonomy": ["MORPHOLOGY_CASE", "ORTHOGRAPHY_ACCENT"], "guided_practice": ["U-A2-003-I02", "U-A2-003-I03", "U-A2-003-I04"], "listening_tasks": ["U-A2-003-I09", "U-A2-003-I10"], "learning_outcome": "Назвать владельца через родительный существительного", "vocabulary_items": [{"lemma": "κλειδί", "stress": "κλειδί", "example": "Βρήκα το κλειδί του σπιτιού.", "inflection": "το κλειδί, του κλειδιού", "meaning_ru": "ключ", "collocations": ["το κλειδί του σπιτιού"]}, {"lemma": "κινητό", "stress": "κινητό", "example": "Το κινητό μου είναι εδώ.", "inflection": "το κινητό, του κινητού", "meaning_ru": "мобильный телефон", "collocations": ["το κινητό μου"]}, {"lemma": "τσάντα", "stress": "τσάντα", "example": "Η τσάντα της Μαρίας είναι μπλε.", "inflection": "η τσάντα, της τσάντας", "meaning_ru": "сумка", "collocations": ["η τσάντα της Μαρίας"]}, {"lemma": "ποιανού", "stress": "ποιανού", "example": "Ποιανού είναι το βιβλίο;", "inflection": "вопросительная форма", "meaning_ru": "чей/кому принадлежит", "collocations": ["ποιανού είναι"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A2-003-I01"], "learning_objectives": ["Назвать владельца через родительный существительного", "Различить владельца и предмет в письменном и устном сообщении", "Уточнить принадлежность нового предмета в диалоге"], "microcompetency_ids": ["U-A2-003-MC01", "U-A2-003-MC02", "U-A2-003-MC03"], "primary_competencies": ["A2-G01"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3130	unit	U-A2-004	7339a54567e1c4b1e49ed71ad29f02e57775c6adddc2c0b85aab052b3890b314	core	{"unit_id": "U-A2-004", "content_hash": "7339a54567e1c4b1e49ed71ad29f02e57775c6adddc2c0b85aab052b3890b314", "canonical_path": "GreekOS_Academic_Corpus/units/U-A2-004.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A2-004-RUBRIC"], "unit_id": "U-A2-004", "version": "0.1.2", "sections": {"theory": "theory_ru", "practice": ["U-A2-004-I02", "U-A2-004-I03", "U-A2-004-I04", "U-A2-004-I05", "U-A2-004-I06"], "reception": ["U-A2-004-I07", "U-A2-004-I08", "U-A2-004-I09", "U-A2-004-I10"], "retention": ["U-A2-004-I14", "U-A2-004-I15", "U-A2-004-I16"], "diagnostic": ["U-A2-004-I01"], "production": ["U-A2-004-I11", "U-A2-004-I12", "U-A2-004-I13"]}, "title_ru": "Сравнить два варианта жилья", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Для базового сравнения используем πιο + прилагательное и από для второго объекта: Το δωμάτιο Α είναι πιο μεγάλο από το Β. После από существительное/местоимение оформляется как соответствующее дополнение; здесь работаем с названиями вариантов. Прилагательное согласуется с тем, что сравниваем: πιο μικρό δωμάτιο, πιο μικρή κουζίνα. Πιο не меняется.\\nПри равенстве возможна модель τόσο…όσο: Το Α είναι τόσο φωτεινό όσο το Β. Для A2 достаточно сначала понимать её и применять в ограниченном наборе; синтетические/нерегулярные сравнения и ограничения относятся к более позднему расширению. Самое дешёвое среди набора: το πιο φτηνό. Но «дешевле» не равняется «лучше» для любого человека.\\nЧтобы выбрать жильё, сравните одинаковые величины: месячная аренда с месячной арендой, время пути одним способом. Если в объявлении не указаны коммунальные расходы, не включайте их в доказанную итоговую цену. В учебном кейсе все суммы вымышлены. Отделяйте факт от предпочтения: Το Α είναι πιο φτηνό, αλλά προτιμώ το Β γιατί είναι κοντά στο μάθημα.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Το Α είναι πιο φτηνό από το Β.", "Η κουζίνα είναι πιο μικρή.", "Το δωμάτιο είναι τόσο φωτεινό όσο το άλλο.", "Προτιμώ το Β γιατί είναι κοντά στο μάθημα."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A2-004-I14", "U-A2-004-I15", "U-A2-004-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF7–8", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction A2", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A2-004-I05", "U-A2-004-I06"], "prerequisites": ["A1-G04"], "reading_tasks": ["U-A2-004-I07", "U-A2-004-I08"], "transfer_task": "U-A2-004-I13", "writing_tasks": ["U-A2-004-I11"], "competency_ids": ["A2-G09", "A2-R01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A2-004-I12"], "errors_taxonomy": ["GENDER_AGREEMENT", "COMPREHENSION", "CONTENT_OMISSION"], "guided_practice": ["U-A2-004-I02", "U-A2-004-I03", "U-A2-004-I04"], "listening_tasks": ["U-A2-004-I09", "U-A2-004-I10"], "remaining_scope": ["Нерегулярные сравнительные формы: отдельное продолжение, не освоены здесь"], "learning_outcome": "Сравнить жильё с πιο…από и понять изученный пример μεγαλύτερη", "vocabulary_items": [{"lemma": "φτηνός", "stress": "φτηνός", "example": "Το σπίτι είναι πιο φτηνό.", "inflection": "φτηνός, φτηνή, φτηνό", "meaning_ru": "дешёвый", "collocations": ["πιο φτηνό σπίτι"]}, {"lemma": "φωτεινός", "stress": "φωτεινός", "example": "Θέλω ένα φωτεινό δωμάτιο.", "inflection": "φωτεινός, φωτεινή, φωτεινό", "meaning_ru": "светлый", "collocations": ["φωτεινό δωμάτιο"]}, {"lemma": "ενοίκιο", "stress": "ενοίκιο", "example": "Το ενοίκιο είναι τετρακόσια ευρώ.", "inflection": "το ενοίκιο, τα ενοίκια", "meaning_ru": "аренда", "collocations": ["μηνιαίο ενοίκιο"]}, {"lemma": "προτιμώ", "stress": "προτιμώ", "example": "Προτιμώ το δεύτερο δωμάτιο.", "inflection": "προτιμώ, προτιμάς", "meaning_ru": "предпочитать", "collocations": ["προτιμώ το δεύτερο"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A2-004-I01"], "learning_objectives": ["Сравнить жильё с πιο…από и понять изученный пример μεγαλύτερη", "Извлечь цену и ограничения из объявления", "Обосновать выбор по двум заданным потребностям"], "microcompetency_ids": ["U-A2-004-MC01", "U-A2-004-MC02", "U-A2-004-MC03"], "primary_competencies": ["A2-G09", "A2-R01"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
