3131	unit	U-A2-005	449dfc69cfd8fb9d5eb214aa2c8da2ce7c556e0f1517d9cbe7dce531cc9b4856	core	{"unit_id": "U-A2-005", "content_hash": "449dfc69cfd8fb9d5eb214aa2c8da2ce7c556e0f1517d9cbe7dce531cc9b4856", "canonical_path": "GreekOS_Academic_Corpus/units/U-A2-005.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A2-005-RUBRIC"], "unit_id": "U-A2-005", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-A2-005-I02", "U-A2-005-I03", "U-A2-005-I04", "U-A2-005-I05", "U-A2-005-I06"], "reception": ["U-A2-005-I07", "U-A2-005-I08", "U-A2-005-I09", "U-A2-005-I10"], "retention": ["U-A2-005-I14", "U-A2-005-I15", "U-A2-005-I16"], "diagnostic": ["U-A2-005-I01"], "production": ["U-A2-005-I11", "U-A2-005-I12", "U-A2-005-I13"]}, "title_ru": "Объектные клитики и короткие инструкции", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Если предмет уже назван, его можно заменить безударным местоимением: Βλέπω τον φάκελο → Τον βλέπω; βλέπω την τσάντα → τη βλέπω; βλέπω το κουτί → το βλέπω. Во множественном τους φακέλους → τους, τις τσάντες → τις, τα κουτιά → τα. Выбирайте род и число греческого существительного. В Την ξέρω клитика может обозначать и человека.\\nПеред обычной личной формой местоимение ставится до глагола: Το ανοίγω. После положительного императива — после: Άνοιξέ το. Дополнительное ударение в Άνοιξέ το связано с присоединением безударного местоимения к форме с ударением на третьем слоге от конца; оно не произвольное украшение. В Γράψ’ το сокращённая форма имеет другую графику. Для начальной практики используем Άνοιξέ το / Κλείσ’ το и πλήρη Άνοιξε την πόρτα.\\nОтрицательная инструкция отличается: Μην το ανοίξεις. Здесь местоимение опять перед глаголом. Не используйте *μην άνοιξε как автоматический отрицательный вариант императива. Вежливая альтернатива Μπορείτε να το ανοίξετε; полезна с незнакомым взрослым, а Άνοιξέ το может быть естественным в близком общении или инструкции. Регистр оценивается по ситуации, а не по наличию одного слова παρακαλώ.\\nПеред заменой проверьте, нет ли двух возможных предметов одного рода. Если есть, повторите существительное. Этот урок вводит одиночный прямой объект; двойные клитики «кому+что» изучаются отдельно.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Βλέπω την τσάντα. Τη βλέπω.", "Άνοιξε το παράθυρο. Άνοιξέ το.", "Μην το ανοίξεις ακόμη.", "Μπορείτε να το κλείσετε;"], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A2-005-I14", "U-A2-005-I15", "U-A2-005-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF7–8", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction A2", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A2-005-I05", "U-A2-005-I06"], "prerequisites": ["A1-G02", "A2-G06"], "reading_tasks": ["U-A2-005-I07", "U-A2-005-I08"], "transfer_task": "U-A2-005-I13", "writing_tasks": ["U-A2-005-I11"], "competency_ids": ["A2-G02", "A2-G07"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A2-005-I12"], "errors_taxonomy": ["CLITIC_POSITION", "IMPERATIVE", "ACCENTUATION"], "guided_practice": ["U-A2-005-I02", "U-A2-005-I03", "U-A2-005-I04"], "listening_tasks": ["U-A2-005-I09", "U-A2-005-I10"], "learning_outcome": "Заменить прямой объект одиночной клитикой", "vocabulary_items": [{"lemma": "ανοίγω", "stress": "ανοίγω", "example": "Άνοιξέ το, παρακαλώ.", "inflection": "άνοιξα; άνοιξε; να ανοίξω", "meaning_ru": "открывать", "collocations": ["ανοίγω το παράθυρο"]}, {"lemma": "κλείνω", "stress": "κλείνω", "example": "Μπορείτε να την κλείσετε;", "inflection": "έκλεισα; κλείσε; να κλείσω", "meaning_ru": "закрывать", "collocations": ["κλείνω την πόρτα"]}, {"lemma": "φέρνω", "stress": "φέρνω", "example": "Φέρε τα βιβλία.", "inflection": "έφερα; φέρε; να φέρω", "meaning_ru": "приносить", "collocations": ["φέρνω τα βιβλία"]}, {"lemma": "παράθυρο", "stress": "παράθυρο", "example": "Το παράθυρο είναι κλειστό.", "inflection": "το παράθυρο, τα παράθυρα", "meaning_ru": "окно", "collocations": ["ανοίγω το παράθυρο"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A2-005-I01"], "learning_objectives": ["Заменить прямой объект одиночной клитикой", "Различить порядок клитики в утверждении, приказе и запрете", "Дать новые инструкции с понятным объектом"], "microcompetency_ids": ["U-A2-005-MC01", "U-A2-005-MC02", "U-A2-005-MC03"], "primary_competencies": ["A2-G02", "A2-G07"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
