3132	unit	U-A2-006	a2b8b91353d217acc371435c480c20fb6276640cc7660426155a22161b0228f1	core	{"unit_id": "U-A2-006", "content_hash": "a2b8b91353d217acc371435c480c20fb6276640cc7660426155a22161b0228f1", "canonical_path": "GreekOS_Academic_Corpus/units/U-A2-006.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A2-006-RUBRIC"], "unit_id": "U-A2-006", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-A2-006-I02", "U-A2-006-I03", "U-A2-006-I04", "U-A2-006-I05", "U-A2-006-I06", "U-A2-006-I07", "U-A2-006-I08", "U-A2-006-I19", "U-A2-006-I20"], "reception": ["U-A2-006-I09", "U-A2-006-I10", "U-A2-006-I11", "U-A2-006-I12"], "retention": ["U-A2-006-I16", "U-A2-006-I17", "U-A2-006-I18", "U-A2-006-I22"], "diagnostic": ["U-A2-006-I01"], "production": ["U-A2-006-I13", "U-A2-006-I14", "U-A2-006-I15", "U-A2-006-I21"]}, "title_ru": "Настоящее: εργάζομαι и έρχομαι", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Форма на -μαι относится к медиопассивной морфологии, но не означает автоматически «со мной делают действие». Εργάζομαι означает «работаю», έρχομαι — «прихожу/иду сюда». В Εργάζομαι σε ένα ξενοδοχείο человек работает сам; не нужно придумывать скрытого исполнителя. Различайте внешний вид формы и значение целого глагола.\\n\\nВыучите две парадигмы по лицам: εγώ εργάζομαι, εσύ εργάζεσαι, αυτός/αυτή εργάζεται, εμείς εργαζόμαστε, εσείς εργάζεστε, αυτοί/αυτές εργάζονται. Для έρχομαι: έρχομαι, έρχεσαι, έρχεται, ερχόμαστε, έρχεστε, έρχονται. Обратите внимание на ударение в εργαζόμαστε и ερχόμαστε. Не выводите все шесть форм механически из русского «мы/вы» и не добавляйте активное -ουμε к основе εργάζ-.\\n\\nЛичное местоимение часто не требуется: Εργάζομαι εδώ уже означает «я». Если называете двух людей, нужен множественный глагол: Η Άννα και ο Πέτρος εργάζονται μαζί. При вежливом обращении к одному человеку используйте форму εσείς: Πότε έρχεστε; Это не свидетельство того, что собеседников несколько.\\n\\nНастоящее описывает обычное расписание: Έρχομαι κάθε Τρίτη. С указанием времени оно может выражать договорённость: Έρχομαι αύριο στις δέκα. Контекст определяет, говорим ли о привычке или ближайшем плане. В этом уроке не требуется строить прошедшие формы этих глаголов: они изучаются отдельно.\\n\\nОтрицание стоит перед личной формой: Δεν εργάζομαι την Κυριακή. Вопрос часто сохраняет порядок слов: Έρχεσαι αύριο; В ответе не повторяйте вопросительную форму: Ναι, έρχομαι. Для места работы используйте σε: σε ένα γραφείο, στο γραφείο. Движение έρχομαι связано с приходом к говорящему/собеседнику или согласованной точке: Έρχομαι στο σπίτι σου. Πηγαίνω обычно направляет движение к другой точке; выбор зависит от перспективы, поэтому это не абсолютное географическое правило.\\n\\nПри самостоятельной речи назовите человека, место и время, затем проверьте лицо глагола. Если партнёр меняет время встречи, дайте новый ответ, а не воспроизводите выученный монолог. Успех — понятное согласование реального расписания, а не только шесть форм подряд.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Εργάζομαι σε ένα μικρό ξενοδοχείο.", "Η αδελφή μου εργάζεται στο κέντρο.", "Εμείς εργαζόμαστε μαζί.", "Εσείς εργάζεστε σήμερα;", "Τα παιδιά έρχονται στις έξι.", "Έρχεσαι σπίτι μου; — Ναι, έρχομαι."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A2-006-I16", "U-A2-006-I17", "U-A2-006-I18", "U-A2-006-I22"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Историческая уровневая тематическая карта; размещение требует эксперта", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Reception, production, interaction; author mapping, not official cut score", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "§6: φωνές и личные формы настоящего", "source_id": "N405", "checked_on": "2026-10-14", "claim_scope": "Грамматическое/фонетическое правило; задания оригинальные", "evidence_type": "OFFICIAL_SCHOOL_GRAMMAR_NOT_AUTH_SYLLABUS"}], "evidence_map": [{"delayed": ["U-A2-006-I16", "U-A2-006-I22"], "transfer": ["U-A2-006-I13", "U-A2-006-I15"], "source_ids": ["V201", "W322", "N405"], "prerequisites": ["A1-G06"], "mastery_decision": {"rule": "Целевая связь/форма верна в контролируемом задании; самостоятельное применение в новом сообщении и переносе; повтор без подсказок через 7/14/28 дней. Не усреднять критическую смысловую ошибку.", "status": "NOT_ASSESSED", "pronunciation_gate": "NOT_INFERRED_FROM_TRANSCRIPT"}, "microcompetency_id": "U-A2-006-MC01", "observable_outcome": "Выбрать личную форму εργάζομαι / έρχομαι для шести лиц.", "evidence_is_collected": false, "independent_production": ["U-A2-006-I07", "U-A2-006-I19"], "recognition_or_controlled": ["U-A2-006-I01", "U-A2-006-I02", "U-A2-006-I03", "U-A2-006-I19"], "success_criteria_specific": "Выбрать личную форму εργάζομαι / έρχομαι для шести лиц."}, {"delayed": ["U-A2-006-I17", "U-A2-006-I22"], "transfer": ["U-A2-006-I13", "U-A2-006-I15"], "source_ids": ["V201", "W322", "N405"], "prerequisites": ["A