3133	unit	U-A2-007	bf4400bc00daefb9bb65ace468d91ceffb41d89fd20b43b5df01764742a0ab0e	core	{"unit_id": "U-A2-007", "content_hash": "bf4400bc00daefb9bb65ace468d91ceffb41d89fd20b43b5df01764742a0ab0e", "canonical_path": "GreekOS_Academic_Corpus/units/U-A2-007.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "DRAFT", "rubrics": ["U-A2-007-RUBRIC"], "unit_id": "U-A2-007", "version": "0.1.3", "sections": {"theory": "theory_ru", "practice": ["U-A2-007-I02", "U-A2-007-I03", "U-A2-007-I04", "U-A2-007-I05", "U-A2-007-I06", "U-A2-007-I07", "U-A2-007-I08", "U-A2-007-I09"], "reception": ["U-A2-007-I10", "U-A2-007-I11", "U-A2-007-I12", "U-A2-007-I13"], "retention": ["U-A2-007-I17", "U-A2-007-I18", "U-A2-007-I19"], "diagnostic": ["U-A2-007-I01"], "production": ["U-A2-007-I14", "U-A2-007-I15", "U-A2-007-I16"]}, "title_ru": "Что сообщают, когда, почему и при каком условии", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "После λέει и νομίζω передаём содержание мысли: Λέει ότι εργάζεται / Λέει πως εργάζεται. Здесь оба союза допустимы. Πως без ударения означает «что»; πώς с ударением — «как». Ότι не равно ό,τι («всё, что»), которое пока узнаём.\\nКогда нужен ответ «когда?», используйте όταν. Для причины — επειδή, для ещё неизвестного условия — αν. Όταν έχω χρόνο, διαβάζω описывает обычную ситуацию; Επειδή έχω χρόνο, διαβάζω объясняет выбор; Αν έχω χρόνο, θα διαβάσω ставит результат в зависимость от условия. Слова έχω χρόνο сами не определяют союз: выбор задаёт ваш смысл.\\nДля одного ожидаемого завершения перед следующим действием берём Όταν τελειώσω, θα τηλεφωνήσω. Сравните Αν τελειώσω νωρίς, θα τηλεφωνήσω: здесь условие не гарантировано. Это учебная модель, а не запрет любого θα возле όταν/αν. Прочитайте сообщение, обозначьте его смысл, закройте текст и поменяйте условие.\\nЗависимая часть может стоять первой: Επειδή βρέχει, μένουμε μέσα, или после решения: Μένουμε μέσα επειδή βρέχει. При пересказе меняйте лицо: Άννα: «Εργάζομαι» → Η Άννα λέει ότι εργάζεται. Не сдвигайте все времена автоматически по модели английского. Сначала установите, кто сообщает и о ком. В чтении встретится αν после δεν ξέρει: это «ли», косвенный вопрос, а не условие. Основная продуктивная цель здесь — простые условные планы. Урок готовит U-B1-008, но ещё не доказывает владение длинным сложным высказыванием.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Η Μαρία λέει ότι μένει εδώ.", "Νομίζω πως το μάθημα αρχίζει στις έξι.", "Όταν γυρίζω σπίτι, διαβάζω.", "Μένουμε μέσα επειδή βρέχει.", "Αν έχω χρόνο, θα έρθω.", "Όταν τελειώσω τη δουλειά, θα σου τηλεφωνήσω."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "delivery": "Use concrete D7 and D28 scenarios in microcompetencies.json alongside closed retrieval; no observed mastery yet", "item_ids": ["U-A2-007-I17", "U-A2-007-I18", "U-A2-007-I19"], "hypothesis_not_official": true, "independent_followup_micro_ids": ["U-A2-007-MC01", "U-A2-007-MC02", "U-A2-007-MC03"]}, "source_refs": [{"anchor": "A2-G11 historical curricular theme only", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "A2 interaction/production, project mapping", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "§5.2 ειδικές, αιτιολογικές, υποθετικές, χρονικές", "source_id": "N404", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}], "active_recall": ["U-A2-007-I08", "U-A2-007-I09"], "prerequisites": ["A1-G11", "A2-G05", "A2-G06", "A2-G08"], "reading_tasks": ["U-A2-007-I10", "U-A2-007-I11"], "transfer_task": "U-A2-007-I16", "writing_tasks": ["U-A2-007-I14"], "competency_ids": ["A2-G11"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "reconstruction": {"date": "2026-10-15", "basis": "Saved authoring text and review findings in conversation; reconstructed after workspace cleanup; byte identity to lost drafts not claimed", "previous_unsaved_version": "0.1.0"}, "speaking_tasks": ["U-A2-007-I15"], "errors_taxonomy": ["CLAUSE_RELATION", "CONTENT_VS_MANNER_ACCENT", "REPORTED_PERSON", "CONDITIONAL_CERTAINTY"], "guided_practice": ["U-A2-007-I02", "U-A2-007-I03", "U-A2-007-I04", "U-A2-007-I05", "U-A2-007-I06", "U-A2-007-I07"], "listening_tasks": ["U-A2-007-I12", "U-A2-007-I13"], "learning_outcome": "Передать сообщение с ότι/πως и изменить лицо", "mastery_contract": {"audio": "Не оценивается без аудио", "unaided": "Две самостоятельные реплики без модели", "observed": false, "transfer": "Все условия новой ситуации; целевая форма=2, другие критерии≥1", "retention": "D7/D14/D28 без подсказок плюс новая свободная реплика", "controlled": "≥80% целевых форм; смысловая ошибка требует повторного обучения"}, "vocabulary_items": [{"lemma": "τελειώνω", "stress": "τελειώνω", "example": "Όταν τελειώσω, θα έρθω.", "inflection": "τελείωσα, θα τελειώσω", "meaning_ru": "заканчивать", "collocations": ["τελειώνω τη δουλειά"]}, {"lemma": "βρέχει", "stress": "βρέχει", "example": "Μένω μέσα επειδή βρέχει.", "infl