3134	unit	U-A2-008	7dfc8b22acc765b273212c2b8fca1b0c1e79005206f47b20f3c938becc33b7a1	core	{"unit_id": "U-A2-008", "content_hash": "7dfc8b22acc765b273212c2b8fca1b0c1e79005206f47b20f3c938becc33b7a1", "canonical_path": "GreekOS_Academic_Corpus/units/U-A2-008.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "DRAFT", "rubrics": ["U-A2-008-RUBRIC"], "unit_id": "U-A2-008", "version": "0.1.2", "sections": {"theory": "theory_ru", "practice": ["U-A2-008-I02", "U-A2-008-I03", "U-A2-008-I04", "U-A2-008-I05", "U-A2-008-I06", "U-A2-008-I07", "U-A2-008-I08", "U-A2-008-I09"], "reception": ["U-A2-008-I10", "U-A2-008-I11", "U-A2-008-I12", "U-A2-008-I13"], "retention": ["U-A2-008-I17", "U-A2-008-I18", "U-A2-008-I19"], "diagnostic": ["U-A2-008-I01"], "production": ["U-A2-008-I14", "U-A2-008-I15", "U-A2-008-I16"]}, "title_ru": "Прошлое: фон, привычка и событие целиком", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Παρατατικός показывает процесс или привычную ситуацию: Διάβαζα όταν ήρθε η Άννα. Αόριστος представляет событие целиком: Διάβασα το μήνυμα και απάντησα. Это не «долго — имперфект»: Δούλεψα όλη μέρα охватывает целый длительный день. Повторение тоже можно представить итогом: Πήγα τρεις φορές. Временное слово само по себе не выбирает форму.\\nРяд γράφω: έγραφα, έγραφες, έγραφε, γράφαμε, γράφατε, έγραφαν. Сравните έγραψα, έγραψες, έγραψε, γράψαμε, γράψατε, έγραψαν. В единственном ударение поддерживает έ-, а в γράφαμε оно не нужно. Διαβάζω: διάβαζα, διάβαζες, διάβαζε, διαβάζαμε, διαβάζατε, διάβαζαν; аорист начинается διάβασα. Δουλεύω: δούλευα/δούλεψα. Не все аористы образуются заменой буквы: βλέπω — έβλεπα/είδα, πηγαίνω — πήγαινα/πήγα. Состояния выражаем ήμουν, είχα, не придумываем искусственный аорист.\\nДля рассказа спросите: что уже происходило, что случилось, что было потом? Фон διάβαζα, событие χτύπησε το τηλέφωνο, следующее действие απάντησα. Привычку помещаем в период: Όταν ήμουν παιδί, πήγαινα συχνά στη θάλασσα. В закрытом задании ракурс указан. В свободной речи допустимый вариант оценивается в контексте, а не по механическому правилу о длительности.\\nПрочитайте историю, выделите фон и события разными словами, закройте её и расскажите другой случай. Проверьте лицо, основу и ударение. Если форма верна, но слушатель не понимает, что прервало процесс, измените порядок рассказа. Повторите с новым событием через неделю.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Έγραφα ένα μήνυμα όταν ήρθε η Άννα.", "Έγραψα το μήνυμα και έκλεισα τον υπολογιστή.", "Κάθε πρωί πήγαινα με τα πόδια.", "Χτες πήγα τρεις φορές στο γραφείο.", "Δούλεψα όλη μέρα και μετά ξεκουράστηκα.", "Ήμουν στο σπίτι και είχα χρόνο."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "delivery": "Use concrete D7 and D28 scenarios in microcompetencies.json alongside closed retrieval; no observed mastery yet", "item_ids": ["U-A2-008-I17", "U-A2-008-I18", "U-A2-008-I19"], "hypothesis_not_official": true, "independent_followup_micro_ids": ["U-A2-008-MC01", "U-A2-008-MC02", "U-A2-008-MC03"]}, "source_refs": [{"anchor": "A2-G04 historical curricular theme only", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "A2 interaction/production, project mapping", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "§6.2 ποιόν ενέργειας; κλίση λύνω; αύξηση", "source_id": "N405", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}], "active_recall": ["U-A2-008-I08", "U-A2-008-I09"], "prerequisites": ["A2-G03", "A1-G06"], "reading_tasks": ["U-A2-008-I10", "U-A2-008-I11"], "transfer_task": "U-A2-008-I16", "writing_tasks": ["U-A2-008-I14"], "competency_ids": ["A2-G04"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "reconstruction": {"date": "2026-10-15", "basis": "Saved authoring text and review findings in conversation; reconstructed after workspace cleanup; byte identity to lost drafts not claimed", "previous_unsaved_version": "0.1.0"}, "speaking_tasks": ["U-A2-008-I15"], "errors_taxonomy": ["ASPECT_NOT_DURATION", "AUGMENT_STRESS", "IRREGULAR_PAST", "BACKGROUND_EVENT"], "guided_practice": ["U-A2-008-I02", "U-A2-008-I03", "U-A2-008-I04", "U-A2-008-I05", "U-A2-008-I06", "U-A2-008-I07"], "listening_tasks": ["U-A2-008-I12", "U-A2-008-I13"], "learning_outcome": "Образовать изученные имперфектные и аористные формы", "mastery_contract": {"audio": "Не оценивается без аудио", "unaided": "Две самостоятельные реплики без модели", "observed": false, "transfer": "Все условия новой ситуации; целевая форма=2, другие критерии≥1", "retention": "D7/D14/D28 без подсказок плюс новая свободная реплика", "controlled": "≥80% целевых форм; смысловая ошибка требует повторного обучения"}, "vocabulary_items": [{"lemma": "γράφω", "stress": "γράφω", "example": "Έγραφα όταν ήρθες.", "inflection": "έγραφα / έγραψα", "meaning_ru": "писать", "collocations": ["γράφω μήνυμα"]}, {"lemma": "πηγαίνω", "stress": "πηγαίνω", "example": "Πήγαινα συχνά στη θάλασσα.", "inflection": "πήγαινα / πήγα", "meaning_ru": "ходить", "collocations": ["πηγαίνω στη θάλασσα"]}, {"lemma": "χτυπώ", "stress": "χτυπώ", "example": "Χτύπησε το τηλέφωνο.", "inflection": "χτυπούσα / χτύπησα", "meaning_ru": "звонить", "collocations": ["χτυπά το τηλέφωνο"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A2-008-I01"], "learning_objectives": ["Образовать изученные имперфектные и аористные формы", "Выбрать процесс/привычку или событие целиком", "Рассказать новый случай: фон, событие, результат"], "microcompetency_ids": ["U-A2-008-MC01", "U-A2-008-MC02", "U-A2-008-MC03"], "primary_competencies": ["A2-G04"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
