441	source_claim	CP08-INHERITED-U-A1-009-I10-03	72f5a756d247a2e80b22e9c87e5b7d19fbde2a82296556e01270bc57c726fb57	\N	{"record": {"claim": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A1-009-I10-03", "item_ids": ["U-A1-009-I10"], "source_id": "N404", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A1-009-I10.json", "sha256": "a24dcf1049a7f459c6803e88f83d02f74b379592947ab511c007b7877f836a16"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "§5.1 συμπλεκτικοί/αντιθετικοί; §5.2 αιτιολογικές", "source_id": "N404", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}}, "claim_id": "CP08-INHERITED-U-A1-009-I10-03", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3135	unit	U-A2-009	5c8d530197c3ebb9f56a3c3615404e49c96fbed0e3744cb3d33044d54dc16082	core	{"unit_id": "U-A2-009", "content_hash": "5c8d530197c3ebb9f56a3c3615404e49c96fbed0e3744cb3d33044d54dc16082", "canonical_path": "GreekOS_Academic_Corpus/units/U-A2-009.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A2-009-RUBRIC"], "unit_id": "U-A2-009", "version": "0.1.2", "title_ru": "Кто-нибудь, никто и ничего: искать информацию без ложного отрицания", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Сначала восстановите известные существительные и отрицание δεν: ο φίλος, η φίλη, το βιβλίο; Δεν έχω βιβλίο. Неопределённое местоимение нужно, когда имя человека или название вещи неизвестно либо неважно. Κάποιος, κάποια, κάποιο согласуются с существительным: κάποια φίλη, κάποιο βιβλίο. Без существительного κάποιος обычно указывает на человека. Винительный мужского: βλέπω κάποιον; женского κάποια, среднего κάποιο. Во множественном: κάποιοι φίλοι, κάποιες φίλες, κάποια βιβλία; вижу людей — βλέπω κάποιους φίλους. Κάτι не изменяется и обозначает не названную вещь: Θέλω κάτι για το παιδί. Μερικοί, μερικές, μερικά — некоторое количество во множественном: μερικά εισιτήρια.\\nΚανείς/κανένας, καμία/καμιά, κανένα не всегда переводятся как «никто». В вопросе Έχεις κανένα μολύβι; спрашивают, есть ли хоть какой-нибудь карандаш. В отрицательном сообщении Δεν έχω κανένα μολύβι; отрицают наличие любого карандаша. Сравните: Есть кто-нибудь? — Είναι κανείς εδώ; Никого нет — Δεν είναι κανείς εδώ. Если отрицательное подлежащее стоит первым, δεν сохраняется: Κανείς δεν ξέρει. Два отрицательных элемента здесь выражают одно отрицательное содержание, а не положительный результат. Для полного отрицательного предложения в этом уроке требуется δεν; краткий ответ на «Ποιος;» может быть Κανείς.\\nΚανείς — форма подлежащего; после вижу/жду нужен винительный κανέναν: Δεν περιμένω κανέναν. Τίποτα/τίποτε не изменяются: Δεν θέλω τίποτα. Но Θέλεις τίποτα; — предложение чего-нибудь, а не вопрос «хочешь ничего?». Κάθε сопровождает существительное единственного числа: κάθε μέρα. Καθένας означает каждого отдельно: Ο καθένας έχει ένα κλειδί. Это расширение для узнавания; основной контроль — κάποιος, κάτι, κανείς и τίποτα.\\nВ общении сначала спросите о наличии, затем уточните объект, примите отрицательный ответ и предложите другой вариант. Не заменяйте «не все» на «никто»: это разные сведения. Закройте примеры и сообщите два новых факта о своей учебной группе, затем проверьте лицо/предмет, род/падеж и наличие δεν. Вопросительная интонация должна проверяться только по реальной записи, которой пока нет.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Έχεις κανένα εισιτήριο;", "Δεν έχω κανένα εισιτήριο.", "Κάποια φίλη μου μένει εδώ.", "Δεν περιμένω κανέναν.", "Θέλεις τίποτα;", "Κανείς δεν ξέρει την ώρα."], "review_plan": {"days": [7, 14, 28], "rule": "Новый ответ без модели; после подсказки сохранять assisted, повторить самостоятельно с новыми данными.", "item_ids": ["U-A2-009-I17", "U-A2-009-I18", "U-A2-009-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "§5.6 α; §5.8 β–στ, η–θ", "source_id": "CP06-A2-S001", "checked_on": "2026-10-18", "claim_scope": "Indefinite forms and polarity; invariant relative που. New actual inspection of previously uninspected sections.", "evidence_type": "OFFICIAL_SCHOOL_GRAMMAR_NOT_CEFR"}], "active_recall": ["U-A2-009-I08", "U-A2-009-I09"], "prerequisites": ["A1-G08", "A2-G01"], "reading_tasks": ["U-A2-009-I10", "U-A2-009-I11"], "transfer_task": "U-A2-009-I16", "writing_tasks": ["U-A2-009-I14"], "competency_ids": ["A2-G10"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; no observed learner mastery", "speaking_tasks": ["U-A2-009-I15"], "errors_taxonomy": ["FACT_SUBSTITUTION", "LEXICAL_ROLE_CONFUSION", "REGISTER_MISMATCH", "UNSUPPORTED_INFERENCE", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A2-009-I02", "U-A2-009-I03", "U-A2-009-I04", "U-A2-009-I05", "U-A2-009-I06", "U-A2-009-I07"], "listening_tasks": ["U-A2-009-I12", "U-A2-009-I13"], "reading_text_el": "Σήμερα η Ελένη οργανώνει μια μικρή συνάντηση στη βιβλιοθήκη. Μερικοί φίλοι έχουν ήδη έρθει. Κάποιος άφησε μια μπλε τσάντα στην είσοδο, αλλά κανείς δεν ξέρει ποιανού είναι. Η Ελένη δεν ανοίγει την τσάντα. Ρωτά την υπάλληλο και περιμένει δίπλα στην είσοδο. Δεν υπάρχει κανένα όνομα πάνω στην τσάντα. Σε λίγο μια κοπέλα έρχεται και περιγράφει την τσάντα της. Η υπάλληλος της ζητά να περιμένει για έναν έλεγχο.", "learning_outcome": "Выбрать лицо, предмет и согласованную форму неопределённого местоимения", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "transfer": "I16 + новая самостоятельная речь на I17/I19 по item-specific anchors", "controlled": "≥80% закрытых ответов, затем исправление всех смысловых ошибок"}, "vocabulary_items": [{"lemma": "κάποιος", "stress": "κάποιος", "example": "Κάποιος φίλος τηλεφώνησε.", "inflection": "κάποια, κάποιο; κάποιον", "meaning_ru": "некий; кто-то", "collocations": ["κάποιος φίλος"]}, {"lemma": "κάτι", "stress": "κάτι", "example": "Θέλω κάτι μικρό.", "inflection": "άκλιτο", "meaning_ru": "что-то", "collocations": ["θέλω κάτι"]}, {"lemma": "κανείς", "stress": "κανείς", "example": "Δεν ξέρω κανέναν εδώ.", "inflection": "κανένας, καμία, κανένα; κανέναν", "meaning_ru": "кто-нибудь / никто по контексту", "collocations": ["δεν ξέρω κανέναν"]}, {"lemma": "τίποτα", "stress": "τίποτα", "example": "Δεν έχω τίποτα μαζί μου.", "inflection": "τίποτε; άκλιτο", "meaning_ru": "что-нибудь / ничего по контексту", "collocations": ["δεν έχω τίποτα"]}, {"lemma": "μερικοί", "stress": "μερικοί", "example": "Έχω μερικά βιβλία.", "inflection": "μερικές, μερικά", "meaning_ru": "некоторые; несколько", "collocations": ["μερικά βιβλία"]}, {"lemma": "καθένας", "stress": "καθένας", "example": "Ο καθένας έχει μια θέση.", "inflection": "καθεμία, καθένα", "meaning_ru": "каждый отдельно", "collocations": ["ο καθένας"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A2-009-I01"], "learning_objectives": ["Выбрать лицо, предмет и согласованную форму неопределённого местоимения", "Различить вопрос о наличии и отрицательное сообщение", "Самостоятельно уточнить наличие людей, вещей и свободного времени"], "microcompetency_ids": ["U-A2-009-MC01", "U-A2-009-MC02", "U-A2-009-MC03"], "prerequisite_support": {"A1-G08": {"key": "Δεν έχω βιβλίο.", "probe": "Отрицайте Έχω βιβλίο.", "unit_id": "U-A1-010", "on_failure": "Повторить δεν в U-A1-010, затем новая фраза без модели."}, "A2-G01": {"key": "Анны / της Άννας", "probe": "Выберите владельца: Είναι το βιβλίο της Άννας. Чья книга?", "unit_id": "U-A2-003", "on_failure": "Повторить родительный принадлежности U-A2-003; затем новая именная группа."}}, "primary_competencies": ["A2-G10"], "learner_data_included": false, "estimated_active_minutes": 65}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
