447	source_claim	CP08-INHERITED-U-A1-009-I12-03	634aecaa602064e52c9de5f3d6c61ec40014b30ea042cdd096a0872219caf27c	\N	{"record": {"claim": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A1-009-I12-03", "item_ids": ["U-A1-009-I12"], "source_id": "N404", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A1-009-I12.json", "sha256": "c2c9fde8795f85c968c7342d0ed56a44bd9c483e2769163b70db18c91c92422f"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "§5.1 συμπλεκτικοί/αντιθετικοί; §5.2 αιτιολογικές", "source_id": "N404", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}}, "claim_id": "CP08-INHERITED-U-A1-009-I12-03", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3136	unit	U-A2-010	ae479d71c4625dd2078ae5673b30d4ebcc8bfb1c8eeb9a9f632fa2019b0e4ab3	core	{"unit_id": "U-A2-010", "content_hash": "ae479d71c4625dd2078ae5673b30d4ebcc8bfb1c8eeb9a9f632fa2019b0e4ab3", "canonical_path": "GreekOS_Academic_Corpus/units/U-A2-010.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A2-010-RUBRIC"], "unit_id": "U-A2-010", "version": "0.1.3", "title_ru": "Как часто, насколько и какой именно: наречия и που", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Проверьте предпосылки: прилагательное согласуется с существительным; в рассказе различаются привычный фон и единичное событие. Наречие не меняется вслед за родом: πολύ καλός, πολύ καλή, πολύ καλά. Спрашивайте, что именно оно уточняет. Συχνά и συνήθως описывают регулярность; σήμερα и χτες помещают событие во времени; πολύ и αρκετά показывают степень. Одно слово не выбирает автоматически глагольное время: Χτες δούλευα όταν τηλεφώνησες; Χτες δούλεψα τρεις ώρες.\\nШкала частоты полезна как смысловая опора, но не как точные проценты: πάντα — всегда, συνήθως — обычно, συχνά — часто, μερικές φορές — иногда, σπάνια — редко, ποτέ с отрицанием — никогда. Συνήθως πίνω τσάι не значит «каждый раз». Для ποτέ различайте утверждаемое отсутствие опыта и вопросы; здесь упражняемся в Δεν αργώ ποτέ — никогда не опаздываю. Время: τώρα, σήμερα, χτες/χθες, αύριο, πρώτα, μετά, νωρίς, αργά. Степень: λίγο, αρκετά, πολύ; «в очень маленькой комнате» — σε πολύ μικρό δωμάτιο. Наречие πολύ не получает женское окончание перед καλή.\\nΠου после существительного добавляет характеристику: Η γυναίκα που δουλεύει εδώ είναι η Άννα. Το βιβλίο που διαβάζω είναι μικρό. Που неизменно; оно может связывать определяемое слово с ролью подлежащего или дополнения в придаточной части. Не добавляйте механически второе существительное: το βιβλίο που διαβάζω, а не повторение το βιβλίο в конце. В этом уроке выбирайте простые связи без цепочки из двух возможных предшественников. Το σπίτι που είναι δίπλα στο πάρκο ясно; сложные двусмысленные цепочки требуют перефразирования. Вопросительное πού означает «где?» и имеет ударение; относительное που пишется без него.\\nСоединяйте два навыка по смыслу: Συνήθως πηγαίνω στο καφέ που είναι κοντά στη σχολή. Сначала назовите привычку, затем уточните место, затем добавьте исключение со временем. Прочитайте свою реплику собеседнику: понятно ли, что происходит часто и к какому слову относится που? На D7 и D28 меняется место и распорядок, а не повторяется заученная история.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Συνήθως τρώω στο σπίτι.", "Δεν αργώ ποτέ.", "Η αίθουσα είναι πολύ μικρή.", "Αύριο θα έρθω νωρίς.", "Το βιβλίο που διαβάζω είναι ενδιαφέρον.", "Η φίλη που μένει δίπλα δουλεύει εδώ."], "review_plan": {"days": [7, 14, 28], "rule": "Новый ответ без модели; после подсказки сохранять assisted, повторить самостоятельно с новыми данными.", "item_ids": ["U-A2-010-I17", "U-A2-010-I18", "U-A2-010-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "§5.6 α; §5.8 β–στ, η–θ", "source_id": "CP06-A2-S001", "checked_on": "2026-10-18", "claim_scope": "Indefinite forms and polarity; invariant relative που. New actual inspection of previously uninspected sections.", "evidence_type": "OFFICIAL_SCHOOL_GRAMMAR_NOT_CEFR"}, {"anchor": "§7.1 temporal and quantitative classes; §7.2 α", "source_id": "CP06-A2-S002", "checked_on": "2026-10-18", "claim_scope": "Adverb invariability and time/degree categories; no official CEFR placement claim", "evidence_type": "OFFICIAL_SCHOOL_GRAMMAR_NOT_CEFR"}], "active_recall": ["U-A2-010-I08", "U-A2-010-I09"], "prerequisites": ["A1-G04", "A2-G04"], "reading_tasks": ["U-A2-010-I10", "U-A2-010-I11"], "transfer_task": "U-A2-010-I16", "writing_tasks": ["U-A2-010-I14"], "competency_ids": ["A2-G12"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; no observed learner mastery", "speaking_tasks": ["U-A2-010-I15"], "errors_taxonomy": ["FACT_SUBSTITUTION", "LEXICAL_ROLE_CONFUSION", "REGISTER_MISMATCH", "UNSUPPORTED_INFERENCE", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A2-010-I02", "U-A2-010-I03", "U-A2-010-I04", "U-A2-010-I05", "U-A2-010-I06", "U-A2-010-I07"], "listening_tasks": ["U-A2-010-I12", "U-A2-010-I13"], "reading_text_el": "Ο Νίκος συνήθως δουλεύει από το σπίτι. Το γραφείο που χρησιμοποιεί είναι στο μικρό δωμάτιο δίπλα στην κουζίνα. Το πρωί σηκώνεται νωρίς και πρώτα πίνει καφέ. Μετά διαβάζει τα μηνύματά του. Σπάνια πηγαίνει στο γραφείο της εταιρείας. Χτες όμως πήγε εκεί για μια συνάντηση. Η συνάδελφος που οργάνωσε τη συνάντηση έφερε και τα νέα σχέδια. Η συζήτηση ήταν αρκετά σύντομη. Το απόγευμα ο Νίκος γύρισε σπίτι και έγραψε ένα μήνυμα στην ομάδα.", "learning_outcome": "Передать частоту, время и степень без смешения значений", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "transfer": "I16 + новая самостоятельная речь на I17/I19 по item-specific anchors", "controlled": "≥80% закрытых ответов, затем исправление всех смысловых ошибок"}, "vocabulary_items": [{"lemma": "συνήθως", "stress": "συνήθως", "example": "Συνήθως πηγαίνω με τα πόδια.", "inflection": "άκλιτο", "meaning_ru": "обычно", "collocations": ["συνήθως πηγαίνω"]}, {"lemma": "συχνά", "stress": "συχνά", "example": "Έρχομαι συχνά εδώ.", "inflection": "άκλιτο", "meaning_ru": "часто", "collocations": ["έρχομαι συχνά"]}, {"lemma": "σπάνια", "stress": "σπάνια", "example": "Βγαίνω σπάνια το βράδυ.", "inflection": "άκλιτο", "meaning_ru": "редко", "collocations": ["βγαίνω σπάνια"]}, {"lemma": "νωρίς", "stress": "νωρίς", "example": "Φτάνω νωρίς στη δουλειά.", "inflection": "άκλιτο", "meaning_ru": "рано", "collocations": ["φτάνω νωρίς"]}, {"lemma": "αρκετά", "stress": "αρκετά", "example": "Το σπίτι είναι αρκετά μεγάλο.", "inflection": "άκλιτο", "meaning_ru": "довольно; достаточно по контексту", "collocations": ["αρκετά μεγάλο"]}, {"lemma": "που", "stress": "που", "example": "Το βιβλίο που θέλω είναι εδώ.", "inflection": "άκλιτο", "meaning_ru": "который в простом относительном обороте", "collocations": ["το βιβλίο που"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A2-010-I01"], "learning_objectives": ["Передать частоту, время и степень без смешения значений", "Связать существительное с ясным относительным που", "Сравнить привычный распорядок и отдельное событие"], "microcompetency_ids": ["U-A2-010-MC01", "U-A2-010-MC02", "U-A2-010-MC03"], "prerequisite_support": {"A1-G04": {"key": "μικρή τσάντα / μικρά κουτιά", "probe": "Поставьте μικρός: ___ τσάντα / ___ κουτιά.", "unit_id": "U-A1-006", "on_failure": "Повторить согласование U-A1-006, затем новый пример."}, "A2-G04": {"key": "διάβαζα", "probe": "В Διάβαζα όταν ήρθε η Άννα что задаёт фон?", "unit_id": "U-A2-008", "on_failure": "Повторить процесс/целое событие U-A2-008."}}, "primary_competencies": ["A2-G12"], "learner_data_included": false, "estimated_active_minutes": 65}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
