453	source_claim	CP08-INHERITED-U-A1-009-I14-03	6e0b659e18bb2e15247d713c7fa14dff24a1136b007b491d9283363c93017d4a	\N	{"record": {"claim": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A1-009-I14-03", "item_ids": ["U-A1-009-I14"], "source_id": "N404", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A1-009-I14.json", "sha256": "5e2d3d07fb9d3209a022b2b566dffa0563007383480ee19216d54165747579da"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "§5.1 συμπλεκτικοί/αντιθετικοί; §5.2 αιτιολογικές", "source_id": "N404", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}}, "claim_id": "CP08-INHERITED-U-A1-009-I14-03", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3137	unit	U-A2-011	5654fccfa229dcd111fab353889874dba70a03acbee8d2a0d5bd2871cddd5c25	core	{"unit_id": "U-A2-011", "content_hash": "5654fccfa229dcd111fab353889874dba70a03acbee8d2a0d5bd2871cddd5c25", "canonical_path": "GreekOS_Academic_Corpus/units/U-A2-011.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A2-011-RUBRIC"], "unit_id": "U-A2-011", "version": "0.1.2", "title_ru": "Жильё, услуги и поездки: понять цену и исправить бронирование", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Этот урок связывает жильё, городской маршрут, оплату услуги и поездку одной задачей: понять условия, уточнить непонятное и подтвердить свой выбор. Сначала восстановите A1-V03: вход, остановка, рядом/напротив, идти/ехать. Диагностика ниже проверяет, что вы не путаете место и направление. Если сложно, вернитесь к U-A1-013. Числа повторяются по U-A1-003; время — по опоре этого урока: στις έξι το απόγευμα означает в 18:00, την Τρίτη — во вторник. Прочитайте 480 как τετρακόσια ογδόντα; это готовая опора для цены в тексте, не тест на ещё не изученный ряд сотен. Это языковые сценарии с вымышленными ценами, а не сведения о действующих тарифах или банковских правилах.\\nЖильё: διαμέρισμα — квартира, ενοίκιο — плата за её аренду, όροφος — этаж. Вопрос Πόσο είναι το ενοίκιο τον μήνα; требует месячную сумму. Υπάρχει ασανσέρ; — есть ли лифт? Сравните περιλαμβάνεται — входит в стоимость, πληρώνεται χωριστά — оплачивается отдельно. Эти две частотные формы изучаются как готовые блоки: всю пассивную парадигму здесь не требуем. Το νερό περιλαμβάνεται не позволяет заключить, что включено и электричество. Прежде чем соглашаться, спросите Τι περιλαμβάνεται στην τιμή;\\nГород и услуги: απέναντι από την είσοδο — напротив входа; κοντά στον σταθμό — рядом со станцией. Η στάση — остановка, ο σταθμός — станция: в истории могут присутствовать оба места. В банке λογαριασμός может означать банковский счёт, а λογαριασμός ρεύματος — документ на оплату электричества. Уточнение в словосочетании важнее русского перевода одного слова. Πληρώνω τον λογαριασμό — оплачиваю счёт; открытие счёта — отдельное намерение, а не синоним оплаты. Не сообщайте настоящие номера карт и счетов: для упражнения нужны только действие и способ оплаты.\\nПоездка: κράτηση — бронирование; μονόκλινο и δίκλινο различают номер для одного и двух человек. На этом уровне не выводим конфигурацию кроватей из одного названия номера: при необходимости задаём отдельный вопрос Έχει δύο κρεβάτια; Заучиваем сочетания για δύο νύχτες, με πρωινό, χωρίς πρωινό. Цена τη νύχτα и цена συνολικά различаются. Сначала повторите ночи и тип номера, затем рассчитайте общую сумму, затем уточните оплату. Сумма арифметики — учебное условие, а не банковская рекомендация. Με κάρτα и με μετρητά — два способа оплаты; απόδειξη — чек.\\nПри покупке билета назовите направление, дату, количество пассажиров, затем уточните αναχώρηση и επιστροφή. Готовая просьба Θα ήθελα ένα εισιτήριο για την Πάτρα — вежливый блок; его грамматический разбор не является условием освоения лексики. При ошибке оператора: Συγγνώμη, ζήτησα…; повторите правильный факт. При непонимании: Μπορείτε να το πείτε ξανά; Не соглашайтесь только потому, что узнали одно слово. В конце разговора кратко подтвердите условия: Άρα, δύο νύχτες, χωρίς πρωινό, 140 ευρώ συνολικά. Затем перенесите схему на новую услугу. Скрипт без звучащего файла проверяет чтение, не аудирование.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Ψάχνω ένα μικρό διαμέρισμα.", "Το ενοίκιο είναι 480 ευρώ.", "Το σπίτι είναι στον δεύτερο όροφο.", "Η πολυκατοικία έχει ασανσέρ.", "Το ρεύμα πληρώνεται χωριστά.", "Πληρώνω τον λογαριασμό του νερού.", "Πηγαίνω στην τράπεζα.", "Θα πληρώσω με μετρητά.", "Μπορώ να πληρώσω με κάρτα;", "Θέλω να κάνω κράτηση.", "Έχετε ένα μονόκλινο;", "Θέλω ένα δίκλινο για δύο νύχτες.", "Ποια είναι η ώρα αναχώρησης;", "Θέλω ένα εισιτήριο με επιστροφή.", "Μπορώ να έχω μια απόδειξη;", "Το πρωινό πληρώνεται χωριστά."], "review_plan": {"days": [7, 14, 28], "rule": "Новый ответ без модели; после подсказки сохранять assisted, повторить самостоятельно с новыми данными.", "item_ids": ["U-A2-011-I17", "U-A2-011-I18", "U-A2-011-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Α2: Κατοικία, Ελεύθερος χρόνος, Κοινωνικές σχέσεις, Υγεία, Εκπαίδευση/επαγγελματικός χώρος; production goals", "source_id": "CP06-A2-S003", "checked_on": "2026-10-18", "claim_scope": "Everyday communicative domains only; original lessons and score thresholds are project choices", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR"}, {"anchor": "ΛΚΝ λογαριασμός, II1 and bank-account usage", "source_id": "CP06-A2-S004", "checked_on": "2026-10-18", "claim_scope": "Bill and bank account are context-dependent senses", "evidence_type": "PRIMARY_LEXICOGRAPHIC"}], "active_recall": ["U-A2-011-I08", "U-A2-011-I09"], "prerequisites": ["A1-V03"], "reading_tasks": ["U-A2-011-I10", "U-A2-011-I11"], "transfer_task": "U-A2-011-I16", "writing_tasks": ["U-A2-011-I14"], "competency_ids": ["A2-V01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; no observed learner mastery", "speaking_tasks": ["U-A2-011-I15"], "errors_taxonomy": ["FACT_SUBSTITUTION", "LEXICAL_ROLE_CONFUSION", "REGISTER_MISMATCH", "UNSUPPORTED_INFERENCE", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A2-011-I02", "U-A2-011-I03", "U-A2-011-I04", "U-A2-011-I05", "U-A2-011-I06", "U-A2-011-I07"], "listening_tasks": ["U-A2-011-I12", "U-A2-011-I13"], "reading_text_el": "Η Άννα βρήκε ένα μικρό διαμέρισμα κοντά στον σταθμό. Το ενοίκιο είναι 480 ευρώ τον μήνα. Το νερό περιλαμβάνεται, αλλά το ρεύμα πληρώνεται χωριστά. Το διαμέρισμα είναι στον δεύτερο όροφο και δεν υπάρχει ασανσέρ. Η στάση του λεωφορείου είναι απέναντι από την είσοδο. Η Άννα θέλει να δει το σπίτι την Τρίτη στις έξι. Πριν πάει εκεί, θα πληρώσει έναν λογαριασμό στην τράπεζα. Μετά θα πάρει το λεωφορείο. Δεν έχει αποφασίσει ακόμα αν θα νοικιάσει το σπίτι.", "learning_outcome": "Извлечь и уточнить условия жилья и отдельной оплаты", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "transfer": "I16 + новая самостоятельная речь на I17/I19 по item-specific anchors", "controlled": "≥80% закрытых ответов, затем исправление всех смысловых ошибок"}, "vocabulary_items": [{"lemma": "διαμέρισμα", "stress": "διαμέρισμα", "example": "Ψάχνω ένα μικρό διαμέρισμα.", "inflection": "το διαμέρισμα / τα διαμερίσματα", "meaning_ru": "квартира", "collocations": ["νοικιάζω διαμέρισμα"]}, {"lemma": "ενοίκιο", "stress": "ενοίκιο", "example": "Το ενοίκιο είναι 480 ευρώ.", "inflection": "το ενοίκιο", "meaning_ru": "арендная плата", "collocations": ["πληρώνω το ενοίκιο"]}, {"lemma": "όροφος", "stress": "όροφος", "example": "Το σπίτι είναι στον δεύτερο όροφο.", "inflection": "ο όροφος / οι όροφοι", "meaning_ru": "этаж", "collocations": ["στον δεύτερο όροφο"]}, {"lemma": "ασανσέρ", "stress": "ασανσέρ", "example": "Η πολυκατοικία έχει ασανσέρ.", "inflection": "το ασανσέρ, άκλιτο", "meaning_ru": "лифт", "collocations": ["έχει ασανσέρ"]}, {"lemma": "ρεύμα", "stress": "ρεύμα", "example": "Το ρεύμα πληρώνεται χωριστά.", "inflection": "το ρεύμα", "meaning_ru": "электричество в бытовом счёте", "collocations": ["λογαριασμός ρεύματος"]}, {"lemma": "λογαριασμός", "stress": "λογαριασμός", "example": "Πληρώνω τον λογαριασμό του νερού.", "inflection": "ο λογαριασμός / οι λογαριασμοί", "meaning_ru": "счёт к оплате; банковский счёт", "collocations": ["πληρώνω λογαριασμό"]}, {"lemma": "τράπεζα", "stress": "τράπεζα", "example": "Πηγαίνω στην τράπεζα.", "inflection": "η τράπεζα / οι τράπεζες", "meaning_ru": "банк", "collocations": ["στην τράπεζα"]}, {"lemma": "μετρητά", "stress": "μετρητά", "example": "Θα πληρώσω με μετρητά.", "inflection": "τα μετρητά, πληθυντικός", "meaning_ru": "наличные", "collocations": ["με μετρητά"]}, {"lemma": "κάρτα", "stress": "κάρτα", "example": "Μπορώ να πληρώσω με κάρτα;", "inflection": "η κάρτα", "meaning_ru": "карта", "collocations": ["με κάρτα"]}, {"lemma": "κράτηση", "stress": "κράτηση", "example": "Θέλω να κάνω κράτηση.", "inflection": "η κράτηση / οι κρατήσεις", "meaning_ru": "бронирование", "collocations": ["κάνω κράτηση"]}, {"lemma": "μονόκλινο", "stress": "μονόκλινο", "example": "Έχετε ένα μονόκλινο;", "inflection": "το μονόκλινο δωμάτιο", "meaning_ru": "одноместный номер", "collocations": ["ένα μονόκλινο"]}, {"lemma": "δίκλινο", "stress": "δίκλινο", "example": "Θέλω ένα δίκλινο για δύο νύχτες.", "inflection": "το δίκλινο δωμάτιο", "meaning_ru": "двухместный номер", "collocations": ["ένα δίκλινο"]}, {"lemma": "αναχώρηση", "stress": "αναχώρηση", "example": "Ποια είναι η ώρα αναχώρησης;", "inflection": "η αναχώρηση", "meaning_ru": "отправление", "collocations": ["ώρα αναχώρησης"]}, {"lemma": "επιστροφή", "stress": "επιστροφή", "example": "Θέλω ένα εισιτήριο με επιστροφή.", "inflection": "η επιστροφή", "meaning_ru": "возвращение; обратный путь", "collocations": ["με επιστροφή"]}, {"lemma": "απόδειξη", "stress": "απόδειξη", "example": "Μπορώ να έχω μια απόδειξη;", "inflection": "η απόδειξη", "meaning_ru": "чек", "collocations": ["μια απόδειξη"]}, {"lemma": "χωριστά", "stress": "χωριστά", "example": "Το πρωινό πληρώνεται χωριστά.", "inflection": "άκλιτο", "meaning_ru": "отдельно", "collocations": ["πληρώνω χωριστά"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A2-011-I01"], "learning_objectives": ["Извлечь и уточнить условия жилья и отдельной оплаты", "Различить платёж, бронирование и поездку в коротком бытовом контексте", "Самостоятельно исправить ошибку услуги и подтвердить условия"], "microcompetency_ids": ["U-A2-011-MC01", "U-A2-011-MC02", "U-A2-011-MC03"], "prerequisite_support": {"A1-V03": {"key": "Η στάση είναι απέναντι από την είσοδο.", "probe": "Скажите: остановка напротив входа.", "unit_id": "U-A1-013", "on_failure": "Повторить позицию/направление в U-A1-013."}, "time_support": "Конкретная опора στις έξι το απόγευμα / την Τρίτη дана в теории; после помощи повторить новую попытку самостоятельно.", "numerical_support": {"scope": "Известные базовые числительные; новые суммы даются с опорой в теории, полное владение сотнями не предполагается.", "unit_id": "U-A1-003"}}, "primary_competencies": ["A2-V01"], "learner_data_included": false, "estimated_active_minutes": 65}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
