459	source_claim	CP08-INHERITED-U-A1-009-I16-03	21a2bb2bd2859708141dddf0b1aec918ba6b93251e874e2dd0995b91661e2768	\N	{"record": {"claim": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A1-009-I16-03", "item_ids": ["U-A1-009-I16"], "source_id": "N404", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A1-009-I16.json", "sha256": "8d854dde9b60473bd4ec901e6694ff9c961dff7d1680010224d1c7c7684dc89e"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "§5.1 συμπλεκτικοί/αντιθετικοί; §5.2 αιτιολογικές", "source_id": "N404", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}}, "claim_id": "CP08-INHERITED-U-A1-009-I16-03", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3138	unit	U-A2-012	d0813427262b6c763eae153eb2d95a1a93a9bac7b369da448f9086ac852e2798	core	{"unit_id": "U-A2-012", "content_hash": "d0813427262b6c763eae153eb2d95a1a93a9bac7b369da448f9086ac852e2798", "canonical_path": "GreekOS_Academic_Corpus/units/U-A2-012.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A2-012-RUBRIC"], "unit_id": "U-A2-012", "version": "0.1.2", "title_ru": "Учёба, работа и встречи: сообщить ограничение и согласовать новый план", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "В этом уроке вы согласуете встречу, когда пересекаются учёба, работа, здоровье и свободное время. Проверяем не медицинские знания, а точность сообщения: что уже назначено, почему время не подходит, какой вариант принят. Цены и правила услуг здесь не утверждаются. Перед началом восстановите вопрос о наличии из U-A2-009, обозначение времени по опоре ниже и просьбу об изменении брони из U-A2-011. В I01 назовите время и спросите о другой возможности; если один компонент отсутствует, повторите соответствующий урок перед I02.\\nΡαντεβού — заранее назначенная встреча. Контекст уточняет её вид: με τον γιατρό — приём врача, με μια φίλη — встреча с подругой; само слово не означает обязательно романтическое свидание. Κλείνω ραντεβού — договариваюсь о времени; αλλάζω την ώρα — меняю время; ακυρώνω — отменяю. Эти намерения различаются. Если вам нужен другой день, не заканчивайте разговор одним Θέλω να ακυρώσω: попросите новую дату. При подтверждении повторите день и час, а не только Ναι. В сценарии старое время отменяется явно; вне сценария этого нельзя предполагать.\\nРабота и учёба: δουλειά — работа, μάθημα — занятие, ωράριο — установленное время работы. Μέχρι τις επτά указывает границу занятости; μετά τις επτά — после семи, а не ровно в семь. Έχω μάθημα στις έξι не говорит, когда оно заканчивается. Поэтому нельзя назначить следующую встречу сразу после шести без уточнения. Сравните Κάθε Τετάρτη έχω μάθημα и Αυτή την Τετάρτη δεν μπορώ: обычный план может иметь исключение. Вежливое объяснение обычно короткое: Δυστυχώς δουλεύω εκείνη την ώρα. Не нужно придумывать подробную причину, если человек сообщил только занятость.\\nО самочувствии можно сообщить простыми фразами: Δεν αισθάνομαι καλά — плохо себя чувствую; Έχω πυρετό — у меня температура; Πονάει το κεφάλι μου — болит голова. Учим последние выражения как готовые блоки, не выводим диагноз и лечение. В предложении Πονάει το κεφάλι μου глагол согласован с κεφάλι; в Πονάνε τα πόδια μου — с πόδια. Для языковой записи используйте вымышленные данные. Задача администратора — согласовать время, а не назначить лекарство. Ο γιατρός и ο οδοντίατρος обозначают разные роли; когда говорим о женщине, употребляются η γιατρός, η οδοντίατρος.\\nВстреча с другом допускает более личный регистр: Θέλεις να πάμε σινεμά; Προτιμώ να περπατήσουμε. Отклонить вариант не значит отклонить человека: Ευχαριστώ για την πρόσκληση, αλλά δεν μπορώ σήμερα. Μπορούμε αύριο; В официальном разговоре: Μπορούμε να αλλάξουμε την ώρα του ραντεβού; В обоих регистрах смысл одинаково проверяем: предложить вариант, услышать ограничение, выбрать совместимое время, подтвердить его.\\nПрактикуйтесь по схеме «старое условие → ограничение → альтернатива → подтверждение». Закройте образцы, разыграйте обе стороны и измените день или причину. Не повторяйте автоматически удобный ответ из примера: в новом условии утро может быть занято. На D7 и D28 переносите схему между учебным занятием, приёмом и дружеской встречей. Транскрипт ниже является подготовкой записи: до существования аудиофайла задания I12–I13 не дают балл за аудирование.\\nОпора для времени перед I01: στις πέντε το απόγευμα — в 17:00; την Πέμπτη — в четверг; την Παρασκευή — в пятницу. Μέχρι τις πέντε — до пяти; μετά τις πέντε — после пяти. Повторите числительные из U-A1-003 и затем назовите два своих времени с στις. Если не удаётся, используйте эту опору и зафиксируйте помощь; самостоятельная диагностика должна пройти заново без неё.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Έχω ραντεβού με τον γιατρό.", "Έχω μάθημα στις έξι.", "Είμαι στη δουλειά μέχρι τις επτά.", "Αυτή την εβδομάδα αλλάζει το ωράριό μου.", "Η συνάδελφός μου δουλεύει το πρωί.", "Την Πέμπτη θα πάω στον οδοντίατρο.", "Έχω πυρετό σήμερα.", "Πονάει το κεφάλι μου.", "Σήμερα ξεκουράζομαι στο σπίτι.", "Ευχαριστώ για την πρόσκληση.", "Συμφωνώ, πάμε στο πάρκο.", "Προτιμώ να περπατήσουμε.", "Θέλω να ακυρώσω το ραντεβού.", "Μπορούμε να αλλάξουμε την ώρα;", "Υπάρχει διαθέσιμη ώρα το απόγευμα;", "Δυστυχώς δεν μπορώ την Τρίτη."], "review_plan": {"days": [7, 14, 28], "rule": "Новый ответ без модели; после подсказки сохранять assisted, повторить самостоятельно с новыми данными.", "item_ids": ["U-A2-012-I17", "U-A2-012-I18", "U-A2-012-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Α2: Κατοικία, Ελεύθερος χρόνος, Κοινωνικές σχέσεις, Υγεία, Εκπαίδευση/επαγγελματικός χώρος; production goals", "source_id": "CP06-A2-S003", "checked_on": "2026-10-18", "claim_scope": "Everyday communicative domains only; original lessons and score thresholds are project choices", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR"}, {"anchor": "ΛΚΝ ραντεβού, main definition", "source_id": "CP06-A2-S005", "checked_on": "2026-10-18", "claim_scope": "Prearranged meeting; invariant noun; professional and personal contexts", "evidence_type": "PRIMARY_LEXICOGRAPHIC"}], "active_recall": ["U-A2-012-I08", "U-A2-012-I09"], "prerequisites": ["A2-G10", "A2-V01"], "reading_tasks": ["U-A2-012-I10", "U-A2-012-I11"], "transfer_task": "U-A2-012-I16", "writing_tasks": ["U-A2-012-I14"], "competency_ids": ["A2-V02"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; no observed learner mastery", "speaking_tasks": ["U-A2-012-I15"], "errors_taxonomy": ["FACT_SUBSTITUTION", "LEXICAL_ROLE_CONFUSION", "REGISTER_MISMATCH", "UNSUPPORTED_INFERENCE", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A2-012-I02", "U-A2-012-I03", "U-A2-012-I04", "U-A2-012-I05", "U-A2-012-I06", "U-A2-012-I07"], "listening_tasks": ["U-A2-012-I12", "U-A2-012-I13"], "reading_text_el": "Η Μαρία δουλεύει σε ένα μικρό βιβλιοπωλείο. Την Τετάρτη έχει μάθημα ελληνικών στις έξι, αλλά αυτή την εβδομάδα θα δουλέψει μέχρι τις επτά. Γι’ αυτό ζητά από τη δασκάλα να αλλάξει την ώρα του μαθήματος. Την Πέμπτη το πρωί έχει ραντεβού με τον οδοντίατρο. Δεν μπορεί να αλλάξει αυτό το ραντεβού. Η δασκάλα προτείνει την Παρασκευή στις πέντε και η Μαρία συμφωνεί. Μετά το μάθημα θέλει να συναντήσει τη φίλη της, την Άννα. Η Άννα προτιμά να περπατήσουν στο πάρκο αντί να πάνε σινεμά. Η Μαρία δέχεται, αλλά ζητά να συναντηθούν στις επτά, όχι στις έξι.", "learning_outcome": "Различить назначение, перенос и отмену встречи в контексте работы и учёбы", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "transfer": "I16 + новая самостоятельная речь на I17/I19 по item-specific anchors", "controlled": "≥80% закрытых ответов, затем исправление всех смысловых ошибок"}, "vocabulary_items": [{"lemma": "ραντεβού", "stress": "ραντεβού", "example": "Έχω ραντεβού με τον γιατρό.", "inflection": "το ραντεβού, άκλιτο", "meaning_ru": "назначенная встреча, приём", "collocations": ["κλείνω ραντεβού"]}, {"lemma": "μάθημα", "stress": "μάθημα", "example": "Έχω μάθημα στις έξι.", "inflection": "το μάθημα / τα μαθήματα", "meaning_ru": "занятие, урок", "collocations": ["μάθημα ελληνικών"]}, {"lemma": "δουλειά", "stress": "δουλειά", "example": "Είμαι στη δουλειά μέχρι τις επτά.", "inflection": "η δουλειά", "meaning_ru": "работа", "collocations": ["στη δουλειά"]}, {"lemma": "ωράριο", "stress": "ωράριο", "example": "Αυτή την εβδομάδα αλλάζει το ωράριό μου.", "inflection": "το ωράριο", "meaning_ru": "часы работы", "collocations": ["αλλάζει το ωράριο"]}, {"lemma": "συνάδελφος", "stress": "συνάδελφος", "example": "Η συνάδελφός μου δουλεύει το πρωί.", "inflection": "ο/η συνάδελφος", "meaning_ru": "коллега", "collocations": ["η συνάδελφός μου"]}, {"lemma": "οδοντίατρος", "stress": "οδοντίατρος", "example": "Την Πέμπτη θα πάω στον οδοντίατρο.", "inflection": "ο/η οδοντίατρος", "meaning_ru": "стоматолог", "collocations": ["στον οδοντίατρο"]}, {"lemma": "πυρετός", "stress": "πυρετός", "example": "Έχω πυρετό σήμερα.", "inflection": "ο πυρετός", "meaning_ru": "повышенная температура", "collocations": ["έχω πυρετό"]}, {"lemma": "πονάω", "stress": "πονάω", "example": "Πονάει το κεφάλι μου.", "inflection": "πονώ / πονάω", "meaning_ru": "болеть, испытывать боль", "collocations": ["πονάει το κεφάλι μου"]}, {"lemma": "ξεκουράζομαι", "stress": "ξεκουράζομαι", "example": "Σήμερα ξεκουράζομαι στο σπίτι.", "inflection": "ξεκουράζομαι", "meaning_ru": "отдыхать", "collocations": ["ξεκουράζομαι στο σπίτι"]}, {"lemma": "πρόσκληση", "stress": "πρόσκληση", "example": "Ευχαριστώ για την πρόσκληση.", "inflection": "η πρόσκληση", "meaning_ru": "приглашение", "collocations": ["ευχαριστώ για την πρόσκληση"]}, {"lemma": "συμφωνώ", "stress": "συμφωνώ", "example": "Συμφωνώ, πάμε στο πάρκο.", "inflection": "συμφωνώ", "meaning_ru": "соглашаться", "collocations": ["συμφωνώ μαζί σου"]}, {"lemma": "προτιμώ", "stress": "προτιμώ", "example": "Προτιμώ να περπατήσουμε.", "inflection": "προτιμώ", "meaning_ru": "предпочитать", "collocations": ["προτιμώ να περπατήσω"]}, {"lemma": "ακυρώνω", "stress": "ακυρώνω", "example": "Θέλω να ακυρώσω το ραντεβού.", "inflection": "ακυρώνω", "meaning_ru": "отменять", "collocations": ["ακυρώνω το ραντεβού"]}, {"lemma": "αλλάζω", "stress": "αλλάζω", "example": "Μπορούμε να αλλάξουμε την ώρα;", "inflection": "αλλάζω", "meaning_ru": "менять", "collocations": ["αλλάζω την ώρα"]}, {"lemma": "διαθέσιμος", "stress": "διαθέσιμος", "example": "Υπάρχει διαθέσιμη ώρα το απόγευμα;", "inflection": "διαθέσιμη, διαθέσιμο", "meaning_ru": "свободный, доступный", "collocations": ["διαθέσιμη ώρα"]}, {"lemma": "δυστυχώς", "stress": "δυστυχώς", "example": "Δυστυχώς δεν μπορώ την Τρίτη.", "inflection": "άκλιτο", "meaning_ru": "к сожалению", "collocations": ["δυστυχώς δεν μπορώ"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A2-012-I01"], "learning_objectives": ["Различить назначение, перенос и отмену встречи в контексте работы и учёбы", "Сообщить ограничение и самочувствие без выдуманного диагноза", "Самостоятельно договориться об альтернативе и подтвердить день и час"], "microcompetency_ids": ["U-A2-012-MC01", "U-A2-012-MC02", "U-A2-012-MC03"], "prerequisite_support": {"A2-G10": "U-A2-009, I08/I09: полный вопрос о наличии; при ошибке повторить вопросительное κανένα и δεν.", "A2-V01": "U-A2-011, I15: исправить ошибочное время; I01 этого урока проверяет перенос.", "time_support": "Конкретная опора στις πέντε το απόγευμα / την Πέμπτη дана в теории. Базовые числа U-A1-003; не U-A1-007 (алфавит) и не U-A1-010 (отрицание)."}, "primary_competencies": ["A2-V02"], "learner_data_included": false, "estimated_active_minutes": 65}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
