465	source_claim	CP08-INHERITED-U-A1-009-I18-03	58ee0deb544b8d51a317d984dc145e62f7db7c94e1b8386b2b524ce5640a494a	\N	{"record": {"claim": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A1-009-I18-03", "item_ids": ["U-A1-009-I18"], "source_id": "N404", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A1-009-I18.json", "sha256": "28a72754bdeb9573582e85152f1fac3c0f337ad43360d63bf209b370ac189b65"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "§5.1 συμπλεκτικοί/αντιθετικοί; §5.2 αιτιολογικές", "source_id": "N404", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}}, "claim_id": "CP08-INHERITED-U-A1-009-I18-03", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3139	unit	U-A2-013	2a5eb2ec0a1142dcdeda16262f12dfdb490221ce412e8f32772e45fb05a35765	core	{"unit_id": "U-A2-013", "content_hash": "2a5eb2ec0a1142dcdeda16262f12dfdb490221ce412e8f32772e45fb05a35765", "canonical_path": "GreekOS_Academic_Corpus/units/U-A2-013.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "rubrics": ["U-A2-013-RUBRIC"], "unit_id": "U-A2-013", "version": "0.1.0", "title_ru": "Уточнить сбой и завершить бытовой обмен", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Рутинный обмен становится разговором, когда ответ отличается от ожидаемого. В магазине, библиотеке или на занятии нужно не только произнести просьбу, но и проверить, правильно ли вас поняли. Цель этого урока — заметить конкретный сбой, коротко исправить его и подтвердить итог. Не нужно говорить сложнее собеседника: две ясные фразы обычно полезнее длинного объяснения. Перед началом выполните I01 без образца. Если трудно попросить повторить или назвать день встречи, вернитесь к U-A1-001 и U-A2-012. Запишите помощь отдельно, затем повторите пробу с другим временем.\\nНачните с контакта и нужного действия: Καλημέρα σας. Θέλω να δανειστώ αυτό το βιβλίο. Форма σας подходит сотруднику, с которым вы не знакомы; другу можно сказать Γεια σου. Здесь вежливость создают обращение, παρακαλώ, спокойное уточнение и благодарность, а не одно обязательное слово. Μπορείτε να επαναλάβετε, παρακαλώ; — готовая просьба повторить. Μπορείτε να μιλήσετε πιο αργά; просит замедлиться. Выберите именно ту помощь, которая нужна: если неясен только номер, не заставляйте человека повторять весь рассказ.\\nРазделяйте три состояния. Δεν άκουσα καλά — я плохо расслышал. Δεν καταλαβαίνω τη λέξη — не понимаю слово. Νομίζω ότι υπάρχει ένα λάθος — предполагаю ошибку в информации. Нельзя называть ошибкой собеседника то, что вы просто не расслышали. Вопрос Είπατε δεκατρία ή τριάντα; делает проверку конкретной. Он пока не утверждает ни одного числа. Сначала дождитесь ответа, затем повторите принятое условие: Άρα, την Παρασκευή στις τρεις. Если собеседник не подтвердил новый вариант, договорённость ещё не завершена.\\nДля исправления факта используйте короткий контраст: Όχι την Τρίτη, την Πέμπτη. Ζήτησα ένα εισιτήριο, όχι δύο. Для количества и назначения нужны точные существительные: ένα εισιτήριο για αύριο. Простое Όχι без уточнения может показаться отказом от всей услуги. Если сотрудник предлагает другой вариант, сравните его со своим ограничением. Μπορώ μετά τις τέσσερις, όχι το πρωί. Затем согласитесь или предложите альтернативу. Не отвечайте Ναι автоматически только потому, что хотите быть вежливым.\\nВ разговоре с другом сохраняется та же логика. Ты услышал σινεμά, но друг предложил θέατρο: Συγγνώμη, είπες θέατρο; Не обязательно объяснять все обстоятельства. Если слово неизвестно, спросите Τι σημαίνει αυτό; и укажите слово или предмет. Можно переспросить описательно: Είναι κοντά στην είσοδο; Не заменяйте неизвестный объект другим по догадке. Умение показать границу понимания входит в успешное общение.\\nСоберите разговор из четырёх действий: просьба → ответ с новой информацией → точное уточнение или исправление → подтверждение результата. В парной практике партнёр меняет только один параметр: число, день, предмет или доступность. Получатель должен обнаружить именно этот параметр. Сначала разрешена опора на фразы; следующая попытка проходит без неё и с новыми данными. Если вы повторили готовую модель, отмечайте контролируемое воспроизведение, а не свободную речь.\\nНа D7 и D28 меняются место и адресат: библиотека становится бассейном, покупка — записью на занятие. Проверяйте не количество слов, а возможность действовать по вашему сообщению. После разговора назовите, что было непонятно и каким вопросом вы это выяснили. Аудиозадания пока заблокированы: прочитанный сценарий тренирует чтение и реплики, но не доказывает понимание на слух. Фонетику нельзя оценивать по письменному ответу или автоматической транскрипции.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Μπορείτε να επαναλάβετε, παρακαλώ;", "Δεν άκουσα καλά.", "Τι σημαίνει αυτή η λέξη;", "Είπατε δεκατρία ή τριάντα;", "Όχι για σήμερα, για αύριο.", "Ζήτησα ένα εισιτήριο, όχι δύο.", "Μπορώ μετά τις τέσσερις.", "Άρα, την Πέμπτη στις τρεις."], "review_plan": {"days": [7, 14, 28], "rule": "Новая попытка без модели. Помощь отмечать отдельно; D7/D28 не заменять тем же заученным ответом.", "item_ids": ["U-A2-013-I17", "U-A2-013-I18", "U-A2-013-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Α2: Κατοικία, Ελεύθερος χρόνος, Κοινωνικές σχέσεις, Υγεία, Εκπαίδευση/επαγγελματικός χώρος; production goals", "source_id": "CP06-A2-S003", "checked_on": "2026-10-18", "claim_scope": "Everyday communicative domains only; original lessons and score thresholds are project choices", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR"}], "active_recall": ["U-A2-013-I08", "U-A2-013-I09", "U-A2-013-I20"], "prerequisites": ["A1-PR01", "A2-V02"], "reading_tasks": ["U-A2-013-I10", "U-A2-013-I11"], "transfer_task": "U-A2-013-I16", "writing_tasks": ["U-A2-013-I14"], "competency_ids": ["A2-SI01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; no observed learner mastery or full source certification", "speaking_tasks": ["U-A2-013-I15"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION", "PRAGMATICS_REGISTER", "RETENTION", "SELF_REPAIR", "TRANSFER", "UNSUPPORTED_INFERENCE", "VERB_ASPECT", "VOCAB_SELECTION"], "guided_practice": ["U-A2-013-I02", "U-A2-013-I03", "U-A2-013-I04", "U-A2-013-I05", "U-A2-013-I06", "U-A2-013-I07"], "listening_tasks": ["U-A2-013-I12", "U-A2-013-I13"], "reading_text_el": "Η Νίνα πηγαίνει στη βιβλιοθήκη για ένα βιβλίο ελληνικών. Η υπάλληλος της δίνει δύο βιβλία. Η Νίνα εξηγεί ότι χρειάζεται μόνο το μικρό βιβλίο, όχι το μεγάλο. Η υπάλληλος λέει ότι πρέπει να το επιστρέψει την Πέμπτη. Η Νίνα δεν ακούει καλά και ρωτά: «Την Τρίτη ή την Πέμπτη;» Η υπάλληλος επαναλαμβάνει: «Την Πέμπτη, μέχρι τις έξι το απόγευμα». Η Νίνα δουλεύει μέχρι τις πέντε, αλλά μπορεί να πάει μετά τη δουλειά. Πριν φύγει, επιβεβαιώνει την ημέρα και την ώρα. Δεν ζητά να αλλάξει η ημέρα επιστροφής.", "learning_outcome": "Самостоятельно согласовать итог обмена с новым собеседником", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "controlled": "All meaning-changing mistakes corrected after independent first attempt; project provisional threshold ≥80% controlled tasks", "production": "I14/I15/I16 all required facts and intent clear without model; D7/D28 independent transfer required"}, "vocabulary_items": [{"lemma": "επαναλαμβάνω", "stress": "επαναλαμβάνω", "example": "Μπορείτε να επαναλάβετε;", "inflection": "επαναλαμβάνω — να επαναλάβω", "meaning_ru": "повторять", "collocations": ["να επαναλάβετε"]}, {"lemma": "εισιτήριο", "stress": "εισιτήριο", "example": "Θέλω ένα εισιτήριο.", "inflection": "το εισιτήριο / τα εισιτήρια", "meaning_ru": "билет", "collocations": ["ένα εισιτήριο"]}, {"lemma": "επιστρέφω", "stress": "επιστρέφω", "example": "Πότε πρέπει να επιστρέψω το βιβλίο;", "inflection": "επιστρέφω — να επιστρέψω", "meaning_ru": "возвращать", "collocations": ["επιστρέφω το βιβλίο"]}, {"lemma": "λάθος", "stress": "λάθος", "example": "Νομίζω ότι υπάρχει ένα λάθος.", "inflection": "το λάθος / τα λάθη", "meaning_ru": "ошибка", "collocations": ["υπάρχει ένα λάθος"]}], "diagnostic_item_ids": ["U-A2-013-I01"], "learning_objectives": ["Определять, что именно не расслышано или понято неверно", "Сформулировать точное уточнение и исправить один факт", "Самостоятельно согласовать итог обмена с новым собеседником"], "microcompetency_ids": ["U-A2-013-MC01", "U-A2-013-MC02", "U-A2-013-MC03"], "prerequisite_support": {"A2-V02": "U-A2-012: days/time and alternatives; I01 tests appointment detail", "A1-PR01": "U-A1-001: greeting/request/repair; I01 tests request to repeat"}, "primary_competencies": ["A2-SI01"], "estimated_active_minutes": 80}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
