471	source_claim	CP08-INHERITED-U-A1-010-I01-03	ead033da8c1ab9891a238894fb1e567aab61b66c69f0225785902ce9e7756419	\N	{"record": {"claim": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A1-010-I01-03", "item_ids": ["U-A1-010-I01"], "source_id": "N404", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A1-010-I01.json", "sha256": "a1f9f1b190305770e5e9de3e69a895c3fe04332329c6efbfd23cc9b2084343ed"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "§5.2 άρνηση δε(ν)/μη(ν); τελικό ν", "source_id": "N404", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}}, "claim_id": "CP08-INHERITED-U-A1-010-I01-03", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3140	unit	U-A2-014	28246a68c28d7b4705727e2f52f88aa105e4e8c5729246263dbf61d96ca01f2f	core	{"unit_id": "U-A2-014", "content_hash": "28246a68c28d7b4705727e2f52f88aa105e4e8c5729246263dbf61d96ca01f2f", "canonical_path": "GreekOS_Academic_Corpus/units/U-A2-014.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "rubrics": ["U-A2-014-RUBRIC"], "unit_id": "U-A2-014", "version": "0.1.1", "title_ru": "Рассказать об опыте, плане и предпочтении", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Короткое описание опыта, планов и предпочтений отвечает на три разных вопроса: что уже было, что вы собираетесь делать и что вам обычно нравится. Слушатель должен различать эти планы времени без догадок. Перед началом расскажите две фразы о вчерашнем дне и одну о следующей неделе. Если формы прошедшего времени не восстанавливаются, вернитесь к U-A2-001; если трудно назвать привычный день — к U-A1-017. Этот урок продолжает уже введённые прошедшие формы и будущее, а не заменяет их изучение.\\nВыберите один понятный эпизод. Начните с времени и места: Το περασμένο Σάββατο πήγα στη θάλασσα. Затем сообщите спутника, действие и личную реакцию: Πήγα με την αδελφή μου. Περπατήσαμε και μετά φάγαμε σε μια μικρή ταβέρνα. Μου άρεσε πολύ. Подробности должны помогать слушателю представить событие. Не нужно перечислять каждую минуту. Χτες, την περασμένη εβδομάδα и πέρσι помещают событие в прошлое; αύριο, την επόμενη εβδομάδα и του χρόνου указывают на будущее. Отдельно объясняйте изменение плана: Ήθελα να πάω στο μουσείο, αλλά ήταν κλειστό.\\nВ этом уроке используйте знакомые цепочки форм как опору: πηγαίνω — πήγα — θα πάω; βλέπω — είδα — θα δω; τρώω — έφαγα — θα φάω; μένω — έμεινα — θα μείνω; περπατάω — περπάτησα — θα περπατήσω. Эти формы не выводятся все из одного механического окончания. Сначала проверьте, кто действует: πήγα означает «я пошёл», πήγαμε — «мы пошли». Если вы не помните форму нового глагола, лучше выразить мысль знакомыми средствами, чем выдумать парадигму.\\nПлан не является фактом выполнения. Το επόμενο Σάββατο θα πάω στο μουσείο — сообщение о плане; не говорите о нём как о уже состоявшемся визите. Θέλω να δω την έκθεση выражает желание. Δεν ξέρω ακόμη πότε θα πάω прямо отмечает неопределённость времени. Не добавляйте точную дату или подтверждённую бронь, если их нет. Полезная последовательность: план → причина → известное ограничение. Θα πάω με το λεωφορείο γιατί δεν έχω αυτοκίνητο. Если собеседник уточняет время, отвечайте только тем, что знаете.\\nДля предпочтений нужны различия между обычным вкусом и конкретным впечатлением. Μου αρέσει η θάλασσα — море мне нравится вообще. Μου άρεσε η εκδρομή — понравилась эта поездка. Предпочтение можно пояснить одной причиной: Προτιμώ το τρένο γιατί μπορώ να διαβάζω. Не приписывайте свой вкус другим: ο φίλος μου предпочитает другое, и это отдельная информация. Связки πρώτα, μετά, στο τέλος помогают упорядочить эпизод; γιατί объясняет причину; αλλά вводит контраст. Две связанные мысли полезнее шести несвязанных предложений.\\nВ речевой практике сначала сделайте план из трёх ключевых слов, затем уберите его. Расскажите о реальном или вымышленном эпизоде, одном будущем плане и предпочтении. Партнёр задаёт неизвестный заранее вопрос о причине или спутнике. Если приходится читать модель, попытка остаётся тренировочной, не самостоятельной. Запишите, какие факты слушатель понял: время, действие, план, причина. Языковые ошибки оценивайте отдельно от потери смысла.\\nНа D7 и D28 меняются тема и адресат. Вместо прогулки расскажите о занятии или поездке к родственнику. Успех — способность построить новое связное сообщение, а не воспроизвести текст о музее. Аудиосценарий ниже ещё не озвучен: его чтение не проверяет слух, а текстовый ответ не доказывает произношение. Все критерии освоения — проектные и требуют наблюдения за реальными самостоятельными ответами.\\nОпоры для переноса: φτιάχνω — έφτιαξα — θα φτιάξω (готовить/делать); κολυμπάω — να κολυμπήσω; διαβάζω — διάβασα; γράφω — θα γράψω. Σούπα — суп; νόστιμος/νόστιμη — вкусный/вкусная. Воспользовавшись опорой в контрольной попытке, отметьте помощь.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Χτες πήγα στο πάρκο.", "Πήγαμε με το λεωφορείο.", "Πρώτα περπατήσαμε και μετά φάγαμε.", "Μου άρεσε η έκθεση.", "Το άλλο Σάββατο θα πάω στη βιβλιοθήκη.", "Δεν ξέρω ακόμη τι ώρα θα πάω.", "Προτιμώ το τρένο γιατί μπορώ να διαβάζω.", "Ήθελα να πάω στο μουσείο, αλλά ήταν κλειστό."], "review_plan": {"days": [7, 14, 28], "rule": "Новая попытка без модели. Помощь отмечать отдельно; D7/D28 не заменять тем же заученным ответом.", "item_ids": ["U-A2-014-I17", "U-A2-014-I18", "U-A2-014-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Α2: Κατοικία, Ελεύθερος χρόνος, Κοινωνικές σχέσεις, Υγεία, Εκπαίδευση/επαγγελματικός χώρος; production goals", "source_id": "CP06-A2-S003", "checked_on": "2026-10-18", "claim_scope": "Everyday communicative domains only; original lessons and score thresholds are project choices", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR"}, {"anchor": "§6.2 ποιόν ενέργειας; κλίση λύνω; αύξηση", "source_id": "N405", "checked_on": "2026-10-14", "claim_scope": "Retained checkpoint evidence for aspect and familiar active past morphology only; not all lexical forms or A2 placement", "evidence_type": "RETAINED_PRIMARY_GRAMMAR_INSPECTION"}], "active_recall": ["U-A2-014-I08", "U-A2-014-I09", "U-A2-014-I20"], "prerequisites": ["A1-SP01", "A2-G04", "A2-G05"], "reading_tasks": ["U-A2-014-I10", "U-A2-014-I11"], "transfer_task": "U-A2-014-I16", "writing_tasks": ["U-A2-014-I14"], "competency_ids": ["A2-SP01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; no observed learner mastery or full source certification", "speaking_tasks": ["U-A2-014-I15"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION", "RETENTION", "SELF_REPAIR", "TRANSFER", "UNSUPPORTED_INFERENCE", "VERB_ASPECT", "VERB_TENSE"], "guided_practice": ["U-A2-014-I02", "U-A2-014-I03", "U-A2-014-I04", "U-A2-014-I05", "U-A2-014-I06", "U-A2-014-I07"], "listening_tasks": ["U-A2-014-I12", "U-A2-014-I13"], "reading_text_el": "Την περασμένη Κυριακή ο Άρης πήγε σε μια έκθεση φωτογραφίας με την ξαδέλφη του. Πήγαν με λεωφορείο γιατί έβρεχε. Στην έκθεση είδαν φωτογραφίες από μικρά ελληνικά νησιά. Στον Άρη άρεσαν περισσότερο οι φωτογραφίες με ανθρώπους. Η ξαδέλφη του προτιμούσε τα τοπία. Μετά ήπιαν καφέ, αλλά δεν έφαγαν εκεί γιατί το καφέ δεν είχε φαγητό. Το επόμενο Σαββατοκύριακο ο Άρης θέλει να πάει σε μια άλλη έκθεση. Δεν ξέρει ακόμη ποια ημέρα θα πάει και δεν έχει αγοράσει εισιτήριο.", "learning_outcome": "Самостоятельно рассказать о новом опыте и ответить на уточнение", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "controlled": "All meaning-changing mistakes corrected after independent first attempt; project provisional threshold ≥80% controlled tasks", "production": "I14/I15/I16 all required facts and intent clear without model; D7/D28 independent transfer required"}, "vocabulary_items": [{"lemma": "εκδρομή", "stress": "εκδρομή", "example": "Η εκδρομή ήταν ωραία.", "inflection": "η εκδρομή / οι εκδρομές", "meaning_ru": "экскурсия,поездка", "collocations": ["πάω εκδρομή"]}, {"lemma": "έκθεση", "stress": "έκθεση", "example": "Είδα μια έκθεση φωτογραφίας.", "inflection": "η έκθεση / οι εκθέσεις", "meaning_ru": "выставка", "collocations": ["έκθεση φωτογραφίας"]}, {"lemma": "προτιμώ", "stress": "προτιμώ", "example": "Προτιμώ το τρένο γιατί μπορώ να διαβάζω.", "inflection": "προτιμώ — προτιμάς", "meaning_ru": "предпочитать", "collocations": ["προτιμώ το τρένο"]}, {"lemma": "πηγαίνω", "stress": "πηγαίνω", "example": "Χτες πήγα στο πάρκο.", "inflection": "πηγαίνω — πήγα — θα πάω", "meaning_ru": "идти/ехать", "collocations": ["πηγαίνω στο πάρκο"]}], "diagnostic_item_ids": ["U-A2-014-I01"], "learning_objectives": ["Различать состоявшийся эпизод, будущий план и обычное предпочтение", "Связать эпизод и план временными опорами и простой причиной", "Самостоятельно рассказать о новом опыте и ответить на уточнение"], "microcompetency_ids": ["U-A2-014-MC01", "U-A2-014-MC02", "U-A2-014-MC03"], "prerequisite_support": {"A2-G04": "U-A2-008: background/process versus completed event; entry I01 and I05 require distinguishing event framing; if unclear revisit aspect contrasts before independent narration", "A2-G05": "U-A2-002 future; repair plan vs performed event", "A1-SP01": "U-A1-017 first; entry probe on familiar day; postpone if not authored/independently attempted"}, "primary_competencies": ["A2-SP01"], "estimated_active_minutes": 80}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
