477	source_claim	CP08-INHERITED-U-A1-010-I03-03	d9b3b560f7f4d5bb620c2df4e5e9ea6c4a40132c63022b0c145394c8eb84361e	\N	{"record": {"claim": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A1-010-I03-03", "item_ids": ["U-A1-010-I03"], "source_id": "N404", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A1-010-I03.json", "sha256": "1f7befd5b50e863f161bdb1e081475408670da372c4be24da3dd5e07ad29bc66"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "§5.2 άρνηση δε(ν)/μη(ν); τελικό ν", "source_id": "N404", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}}, "claim_id": "CP08-INHERITED-U-A1-010-I03-03", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3141	unit	U-A2-015	d7a82cdff51c7a6376c5bb3b66db8bafe5c1d7f767a5584f75bb465b23fdf8fb	core	{"unit_id": "U-A2-015", "content_hash": "d7a82cdff51c7a6376c5bb3b66db8bafe5c1d7f767a5584f75bb465b23fdf8fb", "canonical_path": "GreekOS_Academic_Corpus/units/U-A2-015.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "rubrics": ["U-A2-015-RUBRIC"], "unit_id": "U-A2-015", "version": "0.1.0", "title_ru": "Написать личное письмо и понятный запрос", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Личное письмо или короткий запрос нужен, чтобы другой человек понял ситуацию и мог ответить. Здесь вы соединяете сообщение о прошедшем событии с просьбой, предложением или вопросом. Перед началом напишите приветствие другу и одну фразу о вчерашнем дне. Затем вспомните, как попросить информацию у незнакомого сотрудника. Если трудно заполнить основные личные данные, вернитесь к U-A1-015; если не различаются прошедшие формы — к U-A2-001; порядок простых связанных мыслей повторите в U-A2-007. Объём письма в заданиях — учебный ориентир, не официальная норма экзамена.\\nСначала определите адресата и цель. Другу подойдёт Γεια σου, Νίκο! В запросе организации удобно Καλημέρα σας. Вежливое окончание Ευχαριστώ πολύ и имя помогают оформить сообщение. Существуют и другие подходящие приветствия; не оценивайте письмо по совпадению с единственным шаблоном. При обращении к одному знакомому человеку используйте σου/σε; к сотруднику или организации — σας. Если меняете адресата, проверьте формы во всём письме: не начинайте на σας и не заканчивайте случайным σου.\\nРабочая структура содержит четыре части: зачем пишу → необходимые факты → конкретная просьба или вопрос → завершение. Например: Σας γράφω για το μάθημα της Πέμπτης. Χτες δεν μπόρεσα να έρθω γιατί ήμουν άρρωστη. Μπορείτε να μου στείλετε την άσκηση; Ευχαριστώ πολύ. Автор объясняет один пропуск и просит одно действие. Не нужно сообщать лишние личные сведения. В учебной практике используйте вымышленные имена и обстоятельства; реальный диагноз или документ не требуется.\\nЕсли рассказываете о событии, дайте читателю временную опору. Χτες έχασα το λεωφορείο και άργησα στο μάθημα связывает причину и результат. Η γραμματέας μου έδωσε μια άλλη ώρα сообщает полученную информацию. Не превращайте просьбу в подтверждённый результат: Θα ήθελα να αλλάξω την ώρα — желание изменить время, а не доказательство, что организация согласилась. Пока ответа нет, можно написать Περιμένω την απάντησή σας. Для альтернативы укажите ограничение: Δεν μπορώ την Τρίτη, αλλά μπορώ την Τετάρτη μετά τις πέντε.\\nГотовые сочетания этого урока: σας γράφω για…; δεν μπόρεσα να έρθω; μπορείτε να μου στείλετε…; θα ήθελα να ρωτήσω…; περιμένω την απάντησή σας. Новые формы поддержаны знакомыми цепочками: γράφω — έγραψα — θα γράψω; στέλνω — έστειλα — θα στείλω; χάνω — έχασα; μπορώ — μπόρεσα. Они служат практической опорой, а не доказательством освоения всех глаголов. Не ставьте отрицание в случайное место: Δεν μπορώ την Τρίτη отрицает возможность вторника; Μπορώ την Τρίτη сообщает противоположное.\\nСоединяйте предложения по смыслу. Και добавляет факт, αλλά противопоставляет, γιατί объясняет причину, μετά показывает следующий шаг. Читателю должно быть понятно, что произошло раньше и что вы просите теперь. Избегайте длинной цепочки из пяти разных мыслей: лучше разделить её точкой. В коротком письме допустимы простые предложения; сложность конструкции не компенсирует потерянную дату, предмет или вопрос.\\nПосле написания проведите две отдельные проверки. Сначала смысл: все ли обязательные факты есть, не добавлено ли несуществующее подтверждение, может ли адресат ответить? Затем язык: согласованы ли лицо и обращение, различены ли прошлое и будущее, понятны ли местоимения, поставлены ли ударения в знакомых словах? Исправление после подсказки сохраняется как исправленная попытка; следующая самостоятельная работа должна использовать новые данные.\\nНа D7 и D28 меняются адресат, предмет и причина обращения. Не переписывайте письмо преподавателю, заменив только имя. Напишите новый запрос о забытом предмете или изменении встречи. Оценка включает выполнение задачи, понятность, достаточные языковые средства и регистр. Одно удачное письмо не подтверждает весь A2. Аудио пока отсутствует; работа с напечатанным сценарием остаётся чтением.\\nДополнительные опоры переноса: αφήνω — άφησα (оставить); επιστρέφω — επέστρεψα (вернуть); ελέγχω — να ελέγξετε (проверить); φτάνω — έφτασα (прибыть); ξεχνώ — ξέχασα (забыть); δανείζω — να δανείσεις (одолжить). Ο φορτιστής — зарядка; τα γυαλιά — очки; το υλικό — материал. Новые формы сначала прочитайте в примере, затем используйте без справки; помощь отмечается отдельно.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Γεια σου, Νίκο!", "Καλημέρα σας. Σας γράφω για το μάθημα.", "Χτες δεν μπόρεσα να έρθω.", "Έχασα το λεωφορείο και άργησα.", "Μπορείτε να μου στείλετε την άσκηση;", "Δεν μπορώ την Τρίτη, αλλά μπορώ την Τετάρτη.", "Περιμένω την απάντησή σας.", "Ευχαριστώ πολύ για τη βοήθεια."], "review_plan": {"days": [7, 14, 28], "rule": "Новая попытка без модели. Помощь отмечать отдельно; D7/D28 не заменять тем же заученным ответом.", "item_ids": ["U-A2-015-I17", "U-A2-015-I18", "U-A2-015-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Α2: Κατοικία, Ελεύθερος χρόνος, Κοινωνικές σχέσεις, Υγεία, Εκπαίδευση/επαγγελματικός χώρος; production goals", "source_id": "CP06-A2-S003", "checked_on": "2026-10-18", "claim_scope": "Everyday communicative domains only; original lessons and score thresholds are project choices", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR"}, {"anchor": "§6.2 ποιόν ενέργειας; κλίση λύνω; αύξηση", "source_id": "N405", "checked_on": "2026-10-14", "claim_scope": "Retained checkpoint evidence for aspect and familiar active past morphology only; not all lexical forms or A2 placement", "evidence_type": "RETAINED_PRIMARY_GRAMMAR_INSPECTION"}, {"anchor": "§5.2 cause and temporal clauses", "source_id": "N404", "checked_on": "2026-10-14", "claim_scope": "Retained checkpoint evidence for cause/time linking; not institutional approval of original messages", "evidence_type": "RETAINED_PRIMARY_GRAMMAR_INSPECTION"}], "active_recall": ["U-A2-015-I08", "U-A2-015-I09", "U-A2-015-I20"], "prerequisites": ["A1-W01", "A2-G03", "A2-G11"], "reading_tasks": ["U-A2-015-I10", "U-A2-015-I11"], "transfer_task": "U-A2-015-I16", "writing_tasks": ["U-A2-015-I14"], "competency_ids": ["A2-W01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; no observed learner mastery or full source certification", "speaking_tasks": ["U-A2-015-I15"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION", "PRAGMATICS_REGISTER", "RETENTION", "SELF_REPAIR", "SYNTAX", "TRANSFER", "UNSUPPORTED_INFERENCE", "VERB_TENSE"], "guided_practice": ["U-A2-015-I02", "U-A2-015-I03", "U-A2-015-I04", "U-A2-015-I05", "U-A2-015-I06", "U-A2-015-I07"], "listening_tasks": ["U-A2-015-I12", "U-A2-015-I13"], "reading_text_el": "Καλημέρα σας,\\nΣας γράφω για το μάθημα ελληνικών της Τρίτης. Χτες δεν μπόρεσα να έρθω γιατί έχασα το λεωφορείο. Διάβασα το μήνυμα της ομάδας, αλλά δεν βρήκα την άσκηση για το σπίτι. Μπορείτε να μου στείλετε την άσκηση; Την επόμενη Τρίτη θα έρθω κανονικά. Δεν ζητώ να αλλάξει η ώρα του μαθήματος.\\nΕυχαριστώ πολύ,\\nΈλενα", "learning_outcome": "Самостоятельно написать новое письмо,сохранив регистр и различая просьбу и подтверждение", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "controlled": "All meaning-changing mistakes corrected after independent first attempt; project provisional threshold ≥80% controlled tasks", "production": "I14/I15/I16 all required facts and intent clear without model; D7/D28 independent transfer required"}, "vocabulary_items": [{"lemma": "μήνυμα", "stress": "μήνυμα", "example": "Γράφω ένα μήνυμα στον φίλο μου.", "inflection": "το μήνυμα / τα μηνύματα", "meaning_ru": "сообщение", "collocations": ["γράφω ένα μήνυμα"]}, {"lemma": "απάντηση", "stress": "απάντηση", "example": "Περιμένω την απάντησή σας.", "inflection": "η απάντηση / οι απαντήσεις", "meaning_ru": "ответ", "collocations": ["περιμένω την απάντηση"]}, {"lemma": "στέλνω", "stress": "στέλνω", "example": "Μπορείτε να μου στείλετε την άσκηση;", "inflection": "στέλνω — έστειλα — θα στείλω", "meaning_ru": "отправлять", "collocations": ["στέλνω την άσκηση"]}, {"lemma": "χάνω", "stress": "χάνω", "example": "Χτες έχασα το λεωφορείο.", "inflection": "χάνω — έχασα", "meaning_ru": "терять/пропускать", "collocations": ["χάνω το λεωφορείο"]}], "diagnostic_item_ids": ["U-A2-015-I01"], "learning_objectives": ["Извлечь адресата,цель и необходимые факты короткого сообщения", "Составить связный запрос с прошлым событием и точным вопросом", "Самостоятельно написать новое письмо,сохранив регистр и различая просьбу и подтверждение"], "microcompetency_ids": ["U-A2-015-MC01", "U-A2-015-MC02", "U-A2-015-MC03"], "prerequisite_support": {"A1-W01": "U-A1-015:short personal note and addressee; I01 entry probe", "A2-G03": "U-A2-001:familiar past forms; I01 then repair prior lesson", "A2-G11": "U-A2-007:short linked propositions; retain original prerequisite; explicit linkers taught here"}, "primary_competencies": ["A2-W01"], "estimated_active_minutes": 80}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
