483	source_claim	CP08-INHERITED-U-A1-010-I05-03	30f17568f975071163286746e023ee409968441ffd0f72176acc4f3fb45f806f	\N	{"record": {"claim": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A1-010-I05-03", "item_ids": ["U-A1-010-I05"], "source_id": "N404", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A1-010-I05.json", "sha256": "e64024af83da950903a94c529a92c4e94ee4fdd4f4ce70a819d0b972a4a8825c"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "§5.2 άρνηση δε(ν)/μη(ν); τελικό ν", "source_id": "N404", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}}, "claim_id": "CP08-INHERITED-U-A1-010-I05-03", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3142	unit	U-A2-016	f1b336b97bcc8fde8045cca1bb363ea0110ca94c4cfff16b62a8a0e2f09e970b	core	{"unit_id": "U-A2-016", "content_hash": "f1b336b97bcc8fde8045cca1bb363ea0110ca94c4cfff16b62a8a0e2f09e970b", "canonical_path": "GreekOS_Academic_Corpus/units/U-A2-016.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "COMPLETE_NOT_INDEPENDENT", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A2-016-RUBRIC"], "unit_id": "U-A2-016", "version": "0.1.0", "title_ru": "Ударение, границы слов и вопросительная интонация", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "В этом уроке различаем три вещи: ударение внутри слова, объединение слов в смысловые группы и мелодику всей реплики. Правильно поставить значок на письме ещё не означает правильно произнести слово. И наоборот, неточная ASR-транскрипция не доказывает ошибку произношения. Для проверки нужен слышимый ответ ученика и эталон, прошедший проверку носителем. До появления аудио мы выполняем письменную подготовку, но не выставляем акустический балл.\\nУдарная гласная выделяется внутри слова. В общеупотребительных формах основное словесное ударение располагается в пределах трёх последних слогов. Правило ограничивает возможное место, но не позволяет угадать его у любого нового слова. При изменении формы проверяйте ударение заново: γράφω — έγραψα — γράψαμε; μάθημα — μαθήματα. Не выводите из первой пары правило «все прошедшие формы получают έ-»: формы изучаются вместе с глагольной моделью. Входная проверка опирается на знакомые прошедшие формы A2-G03; если смысл и форма не освоены, сначала повторите их.\\nУдобная последовательность: найдите гласную с τόνος, произнесите слово целиком, затем в короткой фразе. Не делайте каждый слог одинаково сильным. В письменной практике έγραψα нельзя заменить εγράψα: ударение является частью формы. В παράδειγμα и παραδείγματα число слогов и место ударения требуют внимания; в этом уроке используем только уже введённые пары, а новое слово проверяем по словарю.\\nВ речи пробелы не звучат как обязательные паузы. Συνδέστε «το μάθημα» и «στην αίθουσα» в смысловые группы. Это не разрешение терять артикль в письме. Полезная разметка для репетиции: Το μάθημα / αρχίζει στις έξι. Косая черта — наша педагогическая отметка группировки, не обязательная пауза носителя и не знак греческой орфографии. Δεν / αρχίζει может неоправданно отделять отрицание от того, что оно отрицает; начинайте с цельного Δεν αρχίζει στις έξι.\\nОдинаковая последовательность слов может звучать как сообщение или вопрос: Έρχεται αύριο. — Έρχεται αύριο; В греческом вопрос обозначается знаком ;. Не учим универсальное правило «каждый вопрос всегда заканчивается подъёмом»: реальные контуры зависят от типа вопроса, фокуса и контекста. Πότε έρχεται; запрашивает время, а Έρχεται αύριο; проверяет предположение. Чтобы проверить интонацию, слушатель должен различить намерение без подсказки пунктуацией. До проверенной записи это задание остаётся заблокированным.\\nПрактика идёт от письменного распознавания формы к произнесению пары и короткой новой реплике. Сначала разрешены пометки ударения; затем уберите их и произнесите ответ в ситуации. Обратная связь отдельно отмечает словесное ударение, понятность группировки и вопросительное намерение. Акцент сам по себе не основание штрафа, если сообщение понятно. При сомнении слушателя попросите повторить один фрагмент и сохраните факт помощи. Через D7/D28 проверьте перенос на новые сочетания известных форм.", "cefr_level": "A2", "time_basis": "AUTHOR_PLANNING_ESTIMATE_NOT_PILOTED", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["γράφω — έγραψα — γράψαμε", "μάθημα — μαθήματα", "Το μάθημα αρχίζει στις έξι.", "Δεν αρχίζει στις έξι.", "Έρχεται αύριο.", "Έρχεται αύριο;", "Πότε έρχεται;"], "review_plan": {"days": [7, 28], "rule": "New stimulus, no model shown before attempt; assistance recorded; corrected answer alone is not independent retention", "item_ids": ["U-A2-016-I14", "U-A2-016-I15"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "§2.3 α–β (lines33–39)", "source_id": "CP08-PHON", "checked_on": "2026-10-21", "claim_scope": "Bounded descriptor or phonological principle only; original examples, lesson sequence, rubrics and thresholds are not official"}], "active_recall": ["U-A2-016-I09"], "prerequisites": ["A1-P02", "A2-G03"], "reading_tasks": ["U-A2-016-I08"], "transfer_task": "U-A2-016-I13", "writing_tasks": ["U-A2-016-I06", "U-A2-016-I09", "U-A2-016-I12"], "assessment_map": [{"kind": "mcq", "item_id": "U-A2-016-I01", "objective": "Различить письменное и акустическое свидетельство", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "mcq", "item_id": "U-A2-016-I02", "objective": "Различить письменное и акустическое свидетельство", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "short", "item_id": "U-A2-016-I03", "objective": "Различить письменное и акустическое свидетельство", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "short", "item_id": "U-A2-016-I04", "objective": "Различить письменное и акустическое свидетельство", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as liste