3143	unit	U-A2-017	3a22488a3d8063c3037bf5fe1ce3aadaccae1d26f21fef233adc6461c47e5e99	core	{"unit_id": "U-A2-017", "content_hash": "3a22488a3d8063c3037bf5fe1ce3aadaccae1d26f21fef233adc6461c47e5e99", "canonical_path": "GreekOS_Academic_Corpus/units/U-A2-017.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "COMPLETE_NOT_INDEPENDENT", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A2-017-RUBRIC"], "unit_id": "U-A2-017", "version": "0.1.0", "title_ru": "Бытовой диалог: запрос, альтернатива и итог", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Короткий диалог содержит не только факты, но и действия: человек просит, сотрудник уточняет, предлагает замену, собеседник соглашается или отказывается. Сначала установите цель разговора. Затем отделите первоначальное желание от достигнутой договорённости. Если человек хотел вторник, но согласился на четверг, в заметке об итоге нужен четверг. Одного узнавания знакомого слова «вторник» недостаточно.\\nНа входе повторите бытовую лексику A2-V01 и понимание простых вопросов A1-L01. Слово ραντεβού здесь означает заранее согласованную встречу или приём. Вопрос Υπάρχει ώρα την Τρίτη; ещё не доказывает запись. Ответ Την Τρίτη δεν γίνεται исключает этот вариант; Μπορείτε την Πέμπτη; предлагает альтернативу. Только последующее Ναι, την Πέμπτη στις δέκα подтверждает выбор в рамках учебной ситуации.\\nРаботайте с тремя колонками: запрос — препятствие — итог. Причина отказа может быть названа или отсутствовать. Не дополняйте «нет свободного времени» догадками о болезни, ремонте или празднике. Уточняйте, кто должен сделать следующий шаг: Θα σας τηλεφωνήσω говорит сотрудник о своём действии, Τηλεφωνήστε μας ζητά звонка от клиента. Эти фразы вводятся в контексте, не как полный урок будущего времени и повелительного наклонения.\\nВ магазине различайте отсутствие товара, отсутствие нужного размера и отсутствие нужного цвета. Если продавец предлагает синюю сумку вместо чёрной, согласие на синий цвет не означает изменение количества. В заданиях новые слова объясняются до первого прослушивания, но итоговая договорённость не показывается. При повторном прослушивании ищите точное место изменения.\\nПересказ должен сохранять факты, но не обязан копировать реплики. «Έκλεισα ραντεβού για την Πέμπτη στις δέκα» допустимо после явного подтверждения. Если разговор прервался раньше, скажите, что встреча ещё не подтверждена. Не путайте неуслышанный ответ с отказом. В самостоятельной роли задайте вопрос, отреагируйте на неожиданную замену и подтвердите результат или вежливо откажитесь.\\nДля проверки аудирования необходимо реальное аудио с двумя различимыми голосами. На подготовительном чтении отмечайте участников, а при прослушивании скрывайте имена ролей и транскрипт. Разные виды помощи фиксируются отдельно. На D7/D28 меняются предмет разговора и данные: оцениваем перенос стратегии, а не запоминание диалога.", "cefr_level": "A2", "time_basis": "AUTHOR_PLANNING_ESTIMATE_NOT_PILOTED", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Θα ήθελα ένα ραντεβού την Τρίτη.", "Την Τρίτη δεν υπάρχει διαθέσιμη ώρα.", "Μπορείτε την Πέμπτη στις δέκα;", "Ναι, την Πέμπτη στις δέκα.", "Δεν έχουμε μαύρη τσάντα.", "Τότε θα πάρω την μπλε."], "review_plan": {"days": [7, 28], "rule": "New stimulus, no model shown before attempt; assistance recorded; corrected answer alone is not independent retention", "item_ids": ["U-A2-017-I12", "U-A2-017-I13"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Κατανόηση προφορικού λόγου, paragraphs 1–2 (lines87–89)", "source_id": "CP08-A2", "checked_on": "2026-10-21", "claim_scope": "Bounded descriptor or phonological principle only; original examples, lesson sequence, rubrics and thresholds are not official"}], "active_recall": ["U-A2-017-I08"], "prerequisites": ["A1-L01", "A2-V01"], "reading_tasks": ["U-A2-017-I07"], "transfer_task": "U-A2-017-I11", "writing_tasks": ["U-A2-017-I09"], "assessment_map": [{"kind": "mcq", "item_id": "U-A2-017-I01", "objective": "Понять цель и участников", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-A2-017-I02", "objective": "Понять цель и участников", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_short", "item_id": "U-A2-017-I03", "objective": "Понять цель и участников", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-A2-017-I04", "objective": "Понять цель и участников", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_short", "item_id": "U-A2-017-I05", "objective": "Понять цель и участников", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-A2-017-I06", "objective": "Отличить предложение от итоговой договорённости", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "read_mcq", "item_id": "U-A2-017-I07", "objective": "Отличить предложение от итоговой договорённости", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "short", "item_id": "U-A2-017-I08", "objective": "Отличить предложение от итоговой договорённости", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "open", "item_id": "U-A2-017-I09", "objective": "Отличить предложение от итоговой договорённости", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "speak", "item_id": "U-A2-017-I10", "objective": "Перенести уточнение и подтверждение в новую ситуацию", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-A2-017-I11", "objective": "Перенести уточнение и подтверждение в новую ситуацию", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-A2-017-I12", "objective": "Перенести уточнение и подтверждение в новую ситуацию", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "speak", "item_id": "U-A2-017-I13", "objective": "Перенести уточнение и подтверждение в новую ситуацию", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}], "competency_ids": ["A2-L01"], "coverage_claim": "TEXT_ROUTE_AUTHORED_AUDIO_AND_INDEPENDENT_QA_BLOCKED", "speaking_tasks": ["U-A2-017-I10", "U-A2-017-I13"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION", "FACT_SUBSTITUTION", "ASR_UNCERTAIN", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A2-017-I02", "U-A2-017-I03", "U-A2-017-I04", "U-A2-017-I05", "U-A2-017-I06", "U-A2-017-I07"], "listening_tasks": ["U-A2-017-I02", "U-A2-017-I03", "U-A2-017-I04", "U-A2-017-I05", "U-A2-017-I06", "U-A2-017-I11", "U-A2-017-I12"], "mastery_contract": {"open": "Every task-specific content criterion met independently, intelligible response; quote evidence per criterion", "closed": "At least80% on fresh controlled tasks, no uncorrected critical fact errors; project heuristic only", "listening": "Requires verified media, transcript hidden, play count logged", "retention": "Independent D7 and D28; one hint makes assisted evidence", "pronunciation": "Requires actual recording and listening; ASR text alone insufficient"}, "reading_texts_el": [], "vocabulary_items": [{"lemma": "το ραντεβού", "stress": "το ραντεβού", "example": "Έχω ραντεβού την Πέμπτη.", "inflection": "неизменяемое: τα ραντεβού", "meaning_ru": "согласованная встреча", "collocations": ["Έχω ραντεβού την Πέμπτη."]}, {"lemma": "διαθέσιμος", "stress": "διαθέσιμος", "example": "Υπάρχει διαθέσιμη ώρα;", "inflection": "διαθέσιμη / διαθέσιμο", "meaning_ru": "доступный", "collocations": ["Υπάρχει διαθέσιμη ώρα;"]}, {"lemma": "η τσάντα", "stress": "η τσάντα", "example": "Θα πάρω την μπλε τσάντα.", "inflection": "την τσάντα / οι τσάντες", "meaning_ru": "сумка", "collocations": ["Θα πάρω την μπλε τσάντα."]}], "diagnostic_item_ids": ["U-A2-017-I01"], "learning_objectives": ["Понять цель и участников", "Отличить предложение от итоговой договорённости", "Перенести уточнение и подтверждение в новую ситуацию"], "prerequisite_support": {"A1-L01": "Use primary unit from CONTENT_Production_Register_96.csv; if entry task fails, reteach prerequisite and retry on a fresh example before target assessment", "A2-V01": "Use primary unit from CONTENT_Production_Register_96.csv; if entry task fails, reteach prerequisite and retry on a fresh example before target assessment"}, "primary_competencies": ["A2-L01"], "estimated_active_minutes": 70}}	fa1d2338-6c24-4ed0-a2