3144	unit	U-A2-018	3cb44a0d9bb2404e6310a188e928dd7ec763c637f1a79b4520b4c2927f5e70c1	core	{"unit_id": "U-A2-018", "content_hash": "3cb44a0d9bb2404e6310a188e928dd7ec763c637f1a79b4520b4c2927f5e70c1", "canonical_path": "GreekOS_Academic_Corpus/units/U-A2-018.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "COMPLETE_NOT_INDEPENDENT", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A2-018-RUBRIC"], "unit_id": "U-A2-018", "version": "0.1.0", "title_ru": "Сообщения и инструкции: порядок, условие, следующий шаг", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "В инструкции сначала найдите конечную цель: получить материалы, войти в помещение, отправить сообщение. Затем выделите действия в порядке выполнения. Πρώτα — сначала, μετά — затем, στο τέλος — в конце. Слова помогают, но слушайте содержание: сначала взять номер, затем ждать — не то же самое, что сразу подойти к стойке. Урок использует учебные процедуры, а не действующие правила учреждений.\\nПредпосылки — A1-L02 и связки A2-G07. Если ученик не различает время и место, сначала повторяем их на коротком сообщении. Затем вводим трёхшаговую инструкцию. В записи основные действия следуют в логичном порядке без сложных отступлений. Сделайте заметку глагол + объект: γράφω όνομα, παίρνω αριθμό, περιμένω. Запись не обязана повторять форму обращения сотрудника.\\nОтделяйте обязательный шаг от условного: Αν δεν λάβετε μήνυμα, τηλεφωνήστε μας означает звонить при отсутствии сообщения. Это не безусловное «всем звонить». Μην κλείσετε τη σελίδα запрещает закрывать страницу на данном этапе. Нельзя игнорировать отрицание, даже если глагол знаком. Мы не оцениваем юридическую правильность процедуры: только соблюдение условий вымышленной задачи.\\nПроверяйте исполнителя и предел инструкции. «Στείλτε μας το αρχείο» — действие адресата; «Θα σας στείλουμε μήνυμα» — обещание отправителя. Получение сообщения ещё не доказывает успешное окончание всех этапов, если это не сказано. Если часть звука потеряна, отметьте конкретный неизвестный шаг и запросите повтор. Не заполняйте пробел обычным, но не названным действием.\\nПосле двух прослушиваний перескажите последовательность другому человеку. Убираем несущественные приветствия, сохраняем порядок, отрицание и условие. Проверяем понимание также действием на безопасной имитации: разложить карточки шагов или выбрать следующее действие. Не выполнять реальные платежи и не вводить настоящие документы.\\nОбратная связь указывает первое место, где последовательность изменилась, затем просит исправить её самостоятельно. Случайная перестановка двух независимых действий не ошибка, если текст допускает оба порядка; наши задания с единственным ключом явно обозначают последовательность. На D7/D28 используются новые инструкции. До готового аудио чтение сценария остаётся отдельным подготовительным режимом.", "cefr_level": "A2", "time_basis": "AUTHOR_PLANNING_ESTIMATE_NOT_PILOTED", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Πρώτα γράψτε το όνομά σας.", "Μετά πάρτε έναν αριθμό.", "Περιμένετε να σας καλέσουμε.", "Αν δεν λάβετε μήνυμα, τηλεφωνήστε μας.", "Μην κλείσετε τη σελίδα."], "review_plan": {"days": [7, 28], "rule": "New stimulus, no model shown before attempt; assistance recorded; corrected answer alone is not independent retention", "item_ids": ["U-A2-018-I12", "U-A2-018-I13"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Κατανόηση προφορικού λόγου, paragraphs 1–2 (lines87–89)", "source_id": "CP08-A2", "checked_on": "2026-10-21", "claim_scope": "Bounded descriptor or phonological principle only; original examples, lesson sequence, rubrics and thresholds are not official"}], "active_recall": ["U-A2-018-I08"], "prerequisites": ["A1-L02", "A2-G07"], "reading_tasks": ["U-A2-018-I07"], "transfer_task": "U-A2-018-I11", "writing_tasks": ["U-A2-018-I09"], "assessment_map": [{"kind": "mcq", "item_id": "U-A2-018-I01", "objective": "Восстановить последовательность", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-A2-018-I02", "objective": "Восстановить последовательность", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_short", "item_id": "U-A2-018-I03", "objective": "Восстановить последовательность", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-A2-018-I04", "objective": "Восстановить последовательность", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-A2-018-I05", "objective": "Восстановить последовательность", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-A2-018-I06", "objective": "Сохранить условие и отрицание", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "read_mcq", "item_id": "U-A2-018-I07", "objective": "Сохранить условие и отрицание", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "short", "item_id": "U-A2-018-I08", "objective": "Сохранить условие и отрицание", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "open", "item_id": "U-A2-018-I09", "objective": "Сохранить условие и отрицание", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "speak", "item_id": "U-A2-018-I10", "objective": "Передать инструкцию и уточнить пробел", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-A2-018-I11", "objective": "Передать инструкцию и уточнить пробел", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-A2-018-I12", "objective": "Передать инструкцию и уточнить пробел", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-A2-018-I13", "objective": "Передать инструкцию и уточнить пробел", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}], "competency_ids": ["A2-L02"], "coverage_claim": "TEXT_ROUTE_AUTHORED_AUDIO_AND_INDEPENDENT_QA_BLOCKED", "speaking_tasks": ["U-A2-018-I10"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION", "FACT_SUBSTITUTION", "ASR_UNCERTAIN", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A2-018-I02", "U-A2-018-I03", "U-A2-018-I04", "U-A2-018-I05", "U-A2-018-I06", "U-A2-018-I07"], "listening_tasks": ["U-A2-018-I02", "U-A2-018-I03", "U-A2-018-I04", "U-A2-018-I05", "U-A2-018-I06", "U-A2-018-I11", "U-A2-018-I12", 