3145	unit	U-A2-019	884d56e7ddd0a2569668764371fca45b5cd5dfd9d44e0e350b2a088107a0d9a8	core	{"unit_id": "U-A2-019", "content_hash": "884d56e7ddd0a2569668764371fca45b5cd5dfd9d44e0e350b2a088107a0d9a8", "canonical_path": "GreekOS_Academic_Corpus/units/U-A2-019.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "COMPLETE_NOT_INDEPENDENT", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A2-019-RUBRIC"], "unit_id": "U-A2-019", "version": "0.1.0", "title_ru": "Передать другому человеку условия короткого объявления", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Посредничество в этом уроке — помочь конкретному человеку понять нужные условия объявления. Это не перевод каждого слова и не свободное сочинение. Сначала выясните, что нужно адресату: время, место, цена, запись или список вещей. Затем найдите эти факты в тексте. Если друг хочет прийти с ребёнком, а возраст в объявлении не указан, нельзя обещать участие ребёнка.\\nПредпосылки — понимание короткого текста A2-R01 и связное простое высказывание A2-SP01. Входное задание проверяет выделение времени и места. Если ученик просто копирует весь текст, попросите убрать приветствия и оставить три нужных поля. При этом нельзя удалить ограничение μόνο, προθεσμία или условие εγγραφή απαραίτητη: коротко не означает неточно.\\nСравните «Είσοδος δωρεάν» и «Απαραίτητη η εγγραφή». Бесплатный вход не отменяет предварительной записи. «Φέρτε νερό» означает взять воду с собой, а не купить воду у организатора. «Σε περίπτωση βροχής» вводит условие; запасное место не заменяет основное при любой погоде. В наших объявлениях факты вымышлены, чтобы тренировать язык без актуальных юридических или организационных обещаний.\\nПодстройте передачу информации под адресата. Друг, который уже знает название мероприятия, может не нуждаться в повторе заголовка, но должен узнать время и необходимость записи. Незнакомому человеку полезно сначала назвать событие. Допустимы разные греческие формулировки: «Χρειάζεται εγγραφή» и «Πρέπει να κάνεις εγγραφή» передают одно условие. Не требуем дословной копии и оцениваем точность смысла.\\nНеизвестное обозначайте прямо: «Δεν γράφει πόσο διαρκεί». Если адресат спрашивает длительность, которой нет, предложите уточнить её у организатора, а не вычисляйте по похожим мероприятиям. Отделяйте факты объявления от вашего совета. «Καλύτερα να ρωτήσεις» — совет, а не новое условие участия.\\nПрактикуйте письменное сообщение, устный пересказ и ответ на уточняющий вопрос. Сначала разрешено выделять факты цветом; самостоятельный перенос выполняется с новым объявлением и без модели ответа. D7/D28 проверяют новые условия, в том числе отмену или перенос. Содержательные критерии оцениваются отдельно от произношения: для последнего нужна запись; чтение вслух известного текста не заменяет самостоятельный пересказ.", "cefr_level": "A2", "time_basis": "AUTHOR_PLANNING_ESTIMATE_NOT_PILOTED", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Η είσοδος είναι δωρεάν, αλλά χρειάζεται εγγραφή.", "Η συνάντηση είναι το Σάββατο στις δέκα.", "Φέρε νερό μαζί σου.", "Δεν γράφει πόσο διαρκεί.", "Αν βρέχει, θα συναντηθούμε στην αίθουσα."], "review_plan": {"days": [7, 28], "rule": "New stimulus, no model shown before attempt; assistance recorded; corrected answer alone is not independent retention", "item_ids": ["U-A2-019-I11", "U-A2-019-I12"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Κατανόηση προφορικού λόγου, paragraphs 1–2 (lines87–89)", "source_id": "CP08-A2", "checked_on": "2026-10-21", "claim_scope": "Bounded descriptor or phonological principle only; original examples, lesson sequence, rubrics and thresholds are not official"}], "active_recall": ["U-A2-019-I06"], "prerequisites": ["A2-R01", "A2-SP01"], "reading_tasks": ["U-A2-019-I01", "U-A2-019-I02", "U-A2-019-I05", "U-A2-019-I09"], "transfer_task": "U-A2-019-I10", "writing_tasks": ["U-A2-019-I04", "U-A2-019-I06", "U-A2-019-I07", "U-A2-019-I10", "U-A2-019-I11"], "assessment_map": [{"kind": "read_mcq", "item_id": "U-A2-019-I01", "objective": "Выделить нужные адресату условия", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "read_mcq", "item_id": "U-A2-019-I02", "objective": "Выделить нужные адресату условия", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "short", "item_id": "U-A2-019-I03", "objective": "Выделить нужные адресату условия", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "open", "item_id": "U-A2-019-I04", "objective": "Выделить нужные адресату условия", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "read_mcq", "item_id": "U-A2-019-I05", "objective": "Сохранить обязательность и неизвестность", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "open", "item_id": "U-A2-019-I06", "objective": "Сохранить обязательность и неизвестность", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "open", "item_id": "U-A2-019-I07", "objective": "Сохранить обязательность и неизвестность", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "speak", "item_id": "U-A2-019-I08", "objective": "Сохранить обязательность и неизвестность", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "read_mcq", "item_id": "U-A2-019-I09", "objective": "Передать новый текст своими словами", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "open", "item_id": "U-A2-019-I10", "objective": "Передать новый текст своими словами", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "open", "item_id": "U-A2-019-I11", "objective": "Передать новый текст своими словами", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "speak", "item_id": "U-A2-019-I12", "objective": "Передать новый текст своими словами", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}], "competency_ids": ["A2-M01"], "coverage_claim": "TEXT_ROUTE_AUTHORED_AUDIO_AND_INDEPENDENT_QA_BLOCKED", "speaking_tasks": ["U-A2-019-I08", "U-A2-019-I12"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION", "FACT_SUBSTITUTION", "ASR_UNCERTAIN", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A2-019-I02", "U-A2-019-I03", "U-A2-019-I04", "U-A2-019-I05", "U-A2-019-I09"], "listening_tasks": [], "mastery_contract": {"open": "Every task-specific content criterion met independently, intelligible response; quote evidence per criterion", "closed": "At least80% on fresh controlled tasks, no uncorrected critical fact errors; project heuristic only", "listening": "Requires verified media, transcript hidden, play count logged", "retention": "Independent D7 and D28; one hint makes assisted evidence", "pronunciation": "Requires actual recording and listening; ASR text alone insufficient"}, "reading_texts_el": ["Περίπατος στη γειτονιά. Σάββατο, 10:00. Συνάντηση μπροστά στη βιβλιοθήκη. Συμμετοχή δωρεάν. Εγγραφή μέχρι την Πέμπτη. Φέρτε νερό."], "vocabulary_items": [{"lemma": "η εγγραφή", "stress": "η εγγραφή", "example": "Χρειάζεται εγγραφή.", "inflection": "την εγγραφή / οι εγγραφές", "meaning_ru": "запись, регистрация", "collocations": ["Χρειάζεται εγγραφή."]}, {"lemma": "δωρεάν", "stress": "δωρεάν", "example": "Η είσοδος είναι δωρεάν.", "inflection": "наречие", "meaning_ru": "бесплатно", "collocations": ["Η είσοδος είναι δωρεάν."]}, {"lemma": "μαζί", "stress": "μαζί", "example": "Φέρε νερό μαζί σου.", "inflection": "неизменяемое", "meaning_ru": "вместе, с собой в сочетании", "collocations": ["Φέρε νερό μαζί σου."]}], "diagnostic_item_ids": ["U-A2-019-I01"], "learning_objectives": ["Выделить нужные адресату условия", "Сохранить обязательность и неизвестность", "Передать новый текст своими словами"], "prerequisite_support": {"A2-R01": "Use primary unit from CONTENT_Production_Register_96.csv; if entry task fails, reteach prerequisite and retry on a fresh example before target assessment", "A2-SP01": "Use primary unit from CONTENT_Production_Register_96.csv; if entry task fails, reteach prerequisite and retry on a fresh example before target assessment"}, "primary_competencies": ["A2-M01"], "estimated_active_minutes": 70}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
