3146	unit	U-A2-020	fbcd81e145b77e2753fc76117ec4f11c08d1903e125a5c433e858e0579450634	core	{"unit_id": "U-A2-020", "content_hash": "fbcd81e145b77e2753fc76117ec4f11c08d1903e125a5c433e858e0579450634", "canonical_path": "GreekOS_Academic_Corpus/units/U-A2-020.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY"}, "rubrics": ["U-A2-020-RUBRIC"], "unit_id": "U-A2-020", "version": "0.1.0", "title_ru": "Приглашение, отказ, смягчённая просьба и исправление", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "В приглашении нужны действие, время и место: «Θέλεις να πάμε για καφέ την Κυριακή;». Адресат должен понимать, какое решение от него требуется. Между друзьями естественны θέλεις, μπορείς, πάμε; с незнакомым человеком или в более официальном контакте можно выбрать θα θέλατε, μπορείτε. Множественное число здесь может выражать вежливое обращение к одному человеку. Не переключайте εσύ/εσείς внутри короткого сообщения без причины.\\nСогласие должно прояснять договорённость. «Ναι, ευχαρίστως. Στις έξι έξω από το μουσείο;» не только выражает желание, но и проверяет детали. «Ίσως» не является подтверждённым согласием. Если план зависит от работы или транспорта, прямо скажите, когда сможете ответить. Не обещайте прийти, если только собираетесь проверить возможность.\\nОтказывать можно кратко и доброжелательно: благодарность → ясная невозможность → при желании короткая причина или другой вариант. «Ευχαριστώ για την πρόσκληση, αλλά δεν μπορώ το Σάββατο. Μπορώ την Κυριακή». Причина не обязательна и не должна раскрывать личные сведения. Не нужно придумывать болезнь или семейную историю ради вежливости. Предложение другого времени полезно, когда вы действительно хотите встретиться.\\nПросьба отличается от приказа. «Μπορείτε να μιλήσετε λίγο πιο αργά, παρακαλώ;» даёт собеседнику понятное действие. «Θα ήθελα…» — удобная вежливая формула; здесь используем её как знакомый образец, не изучаем всю систему условных форм. Выбор одного слова παρακαλώ сам по себе не гарантирует уместного тона: содержание и ситуация тоже важны.\\nИсправляя ошибку в деталях, сначала обозначьте поправку: «Συγγνώμη, εννοούσα την Πέμπτη, όχι την Τρίτη». Затем повторите правильную договорённость целиком. Это надёжнее, чем сказать только «όχι», после которого непонятно, что отменено. Если ошибку сделал собеседник, можно мягко проверить: «Στις επτά είπαμε, σωστά;». Не приписывайте ему плохих намерений.\\nПеред уроком проверьте простое обращение и обмен временем из A1-PR01/A2-SI01. После образцов закройте их и создайте своё приглашение, отказ и уточнение. В устном задании оценивается реальная запись; текст показывает содержание, но не интонацию. Наша цель — ясная взаимная договорённость, а не единственный обязательный шаблон.", "cefr_level": "A2", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Θέλεις να πάμε μια βόλτα;", "Ευχαριστώ, αλλά δεν μπορώ σήμερα.", "Μπορείτε να το επαναλάβετε, παρακαλώ;", "Συγγνώμη, εννοούσα στις επτά, όχι στις έξι."], "review_plan": {"D7": ["U-A2-020-I10"], "D28": ["U-A2-020-I11"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-A2-020-I10", "U-A2-020-I11"]}, "source_refs": [{"anchor": "Written production100–101; oral interaction104–105", "source_id": "CP08-A2", "checked_on": "2026-10-22", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "active_recall": ["U-A2-020-I07", "U-A2-020-I08"], "prerequisites": ["A1-PR01", "A2-SI01"], "reading_tasks": ["U-A2-020-I02", "U-A2-020-I05"], "transfer_task": "U-A2-020-I09", "writing_tasks": ["U-A2-020-I01", "U-A2-020-I07", "U-A2-020-I11"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-A2-020-I01", "U-A2-020-I02", "U-A2-020-I04"], "objective": "Различать приглашение, согласие, отказ и просьбу"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-A2-020-I03", "U-A2-020-I05", "U-A2-020-I06", "U-A2-020-I10"], "objective": "Выбирать обращение и исправлять детали без двусмысленности"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-A2-020-I07", "U-A2-020-I08", "U-A2-020-I09", "U-A2-020-I11"], "objective": "Самостоятельно согласовать или вежливо отклонить встречу"}], "competency_ids": ["A2-PR01"], "speaking_tasks": ["U-A2-020-I08", "U-A2-020-I09", "U-A2-020-I10"], "entry_probe_ids": ["U-A2-020-I01"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION"], "guided_practice": ["U-A2-020-I02", "U-A2-020-I03", "U-A2-020-I04", "U-A2-020-I05", "U-A2-020-I06"], "listening_tasks": [], "modality_status": "AUDIO_PENDING", "vocabulary_items": [{"lemma": "η πρόσκληση", "stress": "η πρόσκληση", "example": "Ευχαριστώ για την πρόσκληση.", "inflection": "της πρόσκλησης; οι προσκλήσεις", "collocations": ["ευχαριστώ για την πρόσκληση"]}, {"lemma": "ευχαρίστως", "stress": "ευχαρίστως", "example": "Ναι, ευχαρίστως θα έρθω.", "inflection": "άκλιτο", "collocations": ["ναι, ευχαρίστως"]}, {"lemma": "εννοώ", "stress": "εννοώ", "example": "Εννοούσα αύριο, όχι σήμερα.", "inflection": "εννοούσα", "collocations": ["εννοώ την Πέμπτη"]}], "learning_objectives": ["Различать приглашение, согласие, отказ и просьбу", "Выбирать обращение и исправлять детали без двусмысленности", "Самостоятельно согласовать или вежливо отклонить встречу"], "prerequisite_policy": "Diagnose before instruction; failure routes to primary unit(s) from96 register. Authored prerequisite is not evidence of learner mastery. Retry with fresh example.", "primary_competencies": ["A2-PR01"], "estimated_active_minutes": 65}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
