3147	unit	U-B1-001	3a4e2d4f441f4ebc5733cedd140b0927ced4573d72c2157a0e611ec98b3aff05	core	{"unit_id": "U-B1-001", "content_hash": "3a4e2d4f441f4ebc5733cedd140b0927ced4573d72c2157a0e611ec98b3aff05", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-001.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B1-001-RUBRIC"], "unit_id": "U-B1-001", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-B1-001-I02", "U-B1-001-I03", "U-B1-001-I04", "U-B1-001-I05", "U-B1-001-I06", "U-B1-001-I07"], "reception": ["U-B1-001-I08", "U-B1-001-I09", "U-B1-001-I10", "U-B1-001-I11"], "retention": ["U-B1-001-I15", "U-B1-001-I16", "U-B1-001-I17"], "diagnostic": ["U-B1-001-I01"], "production": ["U-B1-001-I12", "U-B1-001-I13", "U-B1-001-I14"]}, "title_ru": "Что будет уже сделано к сроку: συντελεσμένος μέλλοντας", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Форма θα έχω + неизменяемая форма вроде γράψει показывает результат, завершённый к будущему ориентиру: Μέχρι την Παρασκευή θα έχω γράψει την αναφορά. Изменяется έχω: θα έχω, θα έχεις, θα έχει, θα έχουμε, θα έχετε, θα έχουν. Слово γράψει здесь не согласуется с лицом или числом. Та же неизменяемая часть встречается в έχω γράψει и είχα γράψει, но временная точка различается: результат сейчас, до прошлого момента, до будущего момента.\\n\\nСравните три взгляда на одну работу. Αύριο στις έξι θα γράφω την αναφορά — в шесть работа будет в процессе. Αύριο θα γράψω την αναφορά — действие представлено как целое. Μέχρι αύριο στις έξι θα έχω γράψει την αναφορά — к шести результат будет достигнут. Простое будущее тоже может употребляться со сроком. Поэтому наличие μέχρι не делает остальные формы всегда неграмматичными: в упражнениях ниже прямо требуется подчеркнуть предшествующее завершение.\\n\\nЧастотные сочетания: θα έχω τελειώσει, θα έχουμε στείλει, θα έχει φύγει. Отрицание: δεν θα έχω τελειώσει. Вопрос: Θα έχεις στείλει το μήνυμα μέχρι τότε; Не нужно добавлять второе θα перед неизменяемой частью. В учебных переговорах отделяйте подтверждённый срок от предположения: Ελπίζω ότι θα έχω τελειώσει… выражает надежду, а не гарантию. Узел дополняет исходный B1-G05: это новая явная микроцель, а не молчаливая замена perfect/pluperfect.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Μέχρι τις οκτώ θα έχω τελειώσει τη δουλειά.", "Όταν φτάσεις, θα έχουμε ετοιμάσει το φαγητό.", "Αύριο στις οκτώ θα δουλεύω ακόμη.", "Αύριο θα στείλω την αίτηση.", "Δεν θα έχουν φύγει μέχρι τότε."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B1-001-I15", "U-B1-001-I16", "U-B1-001-I17"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF10; V226 печатные290/292, V234 PDF30", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Goal-oriented cooperation / correspondence, B1; грамматическая последовательность по историческому AUTH", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "PDF30, ответы к290–291", "source_id": "V234", "checked_on": "2026-10-13", "claim_scope": "Подтверждает присутствие трёх будущих форм в ΚΛΙΚ B1", "evidence_type": "PUBLISHER_PREVIEW"}], "active_recall": ["U-B1-001-I06", "U-B1-001-I07"], "prerequisites": ["A2-G03", "A2-G05"], "reading_tasks": ["U-B1-001-I08", "U-B1-001-I09"], "transfer_task": "U-B1-001-I14", "writing_tasks": ["U-B1-001-I12"], "competency_ids": ["B1-G05", "B1-G03", "B1-W01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B1-001-I13"], "errors_taxonomy": ["VERB_ASPECT", "VERB_TENSE", "CONTENT_OMISSION"], "guided_practice": ["U-B1-001-I02", "U-B1-001-I03", "U-B1-001-I04", "U-B1-001-I05"], "listening_tasks": ["U-B1-001-I10", "U-B1-001-I11"], "learning_outcome": "Выразить ожидаемый результат к будущему сроку через θα έχω + совершенную форму", "vocabulary_items": [{"lemma": "τελειώνω", "stress": "τελειώνω", "example": "Θα έχω τελειώσει την αναφορά.", "inflection": "τελείωσα; έχω τελειώσει", "meaning_ru": "заканчивать", "collocations": ["τελειώνω την αναφορά"]}, {"lemma": "προθεσμία", "stress": "προθεσμία", "example": "Η προθεσμία είναι την Παρασκευή.", "inflection": "η προθεσμία, οι προθεσμίες", "meaning_ru": "крайний срок", "collocations": ["μέχρι την προθεσμία"]}, {"lemma": "στέλνω", "stress": "στέλνω", "example": "Θα έχουμε στείλει την αίτηση.", "inflection": "έστειλα; έχω στείλει", "meaning_ru": "отправлять", "collocations": ["στέλνω την αίτηση"]}, {"lemma": "μέχρι τότε", "stress": "μέχρι τότε", "example": "Μέχρι τότε θα έχω επιστρέψει.", "inflection": "наречное сочетание", "meaning_ru": "к тому моменту", "collocations": ["θα έχω τελειώσει μέχρι τότε"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B1-001-I01"], "learning_objectives": ["Выразить ожидаемый результат к будущему сроку через θα έχω + совершенную форму", "Различить процесс, целое событие и достигнутый к сроку результат", "Согласовать новый срок с проверяемым результатом"], "microcompetency_ids": ["U-B1-001-MC01", "U-B1-001-MC02", "U-B1-001-MC03"], "primary_competencies": ["B1-G05"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
