519	source_claim	CP08-INHERITED-U-A1-010-I17-03	653ff4eed7eec329fb82b58eccbb9336ce3868abf2ac5b419ff5fd508102b2e5	\N	{"record": {"claim": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A1-010-I17-03", "item_ids": ["U-A1-010-I17"], "source_id": "N404", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A1-010-I17.json", "sha256": "0c3d2228e48e983427d3acf8e2d41fc8c25b3744402503ec83ed8998f512464d"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "§5.2 άρνηση δε(ν)/μη(ν); τελικό ν", "source_id": "N404", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}}, "claim_id": "CP08-INHERITED-U-A1-010-I17-03", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3148	unit	U-B1-002	690f5a19a037d7e3ec2b858241dd5ad2c4bb58edc6048f2c4263cedc9e030788	core	{"unit_id": "U-B1-002", "content_hash": "690f5a19a037d7e3ec2b858241dd5ad2c4bb58edc6048f2c4263cedc9e030788", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-002.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B1-002-RUBRIC"], "unit_id": "U-B1-002", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-B1-002-I02", "U-B1-002-I03", "U-B1-002-I04", "U-B1-002-I05", "U-B1-002-I06"], "reception": ["U-B1-002-I07", "U-B1-002-I08", "U-B1-002-I09", "U-B1-002-I10"], "retention": ["U-B1-002-I14", "U-B1-002-I15", "U-B1-002-I16"], "diagnostic": ["U-B1-002-I01"], "production": ["U-B1-002-I11", "U-B1-002-I12", "U-B1-002-I13"]}, "title_ru": "Фон и событие: παρατατικός и αόριστος", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "В рассказе выбор вида показывает, как говорящий представляет действие. Παρατατικός описывает разворачивающийся процесс, повторение или фон: Διάβαζα όταν χτύπησε το τηλέφωνο. Αόριστος представляет событие целиком: Διάβασα το μήνυμα και απάντησα. Длительность сама по себе не определяет время: Έμεινα εκεί τρία χρόνια охватывает весь завершённый период, хотя он длинный. Κάθε μέρα часто поддерживает повторительный фон, но не заменяет понимания контекста.\\nДля γράφω сравните έγραφα и έγραψα; для διαβάζω — διάβαζα и διάβασα. Не образуйте все формы заменой одной буквы: έβλεπα/είδα имеют разные основы. В прошедшем множественного γράφαμε/γράψαμε начальное έ- обычно отсутствует, поскольку меняется место ударения. Учите звучащую форму, а не механически добавляйте аугмент.\\nВ предложении Όταν έφτασα, η Άννα μαγείρευε приготовление уже шло в момент прихода; оно не объявлено завершённым. В Η Άννα μαγείρεψε και έφυγε представлены два целых события. Фон не означает, что действие никогда не закончилось: просто конец не находится в фокусе. Для проверки спросите: мы описываем обстановку или продвигаем цепочку событий? В собственном рассказе допустимы разные ракурсы при сохранении смысла. Ключ с единственным ответом используйте только там, где ракурс явно задан.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Περίμενα όταν άρχισε η βροχή.", "Περίμενα μισή ώρα και μετά έφυγα.", "Κάθε βράδυ έβλεπα τους φίλους μου.", "Χτες είδα τη Δανάη μόνο για λίγο."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B1-002-I14", "U-B1-002-I15", "U-B1-002-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF9–11", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction B1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-B1-002-I05", "U-B1-002-I06"], "prerequisites": ["A2-G03"], "reading_tasks": ["U-B1-002-I07", "U-B1-002-I08"], "transfer_task": "U-B1-002-I13", "writing_tasks": ["U-B1-002-I11"], "competency_ids": ["B1-G03", "A2-G04"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B1-002-I12"], "errors_taxonomy": ["ASPECT", "TENSE", "NARRATIVE_SEQUENCE"], "guided_practice": ["U-B1-002-I02", "U-B1-002-I03", "U-B1-002-I04"], "listening_tasks": ["U-B1-002-I09", "U-B1-002-I10"], "learning_outcome": "Различить процессуальный фон и целое событие в рассказе", "vocabulary_items": [{"lemma": "γράφω", "stress": "γράφω", "example": "Έγραφα όταν ήρθε η Άννα.", "inflection": "έγραφα / έγραψα; γράφαμε / γράψαμε", "meaning_ru": "писать", "collocations": ["γράφω ένα μήνυμα"]}, {"lemma": "βλέπω", "stress": "βλέπω", "example": "Είδα τον Λεωνίδα.", "inflection": "έβλεπα / είδα", "meaning_ru": "видеть", "collocations": ["βλέπω έναν φίλο"]}, {"lemma": "φτάνω", "stress": "φτάνω", "example": "Όταν έφτασα, έβρεχε.", "inflection": "έφτανα / έφτασα", "meaning_ru": "прибывать", "collocations": ["φτάνω στον σταθμό"]}, {"lemma": "βρέχει", "stress": "βρέχει", "example": "Έβρεχε όλο το πρωί.", "inflection": "έβρεχε / έβρεξε", "meaning_ru": "идёт дождь", "collocations": ["άρχισε να βρέχει"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B1-002-I01"], "learning_objectives": ["Различить процессуальный фон и целое событие в рассказе", "Образовать έγραφα/έγραψα и έβλεπα/είδα по заданному ракурсу", "Рассказать о новом происшествии с фоном, событием и реакцией"], "level_override_note": "A2-G04 is legacy macro ID only. Systematic teaching placed at B1 according to v3/V201 PDF10; original registry unchanged.", "microcompetency_ids": ["U-B1-002-MC01", "U-B1-002-MC02", "U-B1-002-MC03"], "primary_competencies": ["B1-G03"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
