3149	unit	U-B1-003	dc8cbe52e55290f3092e793d53d3aa0715ace882bd0f4e2dcfd59659131a579f	core	{"unit_id": "U-B1-003", "content_hash": "dc8cbe52e55290f3092e793d53d3aa0715ace882bd0f4e2dcfd59659131a579f", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-003.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B1-003-RUBRIC"], "unit_id": "U-B1-003", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-B1-003-I02", "U-B1-003-I03", "U-B1-003-I04", "U-B1-003-I05", "U-B1-003-I06"], "reception": ["U-B1-003-I07", "U-B1-003-I08", "U-B1-003-I09", "U-B1-003-I10"], "retention": ["U-B1-003-I14", "U-B1-003-I15", "U-B1-003-I16"], "diagnostic": ["U-B1-003-I01"], "production": ["U-B1-003-I11", "U-B1-003-I12", "U-B1-003-I13"]}, "title_ru": "Передать сообщение и вопрос: ότι, αν, πότε", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Косвенная речь передаёт содержание, не сохраняя реплику как цитату. Сообщение вводится ότι/πως: Η Ελένη είπε ότι δεν μπορούσε να έρθει. Вопрос да/нет вводится αν: Με ρώτησε αν είχα χρόνο. Вопрос со специальным словом сохраняет его: Ρώτησε πότε αρχίζει το μάθημα. Αν здесь означает «ли», а не условие «если».\\nМестоимения и указания времени выбираются по точке зрения рассказчика. Εγώ θα έρθω αύριο, сказанное Марией в понедельник, во вторничном отчёте может стать Η Μαρία είπε ότι θα ερχόταν σήμερα. Но это не автоматическое преобразование каждого αύριο в την επόμενη μέρα: при пересказе в тот же день αύριο может оставаться точным. В греческом нет обязательного механического согласования времён по английской схеме. Решает реальная временная связь: Μου είπε ότι μένει στην Πάτρα естественно, если проживание актуально.\\nИзменение лица зависит от того, кто именно говорит. Με ρώτησε: «Έχεις χρόνο;» → Με ρώτησε αν είχα χρόνο. Сохраняйте источник и степень уверенности: είπε, ρώτησε, πρότεινε — разные действия. Нельзя превращать вопрос «Будет ли готово?» в обещание «Будет готово». После пересказа адресат должен различить подтверждённый факт, вопрос и предложение.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Η Νίκη είπε ότι μένει στην Πάτρα.", "Με ρώτησε αν είχα χρόνο.", "Ρώτησα πότε αρχίζει το μάθημα.", "Ο Στέλιος είπε πως θα μας τηλεφωνήσει."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B1-003-I14", "U-B1-003-I15", "U-B1-003-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF9–11", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction B1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-B1-003-I05", "U-B1-003-I06"], "prerequisites": ["B1-G03", "A2-G05"], "reading_tasks": ["U-B1-003-I07", "U-B1-003-I08"], "transfer_task": "U-B1-003-I13", "writing_tasks": ["U-B1-003-I11"], "competency_ids": ["B1-G09"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B1-003-I12"], "errors_taxonomy": ["INDIRECT_SPEECH", "REFERENCE", "UNSUPPORTED_INFERENCE"], "guided_practice": ["U-B1-003-I02", "U-B1-003-I03", "U-B1-003-I04"], "listening_tasks": ["U-B1-003-I09", "U-B1-003-I10"], "learning_outcome": "Передать сообщение с ότι/πως и общий вопрос с αν", "vocabulary_items": [{"lemma": "ρωτάω", "stress": "ρωτάω", "example": "Με ρώτησε αν μπορώ.", "inflection": "ρώτησα, ρώτησε", "meaning_ru": "спрашивать", "collocations": ["ρωτάω αν"]}, {"lemma": "λέω", "stress": "λέω", "example": "Είπε ότι θα έρθει.", "inflection": "είπα, είπε", "meaning_ru": "сказать", "collocations": ["λέω ότι"]}, {"lemma": "επιβεβαιώνω", "stress": "επιβεβαιώνω", "example": "Δεν επιβεβαίωσε την ώρα.", "inflection": "επιβεβαίωσα", "meaning_ru": "подтверждать", "collocations": ["επιβεβαιώνω την ώρα"]}, {"lemma": "προτείνω", "stress": "προτείνω", "example": "Πρότεινε να περιμένουμε.", "inflection": "πρότεινα", "meaning_ru": "предлагать", "collocations": ["προτείνω μια λύση"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B1-003-I01"], "learning_objectives": ["Передать сообщение с ότι/πως и общий вопрос с αν", "Сохранить референтов и точку отсчёта времени при пересказе", "Не превращать вопрос или неподтверждённый план в факт"], "microcompetency_ids": ["U-B1-003-MC01", "U-B1-003-MC02", "U-B1-003-MC03"], "primary_competencies": ["B1-G09"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
