3150	unit	U-B1-004	008b452418c64fdf540c9a1a493107cabb56d47235a426978d10ace3f87886bc	core	{"unit_id": "U-B1-004", "content_hash": "008b452418c64fdf540c9a1a493107cabb56d47235a426978d10ace3f87886bc", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-004.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B1-004-RUBRIC"], "unit_id": "U-B1-004", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-B1-004-I02", "U-B1-004-I03", "U-B1-004-I04", "U-B1-004-I05", "U-B1-004-I06"], "reception": ["U-B1-004-I07", "U-B1-004-I08", "U-B1-004-I09", "U-B1-004-I10"], "retention": ["U-B1-004-I14", "U-B1-004-I15", "U-B1-004-I16"], "diagnostic": ["U-B1-004-I01"], "production": ["U-B1-004-I11", "U-B1-004-I12", "U-B1-004-I13"]}, "title_ru": "Кому и что: двойные клитики", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Безударные местоимения заменяют уже понятные из контекста объекты. В Η Άννα έδωσε το βιβλίο στον Πέτρο прямой объект — βιβλίο, получатель — Πέτρος. Пересказ: Του το έδωσε. В обычном личном предложении сначала идёт родительный косвенного объекта μου/σου/του/της/μας/σας/τους, затем винительный τον/την/το/τους/τις/τα, затем глагол. Артикль и клитика могут выглядеть одинаково, но выполняют разные функции.\\nВ положительном повелительном местоимения стоят после глагола: Δώσε μου το βιβλίο → Δώσ’ μου το. Для ясного учебного образца используем Πες μου την ώρα → Πες μου την. Некоторые сочетания после императива допускают вариацию порядка; этот урок не объявляет единственный шаблон универсальным. Отрицательное побуждение строится с μη(ν) и формой с местоимениями перед глаголом: Μη μου το δώσεις ακόμη. Не переносите положительный порядок автоматически.\\nПолезно начать с надёжных контрастов: Μου το δίνεις / Να μου το δώσεις / Μη μου το δώσεις. В πλήρη форме объясните, кому и что передают; только затем сокращайте. При двух возможных референтах лучше повторить имя или предмет. У местоимений после ударного глагола возможны дополнительные ударения, например Δώσε μού το. Орфографическая вычитка таких сочетаний обязательна; предпочтительный учебный пример здесь Δώσ’ μου το избегает спорного обобщения.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Του το έστειλα χτες.", "Να μου το δώσεις αύριο.", "Μη μου το δώσεις ακόμη.", "Δώσ’ μου το, παρακαλώ."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B1-004-I14", "U-B1-004-I15", "U-B1-004-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF9–11", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction B1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-B1-004-I05", "U-B1-004-I06"], "prerequisites": ["A2-G02", "A2-G06", "A2-G07"], "reading_tasks": ["U-B1-004-I07", "U-B1-004-I08"], "transfer_task": "U-B1-004-I13", "writing_tasks": ["U-B1-004-I11"], "competency_ids": ["B1-G02", "B1-G06"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B1-004-I12"], "errors_taxonomy": ["CLITIC_ORDER", "REFERENCE", "ACCENTUATION"], "guided_practice": ["U-B1-004-I02", "U-B1-004-I03", "U-B1-004-I04"], "listening_tasks": ["U-B1-004-I09", "U-B1-004-I10"], "learning_outcome": "Заменить ясные прямой и косвенный объекты двумя клитиками", "vocabulary_items": [{"lemma": "δίνω", "stress": "δίνω", "example": "Της το έδωσα.", "inflection": "έδωσα; δώσε", "meaning_ru": "давать", "collocations": ["δίνω κάτι σε κάποιον"]}, {"lemma": "στέλνω", "stress": "στέλνω", "example": "Σας το έστειλα.", "inflection": "έστειλα; στείλε", "meaning_ru": "отправлять", "collocations": ["στέλνω ένα αρχείο"]}, {"lemma": "επιστρέφω", "stress": "επιστρέφω", "example": "Θα σου το επιστρέψω.", "inflection": "επέστρεψα; επιστρέφω κάτι", "meaning_ru": "возвращать", "collocations": ["επιστρέφω το βιβλίο"]}, {"lemma": "παραλήπτης", "stress": "παραλήπτης", "example": "Ποιος είναι ο παραλήπτης;", "inflection": "ο παραλήπτης, οι παραλήπτες", "meaning_ru": "получатель", "collocations": ["το όνομα του παραλήπτη"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B1-004-I01"], "learning_objectives": ["Заменить ясные прямой и косвенный объекты двумя клитиками", "Различить положение клитик в личной форме, побуждении и запрете", "Исправить получателя предмета в новом диалоге"], "microcompetency_ids": ["U-B1-004-MC01", "U-B1-004-MC02", "U-B1-004-MC03"], "primary_competencies": ["B1-G02", "B1-G06"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
