3151	unit	U-B1-005	b4122018d230fae401dfd422be7c4976f1ffbc545eb52130d1b437d517bb168f	core	{"unit_id": "U-B1-005", "content_hash": "b4122018d230fae401dfd422be7c4976f1ffbc545eb52130d1b437d517bb168f", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-005.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B1-005-RUBRIC"], "unit_id": "U-B1-005", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-B1-005-I02", "U-B1-005-I03", "U-B1-005-I04", "U-B1-005-I05", "U-B1-005-I06"], "reception": ["U-B1-005-I07", "U-B1-005-I08", "U-B1-005-I09", "U-B1-005-I10"], "retention": ["U-B1-005-I14", "U-B1-005-I15", "U-B1-005-I16"], "diagnostic": ["U-B1-005-I01"], "production": ["U-B1-005-I11", "U-B1-005-I12", "U-B1-005-I13"]}, "title_ru": "Родительный множественного: формы и связи", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Родительный множественного имеет общий артикль των, но форма существительного требует знания модели и ударения. Сравним οι φίλοι → των φίλων, οι μαθητές → των μαθητών, τα παιδιά → των παιδιών, οι πόλεις → των πόλεων. Нельзя просто добавить -ων к видимой форме именительного и сохранить любое ударение. Полезно учить пару целиком: οι πόλεις / των πόλεων.\\nВ группе η πρόταση των μαθητών главное слово — πρόταση, а родительный указывает, чья это идея. Сказуемое согласуется с главным словом: Η πρόταση των μαθητών είναι ενδιαφέρουσα. Во множественном Οι προτάσεις των μαθητών είναι ενδιαφέρουσες. Близость μαθητών к глаголу не делает его подлежащим. Прилагательное внутри зависимой группы тоже согласуется: των νέων μαθητών; его окончание не следует за πρόταση.\\nРодительный выражает не только принадлежность вещи человеку. В το κέντρο της πόλης он связывает части пространственного описания; в η προστασία των παιδιών обозначает объект заботы. Значение устанавливается всей группой, поэтому русский перевод с «у» не является универсальным.\\nДля самостоятельного письма надёжнее применить знакомую модель, чем создавать незнакомую форму по аналогии. При неизвестном исключении допустима временная перефразировка и проверка словаря. Здесь отрабатываются четыре частотные модели; нерегулярные γεγονός/προϊόν и прилагательные на -ής изучаются в отдельном B2 блоке.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Η πρόταση των μαθητών είναι ενδιαφέρουσα.", "Τα παιχνίδια των παιδιών είναι εδώ.", "Συγκρίνουμε τα κέντρα των πόλεων.", "Οι φίλοι των νέων μαθητών περιμένουν έξω."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B1-005-I14", "U-B1-005-I15", "U-B1-005-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF9–11", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction B1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-B1-005-I05", "U-B1-005-I06"], "prerequisites": ["A2-G01", "A1-G03"], "reading_tasks": ["U-B1-005-I07", "U-B1-005-I08"], "transfer_task": "U-B1-005-I13", "writing_tasks": ["U-B1-005-I11"], "competency_ids": ["B1-G01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B1-005-I12"], "errors_taxonomy": ["GENITIVE_PLURAL", "AGREEMENT", "ACCENTUATION"], "guided_practice": ["U-B1-005-I02", "U-B1-005-I03", "U-B1-005-I04"], "listening_tasks": ["U-B1-005-I09", "U-B1-005-I10"], "learning_outcome": "Образовать родительный множественного четырёх изученных моделей", "vocabulary_items": [{"lemma": "μαθητής", "stress": "μαθητής", "example": "Ακούσαμε την πρόταση των μαθητών.", "inflection": "ο μαθητής, οι μαθητές, των μαθητών", "meaning_ru": "ученик", "collocations": ["πρόταση των μαθητών"]}, {"lemma": "παιδί", "stress": "παιδί", "example": "Τα παιχνίδια των παιδιών είναι εδώ.", "inflection": "το παιδί, τα παιδιά, των παιδιών", "meaning_ru": "ребёнок", "collocations": ["παιχνίδια των παιδιών"]}, {"lemma": "πόλη", "stress": "πόλη", "example": "Μελετάμε τα κέντρα των πόλεων.", "inflection": "η πόλη, οι πόλεις, των πόλεων", "meaning_ru": "город", "collocations": ["κέντρα των πόλεων"]}, {"lemma": "πρόταση", "stress": "πρόταση", "example": "Η πρόταση είναι σαφής.", "inflection": "η πρόταση, οι προτάσεις, των προτάσεων", "meaning_ru": "предложение", "collocations": ["εξέταση των προτάσεων"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B1-005-I01"], "learning_objectives": ["Образовать родительный множественного четырёх изученных моделей", "Найти главное слово группы и согласовать с ним сказуемое", "Употребить родительный в новом сообщении"], "microcompetency_ids": ["U-B1-005-MC01", "U-B1-005-MC02", "U-B1-005-MC03"], "primary_competencies": ["B1-G01"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
