3152	unit	U-B1-006	afb90e5971bd628e7d14e9ae86bbe9310bca86229f5c23b11297daf69ecfed5b	core	{"unit_id": "U-B1-006", "content_hash": "afb90e5971bd628e7d14e9ae86bbe9310bca86229f5c23b11297daf69ecfed5b", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-006.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B1-006-RUBRIC"], "unit_id": "U-B1-006", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-B1-006-I02", "U-B1-006-I03", "U-B1-006-I04", "U-B1-006-I05", "U-B1-006-I06"], "reception": ["U-B1-006-I07", "U-B1-006-I08", "U-B1-006-I09", "U-B1-006-I10"], "retention": ["U-B1-006-I14", "U-B1-006-I15", "U-B1-006-I16"], "diagnostic": ["U-B1-006-I01"], "production": ["U-B1-006-I11", "U-B1-006-I12", "U-B1-006-I13"]}, "title_ru": "Реальное условие и план действий", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Αν вводит условие, при котором выполняется другое действие. Αν βρέξει, θα μείνουμε μέσα оставляет дождь возможным будущим событием. В условной части нет необходимости добавлять θα: в этой базовой модели используем αν + совершенную форму, затем θα + совершенную форму. Отрицательное условие строится с δεν: Αν δεν έρθει, θα αρχίσουμε χωρίς αυτόν. Не переносите μην из конструкции να механически.\\nУсловие может описывать повторяющуюся связь: Αν έχω χρόνο, διαβάζω. Здесь нет обещания одного будущего действия. Когда событие ожидается как часть плана, когда подходит όταν: Όταν τελειώσει η συνάντηση, θα τηλεφωνήσω. Αν оставляет сам факт под вопросом; όταν организует время предполагаемого события. Это смысловой контраст, а не запрет на употребление όταν в любых неопределённых обстоятельствах.\\nДля совместного плана важно договориться о действиях в обеих ветках. Если зал свободен — встречаемся там; если нет — переносим встречу или выбираем другое место. Не обещайте подтверждённую бронь на основании условного предложения. Глагол θα мог бы обозначать будущее внутри пересказа, но в этом уроке отрабатывается базовый прямой план.\\nВ разговоре сначала сформулируйте условие, затем понятный результат и того, кто проверяет условие. Допустим и обратный порядок: Θα μείνουμε μέσα αν βρέξει. Запятая на письме не является главным критерием понимания; важнее не перепутать условие и уже известный факт.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Αν βρέξει, θα μείνουμε μέσα.", "Αν δεν έρθει η Άννα, θα της τηλεφωνήσω.", "Όταν τελειώσει η συνάντηση, θα φύγουμε.", "Θα περιμένουμε αν χρειαστεί."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B1-006-I14", "U-B1-006-I15", "U-B1-006-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF9–11", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction B1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-B1-006-I05", "U-B1-006-I06"], "prerequisites": ["A2-G05", "A2-G06", "A2-G03"], "reading_tasks": ["U-B1-006-I07", "U-B1-006-I08"], "transfer_task": "U-B1-006-I13", "writing_tasks": ["U-B1-006-I11"], "competency_ids": ["B1-G07"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B1-006-I12"], "errors_taxonomy": ["CONDITIONAL", "NEGATION", "FACT_VS_PLAN"], "guided_practice": ["U-B1-006-I02", "U-B1-006-I03", "U-B1-006-I04"], "listening_tasks": ["U-B1-006-I09", "U-B1-006-I10"], "learning_outcome": "Построить условный план с αν и отрицанием δεν", "vocabulary_items": [{"lemma": "χρειάζομαι", "stress": "χρειάζομαι", "example": "Θα βοηθήσω αν χρειαστεί.", "inflection": "θα χρειαστώ; χρειαστεί безлично", "meaning_ru": "нуждаться; понадобиться", "collocations": ["αν χρειαστεί"]}, {"lemma": "ελεύθερος", "stress": "ελεύθερος", "example": "Η αίθουσα είναι ελεύθερη.", "inflection": "ελεύθερος, ελεύθερη, ελεύθερο", "meaning_ru": "свободный", "collocations": ["ελεύθερη αίθουσα"]}, {"lemma": "μεταφέρω", "stress": "μεταφέρω", "example": "Θα μεταφέρουμε τη συνάντηση.", "inflection": "μετέφερα; θα μεταφέρω", "meaning_ru": "переносить", "collocations": ["μεταφέρω τη συνάντηση"]}, {"lemma": "επιβεβαιώνω", "stress": "επιβεβαιώνω", "example": "Θα επιβεβαιώσω την κράτηση.", "inflection": "επιβεβαίωσα; θα επιβεβαιώσω", "meaning_ru": "подтверждать", "collocations": ["επιβεβαιώνω την κράτηση"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B1-006-I01"], "learning_objectives": ["Построить условный план с αν и отрицанием δεν", "Отличить условный план от подтверждённого события", "Согласовать действия при двух возможных исходах"], "microcompetency_ids": ["U-B1-006-MC01", "U-B1-006-MC02", "U-B1-006-MC03"], "primary_competencies": ["B1-G07"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
