3153	unit	U-B1-007	eee039511377687ccc20d5ae5903ccb2e7467c0056802888c22710852c0739b8	core	{"unit_id": "U-B1-007", "content_hash": "eee039511377687ccc20d5ae5903ccb2e7467c0056802888c22710852c0739b8", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-007.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B1-007-RUBRIC"], "unit_id": "U-B1-007", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-B1-007-I02", "U-B1-007-I03", "U-B1-007-I04", "U-B1-007-I05", "U-B1-007-I06"], "reception": ["U-B1-007-I07", "U-B1-007-I08", "U-B1-007-I09", "U-B1-007-I10"], "retention": ["U-B1-007-I14", "U-B1-007-I15", "U-B1-007-I16"], "diagnostic": ["U-B1-007-I01"], "production": ["U-B1-007-I11", "U-B1-007-I12", "U-B1-007-I13"]}, "title_ru": "Связное письмо: опыт, причина и запрос", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "В письме B1 адресат должен понять, зачем вы пишете, что произошло и чего вы ждёте в ответ. Полезная структура: обращение → краткая ситуация → опыт с причиной оценки → конкретный запрос → завершение. Это рабочая опора, а не обязательный шаблон для любого жанра. Письмо знакомому Γεια σου, Ρέα допускает более разговорный тон, чем Αγαπητή κυρία... Не смешивайте в одном письме ты и вежливое вы без причины.\\nОпыт описывается понятной последовательностью. Χτες πήγα... сначала устанавливает событие, затем επειδή/γι’ αυτό связывают причину и результат. Κι ещё одной связки недостаточно, если адресат не понимает, к чему относится местоимение. Назовите предмет или человека повторно, когда это снимает двусмысленность.\\nЗапрос должен быть исполнимым: Μπορείτε να μου πείτε αν υπάρχει άλλο τμήμα; яснее, чем γενικό Θέλω βοήθεια без уточнения. Укажите нужный параметр — день, время, формат ответа, — но не выдумывайте обязательство организации. В модели ниже цены и расписание не сообщаются, потому что автор их не знает.\\nПеред отправкой проверьте четыре вещи: все пункты задания раскрыты; обращение соответствует отношениям; причины относятся к своей оценке; просьба не выглядит уже полученным подтверждением. Орфографические ошибки исправляйте после смыслового прохода. Краткий образец помогает понять структуру, но его нельзя запоминать как единственно допустимый ответ на новое задание.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Σας γράφω για να ζητήσω πληροφορίες.", "Το μάθημα μου άρεσε, επειδή είχαμε χρόνο για συζήτηση.", "Δεν μπορώ να έρχομαι την Τρίτη, γι’ αυτό αναζητώ άλλο τμήμα.", "Μπορείτε να μου πείτε ποιες άλλες ώρες υπάρχουν;"], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B1-007-I14", "U-B1-007-I15", "U-B1-007-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF9–11", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction B1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-B1-007-I05", "U-B1-007-I06"], "prerequisites": ["A2-G03", "A2-G05", "B1-G10"], "reading_tasks": ["U-B1-007-I07", "U-B1-007-I08"], "transfer_task": "U-B1-007-I13", "writing_tasks": ["U-B1-007-I11"], "competency_ids": ["B1-W01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B1-007-I12"], "errors_taxonomy": ["REGISTER", "COHESION", "TASK_COMPLETION"], "guided_practice": ["U-B1-007-I02", "U-B1-007-I03", "U-B1-007-I04"], "listening_tasks": ["U-B1-007-I09", "U-B1-007-I10"], "learning_outcome": "Написать связное письмо об опыте и запросе", "vocabulary_items": [{"lemma": "πληροφορία", "stress": "πληροφορία", "example": "Θα ήθελα πληροφορίες για το τμήμα.", "inflection": "η πληροφορία, οι πληροφορίες", "meaning_ru": "сведения", "collocations": ["ζητάω πληροφορίες"]}, {"lemma": "τμήμα", "stress": "τμήμα", "example": "Υπάρχει άλλο τμήμα;", "inflection": "το τμήμα, τα τμήματα", "meaning_ru": "группа; отделение", "collocations": ["άλλο τμήμα"]}, {"lemma": "διαθέσιμος", "stress": "διαθέσιμος", "example": "Ποιες ώρες είναι διαθέσιμες;", "inflection": "διαθέσιμος, διαθέσιμη, διαθέσιμο", "meaning_ru": "доступный", "collocations": ["διαθέσιμη ώρα"]}, {"lemma": "αναζητώ", "stress": "αναζητώ", "example": "Αναζητώ ένα πρωινό τμήμα.", "inflection": "αναζητώ, αναζητάς; αναζήτησα", "meaning_ru": "искать", "collocations": ["αναζητώ λύση"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B1-007-I01"], "learning_objectives": ["Написать связное письмо об опыте и запросе", "Обосновать оценку и причину изменения", "Сохранить регистр и отделить просьбу от подтверждения"], "microcompetency_ids": ["U-B1-007-MC01", "U-B1-007-MC02", "U-B1-007-MC03"], "primary_competencies": ["B1-W01"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
