591	source_claim	CP08-INHERITED-U-A1-011-I14-01	e91a3add7510d5de4cfd9b39cbc2e1112e8e4e93c535ab9a8e11b4d4671911ad	\N	{"record": {"claim": "Уровневая тема; не дословный источник авторских фраз", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A1-011-I14-01", "item_ids": ["U-A1-011-I14"], "source_id": "V201", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A1-011-I14.json", "sha256": "7e1ffb117e36af338af3b2fa3c908acb17126f1838211343b40c9e200af28488"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "A1-G10 historical curricular theme only", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}}, "claim_id": "CP08-INHERITED-U-A1-011-I14-01", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3154	unit	U-B1-008	8f566fbde9f3f2d4af116b85bd9109694179e3c7108c4a2d37975b7aca010ba4	core	{"unit_id": "U-B1-008", "content_hash": "8f566fbde9f3f2d4af116b85bd9109694179e3c7108c4a2d37975b7aca010ba4", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-008.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B1-008-RUBRIC"], "unit_id": "U-B1-008", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-B1-008-I02", "U-B1-008-I03", "U-B1-008-I04", "U-B1-008-I05", "U-B1-008-I06", "U-B1-008-I07", "U-B1-008-I08", "U-B1-008-I19", "U-B1-008-I20"], "reception": ["U-B1-008-I09", "U-B1-008-I10", "U-B1-008-I11", "U-B1-008-I12"], "retention": ["U-B1-008-I16", "U-B1-008-I17", "U-B1-008-I18", "U-B1-008-I22"], "diagnostic": ["U-B1-008-I01"], "production": ["U-B1-008-I13", "U-B1-008-I14", "U-B1-008-I15", "U-B1-008-I21"]}, "title_ru": "Объясняем причину, цель и результат", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Сначала определите связь между событиями. Причина отвечает на «почему это произошло?»: Έμεινα σπίτι επειδή έβρεχε. Дождь объясняет решение остаться. Цель отвечает на «зачем действовал человек?»: Έφυγα νωρίς για να προλάβω το λεωφορείο. Намерение не доказывает успех: можно добавить αλλά τελικά το έχασα. Последовательность двух событий сама по себе не доказывает причинность.\\n\\nΕπειδή вводит предложение с личной формой. В отрицательном факте употребляем δεν: Δεν ήρθα επειδή δεν αισθανόμουν καλά. Вынесенная вперёд причина обычно отделяется запятой: Επειδή έβρεχε, μείναμε μέσα. Не переводите русское «потому» отдельным местоимением без нужной связи.\\n\\nΓια να вводит цель и требует формы после να. Законченную цель выражает, например, για να διαβάσω το μήνυμα; повторяющуюся — για να διαβάζω κάθε βράδυ. Отрицательная цель: για να μην αργήσω. Субъекты могут отличаться: Μίλησα αργά για να με καταλάβουν όλοι. Не согласовывайте второй глагол автоматически с первым.\\n\\nΓι’ αυτό связывает уже названную причину со следующим решением или следствием: Το λεωφορείο χάλασε. Γι’ αυτό αργήσαμε. Это отдельное обстоятельственное выражение, а не замена επειδή внутри любой конструкции. При перестройке сохраните направление причинности: Αργήσαμε επειδή χάλασε το λεωφορείο.\\n\\nΏστε вводит результат; конструкцию выбирают вместе со значением. Ήταν τόσο δυνατός ο θόρυβος, ώστε δεν ακούσαμε την ανακοίνωση: здесь прямо сообщён фактический результат. В Μίλησε αρκετά δυνατά ώστε να τον ακούσουν όλοι конструкция с να описывает достаточное условие/ожидаемый эффект; нельзя из одного να вывести, что все действительно услышали. В этом уроке для однозначного сообщения о случившемся используйте ώστε + личную форму с контекстом факта, а намерение обозначайте για να.\\n\\nПри проверке сначала перескажите смысл без связки, затем выберите форму. Одна грамматически правильная связка не компенсирует перевёрнутую причину. В собственной речи объясните решение, обозначьте цель и отдельно сообщите, достигнута ли она. Если собеседник не понял, уточните γεγονός ή στόχος — факт это или цель.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Ακύρωσα τη βόλτα επειδή έβρεχε.", "Πήγα στη βιβλιοθήκη για να δουλέψω ήσυχα.", "Πήρα σημειώσεις για να μην ξεχάσω τις οδηγίες.", "Δεν υπήρχαν εισιτήρια. Γι’ αυτό γυρίσαμε σπίτι.", "Η αίθουσα ήταν τόσο μικρή, ώστε αρκετοί έμειναν όρθιοι.", "Έστειλα το αρχείο για να το ελέγξει η Άννα, αλλά δεν το έχει ανοίξει ακόμη."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B1-008-I16", "U-B1-008-I17", "U-B1-008-I18", "U-B1-008-I22"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Историческая уровневая тематическая карта; размещение требует эксперта", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Reception, production, interaction; author mapping, not official cut score", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "§5.2: αιτιολογικές, τελικές, αποτελεσματικές", "source_id": "N404", "checked_on": "2026-10-14", "claim_scope": "Грамматическое/фонетическое правило; задания оригинальные", "evidence_type": "OFFICIAL_SCHOOL_GRAMMAR_NOT_AUTH_SYLLABUS"}], "evidence_map": [{"delayed": ["U-B1-008-I16", "U-B1-008-I22"], "transfer": ["U-B1-008-I13", "U-B1-008-I15"], "source_ids": ["V201", "W322", "N404"], "prerequisites": ["A2-G11", "A2-G06"], "mastery_decision": {"rule": "Целевая связь/форма верна в контролируемом задании; самостоятельное применение в новом сообщении и переносе; повтор без подсказок через 7/14/28 дней. Не усреднять критическую смысловую ошибку.", "status": "NOT_ASSESSED", "pronunciation_gate": "NOT_INFERRED_FROM_TRANSCRIPT"}, "microcompetency_id": "U-B1-008-MC01", "observable_outcome": "Различить причину, намерение и фактическое следствие в сообщении.", "evidence_is_collected": false, "independent_production": ["U-B1-008-I07", "U-B1-008-I19"], "recognition_or_controlled": ["U-B1-008-I01", "U-B1-008-I02", "U-B1-008-I03", "U-B1-008-I19"], "success_criteria_specific": "Различить причину, намерение и ф