3155	unit	U-B1-009	19f7bb08c83a4f5b3c95a2f03c73de0bf437f585a47dd3d83f3ae2ddb817bda7	core	{"unit_id": "U-B1-009", "content_hash": "19f7bb08c83a4f5b3c95a2f03c73de0bf437f585a47dd3d83f3ae2ddb817bda7", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-009.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B1-009-RUBRIC"], "unit_id": "U-B1-009", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-B1-009-I02", "U-B1-009-I03", "U-B1-009-I04", "U-B1-009-I05", "U-B1-009-I06", "U-B1-009-I07", "U-B1-009-I08", "U-B1-009-I19", "U-B1-009-I20"], "reception": ["U-B1-009-I09", "U-B1-009-I10", "U-B1-009-I11", "U-B1-009-I12"], "retention": ["U-B1-009-I16", "U-B1-009-I17", "U-B1-009-I18", "U-B1-009-I22"], "diagnostic": ["U-B1-009-I01"], "production": ["U-B1-009-I13", "U-B1-009-I14", "U-B1-009-I15", "U-B1-009-I21"]}, "title_ru": "Перфект и плюсквамперфект: результат и более раннее событие", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Παρακείμενος строится из настоящего έχω и неизменяемой завершённой формы: έχω γράψει. Меняется вспомогательный глагол: έχω, έχεις, έχει, έχουμε, έχετε, έχουν γράψει. Не согласовывайте вторую часть по лицу: *έχουμε γράψουμε неверно. Формы для этого урока: γράψει, στείλει, τελειώσει, κλείσει, φύγει, διαβάσει. Учите их с соответствующим глаголом и контекстом.\\n\\nПерфект связывает завершённое действие с настоящим состоянием: Έχω στείλει την αίτηση — заявка уже отправлена, сейчас это важно. Ο αόριστος часто помещает завершённое событие в рассказ: Έστειλα την αίτηση χθες. В греческом не следует механически переносить английские запреты на сочетания перфекта с любым указанием времени. В ряде ситуаций возможны разные формы с изменением фокуса; задание должно явно задавать нужную временную перспективу. Если оба варианта естественны, требуется смысловая проверка, а не штраф за несовпадение с одним образцом.\\n\\nΥπερσυντέλικος строится с είχα: είχα, είχες, είχε, είχαμε, είχατε, είχαν γράψει. Он переносит точку отсчёта в прошлое: Όταν έφτασα, η Άννα είχε φύγει. Сначала Анна ушла, потом я пришёл. При Όταν έφτασα, η Άννα έφυγε уход представлен как событие при моём приходе; смысловая связь меняется.\\n\\nОтрицание и местоимение находятся перед вспомогательным глаголом: Δεν έχω διαβάσει το μήνυμα. Δεν το είχα διαβάσει όταν μου τηλεφώνησες. Ήδη подчёркивает «уже», ακόμη/ακόμα с отрицанием — «ещё не»: Δεν έχω τελειώσει ακόμη. Эти слова помогают понять перспективу, но сами по себе не выбирают время автоматически.\\n\\nДля хронологии нарисуйте две точки: более раннее действие и прошлый ориентир. Сообщайте состояние именно на момент ориентира, а не сегодняшнее: Είχα κλείσει τραπέζι πριν φτάσουμε. Для отчёта «что готово сейчас» выберите настоящее вспомогательное: Έχουμε κλείσει τραπέζι, μπορούμε να πάμε. Будущее завершённое θα έχω… уже изучалось отдельно; это не основание объявить всю компетенцию освоенной.\\n\\nПри проверке собственной речи назовите точку отсчёта, проверьте лицо вспомогательного и неизменяемость второй части. В свободном рассказе допустим естественный аорист, если он передаёт нужную хронологию; но для доказательства владения целевой формой нужна хотя бы одна самостоятельная уместная конструкция каждого изучаемого времени.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Έχω γράψει το μήνυμα, αλλά δεν το έχω στείλει ακόμη.", "Έχουμε κλείσει δύο θέσεις.", "Έχετε διαβάσει τις οδηγίες;", "Όταν τηλεφώνησα, είχαν ήδη φύγει.", "Δεν είχα τελειώσει όταν έφτασε η Άννα.", "Είχαμε στείλει τα στοιχεία πριν αρχίσει η συνάντηση."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B1-009-I16", "U-B1-009-I17", "U-B1-009-I18", "U-B1-009-I22"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Историческая уровневая тематическая карта; размещение требует эксперта", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Reception, production, interaction; author mapping, not official cut score", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "Составные времена: παρακείμενος / υπερσυντέλικος", "source_id": "N406", "checked_on": "2026-10-14", "claim_scope": "Грамматическое/фонетическое правило; задания оригинальные", "evidence_type": "OFFICIAL_SCHOOL_GRAMMAR_NOT_AUTH_SYLLABUS"}, {"anchor": "§6: άκλιτος τύπος и вспомогательные формы", "source_id": "N405", "checked_on": "2026-10-14", "claim_scope": "Грамматическое/фонетическое правило; задания оригинальные", "evidence_type": "OFFICIAL_SCHOOL_GRAMMAR_NOT_AUTH_SYLLABUS"}], "evidence_map": [{"delayed": ["U-B1-009-I16", "U-B1-009-I22"], "transfer": ["U-B1-009-I13", "U-B1-009-I15"], "source_ids": ["V201", "W322", "N406", "N405"], "prerequisites": ["A2-G03", "A2-G04"], "mastery_decision": {"rule": "Целевая связь/форма верна в контролируемом задании; самостоятельное применение в новом сообщении и переносе; повтор без подсказок через 7/14/28 дней. Не усреднять критическую смысловую ошибку.", "status": "NOT_ASSESSED", "pronunciation_gate": "NOT_INFERRED_FROM_T