3156	unit	U-B1-010	cf8fbcb0eb083bdda76f20594e4b06e8da03ae2952b9d7dd15624ef6a98684a6	core	{"unit_id": "U-B1-010", "content_hash": "cf8fbcb0eb083bdda76f20594e4b06e8da03ae2952b9d7dd15624ef6a98684a6", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-010.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "DRAFT", "rubrics": ["U-B1-010-RUBRIC"], "unit_id": "U-B1-010", "version": "0.1.2", "sections": {"theory": "theory_ru", "practice": ["U-B1-010-I02", "U-B1-010-I03", "U-B1-010-I04", "U-B1-010-I05", "U-B1-010-I06", "U-B1-010-I07", "U-B1-010-I08", "U-B1-010-I09"], "reception": ["U-B1-010-I10", "U-B1-010-I11", "U-B1-010-I12", "U-B1-010-I13"], "retention": ["U-B1-010-I17", "U-B1-010-I18", "U-B1-010-I19"], "diagnostic": ["U-B1-010-I01"], "production": ["U-B1-010-I14", "U-B1-010-I15", "U-B1-010-I16"]}, "title_ru": "Одевался, оделся, было решено: медиопассивное прошедшее", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "-Μαι в настоящем указывает на морфологическую модель, не автоматически на пассивный смысл. Ντύνομαι — одеваюсь сам; θυμάμαι — помню. Сначала восстановите участников, затем определяйте значение. Это продолжает U-A2-006.\\nПроцесс: ντυνόμουν, ντυνόσουν, ντυνόταν, ντυνόμασταν, ντυνόσασταν, ντύνονταν. Целое событие: ντύθηκα, ντύθηκες, ντύθηκε, ντυθήκαμε, ντυθήκατε, ντύθηκαν. Ударение в ντυθήκαμε не копируется из ντύθηκα. Разговорное ντυνόμουνα распознаём; сначала производим нейтральный ряд. Ντυνόμουν όταν τηλεφώνησες — процесс; Ντύθηκα και έφυγα — завершение и следующий шаг.\\nПассивный результат: Το πρόβλημα λύθηκε από την ομάδα. Если исполнитель важен и известен, добавьте από с винительным. Если неизвестен, не придумывайте: Το πρόβλημα λύθηκε. Η ομάδα έλυσε το πρόβλημα → Το πρόβλημα λύθηκε από την ομάδα. Новое подлежащее определяет число: Τα προβλήματα λύθηκαν.\\nНельзя добавлять -θηκα к любому глаголу. Изучаем θυμάμαι — θυμήθηκα, έρχομαι — ήρθα, γίνομαι — έγινα, εργάζομαι — εργάστηκα. Эти формы не означают «меня пришли/работали». Для незнакомой основы нужна словарная проверка. В чтении μεταφέρθηκε — было перенесено, готовая рецептивная форма; в сценарии ετοιμαζόμουν — я готовился/готовилась. Их включение не означает освоения новых парадигм.\\nРассказ должен разделять личное действие, чужое действие и неизвестное. В преобразовании сохраняйте исполнителя, если требует задача. Затем измените ситуацию и расскажите без таблицы. Слушатель должен понимать, что происходило до события и чем оно закончилось. Все модели пассивного спряжения этот урок не закрывает.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Ντυνόμουν όταν τηλεφώνησες.", "Ντύθηκα γρήγορα και έφυγα.", "Τα παιδιά ντύθηκαν μόνα τους.", "Το πρόβλημα λύθηκε από την ομάδα.", "Θυμήθηκα το όνομά της.", "Ήρθα νωρίς και εργάστηκα μέχρι τις έξι."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "delivery": "Use concrete D7 and D28 scenarios in microcompetencies.json alongside closed retrieval; no observed mastery yet", "item_ids": ["U-B1-010-I17", "U-B1-010-I18", "U-B1-010-I19"], "hypothesis_not_official": true, "independent_followup_micro_ids": ["U-B1-010-MC01", "U-B1-010-MC02", "U-B1-010-MC03"]}, "source_refs": [{"anchor": "B1-G04 historical curricular theme only", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "B1 interaction/production, project mapping", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "§6.2 φωνές/διαθέσεις; λύνομαι; θυμάμαι; ανώμαλα", "source_id": "N405", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}], "active_recall": ["U-B1-010-I08", "U-B1-010-I09"], "prerequisites": ["A2-G08", "A2-G04", "A2-G03"], "reading_tasks": ["U-B1-010-I10", "U-B1-010-I11"], "transfer_task": "U-B1-010-I16", "writing_tasks": ["U-B1-010-I14"], "competency_ids": ["B1-G04"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "reconstruction": {"date": "2026-10-15", "basis": "Saved authoring text and review findings in conversation; reconstructed after workspace cleanup; byte identity to lost drafts not claimed", "previous_unsaved_version": "0.1.0"}, "speaking_tasks": ["U-B1-010-I15"], "errors_taxonomy": ["VOICE_VS_MEANING", "MEDIOPASSIVE_PAST_STRESS", "INVENTED_PASSIVE_STEM", "AGENT_ATTRIBUTION", "BACKGROUND_EVENT"], "guided_practice": ["U-B1-010-I02", "U-B1-010-I03", "U-B1-010-I04", "U-B1-010-I05", "U-B1-010-I06", "U-B1-010-I07"], "listening_tasks": ["U-B1-010-I12", "U-B1-010-I13"], "learning_outcome": "Образовать изученное медиопассивное прошедшее с ударением", "mastery_contract": {"audio": "Не оценивается без аудио", "unaided": "Две самостоятельные реплики без модели", "observed": false, "transfer": "Все условия новой ситуации; целевая форма=2, другие критерии≥1", "retention": "D7/D14/D28 без подсказок плюс новая свободная реплика", "controlled": "≥80% целевых форм; смысловая ошибка требует повторного обучения"}, "vocabulary_items": [{"lemma": "ντύνομαι", "stress": "ντύνομαι", "example": "Ντύθηκα μόνος μου.", "inflection": "ντυνόμουν / ντύθηκα", "meaning_ru": "одеваться", "collocations": ["ντύνομαι μόνος μου"]}, {"lemma": "λύνομαι", "stress": "λύνομαι", "example": "Το πρόβλημα λύθηκε.", "inflection": "λυνόμουν / λύθηκα", "meaning_ru": "решаться", "collocations": ["λύνεται το πρόβλημα"]}, {"lemma": "θυμάμαι", "stress": "θυμάμαι", "example": "Θυμήθηκα το όνομα.", "inflection": "θυμόμουν / θυμήθηκα", "meaning_ru": "помнить", "collocations": ["θυμάμαι το όνομα"]}, {"lemma": "εργάζομαι", "stress": "εργάζομαι", "example": "Εργάστηκα όλη μέρα.", "inflection": "εργαζόμουν / εργάστηκα", "meaning_ru": "работать", "collocations": ["εργάζομαι στο γραφείο"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B1-010-I01"], "learning_objectives": ["Образовать изученное медиопассивное прошедшее с ударением", "Различить форму и возвратное/пассивное/лексическое значение", "Передать процесс, завершение и известного агента в новом рассказе"], "microcompetency_ids": ["U-B1-010-MC01", "U-B1-010-MC02", "U-B1-010-MC03"], "primary_competencies": ["B1-G04"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
