3157	unit	U-B1-011	16fb5bac500451fb3a48600dfdd04ecf5dfe1ad42226a90212a7c2945ccad900	core	{"unit_id": "U-B1-011", "content_hash": "16fb5bac500451fb3a48600dfdd04ecf5dfe1ad42226a90212a7c2945ccad900", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-011.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "DRAFT", "rubrics": ["U-B1-011-RUBRIC"], "unit_id": "U-B1-011", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-B1-011-I02", "U-B1-011-I03", "U-B1-011-I04", "U-B1-011-I05", "U-B1-011-I06", "U-B1-011-I07", "U-B1-011-I08", "U-B1-011-I09"], "reception": ["U-B1-011-I10", "U-B1-011-I11", "U-B1-011-I12", "U-B1-011-I13"], "retention": ["U-B1-011-I17", "U-B1-011-I18", "U-B1-011-I19"], "diagnostic": ["U-B1-011-I01"], "production": ["U-B1-011-I14", "U-B1-011-I15", "U-B1-011-I16"]}, "title_ru": "Два действия одного человека и состояние результата", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Сначала спросите, что сообщаете: «как человек действует?» или «в каком состоянии находится предмет/человек?». В Περπατώ μιλώντας στο τηλέφωνο один человек одновременно идёт и разговаривает. Μιλώντας не обозначает пол, число или самостоятельное время. Сравните Ο Νίκος μπήκε χαμογελώντας и Τα παιδιά μπήκαν χαμογελώντας: изменилось сказуемое, но не χαμογελώντας. Для учебной продукции в этом уроке исполнитель обоих действий должен быть одним и тем же. Если люди разные, выберите две личные формы: Ενώ εγώ διάβαζα, η Άννα μαγείρευε. Не сокращайте это до Διαβάζοντας, η Άννα μαγείρευε: получится другое распределение действий.\\nОт настоящей основы: γράφω → γράφοντας, διαβάζω → διαβάζοντας, περιμένω → περιμένοντας. При ударном окончании: μιλώ → μιλώντας, γελώ → γελώντας, περπατώ → περπατώντας. В безударной части -οντας пишется ο, в ударной -ώντας — ώ. Не подставляйте аористную основу: изучаем γράφοντας, не «γράψοντας». Начните с двух коротких предложений, проверьте одного исполнителя, только затем соедините их. Форма может передавать сопутствующее действие или способ: Μαθαίνω ελληνικά διαβάζοντας μικρά κείμενα. Она не заменяет любой союз и не гарантирует последовательность «сначала — потом».\\nДругая задача: Οι πόρτες είναι κλεισμένες. Здесь кλεισμένες согласуется с πόρτες. Учим готовые ряды: κουρασμένος, κουρασμένη, κουρασμένο; κλεισμένος, κλεισμένη, κλεισμένο; γραμμένος, γραμμένη, γραμμένο. Во множественном: κουρασμένοι, κουρασμένες, κουρασμένα. В винительном мужского единственного: Βλέπω έναν κουρασμένο φίλο. Эти формы описывают состояние; существительное определяет род, число, падеж. У γραμμένος сохраняются два μ. Не превращайте -μένος в универсальное окончание для любого глагола: новую лексему проверяйте отдельно.\\nОтличайте событие Η Άννα έκλεισε την πόρτα от состояния Η πόρτα είναι κλεισμένη. Описание состояния само по себе не сообщает, кто и когда закрыл дверь. Не добавляйте эти факты в пересказ. Слово κουρασμένος можно употреблять как знакомую характеристику без освоения всей системы пассивного перфекта. Формы на -όμενος и книжные причастия здесь не вводятся.\\nПрактический порядок: восстановите участников; определите действие или состояние; выберите форму; проверьте ударение/согласование; перескажите без модели. В свободной речи важнее сохранить смысл, чем вставить как можно больше причастий. Если сокращённая фраза затрудняет понимание, две ясные фразы лучше. Самостоятельность проверяется на новых людях и предметах, а не переписыванием образца.\\nЛексическая опора для переноса: πλένω → πλυμένος, πλυμένη, πλυμένο; τα πιάτα είναι πλυμένα — тарелки вымыты. Κολλώ → κολλημένος, κολλημένη, κολλημένο; οι φωτογραφίες είναι κολλημένες — фотографии приклеены. Это отдельные изучаемые ряды, не правило образования от любого глагола. Ανακατεύω τη σούπα — помешиваю суп; ανακάτευα — помешивал. Сначала используйте опору, затем возвращайтесь к заданию без неё.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Η Άννα μπήκε χαμογελώντας.", "Τα παιδιά μπήκαν χαμογελώντας.", "Έμαθα τη διαδρομή περπατώντας στη γειτονιά.", "Οι οδηγίες είναι γραμμένες στα ελληνικά.", "Βλέπω έναν κουρασμένο φίλο.", "Ενώ εγώ διάβαζα, η Άννα μαγείρευε."], "review_plan": {"days": [7, 14, 28], "rule": "Новая самостоятельная попытка; помощь фиксировать отдельно; нет эмпирически подтверждённого mastery.", "item_ids": ["U-B1-011-I17", "U-B1-011-I18", "U-B1-011-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "§6.2ι, lines 250–255", "source_id": "N405", "checked_on": "2026-10-19", "claim_scope": ["Invariant -οντας/-ώντας; stressed omega versus unstressed omicron", "-μένος inflects for gender and number; not every verb forms it"], "evidence_type": "OFFICIAL_GRAMMAR_OR_DICTIONARY", "evidence_record": "B06-S01", "evidence_status": "SOURCE_PASS_BOUNDED_CLAIMS"}], "active_recall": ["U-B1-011-I08", "U-B1-011-I09"], "prerequisites": ["A2-G08", "B1-G04"], "reading_tasks": ["U-B1-011-I10", "U-B1-011-I11"], "transfer_task": "U-B1-011-I16", "writing_tasks": ["U-B1-011-I14"], "competency_ids": ["B1-G12"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B1-011-I15"], "errors_taxonomy": ["TARGET_FORM", "MEANING_DISTORTION", "AGENT_REFERENCE", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-B1-011-I02", "U-B1-011-I03", "U-B1-011-I04", "U-B1-011-I05", "U-B1-011-I06", "U-B1-011-I07"], "listening_tasks": ["U-B1-011-I12", "U-B1-011-I13"], "learning_outcome": "Различать неизменяемое сопутствующее действие и согласуемое состояние", "mastery_contract": {"audio": "Не оценивается без аудио", "unaided": "Две самостоятельные реплики без модели", "observed": false, "transfer": "Все условия новой ситуации; целевая форма=2, другие критерии≥1", "retention": "D7/D14/D28 без подсказок плюс новая свободная реплика", "controlled": "≥80% целевых форм; смысловая ошибка требует повторного обучения"}, "vocabulary_items": [{"lemma": "χαμογελώ", "stress": "χαμογελώ", "example": "Μπήκε χαμογελώντας.", "inflection": "χαμογελώντας", "meaning_ru": "улыбаться", "collocations": ["χαμογελώ"]}, {"lemma": "γράφω", "stress": "γράφω", "example": "Οι οδηγίες είναι γραμμένες εδώ.", "inflection": "γράφοντας / γραμμένος, -η, -ο", "meaning_ru": "писать", "collocations": ["γράφω"]}, {"lemma": "κουρασμένος", "stress": "κουρασμένος", "example": "Είμαστε κουρασμένοι.", "inflection": "κουρασμένη, κουρασμένο; κουρασμένοι", "meaning_ru": "уставший", "collocations": ["κουρασμένος"]}, {"lemma": "κλεισμένος", "stress": "κλεισμένος", "example": "Οι πόρτες είναι κλεισμένες.", "inflection": "κλεισμένη, κλεισμένο; κλεισμένες", "meaning_ru": "закрытый", "collocations": ["κλεισμένος"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B1-011-I01"], "learning_objectives": ["Различать неизменяемое сопутствующее действие и согласуемое состояние", "Образовывать изученные -οντας/-ώντας и согласовывать частотные -μένος", "Самостоятельно передавать способ действия и состояние, сохраняя исполнителя"], "microcompetency_ids": ["U-B1-011-MC01", "U-B1-011-MC02", "U-B1-011-MC03"], "primary_competencies": ["B1-G12"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
