3158	unit	U-B1-012	4d5cf76875b1c6018a65de95f74885d644cf36f41fdddad54f5268d73677d713	core	{"unit_id": "U-B1-012", "content_hash": "4d5cf76875b1c6018a65de95f74885d644cf36f41fdddad54f5268d73677d713", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-012.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "DRAFT", "rubrics": ["U-B1-012-RUBRIC"], "unit_id": "U-B1-012", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-B1-012-I02", "U-B1-012-I03", "U-B1-012-I04", "U-B1-012-I05", "U-B1-012-I06", "U-B1-012-I07", "U-B1-012-I08", "U-B1-012-I09"], "reception": ["U-B1-012-I10", "U-B1-012-I11", "U-B1-012-I12", "U-B1-012-I13"], "retention": ["U-B1-012-I17", "U-B1-012-I18", "U-B1-012-I19"], "diagnostic": ["U-B1-012-I01"], "production": ["U-B1-012-I14", "U-B1-012-I15", "U-B1-012-I16"]}, "title_ru": "Уточнить, о ком речь: που и узнавание ο οποίος", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "В разговоре недостаточно сказать «женщина» или «книга»: собеседник может видеть несколько. Относительное предложение добавляет признак: Η γυναίκα που δουλεύει στη βιβλιοθήκη είναι η Ελένη. Сначала найдите существительное γυναίκα, затем признак δουλεύει στη βιβλιοθήκη. Здесь именно женщина работает. В Η γυναίκα που συνάντησα είναι η Ελένη встретил её я. Одинаковое που не показывает, является ли женщина исполнителем или объектом: это выясняют по всему предложению, в том числе по окончанию глагола. Μου έδωσες το βιβλίο που ζήτησα: попросил я, дал ты. Не меняйте участников при пересказе.\\nΠου не меняется по роду и числу: ο φίλος που μένει εδώ, η φίλη που μένει εδώ, τα παιδιά που μένουν εδώ. Согласуется личный глагол, если названное существительное — его подлежащее. Относительное που пишется без ударения; вопросительное πού («где?») — с ударением: Πού είναι το βιβλίο που αγόρασες; Это две разные функции. Не вставляйте лишнее προσωπικό местоимение механически: для нашего простого образца Το βιβλίο που διαβάζω достаточно, не требуется повторять объект как το.\\nВ объявлениях и более формальном письме встретятся ο οποίος, η οποία, το οποίο. На этом уровне цель — узнать форму и точно понять сообщение; свободное владение всей парадигмой не объявляется освоенным. Род и число идут от слова, к которому относится форма, а падеж — от её роли внутри относительного предложения. Узнаём: ο οποίος/η οποία/το οποίο; οι οποίοι/οι οποίες/τα οποία — подлежащие. Τον οποίο/την οποία/το οποίο; τους οποίους/τις οποίες/τα οποία — прямые объекты. В Η υπάλληλος την οποία κάλεσα απάντησε η υπάλληλος — подлежащее главного απάντησε, но την οποία — объект κάλεσα. Не копируйте падеж существительного автоматически. С предлогом: Η συνάδελφος με την οποία μίλησα — я говорил с коллегой. Для свободной речи можно безопасно разделить: Μίλησα με μια συνάδελφο. Η συνάδελφος με βοήθησε. Относительные притяжательные формы здесь не требуются.\\nΠου нормально и в нейтральной письменной речи; ο οποίος не делает текст автоматически «лучше». Склоняемая форма может помочь уточнить референцию. Если фраза длинная и непонятно, к чему относится που, назовите нужный предмет отдельно: Παρέλαβα την τσάντα με τα έγγραφα. Τα έγγραφα που έστειλες είναι μέσα. Не пытайтесь угадывать намерение автора при двух возможных связях: попросите уточнение Ποιο ακριβώς εννοείς; В этом уроке ясное повторение существительного допускается и в устном ответе.\\nРазличайте необходимый признак и добавочную информацию. Οι μαθητές που έχουν κάρτα μπαίνουν δωρεάν: льгота для тех учеников, у кого есть карта; про остальных правило не утверждается. Η Μαρία, που εργάζεται εδώ, θα μας βοηθήσει: Μαρία уже названа, работа здесь — дополнительное сообщение, обособленное запятыми. Не добавляйте запятые просто перед любым που. В заданиях мы даём достаточный контекст для выбранного прочтения.\\nРабочий алгоритм: найдите опорное существительное; восстановите полную простую фразу без относительного слова; проверьте участников; соедините с που или распознайте письменную форму; спросите себя, исключает ли признак другие объекты. Сначала выполните знакомое различение A2-G12 и B1-G01. Если вы путаете объект и подлежащее, вернитесь к двум коротким предложениям, а не заучивайте длинную формулу. Проверка переноса требует нового человека и нового предмета; повторение готового диалога считается практикой с опорой.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Ο φίλος που δουλεύει εδώ είναι ο Πέτρος.", "Ο φίλος που κάλεσα είναι ο Πέτρος.", "Η υπάλληλος την οποία κάλεσα απάντησε.", "Οι αιτήσεις τις οποίες στείλατε έφτασαν.", "Πού είναι το κλειδί που βρήκες;", "Τα βιβλία που έχουν κόκκινη ετικέτα είναι για παιδιά."], "review_plan": {"days": [7, 14, 28], "rule": "Новая самостоятельная попытка; помощь фиксировать отдельно; нет эмпирически подтверждённого mastery.", "item_ids": ["U-B1-012-I17", "U-B1-012-I18", "U-B1-012-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "§5.6 lines 65–69", "source_id": "N410", "checked_on": "2026-10-19", "claim_scope": ["που invariant; ο οποίος inflected with article", "Inflected relative can disambiguate reference and occurs in formal register"], "evidence_type": "OFFICIAL_GRAMMAR_OR_DICTIONARY", "evidence_record": "B06-S03", "evidence_status": "SOURCE_PASS_BOUNDED_CLAIMS"}, {"anchor": "§5.2γ lines 53–55", "source_id": "N404", "checked_on": "2026-10-19", "claim_scope": ["Restrictive versus supplementary relative clauses and comma distinction"], "evidence_type": "OFFICIAL_GRAMMAR_OR_DICTIONARY", "evidence_record": "B06-S04", "evidence_status": "SOURCE_PASS_BOUNDED_CLAIMS"}], "active_recall": ["U-B1-012-I08", "U-B1-012-I09"], "prerequisites": ["A2-G12", "B1-G01"], "reading_tasks": ["U-B1-012-I10", "U-B1-012-I11"], "transfer_task": "U-B1-012-I16", "writing_tasks": ["U-B1-012-I14"], "competency_ids": ["B1-G08"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B1-012-I15"], "errors_taxonomy": ["TARGET_FORM", "MEANING_DISTORTION", "AGENT_REFERENCE", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-B1-012-I02", "U-B1-012-I03", "U-B1-012-I04", "U-B1-012-I05", "U-B1-012-I06", "U-B1-012-I07"], "listening_tasks": ["U-B1-012-I12", "U-B1-012-I13"], "learning_outcome": "Определять, к какому существительному относится относительное предложение и кто выполняет действие", "mastery_contract": {"audio": "Не оценивается без аудио", "unaided": "Две самостоятельные реплики без модели", "observed": false, "transfer": "Все условия новой ситуации; целевая форма=2, другие критерии≥1", "retention": "D7/D14/D28 без подсказок плюс новая свободная реплика", "controlled": "≥80% целевых форм; смысловая ошибка требует повторного обучения"}, "vocabulary_items": [{"lemma": "η αίτηση", "stress": "η αίτηση", "example": "Η αίτηση που έστειλα έφτασε.", "inflection": "οι αιτήσεις", "meaning_ru": "заявление", "collocations": ["η αίτηση"]}, {"lemma": "ο υπάλληλος", "stress": "ο υπάλληλος", "example": "Η υπάλληλος που με βοήθησε λέγεται Εύα.", "inflection": "η υπάλληλος; οι υπάλληλοι", "meaning_ru": "сотрудник", "collocations": ["ο υπάλληλος"]}, {"lemma": "η ετικέτα", "stress": "η ετικέτα", "example": "Ψάχνω την τσάντα που έχει μπλε ετικέτα.", "inflection": "οι ετικέτες", "meaning_ru": "этикетка", "collocations": ["η ετικέτα"]}, {"lemma": "το έγγραφο", "stress": "το έγγραφο", "example": "Τα έγγραφα που ζήτησες είναι εδώ.", "inflection": "τα έγγραφα", "meaning_ru": "документ", "collocations": ["το έγγραφο"]}, {"lemma": "εννοώ", "stress": "εννοώ", "example": "Ποιο βιβλίο εννοείς;", "inflection": "εννοείς; εννοούσα", "meaning_ru": "иметь в виду", "collocations": ["εννοώ"]}, {"lemma": "δωρεάν", "stress": "δωρεάν", "example": "Τα παιδιά που έχουν κάρτα μπαίνουν δωρεάν.", "inflection": "неизменяемое", "meaning_ru": "бесплатно", "collocations": ["δωρεάν"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B1-012-I01"], "learning_objectives": ["Определять, к какому существительному относится относительное предложение и кто выполняет действие", "Узнавать род, число и роль форм ο οποίος в знакомом контексте и перефразировать через που", "Самостоятельно уточнять человека или предмет с που, устраняя двусмысленность"], "microcompetency_ids": ["U-B1-012-MC01", "U-B1-012-MC02", "U-B1-012-MC03"], "primary_competencies": ["B1-G08"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
