3159	unit	U-B1-013	cba183deb74f1396731fc1fa2f88aea1cbcc4b461d1088dac4187128a6f3638e	core	{"unit_id": "U-B1-013", "content_hash": "cba183deb74f1396731fc1fa2f88aea1cbcc4b461d1088dac4187128a6f3638e", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-013.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "DRAFT", "rubrics": ["U-B1-013-RUBRIC"], "unit_id": "U-B1-013", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-B1-013-I02", "U-B1-013-I03", "U-B1-013-I04", "U-B1-013-I05", "U-B1-013-I06", "U-B1-013-I07", "U-B1-013-I08", "U-B1-013-I09"], "reception": ["U-B1-013-I10", "U-B1-013-I11", "U-B1-013-I12", "U-B1-013-I13"], "retention": ["U-B1-013-I17", "U-B1-013-I18", "U-B1-013-I19"], "diagnostic": ["U-B1-013-I01"], "production": ["U-B1-013-I14", "U-B1-013-I15", "U-B1-013-I16"]}, "title_ru": "Сначала, после и до момента: πριν, αφού, μέχρι", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Союз сообщает отношение между событиями, а не просто делает фразу длиннее. Αφού έλεγξα τη διεύθυνση, έστειλα το γράμμα: проверка была раньше отправки. Πριν στείλω το γράμμα, έλεγξα τη διεύθυνση: то же отношение выражено с другой точки зрения. Вторая фраза не говорит, что отправка была первой только потому, что слово στείλω стоит раньше в строке. При чтении выпишите действия, затем расположите их во времени.\\nΠριν с существительным и πριν с глаголом строятся по-разному. Πριν από το μάθημα — перед уроком; πριν φύγω / πριν να φύγω — перед тем как я уйду. После πριν не ставим θα в изучаемом образце будущего: Θα σε πάρω πριν φύγω. Форма φύγω сама по себе не сообщает прошлое; её время определяется всей ситуацией. В Χτες σε πήρα πριν φύγω звонок уже состоялся вчера. Не заменяйте ожидаемую/зависимую форму механически прошедшим έφυγα. На этом этапе учим модели πριν φύγω, πριν αρχίσουμε, πριν στείλεις. Безопасная перефразировка: сначала две личные фразы с πρώτα/μετά, затем одна с πριν.\\nΑφού в данном временном употреблении показывает, что событие придаточного предшествует следующему шагу: Αφού τελείωσα την εργασία, βγήκα έξω. В будущем плане: Αφού τελειώσω, θα σου τηλεφωνήσω. Знакомые пары: τελειώνω/τελειώσω, ελέγχω/ελέγξω, στέλνω/στείλω, φτάνω/φτάσω, αρχίζω/αρχίσω. Они даются как лексическая опора; их не надо угадывать по универсальному окончанию. Αφού бывает и причинным («раз/поскольку»): Αφού είσαι εδώ, βοήθησέ με. Чтобы проверить временное понимание, наши задания задают последовательные события; не выводите «после» из каждого αφού без контекста.\\nΜέχρι с временем задаёт границу: Θα μείνω μέχρι τις έξι. С ожидаемым событием используем μέχρι να: Θα περιμένω μέχρι να έρθει η Άννα. Ожидание продолжается до её прихода; μέχρι не значит «после». С прошедшей рамкой тоже возможно Περίμενα μέχρι να έρθει η Άννα: пришла позже начала ожидания. Не делайте из να доказательство будущего времени. Для определённого времени сравните μέχρι τις έξι и πριν από τις έξι: первое задаёт предел, второе требует раньше шести. При неоднозначной бытовой договорённости уточните время, а не угадывайте, включается ли предельная минута в срок.\\nФорма глагола зависит от представления действия. В этом уроке сначала один конкретный план: πριν φύγω, αφού τελειώσω, μέχρι να φτάσει. Для привычного процесса в контексте встречаются формы настоящей основы, но полное владение всеми видовыми комбинациями здесь не заявляется. Не используйте только порядок союзов как доказательство, что поручение уже выполнено: Θα στείλω το αρχείο αφού το ελέγξω — это обещание, не отчёт о готовом файле.\\nРабочая опора: выпишите «что раньше», «что позже» и «до какого момента продолжается действие»; выберите союз; восстановите лицо и знакомую форму; проверьте, является ли всё сообщённое фактом или планом. При изменении плана сохраните обязательное условие: если файл можно отправить только после проверки, опоздание проверяющего не даёт права объявить отправку завершённой. Самостоятельность проверяем в другой ситуации на D7/D28. Если путается порядок действий, вернитесь к A2-G11 и B1-G05; назовите два шага отдельно.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Πριν από τη συνάντηση θα αγοράσω νερό.", "Θα αγοράσω νερό πριν αρχίσει η συνάντηση.", "Αφού διάβασα το μήνυμα, απάντησα.", "Αφού τελειώσω, θα σε πάρω.", "Θα περιμένουμε μέχρι να ανοίξει η πόρτα.", "Περίμενα μέχρι να έρθει η Εύα."], "review_plan": {"days": [7, 14, 28], "rule": "Новая самостоятельная попытка; помощь фиксировать отдельно; нет эмпирически подтверждённого mastery.", "item_ids": ["U-B1-013-I17", "U-B1-013-I18", "U-B1-013-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "§5.2β lines 48–52; causal αφού lines 32–33", "source_id": "N404", "checked_on": "2026-10-19", "claim_scope": ["Temporal clauses and expected events; αφού also causal"], "evidence_type": "OFFICIAL_GRAMMAR_OR_DICTIONARY", "evidence_record": "B06-S05", "evidence_status": "SOURCE_PASS_BOUNDED_CLAIMS"}, {"anchor": "Λεξικό Τριανταφυλλίδη μέχρι I.1, IV.2; lines 138,141–142", "source_id": "N-B06-MEXRI", "checked_on": "2026-10-19", "claim_scope": ["Accusative temporal endpoint; μέχρι να for expected event and past narrative endpoint"], "evidence_type": "OFFICIAL_GRAMMAR_OR_DICTIONARY", "evidence_record": "B06-S06", "evidence_status": "SOURCE_PASS_BOUNDED_CLAIMS"}], "active_recall": ["U-B1-013-I08", "U-B1-013-I09"], "prerequisites": ["A2-G11", "B1-G05"], "reading_tasks": ["U-B1-013-I10", "U-B1-013-I11"], "transfer_task": "U-B1-013-I16", "writing_tasks": ["U-B1-013-I14"], "competency_ids": ["B1-G11"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B1-013-I15"], "errors_taxonomy": ["TARGET_FORM", "MEANING_DISTORTION", "AGENT_REFERENCE", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-B1-013-I02", "U-B1-013-I03", "U-B1-013-I04", "U-B1-013-I05", "U-B1-013-I06", "U-B1-013-I07"], "listening_tasks": ["U-B1-013-I12", "U-B1-013-I13"], "learning_outcome": "Восстанавливать порядок и границу событий по πριν, αφού и μέχρι να", "mastery_contract": {"audio": "Не оценивается без аудио", "unaided": "Две самостоятельные реплики без модели", "observed": false, "transfer": "Все условия новой ситуации; целевая форма=2, другие критерии≥1", "retention": "D7/D14/D28 без подсказок плюс новая свободная реплика", "controlled": "≥80% целевых форм; смысловая ошибка требует повторного обучения"}, "vocabulary_items": [{"lemma": "ελέγχω", "stress": "ελέγχω", "example": "Θα στείλω το αρχείο αφού το ελέγξω.", "inflection": "έλεγξα; να ελέγξω", "meaning_ru": "проверять", "collocations": ["ελέγχω"]}, {"lemma": "στέλνω", "stress": "στέλνω", "example": "Πριν στείλω το μήνυμα, θα το διαβάσω.", "inflection": "έστειλα; να στείλω", "meaning_ru": "отправлять", "collocations": ["στέλνω"]}, {"lemma": "φτάνω", "stress": "φτάνω", "example": "Περίμενε μέχρι να φτάσω.", "inflection": "έφτασα; να φτάσω", "meaning_ru": "прибывать", "collocations": ["φτάνω"]}, {"lemma": "αρχίζω", "stress": "αρχίζω", "example": "Θα φύγω πριν αρχίσει η ταινία.", "inflection": "άρχισα; να αρχίσω", "meaning_ru": "начинать", "collocations": ["αρχίζω"]}, {"lemma": "το αρχείο", "stress": "το αρχείο", "example": "Το αρχείο δεν είναι έτοιμο.", "inflection": "τα αρχεία", "meaning_ru": "файл", "collocations": ["το αρχείο"]}, {"lemma": "ο έλεγχος", "stress": "ο έλεγχος", "example": "Η αποστολή θα γίνει μετά τον έλεγχο.", "inflection": "οι έλεγχοι", "meaning_ru": "проверка", "collocations": ["ο έλεγχος"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B1-013-I01"], "learning_objectives": ["Восстанавливать порядок и границу событий по πριν, αφού и μέχρι να", "Строить изученные временные конструкции, различая время с существительным и событие с глаголом", "Самостоятельно объяснять последовательность и менять план без потери временных условий"], "microcompetency_ids": ["U-B1-013-MC01", "U-B1-013-MC02", "U-B1-013-MC03"], "primary_competencies": ["B1-G11"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
