2708	competency	A2-G07	174dd785f6f86d0530062c432dd3162188be35860e1e2cd938b9bc659137a955	core	{"name": "Императив частотных глаголов и вежливые альтернативы", "level": "A2", "competency_id": "A2-G07", "prerequisites": ["A2-G06"], "content_complete": false, "primary_unit_ids": ["U-A2-005"], "incidental_unit_ids": ["U-A2-005"], "current_coverage_status": "PARTIAL_AUTHORED_NOT_RELEASED", "coverage_status_at_baseline": "PARTIAL_AUTHORED_NOT_RELEASED"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3160	unit	U-B1-014	153b69aaa01360540dcb610d534d9d5ca7c83644c482461cf419aa773c0546e3	core	{"unit_id": "U-B1-014", "content_hash": "153b69aaa01360540dcb610d534d9d5ca7c83644c482461cf419aa773c0546e3", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-014.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "independent_linguistic_review": "NOT_REVIEWED"}, "rubrics": ["U-B1-014-RUBRIC"], "unit_id": "U-B1-014", "version": "0.1.0", "title_ru": "Семьи слов: узнавание формы и проверка значения", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Словообразование помогает читать незнакомую лексику, но не позволяет угадывать любое слово без проверки. Наша задача — узнавать знакомую семью и выбирать слово нужной роли: действие, человека, предмет или признак. Сначала повторите из A2-V02 названия занятий и описание человека. В предложении «Η Μαρία δουλεύει εδώ» найдите действие; в «Η Μαρία είναι υπάλληλος» — название человека. Если эти роли смешиваются, вернитесь к простым предложениям, прежде чем разбирать длинные слова.\\nСравните διαβάζω — διάβασμα: первое обозначает действие и меняется по лицам; второе является существительным. Διαβάζω — διαβάζεις — διαβάζουμε остаются формами одного глагола. Образование нового слова и изменение грамматической формы — разные операции. Учите семью вместе с артиклем, ударением и коротким употреблением, а не как цепочку русских переводов. Το διάβασμα χρειάζεται χρόνο. Не вставляйте διάβασμα туда, где предложение требует личного глагола.\\nВ изучаемых примерах окончания помогают различать функции: εκπαιδεύω — εκπαιδευτής, организую обучение — человек, который обучает; οργανώνω — οργάνωση, действие или его результат в подходящем контексте. Это ограниченные лексические модели, не команда присоединять -τής или -ση к любому глаголу. Семья не гарантирует одинакового перевода: η εργασία может обозначать работу или учебное задание; нужное значение выбираем из ситуации. Новую форму, которой не было в материале, сначала проверяем в словаре.\\nΞαναγράφω означает «пишу снова». В просьбе Ξαναγράψε το όνομά σου речь о повторении записи, а не о её удалении. Узнайте также пару κλειδώνω — ξεκλειδώνω: запираю — отпираю. Из этой пары нельзя заключить, что любое ξε- всегда выражает противоположность. Несколько значений приставки существуют одновременно, поэтому для нового слова нужно прочитать целую фразу. В этом уроке продуктивно используем только явно введённые пары.\\nПри сложении слов встречаются изменения основы и ударения. Το βιβλιοπωλείο продаёт книги; η βιβλιοθήκη хранит книги и может их выдавать. Общая часть βιβλιο- помогает определить тему, но не отличить магазин от библиотеки. Выпишите различающий признак каждого слова. Ударение запоминайте в целом слове: не переносите его механически с первой части. Слово, похожее на известное, проверяйте по функции и контексту.\\nРабочая последовательность такая: прочитайте всё предложение, определите требуемую часть речи, найдите знакомую часть, предложите ограниченную гипотезу и проверьте смысл. Затем составьте собственное сообщение. Если забыли название, объясните функцию: Είναι το μέρος όπου αγοράζουμε βιβλία. Такая перифраза лучше выдуманного слова. Контроль после урока требует нового примера, а через семь и двадцать восемь дней — объяснения без таблицы. Быстрое узнавание в списке ещё не доказывает самостоятельного использования.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "entry_probe": {"prompt": "Назовите по-гречески место работы и действие знакомого человека; отличите εργάζεται от υπάλληλος.", "expected": "Личный глагол описывает действие, существительное человека.", "remediation_unit": "U-A2-012"}, "examples_el": ["Το διάβασμα χρειάζεται χρόνο.", "Ο εκπαιδευτής εξηγεί την άσκηση.", "Θα ξαναγράψω το μήνυμα.", "Μπορείς να ξεκλειδώσεις την πόρτα;", "Αγοράζω βιβλία στο βιβλιοπωλείο.", "Δανείζομαι βιβλία από τη βιβλιοθήκη."], "review_plan": {"days": [7, 14, 28], "rule": "Fresh independent attempts before feedback; schedule from actual lesson date, not exam date", "item_ids": ["U-B1-014-I17", "U-B1-014-I18", "U-B1-014-I19"]}, "source_refs": [{"anchor": "§2.2 lines13–38; §2.3 lines46–49", "source_id": "CP07-B1-S01", "checked_on": "2026-10-20", "claim_scope": "Word families; derivation versus inflection; prefixes have more than one meaning; compounding and variable stress; polysemy. Original vocabulary examples separately require linguistic QA."}, {"anchor": "Reading lines92–96; production98–103; education/work139–145; travel147–152", "source_id": "CP07-B1-S02", "checked_on": "2026-10-20", "claim_scope": "B1 functional scope: main idea/details of familiar texts, routine institutional and travel communication, explanatory circumlocution. No approval of particular GreekOS item, time or mastery threshold."}, {"anchor": "ξανα- entry; indexed search excerpt turn168search6", "source_id": "CP07-B1-S03", "checked_on": "2026-10-20", "claim_scope": "ξανα- marks repetition; ξαναγράφω among examples. Direct page open403, so only indexed excerpt inspected."}], "active_recall": ["U-B1-014-I08", "U-B1-014-I09"], "prerequisites": ["A2-V02"], "reading_tasks": ["U-B1-014-I10", "U-B1-014-I11"], "transfer_task": "U-B1-014-I16", "writing_tasks": ["U-B1-014-I14"], "competency_ids": ["B1-G13"], "coverage_claim": "Partial macro evidence; not full competency verification", "speaking_tasks": ["U-B1-014-I15"], "errors_taxonomy": ["VOCAB_SELECTION", "COLLOCATION", "CONTENT_OMISSION", "COMPREHENSION", "PRAGMATICS_REGISTER", "ORTHOGRAPHY_ACCENT", "ASR_UNCERTAIN"], "guided_practice": ["U-B1-014-I02", "U-B1-014-I03", "U-B1-014-I04", "U-B1-014-I05", "U-B1-014-I06", "U-B1-014-I07"], "listening_tasks": ["U-B1-014-I12", "U-B1-014-I13"], "learning_outcome": "Самостоятельно использовать изученное для новой коммуникативной задачи, сохраняя смысл и ограничения ситуации.", "mastery_contract": {"observed": false, "recognition": "At least4/5 relevant checks and explanation of distractor", "retention_transfer": "New unaided D7 and D28 evidence; assistance recorded separately", "independent_production": "Complete task without copying model, all critical facts correct"}, "vocabulary_items": [{"lemma": "το διάβασμα", "stress": "το διάβασμα", "example": "Το διάβασμα με βοηθά.", "inflection": "του διαβάσματος", "meaning_ru": "чтение/учёба", "collocations": ["χρειάζεται διάβασμα"]}, {"lemma": "ο εκπαιδευτής", "stress": "ο εκπαιδευτής", "example": "Ο εκπαιδευτής απαντά.", "inflection": "η εκπαιδεύτρια; οι εκπαιδευτές", "meaning_ru": "преподаватель/инструктор", "collocations": ["εκπαιδευτής ενηλίκων"]}, {"lemma": "η οργάνωση", "stress": "η οργάνωση", "example": "Η οργάνωση θέλει χρόνο.", "inflection": "οι οργανώσεις", "meaning_ru": "организация", "collocations": ["οργάνωση εργαστηρίου"]}, {"lemma": "ξαναγράφω", "stress": "ξαναγράφω", "example": "Θα ξαναγράψω το μήνυμα.", "inflection": "ξαναέγραψα; θα ξαναγράψω", "meaning_ru": "писать снова", "collocations": ["ξαναγράφω το μήνυμα"]}, {"lemma": "ξεκλειδώνω", "stress": "ξεκλειδώνω", "example": "Ξεκλείδωσα την πόρτα.", "inflection": "ξεκλείδωσα; θα ξεκλειδώσω", "meaning_ru": "отпирать", "collocations": ["ξεκλειδώνω την πόρτα"]}, {"lemma": "το βιβλιοπωλείο", "stress": "το βιβλιοπωλείο", "example": "Το βιβλιοπωλείο είναι κοντά.", "inflection": "τα βιβλιοπωλεία", "meaning_ru": "книжный магазин", "collocations": ["αγοράζω στο βιβλιοπωλείο"]}], "remediation_policy": "До основного урока выполнить входную пробу без образца. При смысловой ошибке открыть указанный prerequisite unit, выполнить новую аналогичную пробу; подсказанную попытку не считать освоением.", "diagnostic_item_ids": ["U-B1-014-I01"], "learning_objectives": ["Различать новую лексему и формы одного слова", "Выбирать введённое производное/сложное слово по функции и контексту", "Объяснять значение и самостоятельно применять изученную семью в новой ситуации"], "microcompetency_ids": ["U-B1-014-MC01", "U-B1-014-MC02", "U-B1-014-MC03"], "primary_competencies": ["B1-G13"], "prerequisite_unit_ids": ["U-A2-012"], "estimated_active_minutes": 90, "self_explanation_item_id": "U-B1-014-I20"}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
