818	source_claim	CP08-INHERITED-U-A1-018-I06-01	cbac5e4259e59d5d2a9beaa0e8fa2ce2c391a17ffaeea277172ded7c9694f1d7	\N	{"record": {"claim": "Functional scope only; no institutional endorsement of original tasks, thresholds, language forms or CEFR mediation descriptor.", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A1-018-I06-01", "item_ids": ["U-A1-018-I06"], "source_id": "CP06-A1-S01", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A1-018-I06.json", "sha256": "2a74bf2dde20152bf0e16e71befd68ff1e60be934fdfcb1557379390bf9eee72"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "Γενικός Εκπαιδευτικός Στόχος, L83–84; Κατανόηση γραπτού λόγου, L98–100; Παραγωγή προφορικού λόγου,L105", "source_id": "CP06-A1-S01", "checked_on": "2026-10-20", "claim_scope": "Functional scope only; no institutional endorsement of original tasks, thresholds, language forms or CEFR mediation descriptor.", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR_REINSPECTED"}}, "claim_id": "CP08-INHERITED-U-A1-018-I06-01", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3161	unit	U-B1-015	889cac7ddda39a07418e32b591e433587648b03bf77ddc728fd4eaf6dd801617	core	{"unit_id": "U-B1-015", "content_hash": "889cac7ddda39a07418e32b591e433587648b03bf77ddc728fd4eaf6dd801617", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-015.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "independent_linguistic_review": "NOT_REVIEWED"}, "rubrics": ["U-B1-015-RUBRIC"], "unit_id": "U-B1-015", "version": "0.1.0", "title_ru": "Учёба, работа, технологии и услуги: точный запрос", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "В бытовом разговоре можно сказать «у меня проблема», но в учебном заведении, на работе и в службе этого часто недостаточно. Адресат должен понять, что вы хотите сделать, какой этап уже выполнен и какой информации не хватает. В этом уроке мы связываем знакомую лексику A2 о жилье, здоровье и работе с последовательностью действий: получить сведения, отправить документ, записаться, подтвердить получение и уточнить следующий шаг. Личные данные в тренировке заменяйте вымышленными; умение объяснить запрос важнее настоящего номера документа.\\nРазличайте αίτηση и εγγραφή. Υποβάλλω αίτηση — подаю заявление или заявку; κάνω εγγραφή — записываюсь. В конкретном процессе заявка может предшествовать записи, но слова не взаимозаменяемы и не устанавливают единых правил для всех служб. Η αίτηση στάλθηκε означает отправку; Η εγγραφή ολοκληρώθηκε — завершённую запись. Отправка ещё не доказывает, что адресат получил документ или принял заявку. Поэтому полезно спросить: Μπορείτε να επιβεβαιώσετε ότι λάβατε την αίτηση;\\nСлово δικαιολογητικά обозначает подтверждающие документы в административном контексте. Τα απαραίτητα δικαιολογητικά — нужные документы; не придумывайте их перечень, если его нет в объявлении. Η προθεσμία — срок: Η προθεσμία λήγει την Παρασκευή. Μέχρι την Παρασκευή сообщает границу, но в реальной процедуре нужно отдельно уточнить точное время, если это влияет на действие. Закрепите связки: κλείνω ραντεβού, επισυνάπτω ένα αρχείο, λαμβάνω επιβεβαίωση. Учим выражение в предложении, а не отдельный перевод.\\nДля работы и обучения различайте θέση εργασίας, ωράριο и μάθημα. Θέση εργασίας — вакансия или рабочее место в контексте; ωράριο — расписание рабочих часов; πρόγραμμα может обозначать программу или расписание и требует уточнения. Вопрос Ποιο είναι το ωράριο; не сообщает зарплату. Если объявление не содержит оплаты, спрашивайте об этом отдельно. Не заменяйте отсутствующие факты привычными представлениями о работе учреждения.\\nЦифровая коммуникация требует точного описания сбоя: Δεν μπορώ να ανοίξω το αρχείο, а не просто Δεν δουλεύει. Уточните устройство или действие только когда это полезно и известно. Το αρχείο δεν ανοίγει στον υπολογιστή μου. Μπορείτε να το στείλετε ξανά σε άλλη μορφή; Это запрос альтернативы, не обвинение адресата. Δεν έχω λάβει επιβεβαίωση сообщает об отсутствии подтверждения; оно не доказывает, что заявка потеряна.\\nВ поездке различайте αναχώρηση и άφιξη: отправление и прибытие. Если встреча после приезда, вам нужно время άφιξης, а не ώρα αναχώρησης. Η αλλαγή αφορά μόνο την αναχώρηση не меняет автоматически остальные условия. Стратегия одна для разных сфер: выделить цель, назвать проверенный факт, сформулировать один точный вопрос и подтвердить понимание. В конце перескажите следующий шаг своими словами: Άρα, στέλνω πρώτα το αρχείο και περιμένω επιβεβαίωση. Успешное упражнение с подсказками ещё не означает самостоятельной коммуникации: повторите запрос в новой сфере без готового текста.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "entry_probe": {"prompt": "Объясните по-гречески, где хотите жить/учиться, и задайте простой вопрос о времени встречи.", "expected": "Понятная цель и вопрос; не нужно знать правила конкретной службы.", "remediation_units": ["U-A2-011", "U-A2-012"]}, "examples_el": ["Υπέβαλα αίτηση για το πρόγραμμα.", "Η εγγραφή δεν έχει ολοκληρωθεί ακόμη.", "Ποια δικαιολογητικά χρειάζονται;", "Δεν μπορώ να ανοίξω το αρχείο.", "Μπορείτε να επιβεβαιώσετε ότι το λάβατε;", "Ποια είναι η ώρα άφιξης;"], "review_plan": {"days": [7, 14, 28], "rule": "Fresh independent attempts before feedback; schedule from actual lesson date, not exam date", "item_ids": ["U-B1-015-I17", "U-B1-015-I18", "U-B1-015-I19"]}, "source_refs": [{"anchor": "Reading lines92–96; production98–103; education/work139–145; travel147–152", "source_id": "CP07-B1-S02", "checked_on": "2026-10-20", "claim_scope": "B1 functional scope: main idea/details of familiar texts, routine institutional and travel communication, explanatory circumlocution. No approval of particular GreekOS item, time or mastery threshold."}], "active_recall": ["U-B1-015-I08", "U-B1-015-I09"], "prerequisites": ["A2-V01", "A2-V02"], "reading_tasks": ["U-B1-015-I10", "U-B1-015-I11"], "transfer_task": "U-B1-015-I16", "writing_tasks": ["U-B1-015-I14"], "competency_ids": ["B1-V01"], "coverage_claim": "Partial macro evidence; not full competency verification", "speaking_tasks": ["U-B1-015-I15"], "errors_taxonomy": ["VOCAB_SELECTION", "COLLOCATION", "CONTENT_OMISSION", "COMPREHENSION", "PRAGMATICS_REGISTER", "ORTHOGRAPHY_ACCENT", "ASR_UNCERTAIN"], "guided_practice": ["U-B1-015-I02", "U-B1-015-I03", "U-B1-015-I04", "U-B1-015-I05", "U-B1-015-I06", "U-B1-015-I07"], "listening_tasks": ["U-B1-015-I12", "U-B1-015-I13"], "learning_outcome": "Самостоятельно использовать изученное для новой коммуникативной задачи, сохраняя смысл и ограничения ситуации.", "mastery_contract": {"observed": false, "recognition": "At least4/5 relevant checks and explanation of distractor", "retention_transfer": "New unaided D7 and D28 evidence; assistance recorded separately", "independent_production": "Complete task without copying model, all critical facts correct"}, "vocabulary_items": [{"lemma": "η αίτηση", "stress": "η αίτηση", "example": "Έστειλα την αίτηση.", "inflection": "οι αιτήσεις", "meaning_ru": "заявка", "collocations": ["υποβάλλω αίτηση"]}, {"lemma": "η εγγραφή", "stress": "η εγγραφή", "example": "Η εγγραφή ολοκληρώθηκε.", "inflection": "οι εγγραφές", "meaning_ru": "запись", "collocations": ["ολοκληρώνω την εγγραφή"]}, {"lemma": "η προθεσμία", "stress": "η προθεσμία", "example": "Η προθεσμία λήγει αύριο.", "inflection": "οι προθεσμίες", "meaning_ru": "срок", "collocations": ["λήγει η προθεσμία"]}, {"lemma": "το δικαιολογητικό", "stress": "το δικαιολογητικό", "example": "Ποια δικαιολογητικά χρειάζονται;", "inflection": "τα δικαιολογητικά", "meaning_ru": "подтверждающий документ", "collocations": ["απαραίτητα δικαιολογητικά"]}, {"lemma": "η επιβεβαίωση", "stress": "η επιβεβαίωση", "example": "Περιμένω επιβεβαίωση.", "inflection": "οι επιβεβαιώσεις", "meaning_ru": "подтверждение", "collocations": ["λαμβάνω επιβεβαίωση"]}, {"lemma": "η άφιξη", "stress": "η άφιξη", "example": "Η ώρα άφιξης άλλαξε.", "inflection": "οι αφίξεις", "meaning_ru": "прибытие", "collocations": ["ώρα άφιξης"]}], "remediation_policy": "До основного урока выполнить входную пробу без образца. При смысловой ошибке открыть указанный prerequisite unit, выполнить новую аналогичную пробу; подсказанную попытку не считать освоением.", "diagnostic_item_ids": ["U-B1-015-I01"], "learning_objectives": ["Различать этапы заявки, получения и подтверждения", "Выбирать точные сочетания для срока, файла и поездки", "Самостоятельно уточнять условие услуги и переносить запрос в новую сферу"], "microcompetency_ids": ["U-B1-015-MC01", "U-B1-015-MC02", "U-B1-015-MC03"], "primary_competencies": ["B1-V01"], "prerequisite_unit_ids": ["U-A2-011", "U-A2-012"], "estimated_active_minutes": 90, "self_explanation_item_id": "U-B1-015-I20"}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3162	unit	U-B1-016	6f44a87de262b8546396ae17572f2ded9deee214b9e5ec841906d1b6f7ac89cc	core	{"unit_id": "U-B1-016", "content_hash": "6f44a87de262b8546396ae17572f2ded9deee214b9e5ec841906d1b6f7ac89cc", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-016.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "independent_linguistic_review": "NOT_REVIEWED"}, "rubrics": ["U-B1-016-RUBRIC"], "unit_id": "U-B1-016", "version": "0.1.0", "title_ru": "Сочетаемость и перифраза: продолжить разговор без нужного слова", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "На уровне B1 не обязательно помнить название каждого предмета. Важно сохранить разговор: объяснить функцию, внешний вид или ситуацию использования и проверить, понял ли собеседник. Перифраза — не длинный перевод русского слова по частям. Это выбор нескольких признаков, которые действительно различают нужный предмет. Перед уроком восстановите одну семью слов из U-B1-014: διαβάζω — διάβασμα. Если вы можете назвать только корень, но не построить предложение, сначала повторите разницу существительного и глагола.\\nНачните с общей категории: Είναι ένα εργαλείο…; Είναι μια συσκευή…; Είναι το μέρος όπου…; Είναι ο άνθρωπος που…. Затем добавьте функцию: …που χρησιμοποιούμε για να ανοίγουμε μπουκάλια. Для предмета иногда достаточно «Χρειάζομαι κάτι για να…». Если забыли ανοιχτήρι, можно сказать Χρειάζομαι ένα εργαλείο για να ανοίξω αυτό το μπουκάλι. Однако собеседнику может понадобиться уточнение: бутылка с пробкой или металлической крышкой? Не выдавайте приблизительное описание за точное название.\\nСочетаемость — привычный выбор слов вместе. В этом уроке отрабатываем ограниченный набор: παίρνω απόφαση, κάνω αίτηση, κλείνω ραντεβού, λύνω ένα πρόβλημα, χάνω το λεωφορείο, φορτίζω το κινητό. Их полезно записывать с одним собственным контекстом. Έχασα το λεωφορείο означает, что вы на него не успели в данном контексте; не утверждает, что автобус как предмет потерялся. Новое сочетание проверяйте отдельно, а не переносите буквально русское управление.\\nПерифраза должна учитывать известную информацию. Θέλω τη συσκευή που φορτίζει το κινητό объясняет функцию зарядного устройства; не нужно добавлять цвет, цену и владельца, если вы их не знаете. Фраза Είναι κόκκινο может помочь найти конкретную вещь среди других, но не определяет её назначение. Сначала сообщите достаточный различающий признак, затем отвечайте на уточнение. Если описание слишком общее, собеседник честно не сможет выбрать один предмет.\\nНе смешивайте уверенное название и гипотезу: Νομίζω ότι λέγεται…; Εννοείτε…; Αυτό είναι; позволяют проверить понимание. Когда вам предложили неподходящий предмет, объясните различие вежливо: Όχι αυτό, χρειάζομαι κάτι για να φορτίσω το κινητό, όχι για να ακούσω μουσική. Отрицание и положительная функция вместе полезнее простого Όχι. Если собеседник исправляет название, повторите его в коротком новом предложении, а не только как эхо.\\nВыбирайте стратегию по ситуации. В аптеке, при опасности или технической неисправности неточное угадывание может изменить смысл: лучше показать безопасный образец, уточнить маркировку или попросить специалиста объяснить, чем уверенно назвать неизвестный препарат или инструмент. Здесь мы тренируем обычные бытовые предметы и коммуникацию, а не медицинскую рекомендацию. Можно прямо сказать Δεν ξέρω την ακριβή λέξη.\\nПроверка самостоятельности проходит так: закройте словарь, объясните новый предмет двумя полезными признаками, ответьте на один неожиданный вопрос и подтвердите результат. Если собеседник понял только после перевода, отметьте помощь, но не считайте попытку провалом общения. Через неделю используйте другую вещь, через двадцать восемь дней — другую ситуацию. Знание списка сочетаний и реальное восстановление разговора фиксируются отдельно.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "entry_probe": {"prompt": "Назовите семью διαβάζω–διάβασμα и объясните роль каждого слова.", "expected": "Глагол действия и существительное; короткий контекст для каждого.", "remediation_unit": "U-B1-014"}, "examples_el": ["Πήρα μια απόφαση.", "Έχασα το λεωφορείο και περίμενα το επόμενο.", "Θέλω να κλείσω ραντεβού.", "Χρειάζομαι κάτι για να ανοίξω το μπουκάλι.", "Νομίζω ότι λέγεται φορτιστής.", "Εννοείτε αυτή τη συσκευή;"], "review_plan": {"days": [7, 14, 28], "rule": "Fresh independent attempts before feedback; schedule from actual lesson date, not exam date", "item_ids": ["U-B1-016-I17", "U-B1-016-I18", "U-B1-016-I19"]}, "source_refs": [{"anchor": "Reading lines92–96; production98–103; education/work139–145; travel147–152", "source_id": "CP07-B1-S02", "checked_on": "2026-10-20", "claim_scope": "B1 functional scope: main idea/details of familiar texts, routine institutional and travel communication, explanatory circumlocution. No approval of particular GreekOS item, time or mastery threshold."}], "active_recall": ["U-B1-016-I08", "U-B1-016-I09"], "prerequisites": ["B1-G13"], "reading_tasks": ["U-B1-016-I10", "U-B1-016-I11"], "transfer_task": "U-B1-016-I16", "writing_tasks": ["U-B1-016-I14"], "competency_ids": ["B1-V02"], "coverage_claim": "Partial macro evidence; not full competency verification", "speaking_tasks": ["U-B1-016-I15"], "errors_taxonomy": ["VOCAB_SELECTION", "COLLOCATION", "CONTENT_OMISSION", "COMPREHENSION", "PRAGMATICS_REGISTER", "ORTHOGRAPHY_ACCENT", "ASR_UNCERTAIN"], "guided_practice": ["U-B1-016-I02", "U-B1-016-I03", "U-B1-016-I04", "U-B1-016-I05", "U-B1-016-I06", "U-B1-016-I07"], "listening_tasks": ["U-B1-016-I12", "U-B1-016-I13"], "learning_outcome": "Самостоятельно использовать изученное для новой коммуникативной задачи, сохраняя смысл и ограничения ситуации.", "mastery_contract": {"observed": false, "recognition": "At least4/5 relevant checks and explanation of distractor", "retention_transfer": "New unaided D7 and D28 evidence; assistance recorded separately", "independent_production": "Complete task without copying model, all critical facts correct"}, "vocabulary_items": [{"lemma": "ο φορτιστής", "stress": "ο φορτιστής", "example": "Ξέχασα τον φορτιστή.", "inflection": "οι φορτιστές", "meaning_ru": "зарядное устройство", "collocations": ["φορτιστής κινητού"]}, {"lemma": "η συσκευή", "stress": "η συσκευή", "example": "Αυτή η συσκευή φορτίζει το κινητό.", "inflection": "οι συσκευές", "meaning_ru": "устройство", "collocations": ["ηλεκτρική συσκευή"]}, {"lemma": "η πρίζα", "stress": "η πρίζα", "example": "Η πρίζα είναι δίπλα.", "inflection": "οι πρίζες", "meaning_ru": "розетка", "collocations": ["συνδέω στην πρίζα"]}, {"lemma": "το ανοιχτήρι", "stress": "το ανοιχτήρι", "example": "Αυτό το ανοιχτήρι κάνει.", "inflection": "τα ανοιχτήρια", "meaning_ru": "открывалка", "collocations": ["ανοιχτήρι μπουκαλιών"]}, {"lemma": "το καπάκι", "stress": "το καπάκι", "example": "Το μπουκάλι έχει καπάκι.", "inflection": "τα καπάκια", "meaning_ru": "крышка", "collocations": ["μεταλλικό καπάκι"]}, {"lemma": "η απόφαση", "stress": "η απόφαση", "example": "Πήρα μια απόφαση.", "inflection": "οι αποφάσεις", "meaning_ru": "решение", "collocations": ["παίρνω απόφαση"]}], "remediation_policy": "До основного урока выполнить входную пробу без образца. При смысловой ошибке открыть указанный prerequisite unit, выполнить новую аналогичную пробу; подсказанную попытку не считать освоением.", "diagnostic_item_ids": ["U-B1-016-I01"], "learning_objectives": ["Распознавать функцию и устойчивое сочетание в контексте", "Восстанавливать изученные связки и строить различающее описание", "Самостоятельно уточнять неизвестное слово и проверять понимание в новом диалоге"], "microcompetency_ids": ["U-B1-016-MC01", "U-B1-016-MC02", "U-B1-016-MC03"], "primary_competencies": ["B1-V02"], "prerequisite_unit_ids": ["U-B1-014"], "estimated_active_minutes": 90, "self_explanation_item_id": "U-B1-016-I20"}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
