823	source_claim	CP08-INHERITED-U-A1-018-I11-01	8501a3a29cc03511c341a86100782f93294fdfc5e8508e0695309c0d21481478	\N	{"record": {"claim": "Functional scope only; no institutional endorsement of original tasks, thresholds, language forms or CEFR mediation descriptor.", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A1-018-I11-01", "item_ids": ["U-A1-018-I11"], "source_id": "CP06-A1-S01", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A1-018-I11.json", "sha256": "4a661637b4a6dc80a0f3aa509c79dcfcd9071ccccd65db9617a2206573dd2c05"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "Γενικός Εκπαιδευτικός Στόχος, L83–84; Κατανόηση γραπτού λόγου, L98–100; Παραγωγή προφορικού λόγου,L105", "source_id": "CP06-A1-S01", "checked_on": "2026-10-20", "claim_scope": "Functional scope only; no institutional endorsement of original tasks, thresholds, language forms or CEFR mediation descriptor.", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR_REINSPECTED"}}, "claim_id": "CP08-INHERITED-U-A1-018-I11-01", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3163	unit	U-B1-017	0417c6db39897ef8923959635c0b5f523108a585bb949f4b3376bc8683054475	core	{"unit_id": "U-B1-017", "content_hash": "0417c6db39897ef8923959635c0b5f523108a585bb949f4b3376bc8683054475", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-017.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "independent_linguistic_review": "NOT_REVIEWED"}, "rubrics": ["U-B1-017-RUBRIC"], "unit_id": "U-B1-017", "version": "0.1.0", "title_ru": "Читать статью и сообщение: факт, условие и неизвестное", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "В этом уроке вы читаете статью знакомой тематики и практическое сообщение, чтобы принять решение и объяснить его другому человеку. На B1 не требуется понимать каждое слово до начала чтения. Сначала определите, кто пишет, кому и зачем. Заголовок помогает предположить тему, но ответ ищите в тексте. Перед уроком прочитайте короткое объявление из U-A2-004 и найдите, к кому относится που в примере из U-B1-012. Если участники смешиваются, сначала восстановите цепочку «человек — действие — условие» на коротких предложениях.\\nПервое чтение отвечает на общий вопрос: о чём сообщение и какова его основная цель? Не выбирайте тему по одному знакомому слову. Если статья упоминает мобильный телефон, но объясняет изменение работы библиотеки, её тема не обязательно технологии. После первого чтения сформулируйте одну фразу без деталей. Затем перечитайте нужные места, чтобы проверить время, участника, действие и ограничение. Такой порядок помогает отличить основную мысль от примера.\\nПрактическое чтение требует различать факт, предложение и условие. Η αίθουσα θα ανοίξει τον Νοέμβριο сообщает план; προτείνεται να ανοίγει νωρίτερα — предложение; αν υπάρχουν αρκετοί εθελοντές вводит условие. Нельзя превращать условное действие в гарантированное. Отрицание часто меняет решение: δεν χρειάζεται εγγραφή означает отсутствие требования записи, а не запрет посещать. Сначала переведите смысл своими словами, потом найдите подтверждающую строку.\\nСледите за отсылками. В фразе «Οι εθελοντές που βοηθούν τους επισκέπτες εργάζονται το απόγευμα» относительное предложение описывает волонтёров. «Αυτή η αλλαγή» отсылает к уже названному изменению, но не обязательно к ближайшему существительному. Проверяйте, подходит ли предполагаемая отсылка по смыслу. Если текст не позволяет уверенно выбрать одного участника, отмечайте неоднозначность и задавайте вопрос; грамматически красивый ответ не заменяет доказательство.\\nНеизвестное слово сначала проверьте по окружению. Если μετά το κλείσιμο стоит рядом с часами работы, можно понять временную границу. Но контекстная догадка остаётся гипотезой. Не угадывайте документ, оплату или медицинскую инструкцию только по похожему слову. В учебных текстах можно подчеркнуть неизвестное и продолжить, если оно не меняет нужное решение. Если меняет — уточните значение в словаре или у адресата, а самостоятельную попытку отметьте отдельно от попытки с помощью.\\nДля ответа используйте три шага: краткое утверждение; точная опора в тексте; объяснение связи с вопросом. Например, при запросе о воскресенье недостаточно назвать любые часы. Нужно найти строку именно о воскресенье. «В тексте не сказано» является допустимым выводом, когда сведения отсутствуют: это не то же самое, что «событие запрещено» или «не существует». Не вводите реальные правила учреждения из собственного опыта, поскольку наши тексты вымышленные.\\nПосле чтения выполните перенос: объясните другу, какой вариант подходит его условиям, или напишите короткий запрос организатору. Не копируйте весь текст. Сохраните только сведения, необходимые адресату, и явно назовите неизвестное. В D7 и D28 будут другие сообщения, новые даты и изменённые ограничения. Ответ после повторного чтения — доказательство чтения; заученная цитата без понимания условия не подтверждает перенос. Аудиосценарий этой темы пока не озвучен: чтение транскрипта не даёт балла за понимание на слух.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "entry_probe": {"prompt": "Прочитайте «Οι επισκέπτες που έχουν κράτηση μπαίνουν πρώτοι». Кто входит первым и какое условие?", "expected": "Посетители с бронью; не все посетители.", "remediation_units": ["U-A2-004", "U-B1-012"]}, "examples_el": ["Η αλλαγή αφορά μικρές ομάδες.", "Δεν χρειάζεται εγγραφή.", "Η αίθουσα που χρησιμοποιούσαν οι υπάλληλοι ανοίγει για το κοινό.", "Μπορεί να προστεθούν ώρες, αν υπάρχουν εθελοντές.", "Δεν έχει ληφθεί απόφαση.", "Το κείμενο δεν αναφέρει την ώρα."], "review_plan": {"days": [7, 14, 28], "rule": "Fresh independent attempts before feedback; schedule from actual lesson date, not exam date", "item_ids": ["U-B1-017-I17", "U-B1-017-I18", "U-B1-017-I19"]}, "source_refs": [{"anchor": "Reading lines92–96; production98–103; education/work139–145; travel147–152", "source_id": "CP07-B1-S02", "checked_on": "2026-10-20", "claim_scope": "B1 functional scope: main idea/details of familiar texts, routine institutional and travel communication, explanatory circumlocution. No approval of particular GreekOS item, time or mastery threshold."}], "active_recall": ["U-B1-017-I08", "U-B1-017-I09"], "prerequisites": ["A2-R01", "B1-G08"], "reading_tasks": ["U-B1-017-I10", "U-B1-017-I11"], "transfer_task": "U-B1-017-I16", "writing_tasks": ["U-B1-017-I14"], "competency_ids": ["B1-R01"], "coverage_claim": "Partial macro evidence; not full competency verification", "speaking_tasks": ["U-B1-017-I15"], "errors_taxonomy": ["VOCAB_SELECTION", "COLLOCATION", "CONTENT_OMISSION", "COMPREHENSION", "PRAGMATICS_REGISTER", "ORTHOGRAPHY_ACCENT", "ASR_UNCERTAIN"], "guided_practice": ["U-B1-017-I02", "U-B1-017-I03", "U-B1-017-I04", "U-B1-017-I05", "U-B1-017-I06", "U-B1-017-I07"], "listening_tasks": ["U-B1-017-I12", "U-B1-017-I13"], "learning_outcome": "Самостоятельно использовать изученное для новой коммуникативной задачи, сохраняя смысл и ограничения ситуации.", "mastery_contract": {"observed": false, "recognition": "At least4/5 relevant checks and explanation of distractor", "retention_transfer": "New unaided D7 and D28 evidence; assistance recorded separately", "independent_production": "Complete task without copying model, all critical facts correct"}, "vocabulary_items": [{"lemma": "η αίθουσα", "stress": "η αίθουσα", "example": "Η αίθουσα είναι διαθέσιμη.", "inflection": "οι αίθουσες", "meaning_ru": "комната/зал", "collocations": ["αίθουσα μελέτης"]}, {"lemma": "η κράτηση", "stress": "η κράτηση", "example": "Χρειάζεται κράτηση.", "inflection": "οι κρατήσεις", "meaning_ru": "бронирование", "collocations": ["κάνω κράτηση"]}, {"lemma": "η προϋπόθεση", "stress": "η προϋπόθεση", "example": "Υπάρχει μία προϋπόθεση.", "inflection": "οι προϋποθέσεις", "meaning_ru": "условие", "collocations": ["με την προϋπόθεση"]}, {"lemma": "η συνεργασία", "stress": "η συνεργασία", "example": "Ο χώρος βοηθά τη συνεργασία.", "inflection": "οι συνεργασίες", "meaning_ru": "сотрудничество", "collocations": ["χώρος συνεργασίας"]}, {"lemma": "ο εθελοντής", "stress": "ο εθελοντής", "example": "Χρειαζόμαστε εθελοντές.", "inflection": "οι εθελοντές", "meaning_ru": "волонтёр", "collocations": ["ομάδα εθελοντών"]}, {"lemma": "η ανακοίνωση", "stress": "η ανακοίνωση", "example": "Διάβασα την ανακοίνωση.", "inflection": "οι ανακοινώσεις", "meaning_ru": "объявление", "collocations": ["διαβάζω την ανακοίνωση"]}], "remediation_policy": "До основного урока выполнить входную пробу без образца. При смысловой ошибке открыть указанный prerequisite unit, выполнить новую аналогичную пробу; подсказанную попытку не считать освоением.", "diagnostic_item_ids": ["U-B1-017-I01"], "learning_objectives": ["Различать основную мысль, условия и отсутствующие сведения", "Находить текстовую опору и правильно связывать участников", "Самостоятельно передавать практический вывод по новому сообщению"], "microcompetency_ids": ["U-B1-017-MC01", "U-B1-017-MC02", "U-B1-017-MC03"], "primary_competencies": ["B1-R01"], "prerequisite_unit_ids": ["U-A2-004", "U-B1-012"], "estimated_active_minutes": 90, "self_explanation_item_id": "U-B1-017-I20"}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3164	unit	U-B1-018	01e8163b9e718bfedd0225b576dd731d40a09f817d498c052706de320d26ddd1	core	{"unit_id": "U-B1-018", "content_hash": "01e8163b9e718bfedd0225b576dd731d40a09f817d498c052706de320d26ddd1", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-018.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "COMPLETE_NOT_INDEPENDENT", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-B1-018-RUBRIC"], "unit_id": "U-B1-018", "version": "0.1.0", "title_ru": "Главная мысль и существенные детали развёрнутого сообщения", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "В B1 нужно удержать главную мысль относительно простого сообщения и существенные детали, а не только отдельное число. Начните с вопроса: зачем говорят? Объявление может сообщать изменение расписания, приглашать записаться или объяснять ограничение. Главная мысль объединяет несколько предложений. Упоминание компьютеров само по себе не означает, что речь об их продаже или ремонте.\\nПеред уроком повторите A2-L01 и лексику B1-V01. Для основного текста заранее объясняются εργαστήριο, συμμετοχή, γραμματεία; время, причина и правило записи заранее не раскрываются. Первое прослушивание — выбрать заголовок, второе — заполнить короткую заметку: изменение / причина / условия / исключение. При третьем прослушивании для обучения ищем конкретное непонятое место; это уже assisted evidence, а не независимая первая попытка.\\nОтделяйте изменение от того, что остаётся прежним. «Και κάθε Τετάρτη» добавляет день, а не обязательно заменяет понедельник. «Το πρωινό πρόγραμμα δεν αλλάζει» явно сохраняет старое расписание. Слова δεν χρειάζεται и χρειάζεται в соседних предложениях требуют особого внимания: собственный компьютер не нужен, регистрация нужна. Смысл отрицания не переносится на следующее предложение.\\nСущественная деталь зависит от цели слушателя. Работающему утром человеку важно вечернее время; тому, у кого нет компьютера, — наличие устройств; всем участникам — срок записи. Краткий пересказ может не включать весь текст, но не должен исказить эти условия. Если мест нет, обещан контакт по поводу другой даты, а не гарантированное участие в среду. Извлечение фактов и выводы отмечайте отдельно.\\nНе используйте знания о реальных курсах для заполнения пропусков. В этой учебной ситуации нет требования приносить паспорт или платить залог; такие детали нельзя добавлять. На открытом задании допустимы греческие парафразы и заметки, если сохранены проверяемые факты. При непонятной записи попросите уточнить нужное условие, а не переписывайте весь рассказ из памяти.\\nВ самостоятельном переносе меняется сфера: сообщение о библиотеке или спортивной встрече. Структура «главная цель — существенные условия — следующий шаг» остаётся полезной. На D7/D28 требуется новый стимул. Письменный разбор сценария — подготовка; реальная аудио-оценка возможна только после записи, прослушивания и скрытия транскрипта.", "cefr_level": "B1", "time_basis": "AUTHOR_PLANNING_ESTIMATE_NOT_PILOTED", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Το πρωινό πρόγραμμα δεν αλλάζει.", "Δεν χρειάζεται δικός σας υπολογιστής.", "Χρειάζεται να δηλώσετε συμμετοχή.", "Η αλλαγή γίνεται επειδή πολλοί εργάζονται το πρωί.", "Αν οι θέσεις γεμίσουν, θα επικοινωνήσουμε μαζί σας."], "review_plan": {"days": [7, 28], "rule": "New stimulus, no model shown before attempt; assistance recorded; corrected answer alone is not independent retention", "item_ids": ["U-B1-018-I11", "U-B1-018-I12"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Κατανόηση/Παραγωγή προφορικού λόγου, lines86–102", "source_id": "CP08-B1", "checked_on": "2026-10-21", "claim_scope": "Bounded descriptor or phonological principle only; original examples, lesson sequence, rubrics and thresholds are not official"}], "active_recall": ["U-B1-018-I07"], "prerequisites": ["A2-L01", "B1-V01"], "reading_tasks": ["U-B1-018-I08"], "transfer_task": "U-B1-018-I10", "writing_tasks": ["U-B1-018-I07"], "assessment_map": [{"kind": "mcq", "item_id": "U-B1-018-I01", "objective": "Понять главную цель", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-B1-018-I02", "objective": "Понять главную цель", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_short", "item_id": "U-B1-018-I03", "objective": "Понять главную цель", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-B1-018-I04", "objective": "Понять главную цель", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-B1-018-I05", "objective": "Отделить существенные условия и исключения", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-B1-018-I06", "objective": "Отделить существенные условия и исключения", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "open", "item_id": "U-B1-018-I07", "objective": "Отделить существенные условия и исключения", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "read_mcq", "item_id": "U-B1-018-I08", "objective": "Отделить существенные условия и исключения", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "speak", "item_id": "U-B1-018-I09", "objective": "Передать применимую информацию без домыслов", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-B1-018-I10", "objective": "Передать применимую информацию без домыслов", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-B1-018-I11", "objective": "Передать применимую информацию без домыслов", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-B1-018-I12", "objective": "Передать применимую информацию без домыслов", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}], "competency_ids": ["B1-L01"], "coverage_claim": "TEXT_ROUTE_AUTHORED_AUDIO_AND_INDEPENDENT_QA_BLOCKED", "speaking_tasks": ["U-B1-018-I09"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION", "FACT_SUBSTITUTION", "ASR_UNCERTAIN", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-B1-018-I02", "U-B1-018-I03", "U-B1-018-I04", "U-B1-018-I05", "U-B1-018-I06", "U-B1-018-I08"], "listening_tasks": ["U-B1-018-I02", "U-B1-018-I03", "U-B1-018-I04", "U-B1-018-I05", "U-B1-018-I06", "U-B1-018-I10", "U-B1-018-I11", "U-B1-018-I12"], "mastery_contract": {"open": "Every task-specific content criterion met independently, intelligible response; quote evidence per criterion", "closed": "At least80% on fresh controlled tasks, no uncorrected critical fact errors; project heuristic only", "listening": "Requires verified media, transcript hidden, play count logged", "retention": "Independent D7 and D28; one hint makes assisted evidence", "pronunciation": "Requires actual recording and listening; ASR text alone insufficient"}, "reading_texts_el": ["Καλησπέρα σε όλους. Από την επόμενη εβδομάδα το εργαστήριο υπολογιστών θα λειτουργεί και κάθε Τετάρτη από τις πέντε μέχρι τις επτά το απόγευμα. Η αλλαγή γίνεται επειδή αρκετοί κάτοικοι εργάζονται το πρωί και δεν μπορούσαν να έρθουν. Το πρωινό πρόγραμμα της Δευτέρας δεν αλλάζει. Την Τετάρτη μπορείτε να εξασκηθείτε στην αποστολή μηνυμάτων και στη χρήση απλών ηλεκτρονικών φορμών. Δεν πρόκειται για μάθημα επισκευής υπολογιστών. Δεν χρειάζεται να φέρετε δικό σας υπολογιστή, γιατί υπάρχουν συσκευές στην αίθουσα. Χρειάζεται όμως να δηλώσετε συμμετοχή μέχρι τη Δευτέρα, ώστε να ξέρουμε πόσες θέσεις θα ετοιμάσουμε. Αν οι θέσεις γεμίσουν, θα επικοινωνήσουμε μαζί σας για μια άλλη ημέρα. Η συμμετοχή είναι δωρεάν. Για περισσότερες πληροφορίες ρωτήστε στη γραμματεία."], "vocabulary_items": [{"lemma": "το εργαστήριο", "stress": "το εργαστήριο", "example": "Το εργαστήριο λειτουργεί την Τετάρτη.", "inflection": "τα εργαστήρια", "meaning_ru": "мастерская, практическое занятие", "collocations": ["Το εργαστήριο λειτουργεί την Τετάρτη."]}, {"lemma": "η συμμετοχή", "stress": "η συμμετοχή", "example": "Δηλώστε συμμετοχή μέχρι τη Δευτέρα.", "inflection": "τη συμμετοχή", "meaning_ru": "участие", "collocations": ["Δηλώστε συμμετοχή μέχρι τη Δευτέρα."]}, {"lemma": "η γραμματεία", "stress": "η γραμματεία", "example": "Ρωτήστε στη γραμματεία.", "inflection": "τη γραμματεία", "meaning_ru": "секретариат", "collocations": ["Ρωτήστε στη γραμματεία."]}], "diagnostic_item_ids": ["U-B1-018-I01"], "learning_objectives": ["Понять главную цель", "Отделить существенные условия и исключения", "Передать применимую информацию без домыслов"], "prerequisite_support": {"A2-L01": "Use primary unit from CONTENT_Production_Register_96.csv; if entry task fails, reteach prerequisite and retry on a fresh example before target assessment", "B1-V01": "Use primary unit from CONTENT_Production_Register_96.csv; if entry task fails, reteach prerequisite and retry on a fresh example before target assessment"}, "primary_competencies": ["B1-L01"], "estimated_active_minutes": 70}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
