3165	unit	U-B1-019	d09cf699bcc627d07dcaf56d7466b2b87f4123db2699068ae7166364986724ab	core	{"unit_id": "U-B1-019", "content_hash": "d09cf699bcc627d07dcaf56d7466b2b87f4123db2699068ae7166364986724ab", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-019.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "COMPLETE_NOT_INDEPENDENT", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-B1-019-RUBRIC"], "unit_id": "U-B1-019", "version": "0.1.0", "title_ru": "Рассказ и интервью: последовательность, намерение, изменение мнения", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "В рассказе отделяйте порядок событий от порядка упоминания. Слова στην αρχή, μια μέρα, μετά, τώρα помогают построить линию времени. Рассказчик может назвать прежнее предположение, затем его исправить: Νόμιζα ότι…, αλλά… . Нельзя выдавать первую мысль за реальное условие. Перед уроком повторите A2-L02 и контраст длительного фона/события B1-G03; в задачах оцениваем понимание, а не выбор времени вне контекста.\\nВ интервью вопрос подсказывает функцию ответа. Πώς ξεκίνησες; запрашивает начало истории; Ήταν εύκολη η πρώτη μέρα; — оценку опыта; Θα το πρότεινες; — рекомендацию. Важно различать факт, чувство и совет. «Φοβόμουν μήπως δώσω λάθος πληροφορία» означает опасение, а не признание реально совершённой ошибки. Если ошибки не описаны, не добавляйте их.\\nСоставьте три ряда заметок: что произошло; что человек думал или чувствовал; что он советует. В основном интервью прежняя мысль о ежедневной работе исправляется условием «два часа в неделю». Помощь другого волонтёра предшествует большей уверенности. Совету «сначала узнать обязанности» не следует приписывать значение «не приходить без полной подготовки».\\nСлушайте ограничения рекомендации: αρκεί να… вводит условие в данном контексте. Для B1 достаточно понять практический смысл, не строя все возможные условные конструкции. Различайте «не нужно знать всё» и «можно ничего не делать». Человек рекомендует начать с вопросов и предупреждать об отсутствии, а не игнорировать обязанности.\\nПересказ строится своими словами: исходная ситуация → событие → изменение → вывод. Повторять все вопросы журналиста не нужно. Не заменяйте автора собой: когда говорите об Άννα, используйте третье лицо либо явно сообщите, что цитируете. Русские заметки допустимы на рецептивном этапе; самостоятельная речевая продукция выполняется по-гречески.\\nПосле первого прослушивания сформулируйте тему, после второго проверьте последовательность и намерение. Уберите транскрипт при отсроченной проверке. Если вы уверены только в части рассказа, назовите известное и попросите уточнить остальное. Внешняя калибровка темпа и трудности остаётся открытой: авторский B1-текст не является официальным экзаменационным образцом.", "cefr_level": "B1", "time_basis": "AUTHOR_PLANNING_ESTIMATE_NOT_PILOTED", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Στην αρχή πήγαινα μόνο για να δανειστώ βιβλία.", "Νόμιζα ότι έπρεπε να έρχομαι κάθε μέρα.", "Μετά ένιωθα πιο άνετα.", "Φοβόμουν μήπως δώσω λάθος πληροφορία.", "Ρώτησε πρώτα τι ακριβώς χρειάζεται."], "review_plan": {"days": [7, 28], "rule": "New stimulus, no model shown before attempt; assistance recorded; corrected answer alone is not independent retention", "item_ids": ["U-B1-019-I11", "U-B1-019-I12"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Κατανόηση/Παραγωγή προφορικού λόγου, lines86–102", "source_id": "CP08-B1", "checked_on": "2026-10-21", "claim_scope": "Bounded descriptor or phonological principle only; original examples, lesson sequence, rubrics and thresholds are not official"}], "active_recall": ["U-B1-019-I07"], "prerequisites": ["A2-L02", "B1-G03"], "reading_tasks": ["U-B1-019-I08"], "transfer_task": "U-B1-019-I10", "writing_tasks": ["U-B1-019-I07"], "assessment_map": [{"kind": "mcq", "item_id": "U-B1-019-I01", "objective": "Построить последовательность", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-B1-019-I02", "objective": "Построить последовательность", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-B1-019-I03", "objective": "Построить последовательность", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-B1-019-I04", "objective": "Построить последовательность", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_short", "item_id": "U-B1-019-I05", "objective": "Различить факт, чувство и предположение", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-B1-019-I06", "objective": "Различить факт, чувство и предположение", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "open", "item_id": "U-B1-019-I07", "objective": "Различить факт, чувство и предположение", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "read_mcq", "item_id": "U-B1-019-I08", "objective": "Различить факт, чувство и предположение", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "speak", "item_id": "U-B1-019-I09", "objective": "Распознать и передать рекомендацию", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-B1-019-I10", "objective": "Распознать и передать рекомендацию", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-B1-019-I11", "objective": "Распознать и передать рекомендацию", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-B1-019-I12", "objective": "Распознать и передать рекомендацию", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}], "competency_ids": ["B1-L02"], "coverage_claim": "TEXT_ROUTE_AUTHORED_AUDIO_AND_INDEPENDENT_QA_BLOCKED", "speaking_tasks": ["U-B1-019-I09"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION", "FACT_SUBSTITUTION", "ASR_UNCERTAIN", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-B1-019-I02", "U-B1-019-I03", "U-B1-019-I04", "U-B1-019-I05", "U-B1-019-I06", "U-B1-019-I08"], "listening_tasks": ["U-B1-019-I02", "U-B1-019-I03", "U-B1-019-I04", "U-B1-019-I05", "U-B1-019-I06", "U-B1-019-I10", "U-B1-019-I11", "U-B1-019-I12"], "mastery_contract": {"open": "Every task-specific content criterion met independently, intelligible response; quote evidence per criterion", "closed": "At least80% on fresh controlled tasks, no uncorrected critical fact errors; project heuristic only", "listening": "Requires verified media, transcript hidden, play count logged", "retention": "Independent D7 and D28; one hint makes assisted evidence", "pronunciation": "Requires actual recording and listening; ASR text alone insufficient"}, "reading_texts_el": ["Δημοσιογράφος: Πώς ξεκίνησες να βοηθάς στη βιβλιοθήκη; Άννα: Στην αρχή πήγαινα μόνο για να δανειστώ βιβλία. Μια μέρα είδα μια ανακοίνωση για εθελοντές και μίλησα με την υπεύθυνη. Νόμιζα ότι θα χρειαζόταν να έρχομαι κάθε μέρα, αλλά μου εξήγησε ότι δύο ώρες την εβδομάδα ήταν αρκετές. Δημοσιογράφος: Ήταν εύκολη η πρώτη μέρα; Άννα: Όχι ακριβώς. Δεν ήξερα πού βρίσκονταν όλα τα βιβλία και φοβόμουν μήπως δώσω λάθος πληροφορία. Ένας άλλος εθελοντής μου έδειξε τον κατάλογο. Μετά από λίγες συναντήσεις ένιωθα πιο άνετα. Τώρα βοηθάω τους επισκέπτες να βρουν αυτό που ψάχνουν. Δημοσιογράφος: Θα το πρότεινες σε κάποιον άλλο; Άννα: Ναι, αρκεί να ρωτήσει πρώτα τι ακριβώς χρειάζεται. Δεν χρειάζεται να ξέρει τα πάντα από την πρώτη μέρα. Είναι όμως σημαντικό να ενημερώνει εγκαίρως αν δεν μπορεί να έρθει."], "vocabulary_items": [{"lemma": "ο εθελοντής", "stress": "ο εθελοντής", "example": "Ένας εθελοντής με βοήθησε.", "inflection": "οι εθελοντές / η εθελόντρια", "meaning_ru": "волонтёр", "collocations": ["Ένας εθελοντής με βοήθησε."]}, {"lemma": "δανείζομαι", "stress": "δανείζομαι", "example": "Δανείστηκα ένα βιβλίο.", "inflection": "δανείστηκα", "meaning_ru": "брать взаймы", "collocations": ["Δανείστηκα ένα βιβλίο."]}, {"lemma": "εγκαίρως", "stress": "εγκαίρως", "example": "Ενημέρωσε εγκαίρως.", "inflection": "наречие", "meaning_ru": "вовремя", "collocations": ["Ενημέρωσε εγκαίρως."]}], "diagnostic_item_ids": ["U-B1-019-I01"], "learning_objectives": ["Построить последовательность", "Различить факт, чувство и предположение", "Распознать и передать рекомендацию"], "prerequisite_support": {"A2-L02": "Use primary unit from CONTENT_Production_Register_96.csv; if entry task fails, reteach prerequisite and retry on a fresh example before target assessment", "B1-G03": "Use primary unit from CONTENT_Production_Register_96.csv; if entry task fails, reteach prerequisite and retry on a fresh example before target assessment"}, "primary_competencies": ["B1-L02"], "estimated_active_minutes": 70}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3166	unit	U-B1-020	0b6b1ebb5e0e6df02ae46ac9ba723c24027c57cf47d68e478a6bc5bf30dde9c5	core	{"unit_id": "U-B1-020", "content_hash": "0b6b1ebb5e0e6df02ae46ac9ba723c24027c57cf47d68e478a6bc5bf30dde9c5", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-020.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "COMPLETE_NOT_INDEPENDENT", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-B1-020-RUBRIC"], "unit_id": "U-B1-020", "version": "0.1.0", "title_ru": "Связный рассказ, мнение и краткое обоснование", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Связный ответ — это несколько связанных мыслей, которые адресат может проследить без догадок. В рассказе используйте рамку: где и когда → событие → трудность → действие → результат. Во мнении: позиция → причина → пример → краткий вывод. Это опоры, а не обязательные одинаковые фразы. Не заполняйте ответ длинным вступлением, если вопрос просит назвать причину.\\nПредпосылки — A2-SP01 и средства связи B1-G10. Перед началом расскажите о простой вымышленной ситуации тремя предложениями. Если связь теряется, сначала составьте три ключевых слова, затем повторите без полного текста. Подсказка учитывается отдельно; чтение подготовленного ответа не доказывает спонтанное владение.\\nВ рассказе фон и отдельные события выполняют разные функции: «Περίμενα στη στάση όταν άρχισε να βρέχει». Фон ожидания и событие дождя связаны по времени. В этом уроке повторяем знакомые формы, а не вводим новую парадигму. После «έχασα το λεωφορείο» не утверждайте, что успели на него, если не объяснили другое событие. Сначала проверяйте внутреннюю логику фактов, затем грамматику.\\nОбоснование должно поддерживать конкретную позицию. «Προτιμώ το πρωινό μάθημα επειδή το απόγευμα εργάζομαι» объясняет выбор утреннего занятия. «Μου αρέσει πολύ» выражает оценку, но не раскрывает причину. Добавьте пример, который действительно иллюстрирует её. Μπορεί и ίσως полезны, когда вы не уверены; не превращайте личный опыт в доказательство того, что способ подходит всем.\\nНе связывайте каждую фразу словом και. Для порядка пригодны πρώτα, μετά, στο τέλος; для причины επειδή; для результата γι' αυτό; для простого противопоставления αλλά. Выбор оценивается по смыслу. Если связь понятна без специального маркера, не штрафуйте за отсутствие «красивого» союза. В речи допустимы паузы поиска, самокоррекция и просьба повторить вопрос.\\nПосле короткого рассказа партнёр задаёт новый вопрос. Не возвращайтесь автоматически к заученному началу; ответьте на нужную часть. Рубрика отдельно оценивает содержание, связность, языковую понятность и самостоятельность. Произношение можно оценить только по записи. D7/D28 требуют нового содержания: другая трудность или другой выбор, а не перестановка имён в старом монологе.", "cefr_level": "B1", "time_basis": "AUTHOR_PLANNING_ESTIMATE_NOT_PILOTED", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Περίμενα στη στάση όταν άρχισε να βρέχει.", "Πρώτα τηλεφώνησα και μετά έστειλα μήνυμα.", "Προτιμώ το πρωινό μάθημα επειδή εργάζομαι το απόγευμα.", "Ήταν δύσκολο, αλλά βρήκα μια λύση.", "Δεν είμαι σίγουρος· χρειάζομαι περισσότερες πληροφορίες."], "review_plan": {"days": [7, 28], "rule": "New stimulus, no model shown before attempt; assistance recorded; corrected answer alone is not independent retention", "item_ids": ["U-B1-020-I10", "U-B1-020-I11"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Κατανόηση/Παραγωγή προφορικού λόγου, lines86–102", "source_id": "CP08-B1", "checked_on": "2026-10-21", "claim_scope": "Bounded descriptor or phonological principle only; original examples, lesson sequence, rubrics and thresholds are not official"}], "active_recall": ["U-B1-020-I05"], "prerequisites": ["A2-SP01", "B1-G10"], "reading_tasks": ["U-B1-020-I04"], "transfer_task": "U-B1-020-I09", "writing_tasks": ["U-B1-020-I01", "U-B1-020-I03", "U-B1-020-I05", "U-B1-020-I08", "U-B1-020-I10"], "assessment_map": [{"kind": "open", "item_id": "U-B1-020-I01", "objective": "Построить связный рассказ", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "mcq", "item_id": "U-B1-020-I02", "objective": "Построить связный рассказ", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "open", "item_id": "U-B1-020-I03", "objective": "Построить связный рассказ", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "read_mcq", "item_id": "U-B1-020-I04", "objective": "Построить связный рассказ", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "open", "item_id": "U-B1-020-I05", "objective": "Поддержать мнение причиной и примером", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "speak", "item_id": "U-B1-020-I06", "objective": "Поддержать мнение причиной и примером", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "speak", "item_id": "U-B1-020-I07", "objective": "Поддержать мнение причиной и примером", "audio_required": true, "mastery_evidence": "Ind