869	source_claim	CP08-INHERITED-U-A2-002-I02-01	e9cf5834c529a4e20aa06428cf78658cf33ccdb2a6aa2095696dabe545d61ef0	\N	{"record": {"claim": "Уровневая тема; не дословный источник авторских фраз", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A2-002-I02-01", "item_ids": ["U-A2-002-I02"], "source_id": "V201", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A2-002-I02.json", "sha256": "0f3ec49445f8726be652be12257c50d6f4ff65bb429ae3968c1251589352d752"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "V201 PDF7–8", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}}, "claim_id": "CP08-INHERITED-U-A2-002-I02-01", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3167	unit	U-B1-021	b3a5fa8cec0554af51bf259f5152287e8732a474ec61804a2de9f4c95773b1c4	core	{"unit_id": "U-B1-021", "content_hash": "b3a5fa8cec0554af51bf259f5152287e8732a474ec61804a2de9f4c95773b1c4", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-021.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY"}, "rubrics": ["U-B1-021-RUBRIC"], "unit_id": "U-B1-021", "version": "0.1.0", "title_ru": "Фразовое ударение, ритм, связная речь и разборчивость", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Ударение слова и выделение смысла во фразе решают разные задачи. В слове εισιτήριο ударение принадлежит определённому слогу; в высказывании можно дополнительно выделить слово, которое исправляет ожидание собеседника. «Η Άννα θα φέρει τα εισιτήρια αύριο» отвечает на разные вопросы в зависимости от смыслового центра: кто, что или когда. Выделение не требует крика и не переносит словесное ударение на неправильный слог. На письме прописные буквы могут быть редакторской подсказкой, но в ученическом тесте они заранее раскрыли бы ответ.\\nСначала определите коммуникативную задачу. Если собеседник думает, что билеты принесёт Петрос, подчеркните Анну; если ошибается в дне — αύριο. Контекст и интонация работают вместе. По одному письменному предложению нельзя надёжно восстановить реальный контур, а по сомнительной ASR-транскрипции нельзя оценить фразовое ударение. Поэтому наши рецептивные задания заблокированы до записи и прослушивания двух контрастных вариантов с одинаковыми словами.\\nПаузы помогают отделять смысловые группы: «Αν βρέξει, / θα συναντηθούμε μέσα». Граница отделяет условие от основного сообщения. Не делайте обязательную паузу после каждого слова и не отрывайте короткий артикль от существительного ради чтения по слогам. Разметка косой чертой — один возможный тренировочный вариант, а не единственно допустимое произношение. Критерий — слушатель понимает связи и условия без повторного угадывания.\\nВ связной речи звуки соседних слов могут взаимодействовать. Не ожидайте, что каждое слово звучит так же изолированно, как в словаре; одновременно не учите произвольное проглатывание звуков как признак естественности. На этом этапе цель — понятность, устойчивое словесное ударение и осмысленные группы. Точная имитация регионального акцента не требуется. Скорость не равна беглости: слишком быстрый ответ с потерянными условиями хуже более спокойного, но связного объяснения.\\nПрактика: прослушайте целую фразу, назовите смысловой центр, повторите её, затем произнесите новое сообщение без образца. Запишите ответ и попросите слушателя назвать, что именно вы исправляли. Если его интерпретация другая, измените контекст или выделение и повторите. Самопроверка записи полезна, но не заменяет независимого слушателя. Перед уроком нужны A2-P01 и B1-SP01. D7 проверяет новую коррекцию, D28 — связное сообщение с условием и самопоправкой. Пока записи отсутствуют, урок является редакторским сценарием, а не закрытой акустической компетенцией.", "cefr_level": "B1", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Η Άννα θα φέρει τα εισιτήρια αύριο.", "Αν βρέξει, θα συναντηθούμε μέσα.", "Είπα την Πέμπτη, όχι την Τρίτη.", "Θα έρθουμε στις επτά, δηλαδή μία ώρα αργότερα."], "review_plan": {"D7": ["U-B1-021-I10"], "D28": ["U-B1-021-I11"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-B1-021-I10", "U-B1-021-I11"]}, "source_refs": [{"anchor": "§2.3 suprasegmentals, stress, pause and rhythm; §2.2 connected speech", "source_id": "CP08-PHON", "checked_on": "2026-10-22", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "active_recall": ["U-B1-021-I08"], "prerequisites": ["A2-P01", "B1-SP01"], "reading_tasks": [], "transfer_task": "U-B1-021-I09", "writing_tasks": ["U-B1-021-I05"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B1-021-I01", "U-B1-021-I02"], "objective": "Различать словесное ударение и смысловой центр"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B1-021-I03", "U-B1-021-I04", "U-B1-021-I06", "U-B1-021-I08", "U-B1-021-I10"], "objective": "Распознавать и воспроизводить контраст в реальном звуке"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B1-021-I05", "U-B1-021-I07", "U-B1-021-I09", "U-B1-021-I11"], "objective": "Группировать связную речь и самостоятельно исправлять сообщение"}], "competency_ids": ["B1-P01"], "speaking_tasks": ["U-B1-021-I01", "U-B1-021-I06", "U-B1-021-I07", "U-B1-021-I08", "U-B1-021-I09", "U-B1-021-I10", "U-B1-021-I11"], "entry_probe_ids": ["U-B1-021-I01"], "errors_taxonomy": ["COMPREHENSION", "PRONUNCIATION_CANDIDATE"], "guided_practice": ["U-B1-021-I02", "U-B1-021-I03", "U-B1-021-I04", "U-B1-021-I05", "U-B1-021-I06", "U-B1-021-I07"], "listening_tasks": ["U-B1-021-I03", "U-B1-021-I04"], "modality_status": "AUDIO_PENDING", "vocabulary_items": [{"lemma": "η έμφαση", "stress": "η έμφαση", "example": "Δίνω έμφαση στην ώρα.", "inflection": "της έμφασης", "collocations": ["δίνω έμφαση"]}, {"lemma": "η παύση", "stress": "η παύση", "example": "Μια σύντομη παύση βοηθά.", "inflection": "της παύσης; οι παύσεις", "collocations": ["σύντομη παύση"]}, {"lemma": "ο ρυθμός", "stress": "ο ρυθμός", "example": "Μίλησε με φυσικό ρυθμό.", "inflection": "του ρυθμού", "collocations": ["φυσικός ρυθμός"]}], "learning_objectives": ["Различать словесное ударение и смысловой центр", "Распознавать и воспроизводить контраст в реальном звуке", "Группировать связную речь и самостоятельно исправлять сообщение"], "prerequisite_policy": "Diagnose before instruction; failure routes to primary unit(s) from96 register. Authored prerequisite is not evidence of learner mastery. Retry with fresh example.", "primary_competencies": ["B1-P01"], "estimated_active_minutes": 65}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3168	unit	U-B1-022	d821b1d715ca8d0a5256d36b057577123e7bcfa5d218b1252af38542e706bd91	core	{"unit_id": "U-B1-022", "content_hash": "d821b1d715ca8d0a5256d36b057577123e7bcfa5d218b1252af38542e706bd91", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-022.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY"}, "rubrics": ["U-B1-022-RUBRIC"], "unit_id": "U-B1-022", "version": "0.1.0", "title_ru": "Неподготовленный разговор и решение неожиданности", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Неподготовленный разговор не требует мгновенно знать все слова. Нужно удержать цель, объяснить препятствие, запросить помощь и проверить решение. В ситуации с бронью сначала сообщите, что ожидали: «Έχω κράτηση για δύο άτομα». Затем назовите проблему, не обвиняя собеседника: «Δεν βρίσκω το μήνυμα επιβεβαίωσης». После этого задайте конкретный вопрос. Длинная история без запроса затрудняет помощь.\\nКогда ситуация меняется, не продолжайте заученный монолог. Ответ «Δεν υπάρχει τραπέζι στις επτά» требует выбора: спросить другое время, другой день или отказаться. «Τότε υπάρχει κάτι στις οκτώ;» связывает реплику с новой информацией. Если названное время вам не подходит, объясните ограничение: «Πρέπει να φύγω πριν από τις εννέα». Это позволяет обсуждать действительно возможные варианты.\\nПроверка понимания отличается от повторения любого слова. «Δηλαδή η κράτηση είναι για αύριο, όχι για σήμερα;» показывает конкретную гипотезу. «Μπορείτε να το πείτε λίγο πιο απλά;» помогает, когда непонятна формулировка. Если не знаете слово, опишите функцию: «το μήνυμα που δείχνει ότι η κράτηση έγινε». Перефразировка — полноценная стратегия; переход на русский может быть полезной аварийной опорой, но не доказывает самостоятельное выполнение по-гречески.\\nНе соглашайтесь с неизвестной суммой или неподтверждённым условием. «Πριν συμφωνήσω, θα ήθελα να ξέρω…» даёт время уточнить. В учебных заданиях все правила вымышлены; они не являются юридической консультацией о возвратах или правах покупателя. Участник должен опираться на конкретные условия карточки, а не придумывать обязанность сотрудника.\\nЗавершите разговор кратким подтверждением: время, место, действие и кто его выполняет. «Λοιπόν, θα έρθουμε αύριο στις οκτώ και θα σας στείλω το όνομα τώρα». Если решения нет, корректное завершение тоже успешно: «Ευχαριστώ, θα το σκεφτώ και θα σας καλέσω». Не оценивайте успех только по получению желаемой услуги.\\nПредпосылки — A2-SI01 и B1-V02. Диагностика проверяет объяснение цели и ограничений. Ролевая задача должна выдавать следующую реплику только после ответа ученика; просмотр всех веток заранее снижает спонтанность. Грамматика и уместность оцениваются вместе с реакцией на новое препятствие. Для настоящего диалога нужны живой партнёр или работающий voice-движок; текущие карточки готовы к редакторской проверке, а runtime не протестирован.", "cefr_level": "B1", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Έχω κράτηση, αλλά δεν βρίσκω την επιβεβαίωση.", "Μήπως υπάρχει άλλη ώρα;", "Δηλαδή πρέπει να έρθω αύριο;", "Ευχαριστώ, θα σας καλέσω αργότερα."], "review_plan": {"D7": ["U-B1-022-I11"], "D28": ["U-B1-022-I12"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-B1-022-I11", "U-B1-022-I12"]}, "source_refs": [{"anchor": "Oral production101–103, handling communication problems", "source_id": "CP08-B1", "checked_on": "2026-10-22", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "active_recall": ["U-B1-022-I07", "U-B1-022-I08"], "prerequisites": ["A2-SI01", "B1-V02"], "reading_tasks": ["U-B1-022-I02"], "transfer_task": "U-B1-022-I09", "writing_tasks": ["U-B1-022-I10"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B1-022-I01", "U-B1-022-I02", "U-B1-022-I03", "U-B1-022-I05", "U-B1-022-I06"], "objective": "Объяснять проблему и уточнять неизвестное"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B1-022-I04", "U-B1-022-I07", "U-B1-022-I08", "U-B1-022-I11"], "objective": "Реагировать на новое ограничение и выбирать решение"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B1-022-I09", "U-B1-022-I10", "U-B1-022-I12"], "objective": "Самостоятельно вести и завершать короткие переговоры"}], "competency_ids": ["B1-SI01"], "speaking_tasks": ["U-B1-022-I01", "U-B1-022-I03", "U-B1-022-I06", "U-B1-022-I07", "U-B1-022-I08", "U-B1-022-I09", "U-B1-022-I11", "U-B1-022-I12"], "entry_probe_ids": ["U-B1-022-I01"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION"], "guided_practice": ["U-B1-022-I02", "U-B1-022-I03", "U-B1-022-I04", "U-B1-022-I05", "U-B1-022-I06", "U-B1-022-I10"], "listening_tasks": [], "modality_status": "AUDIO_PENDING", "vocabulary_items": [{"lemma": "η κράτηση", "stress": "η κράτηση", "example": "Έχω κράτηση για δύο άτομα.", "inflection": "της κράτησης; οι κρατήσεις", "collocations": ["κάνω κράτηση"]}, {"lemma": "η επιβεβαίωση", "stress": "η επιβεβαίωση", "example": "Δεν έλαβα επιβεβαίωση.", "inflection": "της επιβεβαίωσης", "collocations": ["μήνυμα επιβεβαίωσης"]}, {"lemma": "διευκρινίζω", "stress": "διευκρινίζω", "example": "Θα ήθελα να διευκρινίσω την ώρα.", "inflection": "διευκρίνισα", "collocations": ["διευκρινίζω την ώρα"]}], "learning_objectives": ["Объяснять проблему и уточнять неизвестное", "Реагировать на новое ограничение и выбирать решение", "Самостоятельно вести и завершать короткие переговоры"], "prerequisite_policy": "Diagnose before instruction; failure routes to primary unit(s) from96 register. Authored prerequisite is not evidence of learner mastery. Retry with fresh example.", "primary_competencies": ["B1-SI01"], "estimated_active_minutes": 65}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
