875	source_claim	CP08-INHERITED-U-A2-002-I05-01	131314dc3757b908ed3d93cae4463bee6279640f80fcc883047169a745b55ca9	\N	{"record": {"claim": "Уровневая тема; не дословный источник авторских фраз", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A2-002-I05-01", "item_ids": ["U-A2-002-I05"], "source_id": "V201", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A2-002-I05.json", "sha256": "b63397ea6f086e361b2e390f9582ce24113a736831ef3d116b08923b8e2d1994"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "V201 PDF7–8", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}}, "claim_id": "CP08-INHERITED-U-A2-002-I05-01", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3169	unit	U-B1-023	c8949ec5122ac8f165ae36d3400825b2ba0409a7944a10c6abed3e162a589595	core	{"unit_id": "U-B1-023", "content_hash": "c8949ec5122ac8f165ae36d3400825b2ba0409a7944a10c6abed3e162a589595", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-023.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY"}, "rubrics": ["U-B1-023-RUBRIC"], "unit_id": "U-B1-023", "version": "0.1.0", "title_ru": "Суммировать практическую информацию для другого человека", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Медиация практической информации — это помощь конкретному человеку понять, что ему делать. Это не обязательно дословный перевод и не полное изложение всех строк объявления. Сначала выясните потребность адресата. Для новичка без фотоаппарата важно, можно ли участвовать с телефоном; для человека с ограниченной подвижностью — доступ к помещению. Передайте нужные сведения точно, сохранив ограничения.\\nРабочая схема: кому помогаю → что он хочет сделать → какие данные нужны → какое действие и срок → чего мы не знаем. Выделите в источнике место, время, условие участия, оборудование и возможные ограничения. При сокращении нельзя потерять слово μέχρι или отрицание δεν: они могут изменить решение адресата. «Μπορείς να μπεις σε λίστα αναμονής» не равно «Έχεις θέση».\\nРазделяйте сведения источника и своё предложение. «Η ανακοίνωση λέει ότι…» вводит проверяемую информацию; «θα σου πρότεινα να…» — совет. Если человек спрашивает об условиях, которых нет в тексте, честно укажите пробел и предложите связаться с организатором. Не добавляйте бесплатную парковку, переводчика или гарантированный доступ только потому, что они были бы удобны.\\nСложное сообщение можно упростить короткими предложениями: «Πρέπει να δηλώσεις συμμετοχή μέχρι την Πέμπτη. Δεν χρειάζεται ακριβή μηχανή· μπορείς να χρησιμοποιήσεις κινητό». Такая перестройка полезна, если адресат плохо владеет греческим. Не следует говорить громче вместо упрощения содержания. Попросите адресата повторить следующий шаг своими словами — так проверяется понимание без унижения.\\nСохраняйте числа и время. Если источник использует24-часовой формат, можно сказать «στις δέκα το πρωί», но не потерять день или длительность. Не превращайте дедлайн регистрации в день мероприятия. Если источники противоречат друг другу, отметьте противоречие и уточните; не выбирайте наугад удобный вариант.\\nВ этом уроке источник один и короткий: синтез нескольких развёрнутых источников будет отдельной задачей B2. Предпосылки — B1-R01 и B1-SP01. Диагностика проверяет извлечение времени и условия, затем вы создаёте сообщение для конкретного адресата. Критерий освоения — адресат может выполнить нужное действие без потерянного ограничения. Самостоятельный пересказ и D7/D28 должны использовать новый контекст; заученная модель не доказывает медиацию.", "cefr_level": "B1", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Μπορείς να χρησιμοποιήσεις το κινητό σου.", "Πρέπει να δηλώσεις συμμετοχή μέχρι την Πέμπτη.", "Η λίστα αναμονής δεν σου εξασφαλίζει θέση.", "Δεν αναφέρεται αν υπάρχει χώρος στάθμευσης."], "review_plan": {"D7": ["U-B1-023-I10"], "D28": ["U-B1-023-I11"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-B1-023-I10", "U-B1-023-I11"]}, "source_refs": [{"anchor": "Oral production101–103, handling communication problems", "source_id": "CP08-B1", "checked_on": "2026-10-22", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "active_recall": ["U-B1-023-I07"], "prerequisites": ["B1-R01", "B1-SP01"], "reading_tasks": ["U-B1-023-I01", "U-B1-023-I02", "U-B1-023-I03"], "transfer_task": "U-B1-023-I09", "writing_tasks": ["U-B1-023-I04", "U-B1-023-I05", "U-B1-023-I09", "U-B1-023-I11"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B1-023-I01", "U-B1-023-I03"], "objective": "Извлекать действия, сроки и ограничения источника"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B1-023-I02", "U-B1-023-I04", "U-B1-023-I05", "U-B1-023-I06", "U-B1-023-I08"], "objective": "Отбирать сведения для конкретного адресата без домысливания"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B1-023-I07", "U-B1-023-I09", "U-B1-023-I10", "U-B1-023-I11"], "objective": "Самостоятельно передавать информацию и проверять понимание"}], "competency_ids": ["B1-M01"], "speaking_tasks": ["U-B1-023-I07", "U-B1-023-I08", "U-B1-023-I10"], "entry_probe_ids": ["U-B1-023-I01"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION"], "guided_practice": ["U-B1-023-I02", "U-B1-023-I03", "U-B1-023-I04", "U-B1-023-I05", "U-B1-023-I06", "U-B1-023-I08"], "listening_tasks": [], "modality_status": "AUDIO_PENDING", "vocabulary_items": [{"lemma": "η προθεσμία", "stress": "η προθεσμία", "example": "Η προθεσμία λήγει την Πέμπτη.", "inflection": "της προθεσμίας; οι προθεσμίες", "collocations": ["προθεσμία εγγραφής"]}, {"lemma": "η λίστα αναμονής", "stress": "η λίστα αναμονής", "example": "Μπορείς να μπεις σε λίστα αναμονής.", "inflection": "της λίστας αναμονής", "collocations": ["μπαίνω σε λίστα αναμονής"]}, {"lemma": "εξασφαλίζω", "stress": "εξασφαλίζω", "example": "Η αίτηση δεν εξασφαλίζει θέση.", "inflection": "εξασφάλισα", "collocations": ["εξασφαλίζω θέση"]}], "learning_objectives": ["Извлекать действия, сроки и ограничения источника", "Отбирать сведения для конкретного адресата без домысливания", "Самостоятельно передавать информацию и проверять понимание"], "prerequisite_policy": "Diagnose before instruction; failure routes to primary unit(s) from96 register. Authored prerequisite is not evidence of learner mastery. Retry with fresh example.", "primary_competencies": ["B1-M01"], "estimated_active_minutes": 65}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3170	unit	U-B1-024	69e8687007ae684d530b36f43c72abf9912ae31aa7edbc4f7acd074ea333c1da	core	{"unit_id": "U-B1-024", "content_hash": "69e8687007ae684d530b36f43c72abf9912ae31aa7edbc4f7acd074ea333c1da", "canonical_path": "GreekOS_Academic_Corpus/units/U-B1-024.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY"}, "rubrics": ["U-B1-024-RUBRIC"], "unit_id": "U-B1-024", "version": "0.1.0", "title_ru": "Взять слово, уточнить, вежливо возразить и восстановить понимание", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Участие в разговоре — это не только правильное предложение. Нужно вовремя вступить, показать связь с чужой мыслью, уточнить непонятное и вернуть разговор к общей цели. «Μπορώ να προσθέσω κάτι;» просит слово, «Αν κατάλαβα σωστά…» проверяет понимание, а «Συμφωνώ ως προς…, αλλά…» позволяет выделить конкретную область согласия. Не используйте эти формулы как украшения: за ними должно следовать содержательное действие.\\nКогда хотите вступить, дождитесь естественной границы реплики. Если приходится перебить из-за важной ошибки, обозначьте причину кратко: «Συγγνώμη που διακόπτω, αλλά πρέπει να διευκρινίσουμε την ώρα». После уточнения верните слово: «Συνέχισε, σε παρακαλώ». В письменной симуляции можно проверить содержание этих ходов, но нельзя подтвердить реальное управление паузами и перебиванием без звука и партнёра.\\nУточнение полезнее общего «Δεν κατάλαβα», если вы можете назвать пробел. Спросите «Όταν λες νωρίς, εννοείς πριν από τις οκτώ;». Это гипотеза, а не утверждение. Если собеседник её опровергает, обновите понимание: «Εντάξει, άρα στις εννέα». Не продолжайте исходный план после получения поправки. Перефразирование должно сохранять степень уверенности: «ίσως» нельзя пересказывать как «σίγουρα».\\nВежливое несогласие направляйте на предложение, а не на человека. Можно признать пользу идеи, затем назвать затруднение и предложить проверяемую альтернативу. «Καταλαβαίνω ότι η Κυριακή βολεύει πολλούς, αλλά εγώ εργάζομαι. Μήπως μπορούμε το Σάββατο;». Такая структура не обязательна в каждой реплике: слишком длинная формула может мешать простому обмену. Важно, чтобы адресат понял, с чем именно вы не согласны и какое действие предлагаете.\\nЕсли ваша речь вызвала непонимание, переформулируйте, а не просто повторите громче. «Με άλλα λόγια, δεν ζητώ να ακυρωθεί η συνάντηση· ζητώ να αλλάξει η ώρα». Исправляя собственную неточность, назовите окончательный вариант. Не заставляйте собеседника угадывать, относится ли поправка ко всему плану или к одной детали. Если неизвестно слово, используйте описание функции; помощь собеседника фиксируется как поддержка, но не как неуспех всего общения.\\nЗавершайте обсуждение совместным итогом: что согласовано, что осталось открытым, кто уточняет следующий вопрос. «Συμφωνήσαμε για το Σάββατο, αλλά η αίθουσα δεν έχει επιβεβαιωθεί. Θα ρωτήσω εγώ». Это предотвращает ложную договорённость. Предпосылки — A2-PR01 и B1-SI01. В независимой практике партнёр даёт неожиданную поправку после первого ответа; заранее видимый полный диалог проверяет чтение, а не спонтанное взаимодействие. D7 и D28 меняют ситуацию и сохраняют необходимость реального ответа.", "cefr_level": "B1", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Μπορώ να προσθέσω κάτι;", "Όταν λες νωρίς, τι ώρα εννοείς;", "Καταλαβαίνω την πρόταση, αλλά έχω μια δυσκολία.", "Συμφωνήσαμε για την ημέρα, όχι ακόμη για τον χώρο."], "review_plan": {"D7": ["U-B1-024-I11"], "D28": ["U-B1-024-I12"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-B1-024-I11", "U-B1-024-I12"]}, "source_refs": [{"anchor": "Oral production101–103, handling communication problems", "source_id": "CP08-B1", "checked_on": "2026-10-22", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "active_recall": ["U-B1-024-I08"], "prerequisites": ["A2-PR01", "B1-SI01"], "reading_tasks": ["U-B1-024-I04"], "transfer_task": "U-B1-024-I09", "writing_tasks": ["U-B1-024-I10"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B1-024-I01", "U-B1-024-I02", "U-B1-024-I07"], "objective": "Вступать в разговор и возвращать слово"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B1-024-I03", "U-B1-024-I04", "U-B1-024-I05", "U-B1-024-I06", "U-B1-024-I08", "U-B1-024-I11"], "objective": "Уточнять смысл, вежливо возражать и исправлять понимание"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B1-024-I09", "U-B1-024-I10", "U-B1-024-I12"], "objective": "Самостоятельно поддерживать разговор и фиксировать общий итог"}], "competency_ids": ["B1-PR01"], "speaking_tasks": ["U-B1-024-I01", "U-B1-024-I03", "U-B1-024-I05", "U-B1-024-I06", "U-B1-024-I07", "U-B1-024-I08", "U-B1-024-I09", "U-B1-024-I11", "U-B1-024-I12"], "entry_probe_ids": ["U-B1-024-I01"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION"], "guided_practice": ["U-B1-024-I02", "U-B1-024-I03", "U-B1-024-I04", "U-B1-024-I05", "U-B1-024-I06", "U-B1-024-I07", "U-B1-024-I10"], "listening_tasks": [], "modality_status": "AUDIO_PENDING", "vocabulary_items": [{"lemma": "διευκρινίζω", "stress": "διευκρινίζω", "example": "Θέλω να διευκρινίσω την ώρα.", "inflection": "διευκρίνισα; να διευκρινίσω", "collocations": ["διευκρινίζω την ώρα"]}, {"lemma": "διακόπτω", "stress": "διακόπτω", "example": "Συγγνώμη που διακόπτω.", "inflection": "διέκοψα; να διακόψω", "collocations": ["διακόπτω τον συνομιλητή"]}, {"lemma": "συμφωνώ", "stress": "συμφωνώ", "example": "Συμφωνώ με την πρόταση, αλλά χρειάζομαι περισσότερες πληροφορίες.", "inflection": "συμφώνησα; να συμφωνήσω", "collocations": ["συμφωνώ με την πρόταση"]}], "learning_objectives": ["Вступать в разговор и возвращать слово", "Уточнять смысл, вежливо возражать и исправлять понимание", "Самостоятельно поддерживать разговор и фиксировать общий итог"], "prerequisite_policy": "Diagnose before instruction; failure routes to primary unit(s) from96 register. Authored prerequisite is not evidence of learner mastery. Retry with fresh example.", "primary_competencies": ["B1-PR01"], "estimated_active_minutes": 65}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
