881	source_claim	CP08-INHERITED-U-A2-002-I08-01	a91685a80ba9ac51ac1826df17cc29a12d24c6addba95fb277d8ab92ed1a7b91	\N	{"record": {"claim": "Уровневая тема; не дословный источник авторских фраз", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A2-002-I08-01", "item_ids": ["U-A2-002-I08"], "source_id": "V201", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A2-002-I08.json", "sha256": "37f39ffd20b777383481593a35861d7240d6a536558115c3492b50644b76948b"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "V201 PDF7–8", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}}, "claim_id": "CP08-INHERITED-U-A2-002-I08-01", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3171	unit	U-B2-001	02849046ebf0d4844fd6f30481f0c76ef4a14a7abfa443edc6b6464f1af13b5c	core	{"unit_id": "U-B2-001", "content_hash": "02849046ebf0d4844fd6f30481f0c76ef4a14a7abfa443edc6b6464f1af13b5c", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-001.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B2-001-RUBRIC"], "unit_id": "U-B2-001", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-B2-001-I02", "U-B2-001-I03", "U-B2-001-I04", "U-B2-001-I05", "U-B2-001-I06", "U-B2-001-I07"], "reception": ["U-B2-001-I08", "U-B2-001-I09", "U-B2-001-I10", "U-B2-001-I11"], "retention": ["U-B2-001-I15", "U-B2-001-I16", "U-B2-001-I17"], "diagnostic": ["U-B2-001-I01"], "production": ["U-B2-001-I12", "U-B2-001-I13", "U-B2-001-I14"]}, "title_ru": "Статья для городской газеты: тезис, возражение и предложение", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Статья отличается от письма: ей обычно не нужны личное приветствие и подпись адресату, зато нужен заголовок и понятная читателю постановка проблемы. В этом блоке пишем для городской газеты о пользовании общественным пространством. Рабочая структура: проблема → позиция с основанием → серьёзное возражение и ответ → конкретное предложение. Это опора, а не обязательные четыре одинаковых абзаца.\\n\\nСвязка должна показывать реальное отношение мыслей. Ωστόσο вводит противопоставление, επομένως — следствие, για παράδειγμα — пример, παρόλο που — уступительное придаточное. Сравните Παρόλο που ο χώρος είναι μικρός, μπορεί να εξυπηρετήσει πολλούς κατοίκους и Ο χώρος είναι μικρός. Επομένως, χρειάζεται προσεκτική οργάνωση. Не заменяйте одну связку другой только для разнообразия. После παρόλο που нужна предикативная часть, тогда как несмотря на существительное можно передать παρά + винительный.\\n\\nСильный аргумент называет причину и последствия. «Это полезно» слабее, чем «Общий график позволяет пользоваться площадкой и детям, и пожилым». Для учебной статьи факты вымышленного кейса даны в условии. Не добавляйте проценты, ссылки на исследования и гарантии безопасности без источника. Уступка не означает отказ от позиции: Можно признать расходы, затем предложить ограниченный пробный период. При редактировании проверьте, отвечает ли каждый абзац задаче, не повторяет ли заключение начало дословно, понятны ли местоименные ссылки. Около 200 слов — ориентир задания B2, не доказательство нужного качества само по себе.", "cefr_level": "B2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Η πλατεία χρειάζεται περισσότερο πράσινο. Ωστόσο, πρέπει να παραμείνει προσβάσιμη.", "Παρόλο που το κόστος είναι σημαντικό, μπορούμε να ξεκινήσουμε με μια μικρή παρέμβαση.", "Ο φωτισμός είναι ανεπαρκής. Επομένως, χρειάζεται βελτίωση.", "Για παράδειγμα, οι κάτοικοι θα μπορούσαν να προτείνουν ένα κοινό ωράριο.", "Η πρόταση αυτή δεν λύνει κάθε πρόβλημα, αλλά μπορεί να δοκιμαστεί για έναν μήνα."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B2-001-I15", "U-B2-001-I16", "U-B2-001-I17"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF4,12–14; V268 PDF4 подтверждает жанр статьи; не подмена всеми заданиями письма", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Reports and essays / thematic development / coherence, B2", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-B2-001-I06", "U-B2-001-I07"], "prerequisites": ["B1-W01"], "reading_tasks": ["U-B2-001-I08", "U-B2-001-I09"], "transfer_task": "U-B2-001-I14", "writing_tasks": ["U-B2-001-I12"], "competency_ids": ["B2-W02", "B2-G07", "B2-V01", "B2-PR01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B2-001-I13"], "errors_taxonomy": ["PRAGMATICS_REGISTER", "SYNTAX", "CONTENT_OMISSION", "COLLOCATION"], "guided_practice": ["U-B2-001-I02", "U-B2-001-I03", "U-B2-001-I04", "U-B2-001-I05"], "listening_tasks": ["U-B2-001-I10", "U-B2-001-I11"], "learning_outcome": "Написать статью с тезисом, контраргументом и обоснованным предложением", "vocabulary_items": [{"lemma": "πρόσβαση", "stress": "πρόσβαση", "example": "Χρειαζόμαστε ελεύθερη πρόσβαση στον χώρο.", "inflection": "η πρόσβαση", "meaning_ru": "доступ", "collocations": ["ελεύθερη πρόσβαση", "πρόσβαση στον χώρο"]}, {"lemma": "παρέμβαση", "stress": "παρέμβαση", "example": "Μια μικρή παρέμβαση μπορεί να βοηθήσει.", "inflection": "η παρέμβαση, οι παρεμβάσεις", "meaning_ru": "изменение/вмешательство", "collocations": ["μικρή παρέμβαση"]}, {"lemma": "επιχείρημα", "stress": "επιχείρημα", "example": "Το κόστος είναι ένα σοβαρό επιχείρημα.", "inflection": "το επιχείρημα, τα επιχειρήματα", "meaning_ru": "аргумент", "collocations": ["ισχυρό επιχείρημα"]}, {"lemma": "ωστόσο", "stress": "ωστόσο", "example": "Η ιδέα είναι χρήσιμη. Ωστόσο, χρειάζεται έλεγχο.", "inflection": "связующее наречие", "meaning_ru": "однако", "collocations": ["ωστόσο, χρειάζεται…"]}], "soft_prerequisites": ["B2-G11"], "diagnostic_item_ids": ["U-B2-001-I01"], "learning_objectives": ["Написать статью с тезисом, контраргументом и обоснованным предложением", "Уместно связать уступку и противопоставление", "Отредактировать аргумент для публичного адресата без выдуманных данных"], "microcompetency_ids": ["U-B2-001-MC01", "U-B2-001-MC02", "U-B2-001-MC03"], "primary_competencies": ["B2-W02", "B2-G07"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3172	unit	U-B2-002	37136c9fcfcb982695197128c2e241a60fbac6cfcfc491cce91c3bdc89bd3d03	core	{"unit_id": "U-B2-002", "content_hash": "37136c9fcfcb982695197128c2e241a60fbac6cfcfc491cce91c3bdc89bd3d03", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-002.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B2-002-RUBRIC"], "unit_id": "U-B2-002", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-B2-002-I02", "U-B2-002-I03", "U-B2-002-I04", "U-B2-002-I05", "U-B2-002-I06"], "reception": ["U-B2-002-I07", "U-B2-002-I08", "U-B2-002-I09", "U-B2-002-I10"], "retention": ["U-B2-002-I14", "U-B2-002-I15", "U-B2-002-I16"], "diagnostic": ["U-B2-002-I01"], "production": ["U-B2-002-I11", "U-B2-002-I12", "U-B2-002-I13"]}, "title_ru": "Особые именные модели: διεθνής, γεγονός, προϊόν", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "У прилагательного διεθνής мужской и женский род в именительном единственного совпадают: ο διεθνής οργανισμός, η διεθνής συνεργασία; средний — το διεθνές συνέδριο. Родительный всех трёх родов: του/της διεθνούς. Во множественном мужской и женский — διεθνείς, средний — διεθνή, родительный — διεθνών. Сравните οι διεθνείς σχέσεις и τα διεθνή συνέδρια: существительное определяет род и число, а падеж задаёт синтаксис.\\nСуществительные το γεγονός и το προϊόν требуют отдельной парадигмы: του γεγονότος, τα γεγονότα, των γεγονότων; του προϊόντος, τα προϊόντα, των προϊόντων. Ударение — часть формы. Нельзя заменить их обычным окончанием существительных на -ο. Согласование помогает заметить ошибку, но не угадывает неизвестную основу.\\nПри чтении сначала найдите главное существительное, затем установите отношения в группе: η ποιότητα των τοπικών προϊόντων. Качество — подлежащее единственного числа; προϊόντων находится внутри зависимой группы и не управляет числом сказуемого. В Η εξέταση των γεγονότων απαιτεί χρόνο сказуемое относится к εξέταση. Эти модели выбираются для точности аргументативного текста, а не как полный перечень исключений B2. Если сомневаетесь, переформулируйте и проверьте конкретную парадигму, не создавая форму по одному внешнему окончанию.", "cefr_level": "B2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Η διεθνής συνεργασία είναι απαραίτητη.", "Συμμετείχαν σε δύο διεθνή συνέδρια.", "Η ποιότητα των προϊόντων ελέγχεται.", "Η σειρά των γεγονότων δεν είναι σαφής."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B2-002-I14", "U-B2-002-I15", "U-B2-002-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF12–14", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction B2", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-B2-002-I05", "U-B2-002-I06"], "prerequisites": ["B1-G01"], "reading_tasks": ["U-B2-002-I07", "U-B2-002-I08"], "transfer_task": "U-B2-002-I13", "writing_tasks": ["U-B2-002-I11"], "competency_ids": ["B2-G01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B2-002-I12"], "errors_taxonomy": ["DECLENSION_EXCEPTION", "AGREEMENT", "ACCENTUATION"], "guided_practice": ["U-B2-002-I02", "U-B2-002-I03", "U-B2-002-I04"], "listening_tasks": ["U-B2-002-I09", "U-B2-002-I10"], "learning_outcome": "Согласовать διεθνής в трёх родах и нужном числе", "vocabulary_items": [{"lemma": "διεθνής", "stress": "διεθνής", "example": "Μελετά τις διεθνείς σχέσεις.", "inflection": "ο/η διεθνής, το διεθνές; γεν. διεθνούς; πληθ. διεθνείς/διεθνή", "meaning_ru": "международный", "collocations": ["διεθνείς σχέσεις"]}, {"lemma": "γεγονός", "stress": "γεγονός", "example": "Δεν γνωρίζουμε όλα τα γεγονότα.", "inflection": "το γεγονός, του γεγονότος, τα γεγονότα, των γεγονότων", "meaning_ru": "событие; факт", "collocations": ["εξέταση των γεγονότων"]}, {"lemma": "προϊόν", "stress": "προϊόν", "example": "Ελέγχουν την ποιότητα των προϊόντων.", "inflection": "το προϊόν, του προϊόντος, τα προϊόντα, των προϊόντων", "meaning_ru": "продукт", "collocations": ["ποιότητα προϊόντων"]}, {"lemma": "συνέδριο", "stress": "συνέδριο", "example": "Το συνέδριο αρχίζει αύριο.", "inflection": "το συνέδριο, τα συνέδρια", "meaning_ru": "конференция", "collocations": ["διεθνές συνέδριο"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B2-002-I01"], "learning_objectives": ["Согласовать διεθνής в трёх родах и нужном числе", "Образовать родительный γεγονός/προϊόν в единственном и множественном числе", "Передать вывод нейтрально, не приписывая источнику недоказанное"], "microcompetency_ids": ["U-B2-002-MC01", "U-B2-002-MC02", "U-B2-002-MC03"], "primary_competencies": ["B2-G01"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
