3173	unit	U-B2-003	44b0907faeb5d4cad813c2fd03d93024e2d1dafad81acb3f743308f8c1822263	core	{"unit_id": "U-B2-003", "content_hash": "44b0907faeb5d4cad813c2fd03d93024e2d1dafad81acb3f743308f8c1822263", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-003.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B2-003-RUBRIC"], "unit_id": "U-B2-003", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-B2-003-I02", "U-B2-003-I03", "U-B2-003-I04", "U-B2-003-I05", "U-B2-003-I06"], "reception": ["U-B2-003-I07", "U-B2-003-I08", "U-B2-003-I09", "U-B2-003-I10"], "retention": ["U-B2-003-I14", "U-B2-003-I15", "U-B2-003-I16"], "diagnostic": ["U-B2-003-I01"], "production": ["U-B2-003-I11", "U-B2-003-I12", "U-B2-003-I13"]}, "title_ru": "Нереальность сейчас и в прошлом", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Условие выражает отношение между предпосылкой и следствием. В Αν έχω χρόνο, θα έρθω говорящий оставляет условие открытым. В Αν είχα περισσότερο χρόνο, θα ερχόμουν представляется гипотетическая ситуация; παρατατικός здесь не обязательно сообщает о прошлом. Контекст τώρα может явно отнести её к настоящему. Не делайте вывод о календарном времени только по форме.\\nДля нереализованного прошлого используем Αν είχα φύγει νωρίτερα, θα είχα προλάβει το λεωφορείο. В условной части είχα + форма совершенного вида показывает предшествующий результат, в следствии θα είχα + та же конструкция. В этой задаче контекст сообщает, что автобус уже ушёл и говорящий опоздал. Без контекста некоторые условные конструкции допускают больше одной интерпретации.\\nСравните гипотезу о ресурсах сейчас и сожаление о вчерашнем решении. Αν είχα χρήματα, θα αγόραζα έναν υπολογιστή не утверждает, что покупка состоялась. Αν είχα ελέγξει την ώρα, δεν θα είχα αργήσει обсуждает альтернативное прошлое. Можно выразить сожаление и с Μακάρι να είχα ελέγξει την ώρα. Это не обещание изменить уже случившееся.\\nВ переговорах контрфактическое рассуждение помогает найти причину сбоя, но не должно превращаться в голословное обвинение. Сначала назовите известное событие, затем условную альтернативу и реальный следующий шаг. Задания на открытый ответ допускают естественные перефразировки, сохраняющие различие факта и предположения.", "cefr_level": "B2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Αν είχα χρόνο τώρα, θα ερχόμουν μαζί σας.", "Αν είχα φύγει νωρίτερα, θα είχα προλάβει το τρένο.", "Μακάρι να είχα κρατήσει ένα αντίγραφο.", "Αν έχουμε χρόνο αύριο, θα συζητήσουμε ξανά."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B2-003-I14", "U-B2-003-I15", "U-B2-003-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF12–14", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction B2", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-B2-003-I05", "U-B2-003-I06"], "prerequisites": ["B1-G07", "B1-G05"], "reading_tasks": ["U-B2-003-I07", "U-B2-003-I08"], "transfer_task": "U-B2-003-I13", "writing_tasks": ["U-B2-003-I11"], "competency_ids": ["B2-G03"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B2-003-I12"], "errors_taxonomy": ["CONDITIONAL", "TENSE", "MODALITY"], "guided_practice": ["U-B2-003-I02", "U-B2-003-I03", "U-B2-003-I04"], "listening_tasks": ["U-B2-003-I09", "U-B2-003-I10"], "learning_outcome": "Различить открытое условие и гипотетическое настоящее", "vocabulary_items": [{"lemma": "προλαβαίνω", "stress": "προλαβαίνω", "example": "Δεν πρόλαβα το τρένο.", "inflection": "πρόλαβα; έχω προλάβει", "meaning_ru": "успевать", "collocations": ["προλαβαίνω το τρένο"]}, {"lemma": "ελέγχω", "stress": "ελέγχω", "example": "Είχα ελέγξει την ώρα.", "inflection": "έλεγξα; έχω ελέγξει", "meaning_ru": "проверять", "collocations": ["ελέγχω την ώρα"]}, {"lemma": "μετανιώνω", "stress": "μετανιώνω", "example": "Μετάνιωσα για την απόφασή μου.", "inflection": "μετάνιωσα", "meaning_ru": "сожалеть", "collocations": ["μετανιώνω για μια απόφαση"]}, {"lemma": "αντίγραφο", "stress": "αντίγραφο", "example": "Κράτησα ένα αντίγραφο.", "inflection": "το αντίγραφο, τα αντίγραφα", "meaning_ru": "копия", "collocations": ["κρατάω ένα αντίγραφο"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B2-003-I01"], "learning_objectives": ["Различить открытое условие и гипотетическое настоящее", "Построить альтернативное прошлое с αν είχα…θα είχα", "Обсудить сожаление и реальный следующий шаг без смешения времён"], "microcompetency_ids": ["U-B2-003-MC01", "U-B2-003-MC02", "U-B2-003-MC03"], "primary_competencies": ["B2-G03"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3174	unit	U-B2-004	9079ef937b3cc93fb63976f9f1700686b04ebc3288c06ed21538067baf854e2b	core	{"unit_id": "U-B2-004", "content_hash": "9079ef937b3cc93fb63976f9f1700686b04ebc3288c06ed21538067baf854e2b", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-004.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B2-004-RUBRIC"], "unit_id": "U-B2-004", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-B2-004-I02", "U-B2-004-I03", "U-B2-004-I04", "U-B2-004-I05", "U-B2-004-I06"], "reception": ["U-B2-004-I07", "U-B2-004-I08", "U-B2-004-I09", "U-B2-004-I10"], "retention": ["U-B2-004-I14", "U-B2-004-I15", "U-B2-004-I16"], "diagnostic": ["U-B2-004-I01"], "production": ["U-B2-004-I11", "U-B2-004-I12", "U-B2-004-I13"]}, "title_ru": "Сравнение с оговорками: περισσότερο, καλύτερα, όσο…τόσο", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Сравнение требует назвать признак и основание. Прилагательное согласуется с существительным: καλύτερη λύση, καλύτερο σχέδιο, καλύτερες συνθήκες. Наречие характеризует действие: λειτουργεί καλύτερα. Поэтому «более хороший способ» — καλύτερος τρόπος, но «работает лучше» — δουλεύει καλύτερα. Περισσότερος также согласуется: περισσότερος χρόνος, περισσότερη βοήθεια, περισσότερο φως, περισσότερες επιλογές. Наречное περισσότερο в δουλεύει περισσότερο говорит об объёме или длительности работы.\\nОтносительное превосходство обозначает крайний случай внутри группы: η καλύτερη από τις τρεις προτάσεις. Оно не доказывает абсолютного совершенства и не делает решение лучшим по всем критериям. Более дешёвый вариант может быть менее удобным. Фраза σε σχέση με помогает задать базу сравнения, ενώ/ωστόσο — сохранить оговорку.\\nКорреляция όσο…τόσο показывает сопряжённое изменение: Όσο περισσότερο εξασκούμαι, τόσο πιο άνετα μιλάω. Это языковая модель, а не универсальная научная гарантия. В обсуждении конкретных данных не приписывайте причинность простой совместной динамике. Сначала назовите наблюдаемое различие, затем предел вывода.\\nВ задании с таблицей используйте только её числа. Если вариант A дешевле B, это ещё не означает, что A доступнее людям без транспорта. Уточните нужду адресата. Качественная рекомендация B2 связывает минимум два критерия и указывает, при каком условии изменился бы выбор.", "cefr_level": "B2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Αυτή είναι η καλύτερη λύση για την ομάδα μας.", "Το νέο σύστημα λειτουργεί καλύτερα, αλλά κοστίζει περισσότερο.", "Χρειαζόμαστε περισσότερες επιλογές.", "Όσο περισσότερο εξασκούμαι, τόσο πιο άνετα μιλάω."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B2-004-I14", "U-B2-004-I15", "U-B2-004-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF12–14", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction B2", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-B2-004-I05", "U-B2-004-I06"], "prerequisites": ["A2-G09", "B1-G01"], "reading_tasks": ["U-B2-004-I07", "U-B2-004-I08"], "transfer_task": "U-B2-004-I13", "writing_tasks": ["U-B2-004-I11"], "competency_ids": ["B2-G05", "B2-G07"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B2-004-I12"], "errors_taxonomy": ["COMPARISON", "AGREEMENT", "UNSUPPORTED_INFERENCE"], "guided_practice": ["U-B2-004-I02", "U-B2-004-I03", "U-B2-004-I04"], "listening_tasks": ["U-B2-004-I09", "U-B2-004-I10"], "learning_outcome": "Различить сравнительное прилагательное и наречие καλύτερος/καλύτερα", "vocabulary_items": [{"lemma": "καλύτερος", "stress": "καλύτερος", "example": "Βρήκαμε μια καλύτερη λύση.", "inflection": "καλύτερος, καλύτερη, καλύτερο; наречие καλύτερα", "meaning_ru": "лучший; лучше", "collocations": ["καλύτερη λύση"]}, {"lemma": "περισσότερος", "stress": "περισσότερος", "example": "Χρειάζομαι περισσότερο χρόνο.", "inflection": "περισσότερος, περισσότερη, περισσότερο", "meaning_ru": "больше", "collocations": ["περισσότερος χρόνος"]}, {"lemma": "λιγότερος", "stress": "λιγότερος", "example": "Θέλω λιγότερες μετακινήσεις.", "inflection": "λιγότερος, λιγότερη, λιγότερο", "meaning_ru": "меньше", "collocations": ["λιγότερες μετακινήσεις"]}, {"lemma": "κριτήριο", "stress": "κριτήριο", "example": "Το κόστος δεν είναι το μόνο κριτήριο.", "inflection": "το κριτήριο, τα κριτήρια", "meaning_ru": "критерий", "collocations": ["κριτήρια επιλογής"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B2-004-I01"], "learning_objectives": ["Различить сравнительное прилагательное и наречие καλύτερος/καλύτερα", "Обосновать выбор по двум критериям и обозначить ограничение", "Назвать условие, при котором рекомендация изменилась бы"], "microcompetency_ids": ["U-B2-004-MC01", "U-B2-004-MC02", "U-B2-004-MC03"], "primary_competencies": ["B2-G05", "B2-G07"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
