3175	unit	U-B2-005	b96bf68a575ee64fbb7738623e91aa2697902e8e24b0d3021ce2ebdb01161f21	core	{"unit_id": "U-B2-005", "content_hash": "b96bf68a575ee64fbb7738623e91aa2697902e8e24b0d3021ce2ebdb01161f21", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-005.json", "teaching_material": {"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B2-005-RUBRIC"], "unit_id": "U-B2-005", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-B2-005-I02", "U-B2-005-I03", "U-B2-005-I04", "U-B2-005-I05", "U-B2-005-I06", "U-B2-005-I07", "U-B2-005-I08", "U-B2-005-I19", "U-B2-005-I20"], "reception": ["U-B2-005-I09", "U-B2-005-I10", "U-B2-005-I11", "U-B2-005-I12"], "retention": ["U-B2-005-I16", "U-B2-005-I17", "U-B2-005-I18", "U-B2-005-I22"], "diagnostic": ["U-B2-005-I01"], "production": ["U-B2-005-I13", "U-B2-005-I14", "U-B2-005-I15", "U-B2-005-I21"]}, "title_ru": "Формальные связи: предлоги и управление", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "В официальном сообщении предлог обозначает точное отношение: причину, канал, источник правила или тему. Формальная лексика сама по себе не делает текст точным. Сначала решите, что связываете, затем проверьте падеж всей именной группы, включая артикль и прилагательное.\\n\\nΛόγω + родительный обозначает причину: λόγω της καθυστέρησης, λόγω των τεχνικών προβλημάτων. Εξαιτίας + родительный тоже указывает причину, часто с неблагоприятным оттенком: εξαιτίας της βλάβης. Не вводите жёсткий запрет на нейтральные контексты: окраска зависит от ситуации. Если оба слова подходят к отрицательной причине, вопрос с единственным ключом не должен предлагать их как взаимоисключающие ответы без дополнительного условия.\\n\\nΜέσω + родительный обозначает путь, канал или посредника: μέσω της πλατφόρμας, μέσω του εκπροσώπου. Это не «из-за»: Η αίτηση υποβάλλεται μέσω της πλατφόρμας объясняет способ подачи. Предложение Η αίτηση καθυστέρησε λόγω προβλήματος στην πλατφόρμα сообщает причину задержки. Одинаковое существительное не означает одинаковую связь.\\n\\nВ σύμφωνα με, σχετικά με, με βάση существительное зависит от με и стоит в винительном: σύμφωνα με τον κανονισμό, σχετικά με την αίτηση, με βάση τα στοιχεία. Σύμφωνα με обычно вводит соответствие правилу или источник утверждения; με βάση — основу решения/вывода; σχετικά με — тему. В некоторых контекстах первые два пересекаются, поэтому выбирайте по явно указанной коммуникативной задаче, а не по мнимому универсальному запрету.\\n\\nСопоставьте формы: της νέας αίτησης после λόγω / μέσω и τη νέα αίτηση после σχετικά με; των τεχνικών προβλημάτων и τα τεχνικά προβλήματα. Устойчивую конструкцию нельзя обрывать: *σύμφωνα τον κανονισμό требует με. С другой стороны, после λόγω не добавляется με по аналогии: λόγω της αλλαγής.\\n\\nПри редактировании официального письма сохраняйте факты и степень уверенности. «По имеющимся данным» не равно «это доказано». Не заменяйте разговорное потому что более тяжёлым оборотом, если теряется субъект или причина. Обратная передача простыми словами проверяет понимание: Λόγω της βλάβης… → Επειδή χάλασε…; Μέσω της πλατφόρμας… → Χρησιμοποιήστε την πλατφόρμα… . В самостоятельной задаче адресат должен понять, что произошло, как действовать и на каком основании принято решение.", "cefr_level": "B2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Λόγω της βλάβης, το γραφείο θα ανοίξει αργότερα.", "Η αίτηση αποστέλλεται μέσω της πλατφόρμας.", "Η συνάντηση αναβλήθηκε εξαιτίας της κακοκαιρίας.", "Σύμφωνα με τον κανονισμό, απαιτείται υπογραφή.", "Σας γράφω σχετικά με την αίτησή μου.", "Με βάση τα διαθέσιμα στοιχεία, χρειάζεται νέος έλεγχος."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B2-005-I16", "U-B2-005-I17", "U-B2-005-I18", "U-B2-005-I22"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Историческая уровневая тематическая карта; размещение требует эксперта", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Reception, production, interaction; author mapping, not official cut score", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "§8: προθέσεις; λόγιες, σύνθετες конструкции", "source_id": "N408", "checked_on": "2026-10-14", "claim_scope": "Грамматическое/фонетическое правило; задания оригинальные", "evidence_type": "OFFICIAL_SCHOOL_GRAMMAR_NOT_AUTH_SYLLABUS"}, {"anchor": "§4, genitive/accusative lists", "source_id": "N409", "checked_on": "2026-10-14", "claim_scope": "Explicit government of λόγω/εξαιτίας/μέσω and με", "evidence_type": "OFFICIAL_KEG_GRAMMAR_REFERENCE"}], "evidence_map": [{"delayed": ["U-B2-005-I16", "U-B2-005-I22"], "transfer": ["U-B2-005-I13", "U-B2-005-I15"], "source_ids": ["V201", "W322", "N408", "N409"], "prerequisites": ["A1-G09", "B1-G01"], "mastery_decision": {"rule": "Целевая связь/форма верна в контролируемом задании; самостоятельное применение в новом сообщении и переносе; повтор без подсказок через 7/14/28 дней. Не усреднять критическую смысловую ошибку.", "status": "NOT_ASSESSED", "pronunciation_gate": "NOT_INFERRED_FROM_TRANSCR