ence_is_collected": false, "independent_production": ["U-B2-005-I13", "U-B2-005-I14", "U-B2-005-I21"], "recognition_or_controlled": ["U-B2-005-I09", "U-B2-005-I10"], "success_criteria_specific": "Редактировать письмо и объяснить его содержание простыми словами без потери смысла."}], "active_recall": ["U-B2-005-I07", "U-B2-005-I08", "U-B2-005-I19", "U-B2-005-I20"], "prerequisites": ["A1-G09", "B1-G01"], "reading_tasks": ["U-B2-005-I09", "U-B2-005-I10"], "transfer_task": "U-B2-005-I15", "writing_tasks": ["U-B2-005-I13"], "competency_ids": ["B2-G06"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B2-005-I14", "U-B2-005-I21"], "errors_taxonomy": ["GENITIVE_GOVERNMENT", "ACC_AFTER_ME", "CHANNEL_CAUSE_CONFUSION", "MISSING_ME", "REGISTER_OBSCURES_MEANING", "UNSUPPORTED_CERTAINTY"], "guided_practice": ["U-B2-005-I02", "U-B2-005-I03", "U-B2-005-I04", "U-B2-005-I05", "U-B2-005-I06"], "listening_tasks": ["U-B2-005-I11", "U-B2-005-I12"], "pedagogy_review": {"scope": "full explanation, contrast, model, controlled practice, recall, reception, independent output, repair, transfer, delayed retrieval", "status": "AUTHOR_REVIEWED_NOT_INDEPENDENT", "open_blockers": ["INDEPENDENT_GREEK_REVIEW", "AUDIO_NOT_PRODUCED", "LEARNER_PILOT_NOT_RUN"]}, "learning_outcome": "Выбрать падеж после λόγω, μέσω, εξαιτίας и μετά με в составных выражениях.", "vocabulary_items": [{"lemma": "η βλάβη", "stress": "η βλάβη", "example": "Το σύστημα έκλεισε λόγω της βλάβης.", "inflection": "της βλάβης", "meaning_ru": "неисправность", "collocations": ["λόγω της βλάβης"]}, {"lemma": "η πλατφόρμα", "stress": "η πλατφόρμα", "example": "Στείλτε το αρχείο μέσω της πλατφόρμας.", "inflection": "της πλατφόρμας", "meaning_ru": "платформа", "collocations": ["μέσω της πλατφόρμας"]}, {"lemma": "ο κανονισμός", "stress": "ο κανονισμός", "example": "Απαντούμε σύμφωνα με τον κανονισμό.", "inflection": "του κανονισμού", "meaning_ru": "регламент", "collocations": ["σύμφωνα με τον κανονισμό"]}, {"lemma": "το στοιχείο", "stress": "το στοιχείο", "example": "Η απόφαση βασίζεται στα στοιχεία.", "inflection": "τα στοιχεία", "meaning_ru": "данные/элемент", "collocations": ["με βάση τα στοιχεία"]}, {"lemma": "η υποβολή", "stress": "η υποβολή", "example": "Η υποβολή γίνεται ηλεκτρονικά.", "inflection": "της υποβολής", "meaning_ru": "подача", "collocations": ["η υποβολή αίτησης"]}, {"lemma": "ο εκπρόσωπος", "stress": "ο εκπρόσωπος", "example": "Επικοινωνήστε μέσω του εκπροσώπου.", "inflection": "του εκπροσώπου", "meaning_ru": "представитель", "collocations": ["μέσω του εκπροσώπου"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B2-005-I01"], "learning_objectives": ["Выбрать падеж после λόγω, μέσω, εξαιτίας и μετά με в составных выражениях.", "Различить причину, канал, основание и тему в официальном сообщении.", "Редактировать письмо и объяснить его содержание простыми словами без потери смысла."], "microcompetency_ids": ["U-B2-005-MC01", "U-B2-005-MC02", "U-B2-005-MC03"], "primary_competencies": ["B2-G06"], "learner_data_included": false, "speaking_scenario_ids": ["SC40"], "estimated_active_minutes": 65}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3176	unit	U-B2-006	e105df291bc4f0c5e2720b85c7c181c116befa3b69a45819abca802f268e31ef	core	{"unit_id": "U-B2-006", "content_hash": "e105df291bc4f0c5e2720b85c7c181c116befa3b69a45819abca802f268e31ef", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-006.json", "teaching_material": {"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "DRAFT", "rubrics": ["U-B2-006-RUBRIC"], "unit_id": "U-B2-006", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-B2-006-I02", "U-B2-006-I03", "U-B2-006-I04", "U-B2-006-I05", "U-B2-006-I06", "U-B2-006-I07", "U-B2-006-I08", "U-B2-006-I09"], "reception": ["U-B2-006-I10", "U-B2-006-I11", "U-B2-006-I12", "U-B2-006-I13"], "retention": ["U-B2-006-I17", "U-B2-006-I18", "U-B2-006-I19"], "diagnostic": ["U-B2-006-I01"], "production": ["U-B2-006-I14", "U-B2-006-I15", "U-B2-006-I16"]}, "title_ru": "Редактируем сообщение: действие, результат, голос и намерение", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "В этом уроке мы редактируем сообщение для человека, которому нужно принять решение. Проверяйте три независимых вопроса: что произошло и когда; кто действует или испытывает действие; насколько говорящий уверен и чего он требует. Одна форма не отвечает на все три вопроса. Η ομάδα διορθώνει το κείμενο — команда работает над текстом. Το κείμενο διορθώνεται — в центре сообщения текст и процесс. Не всякое -μαι означает воздействие другого человека: θυμάμαι, έρχομαι остаются лексическими глаголами без такого пассивного смысла.\\nПовторите опорную цепочку διορθώνω — διόρθωσα — θα διορθώσω — έχω διορθώσει; διορθώνομαι — διορθώθηκα — θα διορθωθώ — έχω διορθωθεί. Для предмета: το λάθος διορθώθηκε; τα λάθη διορθώθηκαν. Процесс в прошлом: διόρθωνα/διορθωνόταν. Не переносите ударение механически из одной формы в другую. Практика ограничена изученными рядами: новые пассивные основы следует проверять отдельно.\\nВыбор вида — выбор взгляда на событие. Χτες διόρθωνα το κείμενο όταν τηλεφώνησες показывает процесс в момент звонка; не утверждает, что работа не была завершена позже. Χτες διόρθωσα το κείμενο представляет работу целиком; это не означает, что она заняла секунду. Έχω διορθώσει το κείμενο сообщает о завершении, значимом сейчас; Είχα διορθώσει το κείμενο πριν από τη συνάντηση помещает завершение раньше другого прошлого ориентира. Не учите правило «аорист — коротко, имперфект — долго»: Σπούδασα τέσσερα χρόνια описывает длительный период как целое.\\nПодстановка голоса должна сохранять число, время и известного исполнителя. Η συντάκτρια διόρθωσε τα λάθη → Τα λάθη διορθώθηκαν από τη συντάκτρια. Если исходное сообщение не называет человека, не назначайте его сами. При обратном преобразовании можно сказать Κάποιος διόρθωσε τα λάθη, но это неопределённый агент, а не установленное имя. Предложение Το κείμενο διορθώνεται ακόμη не разрешает сообщить «уже исправлено».\\nБудущий план не равен выполнению: Θα διορθώσουμε το κείμενο αύριο. Требование: Πρέπει να διορθωθεί το κείμενο πριν από την αποστολή. Возможность: Μπορούμε να διορθώσουμε το κείμενο σήμερα. Для одной завершённой правки выбираем να διορθώσουμε; для регулярной обязанности — Πρέπει να ελέγχουμε τις ημερομηνίες κάθε μέρα. Вежливое Θα μπορούσατε να το ελέγξετε; — просьба, а не сообщение о будущем умении. Контекст определяет коммуникативный смысл.\\nРедакторская проверка: подчеркните временную опору, обозначьте участника, отделите факт от обещания, затем прочитайте итог адресату. Он должен понять, можно ли отправлять документ сейчас. Если ответ зависит от ещё не выполненной проверки, назовите это явно. Достигнутый результат фиксируется лишь после самостоятельной новой ситуации и отсроченного переноса; этот урок не закрывает все времена всех спряжений.\\nОпора новых глаголов перед продукцией: ελέγχω — έλεγξα — έχω ελέγξει; ελέγχεται — ελέγχθηκε — έχει ελεγχθεί; ελέγχονται — έχουν ελεγχθεί. Επισκευάζω — επισκευάζεται (ремонтируется). Μεταφράζω — μετέφραζα — έχει μεταφραστεί (переведено). Ολοκληρώνω — θα ολοκληρωθεί (будет завершено). Τυπώνω — τυπώνονται (печатаются). Αλλάζω — άλλαξε (изменилось). Составьте по одной фразе с новой формой до задания; если при переносе нужна эта опора, отмечайте попытку как выполненную с помощью, а затем повторите самостоятельно.", "cefr_level": "B2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Η ομάδα διόρθωνε το κείμενο όταν έφτασα.", "Τα λάθη διορθώθηκαν από τη συντάκτρια.", "Το αρχείο έχει ήδη διορθωθεί.", "Είχαμε ελέγξει τις ημερομηνίες πριν από τη συνάντηση.", "Πρέπει να ελέγχουμε τις ημερομηνίες κάθε μέρα.", "Θα μπορούσατε να ελέγξετε το τελευταίο αρχείο;"], "review_plan": {"days": [7, 14, 28], "rule": "Новая самостоятельная попытка; помощь фиксировать отдельно; нет эмпирически подтверждённого mastery.", "item_ids": ["U-B2-006-I17", "U-B2-006-I18", "U-B2-006-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "§6.2α lines 10–18; §6.2ε lines 79–109", "source_id": "N405", "checked_on": "2026-10-19", "claim_scope": ["Morphological voice differs from semantic disposition", "Aspect categories and active/passive λύνω paradigms; διορθώνω explicitly listed in same class"], "evidence_type": "OFFICIAL_GRAMMAR_OR_DICTIONARY", "evidence_record": "B06-S02", "evidence_status": "SOURCE_PASS_BOUNDED_CLAIMS"}], "active_recall": ["U-B2-006-I08", "U-B2-006-I09"], "prerequisites": ["B1-G04", "B1-G05", "A2-G03"], "reading_tasks": ["U-B2-006-I10", "U-B2-006-I11"], "transfer_task": "U-B2-006-I16", "writing_tasks": ["U-B2-006-I14"], "competency_ids": ["B2-G02"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B2-006-I15"], "errors_taxonomy": ["TARGET_FORM", "MEANING_DISTORTION", "AGENT_REFERENCE", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-B2-006-I02", "U-B2-006-I03", "U-B2-006-I04", "U-B2-006-I05", "U-B2-006-I06", "U-B2-006-I07"], "listening_tasks": ["U-B2-006-I12", "U-B2-006-I13"], "learning_outcome": "Различать процесс, целое событие и предшествующий результат в активной и медиопассивной форме", "mastery_contract": {"audio": "Не оценивается без аудио", "unaided": "Две самостоятельные реплики без модели", "observed": false, "transfer": "Все условия новой ситуации; целевая форма=2, другие критерии≥1", "retention": "D7/D14/D28 без подсказок плюс новая свободная реплика", "controlled": "≥80% целевых форм; смысловая ошибка требует повторного обучения"}, "vocabulary_items": [{"lemma": "διορθώνω", "stress": "διορθώνω", "example": "Διόρθωσα τον τίτλο.", "inflection": "διόρθωσα, έχω διορθώσει", "meaning_ru": "исправлять", "collocations": ["διορθώνω"]}, {"lemma": "διορθώνομαι", "stress": "διορθώνομαι", "example": "Το λάθος διορθώθηκε.", "inflection": "διορθώθηκα, έχει διορθωθεί", "meaning_ru": "исправляться; быть исправленным", "collocations": ["διορθώνομαι"]}, {"lemma": "ελέγχω", "stress": "ελέγχω", "example": "Έχουμε ελέγξει τις ημερομηνίες.", "inflection": "έλεγξα, έχω ελέγξει", "meaning_ru": "проверять", "collocations": ["ελέγχω"]}, {"lemma": "αποστολή", "stress": "αποστολή", "example": "Ο έλεγχος γίνεται πριν από την αποστολή.", "inflection": "η αποστολή, της αποστολής", "meaning_ru": "отправка", "collocations": ["αποστολή"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B2-006-I01"], "learning_objectives": ["Различать процесс, целое событие и предшествующий результат в активной и медиопассивной форме", "Сохранять участников и время при редактировании активного/пассивного сообщения", "Самостоятельно уточнять обязательство и возможность без превращения плана в свершившийся факт"], "microcompetency_ids": ["U-B2-006-MC01", "U-B2-006-MC02", "U-B2-006-MC03"], "primary_competencies": ["B2-G02"], "learner_data_included": false, "estimated_active_minutes": 45}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
