3177	unit	U-B2-007	3348fd063543de3051a4242b4eb3032ef7ad226de2c5e345911c69d7277599ec	core	{"unit_id": "U-B2-007", "content_hash": "3348fd063543de3051a4242b4eb3032ef7ad226de2c5e345911c69d7277599ec", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-007.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "BLOCKED_MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "NOT_REVIEWED"}, "rubrics": ["U-B2-007-RUBRIC"], "unit_id": "U-B2-007", "version": "0.1.0", "title_ru": "Сжать сообщение и сохранить факты: причастные конструкции", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Причастные конструкции помогают убрать повторение, но сокращение полезно лишь тогда, когда адресат по-прежнему понимает, кто действовал, что завершено и какие сведения являются условием. В этом уроке вы редактируете рабочую записку и устно объясняете её менее подготовленному коллеге. Не нужно заменять каждый глагол причастием: полное предложение часто яснее. Прежде чем сокращать, подчеркните участников и временные ориентиры.\\nСравните Σημειώνοντας τις αλλαγές, η Άννα ελέγχει το κείμενο и Η Άννα έλεγξε το κείμενο, έχοντας σημειώσει πρώτα τις αλλαγές. В первом образце записывание сопровождает проверку; во втором πρώτα и завершённая форма показывают предварительный этап. Неизменяемые формы не получают окончания женского рода вслед за Άννα. Рабочая опора: σημειώνω — σημειώνοντας — έχω σημειώσει — έχοντας σημειώσει; ελέγχω — ελέγχοντας — έχω ελέγξει — έχοντας ελέγξει; διαβάζω — διαβάζοντας — έχω διαβάσει — έχοντας διαβάσει. Это конкретные изучаемые цепочки, а не разрешение образовывать любую новую форму по аналогии.\\nОдна конструкция может допускать разные смысловые отношения. В нашем тексте Γνωρίζοντας τον χώρο, η Ελένη μάς ξενάγησε знание помогает понять причину выбора Елены. Однако не объявляйте, что любое -οντας означает причину или всегда одновременность. Чтобы передать намеренный смысл без угадывания, разверните конструкцию с επειδή, ενώ или αφού и проверьте контекст. При двух разумных прочтениях редактор задаёт уточняющий вопрос, а не выбирает ответ по красивой форме.\\nОсобенно внимательно следите за участником. Для продуктивных образцов этого урока у сокращённого действия и главного глагола один явный исполнитель: Διαβάζοντας τις οδηγίες, η Μαρία εντόπισε ένα λάθος. Если инструкции читала Мария, а ошибку нашёл Никос, безопасное сообщение содержит две личные формы: Ενώ η Μαρία διάβαζε τις οδηγίες, ο Νίκος εντόπισε ένα λάθος. Не сохраняйте сокращение ценой подмены факта. Это редакторская проверка наших конструкций, а не утверждение, что во всём греческом нет иных способов оформлять участников.\\nСогласуемые формы описывают предмет или состояние. Οι διορθωμένες σελίδες είναι έτοιμες: страницы исправлены; χρειάζομαι τις διορθωμένες σελίδες: тот же женский множественный, но другая роль группы. Ο διορθωμένος πίνακας, η διορθωμένη λίστα, το διορθωμένο αρχείο; των διορθωμένων αρχείων. В Μια υπάλληλος εκπαιδευμένη στη χρήση του προγράμματος θα μας βοηθήσει определение относится к сотруднице. Выберите ясный полный вариант, если читатель не знает εκπαιδευμένη: Μια υπάλληλος που έχει εκπαιδευτεί στη χρήση του προγράμματος θα μας βοηθήσει.\\nРазличайте процесс и результат на знакомой паре: η αναπτυσσόμενη περιοχή — район, который развивается; η ανεπτυγμένη περιοχή — развитый район. Это лексическая опора именно этой пары, не универсальная замена всех -όμενος на -μένος. Узнавайте также οι εργαζόμενοι: работники; форма с артиклем может обозначать людей, а не быть определением после существительного. Для неизвестной книжной формы не придумывайте значение по окончанию: проверьте словарь или попросите пояснение.\\nПри сжатии нельзя уничтожать существенную информацию. Οι αιτήσεις που εγκρίθηκαν χτες → οι εγκεκριμένες αιτήσεις не сохраняет «вчера». Можно сказать οι αιτήσεις που εγκρίθηκαν χτες или добавить отдельное предложение о времени. Не вынуждайте собеседника восстанавливать сроки, исполнителя или степень готовности из догадки. В задании, где требуется сохранить все факты, краткий вариант без срока неполон, даже если грамматика правильна.\\nПорядок самостоятельной работы: перескажите факты простыми предложениями; сократите только одно подходящее место; восстановите исходные факты из результата; затем объясните тот же текст устно без сложной формы. В новой ситуации меняются адресат и цель: сообщение о проверке документов превращается в инструкцию для организатора мероприятия. Оценка учитывает точность участников, времени и статуса, а не количество причастий. Успешное повторение готового образца с подсказкой фиксируется отдельно от независимого переноса.", "cefr_level": "B2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Έχοντας ελέγξει τα στοιχεία, η ομάδα έστειλε την αναφορά.", "Οι διορθωμένες σελίδες είναι στον φάκελο.", "Διαβάζοντας τις οδηγίες, η Μαρία εντόπισε ένα λάθος.", "Ενώ η Μαρία διάβαζε, ο Νίκος τηλεφώνησε.", "Η αναπτυσσόμενη περιοχή χρειάζεται καλύτερες συγκοινωνίες.", "Οι εργαζόμενοι ζήτησαν σαφέστερο πρόγραμμα."], "review_plan": {"days": [7, 14, 28], "item_ids": ["U-B2-007-I17", "U-B2-007-I18", "U-B2-007-I20"], "conditions": "Independent first attempt, unseen prompt before model; hints recorded separately; no mastery claim from one success"}, "source_refs": [{"anchor": "§6.2ι lines251–255", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S01", "source_id": "N405", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}, {"anchor": "§2 lines13–23,37–43", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S02", "source_id": "N-F07-PART", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}], "entry_probes": [{"prompt": "Назовите род/число γραμμένες и развёрните έχω ελέγξει в сообщение о завершённости.", "expected": "женский множественный; проверка завершена и релевантна сейчас", "remediation": "Если форма/аспект не восстановлены самостоятельно: U-B1-011 и U-B2-006, затем новая проба с διορθωμένες и έχω διαβάσει. Не пропускать к сжатию при неясном участнике."}], "active_recall": ["U-B2-007-I08", "U-B2-007-I09"], "prerequisites": ["B1-G12", "B2-G02"], "reading_tasks": ["U-B2-007-I10", "U-B2-007-I11"], "transfer_task": "U-B2-007-I16", "writing_tasks": ["U-B2-007-I14"], "competency_ids": ["B2-G04"], "coverage_claim": "PARTIAL_MACRO; textual evidence prepared, independent/human/source-completeness/acoustic review outstanding", "speaking_tasks": ["U-B2-007-I15"], "errors_taxonomy": ["ASR_UNCERTAIN", "COMPREHENSION", "CONTENT_OMISSION", "GENDER_AGREEMENT", "MORPHOLOGY_CASE", "ORTHOGRAPHY_ACCENT", "PRAGMATICS_REGISTER", "SPEECH_INTELLIGIBILITY", "SYNTAX", "VERB_ASPECT", "VOCAB_SELECTION"], "guided_practice": ["U-B2-007-I02", "U-B2-007-I03", "U-B2-007-I04", "U-B2-007-I05", "U-B2-007-I06", "U-B2-007-I07", "U-B2-007-I19"], "listening_tasks": ["U-B2-007-I12", "U-B2-007-I13"], "learning_outcome": "Самостоятельно редактировать и объяснять сообщение с уместными причастными конструкциями", "mastery_contract": {"delayed": "D7 and D28 new contexts; delayed independent production required", "observed": false, "controlled": "Target relations and forms correct in unseen controlled set; meaning-changing agent/time/scope error requires remediation", "independent": "Writing and oral transfer meet every task-specific content criterion without model; record assistance"}, "vocabulary_items": [{"lemma": "διορθωμένος", "stress": "διορθωμένος", "example": "Χρειάζομαι τις διορθωμένες σελίδες.", "inflection": "-η, -ο; διορθωμένες", "meaning_ru": "исправленный", "collocations": ["διορθωμένες σελίδες"]}, {"lemma": "εκπαιδευμένος", "stress": "εκπαιδευμένος", "example": "Η υπάλληλος είναι εκπαιδευμένη στη χρήση του προγράμματος.", "inflection": "-η, -ο", "meaning_ru": "обученный", "collocations": ["εκπαιδευμένη υπάλληλος"]}, {"lemma": "αναπτυσσόμενος", "stress": "αναπτυσσόμενος", "example": "Η περιοχή είναι αναπτυσσόμενη.", "inflection": "-η, -ο", "meaning_ru": "развивающийся", "collocations": ["αναπτυσσόμενη περιοχή"]}, {"lemma": "ανεπτυγμένος", "stress": "ανεπτυγμένος", "example": "Η ανεπτυγμένη περιοχή έχει πολλές υπηρεσίες.", "inflection": "-η, -ο", "meaning_ru": "развитый", "collocations": ["ανεπτυγμένη περιοχή"]}, {"lemma": "εκκρεμώ", "stress": "εκκρεμώ", "example": "Η άδεια χρήσης εκκρεμεί.", "inflection": "εκκρεμεί; εκκρεμούν", "meaning_ru": "оставаться нерешённым", "collocations": ["εκκρεμεί η άδεια"]}, {"lemma": "η λεζάντα", "stress": "η λεζάντα", "example": "Η λεζάντα αναφέρει λάθος ημερομηνία.", "inflection": "οι λεζάντες", "meaning_ru": "подпись к изображению", "collocations": ["διορθώνω τη λεζάντα"]}], "diagnostic_item_ids": ["U-B2-007-I01"], "learning_objectives": ["Различать сопутствующее действие, предварительное завершение и согласуемое состояние", "Сохранять участника, время и существенное ограничение при сжатии и развёртывании", "Самостоятельно редактировать и объяснять сообщение с уместными причастными конструкциями"], "microcompetency_ids": ["U-B2-007-MC01", "U-B2-007-MC02", "U-B2-007-MC03"], "primary_competencies": ["B2-G04"], "learner_data_included": false, "prerequisite_unit_map": [{"unit_id": "U-B1-011", "competency_id": "B1-G12"}, {"unit_id": "U-B2-006", "competency_id": "B2-G02"}], "estimated_active_minutes": 90}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3178	unit	U-B2-008	8a4bbe6dbd1ff2aa170d5c2f66021410fd934115e7dfab8f9ecae330c70552f9	core	{"unit_id": "U-B2-008", "content_hash": "8a4bbe6dbd1ff2aa170d5c2f66021410fd934115e7dfab8f9ecae330c70552f9", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-008.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "BLOCKED_MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "NOT_REVIEWED"}, "rubrics": ["U-B2-008-RUBRIC"], "unit_id": "U-B2-008", "version": "0.1.0", "title_ru": "Кто именно и что сообщил: сложные относительные и изъяснительные связи", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "В этом уроке вы редактируете сообщение, в котором важно отделить, о ком идёт речь, от того, что человек утверждает или просит. Сначала восстановите две простые фразы. Η επιτροπή ανακοίνωσε κάτι. Το εργαστήριο θα γίνει διαδικτυακά. Объединение Η επιτροπή ανακοίνωσε ότι το εργαστήριο θα γίνει διαδικτυακά передаёт содержание объявления. В Η επιτροπή που οργάνωσε το εργαστήριο ανακοίνωσε την αλλαγή часть с που помогает определить комиссию. Одинаковое соседство двух глаголов ещё не означает одинаковую функцию зависимой части.\\nДля изученных сообщений говорим ανακοίνωσε ότι, εξήγησε πως, πιστεύει ότι. Отрицание внутри такого сообщения: Εξήγησε ότι δεν συμφωνεί. Просьба или требование оформляется иначе: Ζήτησε να μην αλλάξουμε την ημερομηνία. Первое передаёт позицию человека, второе — желаемое действие адресатов. Не заменяйте ότι на να механически: Η Μαρία είπε ότι θα στείλει το αρχείο сообщает о её будущем действии; Η Μαρία ζήτησε να στείλουμε το αρχείο просит нас его отправить. Проверяйте лицо и время, а не только союз.\\nОтносительное που не меняет формы: ο οδηγός που μίλησε, η επισκέπτρια που μίλησε, τα παιδιά που μίλησαν. Если рядом несколько возможных существительных, одного που может оказаться мало для ясности. Тогда назовите участника заново или используйте подходящую форму ο οποίος. Согласование по роду и числу связано с определяемым существительным; падеж — с ролью внутри относительной части. Η συνεργάτιδα με την οποία μίλησα: με требует винительного. Η συνεργάτιδα της οποίας η πρόταση εγκρίθηκε: της οποίας выражает принадлежность предложения сотруднице. Опора для практики: ο οποίος / τον οποίο / του οποίου; η οποία / την οποία / της οποίας; οι οποίοι / τους οποίους / των οποίων. Не нужно выбирать книжную форму, если повтор имени понятнее адресату.\\nПунктуация помогает показать, определяем ли мы нужную группу или добавляем пояснение. В заданном контексте «из десяти участников только четверо отправили анкету» предложение Οι συμμετέχοντες που έστειλαν τη φόρμα θα λάβουν απάντηση выделяет этих четверых. Если уже известно, что все четверо участников отправили анкету, можно добавить информацию: Οι τέσσερις συμμετέχοντες, οι οποίοι έστειλαν τη φόρμα χτες, θα λάβουν απάντηση. Нельзя из одних запятых без контекста выводить неизвестные численность или факты. При редактировании сначала решите, что именно автор хочет сообщить.\\nРазличайте ότι и ό,τι: Μου είπε ότι χρειάζεται βοήθεια — содержание слов; Πάρε ό,τι χρειάζεσαι — возьми всё, что нужно. Запятая внутри ό,τι не отделяет самостоятельное предложение. Проверка через οτιδήποτε помогает именно этому значению: Πάρε οτιδήποτε χρειάζεσαι. Не подменяйте им союз сообщения. В прямом или косвенном вопросе о месте используется πού: Ρώτησε πού θα συναντηθούμε. В Ο χώρος που επιλέξαμε είναι κοντά που связывает описание с местом, но не задаёт вопрос «где?».\\nПеред отправкой сложного текста проверьте четыре вещи: каждого участника можно назвать; содержание сообщения не стало приказом; ограничение группы сохранено; факты не добавлены ради красивой связи. При устном объяснении допустимо разделить длинную конструкцию на короткие. Самостоятельная речь проверяется в новой ситуации, а не по воспроизведению модели. На D7 и D28 вы снова выбираете отношения и восстанавливаете участников без таблицы. Если для ясности нужна подсказка, запишите помощь и повторите позже на другом материале.", "cefr_level": "B2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Η συντάκτρια με την οποία μίλησα έστειλε το κείμενο.", "Η ερευνήτρια της οποίας το άρθρο διαβάσαμε θα μιλήσει αύριο.", "Εξήγησε ότι δεν συμφωνεί.", "Ζήτησε να μην αλλάξουμε την ημερομηνία.", "Πάρε ό,τι χρειάζεσαι.", "Ρώτησε πού θα συναντηθούμε."], "review_plan": {"days": [7, 14, 28], "item_ids": ["U-B2-008-I17", "U-B2-008-I18", "U-B2-008-I20"], "conditions": "Independent first attempt, unseen prompt before model; hints recorded separately; no mastery claim from one success"}, "source_refs": [{"anchor": "§5.6 lines65–75", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S03", "source_id": "N410", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}, {"anchor": "§5.2α lines18–24", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S04", "source_id": "N404", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}, {"anchor": "§5.2γ lines52–55", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S05", "source_id": "N404", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}], "entry_probes": [{"prompt": "Различите που/πού в «Ο χώρος που επιλέξαμε» и «Ρώτησε πού θα πάμε». Передайте «Η Άννα είπε: Θα έρθω» от третьего лица.", "expected": "относительная связь / вопрос о месте; Η Άννα είπε ότι θα έρθει", "remediation": "Если связи или лицо меняют смысл: U-B1-012 (относительные) и U-B1-003 (передача речи), затем новая входная проба до сложных вложений."}], "active_recall": ["U-B2-008-I08", "U-B2-008-I09"], "prerequisites": ["B1-G08", "B1-G09"], "reading_tasks": ["U-B2-008-I10", "U-B2-008-I11"], "transfer_task": "U-B2-008-I16", "writing_tasks": ["U-B2-008-I14"], "competency_ids": ["B2-G08"], "coverage_claim": "PARTIAL_MACRO; textual evidence prepared, independent/human/source-completeness/acoustic review outstanding", "speaking_tasks": ["U-B2-008-I15"], "errors_taxonomy": ["ASR_UNCERTAIN", "COMPREHENSION", "CONTENT_OMISSION", "MORPHOLOGY_CASE", "ORTHOGRAPHY_ACCENT", "PRAGMATICS_REGISTER", "SPEECH_INTELLIGIBILITY", "SYNTAX"], "guided_practice": ["U-B2-008-I02", "U-B2-008-I03", "U-B2-008-I04", "U-B2-008-I05", "U-B2-008-I06", "U-B2-008-I07", "U-B2-008-I19"], "listening_tasks": ["U-B2-008-I12", "U-B2-008-I13"], "learning_outcome": "Самостоятельно передавать сложное сообщение с ограничениями и уточнениями", "mastery_contract": {"delayed": "D7 and D28 new contexts; delayed independent production required", "observed": false, "controlled": "Target relations and forms correct in unseen controlled set; meaning-changing agent/time/scope error requires remediation", "independent": "Writing and oral transfer meet every task-specific content criterion without model; record assistance"}, "vocabulary_items": [{"lemma": "η συνεργάτιδα", "stress": "η συνεργάτιδα", "example": "Η συνεργάτιδα με την οποία μίλησα θα έρθει.", "inflection": "οι συνεργάτιδες", "meaning_ru": "сотрудница", "collocations": ["συνεργάζομαι με τη συνεργάτιδα"]}, {"lemma": "επιβεβαιώνω", "stress": "επιβεβαιώνω", "example": "Δεν έχει επιβεβαιωθεί η ώρα.", "inflection": "επιβεβαίωσα; έχω επιβεβαιώσει", "meaning_ru": "подтверждать", "collocations": ["επιβεβαιώνω τη συμμετοχή"]}, {"lemma": "η εκδοχή", "stress": "η εκδοχή", "example": "Κυκλοφορούν δύο εκδοχές της ανακοίνωσης.", "inflection": "οι εκδοχές", "meaning_ru": "версия", "collocations": ["διαφορετικές εκδοχές"]}, {"lemma": "ο σύνδεσμος", "stress": "ο σύνδεσμος", "example": "Θα λάβετε τον σύνδεσμο με μήνυμα.", "inflection": "οι σύνδεσμοι", "meaning_ru": "ссылка", "collocations": ["λαμβάνω τον σύνδεσμο"]}, {"lemma": "η γραμματεία", "stress": "η γραμματεία", "example": "Ρωτήστε τη γραμματεία για την ώρα.", "inflection": "οι γραμματείες", "meaning_ru": "секретариат", "collocations": ["επικοινωνώ με τη γραμματεία"]}, {"lemma": "η διευκρίνιση", "stress": "η διευκρίνιση", "example": "Χρειάζομαι μια διευκρίνιση για τη συμμετοχή.", "inflection": "οι διευκρινίσεις", "meaning_ru": "уточнение", "collocations": ["ζητώ διευκρίνιση"]}], "diagnostic_item_ids": ["U-B2-008-I01"], "learning_objectives": ["Различать определение участника, содержание сообщения и просьбу", "Выбирать форму относительного местоимения и сохранять объём группы без двусмысленности", "Самостоятельно передавать сложное сообщение с ограничениями и уточнениями"], "microcompetency_ids": ["U-B2-008-MC01", "U-B2-008-MC02", "U-B2-008-MC03"], "primary_competencies": ["B2-G08"], "learner_data_included": false, "prerequisite_unit_map": [{"unit_id": "U-B1-012", "competency_id": "B1-G08"}, {"unit_id": "U-B1-003", "competency_id": "B1-G09"}], "estimated_active_minutes": 90}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
