905	source_claim	CP08-INHERITED-U-A2-003-I04-01	c2869701d1b65e0f1c8b299d9dc214f138466e131af0e8b5b3f677b930f0215c	\N	{"record": {"claim": "Уровневая тема; не дословный источник авторских фраз", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A2-003-I04-01", "item_ids": ["U-A2-003-I04"], "source_id": "V201", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A2-003-I04.json", "sha256": "1782eb4c00b8b16e05e90753964a12ad066f6f33419474be2a7bfa37f8d47105"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "V201 PDF7–8", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}}, "claim_id": "CP08-INHERITED-U-A2-003-I04-01", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3179	unit	U-B2-009	6c87220834732a101e328fac7eaf615aba1cb33cdc4d3782fa95b846e987a920	core	{"unit_id": "U-B2-009", "content_hash": "6c87220834732a101e328fac7eaf615aba1cb33cdc4d3782fa95b846e987a920", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-009.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY"}, "rubrics": ["U-B2-009-RUBRIC"], "unit_id": "U-B2-009", "version": "0.1.0", "title_ru": "Производные, сложные слова и лексико-грамматическая сочетаемость", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Словообразование помогает понять новое слово, но не заменяет проверки значения. Начинайте с контекста: какого элемента не хватает — лица, действия, качества, предмета? В «Η οργάνωση της εκδήλωσης απαιτεί χρόνο» требуется название процесса, а в «Η οργανώτρια απάντησε στις ερωτήσεις» — действующее лицо. Общий корень не делает слова взаимозаменяемыми. Сначала определите синтаксическое место, затем смысл и только потом выбирайте форму.\\nРазличайте образование слова и его изменение. В οργανώνω → οργάνωση создаётся другое слово и меняется часть речи; οργάνωση → οργανώσεις — формы одного существительного. В сложном слове соединяются две основы: βιβλιοπωλείο связано с книгой и продажей, но нельзя переводить любой набор основ буквально. Некоторые сочетания обозначают закреплённые понятия. Соединительный гласный, написание и ударение нужно проверять по конкретному слову; универсальное правило «соедини и поставь ударение» не работает.\\nСемья слов полезна как сеть функций: υπεύθυνος — ответственный человек или признак; υπευθυνότητα — качество ответственности. После «με μεγάλη» в нашей фразе подходит существительное υπευθυνότητα, а перед множественным существительным εθελοντές — согласованное прилагательное υπεύθυνοι. Окончание производного слова не освобождает от обычного согласования. При выборе ответа перечитайте всё предложение, включая артикль, предлог и число.\\nОтрицательные и повторные значения тоже зависят от слова. επαναχρησιμοποιώ означает использовать снова, а не просто переработать материал. В сообщении о повторном использовании бутылки не заменяйте его автоматически на ανακυκλώνω. Словарь учим вместе с ситуацией: αναλαμβάνω ευθύνη, παίρνω μέτρα, υποβάλλω αίτηση. Буквальный перевод русского глагола может дать неестественное сочетание, даже если каждое отдельное слово существует.\\nРабочий алгоритм: прочитайте контекст → назовите требуемый смысл → определите часть речи → образуйте или выберите слово → проверьте форму и ударение → проверьте сочетаемость. Если неизвестно само слово, используйте описательное выражение и пометьте необходимость проверки, а не изобретайте производное. В продуктивной части важно донести предложение адресату, а не вставить как можно больше длинных слов. Предварительно нужны B1-G13 и B1-V02; диагностическое задание проверяет различение действия и лица. Ошибка возвращает к этим предпосылкам. Самостоятельное освоение проверяем редактированием и новым объявлением; D7/D28 требуют новых контекстов без списка готовых слов.", "cefr_level": "B2", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Η οργάνωση της γιορτής χρειάζεται χρόνο.", "Η οργανώτρια υποδέχτηκε τους επισκέπτες.", "Οι εθελοντές ανέλαβαν την ευθύνη της ενημέρωσης.", "Πρέπει να πάρουμε μέτρα για τη μείωση των απορριμμάτων."], "review_plan": {"D7": ["U-B2-009-I12"], "D28": ["U-B2-009-I13"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-B2-009-I12", "U-B2-009-I13"]}, "source_refs": [{"anchor": "§2.2–2.3 word families, derivation, compounds and lexical meaning", "source_id": "CP07-B1-S01", "checked_on": "2026-10-22", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "active_recall": ["U-B2-009-I09", "U-B2-009-I10"], "prerequisites": ["B1-G13", "B1-V02"], "reading_tasks": ["U-B2-009-I08"], "transfer_task": "U-B2-009-I11", "writing_tasks": ["U-B2-009-I09", "U-B2-009-I11", "U-B2-009-I12"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-009-I01", "U-B2-009-I02", "U-B2-009-I03", "U-B2-009-I04", "U-B2-009-I12"], "objective": "Различать образование и изменение слова и выбирать часть речи"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-009-I05", "U-B2-009-I06", "U-B2-009-I07", "U-B2-009-I08"], "objective": "Проверять форму и сочетаемость в контексте"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-009-I09", "U-B2-009-I10", "U-B2-009-I11", "U-B2-009-I13"], "objective": "Самостоятельно применить лексику в сообщении и переносе"}], "competency_ids": ["B2-G10"], "speaking_tasks": ["U-B2-009-I10", "U-B2-009-I13"], "entry_probe_ids": ["U-B2-009-I01"], "errors_taxonomy": ["COLLOCATION", "COMPREHENSION"], "guided_practice": ["U-B2-009-I02", "U-B2-009-I03", "U-B2-009-I04", "U-B2-009-I05", "U-B2-009-I06", "U-B2-009-I07", "U-B2-009-I08"], "listening_tasks": [], "modality_status": "AUDIO_PENDING", "vocabulary_items": [{"lemma": "η οργάνωση", "stress": "η οργάνωση", "example": "Η οργάνωση της έκθεσης άρχισε.", "inflection": "της οργάνωσης; οι οργανώσεις", "collocations": ["οργάνωση εκδήλωσης"]}, {"lemma": "η υπευθυνότητα", "stress": "η υπευθυνότητα", "example": "Χειρίστηκε το ζήτημα με υπευθυνότητα.", "inflection": "της υπευθυνότητας", "collocations": ["με υπευθυνότητα"]}, {"lemma": "επαναχρησιμοποιώ", "stress": "επαναχρησιμοποιώ", "example": "Επαναχρησιμοποιώ το ίδιο δοχείο.", "inflection": "επαναχρησιμοποίησα", "collocations": ["επαναχρησιμοποιώ συσκευασίες"]}], "learning_objectives": ["Различать образование и изменение слова и выбирать часть речи", "Проверять форму и сочетаемость в контексте", "Самостоятельно применить лексику в сообщении и переносе"], "prerequisite_policy": "Diagnose before instruction; failure routes to primary unit(s) from96 register. Authored prerequisite is not evidence of learner mastery. Retry with fresh example.", "primary_competencies": ["B2-G10"], "estimated_active_minutes": 85}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3180	unit	U-B2-010	d365a668d10368b4d23b3278dc8e79abce35e0b3334d257b962a29a46dfd02da	core	{"unit_id": "U-B2-010", "content_hash": "d365a668d10368b4d23b3278dc8e79abce35e0b3334d257b962a29a46dfd02da", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-010.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY", "readiness12_review": "GreekOS_QA_Reports/readiness12/TARGETED_REVIEW.json"}, "rubrics": ["U-B2-010-RUBRIC"], "unit_id": "U-B2-010", "version": "0.2.0", "title_ru": "Общество, среда, медиа, экономика повседневности, культура", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Η κοινωνία, το περιβάλλον, η ενημέρωση και ο πολιτισμός связаны в реальных обсуждениях. Цель урока — объяснить общественную инициативу точно, назвать выигрыш и издержки, отделить обещание от результата. Тематические слова учите через отношения: η συμμετοχή των κατοίκων, η πρόσβαση στον χώρο, η μείωση των απορριμμάτων, η κάλυψη των εξόδων. Изолированный перевод не показывает, какой предлог и какое зависимое слово нужны.\\nСначала различайте факт, мнение, план и предположение. «Η ομάδα ανακοίνωσε μια δοκιμή» сообщает о действии в авторском тексте. «Η δοκιμή θα λύσει όλα τα προβλήματα» — сильное предсказание, для которого нужны доказательства. Слова προτείνει, υποστηρίζει, εκτιμά, σύμφωνα με позволяют назвать владельца утверждения. Не превращайте чужое мнение в установленный факт при пересказе. Число участников само по себе не доказывает доступность для всех.\\nВ экономике повседневности полезно разделять τιμή, κόστος, έξοδα, δωρεά. Цена для посетителя может быть нулевой, хотя у организатора остаются расходы. Добровольная поддержка не равна обязательному взносу. В экологическом контексте διαχωρισμός απορριμμάτων, ανακύκλωση и επαναχρησιμοποίηση обозначают связанные, но разные действия. Если текст говорит только о ремонте вещей, не приписывайте ему измеренное сокращение загрязнения.\\nСредства массовой информации могут сжимать содержание до заголовка. Сравнивайте масштаб обещания в заголовке с оговорками основного текста: οριστικά против δοκιμαστικά, όλοι против ορισμένοι. Наша задача не объявить источник плохим по одному слову, а показать конкретное расхождение и предложить точный заголовок. В письменном ответе соединяйте позицию, основание и ограничение: «Η πρόταση θα μπορούσε να βοηθήσει, εφόσον…». Условие делает аргумент проверяемым.\\nПри обсуждении культуры учитывайте разные интересы: доступность помещения, время, шум, добровольный вклад. Не приписывайте жителям стереотипы по возрасту или происхождению. Назовите, кому полезна мера и кто может столкнуться с трудностью. Сложность B2 возникает из сопоставления и ограничения выводов, а не из обязательного использования редких слов. Предварительно повторите B1-V01. Затем прочитайте вымышленную историю, создайте собственную аргументацию и перенесите её на новую инициативу. Этот урок начинает широкую тематическую область; для полного B2-V01 понадобятся дополнительные контексты, поэтому один текст не означает исчерпывающего покрытия.\\nДополнительный перенос: сравнивая тарифы, различайте πάγιο (фиксированная плата), χρέωση ανά χρήση (за использование) и συνολικό κόστος. «Συμφέρει αν…» требует назвать условие. В экологическом сообщении уменьшение общего расхода ещё не устанавливает причину: проверьте сопоставимость периодов. В культурном архиве разделяйте личную память, редакторскую атрибуцию и проверенный факт; согласие участвовать не следует автоматически трактовать как согласие на публикацию. Новые задания проверяют экономический выбор, экологическое сообщение, культурное участие и доступность, а не запоминание одной истории.", "cefr_level": "B2", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Η δωρεά είναι προαιρετική.", "Η πρόσβαση στον χώρο πρέπει να είναι εύκολη.", "Σύμφωνα με την ομάδα, η δοκιμή θα διαρκέσει έναν μήνα.", "Η προσέλευση αυξήθηκε, αλλά δεν γνωρίζουμε ακόμη τα συνολικά έξοδα."], "review_plan": {"D7": ["U-B2-010-I11", "U-B2-010-I19"], "D28": ["U-B2-010-I12", "U-B2-010-I20"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-B2-010-I11", "U-B2-010-I12", "U-B2-010-I19", "U-B2-010-I20"]}, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-22", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "active_recall": ["U-B2-010-I09", "U-B2-010-I14", "U-B2-010-I18"], "prerequisites": ["B1-V01"], "reading_tasks": ["U-B2-010-I02", "U-B2-010-I03", "U-B2-010-I04", "U-B2-010-I05", "U-B2-010-I13", "U-B2-010-I15"], "transfer_task": "U-B2-010-I10", "writing_tasks": ["U-B2-010-I06", "U-B2-010-I08", "U-B2-010-I10", "U-B2-010-I11", "U-B2-010-I14", "U-B2-010-I17", "U-B2-010-I19"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-010-I01", "U-B2-010-I04", "U-B2-010-I06", "U-B2-010-I07", "U-B2-010-I08", "U-B2-010-I11", "U-B2-010-I13", "U-B2-010-I19"], "objective": "Различать тематические понятия и утверждения разной достоверности"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-010-I02", "U-B2-010-I03", "U-B2-010-I05", "U-B2-010-I14", "U-B2-010-I15", "U-B2-010-I17"], "objective": "Извлекать интересы участников и ограничения аргумента"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-010-I09", "U-B2-010-I10", "U-B2-010-I12", "U-B2-010-I16", "U-B2-010-I18", "U-B2-010-I20"], "objective": "Самостоятельно обсуждать общественную инициативу"}], "competency_ids": ["B2-V01"], "speaking_tasks": ["U-B2-010-I09", "U-B2-010-I12", "U-B2-010-I16", "U-B2-010-I18", "U-B2-010-I20"], "entry_probe_ids": ["U-B2-010-I01"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION"], "guided_practice": ["U-B2-010-I02", "U-B2-010-I03", "U-B2-010-I04", "U-B2-010-I05", "U-B2-010-I06", "U-B2-010-I07", "U-B2-010-I08", "U-B2-010-I13", "U-B2-010-I15", "U-B2-010-I17"], "listening_tasks": [], "modality_status": "AUDIO_PENDING", "vocabulary_items": [{"lemma": "η συμμετοχή", "stress": "η συμμετοχή", "example": "Η συμμετοχή είναι δωρεάν.", "inflection": "της συμμετοχής", "collocations": ["συμμετοχή σε εκδήλωση"]}, {"lemma": "η πρόσβαση", "stress": "η πρόσβαση", "example": "Η πρόσβαση γίνεται από την πλαϊνή είσοδο.", "inflection": "της πρόσβασης", "collocations": ["πρόσβαση στον χώρο"]}, {"lemma": "τα έξοδα", "stress": "τα έξοδα", "example": "Οι δωρεές καλύπτουν τα έξοδα.", "inflection": "των εξόδων", "collocations": ["κάλυψη εξόδων"]}], "learning_objectives": ["Различать тематические понятия и утверждения разной достоверности", "Извлекать интересы участников и ограничения аргумента", "Самостоятельно обсуждать общественную инициативу"], "prerequisite_policy": "Diagnose before instruction; failure routes to primary unit(s) from96 register. Authored prerequisite is not evidence of learner mastery. Retry with fresh example.", "primary_competencies": ["B2-V01"], "estimated_active_minutes": 85}}	fa1d2338-6c24-4ed