911	source_claim	CP08-INHERITED-U-A2-003-I07-01	590af0c5c80e9595fb2114d61d70142a27f639732fcbcc576aff75b6e926569b	\N	{"record": {"claim": "Уровневая тема; не дословный источник авторских фраз", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A2-003-I07-01", "item_ids": ["U-A2-003-I07"], "source_id": "V201", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A2-003-I07.json", "sha256": "b619166b84211f5cc67d5d7feb39e2f13f58cd66bd39b6810b4618dd8fce51fc"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "V201 PDF7–8", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}}, "claim_id": "CP08-INHERITED-U-A2-003-I07-01", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3181	unit	U-B2-011	ca84ffcaabe4e1d61659d1cb7b64fcb091ab6701f633a3052f9a184b0f23fe4c	core	{"unit_id": "U-B2-011", "content_hash": "ca84ffcaabe4e1d61659d1cb7b64fcb091ab6701f633a3052f9a184b0f23fe4c", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-011.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY"}, "rubrics": ["U-B2-011-RUBRIC"], "unit_id": "U-B2-011", "version": "0.1.0", "title_ru": "Редактирование: лишние элементы, согласование, вид, связность", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Редактирование начинается со смысла и задачи текста. Сначала спросите, кто действует, когда и с каким результатом; затем проверяйте форму. Если два предложения противоречат друг другу, исправление окончаний не восстановит сообщение. Если предложение грамматично, но допускает две отсылки, не объявляйте одну интерпретацию единственно правильной — уточните автора или перепишите связь явно.\\nРаботайте несколькими проходами. Первый: факты и последовательность. Второй: сказуемое и согласование подлежащего, существительных и определений. Третий: вид и временная перспектива. Четвёртый: связки, местоименные отсылки и лишние элементы. Последний: ударения и пунктуация. Этот порядок не является обязательным для всех авторов, но помогает не потерять смысл при локальной правке.\\nРазличайте ошибку и стилистическое предпочтение. В «Οι κάτοικοι ζητά καλύτερο φωτισμό» множественное подлежащее требует ζητούν или ζητάνε. В «Νομίζω ότι πως…» дублируются средства введения одного придаточного; можно оставить ότι либо πως, поэтому задание должно принимать оба полного исправления. Не превращайте упражнение на удаление лишнего слова в угадывание любимого варианта редактора.\\nВид нельзя исправлять без контекста. «Θέλω να διαβάζω κάθε βράδυ» естественно описывает привычку. «Θέλω να διαβάσω όλο το μήνυμα πριν απαντήσω» представляет завершённое чтение одного сообщения. Оба глагола существуют. В задании должны быть указаны временные и смысловые ограничения, иначе автоматическое наказание за другой вид необоснованно. При правке учитывайте также лицо: Θέλουμε να λύσουμε, а не λύσω.\\nСвязка выражает отношение, которое должно поддерживаться содержанием. «Η αίθουσα ήταν μικρή, γι’ αυτό χωρούσαν λίγοι άνθρωποι» показывает причину и результат; «παρ’ όλα αυτά» предполагает преодолённое ожидание. Механическая замена связки на более сложную не улучшает текст. Местоимение αυτό или εκείνος может иметь неоднозначную отсылку; повтор имени иногда яснее изящного, но туманного местоимения.\\nПосле исправления прочитайте результат целиком и сравните с исходной задачей. Не добавляйте факт, которого не было: «отправлена заявка» не значит «заявка одобрена». В самостоятельном задании сохраните исходные факты и объясните две наиболее важные правки. Предпосылки — B2-G02, B2-G07, B2-G10. Урок объединяет редактирование знакомых явлений; отдельная проверка всех правил по первоисточникам остаётся необходимой. Наличие этого блока не закрывает весь редакторский навык.", "cefr_level": "B2", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Οι κάτοικοι ζητούν καλύτερο φωτισμό.", "Νομίζω ότι η πρόταση είναι χρήσιμη.", "Θέλω να διαβάσω όλο το μήνυμα πριν απαντήσω.", "Η αίτηση στάλθηκε, αλλά δεν έχει εγκριθεί ακόμη."], "review_plan": {"D7": ["U-B2-011-I11"], "D28": ["U-B2-011-I12"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-B2-011-I11", "U-B2-011-I12"]}, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-22", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "active_recall": ["U-B2-011-I08"], "prerequisites": ["B2-G02", "B2-G07", "B2-G10"], "reading_tasks": ["U-B2-011-I07"], "transfer_task": "U-B2-011-I10", "writing_tasks": ["U-B2-011-I08", "U-B2-011-I10", "U-B2-011-I11", "U-B2-011-I12"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-011-I01", "U-B2-011-I02", "U-B2-011-I06", "U-B2-011-I07", "U-B2-011-I09"], "objective": "Отличать содержательную ошибку, формальную ошибку и допустимый вариант"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-011-I03", "U-B2-011-I04", "U-B2-011-I05", "U-B2-011-I11"], "objective": "Редактировать согласование, вид и связность с сохранением смысла"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-011-I08", "U-B2-011-I10", "U-B2-011-I12"], "objective": "Самостоятельно редактировать сообщение и обосновывать правки"}], "competency_ids": ["B2-G11"], "speaking_tasks": ["U-B2-011-I09"], "entry_probe_ids": ["U-B2-011-I01"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION"], "guided_practice": ["U-B2-011-I02", "U-B2-011-I03", "U-B2-011-I04", "U-B2-011-I05", "U-B2-011-I06", "U-B2-011-I07", "U-B2-011-I09"], "listening_tasks": [], "modality_status": "AUDIO_PENDING", "vocabulary_items": [{"lemma": "η διόρθωση", "stress": "η διόρθωση", "example": "Η διόρθωση δεν αλλάζει το νόημα.", "inflection": "της διόρθωσης", "collocations": ["κάνω διόρθωση"]}, {"lemma": "η συνοχή", "stress": "η συνοχή", "example": "Οι σύνδεσμοι βοηθούν τη συνοχή.", "inflection": "της συνοχής", "collocations": ["συνοχή κειμένου"]}, {"lemma": "εγκρίνω", "stress": "εγκρίνω", "example": "Η αίτηση δεν έχει εγκριθεί.", "inflection": "ενέκρινα; έχει εγκριθεί", "collocations": ["εγκρίνω αίτηση"]}], "learning_objectives": ["Отличать содержательную ошибку, формальную ошибку и допустимый вариант", "Редактировать согласование, вид и связность с сохранением смысла", "Самостоятельно редактировать сообщение и обосновывать правки"], "prerequisite_policy": "Diagnose before instruction; failure routes to primary unit(s) from96 register. Authored prerequisite is not evidence of learner mastery. Retry with fresh example.", "primary_competencies": ["B2-G11"], "estimated_active_minutes": 85}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3182	unit	U-B2-012	0ccbe91492870858957d57f7e001fa6b9f04af6bbc9e9471bc5c8f6d54f1c9a5	core	{"unit_id": "U-B2-012", "content_hash": "0ccbe91492870858957d57f7e001fa6b9f04af6bbc9e9471bc5c8f6d54f1c9a5", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-012.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY"}, "rubrics": ["U-B2-012-RUBRIC"], "unit_id": "U-B2-012", "version": "0.1.0", "title_ru": "Развёрнутая стандартная речь обычного темпа", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "В развёрнутой речи держите в памяти не все слова, а структуру аргумента: цель → вариант → основание → ограничение → решение. До прослушивания прочитайте задание и определите, что потребуется: общий тезис, конкретная дата, условие или позиция говорящего. Это подготовка к слушанию, а не право заранее читать транскрипт. Первое прослушивание используйте для структуры, второе — для проверки деталей. Для учебной практики число повторов фиксируется как помощь; оно не должно незаметно повышать оценку самостоятельности.\\nВ нашем сообщении о мастерской автор сначала отказывается от чрезмерного обещания, затем описывает пробную организацию. Слова αρχικά, ύστερα, αυτό δεν σημαίνει, εφόσον, διαφορετικά, αν όχι связывают события и границы утверждений. Услышав первое предложенное расписание, не записывайте его как окончательное: последующая поправка может изменить ответ. Отрицание и ограничение важнее знакомого существительного рядом.\\nРазделяйте факт, цель и критерий будущего решения. «Θα ζητάμε σχόλια» — план сбора обратной связи. «Το πρόγραμμα είναι επιτυχημένο» было бы уже выводом; в тексте он пока не сделан. Намерение уменьшить отходы не доказывает измеренный эффект. Если говорящий сообщает, что данных пока нет, правильная заметка сохраняет неизвестность.\\nЗаписывайте кратко: кто/что/когда/условие. Не пытайтесь транскрибировать каждое предложение. Для исключения полезна явная пометка «όχι ηλεκτρικές συσκευές». Для условного решения используйте собственное сокращение, но при развёртывании ответа восстановите связь. После слушания сравните заметки с вопросом: не подменили ли вы причину переноса времени общим описанием проекта?\\nЕсли пропущено незнакомое слово, продолжайте слушать до смыслового завершения. Используйте повтор, противопоставление и пример. При этом контекст не разрешает выдумать число или запрет. Укажите пробел и запросите повтор. В реальном общении можно уточнить: «Αν κατάλαβα σωστά…». В экзаменационном режиме доступные повторы задаёт конкретная инструкция, а не этот учебный урок.\\nЗаписи должны звучать в естественном стандартном темпе, с живыми паузами, без искусственного выделения ответов. Умышленный шум не добавляется до проверки чистого мастера. Предпосылки — B1-L01/B2-V01. Последующее устное резюме проверяет продуктивный перенос, но не заменяет исходное слушание. Данный комплект содержит оригинальный текст и задания; до появления проверенных файлов все акустические результаты остаются AUDIO_PENDING.", "cefr_level": "B2", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Αρχικά σκεφτήκαμε το Σάββατο, αλλά επιλέξαμε την Τετάρτη.", "Η δήλωση δεν αποτελεί εγγύηση επισκευής.", "Δεν έχουμε ακόμη αρκετά στοιχεία.", "Αν η δοκιμή βοηθήσει, θα προτείνουμε τη συνέχισή της."], "review_plan": {"D7": ["U-B2-012-I11"], "D28": ["U-B2-012-I12"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-B2-012-I11", "U-B2-012-I12"]}, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-22", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "active_recall": ["U-B2-012-I09"], "prerequisites": ["B1-L01", "B2-V01"], "reading_tasks": [], "transfer_task": "U-B2-012-I10", "writing_tasks": ["U-B2-012-I10"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-012-I01", "U-B2-012-I02", "U-B2-012-I03"], "objective": "Понимать структуру развёрнутого сообщения и исправленные детали"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-012-I04", "U-B2-012-I05", "U-B2-012-I06", "U-B2-012-I07", "U-B2-012-I08", "U-B2-012-I11"], "objective": "Извлекать условия, основания и пределы выводов"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-012-I09", "U-B2-012-I10", "U-B2-012-I12"], "objective": "Использовать услышанное в самостоятельном резюме и решении"}], "competency_ids": ["B2-L01"], "speaking_tasks": ["U-B2-012-I09"], "entry_probe_ids": ["U-B2-012-I01"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION"], "guided_practice": ["U-B2-012-I02", "U-B2-012-I03", "U-B2-012-I04", "U-B2-012-I05", "U-B2-012-I06", "U-B2-012-I07", "U-B2-012-I08"], "listening_tasks": ["U-B2-012-I01", "U-B2-012-I02", "U-B2-012-I03", "U-B2-012-I04", "U-B2-012-I05", "U-B2-012-I06", "U-B2-012-I07", "U-B2-012-I08", "U-B2-012-I11", "U-B2-012-I12"], "modality_status": "AUDIO_PENDING", "vocabulary_items": [{"lemma": "η δοκιμή", "stress": "η δοκιμή", "example": "Η δοκιμή θα διαρκέσει τρεις μήνες.", "inflection": "της δοκιμής; οι δοκιμές", "collocations": ["δοκιμή τριών μηνών"]}, {"lemma": "η προϋπόθεση", "stress": "η προϋπόθεση", "example": "Η δωρεά δεν είναι προϋπόθεση συμμετοχής.", "inflection": "της προϋπόθεσης", "collocations": ["προϋπόθεση συμμετοχής"]}, {"lemma": "ο εξοπλισμός", "stress": "ο εξοπλισμός", "example": "Η αγορά εξοπλισμού θα γίνει αργότερα.", "inflection": "του εξοπλισμού", "collocations": ["αγορά εξοπλισμού"]}], "learning_objectives": ["Понимать структуру развёрнутого сообщения и исправленные детали", "Извлекать условия, основания и пределы выводов", "Использовать услышанное в самостоятельном резюме и решении"], "prerequisite_policy": "Diagnose before instruction; failure routes to primary unit(s) from96 register. Authored prerequisite is not evidence of learner mastery. Retry with fresh example.", "primary_competencies": ["B2-L01"], "estimated_active_minutes": 85}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
