917	source_claim	CP08-INHERITED-U-A2-003-I10-01	15ebf2e29c26d73ad4f904decf25ddac3a9b72fb4e8ed2d9d1dfd52dc25f81b7	\N	{"record": {"claim": "Уровневая тема; не дословный источник авторских фраз", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A2-003-I10-01", "item_ids": ["U-A2-003-I10"], "source_id": "V201", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A2-003-I10.json", "sha256": "a79056b0b3f0ec1204a921a49214a38a0697d5d501c79c7d123562b38098c716"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "V201 PDF7–8", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}}, "claim_id": "CP08-INHERITED-U-A2-003-I10-01", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3183	unit	U-B2-013	3d498756e5e8d16cf5d188b7cfdc54e97ff81a120ebf34845da6f79633e719e9	core	{"unit_id": "U-B2-013", "content_hash": "3d498756e5e8d16cf5d188b7cfdc54e97ff81a120ebf34845da6f79633e719e9", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-013.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY"}, "rubrics": ["U-B2-013-RUBRIC"], "unit_id": "U-B2-013", "version": "0.1.0", "title_ru": "Развёрнутое объяснение и сопоставление преимуществ/недостатков", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Развёрнутое объяснение строится вокруг вопроса адресата. Если нужно выбрать место для курса, нельзя ограничиться описанием красивого здания. Назовите критерии: доступность, стоимость, тишина, время. Затем сравните варианты по одинаковым критериям. Это делает решение прозрачным. Не сравнивайте цену одного места только с атмосферой другого, забыв остальные условия.\\nНачните с краткой позиции или рамки: «Υπάρχουν δύο λύσεις και θα τις συγκρίνω ως προς…». Для каждого преимущества объясните, кому и почему оно полезно. «Είναι κοντά» становится аргументом, когда добавлено «οπότε οι συμμετέχοντες μπορούν να έρθουν χωρίς αυτοκίνητο». Недостаток тоже требует следствия: ограниченные часы могут исключить работающих вечером.\\nСлова από τη μία/από την άλλη помогают противопоставлению, ενώ — сравнению, ωστόσο — оговорке, επομένως — выводу. Выбирайте связку по смыслу. Наличие большого количества связок не спасает противоречивую логику. «Η αίθουσα είναι δωρεάν, επομένως δεν υπάρχουν έξοδα» слишком сильный вывод: транспорт и оборудование могут потребовать расходов, даже если аренда нулевая.\\nОтделяйте данные карточки от своих предположений. «Σύμφωνα με τις πληροφορίες…» вводит факт; «αν χρειαστεί επιπλέον εξοπλισμός…» — условие. Если неизвестно, есть ли лифт, не называйте помещение доступным для всех. Скажите, что это нужно уточнить, и объясните, как ответ повлияет на решение. B2 допускает обоснованную условную рекомендацию вместо притворной уверенности.\\nСтруктура ответа: задача → два-три критерия → сопоставление → главный компромисс → рекомендация и условие пересмотра. Подготовьте план из ключевых слов, а не полный текст. После первого ответа партнёр меняет один параметр. Вы должны перестроить вывод, а не повторить заученную рекомендацию. Самостоятельное возражение можно начать «Καταλαβαίνω αυτό το πλεονέκτημα, ωστόσο…».\\nОценивайте содержание, связность, диапазон средств и понятность отдельно. Акцент, отличный от акцента носителя, сам по себе не ошибка. Без аудиозаписи нельзя заключить о беглости и произношении. Предварительно нужны B1-SP01 и B2-G07. Рецептивная часть проверяет качество чужого аргумента, продуктивная — собственную рекомендацию, D7/D28 — новые решения с изменёнными ограничениями.", "cefr_level": "B2", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Η πρώτη λύση είναι φθηνότερη, ενώ η δεύτερη προσφέρει περισσότερη ευελιξία.", "Το πλεονέκτημα αυτό έχει σημασία για όσους εργάζονται το πρωί.", "Δεν γνωρίζουμε ακόμη αν υπάρχει ανελκυστήρας.", "Θα επέλεγα την πρώτη λύση, εφόσον επιβεβαιωθεί η πρόσβαση."], "review_plan": {"D7": ["U-B2-013-I10"], "D28": ["U-B2-013-I11"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-B2-013-I10", "U-B2-013-I11"]}, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-22", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "active_recall": ["U-B2-013-I07"], "prerequisites": ["B1-SP01", "B2-G07"], "reading_tasks": ["U-B2-013-I03"], "transfer_task": "U-B2-013-I09", "writing_tasks": ["U-B2-013-I09"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-013-I01", "U-B2-013-I02", "U-B2-013-I04", "U-B2-013-I10"], "objective": "Сопоставлять варианты по одинаковым критериям"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-013-I03", "U-B2-013-I05", "U-B2-013-I06"], "objective": "Различать аргумент, предположение и необоснованный вывод"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-013-I07", "U-B2-013-I08", "U-B2-013-I09", "U-B2-013-I11"], "objective": "Самостоятельно обосновать и пересмотреть рекомендацию"}], "competency_ids": ["B2-SP01"], "speaking_tasks": ["U-B2-013-I01", "U-B2-013-I07", "U-B2-013-I08", "U-B2-013-I10", "U-B2-013-I11"], "entry_probe_ids": ["U-B2-013-I01"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION"], "guided_practice": ["U-B2-013-I02", "U-B2-013-I03", "U-B2-013-I04", "U-B2-013-I05", "U-B2-013-I06", "U-B2-013-I08"], "listening_tasks": [], "modality_status": "AUDIO_PENDING", "vocabulary_items": [{"lemma": "το πλεονέκτημα", "stress": "το πλεονέκτημα", "example": "Η ευελιξία είναι σημαντικό πλεονέκτημα.", "inflection": "του πλεονεκτήματος; τα πλεονεκτήματα", "collocations": ["σημαντικό πλεονέκτημα"]}, {"lemma": "το μειονέκτημα", "stress": "το μειονέκτημα", "example": "Η απόσταση είναι βασικό μειονέκτημα.", "inflection": "του μειονεκτήματος", "collocations": ["βασικό μειονέκτημα"]}, {"lemma": "η ευελιξία", "stress": "η ευελιξία", "example": "Το ωράριο προσφέρει ευελιξία.", "inflection": "της ευελιξίας", "collocations": ["μεγαλύτερη ευελιξία"]}], "learning_objectives": ["Сопоставлять варианты по одинаковым критериям", "Различать аргумент, предположение и необоснованный вывод", "Самостоятельно обосновать и пересмотреть рекомендацию"], "prerequisite_policy": "Diagnose before instruction; failure routes to primary unit(s) from96 register. Authored prerequisite is not evidence of learner mastery. Retry with fresh example.", "primary_competencies": ["B2-SP01"], "estimated_active_minutes": 85}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3184	unit	U-B2-014	056bfb4f660db4b5fe4fcb2595238ace10e7ebb884062340ae07c369b94ee161	core	{"unit_id": "U-B2-014", "content_hash": "056bfb4f660db4b5fe4fcb2595238ace10e7ebb884062340ae07c369b94ee161", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-014.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY", "readiness12_review": "GreekOS_QA_Reports/readiness12/TARGETED_REVIEW.json"}, "rubrics": ["U-B2-014-RUBRIC"], "unit_id": "U-B2-014", "version": "0.2.0", "title_ru": "Коллокации, синонимы, оттенки и устойчивые выражения", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Близкие по переводу слова не всегда подходят к одному контексту. Возможность μπορεί να αποδίδεται как δυνατότητα или ευκαιρία, но первое часто описывает способность или доступную опцию, а второе — благоприятный случай. «Δεν έχω τη δυνατότητα να πληρώσω» не означает, что человек просто упустил приятный шанс. При выборе учитывайте, что именно утверждает говорящий, а не только русское слово-подсказку.\\nКоллокация — привычное сочетание. Учите «λαμβάνω υπόψη», «θέτω έναν στόχο», «καταλήγω σε συμπέρασμα», «αντιμετωπίζω ένα πρόβλημα» как целые конструкции, замечая предлог, падеж и контекст. В живой речи можно сказать «παίρνω μια απόφαση», а в более официальном тексте — «λαμβάνω μια απόφαση». Не делайте из формального варианта единственно правильный. Словарь фиксирует и «παίρνω υπόψη», и «λαμβάνω υπόψη». Нельзя объявлять первый вариант ошибочным только потому, что урок выбрал второй. В упражнении на форму заданного глагола оценивается именно указанная лемма; при свободном ответе обе конструкции допустимы.\\nСлова λύση и απάντηση тоже не полностью взаимозаменяемы. Решение практической проблемы и ответ на вопрос — разные связи. Иногда одна ситуация допускает оба слова с разным акцентом. Поэтому закрытое задание должно сужать контекст или задавать конкретную конструкцию, а открытое — принимать осмысленный вариант. Если редактор не уверен в границе, необходим словарь и экспертная проверка, а не уверенное автоматическое наказание.\\nРегистр зависит от адресата. «Θα ήθελα να σας ενημερώσω» подходит служебному письму; короткое «Να σου πω…» естественнее в дружеском разговоре. Формальная фраза не становится грубой автоматически в дружеском сообщении, но может создавать ненужную дистанцию. Оценка должна объяснять эффект, а не объявлять все нецелевые варианты грамматическими ошибками.\\nУстойчивые выражения могут быть образными. «Δεν είναι στο χέρι μου» означает, что решение не зависит от говорящего; это не сообщение о руке. Проверяйте контекст и нейтральный эквивалент. Не переносите значение на любое предложение со словом χέρι. Выражение «κρατώ τον λόγο μου» связывает речь с обещанием, а не физическим удержанием слова. Собственные задания тренируют понимание и уместное применение; они не доказывают современную частотность или региональное употребление.\\nМетод: запишите сочетание → укажите ситуацию → создайте пример → замените на нейтральную парафразу → перенесите в новое сообщение. Предпосылки — B1-V02 и B2-G10. Критерий освоения — точный смысл в самостоятельном контексте, сохранение регистра и гибкая парафраза; запоминание списка не достаточно. Данный урок вводит выборочную сеть выражений, а не исчерпывает весь B2-словарь.\\nВ новых контекстах αναβάλλω означает перенести действие на более позднее время; отмену без новой даты не следует описывать как назначенный перенос. Αυξάνομαι сообщает об увеличении величины, βελτιώνομαι — об улучшении: увеличение цены само по себе не доказывает улучшение услуги. Παίρνω τον λόγο в собрании — вступаю в обсуждение; κρατώ τον λόγο μου в контексте обещания — выполняю обещанное. Открытый ответ оценивайте по точности мысли, а не обязательному совпадению с одним выражением. Регистр проверяйте изменением адресата при сохранении одной и той же просьбы.", "cefr_level": "B2", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Πρέπει να λάβουμε υπόψη το κόστος.", "Η ομάδα έθεσε έναν σαφή στόχο.", "Καταλήξαμε στο συμπέρασμα ότι χρειάζεται περισσότερος χρόνος.", "Η τελική απόφαση δεν είναι στο χέρι μου."], "review_plan": {"D7": ["U-B2-014-I10", "U-B2-014-I17"], "D28": ["U-B2-014-I11", "U-B2-014-I18"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-B2-014-I10", "U-B2-014-I11", "U-B2-014-I17", "U-B2-014-I18"]}, "source_refs": [{"anchor": "§2.2–2.3 word families, derivation, compounds and lexical meaning", "source_id": "CP07-B1-S01", "checked_on": "2026-10-22", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "active_recall": ["U-B2-014-I08", "U-B2-014-I16"], "prerequisites": ["B1-V02", "B2-G10"], "reading_tasks": ["U-B2-014-I04", "U-B2-014-I05", "U-B2-014-I07", "U-B2-014-I12", "U-B2-014-I14"], "transfer_task": "U-B2-014-I09", "writing_tasks": ["U-B2-014-I06", "U-B2-014-I08", "U-B2-014-I10", "U-B2-014-I13", "U-B2-014-I15", "U-B2-014-I17"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-014-I01", "U-B2-014-I02", "U-B2-014-I03", "U-B2-014-I04", "U-B2-014-I12", "U-B2-014-I13"], "objective": "Различать смысловые оттенки и устойчивые сочетания"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-014-I05", "U-B2-014-I06", "U-B2-014-I07", "U-B2-014-I10", "U-B2-014-I14", "U-B2-014-I15", "U-B2-014-I17"], "objective": "Определять регистр и переносное значение по контексту"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-014-I08", "U-B2-014-I09", "U-B2-014-I11", "U-B2-014-I16", "U-B2-014-I18"], "objective": "Применять и перефразировать выражения в самостоятельной речи"}], "competency_ids": ["B2-V02"], "speaking_tasks": ["U-B2-014-I09", "U-B2-014-I11", "U-B2-014-I16", "U-B2-014-I18"], "entry_probe_ids": ["U-B2-014-I01"], "errors_taxonomy": ["COLLOCATION", "COMPREHENSION"], "guided_practice": ["U-B2-014-I02", "U-B2-014-I03", "U-B2-014-I04", "U-B2-014-I05", "U-B2-014-I06", "U-B2-014-I07", "U-B2-014-I12", "U-B2-014-I13", "U-B2-014-I14"], "listening_tasks": [], "modality_status": "AUDIO_PENDING", "vocabulary_items": [{"lemma": "λαμβάνω υπόψη", "stress": "λαμβάνω υπόψη", "example": "Λαμβάνουμε υπόψη τις ανάγκες όλων.", "inflection": "έλαβα υπόψη; να λάβω υπόψη", "collocations": ["λαμβάνω υπόψη τις ανάγκες"]}, {"lemma": "καταλήγω", "stress": "καταλήγω", "example": "Καταλήξαμε σε κοινό συμπέρασμα.", "inflection": "κατέληξα", "collocations": ["καταλήγω σε συμπέρασμα"]}, {"lemma": "κρατώ τον λόγο μου", "stress": "κρατώ τον λόγο μου", "example": "Υποσχέθηκε να βοηθήσει και κράτησε τον λόγο του.", "inflection": "κράτησα τον λόγο μου", "collocations": ["κρατώ τον λόγο μου"]}], "learning_objectives": ["Различать смысловые оттенки и устойчивые сочетания", "Определять регистр и переносное значение по контексту", "Применять и перефразировать выражения в самостоятельной речи"], "prerequisite_policy": "Diagnose before instruction; failure routes to primary unit(s) from96 register. Authored prerequisite is not evidence of l