923	source_claim	CP08-INHERITED-U-A2-003-I13-01	ec12f82e2a0359ce5cab5c25230739d2ee475a15723bcf786518f08b1b426ede	\N	{"record": {"claim": "Уровневая тема; не дословный источник авторских фраз", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A2-003-I13-01", "item_ids": ["U-A2-003-I13"], "source_id": "V201", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A2-003-I13.json", "sha256": "9385aab4b9f7b205397e6b04041c609e0e31908a9a0f703aaff6b2b1bec9fe6f"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "V201 PDF7–8", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}}, "claim_id": "CP08-INHERITED-U-A2-003-I13-01", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3185	unit	U-B2-015	db6bdc657c13b275d29cf908665449198ff9854348381ac5460aec460d9c247a	core	{"unit_id": "U-B2-015", "content_hash": "db6bdc657c13b275d29cf908665449198ff9854348381ac5460aec460d9c247a", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-015.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY"}, "rubrics": ["U-B2-015-RUBRIC"], "unit_id": "U-B2-015", "version": "0.1.0", "title_ru": "Обсуждение нескольких говорящих и извлечение заметок", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "В обсуждении нескольких людей нужно отслеживать не только содержание, но и владельца каждой позиции. Заведите мысленную или письменную схему: участник → предложение → основание → условие → дальнейшее действие. Не приписывайте человеку мнение только потому, что он первым произнёс ключевое слово: он может пересказывать чужую идею, возражать ей или соглашаться лишь частично.\\nПервое прослушивание посвятите общей задаче встречи и различиям между участниками. Во втором проверьте условия и изменение позиции. В нашем сценарии четыре голоса. У каждого своя функция в разговоре: координация, потребность в тихом месте, техническая готовность, ограниченная доступность волонтёра. Это содержание конкретного текста, а не постоянная характеристика человека. После изменения предложения один участник может поддержать то, что раньше ограничивал.\\nМаркер «συμφωνώ, αλλά…» обычно требует сохранить обе части: область согласия и возражение. «Μπορώ αύριο, αλλά όχι όλον τον μήνα» не означает полный отказ от помощи. «Δεν ξέρουμε ακόμη» означает открытый вопрос, а не доказанный отрицательный факт. Запись, потерявшая отрицание или условие, может привести к ошибочному решению даже при правильном имени.\\nОсобенно внимательно слушайте итог координатора. Итог может представлять предложение для утверждения, а не окончательное решение. Если сказано «θα στείλουμε για έγκριση», не объявляйте мероприятие подтверждённым. В заметках отдельно храните согласованные идеи, невыполненные условия и ответственных за проверку. При переносе в сообщение адресату эти категории должны остаться различимыми.\\nНе пытайтесь записать каждую реплику. Короткая запись «Πέτρος: Τρίτη, όχι πάντα → δεύτερος υπεύθυνος» сохраняет ограничение и решение. Если пропустили имя, оставьте знак вопроса и проверьте позже; не заполняйте его случайным знакомым именем. Для задания на распределение реплик проверяйте инструкцию: в одном задании участники могут повторяться, в другом нет. Наши задания оценивают фактическое содержание, а не угадывание схемы распределения.\\nДля производства требуются четыре различимых согласованных голоса, естественные переходы и паузы. Имена-метки не произносятся. В чистом учебном мастере нет перекрытия реплик; более сложную версию можно добавлять только после native QA. Предпосылки — B1-L02 и B2-L01. Без реальных файлов урок остаётся сценарием. Итоговый письменный протокол и устное объяснение проверяют перенос услышанного; они не заменяют акустическую проверку. D7/D28 используют другие обсуждения, чтобы не измерять запоминание персонажей.", "cefr_level": "B2", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Συμφωνώ με την ιδέα, αλλά όχι με το ωράριο.", "Μπορώ να βοηθήσω την Τρίτη, όχι κάθε εβδομάδα.", "Η πρόταση θα σταλεί για έγκριση.", "Δεν έχει οριστεί ακόμη ημερομηνία έναρξης."], "review_plan": {"D7": ["U-B2-015-I11"], "D28": ["U-B2-015-I12"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-B2-015-I11", "U-B2-015-I12"]}, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-22", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "active_recall": ["U-B2-015-I09"], "prerequisites": ["B1-L02", "B2-L01"], "reading_tasks": ["U-B2-015-I01"], "transfer_task": "U-B2-015-I10", "writing_tasks": ["U-B2-015-I09"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-015-I01", "U-B2-015-I02", "U-B2-015-I03", "U-B2-015-I04", "U-B2-015-I05", "U-B2-015-I11"], "objective": "Различать позиции и ограничения четырёх участников"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-015-I06", "U-B2-015-I07", "U-B2-015-I08"], "objective": "Отделять предложение, условие и окончательное решение"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-015-I09", "U-B2-015-I10", "U-B2-015-I12"], "objective": "Составлять точный протокол и использовать его для действия"}], "competency_ids": ["B2-L02"], "speaking_tasks": ["U-B2-015-I10"], "entry_probe_ids": ["U-B2-015-I01"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION"], "guided_practice": ["U-B2-015-I02", "U-B2-015-I03", "U-B2-015-I04", "U-B2-015-I05", "U-B2-015-I06", "U-B2-015-I07", "U-B2-015-I08"], "listening_tasks": ["U-B2-015-I02", "U-B2-015-I03", "U-B2-015-I04", "U-B2-015-I05", "U-B2-015-I06", "U-B2-015-I07", "U-B2-015-I08", "U-B2-015-I11", "U-B2-015-I12"], "modality_status": "AUDIO_PENDING", "vocabulary_items": [{"lemma": "η επίβλεψη", "stress": "η επίβλεψη", "example": "Δύο άτομα θα αναλάβουν την επίβλεψη.", "inflection": "της επίβλεψης", "collocations": ["αναλαμβάνω την επίβλεψη"]}, {"lemma": "η έγκριση", "stress": "η έγκριση", "example": "Περιμένουμε την έγκριση της επιτροπής.", "inflection": "της έγκρισης", "collocations": ["περιμένω έγκριση"]}, {"lemma": "ο φωτισμός", "stress": "ο φωτισμός", "example": "Ο φωτισμός χρειάζεται επισκευή.", "inflection": "του φωτισμού", "collocations": ["καλύτερος φωτισμός"]}], "learning_objectives": ["Различать позиции и ограничения четырёх участников", "Отделять предложение, условие и окончательное решение", "Составлять точный протокол и использовать его для действия"], "prerequisite_policy": "Diagnose before instruction; failure routes to primary unit(s) from96 register. Authored prerequisite is not evidence of learner mastery. Retry with fresh example.", "primary_competencies": ["B2-L02"], "estimated_active_minutes": 85}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3186	unit	U-B2-016	900926ad36027ad99a9c08ff0f5f55360cf5ab3d34d49391f22321807c67888c	core	{"unit_id": "U-B2-016", "content_hash": "900926ad36027ad99a9c08ff0f5f55360cf5ab3d34d49391f22321807c67888c", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-016.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY", "readiness12_review": "GreekOS_QA_Reports/readiness12/TARGETED_REVIEW.json"}, "rubrics": ["U-B2-016-RUBRIC"], "unit_id": "U-B2-016", "version": "0.2.0", "title_ru": "Понятность, просодия и самокоррекция в спонтанной речи", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "На B2 цель произношения — устойчивая понятность развёрнутой спонтанной речи. Это не требование скрыть происхождение говорящего или точно имитировать одного носителя. Слушатель должен без чрезмерных усилий понять позицию, условия, числа и исправления. Для оценки нужны звуковая запись, понятный контекст и конкретные наблюдения; текстовая транскрипция показывает лишь часть содержания.\\nПодготовьте смысловые группы, а не паузу после каждого слова. В длинной рекомендации сначала обозначьте позицию, затем причину и оговорку. Пауза перед «ωστόσο» может помочь переходу, но её длительность не задаётся универсальным числом секунд. Важнее, чтобы пауза не разрушала тесную связь внутри группы и не заставляла слушателя ошибочно считать мысль законченной. Естественные колебания допустимы.\\nФразовое выделение помогает различать старую и новую информацию. Если исправляете количество, выделите новое число; если меняете ответственного — лицо. Словесное ударение при этом сохраняется. Одно и то же предложение допускает разные реализации в зависимости от контекста. Поэтому в оценке нельзя ставить единственный правильный график высоты голоса на все случаи или считать громкость прямой мерой уверенности.\\nСамокоррекция должна улучшать сообщение. «Θα ξεκινήσουμε στις έξι… συγγνώμη, στις επτά» ясно устанавливает новое время. Но бесконечное возвращение к каждому окончанию может затруднить понимание. Исправляйте прежде всего ошибку, меняющую смысл или отношения. После исправления продолжайте мысль. Можно кратко восстановить ключевую группу целиком, чтобы слушатель не гадал, какая версия действует.\\nРазделяйте языковую трудность и технический сбой. Если ASR записал неверное число, это ещё не доказательство, что ученик его произнёс неверно. Прослушайте запись, сравните с намерением и при неуверенности запросите повтор. Не снижайте балл за произношение по одному распознанному тексту. При обрыве записи ставится отсутствие достаточных данных, а не ноль за навык.\\nЦикл самостоятельной работы: короткий план → запись без чтения → слепое извлечение ключевых фактов слушателем → сопоставление → одна целевая переработка → новый контекст. Не превращайте улучшенную повторную запись в доказательство полностью спонтанного первого выполнения. Фиксируйте помощь и число попыток. Предпосылки — B1-P01 и B2-SP01. В D7/D28 меняется задача, сохраняются условия понятности и самопоправки. Пока отсутствуют записи и независимые решения слушателя, акустическая компетенция AUDIO_PENDING; авторские инструкции не закрывают её.\\nДля рецептивной проверки просодии подготовлены I11–I15. До реальной записи они не предъявляются ученику. В I12 одинаковый текст намеренно записывается с разным фразовым выделением; без слышимого контраста ответы по транскрипту недопустимы. Самокоррекция не обязательна, если ошибка не возникла: обновление плана после новой информации фиксируется отдельно от обнаружения собственной ошибки. Сохраняйте первую самостоятельную попытку и все последующие подсказки раздельно.", "cefr_level": "B2", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Θα ξεκινήσουμε στις έξι… συγγνώμη, στις επτά.", "Προτιμώ τη δεύτερη λύση, επειδή εξυπηρετεί περισσότερους ανθρώπους.", "Το ποσό είναι δεκαπέντε ευρώ, όχι πενήντα.", "Αν αλλάξει το ωράριο, θα χρειαστεί να επανεξετάσουμε την πρόταση."], "review_plan": {"D7": ["U-B2-016-I09", "U-B2-016-I14"], "D28": ["U-B2-016-I10", "U-B2-016-I15"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-B2-016-I09", "U-B2-016-I10", "U-B2-016-I14", "U-B2-016-I15"]}, "source_refs": [{"anchor": "§2.3 suprasegmentals, stress, pause and rhythm; §2.2 connected speech", "source_id": "CP08-PHON", "checked_on": "2026-10-22", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "active_recall": ["U-B2-016-I07"], "prerequisites": ["B1-P01", "B2-SP01"], "reading_tasks": [], "transfer_task": "U-B2-016-I08", "writing_tasks": ["U-B2-016-I03"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-016-I01", "U-B2-016-I03", "U-B2-016-I04", "U-B2-016-I07", "U-B2-016-I09", "U-B2-016-I11", "U-B2-016-I12", "U-B2-016-I13", "U-B2-016-I14", "U-B2-016-I15"], "objective": "Сохранять понятность смысловых групп и фразового выделения"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-016-I05", "U-B2-016-I08", "U-B2-016-I10", "U-B2-016-I16"], "objective": "Самостоятельно исправлять значимую ошибку без разрушения речи"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-016-I02", "U-B2-016-I06"], "objective": "Различать акустическое доказательство, ASR-ошибку и отсутствие данных"}], "competency_ids": ["B2-P01"], "speaking_tasks": ["U-B2-016-I01", "U-B2-016-I04", "U-B2-016-I05", "U-B2-016-I07", "U-B2-016-I08", "U-B2-016-I09", "U-B2-016-I10", "U-B2-016-I16"], "entry_probe_ids": ["U-B2-016-I01"], "errors_taxonomy": ["PRONUNCIATION_CANDIDATE"], "guided_practice": ["U-B2-016-I02", "U-B2-016-I03", "U-B2-016-I04", "U-B2-016-I05", "U-B2-016-I06", "U-B2-016-I11", "U-B2-016-I12", "U-B2-016-I13"], "listening_tasks": ["U-B2-016-I11", "U-B2-016-I12", "U-B2-016-I13", "U-B2-016-I14", "U-B2-016-I15"], "modality_status": "AUDIO_PENDING", "vocabulary_items": [{"lemma": "η καταληπτότητα", "stress": "η καταληπτότητα", "example": "Η καταληπτότητα είναι βασικό κριτήριο.", "inflection": "της καταληπτότητας", "collocations": ["καταληπτότητα της ομιλίας"]}, {"lemma": "η αυτοδιόρθωση", "stress": "η αυτοδιόρθωση", "example": "Η αυτοδιόρθωση έκανε το μήνυμα σαφέστερο.", "inflection": "της αυτοδιόρθωσης", "collocations": ["σαφής αυτοδιόρθωση"]}, {"lemma": "επανεξετάζω", "stress": "επανεξετάζω", "example": "Θα επανεξετάσουμε την πρόταση.", "inflection": "επανεξέτασα", "collocations": ["επανεξετάζω την πρόταση"]}], "learning_objectives": ["Сохранять понятность смысловых групп и фразового выделения", "Самостоятельно исправлять значимую ошибку без разрушения речи", "Различать акустическое доказательство, ASR-ошибку и отсутствие данных"], "prerequisite_policy": "Diagnose before instruction; failure routes to primary unit(s) from96 register. Authored prerequisite is not evidence of learner mastery. Retry with fresh example.", "primary_competencies": ["B2-P01"], "estimated_active_minutes": 85}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
