929	source_claim	CP08-INHERITED-U-A2-003-I16-01	565c99265928149eae673897afb35fedcc9a2b137ac58ca73c7b2e6c50d5d269	\N	{"record": {"claim": "Уровневая тема; не дословный источник авторских фраз", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A2-003-I16-01", "item_ids": ["U-A2-003-I16"], "source_id": "V201", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A2-003-I16.json", "sha256": "b71349c395e2ec37aa880c40ab17d75a71b3606cb317e0029fdd82de8974718d"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "V201 PDF7–8", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}}, "claim_id": "CP08-INHERITED-U-A2-003-I16-01", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3187	unit	U-B2-017	de7ca1a0e0f24bb8de9e898a597aa3343833a44dacfd5fa4aa04beb30d203b3d	core	{"unit_id": "U-B2-017", "content_hash": "de7ca1a0e0f24bb8de9e898a597aa3343833a44dacfd5fa4aa04beb30d203b3d", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-017.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY"}, "rubrics": ["U-B2-017-RUBRIC"], "unit_id": "U-B2-017", "version": "0.1.0", "title_ru": "Статьи, аргументированные тексты, подробные инструкции", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Чтение B2 — это выбор информации под задачу, а не перевод каждого слова. До чтения определите жанр, адресата и вопрос, ради которого читаете. В статье отделяйте тезис автора от мнения, которое он пересказывает ради возражения. В инструкции ищите действие, условие, исключение и момент, после которого действие разрешено. Эти жанры требуют разных способов проверки: для статьи — аргумент и его границы, для инструкции — выполнимую последовательность.\\n\\nПервый проход по статье даёт карту абзацев. Запишите по несколько слов: исходное возражение → предлагаемая польза → ограничения → условия испытания → вывод. Затем вернитесь к точным формулировкам. Όμως и ωστόσο сигнализируют поворот, γι’ αυτό связывает предложение с обоснованием, αν задаёт условие. Они помогают читать, но не заменяют содержания: слово όμως не означает автоматически отрицательного отношения автора ко всему проекту. В нашем тексте автор поддерживает эксперимент, а не безусловное расширение часов. Формулировки μπορεί и θα μπορούσε выражают возможность, а не установленный результат.\\n\\nРазличайте три статуса вывода: прямо сказано; обоснованно следует; не установлено. Если текст не сообщает размер расходов, нельзя выбирать «расходы невелики». Отсутствие доказательства пользы не доказывает бесполезность. В задании с вариантами проверьте каждый отвлекающий ответ: не усилил ли он квантор до «все», не превратил ли условие в гарантию, не приписал ли автору чужое мнение? Для короткого ответа передайте смысл своими словами и укажите опорный абзац. Цитата без ответа на вопрос недостаточна.\\n\\nНезнакомое слово сначала рассмотрите в контексте: кто действует, что противопоставляется, какой результат обсуждается? Предположение нужно проверить ближайшим предложением. Не выводите юридические или фактические правила из учебной ситуации: библиотека и её регламент здесь вымышлены. В инструкции различайте αίτημα, επιβεβαίωση и έγκριση. Поданное заявление не равно подтверждённой записи. Превратите длинную инструкцию в алгоритм с условиями: если ответа нет, связаться; не дублировать заявку. Сохраняйте отрицания и сроки.\\n\\nВ финале чтение превращается в самостоятельное действие: объясните другому человеку, что ему делать, обоснуйте рекомендацию и назовите предел уверенности. Сначала выполняйте задания без ключа; после обратной связи найдите фразу, из-за которой возникла ошибка, и исправьте собственный вывод. Доказательство освоения — верная интерпретация нового текста и перенос инструкции в новую ситуацию. Повторение через семь и двадцать восемь дней использует новые материалы. Высокий результат на знакомой статье не означает освоения всего чтения B2.", "cefr_level": "B2", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Ο συντάκτης υποστηρίζει τη δοκιμή, όχι την άνευ όρων εφαρμογή.", "Το ότι δεν υπάρχουν στοιχεία δεν αποδεικνύει ότι δεν υπάρχει ανάγκη.", "Αν δεν λάβετε επιβεβαίωση, επικοινωνήστε με τη γραμματεία.", "Η προσέλευση αποτελεί ένδειξη, όχι από μόνη της επαρκή απόδειξη."], "review_plan": {"D7": ["U-B2-017-I11"], "D28": ["U-B2-017-I12"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-B2-017-I11", "U-B2-017-I12"]}, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "active_recall": ["U-B2-017-I08", "U-B2-017-I09"], "prerequisites": ["B1-R01", "B2-G08"], "reading_tasks": ["U-B2-017-I01", "U-B2-017-I02", "U-B2-017-I03", "U-B2-017-I04", "U-B2-017-I05", "U-B2-017-I06", "U-B2-017-I11"], "transfer_task": "U-B2-017-I10", "writing_tasks": ["U-B2-017-I07", "U-B2-017-I08", "U-B2-017-I10", "U-B2-017-I12"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-017-I01", "U-B2-017-I02", "U-B2-017-I03", "U-B2-017-I04", "U-B2-017-I05", "U-B2-017-I11"], "objective": "Различать позицию, аргумент, ограничение и недоказанный вывод"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-017-I06", "U-B2-017-I07", "U-B2-017-I12"], "objective": "Извлекать условие и последовательность из подробной инструкции"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-017-I08", "U-B2-017-I09", "U-B2-017-I10"], "objective": "Самостоятельно обосновывать действие по новому письменному источнику"}], "competency_ids": ["B2-R01"], "speaking_tasks": ["U-B2-017-I09"], "entry_probe_ids": ["U-B2-017-I01"], "errors_taxonomy": ["ARGUMENT_SOURCE_BOUNDARY_CANDIDATE", "ATTRIBUTION_CANDIDATE", "AUTHOR_STANCE_CANDIDATE", "CONDITION_LOSS_CANDIDATE", "EVIDENCE_SELECTION_CANDIDATE", "INSTRUCTION_TRANSFER_CANDIDATE", "PROCEDURE_SEQUENCE_CANDIDATE", "PROCEDURE_STATE_CANDIDATE", "UNCERTAINTY_LOSS_CANDIDATE", "UNSUPPORTED_INFERENCE_CANDIDATE"], "guided_practice": ["U-B2-017-I02", "U-B2-017-I03", "U-B2-017-I04", "U-B2-017-I05", "U-B2-017-I06", "U-B2-017-I07"], "listening_tasks": [], "modality_status": "AUDIO_PENDING", "vocabulary_items": [{"lemma": "η πρόσβαση", "stress": "η πρόσβαση", "example": "Η πρόσβαση δεν εξαρτάται μόνο από το ωράριο.", "inflection": "της πρόσβασης", "collocations": "ισότιμη πρόσβαση"}, {"lemma": "η προϋπόθεση", "stress": "η προϋπόθεση", "example": "Η δοκιμή προτείνεται υπό συγκεκριμένες προϋποθέσεις.", "inflection": "οι προϋποθέσεις", "collocations": "υπό προϋποθέσεις"}, {"lemma": "τεκμηριώνω", "stress": "τεκμηριώνω", "example": "Ο αριθμός επισκέψεων δεν τεκμηριώνει κάθε ισχυρισμό.", "inflection": "τεκμηρίωσα", "collocations": "τεκμηριώνω έναν ισχυρισμό"}, {"lemma": "η επιβεβαίωση", "stress": "η επιβεβαίωση", "example": "Περιμένουμε γραπτή επιβεβαίωση.", "inflection": "της επιβεβαίωσης", "collocations": "γραπτή επιβεβαίωση"}], "learning_objectives": ["Различать позицию, аргумент, ограничение и недоказанный вывод", "Извлекать условие и последовательность из подробной инструкции", "Самостоятельно обосновывать действие по новому письменному источнику"], "prerequisite_policy": "Diagnose before instruction; failure routes to primary unit(s) from96 register. Authored prerequisite is not evidence of learner mastery. Retry with fresh example.", "primary_competencies": ["B2-R01"], "estimated_active_minutes": 85}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3188	unit	U-B2-018	1ac13b09075808d9df9083e4cc33da560f109e758c9a1ea16d2f4d8d9e1d0357	core	{"unit_id": "U-B2-018", "content_hash": "1ac13b09075808d9df9083e4cc33da560f109e758c9a1ea16d2f4d8d9e1d0357", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-018.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY"}, "rubrics": ["U-B2-018-RUBRIC"], "unit_id": "U-B2-018", "version": "0.1.0", "title_ru": "Спонтанная дискуссия, аргументация и согласование решения", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Дискуссия B2 требует не длинного монолога, а движения к совместному решению. Участник должен ясно предложить вариант, обосновать его, понять возражение и изменить предложение при новых ограничениях. Согласие не обязательно; обязательно показать, с чем именно вы согласны или спорите. Начните с общего критерия: Τι θέλουμε να πετύχουμε; Затем сравнивайте варианты по одинаковым основаниям — стоимости, доступности, срокам, участию. Если один вариант оценивается по цене, а другой только по привлекательности, сравнение неполно.\\n\\nПолезная структура реплики: позиция → причина → следствие → приглашение к ответу. Προτείνω να… επειδή… Έτσι… Πώς σας φαίνεται; Это опора для планирования, а не обязательная формула каждого хода. Чтобы действительно ответить собеседнику, кратко переформулируйте его мысль: Αν καταλαβαίνω σωστά, σε ανησυχεί… Не приписывайте мотивов. Собеседник может подтвердить или исправить понимание. После этого предложите конкретную модификацию, а не повторяйте прежний аргумент громче.\\n\\nОчередность реплик поддерживается короткими средствами: Να προσθέσω κάτι; Να ολοκληρώσω πρώτα τη σκέψη μου; Δεν σε άκουσα στο τελευταίο σημείο. Вежливость зависит от отношений и интонации, поэтому одна письменная фраза не гарантирует успешного взаимодействия. Не засчитывайте акустическую уверенность по тексту. При затруднении попросите перефразировать, назовите непонятный элемент и подтвердите восстановленный смысл. Переспрос без уточнения может не решить проблему.\\n\\nКомпромисс сохраняет ограничения обеих сторон. Ας κάνουμε Χ, αρκεί να… отличается от безусловного согласия. Ούτε η δωρεάν λύση είναι απαραίτητα προσβάσιμη показывает, что бесплатность и доступность — разные критерии. Указывайте, какие данные ещё нужны: Αν επιβεβαιωθεί η πρόσβαση, θα… Не превращайте предположение в факт. В конце проговорите решение, исполнителя, срок и незакрытое условие. Формула συμφωνούμε не должна скрывать сохраняющееся несогласие.\\n\\nПрактика проводится в два этапа: сначала подготовьте доводы, затем отвечайте на неизвестное заранее возражение без чтения модели. Самостоятельно можно записать начальную реплику, открыть карточку неожиданного ограничения и записать продолжение с одной попытки. Это тренировка реакции, но не доказательство спонтанного двустороннего общения: для этого нужен партнёр или работающий голосовой сценарий. Оценка различает содержание решения, взаимодействие, связность и язык; задержка сети и ошибка распознавания не являются ошибкой ученика. Для переноса смените тему и адресата, а через D7/D28 вновь договоритесь при других ограничениях.", "cefr_level": "B2", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Αν καταλαβαίνω σωστά, σε ανησυχεί η πρόσβαση.", "Θα προτιμούσα τη δεύτερη λύση, αρκεί να μην αυξηθεί το κόστος.", "Να ολοκληρώσω τη σκέψη μου και μετά να σε ακούσω;", "Συμφωνούμε στην ημερομηνία, αλλά εκκρεμεί η επιβεβαίωση του χώρου."], "review_plan": {"D7": ["U-B2-018-I11"], "D28": ["U-B2-018-I12"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-B2-018-I11", "U-B2-018-I12"]}, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "active_recall": ["U-B2-018-I07", "U-B2-018-I08"], "prerequisites": ["B1-SI01", "B2-G07", "B2-V02"], "reading_tasks": ["U-B2-018-I02"], "transfer_task": "U-B2-018-I10", "writing_tasks": ["U-B2-018-I03", "U-B2-018-I04", "U-B2-018-I09", "U-B2-018-I12"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-018-I03", "U-B2-018-I07"], "objective": "Аргументировать и сравнивать варианты по общим критериям"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-018-I01", "U-B2-018-I02", "U-B2-018-I04", "U-B2-018-I06", "U-B2-018-I08", "U-B2-018-I11"], "objective": "Реагировать на возражение, уточнять и восстанавливать коммуникацию"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-018-I05", "U-B2-018-I09", "U-B2-018-I10", "U-B2-018-I12"], "objective": "Согласовать проверяемое совместное решение с условиями"}], "competency_ids": ["B2-SI01"], "speaking_tasks": ["U-B2-018-I01", "U-B2-018-I06", "U-B2-018-I07", "U-B2-018-I08", "U-B2-018-I10", "U-B2-018-I11"], "entry_probe_ids": ["U-B2-018-I01"], "errors_taxonomy": ["AGREEMENT_SCOPE_CANDIDATE", "ARGUMENT_DEVELOPMENT_CANDIDATE", "COMPARISON_CRITERIA_CANDIDATE", "CONDITION_FORM_CANDIDATE", "DECISION_JUSTIFICATION_CANDIDATE", "IGNORED_CONSTRAINT_CANDIDATE", "MISATTRIBUTED_POSITION_CANDIDATE", "NEGOTIATION_TRANSFER_CANDIDATE", "PERSONAL_ATTACK_CANDIDATE", "REGISTER_PRIVACY_CANDIDATE", "RESPONSE_RELEVANCE_CANDIDATE"], "guided_practice": ["U-B2-018-I02", "U-B2-018-I03", "U-B2-018-I04", "U-B2-018-I05", "U-B2-018-I06", "U-B2-018-I09"], "listening_tasks": [], "modality_status": "AUDIO_PENDING", "vocabulary_items": [{"lemma": "η αντίρρηση", "stress": "η αντίρρηση", "example": "Η αντίρρησή σου αφορά το κόστος;", "inflection": "οι αντιρρήσεις", "collocations": "διατυπώνω αντίρρηση"}, {"lemma": "ο συμβιβασμός", "stress": "ο συμβιβασμός", "example": "Καταλήξαμε σε έναν πρακτικό συμβιβασμό.", "inflection": "οι συμβιβασμοί", "collocations": "καταλήγω σε συμβιβασμό"}, {"lemma": "εκκρεμεί", "stress": "εκκρεμεί", "example": "Εκκρεμεί η έγκριση της ημερομηνίας.", "inflection": "εκκρεμούν", "collocations": "εκκρεμεί η έγκριση"}, {"lemma": "το κριτήριο", "stress": "το κριτήριο", "example": "Ας ορίσουμε κοινά κριτήρια.", "inflection": "τα κριτήρια", "collocations": "κοινά κριτήρια"}], "learning_objectives": ["Аргументировать и сравнивать варианты по общим критериям", "Реагировать на возражение, уточнять и восстанавливать коммуникацию", "Согласовать проверяемое совместное решение с условиями"], "prerequisite_policy": "Diagnose before instruction; failure routes to primary unit(s) from96 register. Authored prerequisite is not evidence of learner mastery. Retry with fresh example.", "primary_competencies": ["B2-SI01"], "estimated_active_minutes": 85}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
