935	source_claim	CP08-INHERITED-U-A2-004-I03-01	52523eb21f43fb450ff30280aae84c77c5dabd82c41bd95cfb1515d3decd4079	\N	{"record": {"claim": "Уровневая тема; не дословный источник авторских фраз", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A2-004-I03-01", "item_ids": ["U-A2-004-I03"], "source_id": "V201", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A2-004-I03.json", "sha256": "6913c914ab5395ea7a696a5cdf169559043b26f2c748a05a581f54c5f61fd797"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "V201 PDF7–8", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}}, "claim_id": "CP08-INHERITED-U-A2-004-I03-01", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3189	unit	U-B2-019	ee4cb170eb15b08059b0e0c8c10aad1ad00448fba910752ea1add45257c3f54d	core	{"unit_id": "U-B2-019", "content_hash": "ee4cb170eb15b08059b0e0c8c10aad1ad00448fba910752ea1add45257c3f54d", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-019.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY"}, "rubrics": ["U-B2-019-RUBRIC"], "unit_id": "U-B2-019", "version": "0.1.0", "title_ru": "Порядок слов, тематизация, эмфаза и выбор регистра", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Порядок слов в греческом допускает вариативность, но не случайную перестановку. Чтобы выбрать форму, спросите: о чём уже идёт речь и какую новую информацию нужно сообщить? Тема — отправная точка сообщения; фокус — выделяемая новая или противопоставленная часть. Это полезное рабочее различие, а не механическая метка для каждого первого или последнего слова. Позиция, контекст и интонация действуют совместно. Школьная грамматика подтверждает зависимость порядка от выделяемого элемента, новизны и интонации; более тонкие анализы отдельных конструкций требуют отдельной проверки.\\n\\nВ нейтральном сообщении Η επιτροπή ενέκρινε την πρόταση действующее лицо предшествует действию и объекту. Если предложение уже обсуждается, можно сказать Την πρόταση την ενέκρινε η επιτροπή. Начальная именная группа задаёт предмет разговора, а короткое την отсылает к ней как к объекту. Согласуйте род, число и падеж: Τις αλλαγές τις συζητήσαμε. Δεν τις εγκρίναμε ακόμη. Нельзя менять объект на именительный только потому, что он стал первым. При этом отсутствие удвоения не делает любое предложение автоматически неправильным: выделенный объект может иметь другое информационное прочтение. Поэтому задания здесь оценивают заданный контекст, а не догму «объект впереди — всегда местоимение».\\n\\nСравните ответы на разные вопросы: Ποιος έστειλε το μήνυμα; — Η Άννα το έστειλε. Τι έστειλε η Άννα; — Έστειλε το μήνυμα, όχι την αίτηση. Во втором ответе контраст касается объекта. Не добавляйте εγώ в каждое предложение по русской привычке: личное окончание часто достаточно, а выраженное местоимение может противопоставлять участников. Но наличие εγώ не является само по себе ошибкой или грубостью. Оценивайте, помогает ли оно задаче.\\n\\nПерестановка меняет не только удобство чтения. В высказываниях Μόνο η Άννα άλλαξε την ημερομηνία и Η Άννα άλλαξε μόνο την ημερομηνία слово μόνο ограничивает разные элементы. Проверяйте, кого или что исключает фраза. Не пытайтесь определить все интонационные различия по письму: выделение заглавными буквами — редакторская подсказка, а не звуковое доказательство. Для восприятия фокуса нужен реальный голос и независимая проверка.\\n\\nРегистр выбирается по адресату и цели. В дружеском сообщении Το σχέδιο το είδα, αλλά θέλω να το συζητήσουμε звучит иначе, чем Το σχέδιο εξετάστηκε· απαιτούνται περαιτέρω διευκρινίσεις. В официальной форме безличность не должна скрывать ответственного: назовите, кто уточнит и к какому сроку. Ни разговорная тематизация, ни пассив сами по себе не запрещены в определённом жанре; важны ясность и уместность. При редактировании сначала сохраните участников, действие, время, отрицание и область ограничения, затем изменяйте порядок и лексику. Освоение проверяется новым контекстом, самостоятельным объяснением изменения смысла и отсроченным переносом.", "cefr_level": "B2", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Την αίτηση την έστειλα χθες.", "Τις προτάσεις τις εξετάσαμε, αλλά δεν αποφασίσαμε ακόμη.", "Μόνο ο Νίκος απάντησε, όχι οι υπόλοιποι.", "Ο Νίκος διόρθωσε μόνο την ημερομηνία, όχι το ποσό.", "Εγώ συμφωνώ με τον στόχο, αλλά όχι με τον τρόπο."], "review_plan": {"D7": ["U-B2-019-I11"], "D28": ["U-B2-019-I12"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-B2-019-I11", "U-B2-019-I12"]}, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}, {"anchor": "§1.3 lines19,29–30", "source_id": "CP10-WORDORDER", "checked_on": "2026-10-24", "claim_scope": "Bounded word-order and pronoun principles only"}], "active_recall": ["U-B2-019-I08", "U-B2-019-I09"], "prerequisites": ["B2-G01", "B1-PR01"], "reading_tasks": [], "transfer_task": "U-B2-019-I10", "writing_tasks": ["U-B2-019-I07", "U-B2-019-I08", "U-B2-019-I10", "U-B2-019-I12"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-019-I01", "U-B2-019-I04", "U-B2-019-I06"], "objective": "Сохранять синтаксические роли при тематизации и местоименном повторе"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-019-I02", "U-B2-019-I03", "U-B2-019-I05", "U-B2-019-I09", "U-B2-019-I11"], "objective": "Различать контраст и область действия μόνο по контексту"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-019-I07", "U-B2-019-I08", "U-B2-