3190	unit	U-B2-020	fcfdc867619c36037888c76001ff56ea0ed01ef82cd9f763106a79db66b4b565	core	{"unit_id": "U-B2-020", "content_hash": "fcfdc867619c36037888c76001ff56ea0ed01ef82cd9f763106a79db66b4b565", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-020.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY"}, "rubrics": ["U-B2-020-RUBRIC"], "unit_id": "U-B2-020", "version": "0.1.0", "title_ru": "Синтез нескольких источников и объяснение для конкретного адресата", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Διαμεσολάβηση, или медиация, помогает адресату использовать информацию, которую ему трудно обработать самому. На B2 это не механическое сокращение каждой статьи по очереди. Нужно собрать релевантные сведения из нескольких источников, сравнить их, указать противоречия и ограничения, затем объяснить результат понятным для конкретного человека способом. Перевод каждого предложения не гарантирует, что адресат сможет принять решение.\\n\\nСначала сформулируйте запрос адресата. Руководителю нужны условия решения, ресурсы и риски; новому волонтёру — обязанности, предел ответственности и следующий шаг. Один и тот же набор источников поэтому приводит к разным текстам. Составьте рабочую карту: факт → источник и дата → степень определённости → значение для адресата. Записи карты не являются готовым ответом, но позволяют проверить, не добавили ли вы собственную догадку как чужой факт.\\n\\nСопоставляйте единицы измерения и выборки. В нашем учебном материале 80 посещений не равны 80 людям, а 14 из 20 добровольных ответов не означают предпочтение 70% всего района. Отсутствие возрастных данных нельзя восполнить воображением. Числа, относящиеся к разным группам, нельзя автоматически складывать. Если неизвестно пересечение групп, так и скажите. Эти ограничения важны не только для статистики, но и для честного повседневного объяснения.\\n\\nСвязь между источниками должна быть видна: Σύμφωνα με την αναφορά… Ωστόσο, το μήνυμα της συντονίστριας διευκρινίζει… Από τα διαθέσιμα στοιχεία δεν προκύπτει… Формулировки δηλώνει, εκτιμά, προτείνει не взаимозаменяемы. Не превращайте условное финансирование в полученные деньги, предварительную готовность волонтёров — в обязательство на год. Более поздний документ не автоматически отменяет ранний: установите, относится ли он к тому же вопросу и явно ли меняет условие.\\n\\nХорошая медиация добавляет структуру, а не выдуманные сведения. Можно рекомендовать месячную пробу, но отделите рекомендацию от источников: Με βάση αυτά, προτείνω… Если сведения противоречат друг другу, назовите расхождение и запросите подтверждение; не выбирайте удобную версию молча. Для неспециалиста замените термин объяснением, сохранив ограничение. Упрощение не должно уничтожать существенную оговорку.\\n\\nЗавершайте сообщением, которое ведёт к действию: что можно решить сейчас, что нужно проверить и кто должен это подтвердить. После написания выполните обратную проверку: подчеркните каждое число и утверждение, найдите его источник; собственные предложения пометьте отдельно. Рубрика оценивает верность, отбор под адресата, связи между материалами, ограничения и понятность греческого. Неполный язык и искажённый факт — разные проблемы. Перенос и D7/D28 используют новые источники; память о готовом резюме не считается медиацией нового материала.", "cefr_level": "B2", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Οι επισκέψεις δεν αντιστοιχούν απαραίτητα σε διαφορετικούς επισκέπτες.", "Η χρηματοδότηση προβλέπεται υπό όρους, δεν έχει ακόμη εγκριθεί.", "Για τους εθελοντές προέχει να γνωρίζουν τα όρια της ευθύνης τους.", "Με βάση τα διαθέσιμα στοιχεία, προτείνω μια περιορισμένη δοκιμή."], "review_plan": {"D7": ["U-B2-020-I10"], "D28": ["U-B2-020-I11"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-B2-020-I10", "U-B2-020-I11"]}, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "active_recall": ["U-B2-020-I07", "U-B2-020-I08"], "prerequisites": ["B1-M01", "B2-R01", "B2-L02"], "reading_tasks": ["U-B2-020-I01", "U-B2-020-I02", "U-B2-020-I03", "U-B2-020-I04"], "transfer_task": "U-B2-020-I09", "writing_tasks": ["U-B2-020-I05", "U-B2-020-I06", "U-B2-020-I07", "U-B2-020-I09", "U-B2-020-I10", "U-B2-020-I11"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-020-I01", "U-B2-020-I02", "U-B2-020-I03", "U-B2-020-I04", "U-B2-020-I10"], "objective": "Сопоставлять несколько источников без искажения чисел и степени уверенности"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-020-I06", "U-B2-020-I08"], "objective": "Отбирать и объяснять информацию для определённого адресата"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-020-I05", "U-B2-020-I07", "U-B2-020-I09", "U-B2-020-I11"], "objective": "Разделять факты, выводы и рекомендации с проверяемыми ссылками"}], "competency_ids": ["B2-M01"], "speaking_tasks": ["U-B2-020-I08"], "entry_probe_ids": ["U-B2-020-I01"], "errors_taxonomy": ["APPROVAL_STATUS_CANDIDATE", "AUDIENCE_SELECTION_CANDIDATE", "FACT_RECOMMENDATION_BOUNDARY_CANDIDATE", "SAMPLE_GENERALIZATION_CANDIDATE", "SOURCE_ATTRIBUTION_CANDIDATE", "SOURCE_SYNTHESIS_CANDIDATE", "STALE_INFORMATION_CANDIDATE", "TIME_INFERENCE_CANDIDATE", "UNCERTAINTY_LOSS_CANDIDATE", "UNIT_OF_COUNT_CANDIDATE", "UNSUPPORTED_FACT_CANDIDATE"], "guided_practice": ["U-B2-020-I02", "U-B2-020-I03", "U-B2-020-I04", "U-B2-020-I05", "U-B2-020-I06"], "listening_tasks": [], "modality_status": "AUDIO_PENDING", "vocabulary_items": [{"lemma": "η δέσμευση", "stress": "η δέσμευση", "example": "Δεν υπάρχει δέσμευση για όλο το έτος.", "inflection": "οι δεσμεύσεις", "collocations": "αναλαμβάνω δέσμευση"}, {"lemma": "το δείγμα", "stress": "το δείγμα", "example": "Το δείγμα δεν αντιπροσωπεύει όλους τους κατοίκους.", "inflection": "τα δείγματα", "collocations": "περιορισμένο δείγμα"}, {"lemma": "προκύπτει", "stress": "προκύπτει", "example": "Αυτό δεν προκύπτει από τα στοιχεία.", "inflection": "προέκυψε", "collocations": "προκύπτει από στοιχεία"}, {"lemma": "η αρμοδιότητα", "stress": "η αρμοδιότητα", "example": "Χρειάζονται σαφή όρια αρμοδιότητας.", "inflection": "οι αρμοδιότητες", "collocations": "όρια αρμοδιότητας"}], "learning_objectives": ["Сопоставлять несколько источников без искажения чисел и степени уверенности", "Отбирать и объяснять информацию для определённого адресата", "Разделять факты, выводы и рекомендации с проверяемыми ссылками"], "prerequisite_policy": "Diagnose before instruction; failure routes to primary unit(s) from96 register. Authored prerequisite is not evidence of learner mastery. Retry with fresh example.", "primary_competencies": ["B2-M01"], "estimated_active_minutes": 85}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
