941	source_claim	CP08-INHERITED-U-A2-004-I06-01	1b4d298ac280965bf6609f64aee83fb5778f4ccf55d40f1425cce66a08450604	\N	{"record": {"claim": "Уровневая тема; не дословный источник авторских фраз", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A2-004-I06-01", "item_ids": ["U-A2-004-I06"], "source_id": "V201", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A2-004-I06.json", "sha256": "eae833a0271195b1fdbbc745b394d75d269dfe39e622169df3c2945f7b6cc83f"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "V201 PDF7–8", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}}, "claim_id": "CP08-INHERITED-U-A2-004-I06-01", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3191	unit	U-B2-021	fd75315ab8c3adaf50231805ee4f613406dc48a383c856c19a628ff8c5862fac	core	{"unit_id": "U-B2-021", "content_hash": "fd75315ab8c3adaf50231805ee4f613406dc48a383c856c19a628ff8c5862fac", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-021.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY"}, "rubrics": ["U-B2-021-RUBRIC"], "unit_id": "U-B2-021", "version": "0.1.1", "title_ru": "Вежливое несогласие, дистанция, смена регистра и переговоры", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Вежливое несогласие сохраняет вашу позицию и возможность продолжать разговор. Оно не требует многословных извинений и не означает отказа от границ. На B2 нужно различать отношения с адресатом, серьёзность просьбы, право собеседника отказать и последствия ошибки. С другом можно говорить прямо, с незнакомым сотрудником обычно полезны явная цель и уважительная форма. Но универсальной фразы, которая всегда звучит вежливо, нет: интонация, история разговора и ситуация меняют эффект.\\n\\nРазделяйте признание аргумента и принятие предложения. Καταλαβαίνω γιατί το προτείνετε, αλλά… сообщает понимание причины, а не согласие. Συμφωνώ ως προς τον στόχο, διαφωνώ όμως με… позволяет точно назвать границу. После несогласия дайте обоснование и, если возможно, альтернативу. Избегайте личных оценок Δεν ξέρετε τι λέτε: они не объясняют проблему. Даже формальное σας не делает оскорбление корректным. Обратная крайность — настолько смягчить просьбу, что адресат не поймёт, чего вы хотите.\\n\\nДля запроса используйте σαφές αίτημα: Θα μπορούσατε να…; Θα ήθελα να διευκρινίσω…; Υπάρχει δυνατότητα να…; Грамматическая форма помогает, но запрос должен иметь содержание, срок и объяснимый контекст. Сравните Θα μπορούσατε να το δείτε κάποτε; и Θα μπορούσατε να επιβεβαιώσετε έως την Πέμπτη αν είναι διαθέσιμη η αίθουσα; Во втором варианте понятно, какое действие ожидается. Не придумывайте юридического права или гарантии возврата в бытовом упражнении.\\n\\nПереговоры начинают с фактов и интересов, а не угроз. Назовите наблюдаемую проблему, влияние на вас и желаемое решение. Έχουμε επιβεβαίωση για τις έξι, αλλά η αίθουσα παραμένει κλειστή. Χρειαζόμαστε χώρο για είκοσι άτομα. Ποια λύση μπορείτε να προτείνετε; Если предлагаемое решение не подходит, укажите критерий: Δεν μπορούμε να δεχτούμε μικρότερο χώρο, επειδή… Условное согласие Αν… τότε… фиксирует границу, а не обязательство любой ценой. Итог нужно пересказать и запросить подтверждение.\\n\\nСмена регистра сохраняет смысл. Обращаясь затем к другу, можно убрать официальную рамку, но нельзя превратить «я уточняю возможность» в «мне всё разрешили». При эмоциональном обострении сначала восстановите задачу: Ας επιστρέψουμε στο τι μπορούμε να κάνουμε τώρα. При непонимании спросите о конкретной детали. В речевой практике оцениваются функция, ясность, реакция и уважение к границе собеседника; акцент сам по себе не равен невежливости. Ироническую интерпретацию без реального голоса не считайте подтверждённой.\\n\\nФинальные задания требуют написать и произнести собственные реплики, а затем отреагировать на новое ограничение. Самозапись позволяет проверить ясность, но не заменяет партнёра. D7/D28 возвращают функции в другом контексте: работа, совместное проживание, общественная услуга. Освоение — способность решить новую коммуникативную задачу, а не воспроизвести одну вежливую формулу.", "cefr_level": "B2", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Καταλαβαίνω την ανησυχία σας, αλλά διαφωνώ με τη λύση.", "Θα μπορούσατε να μας προτείνετε έναν προσβάσιμο χώρο;", "Συμφωνώ, εφόσον επιβεβαιωθεί γραπτώς η αλλαγή.", "Ας βεβαιωθούμε ότι καταλάβαμε το ίδιο πράγμα."], "review_plan": {"D7": ["U-B2-021-I11"], "D28": ["U-B2-021-I12"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-B2-021-I11", "U-B2-021-I12"]}, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "active_recall": ["U-B2-021-I07", "U-B2-021-I08"], "prerequisites": ["B1-PR01", "B2-SI01"], "reading_tasks": ["U-B2-021-I02"], "transfer_task": "U-B2-021-I10", "writing_tasks": ["U-B2-021-I06", "U-B2-021-I07", "U-B2-021-I09", "U-B2-021-I12"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-021-I01", "U-B2-021-I02", "U-B2-021-I03", "U-B2-021-I07", "U-B2-021-I11"], "objective": "Выражать точное несогласие без личного нападения"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-021-I04", "U-B2-021-I05", "U-B2-021-I08", "U-B2-021-I10"], "objective": "Вести переговоры: факт, интерес, просьба, условие и подтверждение"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-021-I06", "U-B2-021-I09", "U-B2-021-I12"], "objective": "Менять регистр, сохраняя смысл и границы договорённости"}], "competency_ids": ["B2-PR01"], "speaking_tasks": ["U-B2-021-I01", "U-B2-021-I05", "U-B2-021-I08", "U-B2-021-I10", "U-B2-021-I11"], "entry_probe_ids": ["U-B2-021-I01"], "errors_taxonomy": ["AGREEMENT_SCOPE_CANDIDATE", "ARGUMENT_DEVELOPMENT_CANDIDATE", "BOUNDARY_CLARITY_CANDIDATE", "CERTAINTY_SHIFT_CANDIDATE", "CONDITION_LOSS_CANDIDATE", "IGNORED_CONSTRAINT_CANDIDATE", "NEGOTIATION_CONSTRAINT_CANDIDATE", "NEGOTIATION_TRANSFER_CANDIDATE", "PERSONAL_ATTACK_CANDIDATE", "REQUEST_DEADLINE_CANDIDATE", "REQUEST_REGISTER_CANDIDATE"], "guided_practice": ["U-B2-021-I02", "U-B2-021-I03", "U-B2-021-I04", "U-B2-021-I05", "U-B2-021-I06", "U-B2-021-I09"], "listening_tasks": [], "modality_status": "AUDIO_PENDING", "vocabulary_items": [{"lemma": "η επιφύλαξη", "stress": "η επιφύλαξη", "example": "Έχω μια επιφύλαξη για το χρονοδιάγραμμα.", "inflection": "οι επιφυλάξεις", "collocations": "εκφράζω επιφύλαξη"}, {"lemma": "το αίτημα", "stress": "το αίτημα", "example": "Το αίτημά μας αφορά την ώρα.", "inflection": "τα αιτήματα", "collocations": "σαφές αίτημα"}, {"lemma": "η διαπραγμάτευση", "stress": "η διαπραγμάτευση", "example": "Η διαπραγμάτευση χρειάζεται σαφή όρια.", "inflection": "οι διαπραγματεύσεις", "collocations": "όροι διαπραγμάτευσης"}, {"lemma": "διευκρινίζω", "stress": "διευκρινίζω", "example": "Θα ήθελα να διευκρινίσω έναν όρο.", "inflection": "διευκρίνισα", "collocations": "διευκρινίζω έναν όρο"}], "learning_objectives": ["Выражать точное несогласие без личного нападения", "Вести переговоры: факт, интерес, просьба, условие и подтверждение", "Менять регистр, сохраняя смысл и границы договорённости"], "prerequisite_policy": "Diagnose before instruction; failure routes to primary unit(s) from96 register. Authored prerequisite is not evidence of learner mastery. Retry with fresh example.", "primary_competencies": ["B2-PR01"], "estimated_active_minutes": 85}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3192	unit	U-B2-022	a08d7bd75e052d1a95447d3566e4f45577d9d90a9eaadf7c5ac822b068e5fc20	core	{"unit_id": "U-B2-022", "content_hash": "a08d7bd75e052d1a95447d3566e4f45577d9d90a9eaadf7c5ac822b068e5fc20", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-022.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY"}, "rubrics": ["U-B2-022-RUBRIC"], "unit_id": "U-B2-022", "version": "0.1.0", "title_ru": "Сжатие и связность: пропуски фраз и резюме", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Связность — это отношения между частями текста, а не количество союзов. На B2 читатель должен восстановить ход рассуждения, определить, к чему отсылает местоимение, и сжать материал без потери главного ограничения. В задании на вставку фразы сначала прочитайте весь текст, затем обе границы пропуска. Фраза должна подходить назад и вперёд: объяснять предыдущее, вводить следующее и не повторять уже завершённую мысль.\\n\\nОтслеживайте цепочки отсылок. Эта идея, такая мера, этот результат должны иметь понятный предшествующий смысл. В греческом Αυτό, αυτή η απόφαση, η συγκεκριμένη ανάγκη могут отсылать не только к ближайшему существительному, но и к целой ситуации. Поэтому совпадение рода полезно, но не доказывает ответ. В учебной статье Αυτή η γνώση относится к пониманию проблемы и целесообразности ремонта. Подстановка «эта сломанная вещь» разрушила бы смысл, хотя рядом обсуждаются предметы.\\n\\nПроверьте тип связи: причина, следствие, уступка, пример, уточнение, противопоставление. Ωστόσο сохраняет конфликт ожидания и факта; επομένως представляет вывод; για παράδειγμα вводит частный случай. Механическая замена одного союза другим может изменить логику. При этом несколько форм могут быть допустимы: όμως и ωστόσο часто выражают близкое противопоставление. Если задание не ограничивает форму, принимайте естественную альтернативу, а не только слово из ключа.\\n\\nРезюме начинается с смысловой карты. Назовите тему, позицию автора, два главных основания и существенное ограничение. Затем решите, какие примеры можно объединить, а какие данные необходимы адресату. Сокращать — не значит удалять каждое второе предложение. Перефразируйте на уровне смысла, не заменяя случайные слова синонимами. Сохраняйте отрицание, условность, участников и масштаб вывода: «может помочь» не превращается в «доказало». Не добавляйте свою оценку в резюме, если её не просили; при необходимости отделите её новой фразой.\\n\\nОсобенно опасно потерять оговорку ради красивого короткого текста. В нашем материале обучение ремонту не заменяет профессиональный сервис, результат не гарантирован, снижение отходов ещё не измерено. Резюме «мастерская доказала пользу бесплатного ремонта» искажает сразу несколько смыслов. Число слов — редакторский ориентир для сжатия, не самостоятельное доказательство B2. Если короткий текст сохраняет все нужные отношения, не штрафуйте его сильнее, чем длинный, но неверный.\\n\\nПроверка проходит в два шага: сравните каждое утверждение резюме с исходником, затем прочтите резюме без исходника и проверьте ясность отсылок. После обратной связи исправьте связь, а не просто вставьте новый союз. Самостоятельные задания требуют нового краткого текста и устного объяснения. D7/D28 меняют тему и структуру, чтобы измерить перенос чтения и сжатия, а не память о знакомом абзаце.", "cefr_level": "B2", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Η δράση είναι χρήσιμη· ωστόσο, το αποτέλεσμα δεν είναι εγγυημένο.", "Αυτή η γνώση αφορά την κατανόηση του προβλήματος.", "Ο συντάκτης τονίζει το όφελος αλλά διατηρεί δύο επιφυλάξεις.", "Δεν υπάρχουν ακόμη στοιχεία για τη συνολική μείωση των απορριμμάτων."], "review_plan": {"D7": ["U-B2-022-I10"], "D28": ["U-B2-022-I11"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-B2-022-I10", "U-B2-022-I11"]}, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "active_recall": ["U-B2-022-I07", "U-B2-022-I08"], "prerequisites": ["B2-R01", "B2-G07"], "reading_tasks": ["U-B2-022-I02", "U-B2-022-I03", "U-B2-022-I04", "U-B2-022-I10"], "transfer_task": "U-B2-022-I09", "writing_tasks": ["U-B2-022-I05", "U-B2-022-I07", "U-B2-022-I09", "U-B2-022-I11"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-022-I01", "U-B2-022-I02", "U-B2-022-I03", "U-B2-022-I04", "U-B2-022-I06", "U-B2-022-I10"], "objective": "Восстанавливать связи и отсылки между предложениями"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-022-I05", "U-B2-022-I08"], "objective": "Сжимать аргументированный текст с сохранением ограничений"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-022-I07", "U-B2-022-I09", "U-B2-022-I11"], "objective": "Создавать самостоятельное связное резюме для нового адресата"}], "competency_ids": ["B2-R02"], "speaking_tasks": ["U-B2-022-I08"], "entry_probe_ids": ["U-B2-022-I01"], "errors_taxonomy": ["ANAPHORA_REFERENCE_CANDIDATE", "AUTHOR_PURPOSE_CANDIDATE", "CAUSAL_OVERCLAIM_CANDIDATE", "DISCOURSE_ORDER_CANDIDATE", "DISCOURSE_RELATION_CANDIDATE", "EVIDENCE_STRENGTH_CANDIDATE", "EXPECTATION_SCOPE_CANDIDATE", "FACT_COMMENT_BOUNDARY_CANDIDATE", "SUMMARY_FIDELITY_CANDIDATE"], "guided_practice": ["U-B2-022-I02", "U-B2-022-I03", "U-B2-022-I04", "U-B2-022-I05", "U-B2-022-I06"], "listening_tasks": [], "modality_status": "AUDIO_PENDING", "vocabulary_items": [{"lemma": "η συνοχή", "stress": "η συνοχή", "example": "Η συνοχή δεν εξασφαλίζεται μόνο με συνδέσμους.", "inflection": "της συνοχής", "collocations": "συνοχή κειμένου"}, {"lemma": "η περίληψη", "stress": "η περίληψη", "example": "Η περίληψη διατηρεί το βασικό επιχείρημα.", "inflection": "οι περιλήψεις", "collocations": "γράφω περίληψη"}, {"lemma": "η παραπομπή", "stress": "η παραπομπή", "example": "Η αντωνυμία χρειάζεται σαφή παραπομπή.", "inflection": "οι παραπομπές", "collocations": "σαφής παραπομπή"}, {"lemma": "η επιφύλαξη", "stress": "η επιφύλαξη", "example": "Μην παραλείψεις την ουσιώδη επιφύλαξη.", "inflection": "οι επιφυλάξεις", "collocations": "ουσιώδης επιφύλαξη"}], "learning_objectives": ["Восстанавливать связи и отсылки между предложениями", "Сжимать аргументированный текст с сохранением ограничений", "Создавать самостоятельное связное резюме для нового адресата"], "prerequisite_policy": "Diagnose before instruction; failure routes to primary unit(s) from96 register. Authored prerequisite is not evidence of learner mastery. Retry with fresh example.", "primary_competencies": ["B2-R02"], "estimated_active_minutes": 85}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
