947	source_claim	CP08-INHERITED-U-A2-004-I09-01	37e740e94598e38a42dafba0fcb5d74360395378ad6cc50da2f3565d11cff4dd	\N	{"record": {"claim": "Уровневая тема; не дословный источник авторских фраз", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-A2-004-I09-01", "item_ids": ["U-A2-004-I09"], "source_id": "V201", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-A2-004-I09.json", "sha256": "c133ecf26b2142e7a75166a88eee14256e8207af6bc3d090939efa309540206a"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "V201 PDF7–8", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}}, "claim_id": "CP08-INHERITED-U-A2-004-I09-01", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3193	unit	U-B2-023	bf96fcdaf973b77c28eeaa703adea48cd2fb5371f461abf0d8523f7bd7647a76	core	{"unit_id": "U-B2-023", "content_hash": "bf96fcdaf973b77c28eeaa703adea48cd2fb5371f461abf0d8523f7bd7647a76", "canonical_path": "GreekOS_Academic_Corpus/units/U-B2-023.json", "teaching_material": {"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY"}, "rubrics": ["U-B2-023-RUBRIC"], "unit_id": "U-B2-023", "version": "0.1.0", "title_ru": "Личное и официальное письмо с обоснованием", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Аргументированное письмо должно позволить адресату понять ситуацию, оценить ваши доводы и выполнить ясное действие. На B2 одной корректной формулы приветствия недостаточно: нужна логическая структура, развитие аргумента и уместный тон. Сначала определите адресата, отношения, цель и желаемый результат. Письмо другу может обсуждать сомнение и просить совета; обращение к организации — описывать проблему и предлагать решение. Ни один жанр не требует искусственно сложного языка.\\n\\nРабочая композиция официального письма: тема → причина обращения → проверяемые обстоятельства → последствия → предложение или просьба → ожидаемый ответ. В личном письме можно начать с общей истории, но она должна вести к вашему вопросу. Абзац развивает одну мысль: утверждение, пояснение, пример или следствие. Союзы помогают показать связь, однако длинная цепочка επιπλέον, επίσης, ακόμη не заменяет аргумента. Не изобретайте цифры, нормы или обещания ради убедительности.\\n\\nРазличайте факт, оценку и требование. Στην επιβεβαίωση αναφέρεται ώρα 18:00 — проверяемый факт учебной ситуации. Η αλλαγή δυσκολεύει όσους εργάζονται — обоснованное последствие. Θα μπορούσατε να προτείνετε εναλλακτική; — просьба. Если причина изменения неизвестна, не пишите «вы сделали это из безразличия». Сильное письмо точно описывает проблему, а не усиливает обвинения. В заданиях используйте вымышленные контакты, не раскрывайте собственные документы или чужие данные.\\n\\nКонтраргумент делает позицию точнее: Αναγνωρίζω ότι…, ωστόσο… Сначала честно передайте ограничение другой стороны, затем объясните, почему ваша просьба всё же разумна. Предложите выполнимую альтернативу и при необходимости обозначьте условие. Сохраняйте степень уверенности: θα μπορούσε, ενδέχεται, εφόσον. Личное письмо допускает прямое обращение, эмоцию и разговорные связки; официальное обычно требует последовательного σας и σαφή υπογραφή. Формулы Αγαπητή… и Με εκτίμηση выбираются по отношениям, а не по единственному универсальному шаблону.\\n\\nПеред отправкой проведите четыре проверки. Содержание: выполнены ли все пункты задания, не пропущен ли срок? Логика: каждое ли предложение связано с целью? Язык: согласованы ли формы обращения, времена и отсылки, верны ли ударения? Действие: понятно ли, что адресат должен сделать дальше? Не оценивайте работу только числом ошибок: неверная дата или отсутствующая просьба может быть существеннее единичной опечатки. В то же время понятный смысл не отменяет необходимости языковой обратной связи.\\n\\nПрактика включает полный самостоятельный текст, переработку после конкретного замечания и перенос между личным и официальным регистром. Модели отдельных реплик здесь иллюстрируют функцию, а не заменяют ответ требуемой длины. Объём и время — редакторские ориентиры курса, не официальные экзаменационные нормы. D7 и D28 требуют новой темы без копирования старого письма. Для подтверждения навыка нужны два разных адресата, самостоятельная аргументация, сохранение фактов и актуальная проверка преподавателем; выполнение одного упражнения не сертифицирует B2.", "cefr_level": "B2", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Σας γράφω σχετικά με την αλλαγή του ωραρίου.", "Αναγνωρίζω τη δυσκολία, ωστόσο θα ήθελα να εξετάσετε μια εναλλακτική.", "Πώς θα σου φαινόταν να το δοκιμάσουμε για έναν μήνα;", "Θα εκτιμούσα μια απάντηση πριν από την οριστικοποίηση του προγράμματος."], "review_plan": {"D7": ["U-B2-023-I11"], "D28": ["U-B2-023-I12"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-B2-023-I11", "U-B2-023-I12"]}, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "active_recall": ["U-B2-023-I07", "U-B2-023-I08"], "prerequisites": ["B1-W01", "B2-G09"], "reading_tasks": ["U-B2-023-I02"], "transfer_task": "U-B2-023-I10", "writing_tasks": ["U-B2-023-I01", "U-B2-023-I03", "U-B2-023-I04", "U-B2-023-I06", "U-B2-023-I07", "U-B2-023-I08", "U-B2-023-I09", "U-B2-023-I10", "U-B2-023-I11", "U-B2-023-I12"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-023-I01", "U-B2-023-I02", "U-B2-023-I07", "U-B2-023-I08"], "objective": "Планировать и писать полное личное и официальное аргументированное письмо"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-023-I03", "U-B2-023-I04", "U-B2-023-I06", "U-B2-023-I11"], "objective": "Развивать аргумент, отвечать на возражение и формулировать действие"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-B2-023-I05", "U-B2-023-I09", "U-B2-023-I10", "U-B2-023-I12"], "objective": "Редактировать фактическую точность, связность и регистр в новой ситуации"}], "competency_ids": ["B2-W01"], "speaking_tasks": [], "entry_probe_ids": ["U-B2-023-I01"], "errors_taxonomy": ["ADDRESS_AGREEMENT_CANDIDATE", "ARGUMENT_DEVELOPMENT_CANDIDATE", "AUDIENCE_SUPPORT_CANDIDATE", "COUNTERARGUMENT_CANDIDATE", "FACT_MOTIVE_BOUNDARY_CANDIDATE", "LETTER_TASK_FULFILMENT_CANDIDATE", "LETTER_TRANSFER_CANDIDATE", "PERSONAL_ARGUMENT_CANDIDATE", "REQUEST_DEADLINE_CANDIDATE", "REQUEST_PURPOSE_CANDIDATE", "REVISION_RELEVANCE_CANDIDATE"], "guided_practice": ["U-B2-023-I02", "U-B2-023-I03", "U-B2-023-I04", "U-B2-023-I05", "U-B2-023-I06", "U-B2-023-I09"], "listening_tasks": [], "modality_status": "TEXT_AUTHOR_DRAFT", "vocabulary_items": [{"lemma": "η αιτιολόγηση", "stress": "η αιτιολόγηση", "example": "Το αίτημα χρειάζεται σαφή αιτιολόγηση.", "inflection": "οι αιτιολογήσεις", "collocations": "σαφής αιτιολόγηση"}, {"lemma": "η παράγραφος", "stress": "η παράγραφος", "example": "Κάθε παράγραφος αναπτύσσει μια ιδέα.", "inflection": "οι παράγραφοι", "collocations": "κύρια ιδέα παραγράφου"}, {"lemma": "ο αντίλογος", "stress": "ο αντίλογος", "example": "Λαμβάνω υπόψη τον αντίλογο πριν προτείνω λύση.", "inflection": "του αντιλόγου", "collocations": "λαμβάνω υπόψη τον αντίλογο"}, {"lemma": "οριστικοποιώ", "stress": "οριστικοποιώ", "example": "Το πρόγραμμα δεν έχει οριστικοποιηθεί.", "inflection": "οριστικοποίησα", "collocations": "οριστικοποιώ πρόγραμμα"}], "learning_objectives": ["Планировать и писать полное личное и официальное аргументированное письмо", "Развивать аргумент, отвечать на возражение и формулировать действие", "Редактировать фактическую точность, связность и регистр в новой ситуации"], "prerequisite_policy": "Diagnose before instruction; failure routes to primary unit(s) from96 register. Authored prerequisite is not evidence of learner mastery. Retry with fresh example.", "primary_competencies": ["B2-W01"], "estimated_active_minutes": 85}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3194	audio_job	KEG-B2-L01-AUD1	ccb18f9299a94d6cb6508eb80878e293d50659ed58f64833fbe6592bf38f1973	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": {"status": "PENDING", "evidence": null}, "licence": {"script": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "voice_asset": null}, "text_el": "Καλησπέρα σας. Είμαι η συντονίστρια του προγράμματος «Ανοιχτό Αρχείο». Θα σας εξηγήσω πώς θα λειτουργήσει η πρώτη δοκιμαστική φάση. Θέλουμε να συγκεντρώσουμε παλιές φωτογραφίες της περιοχής και τις ιστορίες που τις συνοδεύουν, χωρίς να ζητήσουμε από κανέναν να αποχωριστεί οριστικά τα προσωπικά του αντικείμενα. Η συμμετοχή είναι προαιρετική και δεν χρειάζεται προηγούμενη εμπειρία.\\nΗ δοκιμή θα διαρκέσει έξι εβδομάδες. Είχαμε αρχικά συζητήσει έναν ολόκληρο χρόνο, αλλά αποφασίσαμε να ξεκινήσουμε με μικρότερο διάστημα, ώστε να εξετάσουμε πρώτα τις δυσκολίες. Η πρώτη ανοιχτή συνάντηση θα γίνει το Σάββατο. Δεν ανακοινώνουμε σήμερα ημερομηνία για πιθανή επέκταση· αυτή θα εξαρτηθεί από τα αποτελέσματα της δοκιμής.\\nΟι συναντήσεις θα φιλοξενούνται στο παλιό ταχυδρομείο, όχι στο δημαρχείο όπου έγινε η αρχική παρουσίαση. Η αίθουσα βρίσκεται στο ισόγειο και υπάρχει πρόσβαση χωρίς σκαλοπάτια από την πλαϊνή είσοδο. Αν δεν γνωρίζετε το κτίριο, μπορείτε να ζητήσετε έναν απλό χάρτη από τη γραμματεία. Στην κεντρική πόρτα θα υπάρχει σχετική ανακοίνωση.\\nΚάθε άτομο μπορεί να φέρει μέχρι τέσσερις φωτογραφίες στην πρώτη συνάντηση. Το όριο δεν σημαίνει ότι οι υπόλοιπες δεν μας ενδιαφέρουν. Απλώς χρειαζόμαστε χρόνο για να καταγράψουμε σωστά την ιστορία καθεμιάς. Δεν θα κρατήσουμε τα πρωτότυπα: θα δημιουργήσουμε ψηφιακά αντίγραφα και θα σας επιστρέψουμε τα πρωτότυπα πριν φύγετε από την αίθουσα.\\nΗ κράτηση θέσης γίνεται τηλεφωνικά. Σας παρακαλούμε να μη στέλνετε αίτημα μέσω κοινωνικών δικτύων, γιατί οι εθελοντές που τα παρακολουθούν δεν έχουν πρόσβαση στον κατάλογο των ραντεβού. Μπορείτε να κλείσετε θέση μέχρι την Πέμπτη το μεσημέρι. Την Παρασκευή θα οργανώσουμε το πρόγραμμα και δεν θα προσθέσουμε νέα ραντεβού.\\nΗ πρώτη ομάδα θα αρχίσει στις δέκα και μισή το πρωί. Παρακαλούμε να έρθετε δέκα λεπτά νωρίτερα, για να βρούμε τα στοιχεία της κράτησής σας. Δεν χρειάζεται να αγοράσετε υλικά ή να πληρώσετε εισιτήριο. Το μόνο που ζητάμε, πέρα από τις φωτογραφίες, είναι ένα σύντομο σημείωμα με όσα γνωρίζετε για αυτές.\\nΣτο σημείωμα γράψτε, αν μπορείτε, το έτος που τραβήχτηκε κάθε φωτογραφία. Αν δεν είστε βέβαιοι, σημειώστε ότι πρόκειται για εκτίμηση. Είναι προτιμότερο να φαίνεται η αβεβαιότητα παρά να καταγράψουμε μια χρονολογία σαν να ήταν αποδεδειγμένη. Μπορείτε επίσης να αναφέρετε τον τόπο και τα πρόσωπα, εφόσον επιθυμείτε να μοιραστείτε αυτές τις πληροφορίες.\\nΠριν δημοσιευτεί οποιοδήποτε ψηφιακό αντίγραφο, θα σας ζητήσουμε γραπτή άδεια. Η άδεια για τη δημιουργία αντιγράφου δεν σημαίνει αυτόματα άδεια για δημόσια ανάρτηση. Θα δείτε πρώτα τη λεζάντα και θα μπορείτε να ζητήσετε διορθώσεις ή να αποφασίσετε ότι η φωτογραφία θα μείνει εκτός της δημόσιας συλλογής. Δεν χρειάζεται να αποφασίσετε αμέσως.\\nΌσοι δεν διαθέτουν φωτογραφίες μπορούν επίσης να βοηθήσουν. Χρειαζόμαστε ανθρώπους που θα καταγράφουν προφορικές αναμνήσεις, αφού προηγουμένως λάβουν τη συναίνεση των συνομιλητών τους. Θα προηγηθεί σύντομη ενημέρωση για τον τρόπο των ερωτήσεων. Δεν ζητάμε εντυπωσιακές ιστορίες, αλλά σαφείς περιγραφές της καθημερινής ζωής. Μια συνηθισμένη διαδρομή μπορεί να αποκαλύψει πολλά για την περιοχή.\\nΤέλος, ο απολογισμός θα παρουσιαστεί στη βιβλιοθήκη, σε διαφορετική συνάντηση από τις συναντήσεις συλλογής στο ταχυδρομείο. Θα δείξουμε τι συγκεντρώθηκε και ποιες απορίες έμειναν ανοιχτές. Θα ζητήσουμε και τη δική σας γνώμη πριν αποφασίσουμε αν θα συνεχιστεί το πρόγραμμα. Σας ευχαριστώ και είμαι έτοιμη να απαντήσω στις οργανωτικές σας ερωτήσεις.", "version": "0.11.0", "audio_id": "KEG-B2-L01-AUD1", "register": "informative monologue / natural reasoned conversation", "segments": [{"text": "Καλησπέρα σας. Είμαι η συντονίστρια του προγράμματος «Ανοιχτό Αρχείο». Θα σας εξηγήσω πώς θα λειτουργήσει η πρώτη δοκιμαστική φάση. Θέλουμε να συγκεντρώσουμε παλιές φωτογραφίες της περιοχής και τις ιστορίες που τις συνοδεύουν, χωρίς να ζητήσουμε από κανέναν να αποχωριστεί οριστικά τα προσωπικά του αντικείμενα. Η συμμετοχή είναι προαιρετική και δεν χρειάζεται προηγούμενη εμπειρία.", "cue_id": "N00", "speaker": "Συντονίστρια", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Η δοκιμή θα διαρκέσει έξι εβδομάδες. Είχαμε αρχικά συζητήσει έναν ολόκληρο χρόνο, αλλά αποφασίσαμε να ξεκινήσουμε με μικρότερο διάστημα, ώστε να εξετάσουμε πρώτα τις δυσκολίες. Η πρώτη ανοιχτή συνάντηση θα γίνει το Σάββατο. Δεν ανακοινώνουμε σήμερα ημερομηνία για πιθανή επέκταση· αυτή θα εξαρτηθεί από τα αποτελέσματα της δοκιμής.", "cue_id": "N01", "speaker": "Συντονίστρια", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Οι συναντήσεις θα φιλοξενούνται στο παλιό ταχυδρομείο, όχι στο δημαρχείο όπου έγινε η αρχική παρουσίαση. Η αίθουσα βρίσκεται στο ισόγειο και υπάρχει πρόσβαση χωρίς σκαλοπάτια από την πλαϊνή είσοδο. Αν δεν γνωρίζετε το κτίριο, μπορείτε να ζητήσετε έναν απλό χάρτη από τη γραμματεία. Στην κεντρική πόρτα θα υπάρχει σχετική ανακοίνωση.", "cue_id": "N02", "speaker": "Συντονίστρια", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Κάθε άτομο μπορεί να φέρει μέχρι τέσσερις φωτογραφίες στην πρώτη συνάντηση. Το όριο δεν σημαίνει ότι οι υπόλοιπες δεν μας ενδιαφέρουν. Απλώς χρειαζόμαστε χρόνο για να καταγράψουμε σωστά την ιστορία καθεμιάς. Δεν θα κρατήσουμε τα πρωτότυπα: θα δημιουργήσουμε ψηφιακά αντίγραφα και θα σας επιστρέψουμε τα πρωτότυπα πριν φύγετε από την αίθουσα.", "cue_id": "N03", "speaker": "Συντονίστρια", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Η κράτηση θέσης γίνεται τηλεφωνικά. Σας παρακαλούμε να μη στέλνετε αίτημα μέσω κοινωνικών δικτύων, γιατί οι εθελοντές που τα παρακολουθούν δεν έχουν πρόσβαση στον κατάλογο των ραντεβού. Μπορείτε να κλείσετε θέση μέχρι την Πέμπτη το μεσημέρι. Την Παρασκευή θα οργανώσουμε το πρόγραμμα και δεν θα προσθέσουμε νέα ραντεβού.", "cue_id": "N04", "speaker": "Συντονίστρια", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Η πρώτη ομάδα θα αρχίσει στις δέκα και μισή το πρωί. Παρακαλούμε να έρθετε δέκα λεπτά νωρίτερα, για να βρούμε τα στοιχεία της κράτησής σας. Δεν χρειάζεται να αγοράσετε υλικά ή να πληρώσετε εισιτήριο. Το μόνο που ζητάμε, πέρα από τις φωτογραφίες, είναι ένα σύντομο σημείωμα με όσα γνωρίζετε για αυτές.", "cue_id": "N05", "speaker": "Συντονίστρια", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Στο σημείωμα γράψτε, αν μπορείτε, το έτος που τραβήχτηκε κάθε φωτογραφία. Αν δεν είστε βέβαιοι, σημειώστε ότι πρόκειται για εκτίμηση. Είναι προτιμότερο να φαίνεται η αβεβαιότητα παρά να καταγράψουμε μια χρονολογία σαν να ήταν αποδεδειγμένη. Μπορείτε επίσης να αναφέρετε τον τόπο και τα πρόσωπα, εφόσον επιθυμείτε να μοιραστείτε αυτές τις πληροφορίες.", "cue_id": "N06", "speaker": "Συντονίστρια", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Πριν δημοσιευτεί οποιοδήποτε ψηφιακό αντίγραφο, θα σας ζητήσουμε γραπτή άδεια. Η άδεια για τη δημιουργία αντιγράφου δεν σημαίνει αυτόματα άδεια για δημόσια ανάρτηση. Θα δείτε πρώτα τη λεζάντα και θα μπορείτε να ζητήσετε διορθώσεις ή να αποφασίσετε ότι η φωτογραφία θα μείνει εκτός της δημόσιας συλλογής. Δεν χρειάζεται να αποφασίσετε αμέσως.", "cue_id": "N07", "speaker": "Συντονίστρια", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Όσοι δεν διαθέτουν φωτογραφίες μπορούν επίσης να βοηθήσουν. Χρειαζόμαστε ανθρώπους που θα καταγράφουν προφορικές αναμνήσεις, αφού προηγουμένως λάβουν τη συναίνεση των συνομιλητών τους. Θα προηγηθεί σύντομη ενημέρωση για τον τρόπο των ερωτήσεων. Δεν ζητάμε εντυπωσιακές ιστορίες, αλλά σαφείς περιγραφές της καθημερινής ζωής. Μια συνηθισμένη διαδρομή μπορεί να αποκαλύψει πολλά για την περιοχή.", "cue_id": "N08", "speaker": "Συντονίστρια", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Τέλος, ο απολογισμός θα παρουσιαστεί στη βιβλιοθήκη, σε διαφορετική συνάντηση από τις συναντήσεις συλλογής στο ταχυδρομείο. Θα δείξουμε τι συγκεντρώθηκε και ποιες απορίες έμειναν ανοιχτές. Θα ζητήσουμε και τη δική σας γνώμη πριν αποφασίσουμε αν θα συνεχιστεί το πρόγραμμα. Σας ευχαριστώ και είμαι έτοιμη να απαντήσω στις οργανωτικές σας ερωτήσεις.", "cue_id": "N09", "speaker": "Συντονίστρια", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}], "output_path": null, "target_path": "audio/exams/KEG-B2-L01-AUD1.wav", "speaker_role": ["Συντονίστρια"], "measured_cues": [], "native_review": {"status": "NOT_PERFORMED"}, "speaking_rate": "B2 natural, final rate established by listener pilot", "voice_profile": "Natural distinct standard Modern Greek voices, audible self-introductions in dialogue", "format_request": "Project master WAV PCM48kHz24bit; not an official KEG requirement", "task_alignment": [{"key": ["έξι", "6"], "cue_ids": ["N01"], "item_id": "KEG-B2-L01-N01"}, {"key": ["ταχυδρομείο"], "cue_ids": ["N02"], "item_id": "KEG-B2-L01-N02"}, {"key": ["τέσσερις", "4"], "cue_ids": ["N03"], "item_id": "KEG-B2-L01-N03"}, {"key": ["τηλεφωνικά", "με τηλέφωνο"], "cue_ids": ["N04"], "item_id": "KEG-B2-L01-N04"}, {"key": ["Πέμπτη"], "cue_ids": ["N04"], "item_id": "KEG-B2-L01-N05"}, {"key": ["10:30", "10.30", "δέκα και μισή", "δέκα τριάντα"], "cue_ids": ["N05"], "item_id": "KEG-B2-L01-N06"}, {"key": ["έτος"], "cue_ids": ["N06"], "item_id": "KEG-B2-L01-N07"}, {"key": ["γραπτή"], "cue_ids": ["N07"], "item_id": "KEG-B2-L01-N08"}, {"key": ["αναμνήσεις"], "cue_ids": ["N08"], "item_id": "KEG-B2-L01-N09"}, {"key": ["βιβλιοθήκη"], "cue_ids": ["N09"], "item_id": "KEG-B2-L01-N10"}], "acceptance_tests": ["Document voice and commercial distribution rights", "Hash actual bytes and measure duration,cue timings,peak,Loudness; reject clipping/truncation", "Blind Greek listener solves all tasks without transcript", "Then verify every word,number,negation and speaker against script; repair discrepancies", "Pilot two plays and reading/response pauses in30minutes", "No AUDIO_VERIFIED or release before actual listening and recorded evidence"], "verification_hash": null, "actual_duration_ms": null, "source_script_path": "GreekOS_Audio_and_Speaking/assets/KEG-B2-L01-AUD1.json", "pronunciation_notes": "Retain all names,numbers,negations,corrections verbatim", "script_version_hash": "00a85de4bfff893571b0d0c9d7950f95b5bef7eab55af775eef592e4b9bd3662", "source_manifest_hash": "5b3dfa95c192986fc27b477690f0269f5c9a5aafee88f8461de60fc1942b2a36", "source_manifest_path": "GreekOS_Audio_and_Speaking/assets/KEG-B2-L01-AUD1.json", "expected_prompt_context": "F01 part1,two plays in final30-minute section", "intonation_instructions": "No answer emphasis; no music; hidden labels not read; self-introductions are spoken", "source_script_file_hash": "5b3dfa95c192986fc27b477690f0269f5c9a5aafee88f8461de60fc1942b2a36"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
