3196	audio_job	D-A1-LISTENING-01-AUD01	bd38ba5dd9c7e499568e345e5b273d4dc3468eeba2de5c452c74e3f42dc9925e	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": null, "licence": null, "text_el": "Δάφνη: Το μάθημα αρχίζει στις πέντε;\\nΟρέστης: Όχι, σήμερα αρχίζει στις έξι.\\nΔάφνη: Στις έξι, εντάξει. Θα είμαι εκεί.", "version": "0.1.0", "audio_id": "D-A1-LISTENING-01-AUD01", "priority": 2, "register": ["standard_modern_greek", "context_of_source_script"], "segments": [{"text_el": "Το μάθημα αρχίζει στις πέντε;", "segment_id": "D-A1-LISTENING-01-AUD01-C01", "speaker_role": "Δάφνη", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Όχι, σήμερα αρχίζει στις έξι.", "segment_id": "D-A1-LISTENING-01-AUD01-C02", "speaker_role": "Ορέστης", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Στις έξι, εντάξει. Θα είμαι εκεί.", "segment_id": "D-A1-LISTENING-01-AUD01-C03", "speaker_role": "Δάφνη", "measured_end_ms": null, "measured_start_ms": null}], "output_path": null, "speaker_role": ["Δάφνη", "Ορέστης"], "verification": {"file_decoded": false, "AUDIO_VERIFIED": false, "HUMAN_VERIFIED": false, "actually_listened": false, "blind_independent_listening": false}, "measured_cues": [], "native_review": {"status": "PENDING", "reviewer_id": null, "evidence_path": null}, "script_rights": {"scope": "Original project script rights only; does not establish recording or voice rights", "source_path": "GreekOS_Audio_and_Speaking/assets/D-A1-LISTENING-01-AUD01.json"}, "speaking_rate": {"kind": "PROVISIONAL_AUTHOR_PLAN_NOT_MEASURED_OR_OFFICIAL", "target_wpm": 95, "instruction": "Natural intelligible delivery; approve level fit after blind listening. Do not distort prosody to hit WPM."}, "voice_profile": {"cast": [{"role": "Δάφνη", "performer_id": null, "consent_record_id": null, "provider_voice_id": null}, {"role": "Ορέστης", "performer_id": null, "consent_record_id": null, "provider_voice_id": null}], "avoid": ["real-person voice imitation", "caricatured r