3204	audio_job	U-A1-013-AUD01	84e8ea4657bcff6cfed1eedee87e2f5425aae46fc2e935eb1c65a1a4de7270ab	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": null, "licence": null, "text_el": "A: Πού είναι το σπίτι σου;\\nB: Κοντά στο σχολείο. Η στάση είναι μπροστά στο σχολείο.\\nA: Πηγαίνεις στη δουλειά με τα πόδια;\\nB: Όχι, με το λεωφορείο. Γυρίζω με τα πόδια.\\nA: Έχει φούρνο κοντά;\\nB: Ναι, δίπλα στο σπίτι.", "version": "0.1.0", "audio_id": "U-A1-013-AUD01", "priority": 3, "register": ["standard_modern_greek", "context_of_source_script"], "segments": [{"text_el": "Πού είναι το σπίτι σου;", "segment_id": "U-A1-013-AUD01-C01", "speaker_role": "A", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Κοντά στο σχολείο. Η στάση είναι μπροστά στο σχολείο.", "segment_id": "U-A1-013-AUD01-C02", "speaker_role": "B", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Πηγαίνεις στη δουλειά με τα πόδια;", "segment_id": "U-A1-013-AUD01-C03", "speaker_role": "A", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Όχι, με το λεωφορείο. Γυρίζω με τα πόδια.", "segment_id": "U-A1-013-AUD01-C04", "speaker_role": "B", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Έχει φούρνο κοντά;", "segment_id": "U-A1-013-AUD01-C05", "speaker_role": "A", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Ναι, δίπλα στο σπίτι.", "segment_id": "U-A1-013-AUD01-C06", "speaker_role": "B", "measured_end_ms": null, "measured_start_ms": null}], "output_path": null, "speaker_role": ["A", "B"], "verification": {"file_decoded": false, "AUDIO_VERIFIED": false, "HUMAN_VERIFIED": false, "actually_listened": false, "blind_independent_listening": false}, "measured_cues": [], "native_review": {"status": "PENDING", "reviewer_id": null, "evidence_path": null}, "script_rights": {"scope": "Original project script rights only; does not establish recording or voice rights", "source_path": "GreekOS_Audio_and_Speaking/assets/U-A1-013-AUD01.jso