3211	audio_job	U-A2-011-AUD01	b486171b45510719d3582369f0f5a807cb0af85f7888dc6f755fbe6da673e80b	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": null, "licence": null, "text_el": "Α: Καλημέρα. Έχω κράτηση για δύο νύχτες, στο όνομα Δήμου.\\nΒ: Ναι, ένα μονόκλινο με πρωινό.\\nΑ: Συγγνώμη, ζήτησα δίκλινο χωρίς πρωινό.\\nΒ: Έχετε δίκιο. Το δίκλινο είναι 70 ευρώ τη νύχτα.\\nΑ: Δηλαδή 140 ευρώ συνολικά;\\nΒ: Ακριβώς.\\nΑ: Μπορώ να πληρώσω με κάρτα;\\nΒ: Βεβαίως.", "version": "0.1.0", "audio_id": "U-A2-011-AUD01", "priority": 3, "register": ["standard_modern_greek", "context_of_source_script"], "segments": [{"text_el": "Καλημέρα. Έχω κράτηση για δύο νύχτες, στο όνομα Δήμου.", "segment_id": "U-A2-011-AUD01-C01", "speaker_role": "Α", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Ναι, ένα μονόκλινο με πρωινό.", "segment_id": "U-A2-011-AUD01-C02", "speaker_role": "Β", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Συγγνώμη, ζήτησα δίκλινο χωρίς πρωινό.", "segment_id": "U-A2-011-AUD01-C03", "speaker_role": "Α", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Έχετε δίκιο. Το δίκλινο είναι 70 ευρώ τη νύχτα.", "segment_id": "U-A2-011-AUD01-C04", "speaker_role": "Β", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Δηλαδή 140 ευρώ συνολικά;", "segment_id": "U-A2-011-AUD01-C05", "speaker_role": "Α", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Ακριβώς.", "segment_id": "U-A2-011-AUD01-C06", "speaker_role": "Β", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Μπορώ να πληρώσω με κάρτα;", "segment_id": "U-A2-011-AUD01-C07", "speaker_role": "Α", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Βεβαίως.", "segment_id": "U-A2-011-AUD01-C08", "speaker_role": "Β", "measured_end_ms": null, "measured_start_ms": null}], "output_path": null, "speaker_role": ["Α", "Β"], "verification": {"file_decoded": false, "AUDIO_VERIFIED": false, "HUMAN_VERIFIED": false