3212	audio_job	U-A2-012-AUD01	bc3a8c63eb5fd6b075150485dae39bf9faacc64bd61b0777fc0b47a635d30255	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": null, "licence": null, "text_el": "Α: Καλημέρα. Θέλω να αλλάξω το ραντεβού μου με τον γιατρό. Είναι για την Τρίτη στις δέκα.\\nΒ: Μπορείτε την Τετάρτη στις έντεκα;\\nΑ: Δυστυχώς δουλεύω το πρωί. Υπάρχει ώρα μετά τις τέσσερις;\\nΒ: Την Πέμπτη στις πέντε.\\nΑ: Ναι, μπορώ. Άρα την Πέμπτη στις πέντε.\\nΒ: Σωστά. Το παλιό ραντεβού ακυρώνεται.", "version": "0.1.0", "audio_id": "U-A2-012-AUD01", "priority": 3, "register": ["standard_modern_greek", "context_of_source_script"], "segments": [{"text_el": "Καλημέρα. Θέλω να αλλάξω το ραντεβού μου με τον γιατρό. Είναι για την Τρίτη στις δέκα.", "segment_id": "U-A2-012-AUD01-C01", "speaker_role": "Α", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Μπορείτε την Τετάρτη στις έντεκα;", "segment_id": "U-A2-012-AUD01-C02", "speaker_role": "Β", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Δυστυχώς δουλεύω το πρωί. Υπάρχει ώρα μετά τις τέσσερις;", "segment_id": "U-A2-012-AUD01-C03", "speaker_role": "Α", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Την Πέμπτη στις πέντε.", "segment_id": "U-A2-012-AUD01-C04", "speaker_role": "Β", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Ναι, μπορώ. Άρα την Πέμπτη στις πέντε.", "segment_id": "U-A2-012-AUD01-C05", "speaker_role": "Α", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Σωστά. Το παλιό ραντεβού ακυρώνεται.", "segment_id": "U-A2-012-AUD01-C06", "speaker_role": "Β", "measured_end_ms": null, "measured_start_ms": null}], "output_path": null, "speaker_role": ["Α", "Β"], "verification": {"file_decoded": false, "AUDIO_VERIFIED": false, "HUMAN_VERIFIED": false, "actually_listened": false, "blind_independent_listening": false}, "measured_cues": [], "native_review": {"status": "PENDING", "reviewer_id": null, "evidence_path": null}, "script_rights": {