3213	audio_job	U-B1-011-SCRIPT	15b1da17a1467c82309dab7de677ba0a106253a44ee1c2b08eea269299e3ea2a	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": null, "licence": null, "text_el": "Ελένη: Γιατί είσαι κουρασμένος;\\nΠέτρος: Πέρασα το πρωί περπατώντας στη γειτονιά και βγάζοντας φωτογραφίες.\\nΕλένη: Οι οδηγίες για την έκθεση είναι έτοιμες;\\nΠέτρος: Ναι, είναι γραμμένες στα ελληνικά. Τις άφησα πάνω στο τραπέζι.\\nΕλένη: Ωραία. Μπήκα πριν λίγο στην αίθουσα. Οι δύο πίσω πόρτες ήταν κλεισμένες.\\nΠέτρος: Ξέρεις ποιος τις έκλεισε;\\nΕλένη: Όχι. Θα ρωτήσω την υπεύθυνη.", "version": "0.1.0", "audio_id": "U-B1-011-SCRIPT", "priority": 3, "register": ["standard_modern_greek", "context_of_source_script"], "segments": [{"text_el": "Γιατί είσαι κουρασμένος;", "segment_id": "U-B1-011-SCRIPT-C01", "speaker_role": "Ελένη", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Πέρασα το πρωί περπατώντας στη γειτονιά και βγάζοντας φωτογραφίες.", "segment_id": "U-B1-011-SCRIPT-C02", "speaker_role": "Πέτρος", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Οι οδηγίες για την έκθεση είναι έτοιμες;", "segment_id": "U-B1-011-SCRIPT-C03", "speaker_role": "Ελένη", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Ναι, είναι γραμμένες στα ελληνικά. Τις άφησα πάνω στο τραπέζι.", "segment_id": "U-B1-011-SCRIPT-C04", "speaker_role": "Πέτρος", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Ωραία. Μπήκα πριν λίγο στην αίθουσα. Οι δύο πίσω πόρτες ήταν κλεισμένες.", "segment_id": "U-B1-011-SCRIPT-C05", "speaker_role": "Ελένη", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Ξέρεις ποιος τις έκλεισε;", "segment_id": "U-B1-011-SCRIPT-C06", "speaker_role": "Πέτρος", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Όχι. Θα ρωτήσω την υπεύθυνη.", "segment_id": "U-B1-011-SCRIPT-C07", "speaker_role": "Ελένη", "measured_end_ms": null, "measured_start_ms": null}], "output_path": null, "speaker_role