3214	audio_job	U-B1-012-SCRIPT	37d801e681c7e8ea017d79ac13f79039921d3580a9942dd507d9a11dbbbd1271	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": null, "licence": null, "text_el": "Νίκος: Ψάχνω την τσάντα που άφησα εδώ το πρωί. Έχει μπλε ετικέτα.\\nΕύα: Αυτή που είναι δίπλα στην πόρτα;\\nΝίκος: Όχι, εκείνη έχει κόκκινη ετικέτα. Η τσάντα που ψάχνω έχει και δύο μικρές τσέπες.\\nΕύα: Την έχει ο συνάδελφος που δουλεύει στην υποδοχή. Θα σου δείξω πού είναι.\\nΝίκος: Ευχαριστώ. Εννοείς τον κύριο που φοράει πράσινο πουκάμισο;\\nΕύα: Ναι, τον κύριο Λάμπρου.", "version": "0.1.0", "audio_id": "U-B1-012-SCRIPT", "priority": 3, "register": ["standard_modern_greek", "context_of_source_script"], "segments": [{"text_el": "Ψάχνω την τσάντα που άφησα εδώ το πρωί. Έχει μπλε ετικέτα.", "segment_id": "U-B1-012-SCRIPT-C01", "speaker_role": "Νίκος", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Αυτή που είναι δίπλα στην πόρτα;", "segment_id": "U-B1-012-SCRIPT-C02", "speaker_role": "Εύα", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Όχι, εκείνη έχει κόκκινη ετικέτα. Η τσάντα που ψάχνω έχει και δύο μικρές τσέπες.", "segment_id": "U-B1-012-SCRIPT-C03", "speaker_role": "Νίκος", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Την έχει ο συνάδελφος που δουλεύει στην υποδοχή. Θα σου δείξω πού είναι.", "segment_id": "U-B1-012-SCRIPT-C04", "speaker_role": "Εύα", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Ευχαριστώ. Εννοείς τον κύριο που φοράει πράσινο πουκάμισο;", "segment_id": "U-B1-012-SCRIPT-C05", "speaker_role": "Νίκος", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Ναι, τον κύριο Λάμπρου.", "segment_id": "U-B1-012-SCRIPT-C06", "speaker_role": "Εύα", "measured_end_ms": null, "measured_start_ms": null}], "output_path": null, "speaker_role": ["Νίκος", "Εύα"], "verification": {"file_decoded": false, "AUDIO_VERIFIED": false, "HUMAN_VERIFIED": false, "actually_listened": false, "blind_i