3215	audio_job	U-B1-013-SCRIPT	461da89cda6951fa29cb7ee9e64c44eee5a20b1c15dc5f254d8ffade2044b18e	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": null, "licence": null, "text_el": "Ελένη: Να στείλω τώρα την πρόσκληση;\\nΝίκος: Όχι ακόμη. Στείλ’ την αφού ελέγξεις τη νέα διεύθυνση.\\nΕλένη: Ωραία. Και οι καρέκλες;\\nΝίκος: Θα περιμένουμε μέχρι να φτάσει το φορτηγό. Μετά θα τις βάλουμε στην αίθουσα.\\nΕλένη: Πριν φύγω, θα σε πάρω τηλέφωνο.\\nΝίκος: Εντάξει. Εγώ θα μείνω εδώ μέχρι τις επτά.", "version": "0.1.0", "audio_id": "U-B1-013-SCRIPT", "priority": 3, "register": ["standard_modern_greek", "context_of_source_script"], "segments": [{"text_el": "Να στείλω τώρα την πρόσκληση;", "segment_id": "U-B1-013-SCRIPT-C01", "speaker_role": "Ελένη", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Όχι ακόμη. Στείλ’ την αφού ελέγξεις τη νέα διεύθυνση.", "segment_id": "U-B1-013-SCRIPT-C02", "speaker_role": "Νίκος", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Ωραία. Και οι καρέκλες;", "segment_id": "U-B1-013-SCRIPT-C03", "speaker_role": "Ελένη", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Θα περιμένουμε μέχρι να φτάσει το φορτηγό. Μετά θα τις βάλουμε στην αίθουσα.", "segment_id": "U-B1-013-SCRIPT-C04", "speaker_role": "Νίκος", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Πριν φύγω, θα σε πάρω τηλέφωνο.", "segment_id": "U-B1-013-SCRIPT-C05", "speaker_role": "Ελένη", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Εντάξει. Εγώ θα μείνω εδώ μέχρι τις επτά.", "segment_id": "U-B1-013-SCRIPT-C06", "speaker_role": "Νίκος", "measured_end_ms": null, "measured_start_ms": null}], "output_path": null, "speaker_role": ["Ελένη", "Νίκος"], "verification": {"file_decoded": false, "AUDIO_VERIFIED": false, "HUMAN_VERIFIED": false, "actually_listened": false, "blind_independent_listening": false}, "measured_cues": [], "native_review": {"status": "PENDING", "reviewer_id": null, "evidence_path