3216	audio_job	U-B2-006-SCRIPT	463d67dfdb7a81d34eabc2e97dccd6e627c9fe3d2a6d486cfd99d3df6252cb0e	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": null, "licence": null, "text_el": "Α: Μπορούμε να στείλουμε την ανακοίνωση τώρα;\\nΒ: Όχι ακόμη. Ο τίτλος έχει διορθωθεί, αλλά πρέπει να ελέγξουμε τις ώρες.\\nΑ: Νόμιζα ότι τις είχες ελέγξει χτες.\\nΒ: Έλεγχα τις ώρες όταν ήρθε ένα νέο πρόγραμμα. Πρέπει να συγκρίνω τα δύο αρχεία.\\nΑ: Θα μπορούσες να το κάνεις μέχρι τις τρεις;\\nΒ: Ναι, μπορώ. Θα σου στείλω μήνυμα όταν τελειώσω.\\nΑ: Ωραία. Θα περιμένω το μήνυμά σου πριν στείλω την ανακοίνωση.", "version": "0.1.0", "audio_id": "U-B2-006-SCRIPT", "priority": 3, "register": ["standard_modern_greek", "context_of_source_script"], "segments": [{"text_el": "Μπορούμε να στείλουμε την ανακοίνωση τώρα;", "segment_id": "U-B2-006-SCRIPT-C01", "speaker_role": "Α", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Όχι ακόμη. Ο τίτλος έχει διορθωθεί, αλλά πρέπει να ελέγξουμε τις ώρες.", "segment_id": "U-B2-006-SCRIPT-C02", "speaker_role": "Β", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Νόμιζα ότι τις είχες ελέγξει χτες.", "segment_id": "U-B2-006-SCRIPT-C03", "speaker_role": "Α", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Έλεγχα τις ώρες όταν ήρθε ένα νέο πρόγραμμα. Πρέπει να συγκρίνω τα δύο αρχεία.", "segment_id": "U-B2-006-SCRIPT-C04", "speaker_role": "Β", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Θα μπορούσες να το κάνεις μέχρι τις τρεις;", "segment_id": "U-B2-006-SCRIPT-C05", "speaker_role": "Α", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Ναι, μπορώ. Θα σου στείλω μήνυμα όταν τελειώσω.", "segment_id": "U-B2-006-SCRIPT-C06", "speaker_role": "Β", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Ωραία. Θα περιμένω το μήνυμά σου πριν στείλω την ανακοίνωση.", "segment_id": "U-B2-006-SCRIPT-C07", "speaker_role": "Α", "measured_end_ms": null, "measured_sta