3260	audio_job	U-A2-013-AUD01	6c16c74bfcaee6e94341d72defa45f22f1aac6853e21ec6297da414afd6a3cbd	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": null, "licence": null, "text_el": "A: Καλημέρα σας. Θέλω ένα εισιτήριο για αύριο το πρωί.\\nB: Για σήμερα στις εννέα;\\nA: Όχι για σήμερα. Για αύριο, παρακαλώ.\\nB: Αύριο υπάρχει λεωφορείο στις οκτώ και στις δέκα.\\nA: Στις δέκα, παρακαλώ. Πόσο κοστίζει;\\nB: Δεκατρία ευρώ.\\nA: Συγγνώμη, είπατε δεκατρία ή τριάντα;\\nB: Δεκατρία.\\nA: Ωραία. Ένα εισιτήριο για αύριο στις δέκα. Ευχαριστώ.", "version": "0.1.0", "audio_id": "U-A2-013-AUD01", "priority": 4, "register": ["standard_modern_greek", "context_of_source_script"], "segments": [{"text_el": "Καλημέρα σας. Θέλω ένα εισιτήριο για αύριο το πρωί.", "segment_id": "U-A2-013-AUD01-C01", "speaker_role": "A", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Για σήμερα στις εννέα;", "segment_id": "U-A2-013-AUD01-C02", "speaker_role": "B", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Όχι για σήμερα. Για αύριο, παρακαλώ.", "segment_id": "U-A2-013-AUD01-C03", "speaker_role": "A", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Αύριο υπάρχει λεωφορείο στις οκτώ και στις δέκα.", "segment_id": "U-A2-013-AUD01-C04", "speaker_role": "B", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Στις δέκα, παρακαλώ. Πόσο κοστίζει;", "segment_id": "U-A2-013-AUD01-C05", "speaker_role": "A", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Δεκατρία ευρώ.", "segment_id": "U-A2-013-AUD01-C06", "speaker_role": "B", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Συγγνώμη, είπατε δεκατρία ή τριάντα;", "segment_id": "U-A2-013-AUD01-C07", "speaker_role": "A", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Δεκατρία.", "segment_id": "U-A2-013-AUD01-C08", "speaker_role": "B", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Ωραία. Ένα εισιτήριο για αύριο στις