3266	audio_job	U-B1-017-AUD01	7d642d0e3d9159bd77909177a0a901ebffe6a4e5038a20421f5767d6c598c7a5	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": null, "licence": null, "text_el": "Υπάλληλος: Η συνάντηση για τη νέα αίθουσα θα γίνει την Πέμπτη στις έξι το απόγευμα.\\nΕπισκέπτρια: Πρέπει να κάνουμε κράτηση για να έρθουμε στη συνάντηση;\\nΥπάλληλος: Όχι, για τη συνάντηση δεν χρειάζεται κράτηση. Για τη χρήση της αίθουσας από ομάδα, όμως, χρειάζεται.\\nΕπισκέπτρια: Θα αποφασιστούν τότε οι πρωινές ώρες;\\nΥπάλληλος: Όχι απαραίτητα. Θα ακούσουμε πρώτα τις προτάσεις των επισκεπτών.", "version": "0.1.0", "audio_id": "U-B1-017-AUD01", "priority": 4, "register": ["standard_modern_greek", "context_of_source_script"], "segments": [{"text_el": "Η συνάντηση για τη νέα αίθουσα θα γίνει την Πέμπτη στις έξι το απόγευμα.", "segment_id": "U-B1-017-AUD01-C01", "speaker_role": "Υπάλληλος", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Πρέπει να κάνουμε κράτηση για να έρθουμε στη συνάντηση;", "segment_id": "U-B1-017-AUD01-C02", "speaker_role": "Επισκέπτρια", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Όχι, για τη συνάντηση δεν χρειάζεται κράτηση. Για τη χρήση της αίθουσας από ομάδα, όμως, χρειάζεται.", "segment_id": "U-B1-017-AUD01-C03", "speaker_role": "Υπάλληλος", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Θα αποφασιστούν τότε οι πρωινές ώρες;", "segment_id": "U-B1-017-AUD01-C04", "speaker_role": "Επισκέπτρια", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Όχι απαραίτητα. Θα ακούσουμε πρώτα τις προτάσεις των επισκεπτών.", "segment_id": "U-B1-017-AUD01-C05", "speaker_role": "Υπάλληλος", "measured_end_ms": null, "measured_start_ms": null}], "output_path": null, "speaker_role": ["Υπάλληλος", "Επισκέπτρια"], "verification": {"file_decoded": false, "AUDIO_VERIFIED": false, "HUMAN_VERIFIED": false, "actually_listened": false, "blind_independent_listening": false}, "measured_cues": [], "native_review