3267	audio_job	U-B2-007-AUD01	433dfc176235fdfbe40626aac1300ba45507c466ef6a27afdccf36176d7514aa	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": null, "licence": null, "text_el": "Συντονίστρια: Έχοντας ελέγξει τα αρχεία, μπορούμε να τα στείλουμε;\\nΣυνεργάτης: Τα κείμενα είναι διορθωμένα, αλλά δύο εικόνες δεν έχουν ακόμη άδεια χρήσης.\\nΣυντονίστρια: Άρα δεν γράφουμε ότι όλο το υλικό είναι έτοιμο.\\nΣυνεργάτης: Ακριβώς. Μπορώ να στείλω μόνο τα κείμενα στην ομάδα για έναν τελευταίο έλεγχο.\\nΣυντονίστρια: Κάνε το, εξηγώντας γιατί οι εικόνες θα ακολουθήσουν αργότερα.\\nΣυνεργάτης: Θα αναφέρω την άδεια που εκκρεμεί, χωρίς να υποσχεθώ συγκεκριμένη ημερομηνία.", "version": "0.1.0", "audio_id": "U-B2-007-AUD01", "priority": 4, "register": ["standard_modern_greek", "context_of_source_script"], "segments": [{"text_el": "Έχοντας ελέγξει τα αρχεία, μπορούμε να τα στείλουμε;", "segment_id": "U-B2-007-AUD01-C01", "speaker_role": "Συντονίστρια", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Τα κείμενα είναι διορθωμένα, αλλά δύο εικόνες δεν έχουν ακόμη άδεια χρήσης.", "segment_id": "U-B2-007-AUD01-C02", "speaker_role": "Συνεργάτης", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Άρα δεν γράφουμε ότι όλο το υλικό είναι έτοιμο.", "segment_id": "U-B2-007-AUD01-C03", "speaker_role": "Συντονίστρια", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Ακριβώς. Μπορώ να στείλω μόνο τα κείμενα στην ομάδα για έναν τελευταίο έλεγχο.", "segment_id": "U-B2-007-AUD01-C04", "speaker_role": "Συνεργάτης", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Κάνε το, εξηγώντας γιατί οι εικόνες θα ακολουθήσουν αργότερα.", "segment_id": "U-B2-007-AUD01-C05", "speaker_role": "Συντονίστρια", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Θα αναφέρω την άδεια που εκκρεμεί, χωρίς να υποσχεθώ συγκεκριμένη ημερομηνία.", "segment_id": "U-B2-007-AUD01-C06", "speaker_role": "Συνεργάτης", "measured_end_ms": null, 