2517	source_claim	CP09-INHERITED-KEG-B2-R01-G07-1	72e08ea25fc80ebc84fa73f978264c706d4635237a17e81c6351034a78c9ea5d	\N	{"record": {"claim": "Existing source identifier association only; no new substantive claim or recent-usage assertion", "limits": "Source meaning, scope, currentness and rights still require academic review", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP09-INHERITED-KEG-B2-R01-G07-1", "item_ids": ["KEG-B2-R01-G07"], "source_id": "V241", "provenance": {"path": "GreekOS_B2_Exam_Bank/items/KEG-B2-R01-G07.json", "field": "source_refs", "sha256": "1763cbe67fab9f623bdc1af667ef6a1b2cfd21d532ff25e786c1d0d0fc2daaed"}}, "claim_id": "CP09-INHERITED-KEG-B2-R01-G07-1", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3303	audio_job	U-B1-018-AUD02	da61cc1c2e6d283044e508abde4c55ea2fb0f2b672279e0c88254e811ccf9b4c	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": {"status": "PROVIDER_OR_SPEAKER_EVIDENCE_REQUIRED"}, "licence": {"status": "UNRESOLVED_VOICE_AND_MEDIA_RIGHTS"}, "text_el": "Καλησπέρα σε όλους. Από την επόμενη εβδομάδα το εργαστήριο υπολογιστών θα λειτουργεί και κάθε Τετάρτη από τις πέντε μέχρι τις επτά το απόγευμα. Η αλλαγή γίνεται επειδή αρκετοί κάτοικοι εργάζονται το πρωί και δεν μπορούσαν να έρθουν. Το πρωινό πρόγραμμα της Δευτέρας δεν αλλάζει. Την Τετάρτη μπορείτε να εξασκηθείτε στην αποστολή μηνυμάτων και στη χρήση απλών ηλεκτρονικών φορμών. Δεν πρόκειται για μάθημα επισκευής υπολογιστών. Δεν χρειάζεται να φέρετε δικό σας υπολογιστή, γιατί υπάρχουν συσκευές στην αίθουσα. Χρειάζεται όμως να δηλώσετε συμμετοχή μέχρι τη Δευτέρα, ώστε να ξέρουμε πόσες θέσεις θα ετοιμάσουμε. Αν οι θέσεις γεμίσουν, θα επικοινωνήσουμε μαζί σας για μια άλλη ημέρα. Η συμμετοχή είναι δωρεάν. Για περισσότερες πληροφορίες ρωτήστε στη γραμματεία.", "version": "0.1.0", "audio_id": "U-B1-018-AUD02", "priority": 1, "register": "clear neutral standard Greek", "segments": [], "output_path": null, "speaker_role": ["Different generic voices for role-labelled dialogue; one voice otherwise; labels not spoken"], "verification": {"status": "NOT_EXECUTED"}, "measured_cues": [], "native_review": {"status": "PENDING", "reviewer": null}, "script_rights": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "speaking_rate": "Clear natural standard Greek appropriate to B1; retain meaningful pauses; no artificial word-by-word delivery; native editor approval required", "voice_profile": {"locale": "el-GR", "identity": "GENERIC_CONSENTED_VOICE_NO_PERSON_IMPERSONATION", "selection": "EXTERNAL_PRODUCER_REQUIRED"}, "state_evidence": {"status": "SCRIPT_ONLY"}, "task_alignment": [{"item_id": "U-B1-018-I03", "item_path": "GreekOS_Academic_Corpus/items/U-B1-018-I03.json", "cue_status": "UNMEASURED_NO_AUDIO", "item_sha256": "0652af4a4658bccbfeaf58002e4a48c2ac565223e6cc7b1857e09083097b005c", "text_alignment_status": "CURRENT_ITEM_REFERENCE_ONLY_NOT_ACOUSTICALLY_VERIFIED"}], "verification_hash": null, "actual_duration_ms": null, "source_script_path": "GreekOS_Audio_and_Speaking/assets/U-B1-018-AUD02.json", "planned_output_path": "AUDIO/media/U-B1-018-AUD02.wav", "production_segments": [{"end_ms": null, "text_el": "Καλησπέρα σε όλους. Από την επόμενη εβδομάδα το εργαστήριο υπολογιστών θα λειτουργεί και κάθε Τετάρτη από τις πέντε μέχρι τις επτά το απόγευμα. Η αλλαγή γίνεται επειδή αρκετοί κάτοικοι εργάζονται το πρωί και δεν μπορούσαν να έρθουν. Το πρωινό πρόγραμμα της Δευτέρας δεν αλλάζει. Την Τετάρτη μπορείτε να εξασκηθείτε στην αποστολή μηνυμάτων και στη χρήση απλών ηλεκτρονικών φορμών. Δεν πρόκειται για μάθημα επισκευής υπολογιστών. Δεν χρειάζεται να φέρετε δικό σας υπολογιστή, γιατί υπάρχουν συσκευές στην αίθουσα. Χρειάζεται όμως να δηλώσετε συμμετοχή μέχρι τη Δευτέρα, ώστε να ξέρουμε πόσες θέσεις θα ετοιμάσουμε. Αν οι θέσεις γεμίσουν, θα επικοινωνήσουμε μαζί σας για μια άλλη ημέρα. Η συμμετοχή είναι δωρεάν. Για περισσότερες πληροφορίες ρωτήστε στη γραμματεία.", "start_ms": null, "segment_id": "U-B1-018-AUD02-SEG001", "speaker_role": "narrator"}], "pronunciation_notes": "Preserve lexical stress, no emphasis leaking answer; evaluate actual audio", "script_version_hash": "79453b85a8ded4362824c8cffb93d29434b3fbaa1ebb450cc482f714de369c0e", "execution_script_txt": "AUDIO_EXECUTION_PACK/scripts/U-B1-018-AUD02.txt", "source_manifest_hash": "6e181e3cd39d24478225f9affb09bd30d3099bbceb1b1485ad37c840339e3b81",