2519	source_claim	CP09-INHERITED-KEG-B2-R01-G09-1	e5c4d09314304bd6d1c3099e9e071b270b35d39b8fe0c9afe29c36287727726e	\N	{"record": {"claim": "Existing source identifier association only; no new substantive claim or recent-usage assertion", "limits": "Source meaning, scope, currentness and rights still require academic review", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP09-INHERITED-KEG-B2-R01-G09-1", "item_ids": ["KEG-B2-R01-G09"], "source_id": "V241", "provenance": {"path": "GreekOS_B2_Exam_Bank/items/KEG-B2-R01-G09.json", "field": "source_refs", "sha256": "6a9f58c7212c9874c83d819cd37c238df941d49355b7fd4c4c7b6700cba80988"}}, "claim_id": "CP09-INHERITED-KEG-B2-R01-G09-1", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3305	audio_job	U-B1-018-AUD04	d87704cf7253d34a9021079c2842aaf6902c705421faacaeacc8fa450094c9b6	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": {"status": "PROVIDER_OR_SPEAKER_EVIDENCE_REQUIRED"}, "licence": {"status": "UNRESOLVED_VOICE_AND_MEDIA_RIGHTS"}, "text_el": "Καλησπέρα σε όλους. Από την επόμενη εβδομάδα το εργαστήριο υπολογιστών θα λειτουργεί και κάθε Τετάρτη από τις πέντε μέχρι τις επτά το απόγευμα. Η αλλαγή γίνεται επειδή αρκετοί κάτοικοι εργάζονται το πρωί και δεν μπορούσαν να έρθουν. Το πρωινό πρόγραμμα της Δευτέρας δεν αλλάζει. Την Τετάρτη μπορείτε να εξασκηθείτε στην αποστολή μηνυμάτων και στη χρήση απλών ηλεκτρονικών φορμών. Δεν πρόκειται για μάθημα επισκευής υπολογιστών. Δεν χρειάζεται να φέρετε δικό σας υπολογιστή, γιατί υπάρχουν συσκευές στην αίθουσα. Χρειάζεται όμως να δηλώσετε συμμετοχή μέχρι τη Δευτέρα, ώστε να ξέρουμε πόσες θέσεις θα ετοιμάσουμε. Αν οι θέσεις γεμίσουν, θα επικοινωνήσουμε μαζί σας για μια άλλη ημέρα. Η συμμετοχή είναι δωρεάν. Για περισσότερες πληροφορίες ρωτήστε στη γραμματεία.", "version": "0.1.0", "audio_id": "U-B1-018-AUD04", "priority": 1, "register": "clear neutral standard Greek", "segments": [], "output_path": null, "speaker_role": ["Different generic voices for role-labelled dialogue; one voice otherwise; labels not spoken"], "verification": {"status": "NOT_EXECUTED"}, "measured_cues": [], "native_review": {"status": "PENDING", "reviewer": null}, "script_rights": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "speaking_rate": "Clear natural standard Greek appropriate to B1; retain meaningful pauses; no artificial word-by-word delivery; native editor approval required", "voice_profile": {"locale": "el-GR", "identity": "GENERIC_CONSENTED_VOICE_NO_PERSON_IMPERSONATION", "selection": "EXTERNAL_PRODUCER_REQUIRED"}, "state_evidence": {"status": "SCRIPT_ONLY"}, "task_alignment": [{"item_id": "U-B1-018-I05", "item_path": "GreekOS_Academic_Corpus/items/U-B1-018-I05.json", "cue_status": "UNMEASURED_NO_AUDIO", "item_sha256": "c617236290a76ddce3c003147a522a5ffb3696228cf381db64f5266b62b5b909", "text_alignment_status": "CURRENT_ITEM_REFERENCE_ONLY_NOT_ACOUSTICALLY_VERIFIED"}], "verification_hash": null, "actual_duration_ms": null, "source_script_path": "GreekOS_Audio_and_Speaking/assets/U-B1-018-AUD04.json", "planned_output_path": "AUDIO/media/U-B1-018-AUD04.wav", "production_segments": [{"end_ms": null, "text_el": "Καλησπέρα σε όλους. Από την επόμενη εβδομάδα το εργαστήριο υπολογιστών θα λειτουργεί και κάθε Τετάρτη από τις πέντε μέχρι τις επτά το απόγευμα. Η αλλαγή γίνεται επειδή αρκετοί κάτοικοι εργάζονται το πρωί και δεν μπορούσαν να έρθουν. Το πρωινό πρόγραμμα της Δευτέρας δεν αλλάζει. Την Τετάρτη μπορείτε να εξασκηθείτε στην αποστολή μηνυμάτων και στη χρήση απλών ηλεκτρονικών φορμών. Δεν πρόκειται για μάθημα επισκευής υπολογιστών. Δεν χρειάζεται να φέρετε δικό σας υπολογιστή, γιατί υπάρχουν συσκευές στην αίθουσα. Χρειάζεται όμως να δηλώσετε συμμετοχή μέχρι τη Δευτέρα, ώστε να ξέρουμε πόσες θέσεις θα ετοιμάσουμε. Αν οι θέσεις γεμίσουν, θα επικοινωνήσουμε μαζί σας για μια άλλη ημέρα. Η συμμετοχή είναι δωρεάν. Για περισσότερες πληροφορίες ρωτήστε στη γραμματεία.", "start_ms": null, "segment_id": "U-B1-018-AUD04-SEG001", "speaker_role": "narrator"}], "pronunciation_notes": "Preserve lexical stress, no emphasis leaking answer; evaluate actual audio", "script_version_hash": "79453b85a8ded4362824c8cffb93d29434b3fbaa1ebb450cc482f714de369c0e", "execution_script_txt": "AUDIO_EXECUTION_PACK/scripts/U-B1-018-AUD04.txt", "source_manifest_hash": "476fb89c8004b401c1e95c809422b93c07875425ee80dae7a0960782afb63ce1",