2525	source_claim	CP09-INHERITED-KEG-B2-R01-M03-1	e5c2958af8e6eb4658a94e144faad403693e45320a85711500bd73fac4ec4489	\N	{"record": {"claim": "Existing source identifier association only; no new substantive claim or recent-usage assertion", "limits": "Source meaning, scope, currentness and rights still require academic review", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP09-INHERITED-KEG-B2-R01-M03-1", "item_ids": ["KEG-B2-R01-M03"], "source_id": "V241", "provenance": {"path": "GreekOS_B2_Exam_Bank/items/KEG-B2-R01-M03.json", "field": "source_refs", "sha256": "f45f79e1d0f468eb759f7077ddcb91fc651a7194e8ca54d1cb87f352141fb499"}}, "claim_id": "CP09-INHERITED-KEG-B2-R01-M03-1", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3311	audio_job	U-B1-019-AUD02	e1f7a2530d3ff0e4ddf7015f3e190f970fbef392bddc1382906ab48e3763282c	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": {"status": "PROVIDER_OR_SPEAKER_EVIDENCE_REQUIRED"}, "licence": {"status": "UNRESOLVED_VOICE_AND_MEDIA_RIGHTS"}, "text_el": "Δημοσιογράφος: Πώς ξεκίνησες να βοηθάς στη βιβλιοθήκη; Άννα: Στην αρχή πήγαινα μόνο για να δανειστώ βιβλία. Μια μέρα είδα μια ανακοίνωση για εθελοντές και μίλησα με την υπεύθυνη. Νόμιζα ότι θα χρειαζόταν να έρχομαι κάθε μέρα, αλλά μου εξήγησε ότι δύο ώρες την εβδομάδα ήταν αρκετές. Δημοσιογράφος: Ήταν εύκολη η πρώτη μέρα; Άννα: Όχι ακριβώς. Δεν ήξερα πού βρίσκονταν όλα τα βιβλία και φοβόμουν μήπως δώσω λάθος πληροφορία. Ένας άλλος εθελοντής μου έδειξε τον κατάλογο. Μετά από λίγες συναντήσεις ένιωθα πιο άνετα. Τώρα βοηθάω τους επισκέπτες να βρουν αυτό που ψάχνουν. Δημοσιογράφος: Θα το πρότεινες σε κάποιον άλλο; Άννα: Ναι, αρκεί να ρωτήσει πρώτα τι ακριβώς χρειάζεται. Δεν χρειάζεται να ξέρει τα πάντα από την πρώτη μέρα. Είναι όμως σημαντικό να ενημερώνει εγκαίρως αν δεν μπορεί να έρθει.", "version": "0.1.0", "audio_id": "U-B1-019-AUD02", "priority": 1, "register": "clear neutral standard Greek", "segments": [], "output_path": null, "speaker_role": ["Different generic voices for role-labelled dialogue; one voice otherwise; labels not spoken"], "verification": {"status": "NOT_EXECUTED"}, "measured_cues": [], "native_review": {"status": "PENDING", "reviewer": null}, "script_rights": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "speaking_rate": "Clear natural standard Greek appropriate to B1; retain meaningful pauses; no artificial word-by-word delivery; native editor approval required", "voice_profile": {"locale": "el-GR", "identity": "GENERIC_CONSENTED_VOICE_NO_PERSON_IMPERSONATION", "selection": "EXTERNAL_PRODUCER_REQUIRED"}, "state_evidence": {"status": "SCRIPT_ONLY"}, "task_alignment": [{"item_id": "U-B1-019-I03", "item_path": "GreekOS_Academic_Corpus/items/U-B1-019-I03.json", "cue_status": "UNMEASURED_NO_AUDIO", "item_sha256": "643c76b275d7985740b73c742cc46472edf5d848da26ace1ded668d061904b81", "text_alignment_status": "CURRENT_ITEM_REFERENCE_ONLY_NOT_ACOUSTICALLY_VERIFIED"}], "verification_hash": null, "actual_duration_ms": null, "source_script_path": "GreekOS_Audio_and_Speaking/assets/U-B1-019-AUD02.json", "planned_output_path": "AUDIO/media/U-B1-019-AUD02.wav", "production_segments": [{"end_ms": null, "text_el": "Πώς ξεκίνησες να βοηθάς στη βιβλιοθήκη;", "start_ms": null, "segment_id": "U-B1-019-AUD02-SEG001", "speaker_role": "Δημοσιογράφος"}, {"end_ms": null, "text_el": "Στην αρχή πήγαινα μόνο για να δανειστώ βιβλία. Μια μέρα είδα μια ανακοίνωση για εθελοντές και μίλησα με την υπεύθυνη. Νόμιζα ότι θα χρειαζόταν να έρχομαι κάθε μέρα, αλλά μου εξήγησε ότι δύο ώρες την εβδομάδα ήταν αρκετές.", "start_ms": null, "segment_id": "U-B1-019-AUD02-SEG002", "speaker_role": "Άννα"}, {"end_ms": null, "text_el": "Ήταν εύκολη η πρώτη μέρα;", "start_ms": null, "segment_id": "U-B1-019-AUD02-SEG003", "speaker_role": "Δημοσιογράφος"}, {"end_ms": null, "text_el": "Όχι ακριβώς. Δεν ήξερα πού βρίσκονταν όλα τα βιβλία και φοβόμουν μήπως δώσω λάθος πληροφορία. Ένας άλλος εθελοντής μου έδειξε τον κατάλογο. Μετά από λίγες συναντήσεις ένιωθα πιο άνετα. Τώρα βοηθάω τους επισκέπτες να βρουν αυτό που ψάχνουν.", "start_ms": null, "segment_id": "U-B1-019-AUD02-SEG004", "speaker_role": "Άννα"}, {"end_ms": null, "text_el": "Θα το πρότεινες σε κάποιον άλλο;", "start_ms": null, "segment_id": "U-B1-019-AUD02-SEG005", "speaker_role": "Δημοσιογράφος"}, {"end_ms": null, "text_el": "Ναι, αρκεί να ρωτήσει πρώτα τι ακριβώς χρειάζεται. Δεν χρειάζεται να ξέρει τα πάντα από την πρώτη μέρα. Είναι όμως σημαντικό να ενημερώνει εγκαίρως αν δεν μπορεί να έρθει.", "start_ms": null, "segment_id": "U-B1-019-AUD02-SEG006", "speaker_role": "Άννα"}], "pronunciation_notes": "Preserve lexical stress, no emphasis leaking answer; evaluate actual audio", "script_version_hash": "81e5903c21e2359a639b0cca319c770b73c7609af28c6f6969b32cad3a7fb7c9", "execution_script_txt": "AUDIO_EXECUTION_PACK/scripts/U-B1-019-AUD02.txt", "source_manifest_hash": "3e7e3a940504743714482bf269a224e2fe01c4b4de5c280d5502006af7b5a4cd", "source_manifest_path": "GreekOS_Audio_and_Speaking/assets/U-B1-019-AUD02.json", "planned_delivery_path": "AUDIO/media/U-B1-019-AUD02.mp3", "expected_prompt_context": {"unit_id": "U-B1-019", "task_ids": ["U-B1-019-I03"]}, "intonation_instructions": "Clear modern standard Greek; A1 deliberately slow with phrase pauses, A2 clear conversational phrasing. Read speakers as separate voices; do not read role labels. No answer-emphasis. Native review required.", "source_script_file_hash": "3e7e3a940504743714482bf269a224e2fe01c4b4de5c280d5502006af7b5a4cd", "production_segment_policy": "Only recognized role labels removed; punctuation inside utterances retained. Producer must confirm turn boundaries before recording. No role labels spoken. Timing fields deliberately null.", "execution_script_txt_sha256": "deddd3de021cf13473c40e4a71e500d642d56dbf09779d3636deac304f920414"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
