ώτα τι ακριβώς χρειάζεται. Δεν χρειάζεται να ξέρει τα πάντα από την πρώτη μέρα. Είναι όμως σημαντικό να ενημερώνει εγκαίρως αν δεν μπορεί να έρθει.", "start_ms": null, "segment_id": "U-B1-019-AUD05-SEG006", "speaker_role": "Άννα"}], "pronunciation_notes": "Preserve lexical stress, no emphasis leaking answer; evaluate actual audio", "script_version_hash": "81e5903c21e2359a639b0cca319c770b73c7609af28c6f6969b32cad3a7fb7c9", "execution_script_txt": "AUDIO_EXECUTION_PACK/scripts/U-B1-019-AUD05.txt", "source_manifest_hash": "23da35029214aeb355ee8a44c79ee0bff247682671a5f4dbd3e84e65d2963014", "source_manifest_path": "GreekOS_Audio_and_Speaking/assets/U-B1-019-AUD05.json", "planned_delivery_path": "AUDIO/media/U-B1-019-AUD05.mp3", "expected_prompt_context": {"unit_id": "U-B1-019", "task_ids": ["U-B1-019-I06"]}, "intonation_instructions": "Clear modern standard Greek; A1 deliberately slow with phrase pauses, A2 clear conversational phrasing. Read speakers as separate voices; do not read role labels. No answer-emphasis. Native review required.", "source_script_file_hash": "23da35029214aeb355ee8a44c79ee0bff247682671a5f4dbd3e84e65d2963014", "production_segment_policy": "Only recognized role labels removed; punctuation inside utterances retained. Producer must confirm turn boundaries before recording. No role labels spoken. Timing fields deliberately null.", "execution_script_txt_sha256": "deddd3de021cf13473c40e4a71e500d642d56dbf09779d3636deac304f920414"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
