1902	source_claim	CP08-INHERITED-U-B1-012-I01-02	26e623fec89534989af77cb4a9f19c8e19f10543542da66ee74a21aefd09226c	\N	{"record": {"claim": ["Restrictive versus supplementary relative clauses and comma distinction"], "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP08-INHERITED-U-B1-012-I01-02", "item_ids": ["U-B1-012-I01"], "source_id": "N404", "provenance": {"path": "GreekOS_Academic_Corpus/items/U-B1-012-I01.json", "sha256": "780b1ccbe447408e59491844adb5eb9471beadaa43a8ced128bc7d3bef321146"}, "limitations": "Registration closes a missing identifier only. No new source reading, rights clearance, whole-item correctness, current legal validity or AUTH endorsement inferred.", "original_source_ref": {"anchor": "§5.2γ lines 53–55", "source_id": "N404", "checked_on": "2026-10-19", "claim_scope": ["Restrictive versus supplementary relative clauses and comma distinction"], "evidence_type": "OFFICIAL_GRAMMAR_OR_DICTIONARY", "evidence_record": "B06-S04", "evidence_status": "SOURCE_PASS_BOUNDED_CLAIMS"}}, "claim_id": "CP08-INHERITED-U-B1-012-I01-02", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
2716	competency	A2-L01	f87fc43d33eadf60bb1a1e20d4aac08a710613efa19f3f769ba8da0ef17f900f	core	{"name": "Короткий бытовой диалог в ясной стандартной речи", "level": "A2", "competency_id": "A2-L01", "prerequisites": ["A1-L01", "A2-V01"], "content_complete": false, "primary_unit_ids": ["U-A2-017"], "incidental_unit_ids": ["U-A2-017"], "current_coverage_status": "PARTIAL_AUTHORED_NOT_RELEASED", "coverage_status_at_baseline": "NOT_AUTHORED"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3320	audio_job	U-B2-012-AUD01	dfc7f298f3b9706f986ac995ebde864490c4b35dc8bfd67d95179d2d2030189b	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": {"status": "EVIDENCE_REQUIRED"}, "licence": {"status": "UNRESOLVED_VOICE_AND_MEDIA_RIGHTS"}, "text_el": "Καλησπέρα σας. Θα σας παρουσιάσω την πρόταση για ένα μικρό εργαστήριο επισκευής στη δημοτική βιβλιοθήκη της φανταστικής μας πόλης. Δεν πρόκειται για κατάστημα ούτε για υπηρεσία που αναλαμβάνει κάθε βλάβη. Στόχος είναι οι κάτοικοι να μάθουν να φροντίζουν απλά αντικείμενα και να ανταλλάσσουν εμπειρίες, με τη βοήθεια εθελοντών.\\nΗ πρώτη σκέψη ήταν να συναντιόμαστε κάθε Σάββατο. Ύστερα από συζήτηση με το προσωπικό, προτιμήσαμε δύο Τετάρτες τον μήνα, επειδή το Σάββατο ο χώρος χρησιμοποιείται ήδη για παιδικές δραστηριότητες. Αυτό δεν σημαίνει ότι οι οικογένειες αποκλείονται. Σημαίνει ότι πρέπει να βρούμε ώρες που δεν δημιουργούν σύγκρουση με το υπάρχον πρόγραμμα. Η δοκιμή θα διαρκέσει τρεις μήνες. Μετά θα εξετάσουμε αν αξίζει να συνεχιστεί.\\nΓια να έρθει κάποιος, θα χρειάζεται να δηλώσει συμμετοχή και να περιγράψει το αντικείμενο που θέλει να φέρει. Η δήλωση δεν θα αποτελεί εγγύηση ότι το αντικείμενο μπορεί να επισκευαστεί. Θα βοηθά απλώς τους εθελοντές να προετοιμάσουν τα κατάλληλα εργαλεία. Δεν θα δεχόμαστε ηλεκτρικές συσκευές σε αυτή την πρώτη φάση. Μπορούμε, για παράδειγμα, να δουλέψουμε με ένα ρούχο που χρειάζεται ράψιμο ή με ένα μικρό ξύλινο αντικείμενο, εφόσον η εργασία είναι απλή και ασφαλής.\\nΑκούστηκε η άποψη ότι θα ήταν καλύτερο να αγοράσουμε αμέσως πολλά καινούρια εργαλεία. Προσωπικά προτείνω το αντίθετο: να καταγράψουμε πρώτα τι υπάρχει και τι μπορεί να δανειστεί η ομάδα. Αν διαπιστώσουμε συγκεκριμένες ανάγκες, τότε να ζητήσουμε χρηματοδότηση. Διαφορετικά κινδυνεύουμε να ξοδέψουμε χρήματα για εξοπλισμό που θα μείνει σε ένα ντουλάπι. Βέβαια, ο δανεισμός έχει και δυσκολίες. Κάποιος πρέπει να ελέγχει την κατάσταση των εργαλείων και να καταγράφει τις επιστροφές.\\nΈνα άλλο ζήτημα είναι πώς θα κρίνουμε την επιτυχία. Ο αριθμός των επισκεπτών έχει ενδιαφέρον, αλλά δεν αρκεί. Θέλουμε να ξέρουμε αν οι άνθρωποι έμαθαν κάτι που μπορούν να εφαρμόσουν μόνοι τους και αν νιώθουν ότι μπορούν να συμμετέχουν ξανά. Στο τέλος κάθε συνάντησης θα ζητάμε ένα σύντομο σχόλιο. Δεν θα ζητάμε από τους συμμετέχοντες να δηλώνουν εισόδημα ή άλλες προσωπικές πληροφορίες που δεν χρειάζονται για τη δραστηριότητα.\\nΤέλος, χρειάζεται να είμαστε προσεκτικοί με τις προσδοκίες. Δεν μπορούμε ακόμη να υποσχεθούμε πόσα αντικείμενα θα σωθούν από τα απορρίμματα. Μπορούμε όμως να καταγράφουμε τι επισκευάστηκε, τι δεν ήταν δυνατό να επισκευαστεί και για ποιον λόγο. Αν τα στοιχεία δείξουν ότι το πρόγραμμα προσφέρει ουσιαστική βοήθεια χωρίς υπερβολικό βάρος για το προσωπικό, θα προτείνουμε τη συνέχισή του. Αν όχι, θα αλλάξουμε τον τρόπο λειτουργίας ή θα σταματήσουμε. Μια δοκιμή έχει αξία και όταν μας δείχνει τι πρέπει να διορθώσουμε.", "version": "0.1.0", "audio_id": "U-B2-012-AUD01", "priority": "CORE_AFTER_L01", "register": "standard neutral Greek", "segments": [], "output_path": null, "speaker_role": ["narrator"], "verification": {"status": "NOT_EXECUTED"}, "measured_cues": [], "native_review": {"status": "PENDING", "reviewer": null}, "script_rights": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "speaking_rate": "Natural B2 for developed talk; B1 diagnostic and prosody at clear natural pace. No measured rate until recorded.", "voice_profile": {"locale": "el-GR", "identity": "GENERIC_CONSENTED_VOICE", "selection": "PRODUCER_NATIVE_APPROVAL_REQUIRED"}, "state_evidence": {"status": "SCRIPT_ONLY"}, "task_alignment": [{"item_id