3321	audio_job	U-B2-012-AUD02	7dbc7d6802304bf6a7d110cdb9b9228386d5ad065eb82aa926c34a2132efc2b2	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": {"status": "EVIDENCE_REQUIRED"}, "licence": {"status": "UNRESOLVED_VOICE_AND_MEDIA_RIGHTS"}, "text_el": "Η ομάδα του κήπου προτείνει να ανοίγει ο χώρος δύο απογεύματα την εβδομάδα. Αρχικά συζητήθηκε καθημερινή λειτουργία, αλλά οι διαθέσιμοι εθελοντές δεν επαρκούν. Η συμμετοχή θα είναι δωρεάν. Όποιος θέλει μπορεί να φέρει σπόρους, χωρίς αυτό να αποτελεί προϋπόθεση εισόδου. Μετά από έξι εβδομάδες θα εξετάσουμε αν οι επισκέπτες μπορούν να φροντίζουν τα φυτά χωρίς συνεχή βοήθεια. Δεν έχουμε ακόμη στοιχεία για εξοικονόμηση νερού. Θα αρχίσουμε να καταγράφουμε την κατανάλωση από την πρώτη εβδομάδα.", "version": "0.1.0", "audio_id": "U-B2-012-AUD02", "priority": "CORE_AFTER_L01", "register": "standard neutral Greek", "segments": [], "output_path": null, "speaker_role": ["narrator"], "verification": {"status": "NOT_EXECUTED"}, "measured_cues": [], "native_review": {"status": "PENDING", "reviewer": null}, "script_rights": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "speaking_rate": "Natural B2 for developed talk; B1 diagnostic and prosody at clear natural pace. No measured rate until recorded.", "voice_profile": {"locale": "el-GR", "identity": "GENERIC_CONSENTED_VOICE", "selection": "PRODUCER_NATIVE_APPROVAL_REQUIRED"}, "state_evidence": {"status": "SCRIPT_ONLY"}, "task_alignment": [{"item_id": "U-B2-012-I11", "item_path": "GreekOS_Academic_Corpus/items/U-B2-012-I11.json", "cue_status": "UNMEASURED_NO_AUDIO", "item_sha256": "77be8eec8c8864725ec8d6e9b91a72c158ffd73353cd9569b7dae2143b6820fe", "text_alignment_status": "CURRENT_ITEM_REFERENCE_ONLY_NOT_ACOUSTICALLY_VERIFIED"}], "verification_hash": null, "actual_duration_ms": null, "source_script_path": "GreekOS_Audio_and_Speaking/assets/U-B2-012-AUD02.json", "planned_output_path": "AUDIO/media/U-B2-012-AUD02.wav", "production_segments": [{"end_ms": null, "text_el": "Η ομάδα του κήπου προτείνει να ανοίγει ο χώρος δύο απογεύματα την εβδομάδα. Αρχικά συζητήθηκε καθημερινή λειτουργία, αλλά οι διαθέσιμοι εθελοντές δεν επαρκούν. Η συμμετοχή θα είναι δωρεάν. Όποιος θέλει μπορεί να φέρει σπόρους, χωρίς αυτό να αποτελεί προϋπόθεση εισόδου. Μετά από έξι εβδομάδες θα εξετάσουμε αν οι επισκέπτες μπορούν να φροντίζουν τα φυτά χωρίς συνεχή βοήθεια. Δεν έχουμε ακόμη στοιχεία για εξοικονόμηση νερού. Θα αρχίσουμε να καταγράφουμε την κατανάλωση από την πρώτη εβδομάδα.", "start_ms": null, "segment_id": "U-B2-012-AUD02-SEG001", "speaker_role": "narrator"}], "pronunciation_notes": "Preserve Greek lexical stress; no answer-leaking emphasis except explicitly assessed contrast, which requires blind native validation.", "script_version_hash": "e1a46354ba3220087d77ef84cdc077cbcaa5d8bfa65aab47e1c6a36eb1022f8a", "execution_script_txt": "AUDIO_EXECUTION_PACK/scripts/U-B2-012-AUD02.txt", "source_manifest_hash": "23066795a2f852fb282be227659ad50c462b3d6f5db6f0bb209b4cda8eeaf32d", "source_manifest_path": "GreekOS_Audio_and_Speaking/assets/U-B2-012-AUD02.json", "planned_delivery_path": "AUDIO/media/U-B2-012-AUD02.mp3", "expected_prompt_context": {"unit_id": "U-B2-012", "task_ids": ["U-B2-012-I11"]}, "intonation_instructions": "Different generic speaker from main recording; natural standard Greek. No music/noise. Keep optional seed donation distinct from entry condition.", "source_script_file_hash": "23066795a2f852fb282be227659ad50c462b3d6f5db6f0bb209b4cda8eeaf32d", "production_segment_policy": "Only recognized role labels removed; punctuation inside utterances retained. Producer must conf