2541	source_claim	CP09-INHERITED-KEG-B2-U01-C2-1	1488031c9a6ca7466515850569a7ac37f660ba8f7e336825d90d9c68d34aefee	\N	{"record": {"claim": "Existing source identifier association only; no new substantive claim or recent-usage assertion", "limits": "Source meaning, scope, currentness and rights still require academic review", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP09-INHERITED-KEG-B2-U01-C2-1", "item_ids": ["KEG-B2-U01-C2"], "source_id": "V241", "provenance": {"path": "GreekOS_B2_Exam_Bank/items/KEG-B2-U01-C2.json", "field": "source_refs", "sha256": "30f8442aff1e4cc18a8317d53d4c361bdd0dc21ab90a9c306b8528daeb14ff95"}}, "claim_id": "CP09-INHERITED-KEG-B2-U01-C2-1", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3324	audio_job	U-B2-015-AUD01	87fffcafa64af9cc6f6809d52922453d889c24f21284c0fccbc5e70611d0bafe	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": {"status": "EVIDENCE_REQUIRED"}, "licence": {"status": "UNRESOLVED_VOICE_AND_MEDIA_RIGHTS"}, "text_el": "Άννα: Ευχαριστώ που ήρθατε. Πρέπει να προτείνουμε πώς θα λειτουργήσει η αίθουσα της γειτονιάς τον επόμενο μήνα. Έχουμε δύο ελεύθερα απογεύματα, την Τρίτη και την Πέμπτη. Αρχικά σκέφτηκα να κάνουμε προβολές ταινιών και τις δύο ημέρες, αλλά θα ήθελα να ακούσω τις ανάγκες σας πριν αποφασίσουμε.\\nΜάνος: Οι προβολές είναι ωραία ιδέα, όμως υπάρχουν μαθητές που ψάχνουν ήσυχο χώρο για διάβασμα. Στο σπίτι δεν έχουν όλοι δικό τους δωμάτιο. Θα πρότεινα η Τρίτη να μείνει για ατομική μελέτη. Δεν χρειάζεται να αγοράσουμε πολλά πράγματα· υπάρχουν ήδη τραπέζια και καρέκλες.\\nΕλένη: Συμφωνώ ότι η μελέτη είναι σημαντική, αλλά θέλω να προσέξουμε τον φωτισμό. Δύο λάμπες δεν λειτουργούν. Αν δεν επισκευαστούν, δεν θα έλεγα ότι ο χώρος είναι έτοιμος. Επίσης, όποιος αναλάβει την επίβλεψη πρέπει να ξέρει πού βρίσκονται τα κλειδιά και πώς κλείνει το κτίριο.\\nΠέτρος: Εγώ μπορώ να βοηθήσω την Τρίτη, όχι όμως κάθε εβδομάδα. Η δουλειά μου αλλάζει ωράριο. Αν στηριχτούμε μόνο σε εμένα, κάποια μέρα μπορεί να μη βρεθεί κανείς να ανοίξει. Θα προτιμούσα να υπάρχει δεύτερος υπεύθυνος και ένα κοινό πρόγραμμα, το οποίο να ελέγχουμε λίγες ημέρες πριν.\\nΆννα: Άρα δεν αρκεί να διαλέξουμε δραστηριότητα. Πρέπει να εξασφαλίσουμε και ότι ο χώρος θα ανοίγει κανονικά. Για την Πέμπτη θα μπορούσαμε να κρατήσουμε μια πολιτιστική δραστηριότητα. Τι θα λέγατε για συζήτηση γύρω από μια ταινία, χωρίς δυνατή μουσική μετά;\\nΜάνος: Αυτό μου φαίνεται πιο λογικό από δύο ίδιες βραδιές. Θα ήθελα όμως να μην αλλάζει η χρήση της Τρίτης τελευταία στιγμή. Αν οι μαθητές υπολογίζουν ότι θα διαβάσουν εδώ, μια ξαφνική προβολή θα τους δημιουργήσει πρόβλημα. Οι αλλαγές πρέπει να ανακοινώνονται εγκαίρως.\\nΕλένη: Δεν έχω αντίρρηση για την Πέμπτη. Προτείνω μόνο να αρχίσουμε με μία δοκιμαστική συνάντηση. Δεν ξέρουμε ακόμη πόσοι θα έρθουν ούτε αν ο προβολέας λειτουργεί σωστά. Μπορώ να τον ελέγξω αύριο, αλλά δεν μπορώ να αναλάβω όλες τις τεχνικές ανάγκες του μήνα.\\nΠέτρος: Αν γίνει δοκιμή, θα μπορούσαμε να ζητήσουμε σύντομα σχόλια. Όχι μόνο αν άρεσε η ταινία, αλλά αν η ώρα και ο χώρος ήταν κατάλληλα. Και για τη μελέτη θα ήταν χρήσιμο να ακούσουμε όσους ήρθαν αλλά δεν βρήκαν θέση. Αλλιώς θα μετράμε μόνο τους ικανοποιημένους.\\nΆννα: Να συνοψίσω λοιπόν την πρόταση, όχι να την παρουσιάσω ως οριστική απόφαση. Την Τρίτη προτείνουμε μελέτη, εφόσον διορθωθεί ο φωτισμός και βρεθούν δύο υπεύθυνοι. Την Πέμπτη προτείνουμε μία δοκιμαστική πολιτιστική συνάντηση, αφού ελεγχθεί ο προβολέας. Θα στείλουμε το σχέδιο στην επιτροπή του κτιρίου για έγκριση.\\nΜάνος: Συμφωνώ με αυτή τη διατύπωση. Να γράψουμε καθαρά ότι περιμένουμε έγκριση, για να μην εμφανιστούν άνθρωποι πριν είμαστε έτοιμοι.\\nΕλένη: Θα στείλω αύριο το αποτέλεσμα του τεχνικού ελέγχου. Αν υπάρχει σοβαρή βλάβη, θα χρειαστούμε άλλη λύση.\\nΠέτρος: Κι εγώ θα ρωτήσω ποιος μπορεί να μοιραστεί την επίβλεψη. Μέχρι να έχουμε απάντηση, ας μην υποσχεθούμε συγκεκριμένη ημερομηνία έναρξης.", "version": "0.1.0", "audio_id": "U-B2-015-AUD01", "priority": "CORE_AFTER_L01", "register": "standard neutral Greek", "segments": [], "output_path": null, "speaker_role": ["Άννα", "Μάνος", "Ελένη", "Πέτρος"], "verification": {"status": "NOT_EXECUTED"}, "measured_cues": [], "native_review": {"status": "PENDING", "reviewer": null}, "script_rights": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "speaking_rate": "Natural B2 for developed talk; B1 diagnostic and prosody at clear natural pace. No measured rate until recorded.", "voice_profile": {"locale": "el-GR", "identity": "GENERIC_CONSENTED_VOICE", "selection": "PRODUCER_NATIVE_APPROVAL_REQUIRED"}, "state_evidence": {"status": "SCRIPT_ONLY"}, "task_alignment": [{"item_id": "U-B2-015-I02", "item_path": "GreekOS_Academic_Corpus/items/U-B2-015-I02.json", "cue_status": "UNMEASURED_NO_AUDIO", "item_sha256": "ba256de38f0c20ecef43445b68f336bc21a33c87d026520e9e522ce615160f71", "text_alignment_status": "CURRENT_ITEM_REFERENCE_ONLY_NOT_ACOUSTICALLY_VERIFIED"}, {"item_id": "U-B2-015-I03", "item_path": "GreekOS_Academic_Corpus/items/U-B2-015-I03.json", "cue_status": "UNMEASURED_NO_AUDIO", "item_sha256": "1f4beb454bc9797bb8423049699ea42529c064cb67e2be699c51b18d491cd689", "text_alignment_status": "CURRENT_ITEM_REFERENCE_ONLY_NOT_ACOUSTICALLY_VERIFIED"}, {"item_id": "U-B2-015-I04", "item_path": "GreekOS_Academic_Corpus/items/U-B2-015-I04.json", "cue_status": "UNMEASURED_NO_AUDIO", "item_sha256": "bd73fef2d7c37b3c7c71bdb3562c2c084f1ddd21422ca0721dcdcb3232ca0295", "text_alignment_status": "CURRENT_ITEM_REFERENCE_ONLY_NOT_ACOUSTICALLY_VERIFIED"}, {"item_id": "U-B2-015-I05", "item_path": "GreekOS_Academic_Corpus/items/U-B2-015-I05.json", "cue_status": "UNMEASURED_NO_AUDIO", "item_sha256": "61afa68cd4a65b46acb98d34a70401dc043c5a58eae90a79b80c0c1c040c0b01", "text_alignment_status": "CURRENT_ITEM_REFERENCE_ONLY_NOT_ACOUSTICALLY_VERIFIED"}, {"item_id": "U-B2-015-I06", "item_path": "GreekOS_Academic_Corpus/items/U-B2-015-I06.json", "cue_status": "UNMEASURED_NO_AUDIO", "item_sha256": "a2bd698ed782a21f37d2e828bbc220014a73e80e3e66fdff5cc7a518c1c8fffe", "text_alignment_status": "CURRENT_ITEM_REFERENCE_ONLY_NOT_ACOUSTICALLY_VERIFIED"}, {"item_id": "U-B2-015-I07", "item_path": "GreekOS_Academic_Corpus/items/U-B2-015-I07.json", "cue_status": "UNMEASURED_NO_AUDIO", "item_sha256": "242646df5ab287d366f3f255e9b11a7e3c4d2ba3832840271ae499f51120a363", "text_alignment_status": "CURRENT_ITEM_REFERENCE_ONLY_NOT_ACOUSTICALLY_VERIFIED"}, {"item_id": "U-B2-015-I08", "item_path": "GreekOS_Academic_Corpus/items/U-B2-015-I08.json", "cue_status": "UNMEASURED_NO_AUDIO", "item_sha256": "fdf05bc69debc597a7d3e429d6e9584fb5f4cde4237c2b9bf5557c1bc058c3a5", "text_alignment_status": "CURRENT_ITEM_REFERENCE_ONLY_NOT_ACOUSTICALLY_VERIFIED"}], "verification_hash": null, "actual_duration_ms": null, "source_script_path": "GreekOS_Audio_and_Speaking/assets/U-B2-015-AUD01.json", "planned_output_path": "AUDIO/media/U-B2-015-AUD01.wav", "production_segments": [{"end_ms": null, "text_el": "Ευχαριστώ που ήρθατε. Πρέπει να προτείνουμε πώς θα λειτουργήσει η αίθουσα της γειτονιάς τον επόμενο μήνα. Έχουμε δύο ελεύθερα απογεύματα, την Τρίτη και την Πέμπτη. Αρχικά σκέφτηκα να κάνουμε προβολές ταινιών και τις δύο ημέρες, αλλά θα ήθελα να ακούσω τις ανάγκες σας πριν αποφασίσουμε.", "start_ms": null, "segment_id": "U-B2-015-AUD01-SEG001", "speaker_role": "Άννα"}, {"end_ms": null, "text_el": "Οι προβολές είναι ωραία ιδέα, όμως υπάρχουν μαθητές που ψάχνουν ήσυχο χώρο για διάβασμα. Στο σπίτι δεν έχουν όλοι δικό τους δωμάτιο. Θα πρότεινα η Τρίτη να μείνει για ατομική μελέτη. Δεν χρειάζεται να αγοράσουμε πολλά πράγματα· υπάρχουν ήδη τραπέζια και καρέκλες.", "start_ms": null, "segment_id": "U-B2-015-AUD01-SEG002", "speaker_role": "Μάνος"}, {"end_ms": null, "text_el": "Συμφωνώ ότι η μελέτη είναι σημαντική, αλλά θέλω να προσέξουμε τον φωτισμό. Δύο λάμπες δεν λειτουργούν. Αν δεν επισκευαστούν, δεν θα έλεγα ότι ο χώρος είναι έτοιμος. Επίσης, όποιος αναλάβει την επίβλεψη πρέπει να ξέρει πού βρίσκονται τα κλειδιά και πώς κλείνει το κτίριο.", "start_ms": null, "segment_id": "U-B2-015-AUD01-SEG003", "speaker_role": "Ελένη"}, {"end_ms": null, "text_el": "Εγώ μπορώ να βοηθήσω την Τρίτη, όχι όμως κάθε εβδομάδα. Η δουλειά μου αλλάζει ωράριο. Αν στηριχτούμε μόνο σε εμένα, κάποια μέρα μπορεί να μη βρεθεί κανείς να ανοίξει. Θα προτιμούσα να υπάρχει δεύτερος υπεύθυνος και ένα κοινό πρόγραμμα, το οποίο να ελέγχουμε λίγες ημέρες πριν.", "start_ms": null, "segment_id": "U-B2-015-AUD01-SEG004", "speaker_role": "Πέτρος"}, {"end_ms": null, "text_el": "Άρα δεν αρκεί να διαλέξουμε δραστηριότητα. Πρέπει να εξασφαλίσουμε και ότι ο χώρος θα ανοίγει κανονικά. Για την Πέμπτη θα μπορούσαμε να κρατήσουμε μια πολιτιστική δραστηριότητα. Τι θα λέγατε για συζήτηση γύρω από μια ταινία, χωρίς δυνατή μουσική μετά;", "start_ms": null, "segment_id": "U-B2-015-AUD01-SEG005", "speaker_role": "Άννα"}, {"end_ms": null, "text_el": "Αυτό μου φαίνεται πιο λογικό από δύο ίδιες βραδιές. Θα ήθελα όμως να μην αλλάζει η χρήση της Τρίτης τελευταία στιγμή. Αν οι μαθητές υπολογίζουν ότι θα διαβάσουν εδώ, μια ξαφνική προβολή θα τους δημιουργήσει πρόβλημα. Οι αλλαγές πρέπει να ανακοινώνονται εγκαίρως.", "start_ms": null, "segment_id": "U-B2-015-AUD01-SEG006", "speaker_role": "Μάνος"}, {"end_ms": null, "text_el": "Δεν έχω αντίρρηση για την Πέμπτη. Προτείνω μόνο να αρχίσουμε με μία δοκιμαστική συνάντηση. Δεν ξέρουμε ακόμη πόσοι θα έρθουν ούτε αν ο προβολέας λειτουργεί σωστά. Μπορώ να τον ελέγξω αύριο, αλλά δεν μπορώ να αναλάβω όλες τις τεχνικές ανάγκες του μήνα.", "start_ms": null, "segment_id": "U-B2-015-AUD01-SEG007", "speaker_role": "Ελένη"}, {"end_ms": null, "text_el": "Αν γίνει δοκιμή, θα μπορούσαμε να ζητήσουμε σύντομα σχόλια. Όχι μόνο αν άρεσε η ταινία, αλλά αν η ώρα και ο χώρος ήταν κατάλληλα. Και για τη μελέτη θα ήταν χρήσιμο να ακούσουμε όσους ήρθαν αλλά δεν βρήκαν θέση. Αλλιώς θα μετράμε μόνο τους ικανοποιημένους.", "start_ms": null, "segment_id": "U-B2-015-AUD01-SEG008", "speaker_role": "Πέτρος"}, {"end_ms": null, "text_el": "Να συνοψίσω λοιπόν την πρόταση, όχι να την παρουσιάσω ως οριστική απόφαση. Την Τρίτη προτείνουμε μελέτη, εφόσον διορθωθεί ο φωτισμός και βρεθούν δύο υπεύθυνοι. Την Πέμπτη προτείνουμε μία δοκιμαστική πολιτιστική συνάντηση, αφού ελεγχθεί ο προβολέας. Θα στείλουμε το σχέδιο στην επιτροπή του κτιρίου για έγκριση.", "start_ms": null, "segment_id": "U-B2-015-AUD01-SEG009", "speaker_role": "Άννα"}, {"end_ms": null, "text_el": "Συμφωνώ με αυτή τη διατύπωση. Να γράψουμε καθαρά ότι περιμένουμε έγκριση, για να μην εμφανιστούν άνθρωποι πριν είμαστε έτοιμοι.", "start_ms": null, "segment_id": "U-B2-015-AUD01-SEG010", "speaker_role": "Μάνος"}, {"end_ms": null, "text_el": "Θα στείλω αύριο το αποτέλεσμα του τεχνικού ελέγχου. Αν υπάρχει σοβαρή βλάβη, θα χρειαστούμε άλλη λύση.", "start_ms": null, "segment_id": "U-B2-015-AUD01-SEG011", "speaker_role": "Ελένη"}, {"end_ms": null, "text_el": "Κι εγώ θα ρωτήσω ποιος μπορεί να μοιραστεί την επίβλεψη. Μέχρι να έχουμε απάντηση, ας μην υποσχεθούμε συγκεκριμένη ημερομηνία έναρξης.", "start_ms": null, "segment_id": "U-B2-015-AUD01-SEG012", "speaker_role": "Πέτρος"}], "pronunciation_notes": "Preserve Greek lexical stress; no answer-leaking emphasis except explicitly assessed contrast, which requires blind native validation.", "script_version_hash": "8fe3ae277fb2cb92dbba54dc7fa0962aaf2a2bb84f4e2a656941b5e6540a97ac", "execution_script_txt": "AUDIO_EXECUTION_PACK/scripts/U-B2-015-AUD01.txt", "source_manifest_hash": "6f72754b72cfa1c99adc56b0b7c30c3460ad667058037727bc4d93009829b174", "source_manifest_path": "GreekOS_Audio_and_Speaking/assets/U-B2-015-AUD01.json", "planned_delivery_path": "AUDIO/media/U-B2-015-AUD01.mp3", "expected_prompt_context": {"unit_id": "U-B2-015", "task_ids": ["U-B2-015-I02", "U-B2-015-I03", "U-B2-015-I04", "U-B2-015-I05", "U-B2-015-I06", "U-B2-015-I07", "U-B2-015-I08"]}, "intonation_instructions": "Four clearly distinct generic adult voices, standard Greek, natural B2 pace. Role labels not spoken. Preserve partial agreements/conditions. Clean non-overlapping turns; blind speaker attribution and every task audited by native reviewer.", "source_script_file_hash": "6f72754b72cfa1c99adc56b0b7c30c3460ad667058037727bc4d93009829b174", "production_segment_policy": "Only recognized role labels removed; punctuation inside utterances retained. Producer must confirm turn boundaries before recording. No role labe