3325	audio_job	U-B2-015-AUD02	f7e4e55a7c215322fcc185cc7079593dd8cf44eac0ac768659d4800c991395ba	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": {"status": "EVIDENCE_REQUIRED"}, "licence": {"status": "UNRESOLVED_VOICE_AND_MEDIA_RIGHTS"}, "text_el": "Λένα: Για την εκδρομή προτείνω να φύγουμε στις οκτώ, ώστε να έχουμε χρόνο για περπάτημα. Νίκος: Εγώ μπορώ μόνο μετά τις εννέα. Αν φύγετε νωρίτερα, θα έρθω μόνος μου. Σοφία: Δεν με απασχολεί τόσο η ώρα, όσο η επιστροφή. Πρέπει να είμαι πίσω πριν από τις έξι. Άρης: Πριν κλείσουμε μεταφορά, ας δούμε τον καιρό. Αν προβλέπεται δυνατή βροχή, προτείνω να αναβάλουμε. Λένα: Άρα δεν έχουμε ακόμη κοινή ώρα αναχώρησης. Θα ελέγξω πρώτα τον καιρό και μετά θα σας στείλω δύο επιλογές. Νίκος: Εντάξει, απλώς κρατήστε ότι πριν από τις εννέα δεν μπορώ.", "version": "0.1.0", "audio_id": "U-B2-015-AUD02", "priority": "CORE_AFTER_L01", "register": "standard neutral Greek", "segments": [], "output_path": null, "speaker_role": ["Λένα", "Νίκος", "Σοφία", "Άρης"], "verification": {"status": "NOT_EXECUTED"}, "measured_cues": [], "native_review": {"status": "PENDING", "reviewer": null}, "script_rights": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "speaking_rate": "Natural B2 for developed talk; B1 diagnostic and prosody at clear natural pace. No measured rate until recorded.", "voice_profile": {"locale": "el-GR", "identity": "GENERIC_CONSENTED_VOICE", "selection": "PRODUCER_NATIVE_APPROVAL_REQUIRED"}, "state_evidence": {"status": "SCRIPT_ONLY"}, "task_alignment": [{"item_id": "U-B2-015-I11", "item_path": "GreekOS_Academic_Corpus/items/U-B2-015-I11.json", "cue_status": "UNMEASURED_NO_AUDIO", "item_sha256": "e875492d61650a4aac0200b165000619d68b8ee79631ab38dd23d09bd7688bf1", "text_alignment_status": "CURRENT_ITEM_REFERENCE_ONLY_NOT_ACOUSTICALLY_VERIFIED"}], "verification_hash": null, "actual_duration_ms": null, "source_script_path": "GreekOS_Audio_and_Speaking/assets/U-B2-015-AUD02.json", "planned_output_path": "AUDIO/media/U-B2-015-AUD02.wav", "production_segments": [{"end_ms": null, "text_el": "Για την εκδρομή προτείνω να φύγουμε στις οκτώ, ώστε να έχουμε χρόνο για περπάτημα.", "start_ms": null, "segment_id": "U-B2-015-AUD02-SEG001", "speaker_role": "Λένα"}, {"end_ms": null, "text_el": "Εγώ μπορώ μόνο μετά τις εννέα. Αν φύγετε νωρίτερα, θα έρθω μόνος μου.", "start_ms": null, "segment_id": "U-B2-015-AUD02-SEG002", "speaker_role": "Νίκος"}, {"end_ms": null, "text_el": "Δεν με απασχολεί τόσο η ώρα, όσο η επιστροφή. Πρέπει να είμαι πίσω πριν από τις έξι.", "start_ms": null, "segment_id": "U-B2-015-AUD02-SEG003", "speaker_role": "Σοφία"}, {"end_ms": null, "text_el": "Πριν κλείσουμε μεταφορά, ας δούμε τον καιρό. Αν προβλέπεται δυνατή βροχή, προτείνω να αναβάλουμε.", "start_ms": null, "segment_id": "U-B2-015-AUD02-SEG004", "speaker_role": "Άρης"}, {"end_ms": null, "text_el": "Άρα δεν έχουμε ακόμη κοινή ώρα αναχώρησης. Θα ελέγξω πρώτα τον καιρό και μετά θα σας στείλω δύο επιλογές.", "start_ms": null, "segment_id": "U-B2-015-AUD02-SEG005", "speaker_role": "Λένα"}, {"end_ms": null, "text_el": "Εντάξει, απλώς κρατήστε ότι πριν από τις εννέα δεν μπορώ.", "start_ms": null, "segment_id": "U-B2-015-AUD02-SEG006", "speaker_role": "Νίκος"}], "pronunciation_notes": "Preserve Greek lexical stress; no answer-leaking emphasis except explicitly assessed contrast, which requires blind native validation.", "script_version_hash": "6d4ca8730621c79778b302054491b269d92df287b039301e2bf9789128bb88e0", "execution_script_txt": "AUDIO_EXECUTION_PACK/scripts/U-B2-015-AUD02.txt", "source_manifest_hash": "70ca5cf8fb9eeb9bac33fa901be01352350df8c1a09c4be3