3326	audio_job	U-B2-015-AUD03	41f7c5796c529aa5c91b1d7af805f8ffb13bcac87b2ed85393e39e9d39228fe0	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": {"status": "EVIDENCE_REQUIRED"}, "licence": {"status": "UNRESOLVED_VOICE_AND_MEDIA_RIGHTS"}, "text_el": "Ρένα: Ο μικρός χώρος είναι φθηνότερος, αλλά δεν χωρά είκοσι άτομα. Γιάννης: Τότε προτιμώ τον μεγαλύτερο, αν το κόστος δεν ξεπερνά τον προϋπολογισμό μας. Δώρα: Η τιμή που έχουμε αφορά μόνο την αίθουσα, όχι τον εξοπλισμό. Κώστας: Άρα δεν πρέπει να κάνουμε κράτηση ακόμη. Ρένα: Θα ρωτήσω σήμερα για την πρόσθετη χρέωση και θα σας ενημερώσω. Γιάννης: Ωραία, κρατάμε την προτίμηση για τον μεγάλο χώρο, αλλά αποφασίζουμε μετά την απάντηση.", "version": "0.1.0", "audio_id": "U-B2-015-AUD03", "priority": "CORE_AFTER_L01", "register": "standard neutral Greek", "segments": [], "output_path": null, "speaker_role": ["Ρένα", "Γιάννης", "Δώρα", "Κώστας"], "verification": {"status": "NOT_EXECUTED"}, "measured_cues": [], "native_review": {"status": "PENDING", "reviewer": null}, "script_rights": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "speaking_rate": "Natural B2 for developed talk; B1 diagnostic and prosody at clear natural pace. No measured rate until recorded.", "voice_profile": {"locale": "el-GR", "identity": "GENERIC_CONSENTED_VOICE", "selection": "PRODUCER_NATIVE_APPROVAL_REQUIRED"}, "state_evidence": {"status": "SCRIPT_ONLY"}, "task_alignment": [{"item_id": "U-B2-015-I12", "item_path": "GreekOS_Academic_Corpus/items/U-B2-015-I12.json", "cue_status": "UNMEASURED_NO_AUDIO", "item_sha256": "43bf68cb15dab330a9ca350aa0622c46cec3c71506f12ab7308785c7e65bd214", "text_alignment_status": "CURRENT_ITEM_REFERENCE_ONLY_NOT_ACOUSTICALLY_VERIFIED"}], "verification_hash": null, "actual_duration_ms": null, "source_script_path": "GreekOS_Audio_and_Speaking/assets/U-B2-015-AUD03.json", "planned_output_path": "AUDIO/media/U-B2-015-AUD03.wav", "production_segments": [{"end_ms": null, "text_el": "Ο μικρός χώρος είναι φθηνότερος, αλλά δεν χωρά είκοσι άτομα.", "start_ms": null, "segment_id": "U-B2-015-AUD03-SEG001", "speaker_role": "Ρένα"}, {"end_ms": null, "text_el": "Τότε προτιμώ τον μεγαλύτερο, αν το κόστος δεν ξεπερνά τον προϋπολογισμό μας.", "start_ms": null, "segment_id": "U-B2-015-AUD03-SEG002", "speaker_role": "Γιάννης"}, {"end_ms": null, "text_el": "Η τιμή που έχουμε αφορά μόνο την αίθουσα, όχι τον εξοπλισμό.", "start_ms": null, "segment_id": "U-B2-015-AUD03-SEG003", "speaker_role": "Δώρα"}, {"end_ms": null, "text_el": "Άρα δεν πρέπει να κάνουμε κράτηση ακόμη.", "start_ms": null, "segment_id": "U-B2-015-AUD03-SEG004", "speaker_role": "Κώστας"}, {"end_ms": null, "text_el": "Θα ρωτήσω σήμερα για την πρόσθετη χρέωση και θα σας ενημερώσω.", "start_ms": null, "segment_id": "U-B2-015-AUD03-SEG005", "speaker_role": "Ρένα"}, {"end_ms": null, "text_el": "Ωραία, κρατάμε την προτίμηση για τον μεγάλο χώρο, αλλά αποφασίζουμε μετά την απάντηση.", "start_ms": null, "segment_id": "U-B2-015-AUD03-SEG006", "speaker_role": "Γιάννης"}], "pronunciation_notes": "Preserve Greek lexical stress; no answer-leaking emphasis except explicitly assessed contrast, which requires blind native validation.", "script_version_hash": "6dd701389fdba9930c40eaf5a8da6e90e5b2cad13a96ab5ea21bc127c90d22f5", "execution_script_txt": "AUDIO_EXECUTION_PACK/scripts/U-B2-015-AUD03.txt", "source_manifest_hash": "f51bb1f0c43e7a3c454e59b520200e1da9dc9cb809b4cade17d8846c07427b7a", "source_manifest_path": "GreekOS_Audio_and_Speaking/assets/U-B2-015-AUD03.json", "planned_delivery_path": "AUDIO/media/U-B2-015-AUD03.mp3", "expected_prompt_context": {"unit_id": "U-B2-015