2546	source_claim	CP09-INHERITED-KEG-B2-U01-C7-1	04621f003de0a81bbdcfae26ad926241fdf4fd4d72b559150213ef796807cf69	\N	{"record": {"claim": "Existing source identifier association only; no new substantive claim or recent-usage assertion", "limits": "Source meaning, scope, currentness and rights still require academic review", "status": "INHERITED_ATTRIBUTION_REGISTERED_NOT_REVERIFIED", "claim_id": "CP09-INHERITED-KEG-B2-U01-C7-1", "item_ids": ["KEG-B2-U01-C7"], "source_id": "V241", "provenance": {"path": "GreekOS_B2_Exam_Bank/items/KEG-B2-U01-C7.json", "field": "source_refs", "sha256": "519e3eb973d09f459e78f33efa332b1a514ec6fa1e989ea47dd33963921d6ee1"}}, "claim_id": "CP09-INHERITED-KEG-B2-U01-C7-1", "evidence_path": "IMPORT/registered_source_attributions.json", "evidence_file_sha256": "1565004cfbd59ffb93b4c00ca479f23330f79068ea7890b0bb57bdfe24b3fe19"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3327	audio_job	KEG-B2-L02-AUD1	fe1687cfdeb4f3004e32a8ba6a79ab4d05f4ac98367f3255dfd8fbc00b09754c	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": {"status": "PENDING", "evidence": null}, "licence": {"script": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "voice_asset": null}, "text_el": "Καλησπέρα σας. Θα σας παρουσιάσω το πρόγραμμα «Νυχτερινός Ουρανός», μια εισαγωγή στην παρατήρηση των άστρων για ενήλικες χωρίς προηγούμενη εμπειρία. Δεν πρόκειται για μάθημα αστρολογίας ούτε για εκδρομή με ελεύθερη προσέλευση. Θέλουμε να μάθετε πώς προετοιμάζεται μια παρατήρηση και γιατί μερικές φορές η αναμονή είναι σημαντικότερη από τον εξοπλισμό.\\nΤο πρόγραμμα περιλαμβάνει πέντε συναντήσεις, παρότι στην πρώτη ανακοίνωση αναφέρονταν τέσσερις. Προσθέσαμε μία συνάντηση για όσους χρειάζονται περισσότερο χρόνο με τους χάρτες. Όλες θα γίνουν στο ίδιο σημείο, εκτός αν υπάρξει προειδοποίηση κακοκαιρίας. Δεν χρειάζεται να έρθετε και στις πέντε, αλλά η πρώτη είναι απαραίτητη για να παρακολουθήσετε τις επόμενες.\\nΗ συγκέντρωση θα γίνεται στην ανατολική είσοδο του πάρκου. Η δυτική είσοδος βρίσκεται πιο κοντά στις στάσεις, όμως κλείνει νωρίς και δεν είναι κατάλληλο σημείο συνάντησης. Ένας συνεργάτης θα περιμένει εκεί μόνο την πρώτη βραδιά, για να κατευθύνει όποιον μπερδευτεί. Από την ανατολική πύλη θα περπατήσουμε όλοι μαζί προς το ξέφωτο.\\nΗ πρώτη συνάντηση αρχίζει στις οκτώ και τέταρτο το βράδυ. Προτείνουμε να φτάσετε δέκα λεπτά νωρίτερα. Η ώρα δεν επιλέχθηκε τυχαία: χρειαζόμαστε λίγο φως στην αρχή, ώστε να εξηγήσουμε με ασφάλεια τον χειρισμό των οργάνων. Μόλις σκοτεινιάσει αρκετά, θα περάσουμε στην παρατήρηση. Όποιος καθυστερήσει πρέπει να περιμένει στην είσοδο τον βοηθό.\\nΓια την εγγραφή χρειάζεται να συμπληρώσετε ηλεκτρονική φόρμα. Ένα μήνυμα στο κοινωνικό δίκτυο δεν αρκεί, γιατί μπορεί να χαθεί ανάμεσα στις γενικές ερωτήσεις. Η φόρμα κλείνει την Τρίτη, ανεξάρτητα από το αν έχουν μείνει θέσεις. Την Τετάρτη θα σταλούν οι επιβεβαιώσεις μαζί με έναν απλό χάρτη της διαδρομής προς το πάρκο.\\nΣτην ομάδα χωρούν δεκαοκτώ άτομα. Το μικρό μέγεθος επιτρέπει σε όλους να χρησιμοποιήσουν το τηλεσκόπιο χωρίς μεγάλη αναμονή. Δεν θα δεχτούμε επιπλέον συμμετοχές επί τόπου. Αν δεν βρείτε θέση, μπορείτε να ζητήσετε ενημέρωση για επόμενο κύκλο, χωρίς προκαταβολή ή υποχρέωση συμμετοχής. Οι συνοδοί χρειάζονται δική τους εγγραφή, ακόμη κι αν δεν χρησιμοποιήσουν όργανα.\\nΜη φέρετε δικό σας τηλεσκόπιο: διαθέτουμε τον απαραίτητο εξοπλισμό και θέλουμε να μείνει ελεύθερος ο χώρος. Φέρτε όμως φακό με κόκκινο φως. Το λευκό φως δυσκολεύει την προσαρμογή των ματιών στο σκοτάδι. Αν δεν έχετε κατάλληλο φακό, σημειώστε το στη φόρμα· μπορούμε να σας δανείσουμε έναν για τη διάρκεια της συνάντησης.\\nΣε περίπτωση έντονης συννεφιάς, η συνάντηση δεν μεταφέρεται σε άλλη ημέρα. Θα γίνει μέσα στο πλανητάριο, όπου θα δουλέψουμε με προβολές και ουράνιους χάρτες. Θα ενημερωθείτε μέχρι το μεσημέρι. Η αλλαγή χώρου δεν επηρεάζει την ώρα έναρξης.\\nΚάθε συμμετέχων θα κρατά ένα ημερολόγιο παρατήρησης, με σκίτσα και σύντομες σημειώσεις. Δεν αξιολογούμε την καλλιτεχνική ικανότητα ούτε ζητάμε φωτογραφίες υψηλής ανάλυσης. Μας ενδιαφέρει να ξεχωρίζετε τι είδατε από αυτό που περιμένατε να δείτε. Στο τέλος θα συγκρίνουμε τις καταγραφές μας και θα συζητήσουμε γιατί το ίδιο αντικείμενο μπορεί να φαίνεται διαφορετικό.\\nΗ τελευταία συνάντηση θα περιλαμβάνει και παρατήρηση της Σελήνης. Αν έχετε γενικές απορίες πριν από την έναρξη, στείλτε τες με ηλεκτρονικό ταχυδρομείο, ώστε η απάντηση να φτάσει σε όλη την ομάδα. Παρακαλώ μη ζητάτε προσωπική βεβαίωση επιτυχίας. Το πρόγραμμα προσφέρει εμπειρία και βασικές γνώσεις, αλλά δεν οδηγεί σε τίτλο σπουδών.", "version": "0.11.0", "audio_id": "KEG-B2-L02-AUD1", "register": "informative monologue / natural reasoned conversation", "segments": [{"text": "Καλησπέρα σας. Θα σας παρουσιάσω το πρόγραμμα «Νυχτερινός Ουρανός», μια εισαγωγή στην παρατήρηση των άστρων για ενήλικες χωρίς προηγούμενη εμπειρία. Δεν πρόκειται για μάθημα αστρολογίας ούτε για εκδρομή με ελεύθερη προσέλευση. Θέλουμε να μάθετε πώς προετοιμάζεται μια παρατήρηση και γιατί μερικές φορές η αναμονή είναι σημαντικότερη από τον εξοπλισμό.", "cue_id": "N00", "speaker": "Συντονίστρια", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Το πρόγραμμα περιλαμβάνει πέντε συναντήσεις, παρότι στην πρώτη ανακοίνωση αναφέρονταν τέσσερις. Προσθέσαμε μία συνάντηση για όσους χρειάζονται περισσότερο χρόνο με τους χάρτες. Όλες θα γίνουν στο ίδιο σημείο, εκτός αν υπάρξει προειδοποίηση κακοκαιρίας. Δεν χρειάζεται να έρθετε και στις πέντε, αλλά η πρώτη είναι απαραίτητη για να παρακολουθήσετε τις επόμενες.", "cue_id": "N01", "speaker": "Συντονίστρια", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Η συγκέντρωση θα γίνεται στην ανατολική είσοδο του πάρκου. Η δυτική είσοδος βρίσκεται πιο κοντά στις στάσεις, όμως κλείνει νωρίς και δεν είναι κατάλληλο σημείο συνάντησης. Ένας συνεργάτης θα περιμένει εκεί μόνο την πρώτη βραδιά, για να κατευθύνει όποιον μπερδευτεί. Από την ανατολική πύλη θα περπατήσουμε όλοι μαζί προς το ξέφωτο.", "cue_id": "N02", "speaker": "Συντονίστρια", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Η πρώτη συνάντηση αρχίζει στις οκτώ και τέταρτο το βράδυ. Προτείνουμε να φτάσετε δέκα λεπτά νωρίτερα. Η ώρα δεν επιλέχθηκε τυχαία: χρειαζόμαστε λίγο φως στην αρχή, ώστε να εξηγήσουμε με ασφάλεια τον χειρισμό των οργάνων. Μόλις σκοτεινιάσει αρκετά, θα περάσουμε στην παρατήρηση. Όποιος καθυστερήσει πρέπει να περιμένει στην είσοδο τον βοηθό.", "cue_id": "N03", "speaker": "Συντονίστρια", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Για την εγγραφή χρειάζεται να συμπληρώσετε ηλεκτρονική φόρμα. Ένα μήνυμα στο κοινωνικό δίκτυο δεν αρκεί, γιατί μπορεί να χαθεί ανάμεσα στις γενικές ερωτήσεις. Η φόρμα κλείνει την Τρίτη, ανεξάρτητα από το αν έχουν μείνει θέσεις. Την Τετάρτη θα σταλούν οι επιβεβαιώσεις μαζί με έναν απλό χάρτη της διαδρομής προς το πάρκο.", "cue_id": "N04", "speaker": "Συντονίστρια", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Στην ομάδα χωρούν δεκαοκτώ άτομα. Το μικρό μέγεθος επιτρέπει σε όλους να χρησιμοποιήσουν το τηλεσκόπιο χωρίς μεγάλη αναμονή. Δεν θα δεχτούμε επιπλέον συμμετοχές επί τόπου. Αν δεν βρείτε θέση, μπορείτε να ζητήσετε ενημέρωση για επόμενο κύκλο, χωρίς προκαταβολή ή υποχρέωση συμμετοχής. Οι συνοδοί χρειάζονται δική τους εγγραφή, ακόμη κι αν δεν χρησιμοποιήσουν όργανα.", "cue_id": "N05", "speaker": "Συντονίστρια", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Μη φέρετε δικό σας τηλεσκόπιο: διαθέτουμε τον απαραίτητο εξοπλισμό και θέλουμε να μείνει ελεύθερος ο χώρος. Φέρτε όμως φακό με κόκκινο φως. Το λευκό φως δυσκολεύει την προσαρμογή των ματιών στο σκοτάδι. Αν δεν έχετε κατάλληλο φακό, σημειώστε το στη φόρμα· μπορούμε να σας δανείσουμε έναν για τη διάρκεια της συνάντησης.", "cue_id": "N06", "speaker": "Συντονίστρια", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Σε περίπτωση έντονης συννεφιάς, η συνάντηση δεν μεταφέρεται σε άλλη ημέρα. Θα γίνει μέσα στο πλανητάριο, όπου θα δουλέψουμε με προβολές και ουράνιους χάρτες. Θα ενημερωθείτε μέχρι το μεσημέρι. Η αλλαγή χώρου δεν επηρεάζει την ώρα έναρξης.", "cue_id": "N07", "speaker": "Συντονίστρια", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Κάθε συμμετέχων θα κρατά ένα ημερολόγιο παρατήρησης, με σκίτσα και σύντομες σημειώσεις. Δεν αξιολογούμε την καλλιτεχνική ικανότητα ούτε ζητάμε φωτογραφίες υψηλής ανάλυσης. Μας ενδιαφέρει να ξεχωρίζετε τι είδατε από αυτό που περιμένατε να δείτε. Στο τέλος θα συγκρίνουμε τις καταγραφές μας και θα συζητήσουμε γιατί το ίδιο αντικείμενο μπορεί να φαίνεται διαφορετικό.", "cue_id": "N08", "speaker": "Συντονίστρια", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Η τελευταία συνάντηση θα περιλαμβάνει και παρατήρηση της Σελήνης. Αν έχετε γενικές απορίες πριν από την έναρξη, στείλτε τες με ηλεκτρονικό ταχυδρομείο, ώστε η απάντηση να φτάσει σε όλη την ομάδα. Παρακαλώ μη ζητάτε προσωπική βεβαίωση επιτυχίας. Το πρόγραμμα προσφέρει εμπειρία και βασικές γνώσεις, αλλά δεν οδηγεί σε τίτλο σπουδών.", "cue_id": "N09", "speaker": "Συντονίστρια", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}], "output_path": null, "target_path": "audio/exams/KEG-B2-L02-AUD1.wav", "speaker_role": ["Συντονίστρια"], "measured_cues": [], "native_review": {"status": "NOT_PERFORMED"}, "speaking_rate": "B2 natural, final rate established by listener pilot", "voice_profile": "Natural distinct standard Modern Greek voices, audible self-introductions in dialogue", "format_request": "Project master WAV PCM48kHz24bit; not an official KEG requirement", "task_alignment": [{"key": ["πέντε"], "cue_ids": ["N01"], "item_id": "KEG-B2-L02-N01"}, {"key": ["ανατολική"], "cue_ids": ["N02"], "item_id": "KEG-B2-L02-N02"}, {"key": ["οκτώ και τέταρτο"], "cue_ids": ["N03"], "item_id": "KEG-B2-L02-N03"}, {"key": ["φόρμας"], "cue_ids": ["N04"], "item_id": "KEG-B2-L02-N04"}, {"key": ["Τρίτη"], "cue_ids": ["N04"], "item_id": "KEG-B2-L02-N05"}, {"key": ["δεκαοκτώ"], "cue_ids": ["N05"], "item_id": "KEG-B2-L02-N06"}, {"key": ["κόκκινο"], "cue_ids": ["N06"], "item_id": "KEG-B2-L02-N07"}, {"key": ["πλανητάριο"], "cue_ids": ["N07"], "item_id": "KEG-B2-L02-N08"}, {"key": ["σκίτσα"], "cue_ids": ["N