2717	competency	A2-L02	1b28381db2a69553544566a21c4681c68da33a1c706992fad02a02940a21a10d	core	{"name": "Сообщения и простые инструкции из нескольких шагов", "level": "A2", "competency_id": "A2-L02", "prerequisites": ["A1-L02", "A2-G07"], "content_complete": false, "primary_unit_ids": ["U-A2-018"], "incidental_unit_ids": ["U-A2-018"], "current_coverage_status": "PARTIAL_AUTHORED_NOT_RELEASED", "coverage_status_at_baseline": "NOT_AUTHORED"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3328	audio_job	KEG-B2-L02-AUD2	a1aee9b99418c881a94597042774e81191b4be9ccfb7d66b6a124366a5c30dbf	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": {"status": "PENDING", "evidence": null}, "licence": {"script": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "voice_asset": null}, "text_el": "Είμαι η Δανάη. Σας κάλεσα για να συζητήσουμε τη νέα σειρά ηχητικών εκπομπών του συλλόγου μας. Έχω ήδη κρατήσει την αίθουσα για τη σημερινή δοκιμή. Θα πρότεινα τα επεισόδια να διαρκούν δεκαπέντε λεπτά. Έτσι μπορούμε να αναπτύσσουμε ένα θέμα χωρίς να κουράζουμε όσους ακούν στη διαδρομή προς τη δουλειά. Δεν θα περιόριζα, πάντως, κάθε απάντηση του καλεσμένου με χρονόμετρο.\\nΕίμαι ο Πέτρος. Εγώ θα έδινα μισή ώρα σε κάθε επεισόδιο, γιατί οι άνθρωποι χρειάζονται χρόνο για να εξηγήσουν την εμπειρία τους. Περισσότερο με απασχολεί η ηχογράφηση. Προτιμώ να καλούμε τους καλεσμένους εδώ, στο στούντιο, όπου ελέγχουμε τον θόρυβο. Η σύνδεση από το σπίτι φαίνεται εύκολη, αλλά συχνά μας αναγκάζει να επαναλαμβάνουμε ολόκληρες φράσεις.\\nΕίμαι η Σοφία. Για τη διάρκεια θα αποφασίσω αφού ακούσω τη δοκιμή. Στις συνεντεύξεις προτιμώ την εξ αποστάσεως συμμετοχή, επειδή ανοίγει την πόρτα σε ανθρώπους που μένουν μακριά. Δέχομαι ότι υπάρχουν τεχνικά προβλήματα, αλλά δεν θεωρώ δίκαιο να αποκλείονται εξαρχής. Μπορούμε να τους δίνουμε οδηγίες για το μικρόφωνο και να κάνουμε έναν σύντομο έλεγχο πριν ξεκινήσουμε.\\nΔεν έχω σταθερή προτίμηση για τον χώρο της συνέντευξης. Για τη μουσική όμως θα ήθελα ένα σύντομο σήμα στην αρχή, με δική μας σύνθεση. Όχι μουσική κάτω από τη συζήτηση. Αν γεμίσουμε κάθε παύση, ο λόγος θα χάσει τη φυσικότητά του. Οι μικρές σιωπές δεν είναι απαραίτητα λάθη που πρέπει να σβήσουμε.\\nΕγώ θα ξεκινούσα κατευθείαν με τη φωνή του παρουσιαστή, χωρίς μουσικό σήμα. Θα κρατούσα επίσης τα επεισόδια στη σελίδα μας χωρίς να επιτρέπεται η λήψη τους. Μπορεί κάποιος να θέλει να διορθώσει μια πληροφορία αργότερα, και προτιμώ να ξέρουμε ποια εκδοχή ακούγεται. Δεν λέω ότι αυτό αποκλείει κάθε παλιό αντίγραφο, αλλά διευκολύνει τη διαχείριση.\\nΗ δική μου πρόταση είναι να προσφέρουμε και αρχείο για λήψη. Πολλοί ακούν όταν δεν έχουν σύνδεση. Μπορούμε να βάζουμε ημερομηνία στην κάθε έκδοση και να σημειώνουμε τις διορθώσεις στη σελίδα. Για τη μουσική δεν έχω ακόμη άποψη. Θα ήθελα επίσης να ανεβάζουμε πλήρη γραπτή απομαγνητοφώνηση, ώστε το περιεχόμενο να είναι προσβάσιμο και σε ανθρώπους με δυσκολία ακοής.\\nΠλήρες κείμενο δεν θα υποσχεθώ πριν δούμε πόσο χρόνο χρειάζεται. Προτείνω αρχικά μόνο μια σύντομη περίληψη με τα βασικά σημεία. Για τους καλεσμένους, θα έστελνα πριν από τη συνέντευξη έναν κατάλογο θεμάτων, χωρίς να απαιτούμε έτοιμες απαντήσεις. Έτσι θα μπορούν να προετοιμάσουν στοιχεία, ενώ η συζήτηση θα παραμένει ανοιχτή σε αυθόρμητες ερωτήσεις.\\nΕγώ δεν θα έστελνα κατάλογο εκ των προτέρων, γιατί φοβάμαι ότι η συνέντευξη θα γίνει ανάγνωση κειμένου. Θα εξηγούσα μόνο τον γενικό σκοπό. Πριν δημοσιεύσουμε το πρώτο επεισόδιο, προτείνω να το ακούσουν πέντε άνθρωποι εκτός της ομάδας μας. Θέλω να μάθουμε αν καταλαβαίνουν ποιος μιλάει και πού αλλάζει το θέμα, χωρίς να τους δώσουμε εξηγήσεις.\\nΔεν θα κάνω εγώ πρόταση για τον κατάλογο ερωτήσεων. Πάντως θα δεχτώ ό,τι συμφωνήσετε, αρκεί ο καλεσμένος να γνωρίζει πού θα δημοσιευτεί η ηχογράφηση. Θεωρώ απαραίτητο να πάρουμε την άδειά του πριν από τη δημοσίευση. Δεν αρκεί ότι δέχτηκε να καθίσει μπροστά στο μικρόφωνο. Για εξωτερική δοκιμή δεν έχω αποφασίσει· θα ήθελα πρώτα να ακούσω το υλικό.", "version": "0.11.0", "audio_id": "KEG-B2-L02-AUD2", "register": "informative monologue / natural reasoned conversation", "segments": [{"text": "Είμαι η Δανάη. Σας κάλεσα για να συζητήσουμε τη νέα σειρά ηχητικών εκπομπών του συλλόγου μας. Έχω ήδη κρατήσει την αίθουσα για τη σημερινή δοκιμή. Θα πρότεινα τα επεισόδια να διαρκούν δεκαπέντε λεπτά. Έτσι μπορούμε να αναπτύσσουμε ένα θέμα χωρίς να κουράζουμε όσους ακούν στη διαδρομή προς τη δουλειά. Δεν θα περιόριζα, πάντως, κάθε απάντηση του καλεσμένου με χρονόμετρο.", "cue_id": "D00", "speaker": "Δανάη", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Είμαι ο Πέτρος. Εγώ θα έδινα μισή ώρα σε κάθε επεισόδιο, γιατί οι άνθρωποι χρειάζονται χρόνο για να εξηγήσουν την εμπειρία τους. Περισσότερο με απασχολεί η ηχογράφηση. Προτιμώ να καλούμε τους καλεσμένους εδώ, στο στούντιο, όπου ελέγχουμε τον θόρυβο. Η σύνδεση από το σπίτι φαίνεται εύκολη, αλλά συχνά μας αναγκάζει να επαναλαμβάνουμε ολόκληρες φράσεις.", "cue_id": "D01", "speaker": "Πέτρος", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Είμαι η Σοφία. Για τη διάρκεια θα αποφασίσω αφού ακούσω τη δοκιμή. Στις συνεντεύξεις προτιμώ την εξ αποστάσεως συμμετοχή, επειδή ανοίγει την πόρτα σε ανθρώπους που μένουν μακριά. Δέχομαι ότι υπάρχουν τεχνικά προβλήματα, αλλά δεν θεωρώ δίκαιο να αποκλείονται εξαρχής. Μπορούμε να τους δίνουμε οδηγίες για το μικρόφωνο και να κάνουμε έναν σύντομο έλεγχο πριν ξεκινήσουμε.", "cue_id": "D02", "speaker": "Σοφία", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Δεν έχω σταθερή προτίμηση για τον χώρο της συνέντευξης. Για τη μουσική όμως θα ήθελα ένα σύντομο σήμα στην αρχή, με δική μας σύνθεση. Όχι μουσική κάτω από τη συζήτηση. Αν γεμίσουμε κάθε παύση, ο λόγος θα χάσει τη φυσικότητά του. Οι μικρές σιωπές δεν είναι απαραίτητα λάθη που πρέπει να σβήσουμε.", "cue_id": "D03", "speaker": "Δανάη", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Εγώ θα ξεκινούσα κατευθείαν με τη φωνή του παρουσιαστή, χωρίς μουσικό σήμα. Θα κρατούσα επίσης τα επεισόδια στη σελίδα μας χωρίς να επιτρέπεται η λήψη τους. Μπορεί κάποιος να θέλει να διορθώσει μια πληροφορία αργότερα, και προτιμώ να ξέρουμε ποια εκδοχή ακούγεται. Δεν λέω ότι αυτό αποκλείει κάθε παλιό αντίγραφο, αλλά διευκολύνει τη διαχείριση.", "cue_id": "D04", "speaker": "Πέτρος", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Η δική μου πρόταση είναι να προσφέρουμε και αρχείο για λήψη. Πολλοί ακούν όταν δεν έχουν σύνδεση. Μπορούμε να βάζουμε ημερομηνία στην κάθε έκδοση και να σημειώνουμε τις διορθώσεις στη σελίδα. Για τη μουσική δεν έχω ακόμη άποψη. Θα ήθελα επίσης να ανεβάζουμε πλήρη γραπτή απομαγνητοφώνηση, ώστε το περιεχόμενο να είναι προσβάσιμο και σε ανθρώπους με δυσκολία ακοής.", "cue_id": "D05", "speaker": "Σοφία", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Πλήρες κείμενο δεν θα υποσχεθώ πριν δούμε πόσο χρόνο χρειάζεται. Προτείνω αρχικά μόνο μια σύντομη περίληψη με τα βασικά σημεία. Για τους καλεσμένους, θα έστελνα πριν από τη συνέντευξη έναν κατάλογο θεμάτων, χωρίς να απαιτούμε έτοιμες απαντήσεις. Έτσι θα μπορούν να προετοιμάσουν στοιχεία, ενώ η συζήτηση θα παραμένει ανοιχτή σε αυθόρμητες ερωτήσεις.", "cue_id": "D06", "speaker": "Δανάη", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Εγώ δεν θα έστελνα κατάλογο εκ των προτέρων, γιατί φοβάμαι ότι η συνέντευξη θα γίνει ανάγνωση κειμένου. Θα εξηγούσα μόνο τον γενικό σκοπό. Πριν δημοσιεύσουμε το πρώτο επεισόδιο, προτείνω να το ακούσουν πέντε άνθρωποι εκτός της ομάδας μας. Θέλω να μάθουμε αν καταλαβαίνουν ποιος μιλάει και πού αλλάζει το θέμα, χωρίς να τους δώσουμε εξηγήσεις.", "cue_id": "D07", "speaker": "Πέτρος", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Δεν θα κάνω εγώ πρόταση για τον κατάλογο ερωτήσεων. Πάντως θα δεχτώ ό,τι συμφωνήσετε, αρκεί ο καλεσμένος να γνωρίζει πού θα δημοσιευτεί η ηχογράφηση. Θεωρώ απαραίτητο να πάρουμε την άδειά του πριν από τη δημοσίευση. Δεν αρκεί ότι δέχτηκε να καθίσει μπροστά στο μικρόφωνο. Για εξωτερική δοκιμή δεν έχω αποφασίσει· θα ήθελα πρώτα να ακούσω το υλικό.", "cue_id": "D08", "speaker": "Σοφία", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}], "output_path": null, "target_path": "audio/exams/KEG-B2-L02-AUD2.wav", "speaker_role": ["Δανάη", "Πέτρος", "Σοφία"], "measured_cues": [], "native_review": {"status": "NOT_PERFORMED"}, "speaking_rate": "B2 natural, final rate established by listener pilot", "voice_profile": "Natural distinct standard Modern Greek voices, audible self-introductions in dialogue", "format_request": "Project master WAV PCM48kHz24bit; not an official KEG requirement", "task_alignment": [{"key": ["Δανάη"], "cue_ids": ["D00"], "item_id": "KEG-B2-L02-A01"}, {"key": ["Πέτρος"], "cue_ids": ["D01"], "item_id": "KEG-B2-L02-A02"}, {"key": ["Σοφία"], "cue_ids": ["D02"], "item_id": "KEG-B2-L02-A03"}, {"key": ["Δανάη"], "cue_ids": ["D03"], "item_id": "KEG-B2-L02-A04"}, {"key": ["Πέτρος"], "cue_ids": ["D04"], "item_id": "KEG-B2-L02-A05"}, {"key": ["Σοφία"], "cue_ids": ["D05"], "item_id": "KEG-B2-L02-A06"}, {"key": ["Δανάη"], "cue_ids": ["D06"], "item_id": "KEG-B2-L02-A07"}, {"key": ["Δανάη"], "cue_ids": ["D06"], "item_id": "KEG-B2-L02-A08"}, {"key": ["Πέτρος"], "cue_ids": ["D07"], "item_id": "KEG-B2-L02-A09"}, {"key": ["Σοφία"], "cue_ids": ["D08"], "item_id": "KEG-B2-L02-A10"}], "acceptance_tests": ["Document voice and commercial distribution rights", "Hash actual bytes and measure duration,cue timings,peak,Loudness; reject clipping/truncation", "Blind Greek listener solves all tasks without transcript", "Then verify every word,number,negation and speaker against script; repair discrepancies", "Pilot two plays and reading/response pauses in30minutes", "No AUDIO_VERIFIED or release before actual listening and recorded evidence"], "verification_hash": null, "actual_duration_ms": null, "source_script_path": "GreekOS_Audio_and_Speaking/assets/KEG-B2-L02-AUD2.json", "pronunciation_notes": "Retain all names,numbers,negations,corrections verbatim", "script_version_hash": "d61de2ba092bef80e7cbd224d5f9e69b836fc8908825cb3e4a8f8bb49bcd41a1", "source_manifest_hash": "d4d9bc7244564086cd6180939f97e1bb592f0693f36c3860ede5a4a5bf13cff7", "source_manifest_path": "GreekOS_Audio_and_Speaking/assets/KEG-B2-L02-AUD2.json", "expected_prompt_context": "F02 part2,two plays in final30-minute section", "intonation_instructions": "No answer emphasis; no music; hidden labels not read; self-introductions are spoken", "source_script_file_hash": "d4d9bc7244564086cd6180939f97e1bb592f0693f36c3860ede5a4a5bf13cff7"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
