3329	audio_job	KEG-B2-L03-AUD1	f7c7ccc6abfac81ca63d73b11dc6680ff601fc3d264dfa5e766d1b3de9cbbe16	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": {"status": "PENDING", "evidence": null}, "licence": {"script": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "voice_asset": null}, "text_el": "Καλώς ήρθατε στην ενημέρωση για τον κύκλο «Μπαλκόνι σε Άνθιση». Το εργαστήριο απευθύνεται σε ανθρώπους που θέλουν να φροντίσουν λίγα φυτά στο σπίτι, χωρίς να διαθέτουν κήπο. Δεν υποσχόμαστε ότι κάθε χώρος είναι κατάλληλος για κάθε φυτό. Θα ξεκινήσουμε από την παρατήρηση του δικού σας μπαλκονιού και θα αποφύγουμε τις αγορές μόνο με βάση μια όμορφη φωτογραφία.\\nΟ κύκλος θα διαρκέσει οκτώ εβδομάδες. Η αρχική σκέψη ήταν να συναντιόμαστε κάθε εβδομάδα, αλλά τελικά θα γίνουν τέσσερις συναντήσεις, ανά δύο εβδομάδες. Στο ενδιάμεσο θα δοκιμάζετε μικρές εργασίες στο σπίτι. Η παρουσία σε όλες τις συναντήσεις δεν είναι υποχρεωτική, όμως οι οδηγίες της πρώτης είναι απαραίτητες για να κατανοήσετε όσα ακολουθούν.\\nΘα χρησιμοποιήσουμε την αίθουσα δίπλα στο θερμοκήπιο του εκπαιδευτικού κέντρου. Το ίδιο το θερμοκήπιο φιλοξενεί άλλο πρόγραμμα και δεν θα είναι ο βασικός μας χώρος. Αν έρθετε με λεωφορείο, κατεβείτε στην τελευταία στάση και ακολουθήστε τον πεζόδρομο.\\nΗ πρώτη συνάντηση μεταφέρθηκε από το Σάββατο στην Κυριακή. Κρατήσαμε την ίδια ώρα, έντεκα το πρωί, ώστε να εξυπηρετούνται όσοι έρχονται από πιο μακρινές περιοχές. Η αλλαγή αφορά μόνο την πρώτη ημερομηνία. Οι υπόλοιπες αναγράφονται στο έντυπο που θα παραλάβετε. Παρακαλώ ελέγξτε το νέο πρόγραμμα και μη βασιστείτε στην παλιά αφίσα που κυκλοφορεί ακόμη.\\nΠριν έρθετε, καταγράψτε για τρεις ημέρες πόσες ώρες άμεσου ήλιου δέχεται το μπαλκόνι σας. Δεν ζητάμε ακριβείς μετρήσεις με ειδικό όργανο, αλλά μια προσεκτική παρατήρηση πρωί και απόγευμα. Σημειώστε επίσης αν φυσάει έντονα. Οι πληροφορίες θα μας βοηθήσουν να συζητήσουμε κατάλληλες επιλογές, αντί να δώσουμε τον ίδιο κατάλογο φυτών σε όλους.\\nΦέρτε μία άδεια γλάστρα, καθαρή και χωρίς σπασμένα σημεία. Δεν χρειάζεται να αγοράσετε καινούρια. Θα χρησιμοποιηθεί στην πρακτική άσκηση, ενώ χώμα και μικρά εργαλεία θα υπάρχουν εδώ. Αν δεν έχετε γλάστρα, ενημερώστε μας εγκαίρως, ώστε να ετοιμάσουμε μία για εσάς από το διαθέσιμο υλικό.\\nΗ συμμετοχή στον κύκλο είναι δωρεάν, αλλά για το προαιρετικό σετ σπόρων θα καταβάλετε επτά ευρώ. Το ποσό αφορά μόνο το σετ και δεν αποτελεί εισιτήριο εισόδου. Μπορείτε να παρακολουθήσετε όλες τις δραστηριότητες χωρίς να το αγοράσετε.\\nΟι θέσεις είναι περιορισμένες και η κράτηση γίνεται τηλεφωνικά. Το γραφείο δέχεται κλήσεις μέχρι την Παρασκευή στις δύο το μεσημέρι. Αν απαντήσει ο τηλεφωνητής, αφήστε όνομα και αριθμό επικοινωνίας· η θέση επιβεβαιώνεται μόνο όταν σας καλέσουμε εμείς. Η αποστολή μηνύματος στην προσωπική σελίδα του εκπαιδευτή δεν αντικαθιστά αυτή τη διαδικασία.\\nΜετά τη δεύτερη συνάντηση, θα μπορείτε να στέλνετε φωτογραφίες των φυτών σας για γενικές παρατηρήσεις. Παρακαλώ να μη φαίνονται πρόσωπα ή στοιχεία διεύθυνσης. Οι εικόνες θα χρησιμοποιούνται μόνο μέσα στην ομάδα και δεν θα αναρτώνται δημόσια. Για κάθε διαφορετική χρήση θα χρειαζόταν χωριστή συνεννόηση. Όποιος δεν επιθυμεί φωτογραφίες μπορεί να κρατά γραπτή περιγραφή.\\nΣτο τέλος θα γίνει ανταλλαγή εμπειριών, όχι διαγωνισμός για το πιο εντυπωσιακό μπαλκόνι. Θα φέρετε το ημερολόγιο φροντίδας, ακόμη κι αν κάποιο φυτό δεν έχει αναπτυχθεί όπως περιμένατε. Οι δυσκολίες είναι χρήσιμο υλικό συζήτησης. Θα εξετάσουμε τι αλλάξατε και τι παρατηρήσατε, χωρίς να αποδίδουμε κάθε αποτέλεσμα σε μία μόνο αιτία.", "version": "0.11.0", "audio_id": "KEG-B2-L03-AUD1", "register": "informative monologue / natural reasoned conversation", "segments": [{"text": "Καλώς ήρθατε στην ενημέρωση για τον κύκλο «Μπαλκόνι σε Άνθιση». Το εργαστήριο απευθύνεται σε ανθρώπους που θέλουν να φροντίσουν λίγα φυτά στο σπίτι, χωρίς να διαθέτουν κήπο. Δεν υποσχόμαστε ότι κάθε χώρος είναι κατάλληλος για κάθε φυτό. Θα ξεκινήσουμε από την παρατήρηση του δικού σας μπαλκονιού και θα αποφύγουμε τις αγορές μόνο με βάση μια όμορφη φωτογραφία.", "cue_id": "N00", "speaker": "Υπεύθυνος", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Ο κύκλος θα διαρκέσει οκτώ εβδομάδες. Η αρχική σκέψη ήταν να συναντιόμαστε κάθε εβδομάδα, αλλά τελικά θα γίνουν τέσσερις συναντήσεις, ανά δύο εβδομάδες. Στο ενδιάμεσο θα δοκιμάζετε μικρές εργασίες στο σπίτι. Η παρουσία σε όλες τις συναντήσεις δεν είναι υποχρεωτική, όμως οι οδηγίες της πρώτης είναι απαραίτητες για να κατανοήσετε όσα ακολουθούν.", "cue_id": "N01", "speaker": "Υπεύθυνος", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Θα χρησιμοποιήσουμε την αίθουσα δίπλα στο θερμοκήπιο του εκπαιδευτικού κέντρου. Το ίδιο το θερμοκήπιο φιλοξενεί άλλο πρόγραμμα και δεν θα είναι ο βασικός μας χώρος. Αν έρθετε με λεωφορείο, κατεβείτε στην τελευταία στάση και ακολουθήστε τον πεζόδρομο.", "cue_id": "N02", "speaker": "Υπεύθυνος", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Η πρώτη συνάντηση μεταφέρθηκε από το Σάββατο στην Κυριακή. Κρατήσαμε την ίδια ώρα, έντεκα το πρωί, ώστε να εξυπηρετούνται όσοι έρχονται από πιο μακρινές περιοχές. Η αλλαγή αφορά μόνο την πρώτη ημερομηνία. Οι υπόλοιπες αναγράφονται στο έντυπο που θα παραλάβετε. Παρακαλώ ελέγξτε το νέο πρόγραμμα και μη βασιστείτε στην παλιά αφίσα που κυκλοφορεί ακόμη.", "cue_id": "N03", "speaker": "Υπεύθυνος", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Πριν έρθετε, καταγράψτε για τρεις ημέρες πόσες ώρες άμεσου ήλιου δέχεται το μπαλκόνι σας. Δεν ζητάμε ακριβείς μετρήσεις με ειδικό όργανο, αλλά μια προσεκτική παρατήρηση πρωί και απόγευμα. Σημειώστε επίσης αν φυσάει έντονα. Οι πληροφορίες θα μας βοηθήσουν να συζητήσουμε κατάλληλες επιλογές, αντί να δώσουμε τον ίδιο κατάλογο φυτών σε όλους.", "cue_id": "N04", "speaker": "Υπεύθυνος", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Φέρτε μία άδεια γλάστρα, καθαρή και χωρίς σπασμένα σημεία. Δεν χρειάζεται να αγοράσετε καινούρια. Θα χρησιμοποιηθεί στην πρακτική άσκηση, ενώ χώμα και μικρά εργαλεία θα υπάρχουν εδώ. Αν δεν έχετε γλάστρα, ενημερώστε μας εγκαίρως, ώστε να ετοιμάσουμε μία για εσάς από το διαθέσιμο υλικό.", "cue_id": "N05", "speaker": "Υπεύθυνος", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Η συμμετοχή στον κύκλο είναι δωρεάν, αλλά για το προαιρετικό σετ σπόρων θα καταβάλετε επτά ευρώ. Το ποσό αφορά μόνο το σετ και δεν αποτελεί εισιτήριο εισόδου. Μπορείτε να παρακολουθήσετε όλες τις δραστηριότητες χωρίς να το αγοράσετε.", "cue_id": "N06", "speaker": "Υπεύθυνος", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Οι θέσεις είναι περιορισμένες και η κράτηση γίνεται τηλεφωνικά. Το γραφείο δέχεται κλήσεις μέχρι την Παρασκευή στις δύο το μεσημέρι. Αν απαντήσει ο τηλεφωνητής, αφήστε όνομα και αριθμό επικοινωνίας· η θέση επιβεβαιώνεται μόνο όταν σας καλέσουμε εμείς. Η αποστολή μηνύματος στην προσωπική σελίδα του εκπαιδευτή δεν αντικαθιστά αυτή τη διαδικασία.", "cue_id": "N07", "speaker": "Υπεύθυνος", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Μετά τη δεύτερη συνάντηση, θα μπορείτε να στέλνετε φωτογραφίες των φυτών σας για γενικές παρατηρήσεις. Παρακαλώ να μη φαίνονται πρόσωπα ή στοιχεία διεύθυνσης. Οι εικόνες θα χρησιμοποιούνται μόνο μέσα στην ομάδα και δεν θα αναρτώνται δημόσια. Για κάθε διαφορετική χρήση θα χρειαζόταν χωριστή συνεννόηση. Όποιος δεν επιθυμεί φωτογραφίες μπορεί να κρατά γραπτή περιγραφή.", "cue_id": "N08", "speaker": "Υπεύθυνος", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Στο τέλος θα γίνει ανταλλαγή εμπειριών, όχι διαγωνισμός για το πιο εντυπωσιακό μπαλκόνι. Θα φέρετε το ημερολόγιο φροντίδας, ακόμη κι αν κάποιο φυτό δεν έχει αναπτυχθεί όπως περιμένατε. Οι δυσκολίες είναι χρήσιμο υλικό συζήτησης. Θα εξετάσουμε τι αλλάξατε και τι παρατηρήσατε, χωρίς να αποδίδουμε κάθε αποτέλεσμα σε μία μόνο αιτία.", "cue_id": "N09", "speaker": "Υπεύθυνος", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}], "output_path": null, "target_path": "audio/exams/KEG-B2-L03-AUD1.wav", "speaker_role": ["Υπεύθυνος"], "measured_cues": [], "native_review": {"status": "NOT_PERFORMED"}, "speaking_rate": "B2 natural, final rate established by listener pilot", "voice_profile": "Natural distinct standard Modern Greek voices, audible self-introductions in dialogue", "format_request": "Project master WAV PCM48kHz24bit; not an official KEG requirement", "task_alignment": [{"key": ["τέσσερις"], "cue_ids": ["N01"], "item_id": "KEG-B2-L03-N01"}, {"key": ["θερμοκήπιο"], "cue_ids": ["N02"], "item_id": "KEG-B2-L03-N02"}, {"key": ["Κυριακή"], "cue_ids": ["N03"], "item_id": "KEG-B2-L03-N03"}, {"key": ["ήλιου"], "cue_ids": ["N04"], "item_id": "KEG-B2-L03-N04"}, {"key": ["γλάστρα"], "cue_ids": ["N05"], "item_id": "KEG-B2-L03-N05"}, {"key": ["επτά"], "cue_ids": ["N06"], "item_id": "KEG-B2-L03-N06"}, {"key": ["τηλεφωνικά"], "cue_ids": ["N07"], "item_id": "KEG-B2-L03-N07"}, {"key": ["δύο"], "cue_ids": ["N07"], "item_id": "KEG-B2-L03-N08"}, {"key": ["ομάδα"], "cue_ids": ["N08"], "item_id": "KEG-B2-L03-N09"}, {"key": ["ημερολόγιο"], "cue_ids": ["N09"], "item_id": "KEG-B2-L03-N10"}], "acceptance_tests": ["Document voice and commercial distribution rights", "Hash actual bytes and measure duration,cue timings,peak,Loudness; reject clipping/