2719	competency	A2-SP01	9f6d65a09c656688371123ec50bda50c0deea0bfc585cb80cbc449945b9fa5d0	core	{"name": "Описание опыта, планов и предпочтений", "level": "A2", "competency_id": "A2-SP01", "prerequisites": ["A1-SP01", "A2-G04", "A2-G05"], "content_complete": false, "primary_unit_ids": ["U-A2-014"], "incidental_unit_ids": ["U-A2-001", "U-A2-014"], "current_coverage_status": "PARTIAL_AUTHORED_NOT_RELEASED", "coverage_status_at_baseline": "PARTIAL_AUTHORED_NOT_RELEASED"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3330	audio_job	KEG-B2-L03-AUD2	5a8738db6a14d88fd9410b5589bb52f15bca962065c9ad58fc6cbbaa80161c38	\N	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": {"status": "PENDING", "evidence": null}, "licence": {"script": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "voice_asset": null}, "text_el": "Είμαι η Λένα. Έχω συγκεντρώσει τις προτάσεις για την ομαδική μας εκδρομή, αλλά δεν έχω κάνει καμία κράτηση. Εγώ προτιμώ να φύγουμε Παρασκευή απόγευμα, ώστε να έχουμε δύο ολόκληρες ημέρες στον προορισμό. Ξέρω ότι θα φτάσουμε αργά. Θα δεχόμουν το Σάββατο αν δεν βρεθεί λύση, όμως δεν είναι η πρώτη μου επιλογή. Ας ξεχωρίσουμε τι προτιμάμε από όσα μπορούμε να ανεχτούμε.\\nΕίμαι ο Ορέστης. Εμένα με εξυπηρετεί μόνο το Σάββατο το πρωί, γιατί την Παρασκευή εργάζομαι μέχρι αργά. Θα ήθελα επίσης να ταξιδέψουμε με τρένο. Μπορούμε να συζητάμε ή να ξεκουραζόμαστε χωρίς να αναλάβει κάποιος την οδήγηση. Αν ο σταθμός βρίσκεται μακριά από το κατάλυμα, θα υπολογίσουμε χωριστά τη μικρή μετακίνηση από εκεί. Δεν έχω αντίρρηση να περπατήσω λίγο με τη βαλίτσα.\\nΕίμαι η Μυρτώ. Για την ημέρα αναχώρησης δεν θα εκφράσω ακόμη προτίμηση. Για τη διαδρομή, όμως, θα επέλεγα νοικιασμένο μικρό λεωφορείο με οδηγό. Θα μπορούσαμε να σταματήσουμε όπου χρειάζεται και να μεταφέρουμε όλοι μαζί τις αποσκευές. Καταλαβαίνω ότι ίσως κοστίσει περισσότερο από το τρένο. Γι’ αυτό θέλω συγκεκριμένη προσφορά πριν αποφασίσουμε, όχι μια αισιόδοξη υπόθεση για το συνολικό ποσό.\\nΔεν έχω αποφασίσει ανάμεσα στα δύο μέσα. Στον προορισμό θα προτιμούσα να μείνουμε σε μικρό ξενώνα στο κέντρο, ακόμη κι αν τα δωμάτια είναι απλά. Έτσι θα μπορεί ο καθένας να βγει μόνος του όταν θέλει. Δεν θα διάλεγα απομονωμένο κατάλυμα μόνο και μόνο για μεγαλύτερα δωμάτια, αν κάθε μικρή μετακίνηση απαιτεί συνεννόηση ολόκληρης της ομάδας.\\nΕγώ θα επέλεγα έναν ήσυχο χώρο έξω από το κέντρο, γιατί με ενδιαφέρει περισσότερο να ξεκουραστώ. Θα ήθελα ακόμη να κλείσουμε μια ξενάγηση το πρώτο πρωί. Ένας άνθρωπος που γνωρίζει τον τόπο μπορεί να μας βοηθήσει να καταλάβουμε όσα βλέπουμε. Δεν ζητάω οργανωμένο πρόγραμμα για κάθε ώρα, αλλά μία δραστηριότητα που θα μας δώσει κοινή αφετηρία.\\nΓια τη διαμονή θα περιμένω να δω τις επιλογές. Δεν θα έκλεινα ξενάγηση εκ των προτέρων. Προτιμώ έναν ελεύθερο περίπατο, ώστε να αλλάζουμε διαδρομή αν κάτι μας κινήσει το ενδιαφέρον. Όποιος θέλει οδηγό, φυσικά, μπορεί να αναζητήσει μια χωριστή δραστηριότητα. Αυτό δεν σημαίνει ότι πρέπει όλοι να ακολουθούμε το ίδιο πρόγραμμα για να θεωρούμαστε παρέα.\\nΘα ήθελα να κρατήσουμε το Σάββατο το απόγευμα τελείως ελεύθερο. Μπορούμε να συναντηθούμε ξανά για φαγητό χωρίς να εξηγήσει ο καθένας πώς πέρασε κάθε λεπτό. Για το εστιατόριο προτείνω μία κράτηση πριν φύγουμε, αφού πρώτα ρωτήσουμε για διαφορετικές διατροφικές ανάγκες. Δεν θέλω να ψάχνουμε όλοι μαζί όταν θα είμαστε ήδη κουρασμένοι και πεινασμένοι.\\nΕγώ θα διάλεγα εστιατόριο επί τόπου, βλέποντας τι μας ταιριάζει. Αν όμως οι άλλοι προτιμούν κράτηση, θα ακολουθήσω χωρίς να επιμείνω. Για τα χρήματα, θεωρώ απαραίτητο να συμφωνήσουμε από τώρα ένα ανώτατο ποσό ανά άτομο. Αλλιώς κινδυνεύουμε να δεχτούμε χωριστά πολλές μικρές δαπάνες που στο τέλος γίνονται απαγορευτικές για κάποιον, χωρίς να το έχει προβλέψει.\\nΓια το εστιατόριο δεν έχω πρόταση. Θα ήθελα όμως να μοιραστούμε τις οργανωτικές εργασίες, αντί να περιμένουμε να τα κάνει όλα η Λένα. Μπορώ να ζητήσω εγώ προσφορές μεταφοράς και κάποιος άλλος να ελέγξει τα καταλύματα. Ας επιστρέψουμε με συγκεκριμένα στοιχεία και ας αφήσουμε τις τελικές κρατήσεις για τότε. Η σημερινή συζήτηση δείχνει ανάγκες, όχι οριστική συμφωνία.", "version": "0.11.0", "audio_id": "KEG-B2-L03-AUD2", "register": "informative monologue / natural reasoned conversation", "segments": [{"text": "Είμαι η Λένα. Έχω συγκεντρώσει τις προτάσεις για την ομαδική μας εκδρομή, αλλά δεν έχω κάνει καμία κράτηση. Εγώ προτιμώ να φύγουμε Παρασκευή απόγευμα, ώστε να έχουμε δύο ολόκληρες ημέρες στον προορισμό. Ξέρω ότι θα φτάσουμε αργά. Θα δεχόμουν το Σάββατο αν δεν βρεθεί λύση, όμως δεν είναι η πρώτη μου επιλογή. Ας ξεχωρίσουμε τι προτιμάμε από όσα μπορούμε να ανεχτούμε.", "cue_id": "D00", "speaker": "Λένα", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Είμαι ο Ορέστης. Εμένα με εξυπηρετεί μόνο το Σάββατο το πρωί, γιατί την Παρασκευή εργάζομαι μέχρι αργά. Θα ήθελα επίσης να ταξιδέψουμε με τρένο. Μπορούμε να συζητάμε ή να ξεκουραζόμαστε χωρίς να αναλάβει κάποιος την οδήγηση. Αν ο σταθμός βρίσκεται μακριά από το κατάλυμα, θα υπολογίσουμε χωριστά τη μικρή μετακίνηση από εκεί. Δεν έχω αντίρρηση να περπατήσω λίγο με τη βαλίτσα.", "cue_id": "D01", "speaker": "Ορέστης", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Είμαι η Μυρτώ. Για την ημέρα αναχώρησης δεν θα εκφράσω ακόμη προτίμηση. Για τη διαδρομή, όμως, θα επέλεγα νοικιασμένο μικρό λεωφορείο με οδηγό. Θα μπορούσαμε να σταματήσουμε όπου χρειάζεται και να μεταφέρουμε όλοι μαζί τις αποσκευές. Καταλαβαίνω ότι ίσως κοστίσει περισσότερο από το τρένο. Γι’ αυτό θέλω συγκεκριμένη προσφορά πριν αποφασίσουμε, όχι μια αισιόδοξη υπόθεση για το συνολικό ποσό.", "cue_id": "D02", "speaker": "Μυρτώ", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Δεν έχω αποφασίσει ανάμεσα στα δύο μέσα. Στον προορισμό θα προτιμούσα να μείνουμε σε μικρό ξενώνα στο κέντρο, ακόμη κι αν τα δωμάτια είναι απλά. Έτσι θα μπορεί ο καθένας να βγει μόνος του όταν θέλει. Δεν θα διάλεγα απομονωμένο κατάλυμα μόνο και μόνο για μεγαλύτερα δωμάτια, αν κάθε μικρή μετακίνηση απαιτεί συνεννόηση ολόκληρης της ομάδας.", "cue_id": "D03", "speaker": "Λένα", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Εγώ θα επέλεγα έναν ήσυχο χώρο έξω από το κέντρο, γιατί με ενδιαφέρει περισσότερο να ξεκουραστώ. Θα ήθελα ακόμη να κλείσουμε μια ξενάγηση το πρώτο πρωί. Ένας άνθρωπος που γνωρίζει τον τόπο μπορεί να μας βοηθήσει να καταλάβουμε όσα βλέπουμε. Δεν ζητάω οργανωμένο πρόγραμμα για κάθε ώρα, αλλά μία δραστηριότητα που θα μας δώσει κοινή αφετηρία.", "cue_id": "D04", "speaker": "Ορέστης", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Για τη διαμονή θα περιμένω να δω τις επιλογές. Δεν θα έκλεινα ξενάγηση εκ των προτέρων. Προτιμώ έναν ελεύθερο περίπατο, ώστε να αλλάζουμε διαδρομή αν κάτι μας κινήσει το ενδιαφέρον. Όποιος θέλει οδηγό, φυσικά, μπορεί να αναζητήσει μια χωριστή δραστηριότητα. Αυτό δεν σημαίνει ότι πρέπει όλοι να ακολουθούμε το ίδιο πρόγραμμα για να θεωρούμαστε παρέα.", "cue_id": "D05", "speaker": "Μυρτώ", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Θα ήθελα να κρατήσουμε το Σάββατο το απόγευμα τελείως ελεύθερο. Μπορούμε να συναντηθούμε ξανά για φαγητό χωρίς να εξηγήσει ο καθένας πώς πέρασε κάθε λεπτό. Για το εστιατόριο προτείνω μία κράτηση πριν φύγουμε, αφού πρώτα ρωτήσουμε για διαφορετικές διατροφικές ανάγκες. Δεν θέλω να ψάχνουμε όλοι μαζί όταν θα είμαστε ήδη κουρασμένοι και πεινασμένοι.", "cue_id": "D06", "speaker": "Λένα", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Εγώ θα διάλεγα εστιατόριο επί τόπου, βλέποντας τι μας ταιριάζει. Αν όμως οι άλλοι προτιμούν κράτηση, θα ακολουθήσω χωρίς να επιμείνω. Για τα χρήματα, θεωρώ απαραίτητο να συμφωνήσουμε από τώρα ένα ανώτατο ποσό ανά άτομο. Αλλιώς κινδυνεύουμε να δεχτούμε χωριστά πολλές μικρές δαπάνες που στο τέλος γίνονται απαγορευτικές για κάποιον, χωρίς να το έχει προβλέψει.", "cue_id": "D07", "speaker": "Ορέστης", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}, {"text": "Για το εστιατόριο δεν έχω πρόταση. Θα ήθελα όμως να μοιραστούμε τις οργανωτικές εργασίες, αντί να περιμένουμε να τα κάνει όλα η Λένα. Μπορώ να ζητήσω εγώ προσφορές μεταφοράς και κάποιος άλλος να ελέγξει τα καταλύματα. Ας επιστρέψουμε με συγκεκριμένα στοιχεία και ας αφήσουμε τις τελικές κρατήσεις για τότε. Η σημερινή συζήτηση δείχνει ανάγκες, όχι οριστική συμφωνία.", "cue_id": "D08", "speaker": "Μυρτώ", "end_seconds": null, "start_seconds": null, "timecode_status": "UNMEASURED_NO_AUDIO"}], "output_path": null, "target_path": "audio/exams/KEG-B2-L03-AUD2.wav", "speaker_role": ["Λένα", "Ορέστης", "Μυρτώ"], "measured_cues": [], "native_review": {"status": "NOT_PERFORMED"}, "speaking_rate": "B2 natural, final rate established by listener pilot", "voice_profile": "Natural distinct standard Modern Greek voices, audible self-introductions in dialogue", "format_request": "Project master WAV PCM48kHz24bit; not an official KEG requirement", "task_alignment": [{"key": ["Λένα"], "cue_ids": ["D00"], "item_id": "KEG-B2-L03-A01"}, {"key": ["Ορέστης"], "cue_ids": ["D01"], "item_id": "KEG-B2-L03-A02"}, {"key": ["Μυρτώ"], "cue_ids": ["D02"], "item_id": "KEG-B2-L03-A03"}, {"key": ["Λένα"], "cue_ids": ["D03"], "item_id": "KEG-B2-L03-A04"}, {"key": ["Ορέστης"], "cue_ids": ["D04"], "item_id": "KEG-B2-L03-A05"}, {"key": ["Ορέστης"], "cue_ids": ["D04"], "item_id": "KEG-B2-L03-A06"}, {"key": ["Μυρτώ"], "cue_ids": ["D05"], "item_id": "KEG-B2-L03-A07"}, {"key": ["Λένα"], "cue_ids": ["D06"], "item_id": "KEG-B2-L03-A08"}, {"key": ["Ορέστης"], "cue_ids": ["D07"], "item_id": "KEG-B2-L03-A09"}, {"key": ["Μυρτώ"], "cue_ids": ["D08"], "item_id": "KEG-B2-L03-A10"}], "acceptance_tests": ["Document voice and commercial distribution rights", "Hash actual bytes and measure duration,cue timings,peak,Loudness; reject clipping/truncation", "Blind Greek listener solves all tasks without transcript", "Then verify every word,number,negation and s