2776	competency	PEGP-P05-GEO-004-MC	b99e93b9e4ce43b12450ecadc45ec7dd5ca2a51756152f92b145c3531e7e2d99	pegp	{"module": "pegp", "definition": {"rubric": {"0": "Required relation absent/false", "1": "Partial requested information or assistance", "2": "All requested factual information independently conveyed; equivalent wording accepted", "accent_policy": "Tag stress/form errors separately; do not turn correct fact into incorrect fact.", "language_score_separate": true}, "status": "AUTHORED_DRAFT", "card_id": "PEGP-P05-GEO-004-CARD", "item_id": "PEGP-P05-GEO-004", "theory_ru": "Ласити — региональная единица, а Крит — географическое отделение в этой классификации. Не отвечайте названием города: проверяется отношение части и более крупной территории. Карточка не требует перечисления всех единиц Крита.", "source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057909#page=21", "sha256": "b2c569c8349c9150d4a96bf685647657d66bfc7ba08e12b02badddaf301e869a", "pdf_page": 21, "source_id": "PEGP-BANK-1057909", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 21, "official_topic": 45, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}], "competency_id": "PEGP-P05-GEO-004-MC", "prerequisites": ["Basic Greek question comprehension", "Read the names and relation in this card"], "delayed_review": {"D7": "Σε ποιο γεωγραφικό διαμέρισμα ανήκει το Λασίθι;", "D28": "Σε έναν χάρτη το Λασίθι σημειώνεται στην Πελοπόννησο. Διόρθωσε την περιοχή.", "conditions": "Without card/options; score only requested relation, not literal base key"}, "mastery_criteria": {"fact": "Correct requested factual relation with no contradiction", "observed": false, "retention": "D7 and D28 completed independently; no observations yet", "production": "Independent completion of transfer task"}, "original_example": "Το Λασίθι είναι μία από τις Περιφερειακές Ενότητες της Κρήτης.", "practice_item_ids": ["PEGP-P05-GEO-004"], "observable_outcome": "Самостоятельно воспроизвести выбранную связь и применить её в исправлении/объяснении", "independent_transfer": {"prompt_el": "Δώσε σε έναν φίλο σύντομη εξήγηση γιατί το Λασίθι μπαίνει στον φάκελο «Κρήτη».", "conditions": "Hide original card and keys; produce own utterance; do not require details absent from prompt.", "model_not_exhaustive": true}, "prerequisite_support": {"probe": "Объясните по-русски, что именно требуется назвать в основном вопросе; затем прочтите ключевые имена.", "remediation": "Разобрать имя, падеж и отношение с русской опорой; закрыть модель перед самостоятельной попыткой."}}, "source_path": "GreekOS_PEGP_Module/PEGP-2026-11-P05.json", "competency_id": "PEGP-P05-GEO-004-MC"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
