2782	competency	PEGP-P05-CUL-002-MC	f3b39d90715063cdb68f77c22fc7c8da0e485637f3b8276faff95ed4d74ff0d3	pegp	{"module": "pegp", "definition": {"rubric": {"0": "Required relation absent/false", "1": "Partial requested information or assistance", "2": "All requested factual information independently conveyed; equivalent wording accepted", "accent_policy": "Tag stress/form errors separately; do not turn correct fact into incorrect fact.", "language_score_separate": true}, "status": "AUTHORED_DRAFT", "card_id": "PEGP-P05-CUL-002-CARD", "item_id": "PEGP-P05-CUL-002", "theory_ru": "Неоклассицизм обращается к элементам древнегреческой архитектуры; в источнике выделены колонны преимущественно с ионическими капителями. Слово «преимущественно» важно: это не запрет других ордеров. Карточка даёт словесный признак, но не заменяет распознавание зданий на фотографии. Изображения официального задания не копируются без подтверждения прав.", "source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057906#page=19", "sha256": "5163ff77c395802de2f24f88cfb65be7cc4681c128c6801e1d6d2566bceaea2d", "pdf_page": 19, "source_id": "PEGP-BANK-1057906", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 19, "official_topic": 31, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}], "competency_id": "PEGP-P05-CUL-002-MC", "prerequisites": ["Basic Greek question comprehension", "Read the names and relation in this card"], "delayed_review": {"D7": "Ποιο στοιχείο της αρχαίας αρχιτεκτονικής επανεμφανίζεται στην περιγραφή του Νεοκλασικισμού;", "D28": "Εξήγησε γιατί η λέξη «κυρίως» δεν σημαίνει «αποκλειστικά» στην περιγραφή των κιονοκράνων.", "conditions": "Without card/options; score only requested relation, not literal base key"}, "mastery_criteria": {"fact": "Correct requested factual relation with no contradiction", "observed": false, "retention": "D7 and D28 completed independently; no observations yet", "production": "Independent completion of transfer task"}, "original_example": "Η περιγραφή του νεοκλασικού κτηρίου αναφέρει κίονες και ιωνικά κιονόκρανα.", "practice_item_ids": ["PEGP-P05-CUL-002"], "observable_outcome": "Самостоятельно воспроизвести выбранную связь и применить её в исправлении/объяснении", "independent_transfer": {"prompt_el": "Διόρθωσε την απόλυτη διατύπωση «ο Νεοκλασικισμός δεν χρησιμοποιεί κίονες».", "conditions": "Hide original card and keys; produce own utterance; do not require details absent from prompt.", "model_not_exhaustive": true}, "prerequisite_support": {"probe": "Объясните по-русски, что именно требуется назвать в основном вопросе; затем прочтите ключевые имена.", "remediation": "Разобрать имя, падеж и отношение с русской опорой; закрыть модель перед самостоятельной попыткой."}}, "source_path": "GreekOS_PEGP_Module/PEGP-2026-11-P05.json", "competency_id": "PEGP-P05-CUL-002-MC"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
