2786	competency	PEGP-P05-INS-002-MC	4b78406fce031a9f14e9e35ea75ac8843d7ed233aca09e146d05d4128fb457e9	pegp	{"module": "pegp", "definition": {"rubric": {"0": "Required relation absent/false", "1": "Partial requested information or assistance", "2": "All requested factual information independently conveyed; equivalent wording accepted", "accent_policy": "Tag stress/form errors separately; do not turn correct fact into incorrect fact.", "language_score_separate": true}, "status": "AUTHORED_DRAFT", "card_id": "PEGP-P05-INS-002-CARD", "item_id": "PEGP-P05-INS-002", "theory_ru": "В изучаемых первой серии и серии Europa мосты на обороте банкнот символизируют общение между народами. Это символический мотив, а не набор точных изображений существующих мостов. Карточка не распространяет утверждение на возможные будущие дизайны. Изображение банкноты не воспроизводится.", "source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057910#page=19", "sha256": "1f09beeb569cae5ac98d86a44f3d130ab3581eeb9e94edf2dcdae470ea379e0f", "pdf_page": 19, "source_id": "PEGP-BANK-1057910", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 19, "official_topic": 35, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}], "competency_id": "PEGP-P05-INS-002-MC", "prerequisites": ["Basic Greek question comprehension", "Read the names and relation in this card"], "delayed_review": {"D7": "Τι συμβολίζουν οι γέφυρες στις δύο εξεταζόμενες σειρές ευρώ;", "D28": "Διόρθωσε τη φράση «οι γέφυρες στα χαρτονομίσματα συμβολίζουν συγκεκριμένους ηγέτες».", "conditions": "Without card/options; score only requested relation, not literal base key"}, "mastery_criteria": {"fact": "Correct requested factual relation with no contradiction", "observed": false, "retention": "D7 and D28 completed independently; no observations yet", "production": "Independent completion of transfer task"}, "original_example": "Οι γέφυρες στα χαρτονομίσματα συμβολίζουν την επικοινωνία.", "practice_item_ids": ["PEGP-P05-INS-002"], "observable_outcome": "Самостоятельно воспроизвести выбранную связь и применить её в исправлении/объяснении", "independent_transfer": {"prompt_el": "Εξήγησε σε έναν φίλο γιατί ο συμβολισμός των γεφυρών σχετίζεται με την επικοινωνία και όχι με διάσημα πρόσωπα.", "conditions": "Hide original card and keys; produce own utterance; do not require details absent from prompt.", "model_not_exhaustive": true}, "prerequisite_support": {"probe": "Объясните по-русски, что именно требуется назвать в основном вопросе; затем прочтите ключевые имена.", "remediation": "Разобрать имя, падеж и отношение с русской опорой; закрыть модель перед самостоятельной попыткой."}}, "source_path": "GreekOS_PEGP_Module/PEGP-2026-11-P05.json", "competency_id": "PEGP-P05-INS-002-MC"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
