2788	competency	PEGP-P05-INS-004-MC	44fae7454d1f6f659c8e5344c8716438abe863dc3884c96cdd21dac467276e23	pegp	{"module": "pegp", "definition": {"rubric": {"0": "Required relation absent/false", "1": "Partial requested information or assistance", "2": "All requested factual information independently conveyed; equivalent wording accepted", "accent_policy": "Tag stress/form errors separately; do not turn correct fact into incorrect fact.", "language_score_separate": true}, "status": "AUTHORED_DRAFT", "card_id": "PEGP-P05-INS-004-CARD", "item_id": "PEGP-P05-INS-004", "theory_ru": "В статье26 исполнительная функция отнесена к Президенту Республики и Правительству; законодательная — к Парламенту и Президенту. Основной вопрос спрашивает только второго участника исполнительной функции. Не делайте из этой схемы выводов о полномочиях по конкретному делу: распределение практических полномочий требует других статей.", "source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057910#page=21", "sha256": "1f09beeb569cae5ac98d86a44f3d130ab3581eeb9e94edf2dcdae470ea379e0f", "pdf_page": 21, "source_id": "PEGP-BANK-1057910", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 21, "official_topic": 39, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}], "competency_id": "PEGP-P05-INS-004-MC", "prerequisites": ["Basic Greek question comprehension", "Read the names and relation in this card"], "delayed_review": {"D7": "Ποιο όργανο ασκεί την εκτελεστική λειτουργία μαζί με τον Πρόεδρο;", "D28": "Πες τα δύο όργανα της εκτελεστικής λειτουργίας, σύμφωνα με το άρθρο26 που μελετήσαμε.", "conditions": "Without card/options; score only requested relation, not literal base key"}, "mastery_criteria": {"fact": "Correct requested factual relation with no contradiction", "observed": false, "retention": "D7 and D28 completed independently; no observations yet", "production": "Independent completion of transfer task"}, "original_example": "Η εκτελεστική λειτουργία συνδέεται με τον Πρόεδρο της Δημοκρατίας και την Κυβέρνηση.", "practice_item_ids": ["PEGP-P05-INS-004"], "observable_outcome": "Самостоятельно воспроизвести выбранную связь и применить её в исправлении/объяснении", "independent_transfer": {"prompt_el": "Ένας πίνακας βάζει τη Βουλή δίπλα στον Πρόεδρο στην εκτελεστική λειτουργία. Αντικατάστησε τη Βουλή με το όργανο της κάρτας.", "conditions": "Hide original card and keys; produce own utterance; do not require details absent from prompt.", "model_not_exhaustive": true}, "prerequisite_support": {"probe": "Объясните по-русски, что именно требуется назвать в основном вопросе; затем прочтите ключевые имена.", "remediation": "Разобрать имя, падеж и отношение с русской опорой; закрыть модель перед самостоятельной попыткой."}}, "source_path": "GreekOS_PEGP_Module/PEGP-2026-11-P05.json", "competency_id": "PEGP-P05-INS-004-MC"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
2789	competency	PEGP-P03-GEO-001-MC	09bc5be36fbed597e1e31b621b712e33c5210ef039cbf4f5916a820312f88e6c	pegp	{"module": "pegp", "definition": {"rubric": {"0": "Для данного предъявленного задания требуемый факт неверен либо отсутствует; base-item key применяется только к базовому item.", "1": "Требуемая заданием фактическая связь названа неполно или после помощи; не требуйте необязательных деталей модели.", "2": "Самостоятельно выполнены условия именно предъявленного задания; достаточное имя/дата/слово допустимы. Дополнительные верные детали модели не обязательны.", "fact_anchor": ["Αιτωλοακαρνανίας"], "transfer_anchor": "Η λίμνη Τριχωνίδα βρίσκεται στην Περιφερειακή Ενότητα Αιτωλοακαρνανίας.", "transfer_scoring": "Score the actual independent_transfer prompt. Accept a short sufficient name/date/word if that is all requested. Do not compare a reverse-retrieval answer with the base-item key.", "fact_anchor_scope": "BASE_ITEM_ONLY", "transfer_anchor_scope": "NON_EXHAUSTIVE_INSTRUCTOR_EXAMPLE; not all details compulsory", "language_score_separate": true}, "card_id": "PEGP-P03-GEO-001-CARD", "item_id": "PEGP-P03-GEO-001", "theory_ru": "Озеро Трихонида: привязка к региональной единице Этолия и Акарнания. Не путать озеро с городом.", "source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057909#page=10", "sha256": "b2c569c8349c9150d4a96bf685647657d66bfc7ba08e12b02badddaf301e869a", "pdf_page": 10, "source_id": "PEGP-BANK-1057909", "checked_on": "2026-10-15", "bank_version": "2026/11", "printed_page": 10, "official_topic": 20}], "competency_id": "PEGP-P03-GEO-001-MC", "prerequisites": ["Прочитать греческие собственные имена", "Понять русское объяснение и ключевой греческий термин"], "delayed_review": {"D7": "Без карточки: Η Τριχωνίδα βρίσκεται στην Περιφερειακή Ενότητα ___.", "D28": "Без подсказки назовите изученное здесь озеро и его региональную единицу.", "conditions": "Новый порядок предъявления; модель скрыта; факт и язык оцениваются отдельно"}, "mastery_criteria": {"fact": "Точно названа связь; нет противоречащего добавления", "observed": false, "retention": "Верное D7 и D28 без помощи", "production": "Объяснение без готовой модели"}, "original_example": "Η λίμνη Τριχωνίδα βρίσκεται στην Περιφερειακή Ενότητα Αιτωλοακαρνανίας.", "practice_item_ids": ["PEGP-P03-GEO-001"], "observable_outcome": "Воспроизвести проверенную связь и объяснить её в новой формулировке: Αιτωλοακαρνανίας", "independent_transfer": {"model_el": "Η λίμνη Τριχωνίδα βρίσκεται στην Περιφερειακή Ενότητα Αιτωλοακαρνανίας.", "prompt_ru": "Назовите изученное в этой карточке озеро, связанное с Αιτωλοακαρνανία; другие озёра области не требуются.", "model_not_exhaustive": true}}, "source_path": "GreekOS_PEGP_Module/PEGP-2026-11-P03.json", "competency_id": "PEGP-P03-GEO-001-MC"}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
