3484	item	PEGP-LANG-P05-08	9eab8821295a2cd490151383798bdf3c7fa387469bb3ebfd70ebb574132a7e97	pegp	{"type": "D28_transfer", "level": "B1", "answer": [], "module": "pegp", "prompt": "Μετά από 28 ημέρες διαβάστε το νέο μήνυμα: «Η ξενάγηση θα γίνει το Σάββατο στις 11:00. Αν βρέχει, θα μεταφερθεί στην Κυριακή την ίδια ώρα. Θα στείλουμε επιβεβαίωση την Παρασκευή». Ένας φίλος λέει: «Άρα σίγουρα την Κυριακή». Διορθώστε τον, εξηγώντας το αρχικό σχέδιο, την προϋπόθεση αλλαγής και πότε αναμένεται επιβεβαίωση.", "rubric": {"mastery": "Ανεξάρτητη πρώτη προσπάθεια και νέα καθυστερημένη μεταφορά· το υπόδειγμα δεν είναι μοναδική λύση.", "task_0_2": {"0": "Δεν μεταδίδονται τα βασικά ζητούμενα ή αλλάζει κρίσιμο γεγονός.", "1": "Μεταδίδεται μέρος των ζητουμένων ή χρειάζεται βοήθεια.", "2": "Διατηρεί Σάββατο11:00, αλλαγή μόνο αν βρέχει, Κυριακή ίδια ώρα και επιβεβαίωση Παρασκευή· δεν υποθέτει καιρό."}, "language_0_2": {"0": "Το νόημα δεν γίνεται κατανοητό.", "1": "Το νόημα γίνεται κατανοητό με προσπάθεια· υπάρχουν γλωσσικά λάθη.", "2": "Κατανοητές συνδεδεμένες φράσεις κατάλληλες για τον συγκεκριμένο αποδέκτη· μικρά λάθη δεν αλλάζουν το νόημα."}, "speaking_only": "Προφορά μόνο από πραγματικό ήχο με ακουστική αξιολόγηση. Γραπτό/ASR κείμενο: NO_PRONUNCIATION_SCORE."}, "item_id": "PEGP-LANG-P05-08", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": null, "version": "0.1.0", "criteria": [], "stimulus": {"text_id": "PEGP-LANG-P05-T01"}, "canonical": {"path": "GreekOS_PEGP_Module/language_support/items/PEGP-LANG-P05-08.json", "sha256": "72d72952acc079b1613051bc9bd758a656582876cfd6eec66752c87c4d422b46"}, "error_tags": null, "audio_job_ids": [], "competency_ids": [], "model_response": "Όχι απαραίτητα. Το αρχικό σχέδιο είναι το Σάββατο στις έντεκα. Μόνο αν βρέχει θα μεταφερθεί η ξενάγηση στην Κυριακή, την ίδια ώρα. Θα περιμένουμε την επιβεβαίωση την Παρασκευή.", "requires_audio": false, "estimated_effort": null, "original_payload": {"rubric": {"mastery": "Ανεξάρτητη πρώτη προσπάθεια και νέα καθυστερημένη μεταφορά· το υπόδειγμα δεν είναι μοναδική λύση.", "task_0_2": {"0": "Δεν μεταδίδονται τα βασικά ζητούμενα ή αλλάζει κρίσιμο γεγονός.", "1": "Μεταδίδεται μέρος των ζητουμένων ή χρειάζεται βοήθεια.", "2": "Διατηρεί Σάββατο11:00, αλλαγή μόνο αν βρέχει, Κυριακή ίδια ώρα και επιβεβαίωση Παρασκευή· δεν υποθέτει καιρό."}, "language_0_2": {"0": "Το νόημα δεν γίνεται κατανοητό.", "1": "Το νόημα γίνεται κατανοητό με προσπάθεια· υπάρχουν γλωσσικά λάθη.", "2": "Κατανοητές συνδεδεμένες φράσεις κατάλληλες για τον συγκεκριμένο αποδέκτη· μικρά λάθη δεν αλλάζουν το νόημα."}, "speaking_only": "Προφορά μόνο από πραγματικό ήχο με ακουστική αξιολόγηση. Γραπτό/ASR κείμενο: NO_PRONUNCIATION_SCORE."}, "status": "AUTHORED_DRAFT", "strand": "PEGP_LANGUAGE_SUPPORT_ORIGINAL", "item_id": "PEGP-LANG-P05-08", "version": "0.1.0", "prompt_el": "Μετά από 28 ημέρες διαβάστε το νέο μήνυμα: «Η ξενάγηση θα γίνει το Σάββατο στις 11:00. Αν βρέχει, θα μεταφερθεί στην Κυριακή την ίδια ώρα. Θα στείλουμε επιβεβαίωση την Παρασκευή». Ένας φίλος λέει: «Άρα σίγουρα την Κυριακή». Διορθώστε τον, εξηγώντας το αρχικό σχέδιο, την προϋπόθεση αλλαγής και πότε αναμένεται επιβεβαίωση.", "rationale": "Новая ситуация проверяет перенос: исходный план, условность и подтверждение. Не предполагаем фактическую погоду и не заменяем условие уверенностью.", "evaluation": {"unlisted_plausible_answer": "REVIEW_NO_AUTOMATIC_PENALTY", "fact_and_language_separate": true}, "answer_type": "D28_transfer", "publishable": false, "source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057909#page=18", "sha256": "b2c569c8349c9150d4a96bf685647657d66bfc7ba08e12b02badddaf301e869a", "pdf_page": 18, "source_id": "PEGP-BANK-1057909", "checked_on": "2026-