3024	object	RUB-KEG-WRITING-PROJECT	aad5107b49ef5b8c96ffcdcb0f3ebd6d978eb1b46ebe7e7f6f31e816e0422739	\N	{"refs": [{"path": "GreekOS_B2_Exam_Bank/RUB-KEG-WRITING-PROJECT.json", "sha256": "5bd2ebb9c8e376e92f091c7fe715d3fd5d342a6ec555d6d43237fa3390132a08", "pointer": ""}], "payload": {"version": "0.1.0", "criteria": [{"scale": "0=не продемонстрировано;1=частично;2=устойчиво на этой задаче; описательное наблюдение, не официальный вес", "criterion": "Выполнение пунктов"}, {"scale": "0=не продемонстрировано;1=частично;2=устойчиво на этой задаче; описательное наблюдение, не официальный вес", "criterion": "Организация и связность"}, {"scale": "0=не продемонстрировано;1=частично;2=устойчиво на этой задаче; описательное наблюдение, не официальный вес", "criterion": "Регистр и адресат"}, {"scale": "0=не продемонстрировано;1=частично;2=устойчиво на этой задаче; описательное наблюдение, не официальный вес", "criterion": "Лексический диапазон и уместность"}, {"scale": "0=не продемонстрировано;1=частично;2=устойчиво на этой задаче; описательное наблюдение, не официальный вес", "criterion": "Грамматический контроль"}, {"scale": "0=не продемонстрировано;1=частично;2=устойчиво на этой задаче; описательное наблюдение, не официальный вес", "criterion": "Орфография и ударения"}], "rubric_id": "RUB-KEG-WRITING-PROJECT", "source_refs": ["V243"], "exam_profile": "KEG_B2", "human_review": "NOT_REVIEWED", "score_policy": "Профиль0–2 по аспектам не складывается в официальный балл10/20; калиброванное преобразование отсутствует. Для тренировочной оценки нужна отдельная экспертная подпись.", "review_status": "DRAFT", "scored_exemplars": []}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3025	object	KEG-B2-U02-T1	80b38dad7fe341142ff6676ac331005b27afcfbc4c3ab27fb3e53a1b3c26f30d	\N	{"refs": [{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-U02-T1.json", "sha256": "eb4c30eda05514d3a2fa8a1afef5c42a9a7bafa4cd8b41a7df630d378c72ba1b", "pointer": ""}], "payload": {"text": "Παράδειγμα (0): Η επιτροπή θέλει ότι να ενημερωθεί. Αφαιρείται το «ότι».\\n\\n(1) Η επιτροπή της πολυκατοικίας συμφώνησε ότι ο παλιός αποθηκευτικός χώρος να έπρεπε να αξιοποιηθεί για ποδήλατα. Πριν παραγγείλει εξοπλισμό, ζήτησε από τους ενοίκους να δηλώσουν πόσες θέσεις χρειάζονταν πραγματικά.\\n\\n(2) Κανένας ένοικος δεν ήταν υποχρεωμένος ότι να συμμετάσχει στην αγορά στηριγμάτων. Όσοι δεν είχαν ποδήλατο μπορούσαν ωστόσο να προτείνουν κανόνες, αφού η είσοδος του χώρου ήταν κοινή για όλους.\\n\\n(3) Ο τεχνικός συνέστησε να διατηρηθεί ελεύθερος ο διάδρομος, αντί για να γεμίσει με πρόσθετες βάσεις. Η ασφάλεια της πρόσβασης κρίθηκε σημαντικότερη από την εξασφάλιση λίγων ακόμη θέσεων στο βάθος.\\n\\n(4) Η τελική απόφαση εξαρτήθηκε από το πόσο θα κόστιζε η εγκατάσταση, όχι από για τις προσωπικές προτιμήσεις του διαχειριστή. Παρουσιάστηκαν δύο προσφορές με διαφορετικό κόστος συντήρησης, ώστε να γίνει ουσιαστική σύγκριση.\\n\\n(5) Οι κάτοικοι επέλεξαν τη λύση που θα μπορούσαν να θα συντηρούν μόνοι τους. Δεν ήθελαν μια εγκατάσταση της οποίας η λειτουργία θα εξαρτιόταν διαρκώς από ακριβά ανταλλακτικά ή εξωτερική τεχνική υποστήριξη.\\n\\n(6) Κατά την παράδοση, ο υπεύθυνος εξήγησε σε πώς λειτουργούσε η κλειδαριά και παρέδωσε γραπτές οδηγίες. Κάθε χρήστης ανέλαβε να αφήνει τον χώρο τακτοποιημένο, ακόμη κι όταν βιαζόταν να φύγει.\\n\\n(7) Μετά από έναν μήνα εξετάστηκαν τα σχόλια των χρηστών. Το αν η λύση ήταν πρακτική δεν μπορούσε να κριθεί μόνο από την εμφάνισή της, αλλά ούτε από όσο τον αρχικό ενθουσιασμό. Η επανεξέταση έγινε σε κοινή συνάντηση, ώστε ακόμη και όσοι χρησιμοποιούσαν σπάνια τον χώρο να μπορούν να εξηγήσουν τις δικές τους ανάγκες.", "status": "AUTHOR_COMPLETE_AI_REVIEW_PENDING", "text_id": "KEG-B2-U02-T1", "version": "0.1.1", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "word_count": 241, "word_count_method": "Greek lexical tokens; printed example counted separately in QA"}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3026	object	KEG-B2-U01-TEXT3	287d577279c93ba2efbe84e7e4de66455ec0a9e96a2116a128b001038e8c3002	\N	{"refs": [{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-U01-TEXT3.json", "sha256": "522120af70276575ae75d78809b2976850cfe02e652d0d764556e26230696517", "pointer": ""}], "payload": {"text": "Ένα μικρό αναγνωστήριο αποφάσισε να δανείζει επιτραπέζια παιχνίδια, (0) ___ μέχρι τότε διέθετε μόνο βιβλία. Η πρόταση προήλθε από μια ομάδα γονέων, οι οποίοι ήθελαν να δοκιμάζουν παιχνίδια στο σπίτι πριν αποφασίσουν αν θα αγόραζαν κάποιο.\\nΟι υπεύθυνοι δέχτηκαν την ιδέα, (1) ___ έθεσαν έναν όρο: κάθε παιχνίδι θα έπρεπε να συνοδεύεται από κατάλογο των κομματιών του. Ο έλεγχος θα γινόταν κατά την επιστροφή, χωρίς να θεωρείται αυτόματα υπεύθυνος ο τελευταίος δανειστής για κάθε παλιότερη φθορά.\\nΣτην αρχή διατέθηκαν λίγα παιχνίδια, (2) ___ οι εθελοντές να εξοικειωθούν με τη διαδικασία. Η ομάδα εξήγησε τους κανόνες σε μια ανοιχτή συνάντηση και ζήτησε να σημειώνονται οι δυσκολίες. (3) ___ εμφανιζόταν κάποιο πρόβλημα, θα εξεταζόταν πρώτα τι ακριβώς είχε συμβεί.\\nΈνας γονέας πρότεινε μεγαλύτερη διάρκεια δανεισμού, (4) ___ ορισμένες οικογένειες μπορούσαν να παίζουν μόνο το Σαββατοκύριακο. Μια άλλη συμμετέχουσα παρατήρησε ότι αυτό θα περιόριζε τη διαθεσιμότητα για τους υπόλοιπους. Συμφώνησαν τελικά να κρατήσουν το αρχικό όριο για έναν μήνα και να συγκρίνουν τις ανάγκες με τις πραγματικές επιστροφές.\\nΗ δοκιμή δεν είχε ολοκληρωθεί, (5) ___ το προσωπικό ετοίμασε μια πρώτη καταγραφή. Την παρουσίασε περισσότερο ως βάση για συζήτηση (6) ___ ως τελική αξιολόγηση. Στόχος ήταν να διαπιστωθεί (7) ___ η νέα υπηρεσία μπορούσε να λειτουργήσει σταθερά με τον διαθέσιμο χρόνο και τους ανθρώπους που ήδη βοηθούσαν. Οι αποφάσεις για την επέκταση θα λαμβάνονταν αργότερα. Στο μεταξύ, οι συμμετέχοντες μπορούσαν να προτείνουν μικρές αλλαγές στους κανόνες, αρκεί να εξηγούσαν ποια συγκεκριμένη δυσκολία προσπαθούσαν να αντιμετωπίσουν με την πρότασή τους.", "format": "gapped_text_with_distractors", "status": "DRAFT", "example": {"gap": "0", "answer": "ενώ"}, "text_id": "KEG-B2-U01-TEXT3", "version": "0.1.0", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "word_bank": ["κατά πόσο", "παρά", "επειδή", "όταν", "ώστε", "αλλά", "ενώ", "αν", "παρά τη", "αντί για", "δηλαδή", "χάρη στην", "εξαιτίας"], "bank_reuse_allowed": false, "surface_greek_word_count": 229}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3027	object	KEG-B2-R02-T1	38f63a0346fb38a02282c74879ba4f49b34e6d1b25b7fc6ec56d9256dcd9b7d8	\N	{"refs": [{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-R02-T1.json", "sha256": "472f67fafae8da51f9357c112ab6b8a003d1ddaaf4121551ef9976fff0b52a2f", "pointer": ""}], "payload": {"text": "Η εργασία δεν τελειώνει πάντα όταν κλείνει το γραφείο. Ένα μήνυμα στο κινητό μπορεί να επαναφέρει μια εκκρεμότητα την ώρα του φαγητού. Η δυνατότητα επικοινωνίας διευκολύνει τη συνεργασία, αλλά δημιουργεί και την προσδοκία ότι ο εργαζόμενος είναι (0) [διαρκώς διαθέσιμος]. Το ζήτημα δεν αφορά μόνο όσους εργάζονται από το σπίτι.\\nΜια μικρή ομάδα αποφάσισε να εξετάσει πώς χρησιμοποιεί τα ψηφιακά εργαλεία. Αντί να απαγορεύσει κάθε επικοινωνία, ζήτησε από τα μέλη της να καταγράψουν (1) ___. Η καταγραφή έδειξε ότι πολλά μηνύματα στέλνονταν αργά επειδή τότε εξυπηρετούνταν ο αποστολέας, όχι επειδή το θέμα ήταν επείγον. Ο παραλήπτης, ωστόσο, δεν μπορούσε να γνωρίζει (2) ___. Συχνά απαντούσε αμέσως, από φόβο μήπως θεωρηθεί αδιάφορος.\\nΗ ομάδα συμφώνησε να διακρίνει την αποστολή ενός μηνύματος (3) ___. Όποιος εργάζεται με διαφορετικό ωράριο μπορεί να ετοιμάζει την επικοινωνία του όταν τον εξυπηρετεί, χρησιμοποιώντας προγραμματισμένη αποστολή. Για πραγματικά επείγουσες περιπτώσεις ορίστηκε (4) ___, ώστε να μην παρουσιάζεται κάθε μικρή εκκρεμότητα ως κρίση. Παράλληλα, οι εργασίες οργανώθηκαν με σαφή υπεύθυνο και προθεσμία.\\nΗ αλλαγή δεν ήταν απλώς τεχνική. Έπρεπε να συζητηθεί αν η γρήγορη απάντηση χρησιμοποιούνταν (5) ___. Αν ένας προϊστάμενος επαινεί συστηματικά όσους απαντούν τα μεσάνυχτα, μια γραπτή οδηγία για ξεκούραση δύσκολα πείθει. Χρειάζεται συνέπεια ανάμεσα (6) ___. Διαφορετικά, οι εργαζόμενοι συνεχίζουν να παρακολουθούν την οθόνη, ακόμη κι όταν δεν έρχεται κανένα μήνυμα.\\nΥπήρξαν και αντιρρήσεις. Κάποιοι φοβήθηκαν ότι οι κοινοί κανόνες θα περιόριζαν (7) ___, ιδίως για όσους φροντίζουν παιδιά. Η λύση δεν ήταν να επιβληθεί το ίδιο ωράριο σε όλους, αλλά να γίνουν σαφή τα διαστήματα συνεργασίας και η δυνατότητα καθυστερημένης απάντησης. Οι κανόνες προσαρμόστηκαν (8) ___, χωρίς να μετατρέπονται σε ατομική διαπραγμάτευση κάθε βράδυ.\\nΎστερα από έξι εβδομάδες, η ομάδα συζήτησε ξανά την εμπειρία. Δεν θεώρησε τον μικρότερο αριθμό μηνυμάτων (9) ___. Εξέτασε επίσης αν χάθηκαν σημαντικές πληροφορίες και αν οι προθεσμίες παρέμεναν ρεαλιστικές. Οι απόψεις δεν ήταν όλες ίδιες, αλλά τα προβλήματα μπορούσαν πλέον να περιγραφούν (10) ___ αντί να αποδίδονται σε προσωπική αδυναμία.\\nΜια τέτοια δοκιμή δεν αποδεικνύει ότι υπάρχει μία λύση για κάθε επάγγελμα. Δείχνει όμως ότι η τεχνολογία χρειάζεται (11) ___. Ο στόχος δεν είναι να εξαφανιστεί η επικοινωνία, αλλά να συνδυαστεί η συνεργασία (12) ___. Το αποτέλεσμα θα κριθεί από την καθημερινή εφαρμογή και όχι μόνο από μια ευχάριστη ανακοίνωση.", "status": "AUTHORED_DRAFT", "text_id": "KEG-B2-R02-T1", "version": "0.1.0", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3028	object	KEG-B2-U01-TEXT1	79eb4edc3f6fd3edbc6c066a2ee22ed975e04dd53ee9359d56f90b20856ea7bf	\N	{"refs": [{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-U01-TEXT1.json", "sha256": "edaa9ebcbc424521b83e55466492ed402b6b1e9f8e22867198feab92486ef7e8", "pointer": ""}], "payload": {"text": "(0) Μια ομάδα κατοίκων αποφάσισε να δημιουργήσει ένα μικρό εργαστήριο επισκευών στη γειτονιά. Όσοι γνώριζαν μια να τεχνική θα βοηθούσαν τους υπόλοιπους να παρατείνουν τη ζωή καθημερινών αντικειμένων.\\n(1) Πριν αρχίσει η δράση, οι οργανωτές συζήτησαν τις ανάγκες του χώρου. Δεν ήθελαν να αγοράσουν ακριβό εξοπλισμό. Γι’ αυτό ζήτησαν από που τους κατοίκους συγκεκριμένες προτάσεις.\\n(2) Στην πρώτη συνάντηση εμφανίστηκαν άνθρωποι διαφορετικών ηλικιών. Ορισμένοι έφεραν μικρά έπιπλα, ενώ άλλοι ήρθαν κυρίως για να παρακολουθήσουν. Η παρουσία τους να έδειξε ότι το ενδιαφέρον δεν περιοριζόταν μόνο στην άμεση εξοικονόμηση χρημάτων.\\n(3) Η υπεύθυνη εξήγησε ότι κανείς δεν ήταν υποχρεωμένος να γνωρίζει ήδη κάποια τεχνική. Αρκούσε να ακολουθεί τις οδηγίες, αντί να ότι επιχειρεί μόνος του μια δύσκολη επισκευή.\\n(4) Μετά τις πρώτες εβδομάδες καταγράφηκαν και δυσκολίες. Ορισμένα εργαλεία έλειπαν, ενώ το ωράριο δεν εξυπηρετούσε όλους. Οι συμμετέχοντες πρότειναν για δύο εναλλακτικές ώρες, ώστε να μπορούν να έρχονται και όσοι εργάζονταν το απόγευμα.\\n(5) Η ομάδα δεν θεώρησε αυτές τις παρατηρήσεις αποτυχία. Αντίθετα, τις χρησιμοποίησε για να βελτιώσει την οργάνωση. Δημιούργησε έναν κοινό κατάλογο εργαλείων και όρισε ένα πρόσωπο υπεύθυνο για θα την ενημέρωσή του.\\n(6) Παράλληλα, οι κάτοικοι αποφάσισαν να φωτογραφίζουν τα στάδια κάθε επισκευής, μόνο με τη συγκατάθεση των παρευρισκομένων. Έτσι θα μπορούσαν να θυμούνται ευκολότερα σε όσα είχαν μάθει και να τα εξηγούν αργότερα σε νέους συμμετέχοντες.\\n(7) Η συνέχεια της δράσης θα κρινόταν στο τέλος της δοκιμαστικής περιόδου. Οι οργανωτές ήθελαν πρώτα να εξετάσουν αν ο διαθέσιμος χρόνος και οι πόροι επαρκούσαν. Μια ευχάριστη αρχή δεν αποτελούσε από μόνη της αν εγγύηση διάρκειας.", "format": "remove_exactly_one_extra_word_in_each_numbered_segment", "status": "DRAFT", "example": {"answer": "να", "segment": "0"}, "text_id": "KEG-B2-U01-TEXT1", "version": "0.1.2", "segments": [{"text": "Μια ομάδα κατοίκων αποφάσισε να δημιουργήσει ένα μικρό εργαστήριο επισκευών στη γειτονιά. Όσοι γνώριζαν μια να τεχνική θα βοηθούσαν τους υπόλοιπους να παρατείνουν τη ζωή καθημερινών αντικειμένων.", "label": "0"}, {"text": "Πριν αρχίσει η δράση, οι οργανωτές συζήτησαν τις ανάγκες του χώρου. Δεν ήθελαν να αγοράσουν ακριβό εξοπλισμό. Γι’ αυτό ζήτησαν από που τους κατοίκους συγκεκριμένες προτάσεις.", "label": "1"}, {"text": "Στην πρώτη συνάντηση εμφανίστηκαν άνθρωποι διαφορετικών ηλικιών. Ορισμένοι έφεραν μικρά έπιπλα, ενώ άλλοι ήρθαν κυρίως για να παρακολουθήσουν. Η παρουσία τους να έδειξε ότι το ενδιαφέρον δεν περιοριζόταν μόνο στην άμεση εξοικονόμηση χρημάτων.", "label": "2"}, {"text": "Η υπεύθυνη εξήγησε ότι κανείς δεν ήταν υποχρεωμένος να γνωρίζει ήδη κάποια τεχνική. Αρκούσε να ακολουθεί τις οδηγίες, αντί να ότι επιχειρεί μόνος του μια δύσκολη επισκευή.", "label": "3"}, {"text": "Μετά τις πρώτες εβδομάδες καταγράφηκαν και δυσκολίες. Ορισμένα εργαλεία έλειπαν, ενώ το ωράριο δεν εξυπηρετούσε όλους. Οι συμμετέχοντες πρότειναν για δύο εναλλακτικές ώρες, ώστε να μπορούν να έρχονται και όσοι εργάζονταν το απόγευμα.", "label": "4"}, {"text": "Η ομάδα δεν θεώρησε αυτές τις παρατηρήσεις αποτυχία. Αντίθετα, τις χρησιμοποίησε για να βελτιώσει την οργάνωση. Δημιούργησε έναν κοινό κατάλογο εργαλείων και όρισε ένα πρόσωπο υπεύθυνο για θα την ενημέρωσή του.", "label": "5"}, {"text": "Παράλληλα, οι κάτοικοι αποφάσισαν να φωτογραφίζουν τα στάδια κάθε επισκευής, μόνο με τη συγκατάθεση των παρευρισκομένων. Έτσι θα μπορούσαν να θυμούνται ευκολότερα σε όσα είχαν μάθει και να τα εξηγούν αργότερα σε νέους συμμετέχοντες.", "label": "6"}, {"text": "Η συνέχεια της δράσης θα κρινόταν στο τέλος της δοκιμαστικής περιόδου. Οι οργανωτές ήθελαν πρώτα να εξετάσουν αν ο διαθέσιμος χρόνος και οι πόροι επαρκούσαν. Μια ευχάριστη αρχή δεν αποτελούσε από μόνη της αν εγγύηση διάρκειας.", "label": "7"}], "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "surface_greek_word_count": 247}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3029	object	KEG-B2-U03-T1	d989700c562c84f0a0cf4d7cc27d901e6e5bb4efeb665e407657152f9123b63e	\N	{"refs": [{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-U03-T1.json", "sha256": "e33607abb73d5338119bb9e5fe45f6e991477d05ee2647aed47896e2e616abe3", "pointer": ""}], "payload": {"text": "(0) Η ομάδα θέλει ότι να συνεργαστεί. Παράδειγμα: αφαιρείται το «ότι».\\n\\n(1) Η οργανωτική ομάδα του φεστιβάλ αποφάσισε να προσθέσει υπότιτλους στις μικρές ταινίες. Η αλλαγή δεν αφορούσε μόνο ξενόγλωσσα έργα, αλλά και ελληνικές παραγωγές, ώστε να γίνουν προσβάσιμες σε ότι περισσότερους θεατές.\\n\\n(2) Πριν αρχίσει η εργασία, ζητήθηκε από τους δημιουργούς να εγκρίνουν τη χρήση των διαλόγων. Οι υπεύθυνοι διευκρίνισαν ότι η άδεια προβολής δεν σήμαινε αυτομάτως ότι και άδεια αλλαγής του υπάρχοντος υλικού.\\n\\n(3) Κάθε εθελοντής ανέλαβε ένα σύντομο απόσπασμα, το οποίο θα ελεγχόταν από δεύτερο άτομο. Η ομάδα προτίμησε αυτή τη διαδικασία από να την απλή συγκέντρωση πολλών ανεξάρτητων μεταγραφών χωρίς κοινά κριτήρια ελέγχου.\\n\\n(4) Οι διάλογοι έπρεπε να διαβάζονται εύκολα, χωρίς να χάνεται ο χαρακτήρας της ομιλίας. Δεν ήταν αρκετό να αποδοθούν σωστά οι λέξεις· χρειαζόταν επίσης προσοχή για στον χρόνο που παρέμενε κάθε υπότιτλος στην οθόνη.\\n\\n(5) Σε μια δοκιμαστική προβολή, οι θεατές σημείωσαν σημεία που δεν προλάβαιναν να διαβάσουν. Οι παρατηρήσεις τους οδήγησαν σε διορθώσεις, παρόλο που η ομάδα είχε ήδη αφιερώσει αρκετές ώρες από στον αρχικό έλεγχο.\\n\\n(6) Οι συντελεστές απέφυγαν να θεωρήσουν τις αλλαγές προσωπική κριτική. Αντίθετα, συζήτησαν για το πώς θα μπορούσαν να βελτιώσουν το αποτέλεσμα, διατηρώντας σημειώσεις ώστε για η επόμενη παραγωγή να ξεκινήσει με σαφέστερες οδηγίες.\\n\\n(7) Μετά το φεστιβάλ, η ομάδα κράτησε τις εγκεκριμένες εκδοχές σε κοινό αρχείο. Η πρόσβαση δόθηκε μόνο σε όσους είχαν συγκεκριμένη εργασία να ολοκληρώσουν, επειδή ότι η μελλοντική χρήση απαιτούσε νέα συνεννόηση με τους δημιουργούς. Οι καταγραφές περιλάμβαναν επίσης την ημερομηνία κάθε έγκρισης και το όνομα του υπευθύνου.", "status": "AUTHOR_COMPLETE_AI_REVIEW_PENDING", "text_id": "KEG-B2-U03-T1", "version": "0.1.1", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "word_count": 247}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3030	object	KEG-B2-U03-T2	86080c690925f07e32d4cde157d5c1689da650bd9230a099937e8b78a9691d91	\N	{"refs": [{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-U03-T2.json", "sha256": "4f4f442a3ef400cfebd40401aadd338559eeb3e8981bc5fb5b16305cd3afc104", "pointer": ""}], "payload": {"text": "Όταν ανέλαβα την κουζίνα ενός μικρού ξενώνα, με εντυπωσίασε η (0) ___ της ομάδας να δοκιμάσει αλλαγές. Δεν ήθελα να μειώσω τις μερίδες ούτε να περιορίσω τις επιλογές χωρίς συζήτηση. Με απασχολούσαν κυρίως όσα τρόφιμα αγοράζονταν αλλά τελικά δεν χρησιμοποιούνταν.\\nΞεκινήσαμε με μια απλή (1) ___ των ποσοτήτων που περίσσευαν. Δεν καταγράφαμε ονόματα πελατών ή προσωπικές προτιμήσεις. Παρατηρούσαμε μόνο ποια υλικά έμεναν συστηματικά στο τέλος κάθε ημέρας και ποια τελείωναν πριν εξυπηρετηθούν όλοι. Οι πρώτες σημειώσεις έδειξαν ότι η εικόνα διέφερε ανάμεσα στις καθημερινές και στο σαββατοκύριακο.\\nΗ (2) ___ του νέου προγράμματος απαιτούσε συνεργασία με τους προμηθευτές. Ζητήσαμε μικρότερες αλλά συχνότερες παραδόσεις, χωρίς να θεωρούμε δεδομένο ότι όλοι μπορούσαν να αλλάξουν αμέσως τον τρόπο εργασίας τους. Έπρεπε να συμφωνήσουμε σε (3) ___ όρους, ώστε να γνωρίζουμε ποιος αναλάμβανε κάθε έξοδο.\\nΠαράλληλα, οργανώσαμε καλύτερα την αποθήκη. Μια ευδιάκριτη σήμανση έκανε τον έλεγχο πιο (4) ___ και περιόριζε τις άσκοπες αναζητήσεις. Οι εργαζόμενοι δεν χρειαζόταν πλέον να θυμούνται ποιος είχε μετακινήσει κάθε κιβώτιο. Η σειρά χρήσης των προϊόντων γινόταν σαφής σε όποιον άρχιζε τη βάρδια του.\\nΗ αλλαγή δεν στηρίχθηκε σε μια εντυπωσιακή υπόσχεση άμεσου κέρδους. Χρειάστηκε (5) ___ παρακολούθηση και προσαρμογή, ιδιαίτερα όταν άλλαξε ο αριθμός των επισκεπτών. Κάθε εβδομάδα συζητούσαμε τι λειτούργησε και τι δυσκόλεψε την ομάδα, χωρίς να αναζητούμε κάποιον για να κατηγορήσουμε.\\nΤελικά, θεωρήσαμε σημαντικότερη τη (6) ___ της διαδικασίας παρά έναν μεμονωμένο καλό αριθμό. Θέλαμε μια πρακτική που θα μπορούσε να διατηρηθεί και όταν ο αρχικός ενθουσιασμός θα είχε υποχωρήσει. Οι απλές οδηγίες έμειναν διαθέσιμες και για όσους θα προσλαμβάνονταν αργότερα.", "status": "AUTHOR_COMPLETE_AI_REVIEW_PENDING", "text_id": "KEG-B2-U03-T2", "version": "0.1.1", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "word_count": 241}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3031	object	KEG-B2-R03-SUMMARY	2242ba62ddb29f82a4bbe52202580b26c3913b011ed5f0a401e16a09da5a8b21	\N	{"refs": [{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-R03-SUMMARY.json", "sha256": "9ce4d8be68b142a2b91b00e9f2a641caa3e599c9cf66a52f236421098a6b34ef", "pointer": ""}], "payload": {"text": "Ο αφηγητής εργάστηκε για ένα (0) καλοκαίρι στον ξενώνα της θείας του. Μια οικογένεια είχε ζητήσει δωμάτιο στο (1) ___, αλλά η καταχώριση ήταν διαφορετική. Το λάθος αποκαλύφθηκε όταν εξετάστηκε το μήνυμα (2) ___. Η θεία πρότεινε διαμονή σε άλλο κατάλυμα και ανέλαβε τη διαφορά (3) ___. Έπειτα συμφώνησαν σε κατάλογο που όριζε πότε ο αφηγητής θα ζητούσε (4) ___. Για τις καθημερινές ανάγκες των επισκεπτών δημιούργησε φύλλο πληροφοριών και βελτίωσε τον (5) ___ του. Με μια αλλόγλωσση ταξιδιώτισσα χρησιμοποίησε απλές φράσεις και έγραψε τις ώρες σε (6) ___. Στο τέλος προτίμησε εργασία σχετική με τις (7) ___ του, αναγνωρίζοντας την αξία όσων είχε μάθει.", "status": "AUTHOR_COMPLETE_AI_REVIEW_PENDING", "text_id": "KEG-B2-R03-SUMMARY", "version": "0.1.0", "based_on": "KEG-B2-R03-TEXT2", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "word_count": 90}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3032	object	KEG-B2-U01-TEXT2	ef2544f9e26a6cab909ed3508ceee6a31569a23a73d4fa6b478d2259eed915bc	\N	{"refs": [{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-U01-TEXT2.json", "sha256": "c7d4493889ad4808abb316e55ae053384f339edcd316304396394d82c39d7dc5", "pointer": ""}], "payload": {"text": "Όταν μια ομάδα εθελοντών ανέλαβε να οργανώσει μια μικρή έκθεση φωτογραφίας, έδωσε ιδιαίτερη προσοχή στην (0) ___ του χώρου. Δεν αρκούσε να τοποθετήσει εικόνες στους τοίχους. Έπρεπε να σκεφτεί πώς θα κινούνταν οι επισκέπτες και πώς θα καταλάβαιναν τη σχέση ανάμεσα στις διαφορετικές ενότητες.\\nΗ πρώτη (1) ___ των μελών αφορούσε τη σειρά των εικόνων. Άλλοι προτιμούσαν τη χρονολογική παρουσίαση και άλλοι μια θεματική διαδρομή. Ύστερα από συζήτηση συμφώνησαν να συνδυάσουν τις δύο προσεγγίσεις, διατηρώντας όμως σύντομες και σαφείς εξηγήσεις.\\nΓια να γίνει η έκθεση πιο (2) ___ σε ανθρώπους με διαφορετικές ανάγκες, οι λεζάντες γράφτηκαν με μεγάλα γράμματα και τοποθετήθηκαν σε ύψος που μπορούσαν να διαβάσουν περισσότεροι επισκέπτες. Η ομάδα ζήτησε επίσης τη (3) ___ ενός εκπαιδευτικού για την προετοιμασία μιας δραστηριότητας για παιδιά.\\nΗ (4) ___ του εγχειρήματος δεν θα μετριόταν μόνο από τον αριθμό όσων θα έμπαιναν στην αίθουσα. Οι οργανωτές ήθελαν να μάθουν αν οι επισκέπτες κατανοούσαν το θέμα και αν ένιωθαν ότι μπορούσαν να συμμετέχουν στη συζήτηση. Γι’ αυτό ετοίμασαν ένα σύντομο ερωτηματολόγιο, χωρίς να ζητούν προσωπικά στοιχεία.\\nΜετά την πρώτη ημέρα, μια (5) ___ παρατήρηση οδήγησε σε αλλαγή της διαδρομής: δύο λεζάντες δεν φαίνονταν όταν ο χώρος γέμιζε. Η ομάδα τις μετέφερε και συνέχισε να συγκεντρώνει σχόλια. Η τελική (6) ___ θα γινόταν αφού ολοκληρωνόταν η έκθεση, ώστε να ληφθούν υπόψη τόσο οι θετικές εμπειρίες όσο και οι δυσκολίες που είχαν παρουσιαστεί στην πράξη. Οι επισκέπτες μπορούσαν επίσης να αφήσουν ανώνυμα σχόλια για τη σειρά των εικόνων, χωρίς να συμπληρώσουν ολόκληρο το έντυπο.", "format": "word_formation_mcq", "status": "DRAFT", "example": {"gap": "0", "answer": "οργάνωση"}, "text_id": "KEG-B2-U01-TEXT2", "version": "0.1.0", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "surface_greek_word_count": 235}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3033	object	KEG-B2-R01-SUMMARY	fb04d9e169c2e4abdcb3ed9ddf0dd15887563362c2a2f1ec327e13f84231ca2e	\N	{"refs": [{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-R01-SUMMARY.json", "sha256": "acf9c8e17861f60cdee8bdec968ec27914bdea247d12aa95c585f4678b05f43e", "pointer": ""}], "payload": {"text": "Ο αφηγητής επέστρεψε στην παλιά του (0) γειτονιά και συνεργάστηκε με τη Λίνα. Η πρώτη συνάντηση πραγματοποιήθηκε στη (1) ___. Οι συμμετέχοντες σημείωσαν προσωπικές διαδρομές πάνω σε έναν σημερινό (2) ___. Η διαφωνία για τις παλιές χρήσεις ενός κτιρίου λύθηκε όταν βρέθηκαν οι (3) ___. Στον περίπατο, η ομάδα άλλαξε δρόμο εξαιτίας ενός στενού (4) ___. Μια γυναίκα επέτρεψε να δημοσιευτεί η ιστορία της ως κείμενο χωρίς το (5) ___ της. Αντί για εφαρμογή, δημιουργήθηκε αρχικά ένας (6) ___ χάρτης. Μια παρατήρηση αναγνώστη οδήγησε στη διόρθωση της θέσης ενός παλιού (7) ___.", "status": "AUTHOR_COMPLETE_AI_REVIEW_PENDING", "text_id": "KEG-B2-R01-SUMMARY", "version": "0.1.0", "based_on": "KEG-B2-R01-TEXT2", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "provenance": "Exact export of existing R01 inline summary; no new content", "word_count": 77}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3034	object	KEG-B2-R02-T2	c87c29037c084ccedbb81ab754dba9e1b4375e70ca7c4bfcc8f1ee50be99b79e	\N	{"refs": [{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-R02-T2.json", "sha256": "7506932b73048102249109c26e037ec443b5a3b3eac5ebdd697207cf2b451bdb", "pointer": ""}], "payload": {"text": "Το ραδιόφωνο που δεν πέταξα\\nΌταν άδειασα το παλιό σπίτι του θείου μου, βρήκα ένα μικρό ραδιόφωνο σε μια ντουλάπα. Δεν ήταν σπάνιο ούτε φαινόταν ιδιαίτερα πολύτιμο. Το κουμπί της έντασης είχε χαλαρώσει και το καλώδιο ήταν φθαρμένο. Η πρώτη μου σκέψη ήταν να το πετάξω μαζί με τις άδειες συσκευασίες. Με σταμάτησε όμως ένα χαρτί κολλημένο στο πίσω μέρος: μια λίστα σταθμών, γραμμένη με τον γραφικό χαρακτήρα του θείου. Δεν αποφάσισα εκείνη τη στιγμή να το επισκευάσω. Απλώς το έβαλα σε μια ξεχωριστή κούτα.\\nΓια μήνες η κούτα έμεινε κλειστή. Είχα συνηθίσει να ακούω μουσική από το τηλέφωνο και δεν έβλεπα πρακτικό λόγο να ασχοληθώ. Ένα απόγευμα, φίλη που είχε έρθει για καφέ αναγνώρισε το μοντέλο. Μου είπε ότι ο πατέρας της κρατούσε ένα παρόμοιο, αλλά με προειδοποίησε να μην το βάλω στην πρίζα πριν το ελέγξει τεχνικός. Η παρατήρηση άλλαξε τον τρόπο που έβλεπα το αντικείμενο: δεν ήταν ούτε έτοιμο για χρήση ούτε απαραίτητα άχρηστο.\\nΟ τεχνικός μού εξήγησε ότι το κόστος του ελέγχου ήταν συγκεκριμένο, ενώ η τελική επισκευή θα εξαρτιόταν από τα ανταλλακτικά. Ζήτησα να με ενημερώσει πριν προχωρήσει. Δεν ήθελα να πληρώσω απεριόριστα, αλλά ούτε να αποφασίσω μόνο από την εμφάνιση. Όταν τηλεφώνησε, είπε ότι μπορούσε να αποκαταστήσει τη λειτουργία, χωρίς να εγγυηθεί ότι το περίβλημα θα έμοιαζε καινούργιο. Αυτή η διάκριση με βοήθησε: ήθελα να ακούγεται, όχι να εξαφανιστούν όλα τα σημάδια του χρόνου.\\nΤις πρώτες ημέρες το χρησιμοποιούσα σχεδόν τελετουργικά. Το άνοιγα το πρωί και περίμενα να ακούσω τι θα μετέδιδε ο σταθμός, αντί να επιλέγω εγώ κάθε τραγούδι. Κάποιες εκπομπές δεν μου άρεσαν καθόλου. Δεν έγινα ξαφνικά νοσταλγός μιας εποχής που δεν είχα ζήσει. Ανακάλυψα όμως ότι μου έκανε καλό να μην αλλάζω συνεχώς επιλογές. Μερικές φορές άκουγα μια ολόκληρη συζήτηση για θέμα που δεν θα αναζητούσα μόνος μου.\\nΈστειλα φωτογραφία στην ξαδέλφη μου. Εκείνη θυμήθηκε ότι ο θείος άκουγε συχνά ειδήσεις ενώ μαγείρευε. Εγώ τον θυμόμουν κυρίως να κάθεται στο μπαλκόνι με εφημερίδα. Οι αναμνήσεις μας δεν συμφωνούσαν σε όλα, αλλά δεν προσπαθήσαμε να αποφασίσουμε ποια ήταν η σωστή. Το ραδιόφωνο άνοιξε μια συζήτηση για μικρές καθημερινές συνήθειες που δεν είχαμε ποτέ καταγράψει. Η λίστα των σταθμών παρέμεινε στη θέση της, παρόλο που ορισμένες συχνότητες δεν αντιστοιχούσαν πια σε όσα έγραφε.\\nΑργότερα σκέφτηκα να κρατήσω και άλλα παλιά αντικείμενα. Γρήγορα κατάλαβα ότι δεν είχα ούτε χώρο ούτε χρήματα για όλα. Ένα φωτιστικό το χάρισα, αφού βεβαιώθηκα ότι λειτουργούσε, και μερικά βιβλία τα έδωσα σε ανθρώπους που τα ήθελαν. Δεν ένιωσα ότι έτσι πρόδιδα τη μνήμη του θείου. Το δύσκολο ήταν να ξεχωρίσω την πραγματική προσωπική σημασία από την ενοχή που με έκανε να μη θέλω να αποχωριστώ τίποτα.\\n\\nΜια Κυριακή το πήρα στο σπίτι της μητέρας μου, όχι για να της το χαρίσω, αλλά για να το ακούσουμε μαζί. Εκείνη παρατήρησε έναν μικρό λεκέ στο πλάι που εγώ δεν είχα προσέξει. Δεν θυμόταν πώς είχε δημιουργηθεί. Η άγνοια αυτή δεν μας ενόχλησε· δεν χρειαζόταν κάθε σημάδι να συνοδεύεται από μια συγκινητική ιστορία. Αφήσαμε την εκπομπή να συνεχιστεί ενώ στρώναμε το τραπέζι. Για πρώτη φορά το αντικείμενο συμμετείχε σε μια καινούργια οικογενειακή στιγμή, αντί να μας ζητά μόνο να αναζητήσουμε το παρελθόν του.\\n\\nΣήμερα το ραδιόφωνο δεν είναι διακοσμητικό τρόπαιο. Άλλοτε το ακούω και άλλοτε προτιμώ το τηλέφωνο. Αν χαλάσει ξανά, θα εξετάσω το κόστος και την ασφάλεια πριν αποφασίσω. Η εμπειρία δεν με έπεισε ότι κάθε παλιό πράγμα πρέπει να σωθεί. Με έμαθε να καθυστερώ λίγο την απόφαση, να ρωτώ τι μπορεί να γίνει και να ξεχωρίζω τη χρησιμότητα από την τέλεια εμφάνιση. Αυτό το μικρό διάστημα ανάμεσα στο «δεν το χρειάζομαι» και στο «το πετάω» ήταν, τελικά, η σημαντικότερη αλλαγή.", "status": "AUTHORED_DRAFT", "text_id": "KEG-B2-R02-T2", "version": "0.1.1", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3035	object	KEG-B2-R03-TEXT1	0b61c21bc6860eb8baccb253cd720f2c21df935341a27cfb2fc82a0f7accfd82	\N	{"refs": [{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-R03-TEXT1.json", "sha256": "8d94fbe2413383c38c3b8b87cd4c6542e1e35921556ec23350ad8b72be9c5a72", "pointer": ""}], "payload": {"text": "Μικρές συνδρομές, μεγάλες αποφάσεις\\nΜια μηνιαία συνδρομή μοιάζει συχνά ασήμαντη (0) ___. Χρειάζεται ένας συνολικός κατάλογος, στον οποίο θα φαίνονται όχι μόνο οι τιμές αλλά και η πραγματική χρήση.\\nΗ πρώτη καταγραφή τεκμηριώνεται (1) ___. Μερικές χρεώσεις εμφανίζονται με ονομασία διαφορετική από εκείνη που γνωρίζει ο χρήστης, οπότε απαιτείται προσεκτικός έλεγχος πριν εξαχθούν συμπεράσματα.\\nΣτη συνέχεια μπορεί να σημειώνεται η χρήση κάθε υπηρεσίας (2) ___. Έτσι αποφεύγεται η απόφαση με βάση μια ασυνήθιστα φορτωμένη ή ήσυχη ημέρα. Μια συνδρομή που χρησιμοποιήθηκε πολύ στις διακοπές ίσως παραμένει σχεδόν ανενεργή κατά την εργάσιμη περίοδο.\\nΜια φθηνή υπηρεσία παύει να έχει πρακτική αξία (3) ___. Αντίστοιχα, μια ακριβότερη υπηρεσία μπορεί να έχει μεγαλύτερη αξία όταν καλύπτει συχνή και συγκεκριμένη ανάγκη. Το ερώτημα δεν είναι ποια φαίνεται φθηνότερη στην ανακοίνωση, αλλά ποια προσφέρει κάτι χρήσιμο.\\nΠριν από μια νέα εγγραφή, αξίζει να διαβάζονται οι όροι (4) ___. Μια δοκιμαστική περίοδος χρειάζεται υπενθύμιση στο ημερολόγιο, ώστε η απόφαση για συνέχιση να ληφθεί συνειδητά. Η υπενθύμιση τοποθετείται (5) ___, όχι όταν έχει ήδη εμφανιστεί η επόμενη χρέωση.\\nΗ σύγκριση των υπηρεσιών δεν γίνεται για να αναδειχθεί το ωραιότερο όνομα, αλλά (6) ___. Αν όμως μία υπηρεσία προσφέρει απαραίτητη δυνατότητα που λείπει από την άλλη, η διπλή εγγραφή μπορεί να δικαιολογείται.\\nΣε ένα νοικοκυριό, η συζήτηση πρέπει να περιλαμβάνει όλους τους χρήστες (7) ___. Όποιος πληρώνει δεν γνωρίζει πάντα ποια δυνατότητα αξιοποιούν οι υπόλοιποι. Η ακύρωση χωρίς συζήτηση μπορεί να περιορίσει μια ανάγκη που δεν είχε γίνει ορατή στον λογαριασμό.\\nΜια πρακτική λύση είναι ένας μικρός δοκιμαστικός περιορισμός (8) ___. Καταγράφοντας τι πραγματικά λείπει, οι χρήστες αποκτούν καλύτερη εικόνα από εκείνη που δίνει ένας γενικός φόβος απώλειας. Η επανεξέταση έχει νόημα (9) ___, όταν η δοκιμαστική διακοπή έχει πια ολοκληρωθεί, και όχι όταν όλοι έχουν ξεχάσει γιατί έγινε η αλλαγή.\\nΈνας προϋπολογισμός είναι χρήσιμος (10) ___. Αν μια επιλογή προσφέρει σταθερή απόλαυση χωρίς να εμποδίζει βασικές υποχρεώσεις, δεν ακυρώνεται επειδή κάποιος άλλος δεν τη θεωρεί αναγκαία. Το σημαντικό είναι να υπάρχει επίγνωση (11) ___ και δυνατότητα αναθεώρησης. Η τελική απόφαση στηρίζεται επομένως (12) ___, όχι μόνο στην εντύπωση που δημιούργησε μια προσφορά.", "status": "AUTHOR_COMPLETE_AI_REVIEW_PENDING", "text_id": "KEG-B2-R03-TEXT1", "version": "0.1.0", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "word_count": 319}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3036	object	KEG-B2-U02-T2	09e46b1ed8ce9327e59dba2823ad456e5299cb0b77f99d9494f398c653c00e40	\N	{"refs": [{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-U02-T2.json", "sha256": "cc1aaf3a6cf3acfeb262853562bca6577dfcb688dbcea9bec40b49566059d205", "pointer": ""}], "payload": {"text": "Μια ομάδα κατοίκων δημιούργησε έναν μικρό οδηγό για τις διαδρομές της περιοχής. Σκοπός ήταν η (0) ενημέρωση όσων ήθελαν να περπατούν χωρίς να εξαρτώνται αποκλειστικά από το αυτοκίνητο. Το υλικό δεν παρουσιάστηκε ως επίσημη μελέτη συγκοινωνιών, αλλά ως καταγραφή συγκεκριμένων παρατηρήσεων.\\nΗ πρώτη (1) ___ αφορούσε την πρόσβαση στις στάσεις. Οι συμμετέχοντες περπάτησαν τις διαδρομές σε διαφορετικές ώρες και σημείωσαν εμπόδια, χωρίς να φωτογραφίζουν αναγνωρίσιμους περαστικούς. Η (2) ___ των πληροφοριών ήταν σημαντικότερη από την ταχύτητα ολοκλήρωσης. Όπου υπήρχαν αμφιβολίες, γινόταν δεύτερη επίσκεψη.\\nΣτη συνέχεια η ομάδα ζήτησε τη (3) ___ ενός ειδικού σε θέματα προσβασιμότητας. Εκείνος εξήγησε ότι μια διαδρομή που φαίνεται εύκολη σε κάποιον μπορεί να δημιουργεί δυσκολίες σε άλλον. Έτσι, οι περιγραφές έγιναν πιο (4) ___: ανέφεραν κλίσεις, πλάτος πεζοδρομίου και διαθέσιμα σημεία ανάπαυσης, αντί να χαρακτηρίζουν απλώς μια περιοχή καλή ή κακή.\\nΟ οδηγός δημοσιεύτηκε σε μορφή που επέτρεπε την τακτική (5) ___ του. Οι συντάκτες γνώριζαν ότι ένα έργο στον δρόμο ή μια αλλαγή στάσης μπορούσε να καταστήσει παλιά μια πληροφορία. Κάθε αλλαγή συνοδευόταν από ημερομηνία και σύντομη εξήγηση, ώστε ο αναγνώστης να καταλαβαίνει τι είχε ελεγχθεί.\\nΤο εγχείρημα ενίσχυσε τη (6) ___ ανάμεσα σε ανθρώπους που προηγουμένως δεν γνωρίζονταν. Δεν έλυσε όλα τα προβλήματα μετακίνησης, αλλά δημιούργησε έναν κοινό τρόπο να περιγράφονται οι ανάγκες και να διατυπώνονται συγκεκριμένα αιτήματα προς τους αρμόδιους. Πριν οριστικοποιήσουν κάθε περιγραφή, τη διάβαζαν σε κάποιον που δεν είχε συμμετάσχει στην επίσκεψη. Αν εκείνος ζητούσε διευκρινίσεις, επέστρεφαν στις σημειώσεις τους και συμπλήρωναν όσα έλειπαν, αντί να προσθέτουν αόριστους χαρακτηρισμούς.", "status": "AUTHORED_DRAFT", "text_id": "KEG-B2-U02-T2", "version": "0.1.1", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "word_count": 236}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3037	object	KEG-B2-U03-T3	650fc9aeb573d81d8c12f21689b2dba6c46ad9fb5070d74640443ca18e86c226	\N	{"refs": [{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-U03-T3.json", "sha256": "e801cad75083a48ae3617db9402e65628d20b3efc4de25c7243c5efa0b4eed60", "pointer": ""}], "payload": {"text": "Πριν από το πρώτο μάθημα κωπηλασίας, είχα παρακολουθήσει αρκετά βίντεο και πίστευα ότι ήξερα τι με περίμενε. Παρ’ όλα αυτά, (0) όταν έφτασα στην αποβάθρα, ένιωσα αμηχανία. Όλοι έμοιαζαν πιο άνετοι από εμένα, αν και αργότερα έμαθα ότι αρκετοί ήταν επίσης αρχάριοι.\\nΑποφάσισα (1) ___ ρωτήσω τον εκπαιδευτή αντί να προσποιηθώ ότι καταλάβαινα τις οδηγίες. Εκείνος μου εξήγησε πρώτα πώς θα καθόμουν και πού θα άφηνα τα πράγματά μου. Ο διπλανός μου ήταν μεγαλύτερος (2) ___ εμένα, αλλά συμμετείχε κι αυτός για πρώτη φορά. Η παρουσία του με βοήθησε να σταματήσω τις άχρηστες συγκρίσεις.\\nΣτην αρχή δυσκολευόμουν να κρατήσω τον ίδιο ρυθμό με την ομάδα. Πρόσεχα τόσο πολύ τις κινήσεις μου, που ξεχνούσα να ακούω. Η ισορροπία (3) ___ βάρκας εξαρτιόταν από τη συνεργασία μας, όχι από τη δύναμη του καθενός χωριστά. Ο εκπαιδευτής δεν ύψωσε (4) ___ τη φωνή του ούτε το χέρι του για να με σταματήσει· απλώς επανέλαβε ήρεμα την οδηγία.\\nΜετά από λίγα λεπτά ο ρυθμός έγινε τόσο σταθερός, (5) ___ να μπορώ να παρατηρώ και την ακτή. Δεν είχα γίνει ξαφνικά έμπειρος. Είχα απλώς πάψει να αντιμετωπίζω κάθε κίνηση ως ξεχωριστή δοκιμασία. Κατάλαβα ότι χρειαζόμουν όχι μόνο συγκέντρωση, (6) ___ και εμπιστοσύνη στους άλλους.\\nΣτο τέλος κράτησα στις σημειώσεις μου (7) ___ μου είχε φανεί χρήσιμο, χωρίς να προσπαθήσω να αντιγράψω ολόκληρο το μάθημα. Την επόμενη εβδομάδα ξαναπήγα. Αυτή τη φορά δεν με απασχολούσε να φαίνομαι προετοιμασμένος, αλλά να μπορώ να συμμετέχω πραγματικά στην κοινή προσπάθεια. Η αβεβαιότητα δεν είχε εξαφανιστεί, αλλά δεν με εμπόδιζε πλέον να ρωτώ.", "status": "AUTHOR_COMPLETE_AI_REVIEW_PENDING", "text_id": "KEG-B2-U03-T3", "version": "0.1.1", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "word_count": 238}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3038	object	KEG-B2-R01-TEXT2	b26f75dcd43bd7a4bfc3b4e038c1e7aeefe53e6b7eba1ca9df2224d8b4a30e57	\N	{"refs": [{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-R01-TEXT2.json", "sha256": "4b24773c65e3b7e0c597ff90af2bdbc93e8ac0e69f7130e48da059483474451f", "pointer": ""}], "payload": {"text": "Μια διαδρομή που ξαναμάθαμε\\nΌταν επέστρεψα στη γειτονιά όπου μεγάλωσα, περίμενα να βρω αλλαγμένα τα καταστήματα. Δεν περίμενα όμως να δυσκολεύομαι να περιγράψω τον δρόμο που έκανα καθημερινά για το σχολείο. Θυμόμουν μυρωδιές και πρόσωπα, αλλά όχι πάντα τη σωστή σειρά των δρόμων. Η φίλη μου η Λίνα, που εργαζόταν στη δημοτική βιβλιοθήκη, πρότεινε να δοκιμάσουμε μια μικρή έρευνα με παλιούς και νέους κατοίκους. Δεν θέλαμε να γράψουμε επίσημη ιστορία της πόλης, αλλά να δούμε πώς διαφορετικοί άνθρωποι θυμούνται τον ίδιο τόπο.\\nΗ πρώτη συνάντηση έγινε στη βιβλιοθήκη ένα βροχερό απόγευμα. Είχαμε καλέσει δέκα άτομα και ήρθαν έξι. Αντί να ζητήσουμε αμέσως χρονολογίες, βάλαμε στο τραπέζι έναν σημερινό χάρτη και ζητήσαμε από τον καθένα να σημειώσει μια προσωπική διαδρομή. Ο κύριος Μάνος ζωγράφισε τον δρόμο προς το παλιό συνεργείο του. Η Νουρ, που είχε μετακομίσει πριν από τρία χρόνια, σημείωσε τη διαδρομή από το σπίτι της μέχρι το κέντρο γλωσσών. Οι δύο γραμμές συναντήθηκαν μπροστά σε ένα κλειστό κτίριο που κανείς μας δεν είχε προσέξει ιδιαίτερα.\\nΟ Μάνος θυμόταν εκεί ένα αρτοποιείο, ενώ μια παλιά φωτογραφία έδειχνε επιγραφή καταστήματος υφασμάτων. Για λίγο νομίσαμε ότι κάποιος έκανε λάθος. Όταν όμως βρήκαμε τις ημερομηνίες, καταλάβαμε ότι οι δύο χρήσεις ανήκαν σε διαφορετικές περιόδους. Η διαφωνία δεν εξαφανίστηκε επειδή εμπιστευτήκαμε τον μεγαλύτερο σε ηλικία συμμετέχοντα, αλλά επειδή αποκτήσαμε ένα στοιχείο που έλειπε. Δεν χρειαζόταν όλοι να συμφωνούν σε κάθε λεπτομέρεια. Χρειαζόταν όμως να ακούει ο ένας τον άλλον και να δέχεται ότι μια προσωπική ανάμνηση μπορεί να συμπληρώνεται από μια διαφορετική εμπειρία, χωρίς να χάνει την αξία της. Από τότε γράφαμε δίπλα σε κάθε πληροφορία αν προερχόταν από ανάμνηση, έγγραφο ή προσωπική παρατήρηση.\\nΣτη δεύτερη συνάντηση βγήκαμε για περίπατο. Η Λίνα είχε ετοιμάσει μια σύντομη διαδρομή, αλλά χρειάστηκε να την αλλάξουμε. Ένα πεζοδρόμιο ήταν τόσο στενό, ώστε μια συμμετέχουσα με αμαξίδιο δεν μπορούσε να περάσει. Δεν θεωρήσαμε λογικό να συνεχίσει η υπόλοιπη ομάδα μόνη της. Επιλέξαμε άλλο δρόμο και καταγράψαμε το εμπόδιο στον χάρτη. Αυτό άλλαξε και τον τρόπο που βλέπαμε την εργασία μας: ο χάρτης δεν θα περιείχε μόνο ιστορίες του παρελθόντος, αλλά και δυσκολίες της σημερινής μετακίνησης.\\nΟι αφηγήσεις ηχογραφήθηκαν μόνο όταν οι ομιλητές συμφώνησαν. Μια γυναίκα θέλησε να μοιραστεί μια οικογενειακή ιστορία, αλλά δεν ήθελε να ακουστεί δημόσια η φωνή της. Της προτείναμε να κρατήσουμε ένα σύντομο γραπτό κείμενο χωρίς το όνομά της. Το διάβασε, έκανε δύο διορθώσεις και επέτρεψε τη δημοσίευσή του. Καταλάβαμε έτσι ότι το ενδιαφέρον μιας ιστορίας δεν μας δίνει αυτομάτως δικαίωμα να χρησιμοποιήσουμε κάθε λεπτομέρειά της.\\nΑρχικά σχεδιάζαμε μια εφαρμογή για κινητά. Έπειτα παρατηρήσαμε ότι δύο τακτικοί συμμετέχοντες δεν χρησιμοποιούσαν έξυπνο τηλέφωνο. Κρατήσαμε λοιπόν την ψηφιακή ιδέα για αργότερα και φτιάξαμε έναν έντυπο χάρτη που μπορούσε να δανείζεται κανείς από τη βιβλιοθήκη. Στο πίσω μέρος αφήσαμε χώρο για σημειώσεις. Δεν θέλαμε οι αναγνώστες να αντιμετωπίζουν το αποτέλεσμα ως κάτι οριστικό: μπορούσαν να διορθώνουν μια διαδρομή ή να προσθέτουν μια δική τους ανάμνηση, αρκεί να ξεχώριζαν όσα γνώριζαν από όσα υπέθεταν.\\nΤον πρώτο μήνα δανείστηκαν τον χάρτη είκοσι άνθρωποι. Ο αριθμός ήταν μικρότερος από αυτόν που είχαμε φανταστεί. Ωστόσο, τέσσερις επέστρεψαν με συγκεκριμένες παρατηρήσεις, και μία από αυτές μας βοήθησε να διορθώσουμε τη θέση ενός παλιού κινηματογράφου. Για μένα αυτό ήταν πιο ουσιαστικό από πολλά γρήγορα διαδικτυακά «μου αρέσει». Η εργασία δεν είχε απλώς προσελκύσει βλέμματα· είχε προκαλέσει προσεκτική ανάγνωση και συνεργασία.\\nΔεν ξέρω αν θα ολοκληρώσουμε ποτέ τον χάρτη. Ίσως η λέξη «ολοκλήρωση» να μην ταιριάζει σε ένα τέτοιο σχέδιο. Κάθε νέος κάτοικος φέρνει άλλες διαδρομές και κάθε αλλαγή στον δρόμο απαιτεί νέα παρατήρηση. Εγώ πάντως δεν ξαναβρήκα απλώς τη γειτονιά των παιδικών μου χρόνων. Έμαθα να τη βλέπω και μέσα από εμπειρίες που δεν ήταν δικές μου.", "format": "narrative_article", "status": "DRAFT", "text_id": "KEG-B2-R01-TEXT2", "version": "0.1.0", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "shared_with": "summary_completion", "author_genre": "original fictional first-person community narrative", "surface_greek_word_count": 602}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3039	object	KEG-B2-R03-TEXT2	938814e95dc0246995a77d7b31af30506c44af6ff850c9798069f1af01a03789	\N	{"refs": [{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-R03-TEXT2.json", "sha256": "84b85b58ee176e61e1842611324d2516e79f8b63f5bbbd49d6f35c5ade25af7b", "pointer": ""}], "payload": {"text": "Η βάρδια που δεν είχα σχεδιάσει\\nΌταν δέχτηκα να βοηθήσω για ένα καλοκαίρι στον μικρό ξενώνα της θείας μου, φαντάστηκα ότι θα περνούσα τις ημέρες μου δίνοντας κλειδιά και προτείνοντας παραλίες. Είχα μόλις τελειώσει τις σπουδές μου και ήθελα να κερδίσω λίγα χρήματα πριν αποφασίσω τι θα κάνω στη συνέχεια. Δεν θεωρούσα τη δουλειά ιδιαίτερα δύσκολη. Η θεία μου χαμογέλασε όταν το είπα, αλλά δεν προσπάθησε να με πείσει με προειδοποιήσεις. Μου έδειξε το βιβλίο κρατήσεων και με άφησε να παρακολουθήσω δύο βάρδιες πριν μείνω μόνος στην υποδοχή.\\nΤο πρώτο απόγευμα όλα πήγαιναν ήσυχα, μέχρι που έφτασε μια οικογένεια με δύο μικρά παιδιά. Είχαν ζητήσει δωμάτιο στο ισόγειο, όμως στο βιβλίο υπήρχε κράτηση στον δεύτερο όροφο. Έσπευσα να τους εξηγήσω ότι δεν μπορούσα να αλλάξω κάτι, επειδή όλα τα δωμάτια ήταν γεμάτα. Ο πατέρας έβγαλε το μήνυμα επιβεβαίωσης. Αντί να το διαβάσω, άρχισα να επαναλαμβάνω τι έγραφε το βιβλίο. Όσο μιλούσα, τόσο περισσότερο εκνευριζόταν. Μόνο όταν σταμάτησα κατάλαβα ότι δεν ζητούσε ειδική μεταχείριση· προσπαθούσε να μου δείξει μια ασυμφωνία.\\nΤο μήνυμα πράγματι ανέφερε ισόγειο. Τηλεφώνησα στη θεία μου, η οποία διαπίστωσε ότι είχε γίνει λάθος κατά τη μεταφορά της κράτησης. Δεν υπήρχε κενό ισόγειο δωμάτιο στον ξενώνα μας. Υπήρχε όμως ένα σε γειτονικό κατάλυμα, με το οποίο συνεργαζόταν περιστασιακά. Πρότεινε να καλύψουμε τη διαφορά τιμής και να βοηθήσουμε με τις αποσκευές. Η οικογένεια δέχτηκε, όχι επειδή εξαφανίστηκε η ταλαιπωρία, αλλά επειδή υπήρχε συγκεκριμένη λύση και κάποιος αναλάμβανε την ευθύνη. Εγώ ένιωσα ανακούφιση, μαζί με ντροπή για την αρχική βεβαιότητά μου.\\nΤο βράδυ περίμενα μια αυστηρή παρατήρηση. Η θεία μου με ρώτησε πρώτα τι θα έκανα διαφορετικά. Είπα ότι θα διάβαζα το μήνυμα πριν υπερασπιστώ την καταχώριση. Εκείνη πρόσθεσε ότι δεν χρειαζόταν να έχω έτοιμη λύση για τα πάντα. Έπρεπε όμως να ξέρω πότε μπορώ να αποφασίσω μόνος μου και πότε να ζητήσω βοήθεια. Συμφωνήσαμε σε έναν σύντομο κατάλογο περιπτώσεων για τις οποίες θα τηλεφωνούσα αμέσως. Δεν ήταν κατάλογος έτοιμων απαντήσεων, αλλά όριο της δικής μου αρμοδιότητας.\\nΤην επόμενη βάρδια έλεγξα τις νέες αφίξεις πριν εμφανιστούν οι επισκέπτες. Βρήκα μια ασαφή σημείωση και ρώτησα εγκαίρως τι σήμαινε. Η προετοιμασία δεν απέκλειε κάθε απρόοπτο, αλλά μου επέτρεπε να αντιμετωπίζω τις δυσκολίες χωρίς να ξεκινώ από μια υπόθεση που κανείς δεν είχε επιβεβαιώσει.\\nΤις επόμενες ημέρες άρχισα να σημειώνω τις συχνές ερωτήσεις των επισκεπτών. Ανακάλυψα ότι οι περισσότεροι δεν ζητούσαν τις εντυπωσιακές προτάσεις που είχα ετοιμάσει. Ήθελαν να ξέρουν πού μπορούσαν να πλύνουν ρούχα, ποιο λεωφορείο περνούσε κοντά και αν υπήρχε κάπου ήσυχος χώρος για να εργαστούν. Έφτιαξα ένα απλό φύλλο πληροφοριών και ζήτησα από δύο επισκέπτες να το δοκιμάσουν. Ο ένας δεν κατάλαβε τον χάρτη. Αντί να του εξηγήσω προφορικά όσα έλειπαν, άλλαξα τον χάρτη, ώστε να μπορεί να χρησιμοποιηθεί χωρίς εμένα.\\nΜια εβδομάδα αργότερα έφτασε μια ταξιδιώτισσα που δεν μιλούσε ελληνικά και καταλάβαινε λίγα αγγλικά. Προσπάθησα να μιλήσω πιο δυνατά, μέχρι που συνειδητοποίησα πόσο άχρηστο ήταν αυτό. Έδειξα τις ώρες σε χαρτί, χρησιμοποίησα απλές φράσεις και της ζήτησα να μου δείξει ποια πληροφορία χρειαζόταν. Η επικοινωνία έγινε πιο αργή, αλλά και πιο ακριβής. Από τότε δεν μπέρδευα τόσο εύκολα τη γρήγορη απάντηση με την αποτελεσματική εξυπηρέτηση.\\nΣτο τέλος του καλοκαιριού, η θεία μου πρότεινε να μείνω και τον χειμώνα. Την ευχαρίστησα, αλλά επέλεξα να αναζητήσω δουλειά σχετική με τις σπουδές μου. Αυτό δεν σήμαινε ότι θεωρούσα τους μήνες στον ξενώνα χαμένο χρόνο. Είχα μάθει να ελέγχω μια πληροφορία πριν επιμείνω, να ακούω ένα παράπονο χωρίς να το παίρνω αμέσως προσωπικά και να διακρίνω την πρωτοβουλία από την αυθαίρετη απόφαση. Όταν έγραψα αργότερα το βιογραφικό μου, δεν αρκέστηκα στη λέξη «υποδοχή». Περιέγραψα τι είχα πράγματι αναλάβει και τι είχα μάθει να κάνω καλύτερα.", "status": "AUTHOR_COMPLETE_AI_REVIEW_PENDING", "text_id": "KEG-B2-R03-TEXT2", "version": "0.1.0", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "word_count": 601}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3040	object	KEG-B2-U02-T3	e26ef21b92367a0ab009689b581e42bd694ef503b8bdb6351620b3c291961636	\N	{"refs": [{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-U02-T3.json", "sha256": "c47b2b033b3a6d0db02c7c19fac8fca701fa98b8dd64950e62d7990db5924d41", "pointer": ""}], "payload": {"text": "Την πρώτη φορά που συμμετείχα σε μια ομάδα πεζοπορίας, νόμιζα ότι το δυσκολότερο θα ήταν η διαδρομή. Είχα ετοιμάσει το σακίδιό μου από το προηγούμενο βράδυ, (0) επειδή δεν ήθελα να καθυστερήσω το πρωί. Όταν έφτασα στο σημείο συνάντησης, ανακάλυψα ότι είχα περισσότερες ερωτήσεις από όσες περίμενα.\\nΟ υπεύθυνος μας ζήτησε (1) ___ ελέγξουμε πρώτα αν είχαμε νερό. Ύστερα εξήγησε τη διαδρομή, η (2) ___ περνούσε από ένα παλιό μονοπάτι κοντά στο χωριό. Δεν έδωσε την εντύπωση ότι όλοι έπρεπε να κινούμαστε με την ίδια ταχύτητα. Αντίθετα, συμφωνήσαμε να περιμένουμε ο ένας τον άλλον στα σημεία που είχε υποδείξει.\\nΣτην αρχή περπατούσα πιο γρήγορα (3) ___ τους υπόλοιπους, προσπαθώντας να δείξω ότι ήμουν προετοιμασμένος. Σύντομα κατάλαβα ότι αυτό δεν βοηθούσε την ομάδα. Η Ελένη μού πρότεινε να μείνω κοντά της, (4) ___ να μπορούμε να συζητάμε και να παρατηρούμε το τοπίο χωρίς βιασύνη.\\nΣε μια διασταύρωση σταματήσαμε. Ο υπεύθυνος ρώτησε αν κάποιος γνώριζε (5) ___ βρισκόταν η παλιά βρύση. Κανείς δεν ήταν βέβαιος, κι έτσι ελέγξαμε τον χάρτη αντί να ακολουθήσουμε την πρώτη υπόθεση. Η μικρή καθυστέρηση μάς γλίτωσε από άσκοπη επιστροφή.\\nΌταν φτάσαμε, αισθάνθηκα (6) ___ κουρασμένος όσο περίμενα, αλλά πολύ πιο ήρεμος. Δεν είχα διανύσει τη μεγαλύτερη δυνατή απόσταση. Είχα μάθει, όμως, ότι η πεζοπορία ήταν περισσότερο μια κοινή εμπειρία (7) ___ ένας προσωπικός αγώνας ταχύτητας. Την επόμενη φορά πήγα με λιγότερη διάθεση να αποδείξω κάτι και περισσότερη προθυμία να ακούσω τους άλλους. Στο σπίτι σημείωσα δύο πράγματα που θα άλλαζα στην προετοιμασία μου. Δεν ήθελα να ξεχάσω την εμπειρία μόλις περνούσε ο πρώτος ενθουσιασμός.", "status": "AUTHORED_DRAFT", "text_id": "KEG-B2-U02-T3", "version": "0.1.1", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "word_count": 242}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3041	object	KEG-B2-R02-SUMMARY	271a3b4f5d3678113220c1df8a8e315e95a30b500f68c7aa6dd91035e8bcf968	\N	{"refs": [{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-R02-SUMMARY.json", "sha256": "9add8fb303d812baf4f5a84dd9b81e18d6ca28fb593ac94165baaca00a107010", "pointer": ""}], "payload": {"text": "Ο αφηγητής βρήκε το ραδιόφωνο στο σπίτι του (0) θείου του. Ανέβαλε την απόρριψή του όταν είδε μια χειρόγραφη (1) ___. Η φίλη του συνέστησε να προηγηθεί έλεγχος από (2) ___. Πριν εγκρίνει την επισκευή, ζήτησε ενημέρωση για το (3) ___. Προτίμησε τη λειτουργία από την τέλεια εξωτερική (4) ___. Η φωτογραφία οδήγησε σε συζήτηση με την (5) ___ του, παρά τις διαφορετικές αναμνήσεις τους. Δεν κράτησε όλα τα αντικείμενα, επειδή υπήρχαν όρια χώρου και (6) ___. Τελικά έμαθε να εξετάζει τις δυνατότητες πριν αποφασίσει την (7) ___.", "status": "AUTHORED_DRAFT", "text_id": "KEG-B2-R02-SUMMARY", "version": "0.1.0", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3042	object	KEG-B2-R01-TEXT1	1b881396fbb018d21c66a10b15d0283a252ed1480583f1625a7b6f47b50081d7	\N	{"refs": [{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-R01-TEXT1.json", "sha256": "f0228e6a20ec59016d6499665704e31484bb471c199cb7c5dbbf41ca86747af7", "pointer": ""}], "payload": {"text": "Η επισκευή ως κοινή εμπειρία\\nΣε μια γειτονιά δημιουργήθηκε ένα εργαστήριο όπου οι κάτοικοι φέρνουν χαλασμένα αντικείμενα (0) ___. Η πρωτοβουλία δεν παρουσιάζεται ως λύση για κάθε βλάβη. Στόχος της είναι να περιορίσει την άσκοπη αντικατάσταση προϊόντων και να προσφέρει βασικές γνώσεις σε ανθρώπους χωρίς τεχνική εμπειρία.\\nΠριν αρχίσει κάθε συνάντηση, ένας τεχνικός εξετάζει τα αντικείμενα (1) ___. Έτσι, συσκευές που μπορεί να προκαλέσουν τραυματισμό δεν περνούν στους πάγκους εργασίας. Η ασφάλεια προηγείται της επιθυμίας να σωθεί οπωσδήποτε ένα παλιό αντικείμενο.\\nΟ ιδιοκτήτης παραμένει δίπλα στον εθελοντή (2) ___. Η παρουσία του δεν είναι τυπική: δοκιμάζει απλές κινήσεις και σημειώνει τι θα προσέξει στο μέλλον. Οι εθελοντές εξηγούν τις επιλογές τους (3) ___. Λέξεις που είναι αυτονόητες για έναν ειδικό μπορεί να αποθαρρύνουν έναν αρχάριο.\\nΑν λείπει κάποιο μικρό εξάρτημα, η ομάδα αναζητά ανταλλακτικό (4) ___. Μόνο όταν η αναζήτηση αποτύχει συζητείται η αγορά. Ωστόσο, δεν δίνεται υπόσχεση (5) ___. Μερικές συσκευές είναι αδύνατο να ανοίξουν χωρίς να καταστραφούν.\\nΤο εργαστήριο προσφέρει τη συμμετοχή δωρεάν, αλλά δεν λειτουργεί (6) ___. Δεν αναλαμβάνει παραγγελίες ούτε παρέχει εγγύηση για μελλοντικές βλάβες. Ούτε επιδιώκει να αντικαταστήσει τους επαγγελματίες, στους οποίους παραπέμπει τις πιο απαιτητικές περιπτώσεις.\\nΣτην αρχή μετρούσαν την επιτυχία (7) ___. Σύντομα διαπίστωσαν ότι αυτό αδικούσε συναντήσεις όπου κανένα αντικείμενο δεν επισκευάστηκε, αλλά οι συμμετέχοντες έμαθαν να αναγνωρίζουν έναν κίνδυνο. Πρόσθεσαν λοιπόν έναν δεύτερο δείκτη: (8) ___. Η νέα μέτρηση γίνεται με μια σύντομη περιγραφή του τι μπορεί πλέον να κάνει κάθε συμμετέχων μόνος του.\\nΥπάρχει επίσης λίστα αναμονής, (9) ___. Περισσότεροι πάγκοι χωρίς περισσότερους εκπαιδευμένους βοηθούς θα αύξαναν τον κίνδυνο λαθών. Η ομάδα προτιμά να δέχεται λιγότερα αντικείμενα και να αφιερώνει αρκετό χρόνο σε καθένα.\\nΣτο τέλος της δοκιμαστικής περιόδου θα δημοσιευτεί απολογισμός (10) ___. Όποιος διαβάσει μόνο τους αριθμούς δεν θα καταλάβει γιατί ορισμένες προσπάθειες διακόπηκαν. Οι εξηγήσεις αυτές θα βοηθήσουν τους κατοίκους να κρίνουν τη χρησιμότητα της δράσης.\\nΗ επέκταση σε άλλες γειτονιές θα εξεταστεί (11) ___. Οι οργανωτές θεωρούν προτιμότερη μια μικρή σταθερή ομάδα από μια εντυπωσιακή αλλά σύντομη εκστρατεία. Τελικά, η αξία της προσπάθειας βρίσκεται όχι μόνο στα αντικείμενα που διατηρούνται, αλλά και (12) ___.", "format": "phrase_gap", "status": "DRAFT", "example": {"gap": 0, "answer": "για να τα εξετάσουν μαζί με εθελοντές", "answer_code": "J"}, "text_id": "KEG-B2-R01-TEXT1", "version": "0.1.0", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "phrase_bank": {"A": "τις γνώσεις που αποκτούν οι συμμετέχοντες", "B": "χωρίς να χρησιμοποιούν δυσνόητους όρους", "C": "σε εγγυημένη παράδοση την επόμενη ημέρα", "D": "εφόσον βρεθούν κατάλληλοι σταθεροί συνεργάτες", "E": "ώστε να εντοπίσει πιθανούς κινδύνους", "F": "ανεξάρτητα από τη διαθεσιμότητα ανθρώπων", "G": "ως επαγγελματικό κατάστημα επισκευών", "H": "στην αυτοπεποίθηση των ανθρώπων που μαθαίνουν", "I": "πρώτα στις διαθέσιμες δωρεές", "J": "για να τα εξετάσουν μαζί με εθελοντές", "K": "χωρίς κανέναν έλεγχο στην είσοδο", "L": "επειδή οι θέσεις επίβλεψης είναι περιορισμένες", "M": "μέχρι να απαγορευτεί η συμμετοχή αρχαρίων", "N": "κατά τη διάρκεια της επισκευής", "O": "μόνο για την πώληση καινούριων συσκευών", "P": "με αριθμούς και αιτιολόγηση των αποφάσεων", "Q": "ότι κάθε επισκευή θα πετύχει", "R": "αφού καταβάλει το υποχρεωτικό εισιτήριο", "S": "μόνο με τον αριθμό των επισκευασμένων αντικειμένων"}, "author_genre": "original fictional editorial; not authentic published journalism", "bank_reuse_allowed": false, "surface_greek_word_count": 322, "completed_greek_word_count": 393, "completed_text_reviewer_only": "Η επισκευή ως κοινή εμπειρία\\nΣε μια γειτονιά δημιουργήθηκε ένα εργαστήριο όπου οι κάτοικοι φέρνουν χαλασμένα αντικείμενα για να τα εξετάσουν μαζί με εθελοντές. Η πρωτοβουλία δεν παρουσιάζεται ως λύση για κάθε βλάβη. Στόχος της είναι να περιορίσει την άσκοπη αντικατάσταση προϊόντων και να προσφέρει βασικές γνώσεις σε ανθρώπους χωρίς τεχνική εμπειρία.\\nΠριν αρχίσει κάθε συνάντηση, ένας τεχνικός εξετάζει τα αντικείμενα ώστε να εντοπίσει πιθανούς κινδύνους. Έτσι, συσκευές που μπορεί να προκαλέσουν τραυματισμό δεν περνούν στους πάγκους εργασίας. Η ασφάλεια προηγείται της επιθυμίας να σωθεί οπωσδήποτε ένα παλιό αντικείμενο.\\nΟ ιδιοκτήτης παραμένει δίπλα στον εθελοντή κατά τη διάρκεια της επισκευής. Η παρουσία του δεν είναι τυπική: δοκιμάζει απλές κινήσεις και σημειώνει τι θα προσέξει στο μέλλον. Οι εθελοντές εξηγούν τις επιλογές τους χωρίς να χρησιμοποιούν δυσνόητους όρους. Λέξεις που είναι αυτονόητες για έναν ειδικό μπορεί να αποθαρρύνουν έναν αρχάριο.\\nΑν λείπει κάποιο μικρό εξάρτημα, η ομάδα αναζητά ανταλλακτικό πρώτα στις διαθέσιμες δωρεές. Μόνο όταν η αναζήτηση αποτύχει συζητείται η αγορά. Ωστόσο, δεν δίνεται υπόσχεση ότι κάθε επισκευή θα πετύχει. Μερικές συσκευές είναι αδύνατο να ανοίξουν χωρίς να καταστραφούν.\\nΤο εργαστήριο προσφέρει τη συμμετοχή δωρεάν, αλλά δεν λειτουργεί ως επαγγελματικό κατάστημα επισκευών. Δεν αναλαμβάνει παραγγελίες ούτε παρέχει εγγύηση για μελλοντικές βλάβες. Ούτε επιδιώκει να αντικαταστήσει τους επαγγελματίες, στους οποίους παραπέμπει τις πιο απαιτητικές περιπτώσεις.\\nΣτην αρχή μετρούσαν την επιτυχία μόνο με τον αριθμό των επισκευασμένων αντικειμένων. Σύντομα διαπίστωσαν ότι αυτό αδικούσε συναντήσεις όπου κανένα αντικείμενο δεν επισκευάστηκε, αλλά οι συμμετέχοντες έμαθαν να αναγνωρίζουν έναν κίνδυνο. Πρόσθεσαν λοιπόν έναν δεύτερο δείκτη: τις γνώσεις που αποκτούν οι συμμετέχοντες. Η νέα μέτρηση γίνεται με μια σύντομη περιγραφή του τι μπορεί πλέον να κάνει κάθε συμμετέχων μόνος του.\\nΥπάρχει επίσης λίστα αναμονής, επειδή οι θέσεις επίβλεψης είναι περιορισμένες. Περισσότεροι πάγκοι χωρίς περισσότερους εκπαιδευμένους βοηθούς θα αύξαναν τον κίνδυνο λαθών. Η ομάδα προτιμά να δέχεται λιγότερα αντικείμενα και να αφιερώνει αρκετό χρόνο σε καθένα.\\nΣτο τέλος της δοκιμαστικής περιόδου θα δημοσιευτεί απολογισμός με αριθμούς και αιτιολόγηση των αποφάσεων. Όποιος διαβάσει μόνο τους αριθμούς δεν θα καταλάβει γιατί ορισμένες προσπάθειες διακόπηκαν. Οι εξηγήσεις αυτές θα βοηθήσουν τους κατοίκους να κρίνουν τη χρησιμότητα της δράσης.\\nΗ επέκταση σε άλλες γειτονιές θα εξεταστεί εφόσον βρεθούν κατάλληλοι σταθεροί συνεργάτες. Οι οργανωτές θεωρούν προτιμότερη μια μικρή σταθερή ομάδα από μια εντυπωσιακή αλλά σύντομη εκστρατεία. Τελικά, η αξία της προσπάθειας βρίσκεται όχι μόνο στα αντικείμενα που διατηρούνται, αλλά και στην αυτοπεποίθηση των ανθρώπων που μαθαίνουν."}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3043	object	PEGP-LANG-P05-T01	6d7e7b96c0a07013d60cbd280298136be8b763f2299939018ad463a14fa4492d	\N	{"refs": [{"path": "GreekOS_PEGP_Module/language_support/PEGP-LANG-P05.json", "sha256": "c93a45d1232e3a5e12f90bd8117687a8ef64122916e844fa938781f922e304a6", "pointer": "/stimuli/0"}], "payload": {"origin": "ORIGINAL_GREEKOS_TEXT", "text_el": "Η ομάδα μας ετοιμάζει μια μικρή εκπαιδευτική έκθεση με θέμα «Τόποι και δημιουργοί». Στο πρώτο τραπέζι θα υπάρχουν κάρτες γεωγραφίας. Μία εξηγεί ότι ο Πηνειός διαρρέει την πεδιάδα της Θεσσαλίας. Μια άλλη συνδέει την Ορεστιάδα με την Περιφερειακή Ενότητα Έβρου. Οι επισκέπτες θα διαβάζουν τις κάρτες και θα διορθώνουν δύο λανθασμένες προτάσεις.\\nΣτο δεύτερο τραπέζι θα συζητήσουμε δύο έργα: την «Κοιμωμένη» του Γιαννούλη Χαλεπά και τις «Ομπρέλες» του Γιώργου Ζογγολόπουλου. Δεν θα χρησιμοποιήσουμε φωτογραφίες, επειδή δεν έχουμε ακόμη άδεια για τη χρήση τους. Θα εργαστούμε μόνο με σύντομα δικά μας κείμενα. Επομένως, η δραστηριότητα θα ελέγχει τη σύνδεση τίτλου και δημιουργού, όχι την αναγνώριση εικόνων.\\nΗ συνάντηση της ομάδας θα γίνει την Παρασκευή στις έξι, στην αίθουσα δύο. Αυτή είναι προετοιμασία για την έκθεση, όχι η ημέρα που θα την επισκεφτεί το κοινό. Η ημερομηνία της έκθεσης δεν έχει αποφασιστεί. Όποιος θέλει να βοηθήσει ας μας στείλει ένα σύντομο μήνυμα μέχρι την Πέμπτη, αναφέροντας ποιο τραπέζι προτιμά και γιατί.", "stimulus_id": "PEGP-LANG-P05-T01", "facts_source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057909#page=18", "sha256": "b2c569c8349c9150d4a96bf685647657d66bfc7ba08e12b02badddaf301e869a", "pdf_page": 18, "source_id": "PEGP-BANK-1057909", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 18, "official_topic": 38, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}, {"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057909#page=20", "sha256": "b2c569c8349c9150d4a96bf685647657d66bfc7ba08e12b02badddaf301e869a", "pdf_page": 20, "source_id": "PEGP-BANK-1057909", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 20, "official_topic": 42, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}, {"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057906#page=21", "sha256": "5163ff77c395802de2f24f88cfb65be7cc4681c128c6801e1d6d2566bceaea2d", "pdf_page": 21, "source_id": "PEGP-BANK-1057906", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 21, "official_topic": 33, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}, {"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057906#page=21", "sha256": "5163ff77c395802de2f24f88cfb65be7cc4681c128c6801e1d6d2566bceaea2d", "pdf_page": 21, "source_id": "PEGP-BANK-1057906", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 21, "official_topic": 33, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}], "fictional_details": ["group", "exhibition", "Friday preparation", "room2", "Thursday deadline"]}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
3044	object	PEGP-LANG-P06-T01	f2cb157753c74c5ff89f29162c2c1c36bc523b9036c1699ce3032dfbd146d556	\N	{"refs": [{"path": "GreekOS_PEGP_Module/language_support/texts/PEGP-LANG-P06-T01.json", "sha256": "d61e5b07a4289cd1c2b25b75961e28069871e4cdab51322988bdd362d8ab4fc9", "pointer": ""}], "payload": {"status": "ORIGINAL_DRAFT", "text_el": "Η ομάδα μελέτης θα συναντηθεί την Παρασκευή στις έξι το απόγευμα στην αίθουσα δύο. Πρώτα θα χωρίσουμε μερικά τοπωνύμια σε ηπειρωτικές και νησιωτικές περιοχές. Η Σίφνος και η Σύρος ανήκουν στη νησιωτική Ελλάδα, ενώ η Καρδίτσα και τα Γρεβενά στην ηπειρωτική. Μετά θα διαβάσουμε μια σύντομη σημείωση για το Νομισματικό Μουσείο και την παλιά κατοικία του Σλήμαν. Δεν θα χρησιμοποιήσουμε φωτογραφίες, επειδή δεν έχουμε ελέγξει τα δικαιώματα χρήσης τους. Κάθε μέλος θα εξηγήσει έναν από τους όρους με δικά του λόγια. Η συνάντηση είναι άσκηση προετοιμασίας της ομάδας, όχι επίσημη εξέταση.", "text_id": "PEGP-LANG-P06-T01", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "fact_source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057909#page=22", "sha256": "b2c569c8349c9150d4a96bf685647657d66bfc7ba08e12b02badddaf301e869a", "pdf_page": 22, "source_id": "PEGP-BANK-1057909", "checked_on": "2026-10-21", "bank_version": "2026/11", "printed_page": 22, "official_topic": 46, "verification_scope": "Selected fact read in retained official PDF text and visually rendered page. Not fresh download, whole-bank audit or legal-rule verification."}, {"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057906#page=22", "sha256": "5163ff77c395802de2f24f88cfb65be7cc4681c128c6801e1d6d2566bceaea2d", "pdf_page": 22, "source_id": "PEGP-BANK-1057906", "checked_on": "2026-10-21", "bank_version": "2026/11", "printed_page": 22, "official_topic": 34, "verification_scope": "Selected fact read in retained official PDF text and visually rendered page. Not fresh download, whole-bank audit or legal-rule verification."}], "fictional_details": "Time, room, study group and procedure are original fictional context, not official exam information"}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
