_review": "NOT_REVIEWED", "learner_task": "Вы — знакомый, хотите уточнить план без насмешки.", "expression_ids": ["RG-0001", "RG-0002", "RG-0003"], "scoring_evidence": ["Quote learner meaning clarification", "Quote neutral reformulation", "Record assistance and response to changed condition"], "phonology_scoring": false, "acceptable_example_not_exhaustive": "Πόσες λέξεις σκοπεύεις να μελετήσεις;"}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
