ен", "sample_feedback_ru": "Сначала укажите конкретно выполненную цель; затем одну подтверждённую трудность с цитатой. Не применять общий шаблон к отсутствующей ошибке.", "speech_recognition_uncertain": "ASR_UNCERTAIN, score withheld, ask repeat; not grammar/pronunciation penalty"}, "retention_tasks": {"D7": "D7: тренировка перенесена с пятницы17:00 на субботу11:00. Вы свободны; уточните, отменена ли пятница.", "D28": "D28: у мастерской нет подходящего времени. Узнайте альтернативу и вежливо откажитесь, не подтверждая неудобную запись."}, "branching_status": "AUTHORED", "learner_brief_ru": "Вы записались на разговорную встречу во вторник в18:00. В этот день можете только после19:00. Нужно уточнить новое время, а не выдумать подтверждение.", "transfer_task_ru": "D28: у мастерской нет подходящего времени. Узнайте альтернативу и вежливо откажитесь, не подтверждая неудобную запись.", "off_script_policy": {"unknown_fact": "Сказать, что нужно уточнить; не выдумывать ответ", "max_repair_loops": 2, "transition_ambiguity": "Prefer clarification; do not penalize ASR uncertainty", "unsafe_real_world_emergency": "Прервать учебную роль и дать уместный реальный ответ", "semantically_valid_unlisted_response": "Accept; examples are not exact keys"}, "learning_objective": "Изменение времени учебной встречи", "spoken_eval_status": "NOT_VALIDATED", "audio_review_status": "MISSING_AUDIO", "primary_competencies": ["A2-SI01", "A2-V02"], "runtime_transition_contract": {"precedence": "ASR uncertainty before semantic scoring", "repair_entry": "Save current active question node before entering REPAIR; increment per-session repair_count when clarification is supplied; do not overwrite saved node with REPAIR", "decline_outcome": "Store outcome=declined; no new purchase/booking. SC42 store old_booking_action=cancel or pending from confirmed learner reply. These are fictional role states; no external transaction.", "max_repair_loops": 2, "terminal_success": "Only after confirmed final learner re