3356	item	D-B1-SPOKEN_INTERACTION-01	ee44bc33bb530fbbd96ffb80fea6a9ad71e2a2f60cd873508a2119d3d9895b9d	core	{"type": "open_response", "level": "B1", "answer": [], "module": "core", "prompt": "Συμφωνήστε με συνεργάτη πώς θα μοιράσετε δύο εργασίες. Εκείνος δεν μπορεί να δουλέψει την ημέρα που προτείνετε. Βρείτε νέο σχέδιο και επιβεβαιώστε ποιος κάνει τι.", "rubric": "RUB-ENTRY-AXIS-01", "item_id": "D-B1-SPOKEN_INTERACTION-01", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": null, "version": "0.1.0", "criteria": ["Пересмотр плана и ясное распределение."], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/diagnostics/D-B1-SPOKEN_INTERACTION-01.json", "sha256": "43d3ed32d8246220503faed21ee3dd3e3ec422bf852c835af5c5de37bc095510"}, "error_tags": null, "audio_job_ids": [], "competency_ids": ["B1-SI01"], "model_response": "Μπορώ να ετοιμάσω το κείμενο την Τετάρτη. Μπορείς να βρεις τις εικόνες την ίδια μέρα; — Δεν μπορώ την Τετάρτη. — Τότε βρες τις την Πέμπτη και θα ενώσω τα δύο μέρη την Παρασκευή. Συμφωνούμε;", "requires_audio": true, "estimated_effort": null, "original_payload": {"pool": "diagnostic_holdout", "level": "B1", "stage": "entry_diagnostic", "prompt": "Συμφωνήστε με συνεργάτη πώς θα μοιράσετε δύο εργασίες. Εκείνος δεν μπορεί να δουλέψει την ημέρα που προτείνετε. Βρείτε νέο σχέδιο και επιβεβαιώστε ποιος κάνει τι.", "skills": ["spoken_interaction"], "status": "DRAFT", "item_id": "D-B1-SPOKEN_INTERACTION-01", "options": [], "unit_id": null, "version": "0.1.0", "language": "el+ru", "stimulus": null, "lic