3479	item	PEGP-LANG-P05-03	c20d9cb14105e7b96a6330400dba90e7af65258bcda1380e66a97590fe4d1713	pegp	{"type": "reading_inference", "level": "B1", "answer": ["Όχι. Την Παρασκευή γίνεται η προετοιμασία της ομάδας και η ημερομηνία της έκθεσης δεν έχει αποφασιστεί."], "module": "pegp", "prompt": "Μπορεί ένας επισκέπτης να συμπεράνει ότι η έκθεση ανοίγει την Παρασκευή στις έξι; Απαντήστε και στηρίξτε την απάντηση σε δύο στοιχεία του κειμένου.", "rubric": null, "item_id": "PEGP-LANG-P05-03", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": null, "version": "0.1.0", "criteria": [], "stimulus": {"text_id": "PEGP-LANG-P05-T01"}, "canonical": {"path": "GreekOS_PEGP_Module/language_support/items/PEGP-LANG-P05-03.json", "sha256": "dda7a9f3f0068926b7bfaa0adac7f8823a17843e2e891ae4d9e067a0810bbd80"}, "error_tags": null, "audio_job_ids": [], "competency_ids": [], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"status": "AUTHORED_DRAFT", "strand": "PEGP_LANGUAGE_SUPPORT_ORIGINAL", "item_id": "PEGP-LANG-P05-03", "version": "0.1.0", "prompt_el": "Μπορεί ένας επισκέπτης να συμπεράνει ότι η έκθεση ανοίγει την Παρασκευή στις έξι; Απαντήστε και στηρίξτε την απάντηση σε δύο στοιχεία του κειμένου.", "rationale": "Не достаточно общего «не знаем»: нужны два явных основания — подготовка отдельно от посещения и дата ещё не определена. За одно основание частичный балл.", "evaluation": {"full_credit": "Αρνητική απάντηση με δύο στοιχεία: προετοιμασία την Παρασκευή και άγνωστη ημερομηνία έκθεσης.", "partial_credit": "Σωστή άρνηση με μόνο ένα σχετικό στοιχείο.", "unlisted_plausible_answer": "REVIEW_NO_AUTOMATIC_PENALTY", "fact_and_language_separate": true}, "answer_type": "reading_inference", "publishable": false, "sou