3480	item	PEGP-LANG-P05-04	2220c1a28e596a2dfdb86dcd70443b38ad47496af276de75479fe87a3606aa48	pegp	{"type": "error_correction", "level": "B1", "answer": ["Η Ορεστιάδα βρίσκεται στην Περιφερειακή Ενότητα Έβρου. Οι Ομπρέλες είναι έργο του Γιώργου Ζογγολόπουλου."], "module": "pegp", "prompt": "Διορθώστε τις δύο λανθασμένες συνδέσεις: «Η Ορεστιάδα βρίσκεται στη Δράμα. Οι Ομπρέλες είναι έργο του Γιαννούλη Χαλεπά».", "rubric": null, "item_id": "PEGP-LANG-P05-04", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": null, "version": "0.1.0", "criteria": [], "stimulus": {"text_id": "PEGP-LANG-P05-T01"}, "canonical": {"path": "GreekOS_PEGP_Module/language_support/items/PEGP-LANG-P05-04.json", "sha256": "a6056c6a14abee86c1b46c2d010d47b3f379aac124124f127400ce084b5c1028"}, "error_tags": null, "audio_job_ids": [], "competency_ids": [], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"status": "AUTHORED_DRAFT", "strand": "PEGP_LANGUAGE_SUPPORT_ORIGINAL", "item_id": "PEGP-LANG-P05-04", "version": "0.1.0", "prompt_el": "Διορθώστε τις δύο λανθασμένες συνδέσεις: «Η Ορεστιάδα βρίσκεται στη Δράμα. Οι Ομπρέλες είναι έργο του Γιαννούλη Χαλεπά».", "rationale": "Проверяются две конкретные связи, без добавления местоположения скульптуры или дат. Допустимо написать только Έβρου / Γιώργου Ζογγολόπουλου с ясным соответствием.", "evaluation": {"unlisted_plausible_answer": "REVIEW_NO_AUTOMATIC_PENALTY", "fact_and_language_separate": true}, "answer_type": "error_correction", "publishable": false, "source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057909#page=18", "sha256": "b2c569c8349c9150d4a96bf685647657d66bfc7ba08e12b02badddaf301e869a", "pdf_page": 18, "source