3481	item	PEGP-LANG-P05-05	cd59ed27df13a7f66f157926d3687cb042ce66014a27bac920490cae73c1c9b2	pegp	{"type": "writing_transfer", "level": "B1", "answer": [], "module": "pegp", "prompt": "Γράψτε ένα μήνυμα περίπου 70–90 λέξεων στην ομάδα. Θέλετε να βοηθήσετε στο τραπέζι της γλυπτικής. Εξηγήστε γιατί, προτείνετε μία δραστηριότητα χωρίς φωτογραφίες και ζητήστε να σας ενημερώσουν όταν αποφασιστεί η ημερομηνία της έκθεσης. Μην παρουσιάσετε την Παρασκευή ως ημέρα εγκαινίων.", "rubric": {"mastery": "Ανεξάρτητη πρώτη προσπάθεια και νέα καθυστερημένη μεταφορά· το υπόδειγμα δεν είναι μοναδική λύση.", "task_0_2": {"0": "Δεν μεταδίδονται τα βασικά ζητούμενα ή αλλάζει κρίσιμο γεγονός.", "1": "Μεταδίδεται μέρος των ζητουμένων ή χρειάζεται βοήθεια.", "2": "Επιλέγει γλυπτική, δίνει σχετικό λόγο, προτείνει δραστηριότητα χωρίς φωτογραφίες και ζητά την άγνωστη ημερομηνία· δεν συγχέει προετοιμασία και έκθεση."}, "language_0_2": {"0": "Το νόημα δεν γίνεται κατανοητό.", "1": "Το νόημα γίνεται κατανοητό με προσπάθεια· υπάρχουν γλωσσικά λάθη.", "2": "Κατανοητές συνδεδεμένες φράσεις κατάλληλες για τον συγκεκριμένο αποδέκτη· μικρά λάθη δεν αλλάζουν το νόημα."}, "speaking_only": "Προφορά μόνο από πραγματικό ήχο με ακουστική αξιολόγηση. Γραπτό/ASR κείμενο: NO_PRONUNCIATION_SCORE."}, "item_id": "PEGP-LANG-P05-05", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": null, "version": "0.1.0", "criteria": [], "stimulus": {"text_id": "PEGP-LANG-P05-T01"}, "canonical": {"path": "GreekOS_PEGP_Module/language_support/items/PEGP-LANG-P05-05.json", "sha256": "05843c285abcb7206617379a97b7a4122aca72eb227d584cc5c2a7ab22b16afe"}, "error_tags": null, "audio_job_ids": [], "competency_ids": [], "model_response": "Καλησπέρα σας! Θα ήθελα να βοηθήσω στο τραπέζι της γλυπτικής, επειδή μου αρέσει να μαθαίνω για τους δημιουργούς και τα έργα τους. Προτείνω να ετοιμάσουμε μικρές κάρτες με τίτλους και ονόματα, ώστε οι επισκέπτες να βρίσκουν τα σωστά ζευγάρια. Έτσι δεν θα χρειαστούμε φωτογραφίες. Μπορώ να έρθω την Παρασκευή για την προετοιμασία. Παρακαλώ ενημερώστε με όταν αποφασιστεί η ημερομηνία της έκθεσης. Θα ήθελα τότε να καλέσω και μια φίλη μου, χωρίς να της δώσω λάθος πληροφορίες.", "requires_audio": false, "estimated_effort": null, "original_payload": {"rubric": {"mastery": "Ανεξάρτητη πρώτη προσπάθεια και νέα καθυστερημένη μεταφορά· το υπόδειγμα δεν είναι μοναδική λύση.", "task_0_2": {"0": "Δεν μεταδίδονται τα βασικά ζητούμενα ή αλλάζει κρίσιμο γεγονός.", "1": "Μεταδίδεται μέρος των ζητουμένων ή χρειάζεται βοήθεια.", "2": "Επιλέγει γλυπτική, δίνει σχετικό λόγο, προτείνει δραστηριότητα χωρίς φωτογραφίες και ζητά την άγνωστη ημερομηνία· δεν συγχέει προετοιμασία και έκθεση."}, "language_0_2": {"0": "Το νόημα δεν γίνεται κατανοητό.", "1": "Το νόημα γίνεται κατανοητό με προσπάθεια· υπάρχουν γλωσσικά λάθη.", "2": "Κατανοητές συνδεδεμένες φράσεις κατάλληλες για τον συγκεκριμένο αποδέκτη· μικρά λάθη δεν αλλάζουν το νόημα."}, "speaking_only": "Προφορά μόνο από πραγματικό ήχο με ακουστική αξιολόγηση. Γραπτό/ASR κείμενο: NO_PRONUNCIATION_SCORE."}, "status": "AUTHORED_DRAFT", "strand": "PEGP_LANGUAGE_SUPPORT_ORIGINAL", "item_id": "PEGP-LANG-P05-05", "version": "0.1.0", "prompt_el": "Γράψτε ένα μήνυμα περίπου 70–90 λέξεων στην ομάδα. Θέλετε να βοηθήσετε στο τραπέζι της γλυπτικής. Εξηγήστε γιατί, προτείνετε μία δραστηριότητα χωρίς φωτογραφίες και ζητήστε να σας ενημερώσουν όταν αποφασιστεί η ημερομηνία της έκθεσης. Μην παρουσιάσετε την Παρασκευή ως ημέρα εγκαινίων.", "rationale": "Оцениваются адресат, выбор, причина, выполнимая без фото деятельность и запрос даты.70–90слов ориентир, не официальный норматив. Модель содержит74 слова.", "evaluation": {"unlisted_plausible_answer": "REVIEW_NO_AUTOMATIC_PENALTY", "fact_and_language_separate": true}, "answer_type": "writing_transfer", "publishable": false, "source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057909#page=18", "sha256": "b2c569c8349c9150d4a96bf685647657d66bfc7ba08e12b02badddaf301e869a", "pdf_page": 18, "source_id": "PEGP-BANK-1057909", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 18, "official_topic": 38, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}, {"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057909#page=20", "sha256": "b2c569c8349c9150d4a96bf685647657d66bfc7ba08e12b02badddaf301e869a", "pdf_page": 20, "source_id": "PEGP-BANK-1057909", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 20, "official_topic": 42, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}, {"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057906#page=21", "sha256": "5163ff77c395802de2f24f88cfb65be7cc4681c128c6801e1d6d2566bceaea2d", "pdf_page": 21, "source_id": "PEGP-BANK-1057906", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 21, "official_topic": 33, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}, {"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057906#page=21", "sha256": "5163ff77c395802de2f24f88cfb65be7cc4681c128c6801e1d6d2566bceaea2d", "pdf_page": 21, "source_id": "PEGP-BANK-1057906", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 21, "official_topic": 33, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank com