3482	item	PEGP-LANG-P05-06	b60a4e8e6b46ce24d031172f07c542afaa7d421b437e62921de8e39a394d8bbb	pegp	{"type": "spoken_interaction", "level": "B1", "answer": [], "module": "pegp", "prompt": "Μιλήστε με τον υπεύθυνο χωρίς να διαβάζετε έτοιμο κείμενο. Ρωτήστε αν μπορείτε να βοηθήσετε την Παρασκευή. Ο υπεύθυνος λέει: «Μόνο από τις επτά, όχι από τις έξι». Εσείς μπορείτε μόνο μέχρι τις έξι και μισή. Εξηγήστε το πρόβλημα και προτείνετε να στείλετε τις κάρτες την Πέμπτη. Ο υπεύθυνος πρέπει να επιβεβαιώσει την πρόταση πριν τη θεωρήσετε συμφωνία.", "rubric": {"mastery": "Ανεξάρτητη πρώτη προσπάθεια και νέα καθυστερημένη μεταφορά· το υπόδειγμα δεν είναι μοναδική λύση.", "task_0_2": {"0": "Δεν μεταδίδονται τα βασικά ζητούμενα ή αλλάζει κρίσιμο γεγονός.", "1": "Μεταδίδεται μέρος των ζητουμένων ή χρειάζεται βοήθεια.", "2": "Δηλώνει σύγκρουση ωρών, προτείνει αποστολή την Πέμπτη ως ερώτημα και επιβεβαιώνει μόνο μετά από ρητή αποδοχή. Αποδεκτή και ευγενική αποχώρηση αν η πρόταση απορριφθεί."}, "language_0_2": {"0": "Το νόημα δεν γίνεται κατανοητό.", "1": "Το νόημα γίνεται κατανοητό με προσπάθεια· υπάρχουν γλωσσικά λάθη.", "2": "Κατανοητές συνδεδεμένες φράσεις κατάλληλες για τον συγκεκριμένο αποδέκτη· μικρά λάθη δεν αλλάζουν το νόημα."}, "speaking_only": "Προφορά μόνο από πραγματικό ήχο με ακουστική αξιολόγηση. Γραπτό/ASR κείμενο: NO_PRONUNCIATION_SCORE."}, "item_id": "PEGP-LANG-P05-06", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": null, "version": "0.1.0", "criteria": [], "stimulus": {"text_id": "PEGP-LANG-P05-T01"}, "canonical": {"path": "GreekOS_PEGP_Module/language_support/items/PEGP-LANG-P05-06.json", "sha256": "d9a791b63f9fdb5d06118a0cd1aa790c2db1b6bf1308abc1b658694f48f5286e"}, "error_tags": null, "audio_job_ids": [], "competency_ids": [], "model_response": "Μπορώ να βοηθήσω την Παρασκευή; — Μόνο από τις επτά, όχι από τις έξι. — Δυστυχώς μπορώ μόνο μέχρι τις έξι και μισή. Μπορώ να σας στείλω τις κάρτες την Πέμπτη; — Ναι, αυτό γίνεται. — Ωραία, θα σας τις στείλω την Πέμπτη.", "requires_audio": false, "estimated_effort": null, "original_payload": {"rubric": {"mastery": "Ανεξάρτητη πρώτη προσπάθεια και νέα καθυστερημένη μεταφορά· το υπόδειγμα δεν είναι μοναδική λύση.", "task_0_2": {"0": "Δεν μεταδίδονται τα βασικά ζητούμενα ή αλλάζει κρίσιμο γεγονός.", "1": "Μεταδίδεται μέρος των ζητουμένων ή χρειάζεται βοήθεια.", "2": "Δηλώνει σύγκρουση ωρών, προτείνει αποστολή την Πέμπτη ως ερώτημα και επιβεβαιώνει μόνο μετά από ρητή αποδοχή. Αποδεκτή και ευγενική αποχώρηση αν η πρόταση απορριφθεί."}, "language_0_2": {"0": "Το νόημα δεν γίνεται κατανοητό.", "1": "Το νόημα γίνεται κατανοητό με προσπάθεια· υπάρχουν γλωσσικά λάθη.", "2": "Κατανοητές συνδεδεμένες φράσεις κατάλληλες για τον συγκεκριμένο αποδέκτη· μικρά λάθη δεν αλλάζουν το νόημα."}, "speaking_only": "Προφορά μόνο από πραγματικό ήχο με ακουστική αξιολόγηση. Γραπτό/ASR κείμενο: NO_PRONUNCIATION_SCORE."}, "status": "AUTHORED_DRAFT", "strand": "PEGP_LANGUAGE_SUPPORT_ORIGINAL", "item_id": "PEGP-LANG-P05-06", "version": "0.1.0", "prompt_el": "Μιλήστε με τον υπεύθυνο χωρίς να διαβάζετε έτοιμο κείμενο. Ρωτήστε αν μπορείτε να βοηθήσετε την Παρασκευή. Ο υπεύθυνος λέει: «Μόνο από τις επτά, όχι από τις έξι». Εσείς μπορείτε μόνο μέχρι τις έξι και μισή. Εξηγήστε το πρόβλημα και προτείνετε να στείλετε τις κάρτες την Πέμπτη. Ο υπεύθυνος πρέπει να επιβεβαιώσει την πρόταση πριν τη θεωρήσετε συμφωνία.", "rationale": "Нужно отреагировать на новое ограничение, а не подтвердить невозможную встречу. Предложение не равно принятой договорённости; ответ сотрудника фиксируется отдельно.", "evaluation": {"unlisted_plausible_answer": "REVIEW_NO_AUTOMATIC_PENALTY", "fact_and_language_separate": true}, "answer_type": "spoken_interaction", "publishable": false, "source_refs": [{"url": "htt