_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "prompt_ru": "D7 и D28 проводятся отдельно, без карточки и моделей. Прочитайте только stimulus своего дня: объясните смысл выражения, назовите конкретную текстовую подсказку и дайте уместную нейтральную реплику. Не приписывайте услышанную интонацию отсутствующему звуку.", "rubric_id": "RG-PRAGMATICS-01", "source_ids": ["RG-D-ντεμέκ", "RG-REG-2015", "RG-F-NTEMEK"], "human_review": "NOT_REVIEWED", "answer_policy": "Meaning-equivalent responses reviewed without automatic penalty; model not exhaustive", "expression_id": "RG-0010", "prerequisites": ["B1 reading; difference between reported fact and inference"], "review_status": "AUTHOR_AI_CHECKED_SECOND_PASS_PENDING", "accepted_variants": [], "canonical_answers": [], "model_response_el": null, "retention_sessions": {"D7": {"stimulus_el": "Α: Μας πούλησαν ντεμέκ δερμάτινη τσάντα, λέει ο Πέτρος. Δεν την έχω δει.", "meaning_and_cue_ru": "Пётр оспаривает материал; рассказчик не проверял.", "instructor_reply_model_el": "Ο Πέτρος αμφισβητεί ότι είναι δερμάτινη. Εγώ δεν την έχω ελέγξει."}, "D28": {"stimulus_el": "Α: Ντεμέκ ειδικός, λέει η Άννα. Β: Έχουμε στοιχεία για την εμπειρία του;", "meaning_and_cue_ru": "Анна выражает отрицательную оценку; вопрос запрашивает основания.", "instructor_reply_model_el": "Η Άννα αμφισβητεί την εμπειρία του. Χρειάζονται στοιχεία."}}, "stimulus_original_el": null, "prerequisite_check_ids": ["RG-PC01", "RG-PC02", "RG-PC03", "RG-PC04"], "prerequisite_competency_ids": ["A1-G07", "A1-G08", "A1-G11", "A2-G11", "A1-PR01"]}, "prerequisite_ids": ["A1-G07", "A1-G08", "A1-G11", "A2-G11", "A1-PR01"], "source_claim_ids": ["CP09-INHERITED-RG-0010-