3619	item	RG-0012-Q05	e75369e1676ad9dc13eb217ef693d76023d275cebc8d294395234345a8206781	real_greek	{"type": "retention", "level": null, "answer": [], "module": "real_greek", "prompt": "D7 и D28 проводятся отдельно, без карточки и моделей. Прочитайте только stimulus своего дня: объясните смысл выражения, назовите конкретную текстовую подсказку и дайте уместную нейтральную реплику. Не приписывайте услышанную интонацию отсутствующему звуку.", "rubric": "RG-PRAGMATICS-01", "item_id": "RG-0012-Q05", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": null, "version": "0.1.4", "criteria": ["Контекстное значение объяснено без карточки", "Приведена конкретная реплика/деталь как основание", "Самостоятельный ответ соответствует фактам и дистанции", "Понимание и продукция фиксируются раздельно; одна вежливая фраза не доказывает понимание выражения"], "stimulus": null, "canonical": {"path": "GreekOS_Real_Greek/items/RG-0012-Q05.json", "sha256": "12c40af9eaefc8a050b336ad0a483fc4cb3a28ef27a98e0187b1dbbab644750e"}, "error_tags": null, "audio_job_ids": [], "competency_ids": [], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "real_greek_sidecar", "type": "retention", "item_id": "RG-0012-Q05", "mastery": "Independent contextual explanation + neutral reformulation + new situation + D7/D28; no observed learner data", "options": [], "version": "0.1.4", "criteria": ["Контекстное значение объяснено без карточки", "Приведена конкретная реплика/деталь как основание", "Самостоятельный ответ соответствует фактам и дистанции", "Понимание и продукция фиксируются раздельно; одна вежливая фраза не доказывает понимание выражения"], "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "prompt_ru": "D7 и D28 проводятся отдельно, без карточки и моделей. Прочитайте только stimulus своего дня: объясните смысл выражения, назовите конкретную текстовую подсказку и дайте уместную нейтральную реплику. Не приписывайте услышанную интонацию отсутствующему звуку.", "rubric_id": "RG-PRAGMATICS-01", "source_ids": ["RG-S-KAI"], "human_review": "NOT_REVIEWED", "answer_policy": "Meaning-equivalent responses reviewed without automatic penalty; model not exhaustive", "expression_id": "RG-0012", "prerequisites": ["B1 reading; difference between reported fact and inference"], "review_status": "AUTHOR_AI_CHECKED_SECOND_PASS_PENDING", "accepted_variants": [], "canonical_answers": [], "model_response_el": null, "retention_sessions": {"D7": {"stimulus_el": "Η Μαρία είπε: «Ο Πέτρος έφυγε και καλά για δουλειά». Εγώ δεν ξέρω τι έγινε.", "meaning_and_cue_ru": "В прямой цитате Мария дистанцируется от объяснения «по работе». Рассказчик прямо сообщает, что не знает, что произошло; личное свидетельство не заявлено.", "instructor_reply_model_el": "Σύμφωνα με τη Μαρία, ο Πέτρος έφυγε για δουλειά. Δεν ξέρω αν αυτός ήταν ο λόγος."}, "D28": {"stimulus_el": "Ο Νίκος είπε: «Η Ελένη είναι και καλά άρρωστη». Δεν την έχει δει.", "meaning_and_cue_ru": "В прямой цитате Никос выражает дистанцию к сообщению о болезни; он не видел Елену, поэтому оценка не доказывает её состояние.", "instructor_reply_model_el": "Σύμφωνα με τον Νίκο, η Ελένη είναι άρρωστη. Δεν γνωρίζω περισσότερα."}}, "stimulus_original_el": null, "prerequisite_check_ids": ["RG-PC01", "RG-PC02", "RG-PC03", "RG-PC04"], "prerequisite_competency_ids": ["A1-G07", "A1-G08", "A1-G11", "A2-G11", "A1-PR01"]}, "prerequisite_ids": ["A1-G07", "A1-G08", "A1-G11", "A2-G11", "A1-PR01"], "source_claim_ids": ["CP09-INHERITED-RG-0012-Q05-1"], "accepted_alternatives": []}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
