4191	item	U-A2-012-I10	6bc9c1acf356bf2a70ca8b9541bf4c34f094430704e3e07bd66eda2493100a56	core	{"type": "mcq", "level": "A2", "answer": ["В пятницу в пять"], "module": "core", "prompt": "По тексту, на какое время окончательно перенесён урок?", "rubric": null, "item_id": "U-A2-012-I10", "options": ["В среду в шесть", "В четверг утром", "В пятницу в пять"], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_human_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "CHOICE_KEY", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-A2-012", "version": "0.1.0", "criteria": [], "stimulus": "Η Μαρία δουλεύει σε ένα μικρό βιβλιοπωλείο. Την Τετάρτη έχει μάθημα ελληνικών στις έξι, αλλά αυτή την εβδομάδα θα δουλέψει μέχρι τις επτά. Γι’ αυτό ζητά από τη δασκάλα να αλλάξει την ώρα του μαθήματος. Την Πέμπτη το πρωί έχει ραντεβού με τον οδοντίατρο. Δεν μπορεί να αλλάξει αυτό το ραντεβού. Η δασκάλα προτείνει την Παρασκευή στις πέντε και η Μαρία συμφωνεί. Μετά το μάθημα θέλει να συναντήσει τη φίλη της, την Άννα. Η Άννα προτιμά να περπατήσουν στο πάρκο αντί να πάνε σινεμά. Η Μαρία δέχεται, αλλά ζητά να συναντηθούν στις επτά, όχι στις έξι.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-A2-012-I10.json", "sha256": "e3ac5d271a0c149c653dd633e69cc0cee59f3cb4b7995d1b9642dea5cfc4697c"}, "error_tags": null, "audio_job_ids": [], "competency_ids": ["A2-V02"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "A2", "stage": "reading", "prompt": "По тексту, на какое время окончательно перенесён урок?", "skills": ["reading"], "status": "DRAFT", "item_id": "U-A2-012-I10", "options": [