4230	item	U-A2-014-I10	81a3246cb7b637d6fb9aeda09a1a956adabecfc866a6a69360dad82cc9077241	core	{"type": "short_answer", "level": "A2", "answer": ["Γιατί έβρεχε."], "module": "core", "prompt": "По тексту: почему Арис и двоюродная сестра поехали на автобусе?", "rubric": null, "item_id": "U-A2-014-I10", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "EXACT_WITH_REVIEW_FALLBACK", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-A2-014", "version": "0.1.0", "criteria": [], "stimulus": {"text_el": "Την περασμένη Κυριακή ο Άρης πήγε σε μια έκθεση φωτογραφίας με την ξαδέλφη του. Πήγαν με λεωφορείο γιατί έβρεχε. Στην έκθεση είδαν φωτογραφίες από μικρά ελληνικά νησιά. Στον Άρη άρεσαν περισσότερο οι φωτογραφίες με ανθρώπους. Η ξαδέλφη του προτιμούσε τα τοπία. Μετά ήπιαν καφέ, αλλά δεν έφαγαν εκεί γιατί το καφέ δεν είχε φαγητό. Το επόμενο Σαββατοκύριακο ο Άρης θέλει να πάει σε μια άλλη έκθεση. Δεν ξέρει ακόμη ποια ημέρα θα πάει και δεν έχει αγοράσει εισιτήριο."}, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-A2-014-I10.json", "sha256": "ae7afa14c86a5c5d767c0bb30e5abb1f5e39f7780ab7e2ccf01de415aed9ac0f"}, "error_tags": ["COMPREHENSION"], "audio_job_ids": [], "competency_ids": ["A2-SP01"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "A2", "stage": "reading", "prompt": "По тексту: почему Арис и двоюродная сестра поехали на автобусе?", "skills": ["reading"], "status": "AUTHORED_DRAFT", "item_id": "U-A2-014-I10", "options": [], "qa_risk": "HIGH", "unit_id": "U-A2-014", "version": "0.1.0", "la