4434	item	U-B1-007-I11	646393334f4248e5ef42734234f4a485c7849d6dfb511d59c49a3d0b495a4a3c	core	{"type": "open_response", "level": "B1", "answer": [], "module": "core", "prompt": "Напишите 80–100 слов организатору: вы довольны первой встречей, но текущий день не подходит. Объясните причину, запросите альтернативу и информацию о порядке смены.", "rubric": "U-B1-007-RUBRIC", "item_id": "U-B1-007-I11", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B1-007", "version": "0.1.0", "criteria": ["Опыт и причина оценки", "Причина изменения", "Два конкретных запроса", "Единый регистр"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B1-007-I11.json", "sha256": "b330a7a30d94d07ed9b58a061897c13f417f655c5d2957cfa97ded1bbb4a80d9"}, "error_tags": null, "audio_job_ids": [], "competency_ids": ["B1-W01"], "model_response": "Αγαπητή κυρία Παππά, σας γράφω σχετικά με το εργαστήριο που ξεκίνησα αυτή την εβδομάδα. Η πρώτη συνάντηση μου άρεσε, ιδιαίτερα επειδή όλοι είχαμε την ευκαιρία να μιλήσουμε και να συνεργαστούμε. Δυστυχώς, το ωράριο της δουλειάς μου αλλάζει από την επόμενη εβδομάδα και δεν θα μπορώ να έρχομαι την Τετάρτη το απόγευμα. Θα ήθελα να ρωτήσω αν υπάρχει κάποιο πρωινό τμήμα ή συνάντηση άλλη μέρα. Αν υπάρχει διαθέσιμη θέση, μπορείτε να μου εξηγήσετε πώς γίνεται η αλλαγή; Ευχαριστώ πολύ για τη βοήθειά σας. Με εκτίμηση, Ίριδα.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B1", "stage": "writing", "prompt": "Напишите 80–100 слов организат