4452	item	U-B1-008-I13	b9d3a58d3ede9981a9c610e945ed3c120772d770e5103f6f1be82a5f439ef9a6	core	{"type": "open_response", "level": "B1", "answer": [], "module": "core", "prompt": "Напишите 80–100 слов группе: перенос встречи, реальная причина, новая цель, достигнутый результат; употребите επειδή, για να и γι’ αυτό.", "rubric": "U-B1-008-RUBRIC", "item_id": "U-B1-008-I13", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B1-008", "version": "0.1.0", "criteria": ["причина не перепутана с целью", "3 разные связи", "результат отделён от намерения"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B1-008-I13.json", "sha256": "16135c9f241b0b00d474509a008f386facf271f91c43042cfee1f9730f0f4f39"}, "error_tags": null, "audio_job_ids": [], "competency_ids": ["B1-G10"], "model_response": "Φίλοι μου, αλλάξαμε τον χώρο επειδή η αυλή είναι κλειστή. Κλείσαμε την αίθουσα για να καθίσουμε όλοι μαζί. Είχαμε μόνο δέκα καρέκλες. Γι’ αυτό δανειστήκαμε άλλες πέντε. Τώρα υπάρχουν αρκετές θέσεις. Στείλαμε μήνυμα και όλοι επιβεβαίωσαν ότι θα έρθουν. Η συνάντηση θα αρχίσει στις επτά. Παρακαλώ ελάτε λίγο νωρίτερα, για να ετοιμάσουμε τον χώρο πριν αρχίσει η συζήτηση. Αν χρειάζεστε οδηγίες, τηλεφωνήστε μου. Θα σας περιμένω στην είσοδο. Μετά τη συνάντηση θα επιστρέψουμε μαζί τις καρέκλες που δανειστήκαμε από τους γείτονες.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B1", "stage": "writing", "prompt": "Напишите 80–100 слов группе: перенос встречи, реальная причина, новая цель, достигнутый результат; употребите επειδή, για να и γι’ αυτό.", "skills": ["writing"], "status": "DRAFT", "item_id": "U-B1-008-I13", "options": [], "unit_id": "U-B1-008", "version": "0.1.0", "language": "el+ru", "stimulus": null, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Оценить передаваемый смысл по условиям задания; образец не единственный допустимый ответ.", "rubric_id": "U-B1-008-RUBRIC", "answer_type": "open_response", "publishable": false, "source_refs": [{"anchor": "Историческая уровневая тематическая карта; размещение требует эксперта", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Reception, production, interaction; author mapping, not official cut score", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "§5.2: αιτιολογικές, τελικές, αποτελεσματικές", "source_id": "N404", "checked_on": "2026-10-14", "claim_scope": "Грамматическое/фонетическое правило; задания оригинальные", "evidence_type": "OFFICIAL_SCHOOL_GRAMMAR_NOT_AUTH_SYLLABUS"}], "human_review": "NOT_REVIEWED", "item_version": "0.1.0", "activity_type": "independent_writing", "review_status": "DRAFT", "competency_ids": ["B1-G10"], "model_response": "Φίλοι μου, αλλάξαμε τον χώρο επειδή η αυλή είναι κλειστή. Κλείσαμε την αίθουσα για να καθίσουμε όλοι μαζί. Είχαμε μόνο δέκα καρέκλες. Γι’ αυτό δανειστήκαμε άλλες πέντε. Τώρα υπάρχουν αρκετές θέσεις. Στείλα