4497	item	U-B1-010-I14	c8fdfcfc935c349b3ac8049eda8fefb77383ac5ea7d9e48caa2ccc24cc3d5ae8	core	{"type": "open_response", "level": "B1", "answer": [], "module": "core", "prompt": "100–120 слов о подготовке мероприятия: процесс, завершение, чужое действие и факт с неизвестным исполнителем.", "rubric": "U-B1-010-RUBRIC", "item_id": "U-B1-010-I14", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B1-010", "version": "0.1.1", "criteria": ["Форма/смысл", "Процесс/завершение", "Агент только известный"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B1-010-I14.json", "sha256": "943aed525a760d6f336b418b1f79e92f969bf80523cb5bb94c93f5a84732e571"}, "error_tags": null, "audio_job_ids": [], "competency_ids": ["B1-G04"], "model_response": "Χτες ετοιμαζόμασταν για μια μικρή εκδήλωση στη σχολή. Εγώ ντυνόμουν όταν με πήρε τηλέφωνο η Άννα. Είπε ότι υπήρχε πρόβλημα με τον υπολογιστή. Ντύθηκα γρήγορα και πήγα εκεί. Το πρόβλημα λύθηκε από την τεχνική ομάδα πριν αρχίσει η εκδήλωση. Στην είσοδο θυμήθηκα ότι είχα αφήσει τις σημειώσεις μου στο σπίτι. Μια φίλη μου έδωσε τις δικές της και έτσι μπόρεσα να μιλήσω. Η ώρα της επόμενης συνάντησης άλλαξε, αλλά δεν ξέρω ποιος πήρε αυτή την απόφαση. Στο τέλος μαζέψαμε τις καρέκλες και ευχαριστήσαμε όσους βοήθησαν. Ήμουν κουρασμένος, αλλά χάρηκα που συνεργαστήκαμε τόσο καλά. Την επόμενη φορά θα ετοιμάσω τις σημειώσεις μου από το προηγούμενο βράδυ.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B1", "stage": "writing", "prompt": "100–120 слов о подготовке мероприятия: процесс, завершение, чужое действие и факт с неизвестным исполнителем.", "skills": ["writing"], "status": "DRAFT", "item_id": "U-B1-010-I14", "options": [], "unit_id": "U-B1-010", "version": "0.1.1", "language": "el+ru", "stimulus": null, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Оценить передаваемый смысл по условиям задания; образец не единственный допустимый ответ.", "rubric_id": "U-B1-010-RUBRIC", "answer_type": "open_response", "source_refs": [{"anchor": "B1-G04 historical curricular theme only", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "B1 interaction/production, project mapping", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "§6.2 φωνές/διαθέσεις; λύνομαι; θυμάμαι; ανώμαλα", "source_id": "N405", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}], "item_version": "0.1.1", "review_status": "DRAFT", "competency_ids": ["B1-G04"], "model_response": "Χτες ετοιμαζόμασταν για μια μικρή εκδήλωση στη σχολή. Εγώ ντυνόμουν όταν με πήρε τηλέφωνο η Άννα. Είπε ότι υπήρχε πρόβλημα με τον υπολογιστή. Ντύθηκα γρήγορα και πήγα εκεί. Το πρόβλημα λύθηκε από την τεχνική ομάδα πριν αρχίσει η εκδήλωση. Στην είσοδο θυμήθηκα ότι είχα αφήσει τις σημειώσεις μου στο σπίτι. Μια φίλη μου έδωσε 