4512	item	U-B1-011-I10	c00b334b2d3c1174f0e9f55e55167b6c10e7ec495b816d6e2ecd108c647b9878	core	{"type": "short_answer", "level": "B1", "answer": ["Οι οδηγίες είναι στα ελληνικά και το σύντομο σημείωμα στα αγγλικά."], "module": "core", "prompt": "Прочитайте текст. На каких языках доступны инструкции и заметка?", "rubric": "U-B1-011-RUBRIC", "item_id": "U-B1-011-I10", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "EXACT_WITH_REVIEW_FALLBACK", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B1-011", "version": "0.1.1", "criteria": [], "stimulus": "Σήμερα η ομάδα μας ετοίμασε μια μικρή έκθεση φωτογραφίας. Η Ελένη έφτασε κρατώντας έναν μεγάλο φάκελο. Μέσα είχε τις φωτογραφίες της γειτονιάς. Ο Πέτρος διάβαζε τις οδηγίες μιλώντας χαμηλόφωνα. Οι οδηγίες ήταν γραμμένες στα ελληνικά, αλλά υπήρχε και ένα σύντομο αγγλικό σημείωμα. Εγώ στεκόμουν κοντά στην είσοδο και βοηθούσα τους επισκέπτες. Δύο πόρτες στο πίσω μέρος ήταν κλεισμένες. Δεν ξέρω ποιος τις έκλεισε ούτε πότε. Στο τέλος ήμασταν όλοι κουρασμένοι, αλλά δεν φύγαμε αμέσως. Καθίσαμε μαζί και συζητήσαμε τι θα αλλάξουμε την επόμενη φορά. Η Ελένη πρότεινε να γράψουμε μεγαλύτερες πινακίδες. Ο Πέτρος συμφώνησε χαμογελώντας. Εγώ ζήτησα να υπάρχει ένας άνθρωπος στην είσοδο σε όλη τη διάρκεια της έκθεσης.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B1-011-I10.json", "sha256": "40d82076223d59bb9fec181690ff339e09bc54b9dca6ffb2fa9680272dd9d280"}, "error_tags": null, "audio_job_ids": [], "competency_ids": ["B1-G12"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "co