4531	item	U-B1-012-I10	7b1a408e5cccd8c1e333f75f3b02d666eb61c199908fc8a2ef3ece890cfe151e	core	{"type": "short_answer", "level": "B1", "answer": ["Τα βιβλία με πράσινη ετικέτα, για δύο εβδομάδες."], "module": "core", "prompt": "По тексту библиотеки: какие книги можно взять домой и на какой срок?", "rubric": "U-B1-012-RUBRIC", "item_id": "U-B1-012-I10", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "EXACT_WITH_REVIEW_FALLBACK", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B1-012", "version": "0.1.1", "criteria": [], "stimulus": "Στη δημοτική βιβλιοθήκη λειτουργεί μια μικρή ομάδα ανταλλαγής βιβλίων. Τα βιβλία που έχουν πράσινη ετικέτα μπορείτε να τα πάρετε για δύο εβδομάδες. Τα βιβλία που έχουν κόκκινη ετικέτα διαβάζονται μόνο στην αίθουσα. Η υπάλληλος η οποία οργανώνει την ομάδα λέγεται Εύα. Η αίτηση την οποία συμπληρώνετε στην είσοδο χρειάζεται μόνο το όνομα και το τηλέφωνό σας. Η Εύα, που εργάζεται εδώ κάθε απόγευμα, μπορεί να σας βοηθήσει. Την Παρασκευή έρχεται ο συγγραφέας που πρότειναν τα μέλη της ομάδας. Η συνάντηση είναι δωρεάν για όλους· δεν χρειάζεται κάρτα μέλους. Παρακαλούμε να επιστρέψετε στην υποδοχή τα βιβλία που δανειστήκατε. Μην τα αφήνετε μόνοι σας στα ράφια.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B1-012-I10.json", "sha256": "2246f32e4507ff5afb8715ad20f05e19383bb7f5e59edb4c7727735aaa4251f5"}, "error_tags": null, "audio_job_ids": [], "competency_ids": ["B1-G08"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B1", "stage": "reading", "prompt": "По 