4550	item	U-B1-013-I10	48b33dc812fb97e77ca471306679e9598b86b63525b29ffd9b7541171fa290b7	core	{"type": "short_answer", "level": "B1", "answer": ["Όχι, δεν έχει σταλεί ακόμη."], "module": "core", "prompt": "По тексту: отправлено ли уже окончательное сообщение посетителям? Ответьте по-гречески.", "rubric": "U-B1-013-RUBRIC", "item_id": "U-B1-013-I10", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "EXACT_WITH_REVIEW_FALLBACK", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B1-013", "version": "0.1.1", "criteria": [], "stimulus": "Αύριο η ομάδα μας θα ετοιμάσει μια μικρή εκδήλωση στη γειτονιά. Πριν ανοίξουμε την αίθουσα, θα ελέγξουμε τις καρέκλες και τα φώτα. Η Άννα θα φέρει τα κλειδιά στις πέντε. Όσοι φτάσουν νωρίτερα θα περιμένουν στο καφέ μέχρι να έρθει. Αφού ανοίξουμε, ο Νίκος θα βάλει τα βιβλία στα τραπέζια. Εγώ θα στείλω το τελικό μήνυμα στους επισκέπτες αφού ελέγξω τη διεύθυνση και την ώρα. Δεν το έχω στείλει ακόμη. Θα μείνουμε στην αίθουσα μέχρι τις οκτώ. Πριν φύγουμε, θα μαζέψουμε τα σκουπίδια. Αν η Άννα αργήσει, θα σας ενημερώσω στο τηλέφωνο. Η εκδήλωση είναι δοκιμαστική, γι’ αυτό δεν θα πουλήσουμε εισιτήρια.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B1-013-I10.json", "sha256": "3ab2a6f82af4515aba4239092fc79ae6a78c7e29cb412ae9646879b8a5cc2d87"}, "error_tags": null, "audio_job_ids": [], "competency_ids": ["B1-G11"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B1", "stage": "reading", "prompt": "По тексту: отправлено ли уже окончательное сообщение посетителям?