4569	item	U-B1-014-I10	fe421b281dc2f6dc7546cd24fdc2b68ffd16b694bd5d7c4c6e2034eb0d93febb	core	{"type": "mcq", "level": "B1", "answer": ["Για να γίνει πιο σαφές."], "module": "core", "prompt": "Прочитайте текст. Зачем участник перепишет свой текст?", "rubric": "U-B1-014-RUBRIC", "item_id": "U-B1-014-I10", "options": ["Για να γίνει πιο σαφές.", "Για να αλλάξει η τιμή.", "Για να πουλήσει βιβλία."], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "CHOICE_KEY", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B1-014", "version": "0.1.0", "criteria": [], "stimulus": {"text": "Στη μικρή βιβλιοθήκη της γειτονιάς οργανώνουμε ένα εργαστήριο για ενήλικες. Ο εκπαιδευτής θα δείξει πώς γράφουμε μια σύντομη ανακοίνωση στον υπολογιστή. Δεν χρειάζεται προηγούμενη εμπειρία. Η οργάνωση του εργαστηρίου γίνεται από τρεις εθελοντές, ενώ τα βιβλία παραμένουν διαθέσιμα για δανεισμό. Όποιος θέλει να αγοράσει βιβλίο πρέπει να πάει στο βιβλιοπωλείο της πλατείας. Στο τέλος κάθε συμμετέχων θα διαβάσει το δικό του κείμενο. Αν κάτι δεν είναι σαφές, θα το ξαναγράψει με τη βοήθεια της ομάδας. Το εργαστήριο είναι δωρεάν, αλλά οι θέσεις είναι μόνο δέκα. Η εγγραφή γίνεται στη βιβλιοθήκη μέχρι την Παρασκευή.", "origin": "ORIGINAL_GREEKOS_TEXT"}, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B1-014-I10.json", "sha256": "7b7544de87e5eb637a76c4cbfb1d555aa41eefa14c4c3b4ca433e9e2fa7c2eb9"}, "error_tags": ["VOCAB_SELECTION"], "audio_job_ids": [], "competency_ids": ["B1-G13"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B1", "stage": "reading", "prompt": "Прочитайте текст. Зачем участник перепишет свой текст?", "status": "AUTHORED_DRAFT", "item_id": "U-B1-014-I10", "options": ["Για να γίνει πιο σαφές.", "Για να αλλάξει η τιμή.", "Για να πουλήσει βιβλία."], "qa_risk": "HIGH", "unit_id": "U-B1-014", "version": "0.1.0", "language": "el+ru", "stimulus": {"text": "Στη μικρή βιβλιοθήκη της γειτονιάς οργανώνουμε ένα εργαστήριο για ενήλικες. Ο εκπαιδευτής θα δείξει πώς γράφουμε μια σύντομη ανακοίνωση στον υπολογιστή. Δεν χρειάζεται προηγούμενη εμπειρία. Η οργάνωση του εργαστηρίου γίνεται από τρεις εθελοντές, ενώ τα βιβλία παραμένουν διαθέσιμα για δανεισμό. Όποιος θέλει να αγοράσει βιβλίο πρέπει να πάει στο βιβλιοπωλείο της πλατείας. Στο τέλος κάθε συμμετέχων θα διαβάσει το δικό του κείμενο. Αν κάτι δεν είναι σαφές, θα το ξαναγράψει με τη βοήθεια της ομάδας. Το εργαστήριο είναι δωρεάν, αλλά οι θέσεις είναι μόνο δέκα. Η εγγραφή γίνεται στη βιβλιοθήκη μέχρι την Παρασκευή.", "origin": "ORIGINAL_GREEKOS_TEXT"}, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "В тексте условие — недостаточная ясность, а не оплата.", "rubric_id": "U-B1-014-RUBRIC", "error_tags": ["VOCAB_SELECTION"], "answer_type": "mcq", "source_refs": [{"anchor": "§2.2 lines13–38; §2.3 lines46–49", "source_id": "CP07-B1-S01", "checked_on": "2026-10-20", "claim_scope": "Word families; derivation versus inflection; prefixes have more than one meaning; compounding and variable stress; polysemy. Original vocabulary examples separately require linguistic QA."}, {"anchor": "Reading lines92–96; production98–103; education/work139–145; travel1