4589	item	U-B1-015-I10	977ecd0ec45206123cac1fdad3c6d93714e6193d6b3fa254dca44cc773f6655e	core	{"type": "mcq", "level": "B1", "answer": ["Να σταλεί ηλεκτρονικά η αίτηση."], "module": "core", "prompt": "Ποια ενέργεια ζητά πρώτα η ανακοίνωση;", "rubric": "U-B1-015-RUBRIC", "item_id": "U-B1-015-I10", "options": ["Να σταλεί ηλεκτρονικά η αίτηση.", "Να γίνει επίσκεψη χωρίς ραντεβού.", "Να σταλούν αμέσως όλα τα δικαιολογητικά."], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "CHOICE_KEY", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B1-015", "version": "0.1.0", "criteria": [], "stimulus": {"text": "Το δημοτικό κέντρο μάθησης οργανώνει ένα απογευματινό πρόγραμμα υπολογιστών για ενήλικες. Τα μαθήματα αρχίζουν στις 12 Νοεμβρίου και γίνονται κάθε Τρίτη και Πέμπτη, από τις έξι μέχρι τις οκτώ. Για να ζητήσετε θέση, στείλτε ηλεκτρονικά την αίτηση μέχρι την Παρασκευή. Μην στείλετε άλλα δικαιολογητικά τώρα. Η γραμματεία θα απαντήσει με μήνυμα και θα σας ενημερώσει για όσα χρειάζονται. Η αποστολή της αίτησης δεν σημαίνει ότι ολοκληρώθηκε η εγγραφή. Αν δεν λάβετε απάντηση μέσα σε τρεις εργάσιμες ημέρες, τηλεφωνήστε στη γραμματεία. Για τεχνικό πρόβλημα με το αρχείο της αίτησης, μπορείτε να ζητήσετε άλλο τρόπο αποστολής. Δεν χρειάζεται να πάτε στο κέντρο χωρίς ραντεβού.", "origin": "ORIGINAL_GREEKOS_TEXT"}, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B1-015-I10.json", "sha256": "34ad09d1c8db387b6ad51665858e19688200de2b1f8acda9aa5b59b7003d2531"}, "error_tags": ["VOCAB_SELECTION"], "audio_job_ids": [], "competency_ids": ["B1-V01"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B1", "stage": "reading", "prompt": "Ποια ενέργεια ζητά πρώτα η ανακοίνωση;", "status": "AUTHORED_DRAFT", "item_id": "U-B1-015-I10", "options": ["Να σταλεί ηλεκτρονικά η αίτηση.", "Να γίνει επίσκεψη χωρίς ραντεβού.", "Να σταλούν αμέσως όλα τα δικαιολογητικά."], "qa_risk": "HIGH", "unit_id": "U-B1-015", "version": "0.1.0", "language": "el+ru", "stimulus": {"text": "Το δημοτικό κέντρο μάθησης οργανώνει ένα απογευματινό πρόγραμμα υπολογιστών για ενήλικες. Τα μαθήματα αρχίζουν στις 12 Νοεμβρίου και γίνονται κάθε Τρίτη και Πέμπτη, από τις έξι μέχρι τις οκτώ. Για να ζητήσετε θέση, στείλτε ηλεκτρονικά την αίτηση μέχρι την Παρασκευή. Μην στείλετε άλλα δικαιολογητικά τώρα. Η γραμματεία θα απαντήσει με μήνυμα και θα σας ενημερώσει για όσα χρειάζονται. Η αποστολή της αίτησης δεν σημαίνει ότι ολοκληρώθηκε η εγγραφή. Αν δεν λάβετε απάντηση μέσα σε τρεις εργάσιμες ημέρες, τηλεφωνήστε στη γραμματεία. Για τεχνικό πρόβλημα με το αρχείο της αίτησης, μπορείτε να ζητήσετε άλλο τρόπο αποστολής. Δεν χρειάζεται να πάτε στο κέντρο χωρίς ραντεβού.", "origin": "ORIGINAL_GREEKOS_TEXT"}, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Первый шаг явно заявлен; документы пока не запрашиваются.", "rubric_id": "U-B1-015-RUBRIC", "error_tags": ["VOCAB_SELECTION"], "answer_type": "mcq", "source_refs": [{"anchor": "Reading lines92–96; production98–103; education/work139–145; travel147–152", "source_id": "CP07-B1-S02", "checked_on": "2026-10-20", "claim_scope": "B1 functional scope: main idea/details of familiar texts, rout