4609	item	U-B1-016-I10	8e4295ae5480aef81c4afcd92685a7646af3f4b61fc73460129a692d65d168c1	core	{"type": "mcq", "level": "B1", "answer": ["Το καλώδιο ήταν για ακουστικά, όχι για φόρτιση."], "module": "core", "prompt": "Γιατί η πρώτη πρόταση της υπαλλήλου δεν ήταν κατάλληλη;", "rubric": "U-B1-016-RUBRIC", "item_id": "U-B1-016-I10", "options": ["Το καλώδιο ήταν για ακουστικά, όχι για φόρτιση.", "Η Λένα δεν είχε κινητό.", "Η Λένα ήθελε να αγοράσει μουσική."], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "CHOICE_KEY", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B1-016", "version": "0.1.0", "criteria": [], "stimulus": {"text": "Η Λένα έφτασε στο γραφείο συνεργασίας και κατάλαβε ότι είχε ξεχάσει τον φορτιστή της. Το κινητό της είχε σχεδόν αδειάσει και έπρεπε να τηλεφωνήσει σε έναν συνεργάτη. Δεν θυμόταν τη λέξη «φορτιστής», γι’ αυτό είπε στην υπάλληλο: «Χρειάζομαι τη συσκευή που συνδέουμε στην πρίζα για να φορτίσουμε το κινητό». Η υπάλληλος της έδειξε πρώτα ένα καλώδιο για ακουστικά. Η Λένα εξήγησε ότι δεν ήθελε να ακούσει μουσική και έδειξε την υποδοχή του κινητού της. Τότε βρήκαν τον σωστό φορτιστή. Η υπάλληλος επέτρεψε να τον χρησιμοποιήσει μέσα στον χώρο, αλλά ζήτησε να μην τον πάρει μαζί της. Η Λένα ευχαρίστησε και επανέλαβε τον όρο σε μια φράση: «Θα αφήσω τον φορτιστή εδώ πριν φύγω».", "origin": "ORIGINAL_GREEKOS_TEXT"}, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B1-016-I10.json", "sha256": "30b8732253d8a11c8449ba36acd25e20fa70e7ec7bd5b00e846392ea57141bf5"}, "error_tags": ["VOCAB_SELECTION"], "audio_job_ids": [], "competency_ids": ["B1-V02"], "model_response": null, 