4632	item	U-B1-017-I13	9665ab18e5931a32dde10dfd7e63bd764f5b46c87ce2a9430fe50a5da26e5380	core	{"type": "short_answer", "level": "B1", "answer": ["Όχι."], "module": "core", "prompt": "После будущей записи: гарантировано ли решение об утренних часах на встрече?", "rubric": "U-B1-017-RUBRIC", "item_id": "U-B1-017-I13", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "EXACT_WITH_REVIEW_FALLBACK", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B1-017", "version": "0.1.0", "criteria": [], "stimulus": {"text": "Υπάλληλος: Η συνάντηση για τη νέα αίθουσα θα γίνει την Πέμπτη στις έξι το απόγευμα.\\nΕπισκέπτρια: Πρέπει να κάνουμε κράτηση για να έρθουμε στη συνάντηση;\\nΥπάλληλος: Όχι, για τη συνάντηση δεν χρειάζεται κράτηση. Για τη χρήση της αίθουσας από ομάδα, όμως, χρειάζεται.\\nΕπισκέπτρια: Θα αποφασιστούν τότε οι πρωινές ώρες;\\nΥπάλληλος: Όχι απαραίτητα. Θα ακούσουμε πρώτα τις προτάσεις των επισκεπτών.", "asset_id": "U-B1-017-AUD01"}, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B1-017-I13.json", "sha256": "dd78ff723dc305f0b552736b14046ce29b24acd56ba0548a32d4cd7a608df160"}, "error_tags": ["COMPREHENSION"], "audio_job_ids": ["U-B1-017-AUD01"], "competency_ids": ["B1-R01"], "model_response": null, "requires_audio": true, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B1", "stage": "listening_script", "prompt": "После будущей записи: гарантировано ли решение об утренних часах на встрече?", "status": "AUTHORED_DRAFT", "item_id": "U-B1-017-I13", "options": [], "qa_risk": "HIGH", "unit_id": "U-B1-017", "version": "0.1.0", "fallback":