4633	item	U-B1-017-I14	37d99517d393302adcf002e8d948c754163df208ac8ef1df4068e455c1cae898	core	{"type": "open_response", "level": "B1", "answer": [], "module": "core", "prompt": "Напишите80–110слов другу по статье: почему появилась комната, кому подходит, какиеусловия действуют в первуюнеделю и что ещё не решено. Не придумывайте воскресные часы.", "rubric": "U-B1-017-RUBRIC", "item_id": "U-B1-017-I14", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B1-017", "version": "0.1.0", "criteria": ["цельсотрудничества", "2–4участника,броньзадень,до2часов", "16–19 в первуюнеделю", "утронерешено и воскресенье неизвестно"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B1-017-I14.json", "sha256": "998225c2a55bdc771c922529cad2346a125576748c612ab2cbdd30802907c4b7"}, "error_tags": ["CONTENT_OMISSION"], "audio_job_ids": [], "competency_ids": ["B1-R01"], "model_response": "Γεια σου, Νίκο. Διάβασα ότι η βιβλιοθήκη ανοίγει μια αίθουσα για μικρές ομάδες μελέτης, επειδή αρκετοί επισκέπτες χρειάζονται χώρο για κοινές εργασίες. Μπορούμε να πάμε μαζί με άλλους δύο φίλους, αλλά πρέπει να κάνουμε κράτηση μία ημέρα νωρίτερα. Η χρήση είναι δωρεάν και μπορούμε να μείνουμε μέχρι δύο ώρες. Την πρώτη εβδομάδα η αίθουσα ανοίγει μόνο από τις τέσσερις μέχρι τις επτά το απόγευμα. Οι πρωινές ώρες δεν έχουν αποφασιστεί ακόμη· εξαρτώνται από τους εθελοντές. Για την Κυριακή δεν βρήκα πληροφορίες. Θέλεις να ρωτήσουμε στην υποδοχή;", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course