4641	item	U-B1-018-I02	2b505a78f0ee54ccbf55e636996aa5eddbc75cf18de4a038ccf4402606c7edc3	core	{"type": "mcq", "level": "B1", "answer": ["Добавляется вечернее занятие с предварительной записью."], "module": "core", "prompt": "Выберите главный смысл сообщения.", "rubric": null, "item_id": "U-B1-018-I02", "options": ["Добавляется вечернее занятие с предварительной записью.", "Отменяются все утренние занятия.", "Открывается платная мастерская ремонта."], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "CHOICE_KEY", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B1-018", "version": "0.1.0", "criteria": [], "stimulus": {"text_el": "Καλησπέρα σε όλους. Από την επόμενη εβδομάδα το εργαστήριο υπολογιστών θα λειτουργεί και κάθε Τετάρτη από τις πέντε μέχρι τις επτά το απόγευμα. Η αλλαγή γίνεται επειδή αρκετοί κάτοικοι εργάζονται το πρωί και δεν μπορούσαν να έρθουν. Το πρωινό πρόγραμμα της Δευτέρας δεν αλλάζει. Την Τετάρτη μπορείτε να εξασκηθείτε στην αποστολή μηνυμάτων και στη χρήση απλών ηλεκτρονικών φορμών. Δεν πρόκειται για μάθημα επισκευής υπολογιστών. Δεν χρειάζεται να φέρετε δικό σας υπολογιστή, γιατί υπάρχουν συσκευές στην αίθουσα. Χρειάζεται όμως να δηλώσετε συμμετοχή μέχρι τη Δευτέρα, ώστε να ξέρουμε πόσες θέσεις θα ετοιμάσουμε. Αν οι θέσεις γεμίσουν, θα επικοινωνήσουμε μαζί σας για μια άλλη ημέρα. Η συμμετοχή είναι δωρεάν. Για περισσότερες πληροφορίες ρωτήστε στη γραμματεία.", "display_policy": "AFTER_ATTEMPT_ONLY"}, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B1-018-I02.json", "sha256": "9c46eee422874fd71560a735306052eb6ae8ead5bd37c7ae97ff7361d0507acb"}, "error_tags": ["C