4653	item	U-B1-019-I02	e1f9ea4de94484213443033db448c20006f2200caf3fd9e9a10a786379abea3e	core	{"type": "mcq", "level": "B1", "answer": ["Брать книги."], "module": "core", "prompt": "Для чего Анна сначала приходила?", "rubric": null, "item_id": "U-B1-019-I02", "options": ["Брать книги.", "Работать каждый день.", "Учить журналиста."], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "CHOICE_KEY", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B1-019", "version": "0.1.0", "criteria": [], "stimulus": {"text_el": "Δημοσιογράφος: Πώς ξεκίνησες να βοηθάς στη βιβλιοθήκη; Άννα: Στην αρχή πήγαινα μόνο για να δανειστώ βιβλία. Μια μέρα είδα μια ανακοίνωση για εθελοντές και μίλησα με την υπεύθυνη. Νόμιζα ότι θα χρειαζόταν να έρχομαι κάθε μέρα, αλλά μου εξήγησε ότι δύο ώρες την εβδομάδα ήταν αρκετές. Δημοσιογράφος: Ήταν εύκολη η πρώτη μέρα; Άννα: Όχι ακριβώς. Δεν ήξερα πού βρίσκονταν όλα τα βιβλία και φοβόμουν μήπως δώσω λάθος πληροφορία. Ένας άλλος εθελοντής μου έδειξε τον κατάλογο. Μετά από λίγες συναντήσεις ένιωθα πιο άνετα. Τώρα βοηθάω τους επισκέπτες να βρουν αυτό που ψάχνουν. Δημοσιογράφος: Θα το πρότεινες σε κάποιον άλλο; Άννα: Ναι, αρκεί να ρωτήσει πρώτα τι ακριβώς χρειάζεται. Δεν χρειάζεται να ξέρει τα πάντα από την πρώτη μέρα. Είναι όμως σημαντικό να ενημερώνει εγκαίρως αν δεν μπορεί να έρθει.", "display_policy": "AFTER_ATTEMPT_ONLY"}, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B1-019-I02.json", "sha256": "5383c3aefe0d9d8eb2a2f7ec6f70994d85311a2144592e3a9405b08115ee4655"}, "error_tags": ["COMPREHENSION"], "audio_job_ids": ["U-B1-019-AUD01"], "competency_ids": ["B1-L02"], "mod