sion": "0.1.1", "language": "el+ru", "stimulus": "Η γειτονιά διαθέτει έναν μικρό ελεύθερο χώρο δίπλα στη βιβλιοθήκη. Μια ομάδα κατοίκων προτείνει να τοποθετηθούν παγκάκια και φυτά. Άλλοι ανησυχούν ότι θα περιοριστεί η πρόσβαση για τα οχήματα τροφοδοσίας. Η πρώτη ομάδα δεν αρνείται το πρόβλημα. Προτείνει να μείνει ελεύθερη μια συγκεκριμένη διαδρομή και να δοκιμαστεί η αλλαγή για έναν μήνα. Η πρόταση δεν συνοδεύεται ακόμη από αναλυτικό προϋπολογισμό. Η βιβλιοθήκη ζητά να ακουστούν και οι απόψεις όσων χρησιμοποιούν τον χώρο καθημερινά.", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Остальные перефразировки требуют семантической проверки, не автоматического штрафа.", "rubric_id": null, "answer_type": "short_answer", "publishable": false, "source_refs": [{"anchor": "V201 PDF4,12–14; V268 PDF4 подтверждает жанр статьи; не подмена всеми заданиями письма", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Reports and essays / thematic development / coherence, B2", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "human_review": "NOT_REVIEWED", "item_version": "0.1.1", "review_status": "DRAFT", "competency_ids": ["B2-W02", "B2-G07"], "model_response": null, "success_criteria": [], "accepted_variants": [], "canonical_answers": ["η πρόσβαση των οχημάτων τροφοδοσίας", "η πρόσβαση για τα οχήματα τροφοδοσίας"], "source_provenance": "original_authoring", "difficult