4799	item	U-B2-005-I14	46104c6595a1cef03c87fb68c63f51c5f7d474e7d00100ec8e60ef54c4f3ecbe	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Без модели объясните клиенту за 90 секунд причину задержки, канал отправки и требование подписи. Клиент говорит «Не понимаю официальный язык». Перескажите просто.", "rubric": "U-B2-005-RUBRIC", "item_id": "U-B2-005-I14", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-005", "version": "0.1.0", "criteria": ["причина и канал различены", "падежи верны", "понятный пересказ по запросу"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-005-I14.json", "sha256": "3c998b04db16a42c566f537d7db8fef4e4796f8618e76af4daee25b362c80e02"}, "error_tags": null, "audio_job_ids": [], "competency_ids": ["B2-G06"], "model_response": "Η καθυστέρηση οφείλεται στη βλάβη. Στείλτε την αίτηση μέσω της πλατφόρμας. Σύμφωνα με τον κανονισμό, χρειάζεται υπογραφή. Δηλαδή, ανοίξτε την πλατφόρμα, ανεβάστε το έντυπο και βεβαιωθείτε ότι το έχετε υπογράψει.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "speaking", "prompt": "Без модели объясните клиенту за 90 секунд причину задержки, канал отправки и требование подписи. Клиент говорит «Не понимаю официальный язык». Перескажите просто.", "skills": ["spoken_interaction"], "status": "DRAFT", "item_id": "U-B2-005-I14", "options": [], "unit_id": "U-B2-005", "version": "0.1.0", "language": "el+ru", "stimulus": null, "licensing