4817	item	U-B2-006-I10	2498ac3b39e72d7e5ab898c175ad6fd6f8be9459fd74887c71d332a01cee2304	core	{"type": "short_answer", "level": "B2", "answer": ["Οι ημερομηνίες."], "module": "core", "prompt": "По тексту: что оставалось непроверенным после правки заголовков?", "rubric": "U-B2-006-RUBRIC", "item_id": "U-B2-006-I10", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "EXACT_WITH_REVIEW_FALLBACK", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-006", "version": "0.1.1", "criteria": [], "stimulus": "Η ομάδα του περιοδικού ετοιμάζει ένα μικρό αφιέρωμα στη γειτονιά. Τη Δευτέρα η συντάκτρια διόρθωνε τα κείμενα όταν ο φωτογράφος έστειλε ένα νέο αρχείο. Οι τίτλοι διορθώθηκαν την ίδια μέρα, αλλά οι ημερομηνίες δεν ελέγχθηκαν. Την Τρίτη ο υπεύθυνος έγραψε στην ομάδα: «Έχουμε διορθώσει τους τίτλους. Πρέπει όμως να ελέγξουμε τις ημερομηνίες πριν στείλουμε το αρχείο στο τυπογραφείο». Μια συνεργάτιδα διάβασε γρήγορα το μήνυμα και ανακοίνωσε ότι όλα ήταν έτοιμα. Ο υπεύθυνος της ζήτησε να διορθώσει την ανακοίνωση. Δεν ήθελε να αποδώσει ευθύνη σε κάποιο συγκεκριμένο πρόσωπο· ήθελε να γίνει σαφές ποια εργασία εκκρεμούσε. Πρότεινε να ελέγχονται οι ημερομηνίες από δύο άτομα στο τέλος κάθε έκδοσης. Για το συγκεκριμένο τεύχος, η Μαρία προσφέρθηκε να κάνει τον έλεγχο το απόγευμα. Η πρότασή της έγινε δεκτή, αλλά εκείνη τη στιγμή ο έλεγχος δεν είχε ακόμη ολοκληρωθεί.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-006-I10.json", "sha256": "97d10c2a0b99c6bc3561f9b550635229686a5c7f4d24eea281803329d6c3f41c"}, "error_tags": null, "audio_job_ids": [], "competency_ids": ["B2-G02"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "reading", "prompt": "По тексту: что оставалось непроверенным после правки заголовков?", "skills": ["reading"], "status": "DRAFT", "item_id": "U-B2-006-I10", "options": [], "unit_id": "U-B2-006", "version": "0.1.1", "language": "el+ru", "stimulus": "Η ομάδα του περιοδικού ετοιμάζει ένα μικρό αφιέρωμα στη γειτονιά. Τη Δευτέρα η συντάκτρια διόρθωνε τα κείμενα όταν ο φωτογράφος έστειλε ένα νέο αρχείο. Οι τίτλοι διορθώθηκαν την ίδια μέρα, αλλά οι ημερομηνίες δεν ελέγχθηκαν. Την Τρίτη ο υπεύθυνος έγραψε στην ομάδα: «Έχουμε διορθώσει τους τίτλους. Πρέπει όμως να ελέγξουμε τις ημερομηνίες πριν στείλουμε το αρχείο στο τυπογραφείο». Μια συνεργάτιδα διάβασε γρήγορα το μήνυμα και ανακοίνωσε ότι όλα ήταν έτοιμα. Ο υπεύθυνος της ζήτησε να διορθώσει την ανακοίνωση. Δεν ήθελε να αποδώσει ευθύνη σε κάποιο συγκεκριμένο πρόσωπο· ήθελε να γίνει σαφές ποια εργασία εκκρεμούσε. Πρότεινε να ελέγχονται οι ημερομηνίες από δύο άτομα στο τέλος κάθε έκδοσης. Για το συγκεκριμένο τεύχος, η Μαρία προσφέρθηκε να κάνει τον έλεγχο το απόγευμα. Η πρότασή της έγινε δεκτή, αλλά εκείνη τη στιγμή ο έλεγχος δεν είχε ακόμη ολοκληρωθεί.", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Сохранить смысл и грамматические отношения; допустимый незаписанный вариант направляется на проверку без автоматического штрафа.", "rubric_id": "U-B2-006-RUBRIC", "answer_type": "short_answer", "source_refs": [{"anchor": "§6.2α lines 10–18; §6.2ε lines 79–109", "source_id": "N405", 