4819	item	U-B2-006-I12	e37467d5d29be8c52764a7aeb3722ab27b6df7e83e48e9007d7406c3113ae9c6	core	{"type": "short_answer", "level": "B2", "answer": ["Ο τίτλος."], "module": "core", "prompt": "По будущей записи: какой элемент уже исправлен? До появления звука читайте сценарий.", "rubric": "U-B2-006-RUBRIC", "item_id": "U-B2-006-I12", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "EXACT_WITH_REVIEW_FALLBACK", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-006", "version": "0.1.1", "criteria": [], "stimulus": {"text": "Α: Μπορούμε να στείλουμε την ανακοίνωση τώρα;\\nΒ: Όχι ακόμη. Ο τίτλος έχει διορθωθεί, αλλά πρέπει να ελέγξουμε τις ώρες.\\nΑ: Νόμιζα ότι τις είχες ελέγξει χτες.\\nΒ: Έλεγχα τις ώρες όταν ήρθε ένα νέο πρόγραμμα. Πρέπει να συγκρίνω τα δύο αρχεία.\\nΑ: Θα μπορούσες να το κάνεις μέχρι τις τρεις;\\nΒ: Ναι, μπορώ. Θα σου στείλω μήνυμα όταν τελειώσω.\\nΑ: Ωραία. Θα περιμένω το μήνυμά σου πριν στείλω την ανακοίνωση.", "asset_id": "U-B2-006-SCRIPT", "audio_files": [], "audio_status": "BLOCKED_MISSING_AUDIO", "timing_status": "NOT_MEASURED", "duration_seconds": null}, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-006-I12.json", "sha256": "918bb317d9a39dcd80d7ffc99b253162345a5a4e8bfd1f321f7ba32db61dddf3"}, "error_tags": null, "audio_job_ids": ["U-B2-006-SCRIPT"], "competency_ids": ["B2-G02"], "model_response": null, "requires_audio": true, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "listening_script_only", "prompt": "По будущей записи: какой элемент уже исправлен? До появления звука читайте сценарий