4835	item	U-B2-007-I09	12bef11dd5990bc3555388e18778a29754c538846b015ee2f2a25acb231b9284	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Факты: сначала вы проверили адрес; после этого ваш коллега отправил письмо. Напишите одно ясное греческое предложение. Не приписывайте обе операции одному человеку.", "rubric": "U-B2-007-RUBRIC", "item_id": "U-B2-007-I09", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "semantic_rubric_with_abstention", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-007", "version": "0.1.2", "criteria": ["Проверил адрес говорящий", "Отправил коллега", "Проверка предшествует отправке"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-007-I09.json", "sha256": "495af6bb2be17d00cde03f17fb22e47baadaccc5c9b91dd31fe3410ddb4f99fc"}, "error_tags": ["SYNTAX", "CONTENT_OMISSION"], "audio_job_ids": [], "competency_ids": ["B2-G04"], "model_response": "Αφού έλεγξα τη διεύθυνση, ο συνάδελφός μου έστειλε το μήνυμα.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "recall", "prompt": "Факты: сначала вы проверили адрес; после этого ваш коллега отправил письмо. Напишите одно ясное греческое предложение. Не приписывайте обе операции одному человеку.", "skills": ["recall"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-007-I09", "options": [], "qa_risk": "HIGH", "unit_id": "U-B2-007", "version": "0.1.2", "language": "el+ru", "stimulus": null, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Разные субъекты требуют явного различения: проверку выполнили вы, отправку — коллега. В одном предложении допустима временная придаточная конструкция с явным подлежащим.", "rubric_id": "U-B2-007-RUBRIC", "error_tags": ["SYNTAX", "CONTENT_OMISSION"], "answer_type": "open_response", "source_refs": [{"anchor": "§6.2ι lines251–255", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S01", "source_id": "N405", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}, {"anchor": "§2 lines13–23,37–43", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S02", "source_id": "N-F07-PART", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}], "item_version": "0.1.2", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-G04"], "model_response": "Αφού έλεγξα τη διεύθυνση, ο συνάδελφός μου έστειλε το μήνυμα.", "source_claim_ids": ["F07-B2-S01", "F07-B2-S02"], "success_criteria": ["Проверил адрес говорящий", "Отправил коллега", "Проверка предшествует отправке"], "accepted_variants": [], "canonical_answers": [], "source_provenance": "Original GreekOS teaching task; narrow source claims only", "difficulty_estimate": "B2_AUTHOR_ESTIMATE_NOT_CALIBRATED", "response_evaluation": {"method": "semantic_rubric_with_abstention", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}}, "prerequisite_ids": ["B1-G12", "B2-G02"], "source_claim_ids": ["F07-B2-S01", "F07-B2-S02"], "accepted_alternatives": []}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-1