4836	item	U-B2-007-I10	d88e566959148cc3ab401dba44cbfc3c4d2dc42e0177e2287418983067d08279	core	{"type": "mcq", "level": "B2", "answer": ["Δεν είχε ακόμη ελέγξει τα πρωτότυπα."], "module": "core", "prompt": "По тексту об архиве: почему Λένα не исправила подписи сразу?", "rubric": "U-B2-007-RUBRIC", "item_id": "U-B2-007-I10", "options": ["Δεν είχε ακόμη ελέγξει τα πρωτότυπα.", "Δεν είχε βρει κανένα λάθος.", "Είχε ήδη λάβει άδεια ανάρτησης."], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "CHOICE_KEY", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-007", "version": "0.1.0", "criteria": [], "stimulus": {"text": "Η μικρή ομάδα του δημοτικού αρχείου ετοιμάζει μια ψηφιακή έκθεση για την καθημερινή ζωή της γειτονιάς. Διαβάζοντας τις περιγραφές, η Λένα εντόπισε δύο φωτογραφίες με λανθασμένη ημερομηνία. Δεν άλλαξε τις λεζάντες μόνη της, επειδή δεν είχε ακόμη ελέγξει τα πρωτότυπα. Ο Άρης, έχοντας συγκρίνει τα πρωτότυπα με τον κατάλογο, επιβεβαίωσε τη σωστή χρονολογία. Οι διορθωμένες λεζάντες στάλθηκαν έπειτα στη συντονίστρια. Η ομάδα αποφάσισε να διατηρήσει και ένα αντίγραφο της προηγούμενης έκδοσης, ώστε να είναι ορατή η αλλαγή.\\nΣτην τελική σημείωση αναφέρεται ότι το υλικό είναι ελεγμένο, όχι όμως έτοιμο για δημόσια ανάρτηση. Μένει να επιβεβαιωθεί η άδεια χρήσης των φωτογραφιών. Μια συνεργάτιδα πρότεινε να συντομεύσουν τη σημείωση σε «Έτοιμο υλικό». Η συντονίστρια διαφώνησε: μια πιο σύντομη διατύπωση δεν πρέπει να δίνει στον επισκέπτη λανθασμένη εικόνα. Ζήτησε λοιπόν δύο χωριστές πληροφορίες, μία για τον έλεγχο και μία για την άδεια. Το χρονοδιάγραμμα της έκθεσης θα ανακοινωθεί μόνο αφού ολοκληρωθεί αυτή η διαδικασία."}, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-007-I10.json", "sha256": "bc7c6acf87cdef20ca752897e7818d264a2038f7d4d209a7088c5f64aa707d1e"}, "error_tags": ["COMPREHENSION"], "audio_job_ids": [], "competency_ids": ["B2-G04"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "reading", "prompt": "По тексту об архиве: почему Λένα не исправила подписи сразу?", "skills": ["reading"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-007-I10", "options": ["Δεν είχε ακόμη ελέγξει τα πρωτότυπα.", "Δεν είχε βρει κανένα λάθος.", "Είχε ήδη λάβει άδεια ανάρτησης."], "qa_risk": "HIGH", "unit_id": "U-B2-007", "version": "0.1.0", "language": "el+ru", "stimulus": {"text": "Η μικρή ομάδα του δημοτικού αρχείου ετοιμάζει μια ψηφιακή έκθεση για την καθημερινή ζωή της γειτονιάς. Διαβάζοντας τις περιγραφές, η Λένα εντόπισε δύο φωτογραφίες με λανθασμένη ημερομηνία. Δεν άλλαξε τις λεζάντες μόνη της, επειδή δεν είχε ακόμη ελέγξει τα πρωτότυπα. Ο Άρης, έχοντας συγκρίνει τα πρωτότυπα με τον κατάλογο, επιβεβαίωσε τη σωστή χρονολογία. Οι διορθωμένες λεζάντες στάλθηκαν έπειτα στη συντονίστρια. Η ομάδα αποφάσισε να διατηρήσει και ένα αντίγραφο της προηγούμενης έκδοσης, ώστε να είναι ορατή η αλλαγή.\\nΣτην τελική σημείωση αναφέρεται ότι το υλικό είναι ελεγμένο, όχι όμως έτοιμο για δημόσια ανάρτηση. Μένει να επιβεβαιωθεί η άδεια χρήσης των φωτογραφιών. Μια συνεργάτιδα πρότεινε να συντομεύσουν τη σημείωση σε «Έτοιμο υλικό». Η συντονίστρια διαφώνησε: μια πιο σύντομη διατύπωση δεν πρέπει να δίνει στον επισκέπτη λανθασμένη εικόνα. Ζήτησε λοιπόν δύο χωριστές πληροφορίες, μία για τον έλεγχο και μία για την άδεια. Το χρονοδιάγραμμα της έκθεσης θα ανακοινωθεί μόνο αφού ολοκληρωθεί αυτή η διαδικασία."}, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Явно назван непроведённый ею контроль оригиналов.", "rubric_id": "U-B2-007-RUBRIC", "error_tags": ["COMPREHENSION"], "answer_type": "mcq", "source_refs": [{"anchor": "§6.2ι lines251–255", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S01", "source_id": "N405", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}, {"anchor": "§2 lines13–23,37–43", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S02", "source_id": "N-F07-PART", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}], "item_version": "0.1.0", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-G04"], "model_response": null, "source_claim_ids": ["F07-B2-S01", "F07-B2-S02"], "success_criteria": [], "accepted_variants": [], "canonical_answers": ["Δεν είχε ακόμη ελέγξει τα πρωτότυπα."], "source_provenance": "Original GreekOS teaching task; narrow source claims only", "difficulty_estimate": "B2_AUTHOR_ESTIMATE_NOT_CALIBRATED", "response_evaluation": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}}, "prerequisite_ids": ["B1-G12", "B2-G02"], "source_claim_ids": ["F07-B2-S01", "F07-B2-S02"], "accepted_alternatives": []}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
