4841	item	U-B2-007-I15	190129895a88b975c326d555dfabbfc63e461ddd7f1a0bfedb07770c694b17e9	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Голосовое объяснение коллеге 60–90 секунд без чтения модели: «Οι διορθωμένες οδηγίες είναι διαθέσιμες, αλλά η δοκιμή του εξοπλισμού εκκρεμεί». Объясните простыми словами, что готово, чего ещё нет, и спросите, кто организует пробу. Не оценивайте произношение без прослушивания.", "rubric": "U-B2-007-RUBRIC", "item_id": "U-B2-007-I15", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "semantic_rubric_with_abstention", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-007", "version": "0.1.0", "criteria": ["Корректно развёрнуто διορθωμένες", "Проба не объявлена завершённой", "Есть вопрос об ответственном", "Самостоятельная связная речь; пример не диктует длину ответа"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-007-I15.json", "sha256": "5867b2348a9fd235a7f42b19d059149c6d26a7bff41c940be1df00af5f1da280"}, "error_tags": ["SPEECH_INTELLIGIBILITY", "CONTENT_OMISSION", "ASR_UNCERTAIN"], "audio_job_ids": [], "competency_ids": ["B2-G04"], "model_response": "Οι οδηγίες έχουν διορθωθεί και μπορούμε να τις διαβάσουμε. Δεν έχει γίνει ακόμη η δοκιμή του εξοπλισμού, οπότε δεν ξέρουμε αν όλα λειτουργούν σωστά. Ποιος θα οργανώσει τη δοκιμή;", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "speaking", "prompt": "Голосовое объяснение коллеге 60–90 секунд без чтения модели: «Οι διορθωμένες οδηγίες είναι διαθέσιμες, αλλά η δοκιμή του εξοπλισμού εκκρεμεί». Объясните простыми словами, что готово, чего ещё нет, и спросите, кто организует пробу. Не оценивайте произношение без прослушивания.", "skills": ["speaking"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-007-I15", "options": [], "qa_risk": "HIGH", "unit_id": "U-B2-007", "version": "0.1.0", "language": "el+ru", "stimulus": null, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Краткая смысловая модель; ученик развивает ответ своими уточнениями.", "rubric_id": "U-B2-007-RUBRIC", "error_tags": ["SPEECH_INTELLIGIBILITY", "CONTENT_OMISSION", "ASR_UNCERTAIN"], "answer_type": "open_response", "source_refs": [{"anchor": "§6.2ι lines251–255", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S01", "source_id": "N405", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}, {"anchor": "§2 lines13–23,37–43", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S02", "source_id": "N-F07-PART", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}], "item_version": "0.1.0", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-G04"], "model_response": "Οι οδηγίες έχουν διορθωθεί και μπορούμε να τις διαβάσουμε. Δεν έχει γίνει ακόμη η δοκιμή του εξοπλισμού, οπότε δεν ξέρουμε αν όλα λειτουργούν σωστά. Ποιος θα οργανώσει τη δοκιμή;", "source_claim_ids": ["F07-B2-S01", "F07-B2-S02"], "success_criteria": ["Корректно развёрнуто διορθωμένες", "Проба не объявлена завершённой", "Есть вопрос об ответственном", "Самостоятельная связная речь; пример не диктует длину ответа"], "accepted_variants": [],