4842	item	U-B2-007-I16	ac8f07a8f8bbdc8ca00410800900dc2dfb1d861303320fcf9895e1368d7af523	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Новая ситуация — спортивный клуб. Вы лично сравнили расписания двух залов; администратор забронировал только малый зал; большой пока недоступен. Дайте тренеру 4–6 греческих предложений: сообщите факты, предложите план и запросите решение. Сокращайте только там, где это не меняет исполнителя.", "rubric": "U-B2-007-RUBRIC", "item_id": "U-B2-007-I16", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "semantic_rubric_with_abstention", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-007", "version": "0.1.0", "criteria": ["Говорящий сравнил, администратор забронировал", "Только малый зал забронирован", "Предложение и запрос решения", "4–6 предложений без неподтверждённых сроков"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-007-I16.json", "sha256": "12897265a81e29c352ea0fcad0f26d2a241a3846559c8c8dc840cee2725832d5"}, "error_tags": ["SYNTAX", "PRAGMATICS_REGISTER", "CONTENT_OMISSION"], "audio_job_ids": [], "competency_ids": ["B2-G04"], "model_response": "Έχοντας συγκρίνει τα προγράμματα των δύο αιθουσών, μπορώ να σας ενημερώσω για τη διαθεσιμότητα. Ο διαχειριστής έχει κλείσει μόνο τη μικρή αίθουσα. Η μεγάλη δεν είναι ακόμη διαθέσιμη. Προτείνω να οργανώσουμε την προπόνηση σε μικρές ομάδες. Συμφωνείτε ή προτιμάτε να αλλάξουμε ημέρα;", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "transfer", "prompt": "Новая ситуация — спортивный клуб. Вы лично сравнили расписания двух залов; администратор забронировал только малый зал; большой пока недоступен. Дайте тренеру 4–6 греческих предложений: сообщите факты, предложите план и запросите решение. Сокращайте только там, где это не меняет исполнителя.", "skills": ["transfer"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-007-I16", "options": [], "qa_risk": "HIGH", "unit_id": "U-B2-007", "version": "0.1.0", "language": "el+ru", "stimulus": null, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Новый адресат и предмет, контроль участников не заученного текста.", "rubric_id": "U-B2-007-RUBRIC", "error_tags": ["SYNTAX", "PRAGMATICS_REGISTER", "CONTENT_OMISSION"], "answer_type": "open_response", "source_refs": [{"anchor": "§6.2ι lines251–255", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S01", "source_id": "N405", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}, {"anchor": "§2 lines13–23,37–43", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S02", "source_id": "N-F07-PART", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}], "item_version": "0.1.0", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-G04"], "model_response": "Έχοντας συγκρίνει τα προγράμματα των δύο αιθουσών, μπορώ να σας ενημερώσω για τη διαθεσιμότητα. Ο διαχειριστής έχει κλείσει μόνο τη μικρή αίθουσα. Η μεγάλη δεν είναι ακόμη διαθέσιμη. Προτείνω να οργανώσουμε την προπόνηση σε μικρές ομάδες. Συμφωνείτε ή προτιμάτε να αλλάξουμε ημέρα;", "source_claim_ids": ["F07-B2-S01", "F07-B2-S02"], "