4843	item	U-B2-007-I17	faa1727addea0a53006db083b8c6d3005d7e9c08b30d836060f38db8c4da76fc	core	{"type": "short_answer", "level": "B2", "answer": ["Έχοντας διαβάσει πρώτα την κριτική, επέλεξα την παράσταση."], "module": "core", "prompt": "Без справочника, новый контекст: «Αφού διάβασα πρώτα την κριτική, επέλεξα την παράσταση». Начните с Έχοντας, сохраните предварительное чтение.", "rubric": "U-B2-007-RUBRIC", "item_id": "U-B2-007-I17", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "EXACT_WITH_REVIEW_FALLBACK", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-007", "version": "0.1.1", "criteria": [], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-007-I17.json", "sha256": "04211850b3b11f4da5f6da84d6d969cf1b06f16f1d5b9f9dd8d516a8567e51f3"}, "error_tags": ["VERB_ASPECT", "ORTHOGRAPHY_ACCENT"], "audio_job_ids": [], "competency_ids": ["B2-G04"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "D7", "prompt": "Без справочника, новый контекст: «Αφού διάβασα πρώτα την κριτική, επέλεξα την παράσταση». Начните с Έχοντας, сохраните предварительное чтение.", "skills": ["D7"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-007-I17", "options": [], "qa_risk": "HIGH", "unit_id": "U-B2-007", "version": "0.1.1", "language": "el+ru", "stimulus": null, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_al