4844	item	U-B2-007-I18	5bb5c2953d91d8702fdaea2a7aa26939b0c4c5e98167e097d53bb1fa8f115400	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Факты: две сотрудницы обучены работе с программой, один сотрудник ещё обучается. Сообщите это по-гречески в двух фразах, используя εκπαιδευμένες и личную глагольную форму для продолжающегося обучения.", "rubric": "U-B2-007-RUBRIC", "item_id": "U-B2-007-I18", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "semantic_rubric_with_abstention", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-007", "version": "0.1.0", "criteria": ["Женское множественное εκπαιδευμένες", "Процесс обучения третьего не представлен завершённым", "Численность сохранена"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-007-I18.json", "sha256": "1e2f540279afed38ae3368fcef3cccc00a462c98744f8cfdcf7179cfa3f8a5f1"}, "error_tags": ["GENDER_AGREEMENT", "VERB_ASPECT"], "audio_job_ids": [], "competency_ids": ["B2-G04"], "model_response": "Οι δύο υπάλληλοι είναι εκπαιδευμένες στη χρήση του προγράμματος. Ένας υπάλληλος εκπαιδεύεται ακόμη.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "D14", "prompt": "Факты: две сотрудницы обучены работе с программой, один сотрудник ещё обучается. Сообщите это по-гречески в двух фразах, используя εκπαιδευμένες и личную глагольную форму для продолжающегося обучения.", "skills": ["D14"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-007-I18", "options": [], "qa_risk": "HIGH", "unit_id": "U-B2-007", "vers