4845	item	U-B2-007-I19	c069313cb46d731101747ca7a5fa86ea1d1c2a721d9f37c2e00b9c9c5c1d4e44	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Редакторская проверка: «Ελέγχοντας τις κρατήσεις, το λεωφορείο έφυγε». Автор поясняет: Νίκος проверял бронирования, автобус тем временем уехал. Исправьте сообщение без потери фактов.", "rubric": "U-B2-007-RUBRIC", "item_id": "U-B2-007-I19", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "semantic_rubric_with_abstention", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-007", "version": "0.1.0", "criteria": ["Проверяет Никос, не автобус", "Отъезд во время проверки", "Ясные личные формы"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-007-I19.json", "sha256": "af70862b313f3a5d59681d65c2c3ac14fcad96377c83598a27e345735daa8efb"}, "error_tags": ["SYNTAX", "COMPREHENSION"], "audio_job_ids": [], "competency_ids": ["B2-G04"], "model_response": "Ενώ ο Νίκος έλεγχε τις κρατήσεις, το λεωφορείο έφυγε.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "guided", "prompt": "Редакторская проверка: «Ελέγχοντας τις κρατήσεις, το λεωφορείο έφυγε». Автор поясняет: Νίκος проверял бронирования, автобус тем временем уехал. Исправьте сообщение без потери фактов.", "skills": ["guided"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-007-I19", "options": [], "qa_risk": "HIGH", "unit_id": "U-B2-007", "version": "0.1.0", "language": "el+ru", "stimulus": null, "licensing": {"originator": "GreekOS AI-assisted original authoring",