4857	item	U-B2-008-I11	34a57c427c4cc8726fb2381ad5d90a07f34aa88231a99827d564534a41d0ea63	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "По тексту: объясните по-гречески, почему сообщение «όλοι θα εξυπηρετηθούν αμέσως» исправили. Назовите два необоснованных обещания из последнего абзаца.", "rubric": "U-B2-008-RUBRIC", "item_id": "U-B2-008-I11", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "semantic_rubric_with_abstention", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-008", "version": "0.1.0", "criteria": ["Не обещана немедленная помощь", "Не объявлен приём любого прибора", "Связь этих фактов с исправлением"], "stimulus": {"text": "Το κέντρο της γειτονιάς ανακοίνωσε ότι το εργαστήριο επισκευής μικρών αντικειμένων θα γίνει σε δύο ομάδες. Οι ενδιαφερόμενοι που έχουν ήδη συμπληρώσει τη φόρμα θα λάβουν μήνυμα για την ώρα της συνάντησης. Όσοι δεν έχουν ακόμη δηλώσει συμμετοχή μπορούν να επικοινωνήσουν με τη γραμματεία, αλλά δεν υπάρχει εγγύηση ότι θα βρεθεί διαθέσιμη θέση.\\nΗ υπεύθυνη εξήγησε πως η αλλαγή έγινε επειδή ο χώρος είναι μικρός. Ζήτησε από τους συμμετέχοντες να μην φέρουν μεγάλες ηλεκτρικές συσκευές. Η τεχνίτρια με την οποία συνεργάζεται το κέντρο θα παρουσιάσει απλές επισκευές, ενώ ένας εθελοντής θα καταγράφει τις ερωτήσεις. Η τεχνίτρια, της οποίας η πρόταση αποτέλεσε τη βάση του προγράμματος, τόνισε ότι ο σκοπός δεν είναι να επισκευαστούν όλα τα αντικείμενα μέσα σε μία συνάντηση.\\nΈνα σύντομο μήνυμα στα κοινωνικά δίκτυα έγραφε ότι «όλοι θα εξυπηρετηθούν αμέσως». Η γραμματεία ζήτησε να διορθωθεί, γιατί ούτε η άμεση εξυπηρέτηση ούτε η αποδοχή κάθε συσκευής είχαν ανακοινωθεί. Στη νέα εκδοχή οι ενδιαφερόμενοι παραπέμπονται στη φόρμα και στην επικοινωνία με τη γραμματεία για τις εκκρεμείς ερωτήσεις."}, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-008-I11.json", "sha256": "075b4cff5e0674a7382abba175751797d84fe5fa1e9ec53e4c8e109326bec646"}, "error_tags": ["COMPREHENSION", "CONTENT_OMISSION"], "audio_job_ids": [], "competency_ids": ["B2-G08"], "model_response": "Δεν είχε ανακοινωθεί ούτε άμεση εξυπηρέτηση ούτε αποδοχή κάθε συσκευής. Γι’ αυτό το μήνυμα έπρεπε να διορθωθεί.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "reading", "prompt": "По тексту: объясните по-гречески, почему сообщение «όλοι θα εξυπηρετηθούν αμέσως» исправили. Назовите два необоснованных обещания из последнего абзаца.", "skills": ["reading"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-008-I11", "options": [], "qa_risk": "HIGH", "unit_id": "U-B2-008", "version": "0.1.0", "language": "el+ru", "stimulus": {"text": "Το κέντρο της γειτονιάς ανακοίνωσε ότι το εργαστήριο επισκευής μικρών αντικειμένων θα γίνει σε δύο ομάδες. Οι ενδιαφερόμενοι που έχουν ήδη συμπληρώσει τη φόρμα θα λάβουν μήνυμα για την ώρα της συνάντησης. Όσοι δεν έχουν ακόμη δηλώσει συμμετοχή μπορούν να επικοινωνήσουν με τη γραμματεία, αλλά δεν υπάρχει εγγύηση ότι θα βρεθεί διαθέσιμη θέση.\\nΗ υπεύθυνη εξήγησε πως η αλλαγή έγινε επειδή ο χώρος είναι μικρός. Ζήτησε από τους συμμετέχοντες να μην φέρουν μεγάλες ηλεκτρικές συσκευές. Η τεχνίτρια με την οποία συνεργάζεται το κέντρο θα παρουσιάσει απλές επισκευές, ενώ ένας εθελοντής θα καταγράφει τις ερωτήσεις. Η τεχνίτρια, της οποίας η πρόταση αποτέλεσε τη βάση του προγράμματος, τόνισε ότι ο σκοπός δεν είναι να επισκευαστούν όλα τα αντικείμενα μέσα σε μία συνάντηση.\\nΈνα σύντομο μήνυμα στα κοινωνικά δίκτυα έγραφε ότι «όλοι θα εξυπηρετηθούν αμέσως». Η γραμματεία ζήτησε να διορθωθεί, γιατί ούτε η άμεση εξυπηρέτηση ούτε η αποδοχή κάθε συσκευής είχαν ανακοινωθεί. Στη νέα εκδοχή οι ενδιαφερόμενοι παραπέμπονται στη φόρμα και στην επικοινωνία με τη γραμματεία για τις εκκρεμείς ερωτήσεις."}, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Нельзя считать запрет крупных приборов обещанием ремонта всех мелких.", "rubric_id": "U-B2-008-RUBRIC", "error_tags": ["COMPREHENSION", "CONTENT_OMISSION"], "answer_type": "open_response", "source_refs": [{"anchor": "§5.6 lines65–75", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S03", "source_id": "N410", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}, {"anchor": "§5.2α lines18–24", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S04", "source_id": "N404", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}, {"anchor": "§5.2γ lines52–55", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S05", "source_id": "N404", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}], "item_version": "0.1.0", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-G08"], "model_response": "Δεν είχε ανακοινωθεί ούτε άμεση εξυπηρέτηση ούτε αποδοχή κάθε συσκευής. Γι’ αυτό το μήνυμα έπρεπε να διορθωθεί.", "source_claim_ids": ["F07-B2-S03", "F07-B2-S04", "F07-B2-S05"], "success_criteria": ["Не обещана немедленная помощь", "Не объявлен приём любого прибора", "Связь этих фактов с исправлением"], "accepted_variants": [], "canonical_answers": [], "source_provenance": "Original GreekOS teaching task; narrow source claims only", "difficulty_estimate": "B2_AUTHOR_ESTIMATE_NOT_CALIBRATED", "response_evaluation": {"method": "semantic_rubric_with_abstention", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}}, "prerequisite_ids": ["B1-G08", "B1-G09"], "source_claim_ids": ["F07-B2-S03", "F07-B2-S04", "F07-B2-S05"], "accepted_alternatives": []}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
