4861	item	U-B2-008-I15	30b541be48fcc691841c56dee01ac0563e9ee40c4c306c58aa9bc1ef3015e205	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Без модели объясните коллеге 60–90 секунд: «Οι πελάτες που έχουν επιβεβαιωμένο ραντεβού θα λάβουν μήνυμα. Η υπεύθυνη ζήτησε να μην προσέλθουν χωρίς ενημέρωση». Скажите, кого касается сообщение, что попросили сделать и какой вопрос следует уточнить.", "rubric": "U-B2-008-RUBRIC", "item_id": "U-B2-008-I15", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "semantic_rubric_with_abstention", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-008", "version": "0.1.1", "criteria": ["Группа ограничена подтверждённой записью", "Просьба не являться без уведомления сохранена", "Есть релевантный уточняющий вопрос", "Независимая речь; фонетика не оценивается по тексту"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-008-I15.json", "sha256": "1d3472225c9ffb0df8a3acac7e047a92050e83aa23ead7a25850c4fba1e6e86d"}, "error_tags": ["COMPREHENSION", "SPEECH_INTELLIGIBILITY", "ASR_UNCERTAIN"], "audio_job_ids": [], "competency_ids": ["B2-G08"], "model_response": "Το μήνυμα αφορά τους πελάτες που έχουν επιβεβαιωμένο ραντεβού. Η υπεύθυνη τους ζήτησε να μην έρθουν πριν λάβουν ενημέρωση. Χρειάζεται να ρωτήσουμε πότε θα σταλεί το μήνυμα.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "speaking", "prompt": "Без модели объясните коллеге 60–90 секунд: «Οι πελάτες που έχουν επιβεβαιωμένο ραντεβού θα λάβουν μήνυμα. Η υπεύθυνη ζήτησε να μην προσέλθουν χωρίς ενημέρωση». Скажите, кого касается сообщение, что попросили сделать и какой вопрос следует уточнить.", "skills": ["speaking"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-008-I15", "options": [], "qa_risk": "HIGH", "unit_id": "U-B2-008", "version": "0.1.1", "language": "el+ru", "stimulus": null, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Краткая смысловая модель, не требование читать её 60 секунд.", "rubric_id": "U-B2-008-RUBRIC", "error_tags": ["COMPREHENSION", "SPEECH_INTELLIGIBILITY", "ASR_UNCERTAIN"], "answer_type": "open_response", "source_refs": [{"anchor": "§5.6 lines65–75", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S03", "source_id": "N410", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}, {"anchor": "§5.2α lines18–24", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S04", "source_id": "N404", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}, {"anchor": "§5.2γ lines52–55", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S05", "source_id": "N404", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}], "item_version": "0.1.1", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-G08"], "model_response": "Το μήνυμα αφορά τους πελάτες που έχουν επιβεβαιωμένο ραντεβού. Η υπεύθυνη τους ζήτησε να μην έρθουν πριν λάβουν ενημέρωση. Χρειάζεται να ρωτήσουμε πότε θα σταλεί το μήνυμα.", "source_claim_ids": ["F07-B2-S03", "F07-B2-S04", "F07-B2-S05"], "success_criteria": ["Группа ограничена подтверждённой записью", "Просьба не являться без уведо