4889	item	U-B2-010-I10	cbaed0dfb09afec9ad408fd16f199ed8b1548258e951ce1ecc6ccbb8957612b7	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Новая ситуация: библиотека хочет выдавать инструменты бесплатно, но имеет бюджет только на ремонт10предметов в месяц. Напишите100–130слов совету: польза, ограничение, правила доступа, показатель успеха.", "rubric": "U-B2-010-RUBRIC", "item_id": "U-B2-010-I10", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-010", "version": "0.2.0", "criteria": ["польза связана с инициативой", "лимит10ремонтов учтён", "правило доступа", "критерий успеха без выдуманной статистики"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-010-I10.json", "sha256": "f33c2c40e405597774470f5807c8d4df8657ab4e7116a22eed331cbc11cc916b"}, "error_tags": ["CONTENT_OMISSION"], "audio_job_ids": [], "competency_ids": ["B2-V01"], "model_response": "Η δωρεάν διάθεση εργαλείων θα βοηθούσε όσους χρειάζονται ένα εργαλείο μόνο για λίγες ώρες και δεν θέλουν να το αγοράσουν. Ωστόσο, η βιβλιοθήκη μπορεί να χρηματοδοτήσει μόνο δέκα επισκευές τον μήνα. Προτείνω να γίνονται κρατήσεις με σειρά προτεραιότητας και να υπάρχει ένα μικρό χρονικό όριο δανεισμού, ώστε να εξυπηρετούνται περισσότεροι κάτοικοι. Κατά την επιστροφή, ένας υπεύθυνος θα ελέγχει την κατάσταση κάθε εργαλείου. Αν εξαντληθεί ο προϋπολογισμός επισκευών, τα χαλασμένα εργαλεία δεν θα διατίθενται μέχρι να επισκευαστούν. Θα αξιολογούσαμε τη δοκιμή καταγράφοντας τη χρήση, τις βλάβες και τα αιτήματα που δεν εξυπηρετήθηκαν. Έτσι θα ξέραμε αν η υπηρεσία είναι χρήσιμη και αν χρειάζεται διαφορετικούς κανόνες.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "transfer", "prompt": "Новая ситуация: библиотека хочет выдавать инструменты бесплатно, но имеет бюджет только на ремонт10предметов в месяц. Напишите100–130слов совету: польза, ограничение, правила доступа, показатель успеха.", "skills": ["writing"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-010-I10", "options": [], "unit_id": "U-B2-010", "version": "0.2.0", "language": "el+ru", "stimulus": null, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Модель — смысловой ориентир, а не полный ответ нужной длины.", "rubric_id": "U-B2-010-RUBRIC", "error_tags": ["CONTENT_OMISSION"], "answer_type": "open_response", "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-22", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "item_version": "0.2.0", "privacy_risk": "FICTIONAL_DETAILS_ONLY", "review_status": "AUTHOR_RECHECKED_EXTERNAL_PENDING", "competency_ids": ["B2-V01"], "model_response": "Η δωρεάν διάθεση εργαλείων θα βοηθούσε όσους χρειάζονται ένα εργαλείο μόνο για λίγες ώρες και δεν θέλουν να το αγοράσουν. Ωστόσο, η βιβλιοθήκη μπορεί να χρηματοδοτήσει μόνο δέκα επισκευές τον μήνα. Προτείνω να γίνονται κρατήσεις με σειρά προτεραιότητας και να υπάρχει ένα μικρό χρονικό όριο δανεισμού, ώστε να εξυπηρετούνται περισσότεροι κάτοικοι. Κατά την επιστροφή, ένας υπεύθυνος θα ελέγχει την κατάσταση κάθε εργαλείου. Αν εξαντληθεί ο προϋπολογισμός επισκευών, τα χαλασμένα εργαλεία δεν θα διατίθενται μέχρι να επισκευαστούν. Θα αξιολογούσαμε τη δοκιμή καταγράφοντας τη χρήση, τις βλάβες και τα αιτήματα που δεν εξυπηρετήθηκαν. Έτσι θα ξέραμε αν η υπηρεσία είναι χρήσιμη και αν χρειάζεται διαφορετικούς κανόνες.", "error_tag_policy": "Candidate categories, not automatic learner diagnosis; use criterion evidence; never infer pronunciation from uncertain ASR", "estimated_effort": null, "source_claim_ids": ["U-B2-010-SCOPE"], "success_criteria": ["польза связана с инициативой", "лимит10ремонтов учтён", "правило доступа", "критерий успеха без выдуманной статистики"], "target_objective": "Самостоятельно обсуждать общественную инициативу", "accepted_variants": [], "canonical_answers": [], "difficulty_estimate": "UNVALIDATED", "response_evaluation": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "estimated_effort_status": "EDITOR_OR_PILOT_DECISION_REQUIRED"}, "prerequisite_ids": ["B1-V01"], "source_claim_ids": ["U-B2-010-SCOPE"], "accepted_alternatives": []}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
