4959	item	U-B2-016-I10	1e11b840fbd6ce77b65049fd00aaef9ba40207306b01789c91c6a585e5471331	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "D28: доступный зал вмещает 12 человек вместо ожидаемых 24. За 60–90 секунд предложите новый план и вывод. Если заметите собственную значимую неточность, исправьте её и продолжите. Если неточности нет, не создавайте ошибку: партнёр после первого плана сообщает, что начало перенесено с 18:00 на 19:00; обновите сообщение. Партнёр затем восстанавливает окончательный план.", "rubric": "U-B2-016-RUBRIC", "item_id": "U-B2-016-I10", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-016", "version": "0.2.0", "criteria": ["ограничение 12 вместо 24 учтено", "собственная поправка или обновление времени ясно отделены от исходного плана", "связный вывод", "слушатель восстановил окончательный план"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-016-I10.json", "sha256": "020503c9e7b24f4ed32661474df00c496f6493e824bd977d14ef673c95e499f1"}, "error_tags": ["PRONUNCIATION_CANDIDATE"], "audio_job_ids": [], "competency_ids": ["B2-P01"], "model_response": "Η αίθουσα χωρά δώδεκα άτομα, ενώ περιμέναμε είκοσι τέσσερα. Προτείνω δύο μικρότερες ομάδες, αν μπορούμε να χρησιμοποιήσουμε τον χώρο δύο φορές. Μόλις έμαθα ότι η πρώτη συνάντηση θα αρχίσει στις επτά, όχι στις έξι. Ας ελέγξουμε αν προλαβαίνουμε και τη δεύτερη ομάδα.", "requires_audio": true, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "D28", "prompt": "D28: доступный зал вмещает 12 человек вместо ожидаемых 24. За 60–90 секунд предложите новый план и вывод. Если заметите собственную значимую неточность, исправьте её и продолжите. Если неточности нет, не создавайте ошибку: партнёр после первого плана сообщает, что начало перенесено с 18:00 на 19:00; обновите сообщение. Партнёр затем восстанавливает окончательный план.", "skills": ["speaking"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-016-I10", "options": [], "unit_id": "U-B2-016", "version": "0.2.0", "language": "el+ru", "stimulus": null, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Не штрафовать отсутствие ошибки. Самокоррекция и обновление после новой информации — разные наблюдения; второе не доказывает спонтанное обнаружение собственной ошибки.", "rubric_id": "U-B2-016-RUBRIC", "error_tags": ["PRONUNCIATION_CANDIDATE"], "answer_type": "open_response", "source_refs": [{"anchor": "§2.3 suprasegmentals, stress, pause and rhythm; §2.2 connected speech", "source_id": "CP08-PHON", "checked_on": "2026-10-22", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "audio_status": "LEARNER_RECORDING_REQUIRED", "item_version": "0.2.0", "privacy_risk": "FICTIONAL_DETAILS_ONLY", "review_status": "AUTHOR_RECHECKED_EXTERNAL_PENDING", "audio_required": true, "competency_ids": ["B2-P01"], "model_response": "Η αίθουσα χωρά δώδεκα άτομα, ενώ περιμέναμε είκοσι τέσσερα. Προτείνω δύο μικρότερες ομάδες, αν μπορούμε να χρησιμοποιήσουμε τον χώρο δύο φορές. Μόλις έμαθα ότι η πρώτη συνάντηση θα αρχίσει στις επτά, όχι στις έξι. Ας ελέγξουμε αν προλαβαίνουμε και τη δεύτερη ομάδα.", "error_tag_policy": "Candidate categories, not automatic learner diagnosis; use criterion evidence; never infer pronunciation from uncertain ASR", "estimated_effort": null, "source_claim_ids": ["U-B2-016-SCOPE"], "success_criteria": ["ограничение 12 вместо 24 учтено", "собственная поправка или обновление времени ясно отделены от исходного плана", "связный вывод", "слушатель восстановил окончательный план"], "target_objective": "Самостоятельно исправлять значимую ошибку без разрушения речи", "accepted_variants": [], "canonical_answers": [], "scoring_constraint": "No acoustic score from text or ASR alone; transcription may support content-only feedback", "difficulty_estimate": "UNVALIDATED", "response_evaluation": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "estimated_effort_status": "EDITOR_OR_PILOT_DECISION_REQUIRED"}, "prerequisite_ids": ["B1-P01", "B2-SP01"], "source_claim_ids": ["U-B2-016-SCOPE"], "accepted_alternatives": []}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
4960	item	U-B2-017-I01	cbc0a708ec87b74e1b5569cca6d60f4aed740f6ba2dae192c2d198a70a2eb8e8	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Διάβασε: «Η δοκιμή φαίνεται χρήσιμη, εφόσον υπάρχει προσωπικό». Τι υποστηρίζεται και τι δεν εγγυάται ο συντάκτης;", "rubric": "U-B2-017-RUBRIC", "item_id": "U-B2-017-I01", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-017", "version": "0.1.0", "criteria": ["условие сохранено", "отсутствие гарантии указано"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-017-I01.json", "sha256": "44c2011b69503118c22e1b00816b049b6b68e2d3c51673f6da80880889f334b7"}, "error_tags": ["CONDITION_LOSS_CANDIDATE"], "audio_job_ids": [], "competency_ids": ["B2-R01"], "model_response": "Υποστηρίζεται μια δοκιμή υπό τον όρο ότι υπάρχει προσωπικό. Δεν εγγυάται την επιτυχία της.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "diagnostic", "prompt": "Διάβασε: «Η δοκιμή φαίνεται χρήσιμη, εφόσον υπάρχει προσωπικό». Τι υποστηρίζεται και τι δεν εγγυάται ο συντάκτης;", "skills": ["reading"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-017-I01", "options": [], "unit_id": "U-B2-017", "version": "0.1.0", "language": "el+ru", "stimulus": null, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Η επιφύλαξη δεν είναι απόρριψη ούτε εγγύηση.", "rubric_id": "U-B2-017-RUBRIC", "error_tags": ["CONDITION_LOSS_CANDIDATE"], "answer_type": "open_response", "publishable": false, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "item_version": "0.1.0", "privacy_risk": "FICTIONAL_DETAILS_ONLY", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-R01"], "model_response": "Υποστηρίζεται μια δοκιμή υπό τον όρο ότι υπάρχει προσωπικό. Δεν εγγυάται την επιτυχία της.", "error_tag_policy": "Item-specific author hypothesis; actual learner error requires quoted response evidence and human/assessor decision. ASR uncertainty excluded.", "estimated_effort": null, "source_claim_ids": ["U-B2-017-SCOPE"], "success_criteria": ["условие сохранено", "отсутствие гарантии указано"], "target_objective": "Различать позицию, аргумент, ограничение и недоказанный вывод", "accepted_variants": [], "canonical_answers": [], "difficulty_estimate": "UNVALIDATED", "response_evaluation": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "estimated_effort_status": "EDITOR_OR_PILOT_DECISION_REQUIRED"}, "prerequisite_ids": ["B1-R01", "B2-G08"], "source_claim_ids": ["U-B2-017-SCOPE"], "accepted_alternatives": []}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
4961	item	U-B2-017-I02	07819e42965d6554e24b429ba6bb9306f7460f39a96fbe4b1e2d9f6ae84d91f3	core	{"type": "mcq", "level": "B2", "answer": ["Να δοκιμαστεί το ωράριο με όρους και αξιολόγηση."], "module": "core", "prompt": "Ποια είναι η βασική θέση του άρθρου;", "rubric": null, "item_id": "U-B2-017-I02", "options": ["Να δοκιμαστεί το ωράριο με όρους και αξιολόγηση.", "Να παραταθεί αμέσως το ωράριο όλων των βιβλιοθηκών.", "Να καταργηθεί κάθε βραδινή λειτουργία.", "Να αντικατασταθεί ο δανεισμός με ψηφιακές υπηρεσίες."], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_semantic_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "CHOICE_KEY", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-017", "version": "0.1.0", "criteria": [], "stimulus": "Μια βιβλιοθήκη που μένει ανοιχτή\\n[1] Όταν ανακοινώθηκε ότι η βιβλιοθήκη της γειτονιάς θα λειτουργούσε δύο βράδια την εβδομάδα, αρκετοί κάτοικοι μίλησαν για περιττή δαπάνη. Κατά τη γνώμη τους, όποιος θέλει να δανειστεί ένα βιβλίο μπορεί να το κάνει το πρωί. Η άποψη αυτή, όμως, θεωρεί δεδομένο ότι όλοι διαθέτουν τον ίδιο ελεύθερο χρόνο. Για έναν εργαζόμενο με σπαστό ωράριο ή για έναν γονέα που φροντίζει μικρά παιδιά, η πρωινή πρόσβαση συχνά υπάρχει μόνο στα χαρτιά.\\n[2] Η πρόταση δεν προβλέπει απλώς περισσότερο χρόνο δανεισμού. Προβλέπει έναν ήσυχο χώρο μελέτης και υποστήριξη για όσους δυσκολεύονται να αναζητήσουν πληροφορίες στο διαδίκτυο. Δεν σημαίνει ότι οι υπάλληλοι θα συμπληρώνουν προσωπικές αιτήσεις αντί των επισκεπτών. Θα τους δείχνουν πώς να εντοπίζουν μια αξιόπιστη πηγή και πώς να αποφεύγουν την κοινοποίηση προσωπικών δεδομένων. Έτσι, η βιβλιοθήκη θα μπορούσε να καλύψει ανάγκες που δεν αντιμετωπίζονται με έναν απλό δανεισμό.\\n[3] Υπάρχουν, βέβαια, βάσιμες αντιρρήσεις. Το επιπλέον ωράριο απαιτεί προσωπικό, θέρμανση και ασφαλή επιστροφή των εργαζομένων. Αν στηριχθεί αποκλειστικά σε απλήρωτη εθελοντική εργασία, δύσκολα θα διατηρηθεί. Ούτε αρκεί να μετρηθεί ο αριθμός των επισκεπτών την πρώτη εβδομάδα: μια εκδήλωση εγκαινίων μπορεί να γεμίσει τον χώρο χωρίς να αποδεικνύει σταθερή ανάγκη. Χρειάζονται στοιχεία για επαναλαμβανόμενες επισκέψεις, για τις υπηρεσίες που χρησιμοποιούνται και για ανθρώπους που εξακολουθούν να αποκλείονται.\\n[4] Γι’ αυτό προτείνουμε μια τρίμηνη δοκιμή, με εξασφαλισμένη αμοιβή του προσωπικού και δημόσια αξιολόγηση. Οι κάτοικοι θα μπορούν να προτείνουν διαφορετικές ημέρες, χωρίς να αναμένεται ότι μία λύση θα εξυπηρετεί τους πάντες. Αν διαπιστωθεί μικρή προσέλευση, πρέπει πρώτα να εξεταστούν η ενημέρωση και η συγκοινωνιακή σύνδεση, προτού κριθεί αποτυχημένο το μέτρο. Αντίστοιχα, η μεγάλη προσέλευση δεν δικαιολογεί από μόνη της οποιοδήποτε κόστος.\\n[5] Η βιβλιοθήκη δεν μπορεί να λύσει όλα τα προβλήματα της γειτονιάς. Μπορεί, ωστόσο, να δοκιμάσει έναν πιο δίκαιο τρόπο πρόσβασης στη γνώση. Το ερώτημα δεν είναι αν ένα βραδινό ωράριο είναι πάντοτε καλό ή κακό, αλλά υπό ποιες προϋποθέσεις προσφέρει ουσιαστικό όφελος. Η υπεύθυνη απόφαση χρειάζεται και κοινωνικό στόχο και ειλικρινή αποτίμηση των περιορισμών της.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-017-I02.json", "sha256": "4fd3b3dacc8202b50db3b4c95b22c075555e2ecb3098047b8f2972fd5dcf4006"}, "error_tags": ["AUTHOR_STANCE_CANDIDATE"], "audio_job_ids": [], "competency_ids": ["B2-R01"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "guided", "prompt": "Ποια είναι η βασική θέση του άρθρου;", "skills": ["reading"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-017-I02", "options": ["Να δοκιμαστεί το ωράριο με όρους και αξιολόγηση.", "Να παραταθεί αμέσως το ωράριο όλων των βιβλιοθηκών.", "Να καταργηθεί κάθε βραδινή λειτουργία.", "Να αντικατασταθεί ο δανεισμός με ψηφιακές υπηρεσίες."], "unit_id": "U-B2-017", "version": "0.1.0", "language": "el+ru", "stimulus": "Μια βιβλιοθήκη που μένει ανοιχτή\\n[1] Όταν ανακοινώθηκε ότι η βιβλιοθήκη της γειτονιάς θα λειτουργούσε δύο βράδια την εβδομάδα, αρκετοί κάτοικοι μίλησαν για περιττή δαπάνη. Κατά τη γνώμη τους, όποιος θέλει να δανειστεί ένα βιβλίο μπορεί να το κάνει το πρωί. Η άποψη αυτή, όμως, θεωρεί δεδομένο ότι όλοι διαθέτουν τον ίδιο ελεύθερο χρόνο. Για έναν εργαζόμενο με σπαστό ωράριο ή για έναν γονέα που φροντίζει μικρά παιδιά, η πρωινή πρόσβαση συχνά υπάρχει μόνο στα χαρτιά.\\n[2] Η πρόταση δεν προβλέπει απλώς περισσότερο χρόνο δανεισμού. Προβλέπει έναν ήσυχο χώρο μελέτης και υποστήριξη για όσους δυσκολεύονται να αναζητήσουν πληροφορίες στο διαδίκτυο. Δεν σημαίνει ότι οι υπάλληλοι θα συμπληρώνουν προσωπικές αιτήσεις αντί των επισκεπτών. Θα τους δείχνουν πώς να εντοπίζουν μια αξιόπιστη πηγή και πώς να αποφεύγουν την κοινοποίηση προσωπικών δεδομένων. Έτσι, η βιβλιοθήκη θα μπορούσε να καλύψει ανάγκες που δεν αντιμετωπίζονται με έναν απλό δανεισμό.\\n[3] Υπάρχουν, βέβαια, βάσιμες αντιρρήσεις. Το επιπλέον ωράριο απαιτεί προσωπικό, θέρμανση και ασφαλή επιστροφή των εργαζομένων. Αν στηριχθεί αποκλειστικά σε απλήρωτη εθελοντική εργασία, δύσκολα θα διατηρηθεί. Ούτε αρκεί να μετρηθεί ο αριθμός των επισκεπτών την πρώτη εβδομάδα: μια εκδήλωση εγκαινίων μπορεί να γεμίσει τον χώρο χωρίς να αποδεικνύει σταθερή ανάγκη. Χρειάζονται στοιχεία για επαναλαμβανόμενες επισκέψεις, για τις υπηρεσίες που χρησιμοποιούνται και για ανθρώπους που εξακολουθούν να αποκλείονται.\\n[4] Γι’ αυτό προτείνουμε μια τρίμηνη δοκιμή, με εξασφαλισμένη αμοιβή του προσωπικού και δημόσια αξιολόγηση. Οι κάτοικοι θα μπορούν να προτείνουν διαφορετικές ημέρες, χωρίς να αναμένεται ότι μία λύση θα εξυπηρετεί τους πάντες. Αν διαπιστωθεί μικρή προσέλευση, πρέπει πρώτα να εξεταστούν η ενημέρωση και η συγκοινωνιακή σύνδεση, προτού κριθεί αποτυχημένο το μέτρο. Αντίστοιχα, η μεγάλη προσέλευση δεν δικαιολογεί από μόνη της οποιοδήποτε κόστος.\\n[5] Η βιβλιοθήκη δεν μπορεί να λύσει όλα τα προβλήματα της γειτονιάς. Μπορεί, ωστόσο, να δοκιμάσει έναν πιο δίκαιο τρόπο πρόσβασης στη γνώση. Το ερώτημα δεν είναι αν ένα βραδινό ωράριο είναι πάντοτε καλό ή κακό, αλλά υπό ποιες προϋποθέσεις προσφέρει ουσιαστικό όφελος. Η υπεύθυνη απόφαση χρειάζεται και κοινωνικό στόχο και ειλικρινή αποτίμηση των περιορισμών της.", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Το συμπέρασμα της §5 συνδυάζεται με την πρόταση της §4. Η καθολική επέκταση, η απόρριψη και ο αποκλειστικά ψηφιακός στόχος δεν υποστηρίζονται.", "error_tags": ["AUTHOR_STANCE_CANDIDATE"], "answer_type": "mcq", "publishable": false, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "item_version": "0.1.0", "privacy_risk": "FICTIONAL_DETAILS_ONLY", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-R01"], "error_tag_policy": "Item-specific author hypothesis; actual learner error requires quoted response evidence and human/assessor decision. ASR uncertainty excluded.", "estimated_effort": null, "source_claim_ids": ["U-B2-017-SCOPE"], "target_objective": "Различать позицию, аргумент, ограничение и недоказанный вывод", "accepted_variants": [], "canonical_answers": ["Να δοκιμαστεί το ωράριο 