, "audio_job_ids": [], "competency_ids": ["B2-R01"], "model_response": "Επικοινωνώ με τη γραμματεία και δεν στέλνω δεύτερο ίδιο αίτημα. Δεν θεωρώ ότι η κράτηση έχει εγκριθεί.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "guided", "prompt": "Έστειλες αίτημα και δύο εργάσιμες ημέρες πέρασαν χωρίς απάντηση. Γράψε τι κάνεις και τι αποφεύγεις.", "skills": ["writing"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-017-I07", "options": [], "unit_id": "U-B2-017", "version": "0.1.0", "language": "el+ru", "stimulus": "Οδηγίες κράτησης αίθουσας — υποθετική βιβλιοθήκη\\nΑ. Ελέγξτε πρώτα το ημερολόγιο διαθεσιμότητας. Η ένδειξη «ελεύθερη» δεν ισοδυναμεί με κράτηση.\\nΒ. Υποβάλετε αίτημα τουλάχιστον πέντε εργάσιμες ημέρες πριν από τη συνάντηση, αναφέροντας σκοπό, αριθμό ατόμων και ανάγκες πρόσβασης. Η αποστολή του αιτήματος δεν αποτελεί έγκριση.\\nΓ. Περιμένετε γραπτή επιβεβαίωση. Αν δεν λάβετε απάντηση μέσα σε δύο εργάσιμες ημέρες, επικοινωνήστε με τη γραμματεία· μην υποβάλετε δεύτερο πανομοιότυπο αίτημα.\\nΔ. Αν η συνάντηση ακυρωθεί, ενημερώστε τη γραμματεία αμέσως. Για αλλαγή ώρας απαιτείται νέα επιβεβαίωση. Μην ανακοινώσετε αλλαγή στους συμμετέχοντες ως οριστική πριν εγκριθεί.\\nΕ. Αφήστε τις εξόδους ελεύθερες και αποχωρήστε στην επιβεβαιωμένη ώρα, συμπεριλαμβάνοντας στον χρόνο σας την τακτοποίηση του χώρου.", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Ελέγχεται πραγματική εκτέλεση της οδηγίας, όχι απομνημόνευση όρων.", "rubric_id": "U-B2-017-RUBRIC", "error_tags": ["PROCEDURE_SEQUENCE_CANDIDATE"], "answer_type": "open_response", "publishable": false, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "item_version": "0.1.0", "privacy_risk": "FICTIONAL_DETAILS_ONLY", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-R01"], "model_response": "Επικοινωνώ με τη γραμματεία και δεν στέλνω δεύτερο ίδιο αίτημα. Δεν θεωρώ ότι η κράτηση έχει εγκριθεί.", "error_tag_policy": "Item-specific author hypothesis; actual learner error requires quoted response evidence and human/assessor decision. ASR uncertainty excluded.", "estimated_effort": null, "source_claim_ids": ["U-B2-017-SCOPE"], "success_criteria": ["связаться с секретариатом", "не дублировать запрос", "не считать бронь одобренной"], "target_objective": "Извлекать условие и последовательность из подробной инструкции", "accepted_variants": [], "canonical_answers": [], "difficulty_estimate": "UNVALIDATED", "response_evaluation": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "estimated_effort_status": "EDITOR_OR_PILOT_DECISION_REQUIRED"}, "prerequisite_ids": ["B1-R01", "B2-G08"], "source_claim_ids": ["U-B2-017-SCOPE"], "accepted_alternatives": []}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
4967	item	U-B2-017-I08	288eb1a1761dbf586ad25525b4062dca118c53b079b741ac3eacef4ee42f1406	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Χωρίς να αντιγράψεις προτάσεις, γράψε 140–180 λέξεις: σύστησε ή απόρριψε τη δοκιμή της βιβλιοθήκης. Χρησιμοποίησε δύο επιχειρήματα του άρθρου, μία επιφύλαξη και δικό σου σαφώς σημειωμένο κριτήριο.", "rubric": "U-B2-017-RUBRIC", "item_id": "U-B2-017-I08", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-017", "version": "0.1.0", "criteria": ["два точных аргумента", "оговорка", "собственный критерий отделён", "связное самостоятельное обоснование", "140–180 слов как редакторский ориентир"], "stimulus": "Μια βιβλιοθήκη που μένει ανοιχτή\\n[1] Όταν ανακοινώθηκε ότι η βιβλιοθήκη της γειτονιάς θα λειτουργούσε δύο βράδια την εβδομάδα, αρκετοί κάτοικοι μίλησαν για περιττή δαπάνη. Κατά τη γνώμη τους, όποιος θέλει να δανειστεί ένα βιβλίο μπορεί να το κάνει το πρωί. Η άποψη αυτή, όμως, θεωρεί δεδομένο ότι όλοι διαθέτουν τον ίδιο ελεύθερο χρόνο. Για έναν εργαζόμενο με σπαστό ωράριο ή για έναν γονέα που φροντίζει μικρά παιδιά, η πρωινή πρόσβαση συχνά υπάρχει μόνο στα χαρτιά.\\n[2] Η πρόταση δεν προβλέπει απλώς περισσότερο χρόνο δανεισμού. Προβλέπει έναν ήσυχο χώρο μελέτης και υποστήριξη για όσους δυσκολεύονται να αναζητήσουν πληροφορίες στο διαδίκτυο. Δεν σημαίνει ότι οι υπάλληλοι θα συμπληρώνουν προσωπικές αιτήσεις αντί των επισκεπτών. Θα τους δείχνουν πώς να εντοπίζουν μια αξιόπιστη πηγή και πώς να αποφεύγουν την κοινοποίηση προσωπικών δεδομένων. Έτσι, η βιβλιοθήκη θα μπορούσε να καλύψει ανάγκες που δεν αντιμετωπίζονται με έναν απλό δανεισμό.\\n[3] Υπάρχουν, βέβαια, βάσιμες αντιρρήσεις. Το επιπλέον ωράριο απαιτεί προσωπικό, θέρμανση και ασφαλή επιστροφή των εργαζομένων. Αν στηριχθεί αποκλειστικά σε απλήρωτη εθελοντική εργασία, δύσκολα θα διατηρηθεί. Ούτε αρκεί να μετρηθεί ο αριθμός των επισκεπτών την πρώτη εβδομάδα: μια εκδήλωση εγκαινίων μπορεί να γεμίσει τον χώρο χωρίς να αποδεικνύει σταθερή ανάγκη. Χρειάζονται στοιχεία για επαναλαμβανόμενες επισκέψεις, για τις υπηρεσίες που χρησιμοποιούνται και για ανθρώπους που εξακολουθούν να αποκλείονται.\\n[4] Γι’ αυτό προτείνουμε μια τρίμηνη δοκιμή, με εξασφαλισμένη αμοιβή του προσωπικού και δημόσια αξιολόγηση. Οι κάτοικοι θα μπορούν να προτείνουν διαφορετικές ημέρες, χωρίς να αναμένεται ότι μία λύση θα εξυπηρετεί τους πάντες. Αν διαπιστωθεί μικρή προσέλευση, πρέπει πρώτα να εξεταστούν η ενημέρωση και η συγκοινωνιακή σύνδεση, προτού κριθεί αποτυχημένο το μέτρο. Αντίστοιχα, η μεγάλη προσέλευση δεν δικαιολογεί από μόνη της οποιοδήποτε κόστος.\\n[5] Η βιβλιοθήκη δεν μπορεί να λύσει όλα τα προβλήματα της γειτονιάς. Μπορεί, ωστόσο, να δοκιμάσει έναν πιο δίκαιο τρόπο πρόσβασης στη γνώση. Το ερώτημα δεν είναι αν ένα βραδινό ωράριο είναι πάντοτε καλό ή κακό, αλλά υπό ποιες προϋποθέσεις προσφέρει ουσιαστικό όφελος. Η υπεύθυνη απόφαση χρειάζεται και κοινωνικό στόχο και ειλικρινή αποτίμηση των περιορισμών της.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-017-I08.json", "sha256": "80e830fd9de90abb68b64eaccc929e3a28f1bbb3497d719b36b7f986e8edb82c"}, "error_tags": ["ARGUMENT_SOURCE_BOUNDARY_CANDIDATE"], "audio_job_ids": [], "competency_ids": ["B2-R01"], "model_response": "Ενδεικτικός πυρήνας: Θα υποστήριζα τη δοκιμή, επειδή διευκολύνει όσους εργάζονται το πρωί. Θα ζητούσα, ωστόσο, σταθερή χρηματοδότηση και αξιολόγηση. Ως πρόσθετο δικό μου κριτήριο προτείνω ανώνυμη καταγραφή ανικανοποίητων αναγκών.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "independent", "prompt": "Χωρίς να αντιγράψεις προτάσεις, γράψε 140–180 λέξεις: σύστησε ή απόρριψε τη δοκιμή της βιβλιοθήκης. Χρησιμοποίησε δύο επιχειρήματα του άρθρου, μία επιφύλαξη και δικό σου σαφώς σημειωμένο κριτήριο.", "skills": ["writing"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-017-I08", "options": [], "unit_id": "U-B2-017", "version": "0.1.0", "language": "el+ru", "stimulus": "Μια βιβλιοθήκη που μένει ανοιχτή\\n[1] Όταν ανακοινώθηκε ότι η βιβλιοθήκη της γειτονιάς θα λειτουργούσε δύο βράδια την εβδομάδα, αρκετοί κάτοικοι μίλησαν για περιττή δαπάνη. Κατά τη γνώμη τους, όποιος θέλει να δανειστεί ένα βιβλίο μπορεί να το κάνει το πρωί. Η άποψη αυτή, όμως, θεωρεί δεδομένο ότι όλοι διαθέτουν τον ίδιο ελεύθερο χρόνο. Για έναν εργαζόμενο με σπαστό ωράριο ή για έναν γονέα που φροντίζει μικρά παιδιά, η πρωινή πρόσβαση συχνά υπάρχει μόνο στα χαρτιά.\\n[2] Η πρόταση δεν προβλέπει απλώς περισσότερο χρόνο δανεισμού. Προβλέπει έναν ήσυχο χώρο μελέτης και υποστήριξη για όσους δυσκολεύονται να αναζητήσουν πληροφορίες στο διαδίκτυο. Δεν σημαίνει ότι οι υπάλληλοι θα συμπληρώνουν προσωπικές αιτήσεις αντί των επισκεπτών. Θα τους δείχνουν πώς να εντοπίζουν μια αξιόπιστη πηγή και πώς να αποφεύγουν την κοινοποίηση προσωπικών δεδομένων. Έτσι, η βιβλιοθήκη θα μπορούσε να καλύψει ανάγκες που δεν αντιμετωπίζονται με έναν απλό δανεισμό.\\n[3] Υπάρχουν, βέβαια, βάσιμες αντιρρήσεις. Το επιπλέον ωράριο απαιτεί προσωπικό, θέρμανση και ασφαλή επιστροφή των εργαζομένων. Αν στηριχθεί αποκλειστικά σε απλήρωτη εθελοντική εργασία, δύσκολα θα διατηρηθεί. Ούτε αρκεί να μετρηθεί ο αριθμός των επισκεπτών την πρώτη εβδομάδα: μια εκδήλωση εγκαινίων μπορεί να γεμίσει τον χώρο χωρίς να αποδεικνύει σταθερή ανάγκη. Χρειάζονται στοιχεία για επαναλαμβανόμενες επισκέψεις, για τις υπηρεσίες που χρησιμοποιούνται και για ανθρώπους που εξακολουθούν να αποκλείονται.\\n[4] Γι’ αυτό προτείνουμε μια τρίμηνη δοκιμή, με εξασφαλισμένη αμοιβή του προσωπικού και δημόσια αξιολόγηση. Οι κάτοικοι θα μπορούν να προτείνουν διαφορετικές ημέρες, χωρίς να αναμένεται ότι μία λύση θα εξυπηρετεί τους πάντες. Αν διαπιστωθεί μικρή προσέλευση, πρέπει πρώτα να εξεταστούν η ενημέρωση και η συγκοινωνιακή σύνδεση, προτού κριθεί αποτυχημένο το μέτρο. Αντίστοιχα, η μεγάλη προσέλευση δεν δικαιολογεί από μόνη της οποιοδήποτε κόστος.\\n[5] Η βιβλιοθήκη δεν μπορεί να λύσει όλα τα προβλήματα της γειτονιάς. Μπορεί, ωστόσο, να δοκιμάσει έναν πιο δίκαιο τρόπο πρόσβασης στη γνώση. Το ερώτημα δεν είναι αν ένα βραδινό ωράριο είναι πάντοτε καλό ή κακό, αλλά υπό ποιες προϋποθέσεις προσφέρει ουσιαστικό όφελος. Η υπεύθυνη απόφαση χρειάζεται και κοινωνικό στόχο και ειλικρινή αποτίμηση των περιορισμών της.", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Модель — каркас, не полный ответ нужной длины. Личная рекомендация может отличаться, если факты переданы верно.", "rubric_id": "U-B2-017-RUBRIC", "error_tags": ["ARGUMENT_SOURCE_BOUNDARY_CANDIDATE"], "answer_type": "open_response", "publishable": false, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "item_version": "0.1.0", "privacy_risk": "FICTIONAL_DETAILS_ONLY", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-R01"], "model_response": "Ενδεικτικός πυρήνας: Θα υποστήριζα τη δοκιμή, επειδή διευκολύνει όσους εργάζονται το πρωί. Θα ζητούσα, ωστόσο, σταθερή χρηματοδότηση και αξιολόγηση. Ως πρόσθετο δικό μου κριτήριο προτείνω ανώνυμη καταγραφή ανικανοποίητων αναγκών.", "error_tag_policy": "Item-specific author hypothesis; actual learner error requires quoted response evidence and human/assessor decision. ASR uncertainty excluded.", "estimated_effort": null, "source_claim_ids": ["U-B2-017-SCOPE"], "success_criteria": ["два точных аргумента", "оговорка", "собственный критерий отделён", "связное самостоятельное обоснование", "140–180 слов как редакторский ориентир"], "target_objective": "Самостоятельно обосновывать действие по новому письменному источнику", "accepted_variants": [], "canonical_answers": [], "difficulty_estimate": "UNVALIDATED", "response_evaluation": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "estimated_effort_status": "EDITOR_OR_PILOT_DECISION_REQUIRED"}, "prerequisite_ids": ["B1-R01", "B2-G08"], "source_claim_ids": ["U-B2-017-SCOPE"], "accepted_alternatives": []}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
4968	item	U-B2-017-I09	9c27188f2a54413923f8f1fa069a376a48dc915cd5b21ff95378c864d88c6f4b	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Εξήγησε προφορικά σε συνεργάτη τη διαδικασία κράτησης, σε 90–120 δευτερόλεπτα. Εκείνος ρωτά: «Η αίθουσα φαίνεται ελεύθερη· να στείλω προσκλήσεις;» Απάντησε χωρίς να διαβάζεις τις οδηγίες.", "rubric": "U-B2-017-RUBRIC", "item_id": "U-B2-017-I09", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-017", "version": "0.1.0", "criteria": ["διακρίνει διαθεσιμότητα από έγκριση", "καλύπτει προθεσμία και αλλαγές", "ανταποκρίνεται στη διευκρίνιση"], "stimulus": "Οδηγίες κράτησης αίθουσας — υποθετική βιβλιοθήκη\\nΑ. Ελέγξτε πρώτα το ημερολόγιο διαθεσιμότητας. Η ένδειξη «ελεύθερη» δεν ισοδυναμεί με κράτηση.\\nΒ. Υποβάλετε αίτημα τουλάχιστον πέντε εργάσιμες ημέρες πριν από τη συνάντηση, αναφέροντας σκοπό, αριθμό ατόμων και ανάγκες πρόσβασης. Η αποστολή του αιτήματος δεν αποτελεί έγκριση.\\nΓ. Περιμένετε γραπτή επιβεβαίωση. Αν δεν λάβετε απάντηση μέσα σε δύο εργάσιμες ημέρες, επικοινωνήστε με τη γραμματεία· μην υποβάλετε δεύτερο πανομοιότυπο αίτημα.\\nΔ. Αν η συνάντηση ακυρωθεί, ενημερώστε τη γραμματεία αμέσως. Για αλλαγή ώρας απαιτείται νέα επιβεβαίωση. Μην ανακοινώσετε αλλαγή στους συμμετέχοντες ως οριστική πριν εγκριθεί.\\nΕ. Αφήστε τις εξόδους ελεύθερες και αποχωρήστε στην επιβεβαιωμένη ώρα, συμπεριλαμβάνοντας στον χρόνο σας την τακτοποίηση του χώρου.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-017-I09.json", "sha256": "0ac554d2b8137ea3173e853472bd2d7c53af16f154dd82235e78bb24bdeacaf9"}, "error_tags": ["INSTRUCTION_TRANSFER_CANDIDATE"], "audio_job_ids": [], "competency_ids": ["B2-R01"], "model_response": "Πρέπει πρώτα να ζητήσουμε και να λάβουμε επιβεβαίωση. Η διαθεσιμότητα από μόνη της δεν αποτελεί κράτηση.", "requires_audio": true, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "independent", "prompt": "Εξήγησε προφορικά σε συνεργάτη τη διαδικασία κράτησης, σε 90–120 δευτερόλεπτα. Εκείνος ρωτά: «Η αίθουσα φαίνεται ελεύθερη· να στείλω προσκλήσεις;» Απάντησε χωρίς να διαβάζεις τις οδηγίες.", "skills": ["speaking"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-017-I09", "options": [], "unit_id": "U-B2-017", "version": "0.1.0", "language": "el+ru", "stimulus": "Οδηγίες κράτησης αίθουσας — υποθετική βιβλιοθήκη\\nΑ. Ελέγξτε πρώτα το ημερολόγιο διαθεσιμότητας. Η ένδειξη «ελεύθερη» δεν ισοδυναμεί με κράτηση.\\nΒ. Υποβάλετε αίτημα τουλάχιστον πέντε εργάσιμες ημέρες πριν από τη συνάντηση, αναφέροντας σκοπό, αριθμό ατόμων και ανάγκες πρόσβασης. Η αποστολή του αιτήματος δεν αποτελεί έγκριση.\\nΓ. Περιμένετε γραπτή επιβεβαίωση. Αν δεν λάβετε απάντηση μέσα σε δύο εργάσιμες ημέρες, επικοινωνήστε με τη γραμματεία· μην υποβάλετε δεύτερο πανομοιότυπο αίτημα.\\nΔ. Αν η συνάντηση ακυρωθεί, ενημερώστε τη γραμματεία αμέσως. Για αλλαγή ώρας απαιτείται νέα επιβεβαίωση. Μην ανακοινώσετε αλλαγή στους συμμετέχοντες ως οριστική πριν εγκριθεί.\\nΕ. Αφήστε τις εξόδους ελεύθερες και αποχωρήστε στην επιβεβαιωμένη ώρα, συμπεριλαμβάνοντας στον χρόνο σας την τακτοποίηση του χώρου.", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Το κλειδί αφορά τη διαδικασία· η προφορά απαιτεί πραγματική ηχογράφηση.", "rubric_id": "U-B2-017-RUBRIC", "error_tags": ["INSTRUCTION_TRANSFER_CANDIDATE"], "answer_type": "open_response", "publishable": false, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "audio_status": "LEARNER_RECORDING_REQUIRED", "item_version": "0.1.0", "privacy_risk": "FICTIONAL_DETAILS_ONLY", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "audio_required": true, "competency_ids": ["B2-R01"], "model_response": "Πρέπει πρώτα να ζητήσουμε και να λάβουμε επιβεβαίωση. Η διαθεσιμότητα από μόνη της δεν αποτελεί κράτηση.", "error_tag_policy": "Item-specific author hypothesis; actual learner error requires quoted response evidence and human/assessor decision. ASR uncertainty excluded.", "estimated_effort": null, "source_claim_ids": ["U-B2-017-SCOPE"], "success_criteria": ["διακρίνει διαθεσιμότητα από έγκριση", "καλύπτει προθεσμία και αλλαγές", "ανταποκρίνεται στη διευκρίνιση"], "target_objective": "Самостоятельно обосновывать действие по новому письменному источнику", "accepted_variants": [], "canonical_answers": [], "scoring_constraint": "No acoustic score from text or ASR alone; transcription may support content-only feedback", "difficulty_estimate": "UNVALIDATED", "response_evaluation": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "estimated_effort_status": "EDITOR_OR_PILOT_DECISION_REQUIRED"}, "prerequisite_ids": ["B1-R01", "B2-G08"], "source_claim_ids": ["U-B2-017-SCOPE"], "accepted_alt