4969	item	U-B2-017-I10	55027aea786f1ada5130c7bcc2b6d87c8a60432e74aec2adf859ec5cc2fb4e92	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Νέος κανονισμός: «Οι ομάδες χρησιμοποιούν τον κήπο μετά τις 17:00, εφόσον υπάρχει υπεύθυνος. Αν βρέχει, η εκδήλωση ακυρώνεται· δεν μεταφέρεται αυτόματα μέσα». Η ομάδα σου δεν έχει υπεύθυνο και προβλέπεται βροχή. Γράψε μήνυμα 80–100 λέξεων που διορθώνει το σχέδιο, χωρίς να επινοείς άδεια.", "rubric": "U-B2-017-RUBRIC", "item_id": "U-B2-017-I10", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-017", "version": "0.1.0", "criteria": ["условие ответственного", "дождь передан условно", "нет выдуманного переноса внутрь", "практическое сообщение"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-017-I10.json", "sha256": "27cc635c82c7650960b47bc9bb19f839be7c414c1ccaaa4bdcab4a0d6352725c"}, "error_tags": ["CONDITION_LOSS_CANDIDATE"], "audio_job_ids": [], "competency_ids": ["B2-R01"], "model_response": "Δεν μπορούμε να προχωρήσουμε χωρίς υπεύθυνο. Χρειάζεται πρώτα να βρεθεί υπεύθυνος και να επιβεβαιωθεί η διοργάνωση· σε περίπτωση βροχής ακυρώνεται, δεν μεταφέρεται αυτόματα μέσα.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "transfer", "prompt": "Νέος κανονισμός: «Οι ομάδες χρησιμοποιούν τον κήπο μετά τις 17:00, εφόσον υπάρχει υπεύθυνος. Αν βρέχει, η εκδήλωση ακυρώνεται· δεν μεταφέρεται αυτόματα μέσα». Η ομάδα σου δεν έχει υπεύθυνο κα