4980	item	U-B2-018-I09	31c4bf482e16301e1dbf6ff55577043dd8236b1d63005347289ea05cd0d6323f	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Η ομάδα συμφώνησε: χώρος Β αν είναι διαθέσιμος, υπεύθυνη ελέγχου η Ελένη, απάντηση έως Τρίτη. Αν όχι, νέα συζήτηση. Γράψε πρακτικό 60–80 λέξεων χωρίς να μετατρέψεις την επιλογή σε οριστική κράτηση.", "rubric": "U-B2-018-RUBRIC", "item_id": "U-B2-018-I09", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-018", "version": "0.1.0", "criteria": ["υπεύθυνος", "προθεσμία", "όρος", "εναλλακτικό επόμενο βήμα"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-018-I09.json", "sha256": "c12449fca33d668a52277101a3fd4b2783a13ce4db416bc0e74526d81fce2012"}, "error_tags": ["AGREEMENT_SCOPE_CANDIDATE"], "audio_job_ids": [], "competency_ids": ["B2-SI01"], "model_response": "Συμφωνήσαμε να επιλέξουμε τον χώρο Β υπό τον όρο ότι είναι διαθέσιμος. Η Ελένη θα ελέγξει και θα μας ενημερώσει έως την Τρίτη. Αν δεν είναι, θα επανεξετάσουμε τις επιλογές.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "guided", "prompt": "Η ομάδα συμφώνησε: χώρος Β αν είναι διαθέσιμος, υπεύθυνη ελέγχου η Ελένη, απάντηση έως Τρίτη. Αν όχι, νέα συζήτηση. Γράψε πρακτικό 60–80 λέξεων χωρίς να μετατρέψεις την επιλογή σε οριστική κράτηση.", "skills": ["writing"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-018-I09", "options": [], "unit_id": "U-B2-018", "version": "0.1.0", "l