4995	item	U-B2-019-I12	0f950f00e58c7d5b02237b57c282ca60e7891413c288385180c768b73ffc5f48	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "D28. Ένας αναγνώστης νομίζει ότι εγκρίθηκαν όλες οι αλλαγές. Τα δεδομένα είναι: συζητήθηκαν όλες, εγκρίθηκαν μόνο οι αλλαγές ώρας. Γράψε διορθωτικό μήνυμα 90–110 λέξεων, με σαφή θέμα και χωρίς επίρριψη ευθυνών.", "rubric": "U-B2-019-RUBRIC", "item_id": "U-B2-019-I12", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-019", "version": "0.1.0", "criteria": ["обсуждение отделено от одобрения", "ограничение по времени", "нет ложного отказа", "ясный регистр"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-019-I12.json", "sha256": "1bba332abee38f0e5e7b7803edba4e8661e9a92ab71e03135da647acc4ab0b3f"}, "error_tags": ["DECISION_SCOPE_CANDIDATE"], "audio_job_ids": [], "competency_ids": ["B2-G09"], "model_response": "Τις αλλαγές τις συζητήσαμε όλες, αλλά εγκρίθηκαν μόνο όσες αφορούν την ώρα. Για τις υπόλοιπες δεν έχει ακόμη ληφθεί απόφαση.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "D28", "prompt": "D28. Ένας αναγνώστης νομίζει ότι εγκρίθηκαν όλες οι αλλαγές. Τα δεδομένα είναι: συζητήθηκαν όλες, εγκρίθηκαν μόνο οι αλλαγές ώρας. Γράψε διορθωτικό μήνυμα 90–110 λέξεων, με σαφή θέμα και χωρίς επίρριψη ευθυνών.", "skills": ["writing"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-019-I12", "options": [], "unit_id": "U-B2-019", "version":