4997	item	U-B2-020-I02	02ee81cafa67786ef8af418450ec7100f0e0ca04ba7379802aadb6b6b8ea77bc	core	{"type": "short_answer", "level": "B2", "answer": ["Β"], "module": "core", "prompt": "Ποια πηγή διευκρινίζει ότι οι εθελοντές δεν δεσμεύονται για όλο το έτος; Γράψε το γράμμα.", "rubric": null, "item_id": "U-B2-020-I02", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_semantic_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "EXACT_WITH_REVIEW_FALLBACK", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-020", "version": "0.1.0", "criteria": [], "stimulus": "Πηγές για υποθετικό κέντρο μάθησης — όλα τα δεδομένα είναι επινοημένα.\\nΑ. Αναφορά δοκιμής, 3 Οκτωβρίου: Σε τέσσερις εβδομάδες καταγράφηκαν 80 επισκέψεις στο εργαστήριο. Πρόκειται για επισκέψεις, όχι κατ’ ανάγκη για 80 διαφορετικούς ανθρώπους. Δεν συλλέχθηκαν στοιχεία ηλικίας. Δύο απογευματινές συναντήσεις ακυρώθηκαν λόγω έλλειψης προσωπικού.\\nΒ. Μήνυμα συντονίστριας, 5 Οκτωβρίου: Οι εθελοντές μπορούν να καλύψουν δύο απογεύματα την εβδομάδα για έναν μήνα. Δεν έχουν δεσμευτεί για το υπόλοιπο έτος. Ζητούν σαφές πρόγραμμα και υπεύθυνο που θα απαντά σε δύσκολα αιτήματα. Δεν πρέπει να χειρίζονται προσωπικούς κωδικούς επισκεπτών.\\nΓ. Ερωτηματολόγιο, 6 Οκτωβρίου: Από 20 ανθρώπους που απάντησαν προαιρετικά, 14 προτιμούν απογευματινό ωράριο. Το ερωτηματολόγιο διανεμήθηκε στο ίδιο το εργαστήριο, όχι σε όλους τους κατοίκους. Πέντε απαντήσεις αναφέρουν δυσκολία μετακίνησης. Δεν γνωρίζουμε αν οι ίδιοι άνθρωποι ανήκουν και στις δύο ομάδες.\\nΔ. Ενημέρωση δήμου, 7 Οκτωβρίου: Υπάρχει διαθέσιμο ποσό έως 600€ για δοκιμή ενός μήνα, υπό τον όρο ότι θα κατατεθεί σχέδιο δαπανών. Η ανακοίνωση δεν είναι έγκριση συγκεκριμένου προγράμματος. Αίτημα για μόνιμη λειτουργία θα εξεταστεί χωριστά.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-020-I02.json", "sha256": "9250d0a9243897e5a35866e641ebc52ab6b4dc2f627f691ff15ddc37215336c6"}, "error_tags": ["SOURCE_ATTRIBUTION_CANDIDATE"], "audio_job_ids": [], "competency_ids": ["B2-M01"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "guided", "prompt": "Ποια πηγή διευκρινίζει ότι οι εθελοντές δεν δεσμεύονται για όλο το έτος; Γράψε το γράμμα.", "skills": ["reading"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-020-I02", "options": [], "unit_id": "U-B2-020", "version": "0.1.0", "language": "el+ru", "stimulus": "Πηγές για υποθετικό κέντρο μάθησης — όλα τα δεδομένα είναι επινοημένα.\\nΑ. Αναφορά δοκιμής, 3 Οκτωβρίου: Σε τέσσερις εβδομάδες καταγράφηκαν 80 επισκέψεις στο εργαστήριο. Πρόκειται για επισκέψεις, όχι κατ’ ανάγκη για 80 διαφορετικούς ανθρώπους. Δεν συλλέχθηκαν στοιχεία ηλικίας. Δύο απογευματινές συναντήσεις ακυρώθηκαν λόγω έλλειψης προσωπικού.\\nΒ. Μήνυμα συντονίστριας, 5 Οκτωβρίου: Οι εθελοντές μπορούν να καλύψουν δύο απογεύματα την εβδομάδα για έναν μήνα. Δεν έχουν δεσμευτεί για το υπόλοιπο έτος. Ζητούν σαφές πρόγραμμα και υπεύθυνο που θα απαντά σε δύσκολα αιτήματα. Δεν πρέπει να χειρίζονται προσωπικούς κωδικούς επισκεπτών.\\nΓ. Ερωτηματολόγιο, 6 Οκτωβρίου: Από 20 ανθρώπους που απάντησαν προαιρετικά, 14 προτιμούν απογευματινό ωράριο. Το ερωτηματολόγιο διανεμήθηκε στο ίδιο το εργαστήριο, όχι σε όλους τους κατοίκους. Πέντε απαντήσεις αναφέρουν δυσκολία μετακίνησης. Δεν γνωρίζουμε αν οι ίδιοι άνθρωποι ανήκουν και στις δύο ομάδες.\\nΔ. Ενημέρωση δήμου, 7 Οκτωβρίου: Υπάρχει διαθέσιμο ποσό έως 600€ για δοκιμή ενός μήνα, υπό τον όρο ότι θα κατατεθεί σχέδιο δαπανών. Η ανακοίνωση δεν είναι έγκριση συγκεκριμένου προγράμματος. Αίτημα για μόνιμη λειτουργία θα εξεταστεί χωριστά.", "licensing": {"originator": 