5002	item	U-B2-020-I07	bae9d0fe7028dc7c10c744ab1fc92b189efc5bdf19a1a902fc962089acc1f9d1	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Για το συμβούλιο γράψε σύνθεση 180–220 λέξεων. Χρησιμοποίησε τουλάχιστον τρεις πηγές, δύο περιορισμούς και τεκμηριωμένη σύσταση. Μην παρουσιάσεις την επιλογή σου ως απόφαση του δήμου.", "rubric": "U-B2-020-RUBRIC", "item_id": "U-B2-020-I07", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-020", "version": "0.1.0", "criteria": ["три точно атрибутированных источника", "два ограничения", "связная синтеза", "рекомендация явно авторская", "текст под совет"], "stimulus": "Πηγές για υποθετικό κέντρο μάθησης — όλα τα δεδομένα είναι επινοημένα.\\nΑ. Αναφορά δοκιμής, 3 Οκτωβρίου: Σε τέσσερις εβδομάδες καταγράφηκαν 80 επισκέψεις στο εργαστήριο. Πρόκειται για επισκέψεις, όχι κατ’ ανάγκη για 80 διαφορετικούς ανθρώπους. Δεν συλλέχθηκαν στοιχεία ηλικίας. Δύο απογευματινές συναντήσεις ακυρώθηκαν λόγω έλλειψης προσωπικού.\\nΒ. Μήνυμα συντονίστριας, 5 Οκτωβρίου: Οι εθελοντές μπορούν να καλύψουν δύο απογεύματα την εβδομάδα για έναν μήνα. Δεν έχουν δεσμευτεί για το υπόλοιπο έτος. Ζητούν σαφές πρόγραμμα και υπεύθυνο που θα απαντά σε δύσκολα αιτήματα. Δεν πρέπει να χειρίζονται προσωπικούς κωδικούς επισκεπτών.\\nΓ. Ερωτηματολόγιο, 6 Οκτωβρίου: Από 20 ανθρώπους που απάντησαν προαιρετικά, 14 προτιμούν απογευματινό ωράριο. Το ερωτηματολόγιο διανεμήθηκε στο ίδιο το εργαστήριο, όχι σε όλους τους κατοίκους. Πέντε απαντήσεις αναφέρουν δυσκολία μετακίνησης. Δεν γνωρίζουμε αν οι ίδιοι άνθρωποι ανήκουν και στις δύο ομάδες.\\nΔ. Ενημέρωση δήμου, 7 Οκτωβρίου: Υπάρχει διαθέσιμο ποσό έως 600€ για δοκιμή ενός μήνα, υπό τον όρο ότι θα κατατεθεί σχέδιο δαπανών. Η ανακοίνωση δεν είναι έγκριση συγκεκριμένου προγράμματος. Αίτημα για μόνιμη λειτουργία θα εξεταστεί χωριστά.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-020-I07.json", "sha256": "9f7a5a03e1c3e8a1be274cafdc06bb8e051856482feadd6e1ee965cbba1cd61b"}, "error_tags": ["FACT_RECOMMENDATION_BOUNDARY_CANDIDATE"], "audio_job_ids": [], "competency_ids": ["B2-M01"], "model_response": "Ενδεικτική κατεύθυνση: δοκιμή ενός μήνα με σχέδιο δαπανών, επιβεβαιωμένο προσωπικό και καλύτερη συλλογή δεδομένων. Τα υπάρχοντα στοιχεία δείχνουν ενδιαφέρον αλλά δεν αποδεικνύουν μόνιμη ζήτηση.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "independent", "prompt": "Για το συμβούλιο γράψε σύνθεση 180–220 λέξεων. Χρησιμοποίησε τουλάχιστον τρεις πηγές, δύο περιορισμούς και τεκμηριωμένη σύσταση. Μην παρουσιάσεις την επιλογή σου ως απόφαση του δήμου.", "skills": ["writing"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-020-I07", "options": [], "unit_id": "U-B2-020", "version": "0.1.0", "language": "el+ru", "stimulus": "Πηγές για υποθετικό κέντρο μάθησης — όλα τα δεδομένα είναι επινοημένα.\\nΑ. Αναφορά δοκιμής, 3 Οκτωβρίου: Σε τέσσερις εβδομάδες καταγράφηκαν 80 επισκέψεις στο εργαστήριο. Πρόκειται για επισκέψεις, όχι κατ’ ανάγκη για 80 διαφορετικούς ανθρώπους. Δεν συλλέχθηκαν στοιχεία ηλικίας. Δύο απογευματινές συναντήσεις ακυρώθηκαν λόγω έλλειψης προσωπικού.\\nΒ. Μήνυμα συντονίστριας, 5 Οκτωβρίου: Οι εθελοντές μπορούν να καλύψουν δύο απογεύματα την εβδομάδα για έναν μήνα. Δεν έχουν δεσμευτεί για το υπόλοιπο έτος. Ζητούν σαφές πρόγραμμα και υπεύθυνο που θα απαντά σε δύσκολα αιτήματα. Δεν πρέπει να χειρίζονται προσωπικούς κωδικούς επισκεπτών.\\nΓ. Ερωτηματολόγιο, 6 Οκτωβρίου: Από 20 ανθρώπους που απάντησαν προαιρετικά, 14 προτιμούν απογευματινό ωράριο. Το ερωτηματολόγιο διανεμήθηκε στο ίδιο το εργαστήριο, όχι σε όλους τους κατοίκους. Πέντε απαντήσεις αναφέρουν δυσκολία μετακίνησης. Δεν γνωρίζουμε αν οι ίδιοι άνθρωποι ανήκουν και στις δύο ομάδες.\\nΔ. Ενημέρωση δήμου, 7 Οκτωβρίου: Υπάρχει διαθέσιμο ποσό έως 600€ για δοκιμή ενός μήνα, υπό τον όρο ότι θα κατατεθεί σχέδιο δαπανών. Η ανακοίνωση δεν είναι έγκριση συγκεκριμένου προγράμματος. Αίτημα για μόνιμη λειτουργία θα εξεταστεί χωριστά.", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Не требовать именно поддержки эксперимента; возможен аргументированный запрос дополнительных данных.", "rubric_id": "U-B2-020-RUBRIC", "error_tags": ["FACT_RECOMMENDATION_BOUNDARY_CANDIDATE"], "answer_type": "open_response", "publishable": false, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "item_version": "0.1.0", "privacy_risk": "FICTIONAL_DETAILS_ONLY", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-M01"], "model_response": "Ενδεικτική κατεύθυνση: δοκιμή ενός μήνα με σχέδιο δαπανών, επιβεβαιωμένο προσωπικό και καλύτερη συλλογή δεδομένων. Τα υπάρχοντα στοιχεία δείχνουν ενδιαφέρον αλλά δεν αποδεικνύουν μόνιμη ζήτηση.", "error_tag_policy": "Item-specific author hypothesis; actual learner error requires quoted response evidence and human/assessor decision. A