5004	item	U-B2-020-I09	66ae4aa79c67f8710ee78f57723495f03ebac58df737acf78ea2d5628d49e7ba	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Νέα πηγή Ε, 9 Οκτωβρίου: «Ένας εθελοντής αποσύρθηκε. Επιβεβαιωμένη κάλυψη υπάρχει μόνο την Τετάρτη». Αναθεώρησε σε 80–100 λέξεις τη σύσταση, εξηγώντας τι αλλάζει και τι παραμένει άγνωστο.", "rubric": "U-B2-020-RUBRIC", "item_id": "U-B2-020-I09", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-020", "version": "0.1.0", "criteria": ["учёл дату/изменение", "не выдумал замену", "пересмотрел рекомендацию"], "stimulus": "Πηγές για υποθετικό κέντρο μάθησης — όλα τα δεδομένα είναι επινοημένα.\\nΑ. Αναφορά δοκιμής, 3 Οκτωβρίου: Σε τέσσερις εβδομάδες καταγράφηκαν 80 επισκέψεις στο εργαστήριο. Πρόκειται για επισκέψεις, όχι κατ’ ανάγκη για 80 διαφορετικούς ανθρώπους. Δεν συλλέχθηκαν στοιχεία ηλικίας. Δύο απογευματινές συναντήσεις ακυρώθηκαν λόγω έλλειψης προσωπικού.\\nΒ. Μήνυμα συντονίστριας, 5 Οκτωβρίου: Οι εθελοντές μπορούν να καλύψουν δύο απογεύματα την εβδομάδα για έναν μήνα. Δεν έχουν δεσμευτεί για το υπόλοιπο έτος. Ζητούν σαφές πρόγραμμα και υπεύθυνο που θα απαντά σε δύσκολα αιτήματα. Δεν πρέπει να χειρίζονται προσωπικούς κωδικούς επισκεπτών.\\nΓ. Ερωτηματολόγιο, 6 Οκτωβρίου: Από 20 ανθρώπους που απάντησαν προαιρετικά, 14 προτιμούν απογευματινό ωράριο. Το ερωτηματολόγιο διανεμήθηκε στο ίδιο το εργαστήριο, όχι σε όλους τους κατοίκους. Πέντε απαντήσεις αναφέρουν δυσκολία μετακίνησης. Δεν γνωρίζουμε αν οι ίδιοι άνθρωποι ανήκουν και στις δύο ομάδες.\\nΔ. Ενημέρωση δήμου, 7 Οκτωβρίου: Υπάρχει διαθέσιμο ποσό έως 600€ για δοκιμή ενός μήνα, υπό τον όρο ότι θα κατατεθεί σχέδιο δαπανών. Η ανακοίνωση δεν είναι έγκριση συγκεκριμένου προγράμματος. Αίτημα για μόνιμη λειτουργία θα εξεταστεί χωριστά.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-020-I09.json", "sha256": "06a8a498f7eb84848f332995586b410b041d8cb25bb65b58234ae6e5c415c608"}, "error_tags": ["STALE_INFORMATION_CANDIDATE"], "audio_job_ids": [], "competency_ids": ["B2-M01"], "model_response": "Η προτεινόμενη λειτουργία περιορίζεται προς το παρόν στην Τετάρτη. Χρειάζεται νέα επιβεβαίωση πριν προστεθεί δεύτερο απόγευμα. Δεν γνωρίζουμε αν μπορεί να βρεθεί αντικαταστάτης.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "transfer", "prompt": "Νέα πηγή Ε, 9 Οκτωβρίου: «Ένας εθελοντής αποσύρθηκε. Επιβεβαιωμένη κάλυψη υπάρχει μόνο την Τετάρτη». Αναθεώρησε σε 80–100 λέξεις τη σύσταση, εξηγώντας τι αλλάζει και τι παραμένει άγνωστο.", "skills": ["writing"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-020-I09", "options": [], "unit_id": "U-B2-020", "version": "0.1.0", "language": "el+ru", "stimulus": "Πηγές για υποθετικό κέντρο μάθησης — όλα τα δεδομένα είναι επινοημένα.\\nΑ. Αναφορά δοκιμής, 3 Οκτωβρίου: Σε τέσσερις εβδομάδες καταγράφηκαν 80 επισκέψεις στο εργαστήριο. Πρόκειται για επισκέψεις, όχι κατ’ ανάγκη για 80 διαφορετικούς ανθρώπους. Δεν συλλέχθηκαν στοιχεία ηλικίας. Δύο απογευματινές συναντήσεις ακυρώθηκαν λόγω έλλειψης προσωπικού.\\nΒ. Μήνυμα συντονίστριας, 5 Οκτωβρίου: Οι εθελοντές μπορούν να καλύψουν δύο απογεύματα την εβδομάδα για έναν μήνα. Δεν έχουν δεσμευτεί για το υπόλοιπο έτος. Ζητούν σαφές πρόγραμμα και υπεύθυνο που θα απαντά σε δύσκολα αιτήματα. Δεν πρέπει να χειρίζονται προσωπικούς κωδικούς επισκεπτών.\\nΓ. Ερωτηματολόγιο, 6 Οκτωβρίου: Από 20 ανθρώπους που απάντησαν προαιρετικά, 14 προτιμούν απογευματινό ωράριο. Το ερωτηματολόγιο διανεμήθηκε στο ίδιο το εργαστήριο, όχι σε όλους τους κατοίκους. Πέντε απαντήσεις αναφέρουν δυσκολία μετακίνησης. Δεν γνωρίζουμε αν οι ίδιοι άνθρωποι ανήκουν και στις δύο ομάδες.\\nΔ. Ενημέρωση δήμου, 7 Οκτωβρίου: Υπάρχει διαθέσιμο ποσό έως 600€ για δοκιμή ενός μήνα, υπό τον όρο ότι θα κατατεθεί σχέδιο δαπανών. Η ανακοίνωση δεν είναι έγκριση συγκεκριμένου προγράμματος. Αίτημα για μόνιμη λειτουργία θα εξεταστεί χωριστά.", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Не молча сохранять два дня.", "rubric_id": "U-B2-020-RUBRIC", "error_tags": ["STALE_INFORMATION_CANDIDATE"], "answer_type": "open_response", "publishable": false, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "item_version": "0.1.0", "privacy_risk": "FICTIONAL_DETAILS_ONLY", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-M01"], "model_response": "Η προτεινόμενη λειτουργία περιορίζεται προς το παρόν στην Τετάρτη. Χρειάζεται νέα επιβεβαίωση πριν προστεθεί δεύτερο απόγευμα. Δεν γνωρίζουμε αν μπορεί να βρεθεί αντικαταστάτης.", "error_tag_policy": "Item-specific author hypothesis; actual learner error requires quoted response evidence and human/assessor decision. ASR uncertainty excluded.", "estimated_effort": null, "source_claim_ids": ["U-B2-020-SCOPE"], "success_criteria": ["учёл дату/изменение", "не выдумал замену", "пересмотрел рекомен