5005	item	U-B2-020-I10	f15186b34b7c0a388c7c500ba2780fb03352fed837809239e2f211fe5bc25aed	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "D7. Α: «Το λεωφορείο αναχωρεί στις 18:00». Β: «Η ενημέρωση τελειώνει περίπου στις 17:50, ίσως αργότερα». Γ: «Η στάση απέχει 15 λεπτά με τα πόδια». Εξήγησε σε επισκέπτη γιατί δεν μπορείς να εγγυηθείς την ανταπόκριση και πρότεινε τι να ελέγξει.", "rubric": "U-B2-020-RUBRIC", "item_id": "U-B2-020-I10", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-020", "version": "0.1.0", "criteria": ["верное сопоставление времени", "не обещает успеть", "полезное действие"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-020-I10.json", "sha256": "9bded395f9700557ae0e3ee01428ff82a119c7d8cdac7ab25dec411693ac8dd7"}, "error_tags": ["TIME_INFERENCE_CANDIDATE"], "audio_job_ids": [], "competency_ids": ["B2-M01"], "model_response": "Ακόμη και με λήξη στις 17:50, η διαδρομή των 15 λεπτών οδηγεί μετά τις 18:00. Χρειάζεται να ελέγξει επόμενο δρομολόγιο ή νωρίτερη αποχώρηση.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "D7", "prompt": "D7. Α: «Το λεωφορείο αναχωρεί στις 18:00». Β: «Η ενημέρωση τελειώνει περίπου στις 17:50, ίσως αργότερα». Γ: «Η στάση απέχει 15 λεπτά με τα πόδια». Εξήγησε σε επισκέπτη γιατί δεν μπορείς να εγγυηθείς την ανταπόκριση και πρότεινε τι να ελέγξει.", "skills": ["writing"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-020-I1