claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Δεκτές ισοδύναμες αντιθετικές συνδέσεις.", "error_tags": ["DISCOURSE_RELATION_CANDIDATE"], "answer_type": "short_answer", "publishable": false, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "item_version": "0.1.0", "privacy_risk": "FICTIONAL_DETAILS_ONLY", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-R02"], "error_tag_policy": "Item-specific author hypothesis; actual learner error requires quoted response evidence and human/assessor decision. ASR uncertainty excluded.", "estimated_effort": null, "source_claim_ids": ["U-B2-022-SCOPE"], "target_objective": "Восстанавливать связи и отсылки между предложениями", "accepted_variants": ["Όμως", "Παρ’ όλα αυτά", "Παρόλα αυτά"], "canonical_answers": ["Ωστόσο"], "difficulty_estimate": "UNVALIDATED", "response_evaluation": {"method": "key_with_semantic_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "estimated_effort_status": "EDITOR_OR_PILOT_DECISION_REQUIRED"}, "prerequisite_ids": ["B2-R01", "B2-G07"], "source_claim_ids": ["U-B2-022-SCOPE"], "accepted_alternatives": ["Όμως", "Παρ’ όλα αυτά", "Παρόλα αυτά"]}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
5020	item	U-B2-022-I02	859e42d1e1182ea07987a678011f4c2c5923069d8ba2d4d66ff8c6e1ad25e292	core	{"type": "mcq", "level": "B2", "answer": ["Ασφαλής μάθηση και αναγνώριση των ορίων της παρέμβασης."], "module": "core", "prompt": "Ποια φράση αποδίδει καλύτερα τον στόχο της §1;", "rubric": null, "item_id": "U-B2-022-I02", "options": ["Ασφαλής μάθηση και αναγνώριση των ορίων της παρέμβασης.", "Κατάργηση των επαγγελματιών τεχνιτών.", "Εγγυημένη δωρεάν επισκευή κάθε συσκευής."], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_semantic_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "CHOICE_KEY", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-022", "version": "0.1.0", "criteria": [], "stimulus": "Μαθαίνοντας να επισκευάζουμε\\n[1] Ένα μικρό εργαστήριο επισκευών άρχισε να λειτουργεί σε έναν χώρο της γειτονιάς. Οι συμμετέχοντες φέρνουν χαλασμένα καθημερινά αντικείμενα και προσπαθούν να τα επισκευάσουν με καθοδήγηση. Ο στόχος δεν είναι να αντικατασταθούν οι επαγγελματίες τεχνίτες, αλλά να μάθουν οι πολίτες πότε μια απλή παρέμβαση είναι ασφαλής και πότε χρειάζεται ειδικός.\\n[2] Η πρώτη δυσκολία ήταν η λανθασμένη προσδοκία ότι κάθε αντικείμενο θα επισκευαζόταν δωρεάν. Οι οργανωτές διευκρίνισαν ότι προσφέρεται χρόνος και γνώση, όχι εγγύηση αποτελέσματος. Αν χρειάζονται ανταλλακτικά, ο ιδιοκτήτης ενημερώνεται για το πιθανό κόστος πριν αποφασίσει. Καμία εργασία που απαιτεί ειδική άδεια δεν πραγματοποιείται από ανειδίκευτους συμμετέχοντες.\\n[3] Το σημαντικότερο όφελος δεν ήταν πάντα ένα αντικείμενο που λειτουργούσε ξανά. Μερικοί έμαθαν να περιγράφουν με ακρίβεια το πρόβλημα, άλλοι κατάλαβαν γιατί μια επισκευή δεν ήταν οικονομικά λογική. Αυτή η γνώση μπορεί να βοηθήσει και σε μελλοντική αγορά. Ωστόσο, οι οργανωτές δεν έχουν ακόμη στοιχεία που να δείχνουν αν μειώθηκαν συνολικά τα απορρίμματα της περιοχής.\\n[4] Για να συνεχιστεί η δράση, χρειάζεται σταθερός χώρος και οργάνωση των ραντεβού. Η μεγάλη συμμετοχή μιας ημέρας δημιουργεί ενθουσιασμό, αλλά μπορεί να οδηγήσει σε βιαστικές παρεμβάσεις αν δεν υπάρχουν αρκετοί καθοδηγητές. Γι’ αυτό αποφασίστηκε περιορισμένος αριθμός θέσεων και καταγραφή των αιτημάτων που δεν εξυπηρετούνται.\\n[5] Η πρωτοβουλία δείχνει ότι η περιβαλλοντική εκπαίδευση μπορεί να συνδεθεί με πρακτικές δεξιότητες. Δεν αποδεικνύει, όμως, ότι κάθε επισκευή συμφέρει ούτε ότι ο εθελοντισμός αρκεί για όλα. Η αξία της θα κριθεί από την ασφάλεια, τη σταθερότητα και όσα οι συμμετέχοντες μπορούν πλέον να κάνουν ή να εξηγήσουν μόνοι τους.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-022-I02.json", "sha256": "021d5819ee2f4aa64e3a6995af9a1092df6f0675dfd52f5f097c46870f13f6ae"}, "error_tags": ["AUTHOR_PURPOSE_CANDIDATE"], "audio_job_ids": [], "competency_ids": ["B2-R02"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "guided", "prompt": "Ποια φράση αποδίδει καλύτερα τον στόχο της §1;", "skills": ["reading"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-022-I02", "options": ["Ασφαλής μάθηση και αναγνώριση των ορίων της παρέμβασης.", "Κατάργηση των επαγγελματιών τεχνιτών.", "Εγγυημένη δωρεάν επισκευή κάθε συσκευής."], "unit_id": "U-B2-022", "version": "0.1.0", "language": "el+ru", "stimulus": "Μαθαίνοντας να επισκευάζουμε\\n[1] Ένα μικρό εργαστήριο επισκευών άρχισε να λειτουργεί σε έναν χώρο της γειτονιάς. Οι συμμετέχοντες φέρνουν χαλασμένα καθημερινά αντικείμενα και προσπαθούν να τα επισκευάσουν με καθοδήγηση. Ο στόχος δεν είναι να αντικατασταθούν οι επαγγελματίες τεχνίτες, αλλά να μάθουν οι πολίτες πότε μια απλή παρέμβαση είναι ασφαλής και πότε χρειάζεται ειδικός.\\n[2] Η πρώτη δυσκολία ήταν η λανθασμένη προσδοκία ότι κάθε αντικείμενο θα επισκευαζόταν δωρεάν. Οι οργανωτές διευκρίνισαν ότι προσφέρεται χρόνος και γνώση, όχι εγγύηση αποτελέσματος. Αν χρειάζονται ανταλλακτικά, ο ιδιοκτήτης ενημερώνεται για το πιθανό κόστος πριν αποφασίσει. Καμία εργασία που απαιτεί ειδική άδεια δεν πραγματοποιείται από ανειδίκευτους συμμετέχοντες.\\n[3] Το σημαντικότερο όφελος δεν ήταν πάντα ένα αντικείμενο που λειτουργούσε ξανά. Μερικοί έμαθαν να περιγράφουν με ακρίβεια το πρόβλημα, άλλοι κατάλαβαν γιατί μια επισκευή δεν ήταν οικονομικά λογική. Αυτή η γνώση μπορεί να βοηθήσει και σε μελλοντική αγορά. Ωστόσο, οι οργανωτές δεν έχουν ακόμη στοιχεία που να δείχνουν αν μειώθηκαν συνολικά τα απορρίμματα της περιοχής.\\n[4] Για να συνεχιστεί η δράση, χρειάζεται σταθερός χώρος και οργάνωση των ραντεβού. Η μεγάλη συμμετοχή μιας ημέρας δημιουργεί ενθουσιασμό, αλλά μπορεί να οδηγήσει σε βιαστικές παρεμβάσεις αν δεν υπάρχουν αρκετοί καθοδηγητές. Γι’ αυτό αποφασίστηκε περιορισμένος αριθμός θέσεων και καταγραφή των αιτημάτων που δεν εξυπηρετούνται.\\n[5] Η πρωτοβουλία δείχνει ότι η περιβαλλοντική εκπαίδευση μπορεί να συνδεθεί με πρακτικές δεξιότητες. Δεν αποδεικνύει, όμως, ότι κάθε επισκευή συμφέρει ούτε ότι ο εθελοντισμός αρκεί για όλα. Η αξία της θα κριθεί από την ασφάλεια, τη σταθερότητα και όσα οι συμμετέχοντες μπορούν πλέον να κάνουν ή να εξηγήσουν μόνοι τους.", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Ο στόχος δεν είναι καθολική δωρεάν επισκευή ή κατάργηση τεχνιτών.", "error_tags": ["AUTHOR_PURPOSE_CANDIDATE"], "answer_type": "mcq", "publishable": false, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "item_version": "0.1.0", "privacy_risk": "FICTIONAL_DETAILS_ONLY", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-R02"], "error_tag_policy": "Item-specific author hypothesis; actual learner error requires quoted response evidence and human/assessor decision. ASR uncertainty excluded.", "estimated_effort": null, "source_claim_ids": ["U-B2-022-SCOPE"], "target_objective": "Восстанавливать связи и отсылки между предложениями", "accepted_variants": [], "canonical_answers": ["Ασφαλής μάθηση και αναγνώριση των ορίων της παρέμβασης."], "difficulty_estimate": "UNVALIDATED", "response_evaluation": {"method": "key_with_semantic_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "estimated_effort_status": "EDITOR_OR_PILOT_DECISION_REQUIRED"}, "prerequisite_ids": ["B2-R01", "B2-G07"], "source_claim_ids": ["U-B2-022-SCOPE"], "accepted_alternatives": []}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
5021	item	U-B2-022-I03	2c6495d9868577ed45770cb5d0af1f958ef5a7208c12cc9a448731700c273cbe	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Σε τι αναφέρεται το «Αυτή η γνώση» στην §3; Παράφρασε με δύο στοιχεία.", "rubric": "U-B2-022-RUBRIC", "item_id": "U-B2-022-I03", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-022", "version": "0.1.0", "criteria": ["описание неисправности", "целесообразность ремонта"], "stimulus": "Μαθαίνοντας να επισκευάζουμε\\n[1] Ένα μικρό εργαστήριο επισκευών άρχισε να λειτουργεί σε έναν χώρο της γειτονιάς. Οι συμμετέχοντες φέρνουν χαλασμένα καθημερινά αντικείμενα και προσπαθούν να τα επισκευάσουν με καθοδήγηση. Ο στόχος δεν είναι να αντικατασταθούν οι επαγγελματίες τεχνίτες, αλλά να μάθουν οι πολίτες πότε μια απλή παρέμβαση είναι ασφαλής και πότε χρειάζεται ειδικός.\\n[2] Η πρώτη δυσκολία ήταν η λανθασμένη προσδοκία ότι κάθε αντικείμενο θα επισκευαζόταν δωρεάν. Οι οργανωτές διευκρίνισαν ότι προσφέρεται χρόνος και γνώση, όχι εγγύηση αποτελέσματος. Αν χρειάζονται ανταλλακτικά, ο ιδιοκτήτης ενημερώνεται για το πιθανό κόστος πριν αποφασίσει. Καμία εργασία που απαιτεί ειδική άδεια δεν πραγματοποιείται από ανειδίκευτους συμμετέχοντες.\\n[3] Το σημαντικότερο όφελος δεν ήταν πάντα ένα αντικείμενο που λειτουργούσε ξανά. Μερικοί έμαθαν να περιγράφουν με ακρίβεια το πρόβλημα, άλλοι κατάλαβαν γιατί μια επισκευή δεν ήταν οικονομικά λογική. Αυτή η γνώση μπορεί να βοηθήσει και σε μελλοντική αγορά. Ωστόσο, οι οργανωτές δεν έχουν ακόμη στοιχεία που να δείχνουν αν μειώθηκαν συνολικά τα απορρίμματα της περιοχής.\\n[4] Για να συνεχιστεί η δράση, χρειάζεται σταθερός χώρος και οργάνωση των ραντεβού. Η μεγάλη συμμετοχή μιας ημέρας δημιουργεί ενθουσιασμό, αλλά μπορεί να οδηγήσει σε βιαστικές παρεμβάσεις αν δεν υπάρχουν αρκετοί καθοδηγητές. Γι’ αυτό αποφασίστηκε περιορισμένος αριθμός θέσεων και καταγραφή των αιτημάτων που δεν εξυπηρετούνται.\\n[5] Η πρωτοβουλία δείχνει ότι η περιβαλλοντική εκπαίδευση μπορεί να συνδεθεί με πρακτικές δεξιότητες. Δεν αποδεικνύει, όμως, ότι κάθε επισκευή συμφέρει ούτε ότι ο εθελοντισμός αρκεί για όλα. Η αξία της θα κριθεί από την ασφάλεια, τη σταθερότητα και όσα οι συμμετέχοντες μπορούν πλέον να κάνουν ή να εξηγήσουν μόνοι τους.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-022-I03.json", "sha256": "46fd7f262fdb991b29c013315452d78e394de76620f571f2fed3cfdc4c2236a9"}, "error_tags": ["ANAPHORA_REFERENCE_CANDIDATE"], "audio_job_ids": [], "competency_ids": ["B2-R02"], "model_response": "Στην ικανότητα ακριβούς περιγραφής του προβλήματος και στην κατανόηση του πότε μια επισκευή δεν συμφέρει.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "guided", "prompt": "Σε τι αναφέρεται το «Αυτή η γνώση» στην §3; Παράφρασε με δύο στοιχεία.", "skills": ["reading"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-022-I03", "options": [], "unit_id": "U-B2-022", "version": "0.1.0", "language": "el+ru", "stimulus": "Μαθαίνοντας να επισκευάζουμε\\n[1] Ένα μικρό εργαστήριο επισκευών άρχισε να λειτουργεί σε έναν χώρο της γειτονιάς. Οι συμμετέχοντες φέρνουν χαλασμένα καθημερινά αντικείμενα και προσπαθούν να τα επισκευάσουν με καθοδήγηση. Ο στόχος δεν είναι να αντικατασταθούν οι επαγγελματίες τεχνίτες, αλλά να μάθουν οι πολίτες πότε μια απλή παρέμβαση είναι ασφαλής και πότε χρειάζεται ειδικός.\\n[2] Η πρώτη δυσκολία ήταν η λανθασμένη προσδοκία ότι κάθε αντικείμενο θα επισκευαζόταν δωρεάν. Οι οργανωτές διευκρίνισαν ότι προσφέρεται χρόνος και γνώση, όχι εγγύηση αποτελέσματος. Αν χρειάζονται ανταλλακτικά, ο ιδιοκτήτης ενημερώνεται για το πιθανό κόστος πριν αποφασίσει. Καμία εργασία που απαιτεί ειδική άδεια δεν πραγματοποιείται από ανειδίκευτους συμμετέχοντες.\\n[3] Το σημαντικότερο όφελος δεν ήταν πάντα ένα αντικείμενο που λειτουργούσε ξανά. Μερικοί έμαθαν να περιγράφουν με ακρίβεια το πρόβλημα, άλλοι κατάλαβαν γιατί μια επισκευή δεν ήταν οικονομικά λογική. Αυτή η γνώση μπορεί να βοηθήσει και σε μελλοντική αγορά. Ωστόσο, οι οργανωτές δεν έχουν ακόμη στοιχεία που να δείχνουν αν μειώθηκαν συνολικά τα απορρίμματα της περιοχής.\\n[4] Για να συνεχιστεί η δράση, χρειάζεται σταθερός χώρος και οργάνωση των ραντεβού. Η μεγάλη συμμετοχή μιας ημέρας δημιουργεί ενθουσιασμό, αλλά μπορεί να οδηγήσει σε βιαστικές παρεμβάσεις αν δεν υπάρχουν αρκετοί καθοδηγητές. Γι’ αυτό αποφασίστηκε περιορισμένος αριθμός θέσεων και καταγραφή των αιτημάτων που δεν εξυπηρετούνται.\\n[5] Η πρωτοβουλία δείχνει ότι η περιβαλλοντική εκπαίδευση μπορεί να συνδεθεί με πρακτικές δεξιότητες. Δεν αποδεικνύει, όμως, ότι κάθε επισκευή συμφέρει ούτε ότι ο εθελοντισμός αρκεί για όλα. Η αξία της θα κριθεί από την ασφάλεια, τη σταθερότητα και όσα οι συμμετέχοντες μπορούν πλέον να κάνουν ή να εξηγήσουν μόνοι τους.", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Όχι απλώς στο επισκευασμένο αντικείμενο.", "rubric_id": "U-B2-022-RUBRIC", "error_tags": ["ANAPHORA_REFERENCE_CANDIDATE"], "answer_type": "open_response", "publishable": false, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "item_version": "0.1.0", "privacy_risk": "FICTIONAL_DETAILS_ONLY", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-R02"], "model_response": "Στην ικανότητα ακριβούς περιγραφής του προβλήματος και στην κατανόηση του πότε μια επισκευή δεν συμφέρει.", "error_tag_policy": "Item-specific author hypothesis; actual learner error requires quoted response evidence and human/assessor decision. ASR uncertainty excluded.", "estimated_effort": null, "source_claim_ids": ["U-B2-022-SCOPE"], "success_criteria": ["описание неисправности", "целесообразность ремонта"], "target_objective": "Восстанавливать связи и отсылки между предложениями", "accepted_variants": [], "canonical_answers": [], "difficulty_estimate": "UNVALIDATED", "response_evaluation": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "estimated_effort_status": "EDITOR_OR_PILOT_DECISION_REQUIRED"}, "prerequisite_ids": ["B2-R01", "B2-G07"], "source_claim_ids": ["U-B2-022-SCOPE"], "accepted_alternatives": []}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
