BRIC", "error_tags": ["CAUSAL_OVERCLAIM_CANDIDATE"], "answer_type": "open_response", "publishable": false, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "item_version": "0.1.0", "privacy_risk": "FICTIONAL_DETAILS_ONLY", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-R02"], "model_response": "Δεν υπάρχουν στοιχεία συνολικής μείωσης απορριμμάτων. Το εργαστήριο συνδέει περιβαλλοντική εκπαίδευση με πρακτικές δεξιότητες, χωρίς να αποδεικνύει ότι ο εθελοντισμός αρκεί.", "error_tag_policy": "Item-specific author hypothesis; actual learner error requires quoted response evidence and human/assessor decision. ASR uncertainty excluded.", "estimated_effort": null, "source_claim_ids": ["U-B2-022-SCOPE"], "success_criteria": ["отсутствие измеренного результата", "сохранена ограниченная польза", "нет новой гиперболы"], "target_objective": "Сжимать аргументированный текст с сохранением ограничений", "accepted_variants": [], "canonical_answers": [], "difficulty_estimate": "UNVALIDATED", "response_evaluation": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "estimated_effort_status": "EDITOR_OR_PILOT_DECISION_REQUIRED"}, "prerequisite_ids": ["B2-R01", "B2-G07"], "source_claim_ids": ["U-B2-022-SCOPE"], "accepted_alternatives": []}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
