5025	item	U-B2-022-I07	59b1d76f0d5e51c96135e8b90b19a4864e4ee60beaa25f50773a812b4de66b8b	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Γράψε περίληψη 110–140 λέξεων για ενημερωτικό δελτίο. Διατήρησε στόχο, οφέλη και δύο περιορισμούς. Μην προσθέσεις προσωπική σύσταση.", "rubric": "U-B2-022-RUBRIC", "item_id": "U-B2-022-I07", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-022", "version": "0.1.0", "criteria": ["στόχος", "οφέλη", "δύο περιορισμοί", "σύνδεση και όχι κατάλογος", "χωρίς προσωπική γνώμη"], "stimulus": "Μαθαίνοντας να επισκευάζουμε\\n[1] Ένα μικρό εργαστήριο επισκευών άρχισε να λειτουργεί σε έναν χώρο της γειτονιάς. Οι συμμετέχοντες φέρνουν χαλασμένα καθημερινά αντικείμενα και προσπαθούν να τα επισκευάσουν με καθοδήγηση. Ο στόχος δεν είναι να αντικατασταθούν οι επαγγελματίες τεχνίτες, αλλά να μάθουν οι πολίτες πότε μια απλή παρέμβαση είναι ασφαλής και πότε χρειάζεται ειδικός.\\n[2] Η πρώτη δυσκολία ήταν η λανθασμένη προσδοκία ότι κάθε αντικείμενο θα επισκευαζόταν δωρεάν. Οι οργανωτές διευκρίνισαν ότι προσφέρεται χρόνος και γνώση, όχι εγγύηση αποτελέσματος. Αν χρειάζονται ανταλλακτικά, ο ιδιοκτήτης ενημερώνεται για το πιθανό κόστος πριν αποφασίσει. Καμία εργασία που απαιτεί ειδική άδεια δεν πραγματοποιείται από ανειδίκευτους συμμετέχοντες.\\n[3] Το σημαντικότερο όφελος δεν ήταν πάντα ένα αντικείμενο που λειτουργούσε ξανά. Μερικοί έμαθαν να περιγράφουν με ακρίβεια το πρόβλημα, άλλοι κατάλαβαν γιατί μια επισκευή δεν ήταν οικονομικά λογική. Αυτή η γνώση μπορεί να βοηθήσει και σε μελλοντική αγορά. Ωστόσο, οι οργανωτές δεν έχουν ακόμη στοιχεία που να δείχνουν αν μειώθηκαν συνολικά τα απορρίμματα της περιοχής.\\n[4] Για να συνεχιστεί η δράση, χρειάζεται σταθερός χώρος και οργάνωση των ραντεβού. Η μεγάλη συμμετοχή μιας ημέρας δημιουργεί ενθουσιασμό, αλλά μπορεί να οδηγήσει σε βιαστικές παρεμβάσεις αν δεν υπάρχουν αρκετοί καθοδηγητές. Γι’ αυτό αποφασίστηκε περιορισμένος αριθμός θέσεων και καταγραφή των αιτημάτων που δεν εξυπηρετούνται.\\n[5] Η πρωτοβουλία δείχνει ότι η περιβαλλοντική εκπαίδευση μπορεί να συνδεθεί με πρακτικές δεξιότητες. Δεν αποδεικνύει, όμως, ότι κάθε επισκευή συμφέρει ούτε ότι ο εθελοντισμός αρκεί για όλα. Η αξία της θα κριθεί από την ασφάλεια, τη σταθερότητα και όσα οι συμμετέχοντες μπορούν πλέον να κάνουν ή να εξηγήσουν μόνοι τους.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-022-I07.json", "sha256": "fbe026750424e99a850fac495fbcb69e236ff90e2980a35e9cb5049a95292d7b"}, "error_tags": ["SUMMARY_FIDELITY_CANDIDATE"], "audio_job_ids": [], "competency_ids": ["B2-R02"], "model_response": "Ενδεικτικός πυρήνας: Το εργαστήριο προσφέρει καθοδήγηση και βοηθά τους συμμετέχοντες να κατανοήσουν πότε χρειάζεται ειδικός. Δεν εγγυάται αποτέλεσμα ούτε διαθέτει ακόμη στοιχεία για συνολική μείωση απορριμμάτων. Η συνέχεια απαιτεί ασφαλή οργάνωση.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "independent", "prompt": "Γράψε περίληψη 110–140 λέξεων για ενημερωτικό δελτίο. Διατήρησε στόχο, οφέλη και δύο περιορισμούς. Μην προσθέσεις προσωπική σύσταση.", "skills": ["writing"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-022-I07", "options": [], "unit_id": "U-B2-022", "version": "0.1.0", "language": "el+ru", "stimulus": "Μαθαίνοντας να επισκευάζουμε\\n[1] Ένα μικρό εργαστήριο επισκευών άρχισε να λειτουργεί σε έναν χώρο της γειτονιάς. Οι συμμετέχοντες φέρνουν χαλασμένα καθημερινά αντικείμενα και προσπαθούν να τα επισκευάσουν με καθοδή