5081	item	KEG-B2-L02-A10	25a49ebaf24c0cdd20e45704a8d078e07aa33b6264d29fe2688b7aeb482a818f	keg_b2	{"type": "multiple_assignment", "level": "B2", "answer": ["Σοφία"], "module": "keg_b2", "prompt": "Δηλώνει απαραίτητη την άδεια του καλεσμένου πριν από τη δημοσίευση.", "rubric": null, "item_id": "KEG-B2-L02-A10", "options": ["Δανάη", "Πέτρος", "Σοφία"], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_semantic_review", "normalization": ["NFC", "trim", "collapse_whitespace"], "strip_accents": false, "unlisted_plausible_answer": "HOLD_FOR_REVIEW", "automatic_final_score_allowed": false}, "strategy": "STRUCTURED_WITH_REVIEW_FALLBACK", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": null, "version": "0.1.0", "criteria": [], "stimulus": {"cue_ids": ["D08"], "asset_id": "KEG-B2-L02-AUD2"}, "canonical": {"path": "GreekOS_B2_Exam_Bank/items/KEG-B2-L02-A10.json", "sha256": "27796741ec7d8c7bfab75324ff1c0bb7f95bf0d2182b3b4a0374820f196b53b3"}, "error_tags": [], "audio_job_ids": ["KEG-B2-L02-AUD2"], "competency_ids": ["B2-L01", "B2-L02"], "model_response": null, "requires_audio": true, "estimated_effort": null, "original_payload": {"pool": "exam_holdout", "level": "B2", "points": 1, "prompt": "Δηλώνει απαραίτητη την άδεια του καλεσμένου πριν από τη δημοσίευση.", "skills": ["listening"], "status": "AUTHOR_COMPLETE_AI_REVIEW_PENDING", "item_id": "KEG-B2-L02-A10", "options": ["Δανάη", "Πέτρος", "Σοφία"], "scoring": {"blank": 0, "points": 1, "multiple_marked": 0, "project_practice": true, "one_choice_per_row": true, "official_scoring_claimed": false}, "unit_id": null, "version": "0.1.0", "stimulus": {"cue_ids": ["D08"], "asset_id": "KEG-B2-L02-AUD2"}, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIG