5086	item	KEG-B2-S02-I1	92e57968b8ad5d59e227ec8935a7fa041a478a9ed62aa8d89030953a25c12230	keg_b2	{"type": "open_response", "level": "B2", "answer": [], "module": "keg_b2", "prompt": "Συζητήστε σε ζευγάρι. Η ομάδα σας διαθέτει χρήματα για μία μόνο εκπαιδευτική δράση το επόμενο τρίμηνο. Μπορεί να επιλέξει είτε ένα εντατικό σαββατοκύριακο είτε έξι σύντομες απογευματινές συναντήσεις. Το συνολικό κόστος είναι ίδιο. Καταλήξτε σε αιτιολογημένη πρόταση. Αν διαφωνείτε, διευκρινίστε σε ποια σημεία και ποιον συμβιβασμό θα μπορούσατε να δεχτείτε.", "rubric": "RUB-KEG-SPEAKING-PROJECT", "item_id": "KEG-B2-S02-I1", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "descriptive_rubric_with_evidence", "unlisted_valid_positions": "ACCEPT_WHEN_JUSTIFIED", "official_point_conversion": null, "audio_required_for_phonology": true, "automatic_final_score_allowed": false}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": null, "version": "0.1.0", "criteria": ["σαφής θέση με αιτιολόγηση", "ουσιαστική αντίδραση στο επιχείρημα του άλλου", "ερώτηση διευκρίνισης ή έλεγχος κατανόησης", "διαπραγμάτευση εφαρμόσιμης λύσης χωρίς απαίτηση συμφωνίας"], "stimulus": null, "canonical": {"path": "GreekOS_B2_Exam_Bank/items/KEG-B2-S02-I1.json", "sha256": "84a2c4bc6b0e3dd66f21f01648dcd004bd8ba90e981e007b3f5b880d15b286be"}, "error_tags": [], "audio_job_ids": [], "competency_ids": ["B2-SI01"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "exam_holdout", "level": "B2", "points": null, "prompt": "Συζητήστε σε ζευγάρι. Η ομάδα σας διαθέτει χρήματα για μία μόνο εκπαιδευτική δράση το επόμενο τρίμηνο. Μπορεί να επιλέξει είτε ένα εντατικό σαββατοκύριακο είτε έξι σύντομες απογευματινές συναντήσεις. Το συνολικό κόστος είναι ίδιο. Καταλήξτε σε αιτιολογημένη πρόταση. Αν διαφωνείτε, διευκρινίστε σε ποια σημεία και ποιον συμβιβασμό θα μπορούσατε να δεχτείτε.", "skills": ["speaking"], "status": "AUTHOR_COMPLETE_AI_REVIEW_PENDING", "item_id": "KEG-B2-S02-I1", "unit_id": null, "version": "0.1.0", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Assess individual contribution, not agreement with prescribed policy. No automatic failure for reasoned disagreement.", "rubric_id": "RUB-KEG-SPEAKING-PROJECT", "role_cards": {"A": "Προτιμάτε το εντατικό σαββατοκύριακο, επειδή εργάζεστε σε διαφορετικές βάρδιες τις καθημερινές. Αναγνωρίστε τον κίνδυνο κόπωσης. Ζητήστε από τον συνομιλητή σας να εξηγήσει πώς θα διευκολυνθεί η συμμετοχή σας. Μπορείτε να αποδεχτείτε αλλαγή αν αντιμετωπίζεται ουσιαστικά το πρόβλημα των βαρδιών.", "B": "Προτιμάτε έξι απογευματινές συναντήσεις, ώστε να υπάρχει χρόνος εφαρμογής ανάμεσα στα μαθήματα. Έχετε οικογενειακές υποχρεώσεις τα σαββατοκύριακα. Εξετάστε τις δυσκολίες του άλλου και προτείνετε έναν τρόπο αναπλήρωσης, χωρίς να απαιτείτε αποκάλυψη προσωπικών στοιχείων."}, "answer_type": "open_response", "exam_family": "KEG_B2", "publishable": false, "source_refs": ["V241"], "exam_form_id": "KEG-B2-S02", "human_review": "NOT_REVIEWED", "competency_ids": ["B2-SI01"], "source_claim_ids": ["EXAM11-OFFICIAL-B2-STRUCTURE"], "success_criteria": ["σαφής θέση με αιτιολόγηση", "ουσιαστική αντίδραση στο επιχείρημα του άλλου", "ερώτηση διευκρίνισης ή έλεγχος κατανόησης", "διαπραγμάτευση εφαρμόσιμης λύσης χωρίς απαίτηση συμφωνίας"], "accepted_variants": [], "canonical_answers": [], "response_evaluation": {"method": "descriptive_rubric_with_evidence", "unlisted_valid_positions": "ACCEPT_WHEN_JUSTIFIED", "official_point_conversion": null, "audio_required_for_phonology": true, "automatic_final_score_allowed": false}, "section_points_total": 20}, "prerequisite_ids": [], "source_claim_ids": ["EXAM11-OFFICIAL-B2-STRUCTURE"], "accepted_alternatives": []}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
