5152	item	KEG-B2-L03-A10	42c07a63c10e8f523013d860ab8c2a234097abb992c4ff793d3eb8240abdbc48	keg_b2	{"type": "multiple_assignment", "level": "B2", "answer": ["Μυρτώ"], "module": "keg_b2", "prompt": "Προτείνει να κατανεμηθούν οι οργανωτικές εργασίες.", "rubric": null, "item_id": "KEG-B2-L03-A10", "options": ["Λένα", "Ορέστης", "Μυρτώ"], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_semantic_review", "normalization": ["NFC", "trim", "collapse_whitespace"], "strip_accents": false, "unlisted_plausible_answer": "HOLD_FOR_REVIEW", "automatic_final_score_allowed": false}, "strategy": "STRUCTURED_WITH_REVIEW_FALLBACK", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": null, "version": "0.1.0", "criteria": [], "stimulus": {"cue_ids": ["D08"], "asset_id": "KEG-B2-L03-AUD2"}, "canonical": {"path": "GreekOS_B2_Exam_Bank/items/KEG-B2-L03-A10.json", "sha256": "90459495fc69be0982c6ce43abcd0a77e2ff8d38f8e1da37c5d03bca61d64ac8"}, "error_tags": [], "audio_job_ids": ["KEG-B2-L03-AUD2"], "competency_ids": ["B2-L01", "B2-L02"], "model_response": null, "requires_audio": true, "estimated_effort": null, "original_payload": {"pool": "exam_holdout", "level": "B2", "points": 1, "prompt": "Προτείνει να κατανεμηθούν οι οργανωτικές εργασίες.", "skills": ["listening"], "status": "AUTHOR_COMPLETE_AI_REVIEW_PENDING", "item_id": "KEG-B2-L03-A10", "options": ["Λένα", "Ορέστης", "Μυρτώ"], "scoring": {"blank": 0, "points": 1, "multiple_marked": 0, "project_practice": true, "one_choice_per_row": true, "official_scoring_claimed": false}, "unit_id": null, "version": "0.1.0", "stimulus": {"cue_ids": ["D08"], "asset_id": "KEG-B2-L03-AUD2"}, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Explicit task-sharing.", "answer_type": "multiple_assignment", "exam_family": "KEG_B2", "publishable": false, "source_refs": ["V241"], "exam_form_id": "KEG-B2-L03", "human_review": "NOT_REVIEWED", "competency_ids": ["B2-L01", "B2-L02"], "source_claim_ids": ["EXAM11-OFFICIAL-B2-STRUCTURE"], "accepted_variants": [], "canonical_answers": ["Μυρτώ"], "response_evaluation": {"method": "key_with_semantic_review", "normalization": ["NFC", "trim", "collapse_whitespace"], "strip_accents": false, "unlisted_plausible_answer": "HOLD_FOR_REVIEW", "automatic_final_score_allowed": false}}, "prerequisite_ids": [], "source_claim_ids": ["EXAM11-OFFICIAL-B2-STRUCTURE"], "accepted_alternatives": []}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
5153	item	KEG-B2-W03-W01	57df886623b89ff119adc9c66b8ede9ebc08cb2d761d3b98912ca393f2da1750	keg_b2	{"type": "open_response", "level": "B2", "answer": [], "module": "keg_b2", "prompt": "Μια φίλη σας θέλει να συμμετάσχει σε ερασιτεχνική θεατρική ομάδα, αλλά φοβάται ότι δεν έχει ταλέντο και αρκετό χρόνο. Εσείς δοκιμάσατε πρόσφατα μια τέτοια δραστηριότητα. Γράψτε της φιλική επιστολή περίπου 200 λέξεων: περιγράψτε την εμπειρία σας, εξηγήστε μία δυσκολία που αντιμετωπίσατε, απαντήστε και στους δύο προβληματισμούς της και δώστε μια ρεαλιστική πρόταση. Μη χρησιμοποιήσετε το πραγματικό σας όνομα.", "rubric": "RUB-KEG-WRITING-PROJECT", "item_id": "KEG-B2-W03-W01", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "descriptive_rubric_with_evidence", "unlisted_valid_positions": "ACCEPT_WHEN_JUSTIFIED", "do_not_require_model_wording": true, "automatic_final_score_allowed": false}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": null, "version": "0.1.0", "criteria": ["конкретный личный опыт и одна трудность", "ответ на сомнение о таланте", "ответ на ограничение времени", "реалистичный совет без обещания гарантированного успеха", "дружеский регистр"], "stimulus": null, "canonical": {"path": "GreekOS_B2_Exam_Bank/items/KEG-B2-W03-W01.json", "sha256": "e8f965e2b14b3792a4003c3222a85bc09b6e3abc416a70e00e8cb5cef4a9dd8e"}, "error_tags": [], "audio_job_ids": [], "competency_ids": ["B2-W01"], "model_response": "Αγαπητή Άννα,\\nΔιάβασα όσα μου έγραψες για τη θεατρική ομάδα και αναγνώρισα αρκετές από τις δικές μου ανησυχίες. Όταν πήγα στην πρώτη συνάντηση, πίστευα ότι όλοι οι άλλοι θα είχαν εμπειρία. Τελικά οι περισσότεροι προσπαθούσαν, όπως κι εγώ, να καταλάβουν αν τους ταιριάζει αυτή η δραστηριότητα.\\nΣτην αρχή δυσκολευόμουν να μιλήσω μπροστά στους υπόλοιπους. Ξεχνούσα ακόμη και απλές φράσεις, επειδή σκεφτόμουν συνεχώς πώς ακουγόμουν. Με βοήθησαν οι μικρές ασκήσεις σε ζευγάρια, όπου δεν χρειαζόταν να παρουσιάσω αμέσως έναν ολόκληρο ρόλο. Σιγά σιγά άρχισα να προσέχω περισσότερο τον συνομιλητή μου και λιγότερο την εικόνα μου.\\nΔεν μπορώ να σου υποσχεθώ ότι θα νιώθεις άνετα από την πρώτη ημέρα. Δεν χρειάζεται όμως να αποδείξεις προκαταβολικά ότι έχεις ιδιαίτερο ταλέντο. Μια ομάδα αρχαρίων οφείλει να σου δίνει χώρο να δοκιμάσεις και να μάθεις, χωρίς να σε συγκρίνει διαρκώς με έμπειρους ηθοποιούς.\\nΓια τον χρόνο, ρώτησε συγκεκριμένα πόσες πρόβες απαιτούνται και αν αυξάνονται πριν από την παράσταση. Εγώ δεν το είχα υπολογίσει και χρειάστηκε να αλλάξω άλλες υποχρεώσεις. Θα σου πρότεινα δύο δοκιμαστικές συναντήσεις πριν δεσμευτείς για ολόκληρη τη χρονιά. Αν το πρόγραμμα δεν ταιριάζει, μπορείς να αναζητήσεις μικρότερο εργαστήριο. Η επιλογή αυτή δεν σημαίνει ότι εγκαταλείπεις την ιδέα.\\nΠεριμένω να μου πεις τι αποφάσισες!\\nΜε αγάπη,\\nΜαρία", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "exam_holdout", "level": "B2", "points": 10, "prompt": "Μια φίλη σας θέλει να συμμετάσχει σε ερασιτεχνική θεατρική ομάδα, αλλά φοβάται ότι δεν έχει ταλέντο και αρκετό χρόνο. Εσείς δοκιμάσατε πρόσφατα μια τέτοια δραστηριότητα. Γράψτε της φιλική επιστολή περίπου 200 λέξεων: περιγράψτε την εμπειρία σας, εξηγήστε μία δυσκολία που αντιμετωπίσατε, απαντήστε και στους δύο προβληματισμούς της και δώστε μια ρεαλιστική πρόταση. Μη χρησιμοποιήσετε το πραγματικό σας όνομα.", "skills": ["writing"], "status": "AUTHOR_COMPLETE_AI_REVIEW_PENDING", "item_id": "KEG-B2-W03-W01", "unit_id": null, "version": "0.1.0", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Демонстрация раскрывает страх публичной речи, практику в парах, отсутствие требования заранее доказать талант, конкретный график и пробное участие. Возможен совет отложить вступление при нехватке времени.", "rubric_id": "RUB-KEG-WRITING-PROJECT", "answer_type": "open_response", "exam_family": "KEG_B2", "publishable": false, "source_refs": ["V241"], "exam_form_id": "KEG-B2-W03", "human_review": "NOT_REVIEWED", "model_answer": "Αγαπητή Άννα,\\nΔιάβασα όσα μου έγραψες για τη θεατρική ομάδα και αναγνώρισα αρκετές από τις δικές μου ανησυχίες. Όταν πήγα στην πρώτη συνάντηση, πίστευα ότι όλοι οι άλλοι θα είχαν εμπειρία. Τελικά οι περισσότεροι προσπαθούσαν, όπως κι εγώ, να καταλάβουν αν τους ταιριάζει αυτή η δραστηριότητα.\\nΣτην αρχή δυσκολευόμουν να μιλήσω μπροστά στους υπόλοιπους. Ξεχνούσα ακόμη και απλές φράσεις, επειδή σκεφτόμουν συνεχώς πώς ακουγόμουν. Με βοήθησαν οι μικρές ασκήσεις σε ζευγάρια, όπου δεν χρειαζόταν να παρουσιάσω αμέσως έναν ολόκληρο ρόλο. Σιγά σιγά άρχισα να προσέχω περισσότερο τον συνομιλητή μου και λιγότερο την εικόνα μου.\\nΔεν μπορώ να σου υποσχεθώ ότι θα νιώθεις άνετα από την πρώτη ημέρα. Δεν χρειάζεται όμως να αποδείξεις προκαταβολικά ότι έχεις ιδιαίτερο ταλέντο. Μια ομάδα αρχαρίων οφείλει να σου δίνει χώρο να δοκιμάσεις και να μάθεις, χωρίς να σε συγκρίνει διαρκώς με έμπειρους ηθοποιούς.\\nΓια τον χρόνο, ρώτησε συγκεκριμένα πόσες πρόβες απαιτούνται και αν αυξάνονται πριν από την παράσταση. Εγώ δεν το είχα υπολογίσει και χρειάστηκε να αλλάξω άλλες υποχρεώσεις. Θα σου πρότεινα δύο δοκιμαστικές συναντήσεις πριν δεσμευτείς για ολόκληρη τη χρονιά. Αν το πρόγραμμα δεν ταιριάζει, μπορείς να αναζητήσεις μικρότερο εργαστήριο. Η επιλογή αυτή δεν σημαίνει ότι εγκαταλείπεις την ιδέα.\\nΠεριμένω να μου πεις τι αποφάσισες!\\nΜε αγάπη,\\nΜαρία", "model_status": "AUTHOR_ILLUSTRATION_NOT_CALIBRATED", "competency_ids": ["B2-W01"], "source_claim_ids": ["EXAM11-OFFICIAL-B2-STRUCTURE"], "success_criteria": ["конкретный личный опыт и одна трудность", "ответ на сомнение о таланте", "ответ на ограничение времени", "реалистичный совет без обещания гарантированного успеха", "дружеский регистр"], "accepted_variants": [], "canonical_answers": [], "response_evaluation": {"method": "descriptive_rubric_with_evidence", "unlisted_valid_positions": "ACCEPT_WHEN_JUSTIFIED", "do_not_require_model_wording": true, "automatic_final_score_allowed": false}}, "prerequisite_ids": [], "source_claim_ids": ["EXAM11-OFFICIAL-B2-STRUCTURE"], "accepted_alternatives": []}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
5154	item	KEG-B2-W03-W02	6d2e53b27303a8af4f43ee2d90a12d00d1c3e1598cadae455337b5a437b26d6d	keg_b2	{"type": "open_response", "level": "B2", "answer": [], "module": "keg_b2", "prompt": "Το δημοτικό κολυμβητήριο ανακοίνωσε ότι οι ώρες ελεύθερης χρήσης θα περιοριστούν μόνο στα πρωινά των καθημερινών. Γράψτε επίσημη επιστολή περίπου 200 λέξεων στη διοίκηση: εξηγήστε ποιους χρήστες δυσκολεύει η αλλαγή και γιατί, αναγνωρίστε μία πιθανή οργανωτική ανάγκη, προτείνετε δίκαιη εναλλακτική και ζητήστε συγκεκριμένη ενημέρωση. Η ανακοίνωση είναι υποθετική· μη χρησιμοποιήσετε πραγματικά προσωπικά στοιχεία ή επινοημένα στατιστικά.", "rubric": "RUB-KEG-WRITING-PROJECT", "item_id": "KEG-B2-W03-W02", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "descriptive_rubric_with_evidence", "unlisted_valid_positions": "ACCEPT_WHEN_JUSTIFIED", "do_not_require_model_wording": true, "automatic_final_score_allowed": false}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": null, "version": "0.1.0", "criteria": ["конкретные затронутые пользователи и причина", "возможная организационная потребность признана как предположение", "выполнимая справедливая альтернатива", "конкретный запрос информации", "формальное обращение и тон без выдуманных данных"], "stimulus": null, "canonical": {"path": "GreekOS_B2_Exam_Bank/items/KEG-B2-W03-W02.json", "sha256": "b29655a7a979a22a1b6569a96b405614f222108357306ea3dcbb753c6efc376d"}, "error_tags": [], "audio_job_ids": [], "competency_ids": ["B2-W01"], "model_response": "Προς τη Διοίκηση του Δημοτικού Κολυμβητηρίου,\\nΣας γράφω σχετικά με την ανακοίνωση ότι η ελεύθερη χρήση θα περιοριστεί στα πρωινά των καθημερινών. Ως τακτική χρήστρια, θα ήθελα να εκφράσω τον προβληματισμό μου και να ζητήσω περισσότερες πληροφορίες για την προτεινόμενη αλλαγή.\\nΤο νέο ωράριο δυσκολεύει ιδιαίτερα όσους εργάζονται ή παρακολουθούν μαθήματα το πρωί. Για αυτούς η δυνατότητα συμμετοχής δεν μειώνεται απλώς· ενδέχεται να χαθεί εντελώς. Παράλληλα, άνθρωποι που συνοδεύουν άλλα μέλη της οικογένειάς τους ίσως χρειάζονται ώρες που μπορούν να συνδυαστούν με τις κοινές τους υποχρεώσεις.\\nΑναγνωρίζω ότι μπορεί να υπάρχουν ανάγκες συντήρησης, περιορισμοί προσωπικού ή αυξημένη ζήτηση από οργανωμένα τμήματα. Δεν γνωρίζω ποιος παράγοντας οδήγησε στην απόφαση και δεν θα ήθελα να κάνω αβάσιμες υποθέσεις. Θεωρώ όμως χρήσιμο να εξεταστεί μια κατανομή που διατηρεί ορισμένες απογευματινές ώρες ελεύθερης χρήσης, έστω σε δύο ημέρες της εβδομάδας.\\nΘα μπορούσε να εφαρμοστεί δοκιμαστικό πρόγραμμα για έναν μήνα, με καταγραφή της προσέλευσης ανά ώρα. Έτσι η επανεξέταση θα βασιστεί σε πραγματικές ανάγκες και όχι μόνο σε μεμονωμένα παράπονα. Η διαδικασία κράτησης πρέπει επίσης να είναι διαθέσιμη σε όσους δεν χρησιμοποιούν εύκολα ψηφιακές υπηρεσίες.\\nΠαρακαλώ να μας ενημερώσετε για τους λόγους της αλλαγής, την ημερομηνία εφαρμογής και το αν προβλέπεται διαβούλευση με τους χρήστες. Σας ευχαριστώ για τον χρόνο σας.\\nΜε εκτίμηση,\\nΣοφία Νικολάου", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "exam_holdout", "level": "B2", "points": 10, "prompt": "Το δημοτικό κολυμβητήριο ανακοίνωσε ότι οι ώρες ελεύθερης χρήσης θα περιοριστούν μόνο στα πρωινά των καθημερινών. Γράψτε επίσημη επιστολή περίπου 200 λέξεων στη διοίκηση: εξηγήστε ποιους χρήστες δυσκολεύει η αλλαγή και γιατί, αναγνωρίστε μία πιθανή οργανωτική ανάγκη, προτείνετε δίκαιη εναλλακτική και ζητήστε συγκεκριμένη ενημέρωση. Η ανακοίνωση είναι υποθετική· μη χρησιμοποιήσετε πραγματικά προσωπικά στοιχεία ή επινοημένα στατιστικά.", "skills": ["writing"], "status": "AUTHOR_COMPLETE_AI_REVIEW_PENDING", "item_id": "KEG-B2-W03-W02", "unit_id": null, "version": "0.1.0", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Называет работающих/учащихся, различает предполагаемые причины и известную информацию, предлагает пробный месяц с двумя вечерами и запрашивает причины/дату/обсуждение. Это не юридическая претензия.", "rubric_id": "RUB-KEG-WRITING-PROJECT", "answer_type": "open_response", "exam_family": "KEG_B2", "publishable": false, "source_refs": ["V241"], "exam_form_id": "KEG-B2-W03", "human_review": "NOT_REVIEWED", "model_answer": "Προς τη Διοίκηση του Δημοτικού Κολυμβητηρίου,\\nΣας γράφω σχετικά με την ανακοίνωση ότι η ελεύθερη χρήση θα περιοριστεί στα πρωινά των καθημερινών. Ως τακτική χρήστρια, θα ήθελα να εκφράσω τον προβληματισμό μου και να ζητήσω περισσότερες πληροφορίες για την προτεινόμενη αλλαγή.\\nΤο νέο ωράριο δυσκολεύει ιδιαίτερα όσους εργάζονται ή παρακολουθούν μαθήματα το πρωί. Για αυτούς η δυνατότητα συμμετοχής δεν μειώνεται απλώς· ενδέχεται να χαθεί εντελώς. Παράλληλα, άνθρωποι που συνοδεύουν άλλα μέλη της οικογένειάς τους ίσως χρειάζονται ώρες που μπορούν να συνδυαστούν με τις κοινές τους υποχρεώσεις.\\nΑναγνωρίζω ότι μπορεί να υπάρχουν ανάγκες συντήρησης, περιορισμοί προσωπικού ή αυξημένη ζήτηση από οργανωμένα τμήματα. Δεν γνωρίζω ποιος παράγοντας οδήγησε στην απόφαση και δεν θα ήθελα να κάνω αβάσιμες υποθέσεις. Θεωρώ όμως χρήσιμο να εξεταστεί μια κατανομή που διατηρεί ορισμένες απογευματινές ώρες ελεύθερης χρήσης, έστω σε δύο ημέρες της εβδομάδας.\\nΘα μπορούσε να εφαρμοστεί δοκιμαστικό πρόγραμμα για έναν μήνα, με καταγραφή της προσέλευσης ανά ώρα. Έτσι η επανεξέταση θα βασιστεί σε πραγματικές ανάγκες και όχι μόνο σε μεμονωμένα παράπονα. Η διαδικασία κράτησης πρέπει επίσης να είναι διαθέσιμη σε όσους δεν χρησιμοποιούν εύκολα ψηφιακές υπηρεσίες.\\nΠαρακαλώ να μας ενημερώσετε για τους λόγους της αλλαγής, την ημερομηνία εφαρμογής και το αν προβλέπεται διαβούλευση με τους χρήστες. Σας ευχαριστώ για τον χρόνο σας.\\nΜε εκτίμηση,\\nΣοφία Νικολάου", "model_status": "AUTHOR_ILLUSTRATION_NOT_CALIBRATED", "competency_ids": ["B2-W01"], "source_claim_ids": ["EXAM11-OFFICIAL-B2-STRUCTURE"], "success_criteria": ["конкретные затронутые пользователи и причина", "возможная организационная потребность признана как предположение", "выполнимая справедливая альтернатива", "конкретный запрос информации", "формальное обращение и тон без выдуманных данных"], "accepted_variants": [], "canonical_answers": [], "response_evaluation": {"method": "descriptive_rubric_with_evidence", "unlisted_valid_positions": "ACCEPT_WHEN_JUSTIFIED", "do_not_require_model_wording": true, "automatic_final_score_allowed": false}}, "prerequisite_ids": [], "source_claim_ids": ["EXAM11-OFFICIAL-B2-STRUCTURE"], "accepted_alternatives": []}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
