5159	item	U-B2-010-I14	d3f961a0c7f90abd56e8d6d0056113a7f4e6f26bfd333fc66f9cee8bf11c6375	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Напишите Марии рекомендацию: сопоставьте общие расходы при 4 и 12 использованиях, объясните зависимость выбора от частоты и задайте один вопрос о неуказанных условиях.", "rubric": "U-B2-010-RUBRIC", "item_id": "U-B2-010-I14", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-010", "version": "0.2.0", "criteria": ["28 против 40 при 4 использованиях", "44 против 40 при 12", "условная рекомендация", "вопрос не выдан за известное условие"], "stimulus": "Σε μια φανταστική υπηρεσία κοινόχρηστων εργαλείων, το πρόγραμμα Α κοστίζει 20 ευρώ τον μήνα και επιπλέον 2 ευρώ για κάθε χρήση. Το πρόγραμμα Β κοστίζει 40 ευρώ τον μήνα, χωρίς επιπλέον χρέωση ανά χρήση. Η Μαρία υπολογίζει ότι θα χρησιμοποιήσει την υπηρεσία δώδεκα φορές. Και τα δύο προγράμματα προσφέρουν τα ίδια εργαλεία και τον ίδιο χρόνο δανεισμού. Η ανακοίνωση δεν δίνει πληροφορίες για επισκευές ή εγγυήσεις.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-010-I14.json", "sha256": "ba64b78d0204c2fd4fd3923719b9c76e20e1d68cdf9e38de0cfb7c79b65d8f18"}, "error_tags": ["CONTENT_OMISSION"], "audio_job_ids": [], "competency_ids": ["B2-V01"], "model_response": "Για τέσσερις χρήσεις το Α κοστίζει 28 ευρώ και το Β 40, οπότε συμφέρει το Α. Για δώδεκα χρήσεις το Α φτάνει τα 44 ευρώ και το Β μένει στα 40. Η επιλογή εξαρτάται λοιπόν από το πόσο συχνά θα χρησιμοποιείς την υπηρεσία. Θα ρωτούσα επίσης ποιος πληρώνει αν ένα εργαλείο χρειαστεί επισκευή.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "independent", "prompt": "Напишите Марии рекомендацию: сопоставьте общие расходы при 4 и 12 использованиях, объясните зависимость выбора от частоты и задайте один вопрос о неуказанных условиях.", "skills": ["writing"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-010-I14", "options": [], "unit_id": "U-B2-010", "version": "0.2.0", "language": "el+ru", "stimulus": "Σε μια φανταστική υπηρεσία κοινόχρηστων εργαλείων, το πρόγραμμα Α κοστίζει 20 ευρώ τον μήνα και επιπλέον 2 ευρώ για κάθε χρήση. Το πρόγραμμα Β κοστίζει 40 ευρώ τον μήνα, χωρίς επιπλέον χρέωση ανά χρήση. Η Μαρία υπολογίζει ότι θα χρησιμοποιήσει την υπηρεσία δώδεκα φορές. Και τα δύο προγράμματα προσφέρουν τα ίδια εργαλεία και τον ίδιο χρόνο δανεισμού. Η ανακοίνωση δεν δίνει πληροφορίες για επισκευές ή εγγυήσεις.", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Модель не исчерпывает допустимые ответы; оценивать сохранение смысла и самостоятельность.", "rubric_id": "U-B2-010-RUBRIC", "error_tags": ["CONTENT_OMISSION"], "answer_type": "open_response", "publishable": false, "source_refs": [{"anchor": "General educational objectives; listening; speaking", "source_id": "R12-KEG-B2", "claim_scope": "Level/task rationale only; original fictional stimuli and keys are author material, not approved by source."}], "item_version": "0.2.0", "privacy_risk": "FICTIONAL_DETAILS_ONLY", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-V01"], "model_response": "Για τέσσερις χρήσεις το Α κοστίζει 28 ευρώ και το Β 40, οπότε συμφέρει το Α. Για δώδεκα χρήσεις το Α φτάνει τα 44 ευρώ και το Β μένει στα 40. Η επιλογή εξαρτάται λοιπόν από το πόσο συχνά θα χρησιμοποιείς την υπηρεσία. Θα ρωτούσα επίσης ποιος πληρώνει αν ένα εργαλείο χρειαστεί επισκευή.", "error_tag_policy": "Candidate categories, not automatic learner diagnosis; use criterion evidence; never infer pronunciation from uncertain ASR", "estimated_effort": null, "source_claim_ids": ["R12-B2-DESCRIPTOR"], "success_criteria": ["28 против 40 при 4 использованиях", "44 против 40 при 12", "условная рекомендация", "вопрос не выдан за известное условие"], "target_objective": "Извлекать интересы участников и ограничения аргумента", "accepted_variants": [], "canonical_answers": [], "difficulty_estimate": "UNVALIDATED", "response_evaluation": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "estimated_effort_status": "UNKNOWN_PILOT_REQUIRED"}, "prerequisite_ids": ["B1-V01"], "source_claim_ids": ["R12-B2-DESCRIPTOR"], "accepted_alternatives": []}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
5160	item	U-B2-010-I15	79ba13b706adf1b4e1e59fa3c4a81452d5402febedffc9ac5d1d24add309e016	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Почему заголовок делает более сильный вывод, чем данные? Исправьте его по-гречески и назовите дополнительное сравнение, которое помогло бы проверить объяснение.", "rubric": "U-B2-010-RUBRIC", "item_id": "U-B2-010-I15", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-010", "version": "0.2.0", "criteria": ["наблюдаемое снижение отделено от причинного вывода", "учтено закрытие", "осторожный заголовок", "предложено сопоставление по дням работы"], "stimulus": "Ένα σχολείο ανακοίνωσε ότι η κατανάλωση νερού μειώθηκε κατά 20% σε σχέση με τον προηγούμενο μήνα. Είχε ξεκινήσει εκστρατεία εξοικονόμησης, αλλά έμεινε και κλειστό για μία εβδομάδα λόγω εργασιών. Δεν υπάρχουν στοιχεία για την κατανάλωση ανά ημέρα λειτουργίας. Μια ανάρτηση έγραψε: «Η εκστρατεία πέτυχε μείωση 20%».", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-010-I15.json", "sha256": "a401311961112142a2b8233d0f26ff6cae2f0096abee64a6ec1e78fecc63437f"}, "error_tags": ["CONTENT_OMISSION"], "audio_job_ids": [], "competency_ids": ["B2-V01"], "model_response": "Η συνολική κατανάλωση μειώθηκε, αλλά το σχολείο ήταν κλειστό για μία εβδομάδα. Δεν ξέρουμε πόση από τη μείωση οφείλεται στην εκστρατεία. Θα έγραφα: «Μείωση της κατανάλωσης νερού σε μήνα με εκστρατεία και διακοπή λειτουργίας». Χρειάζονται συγκρίσιμα στοιχεία ανά ημέρα λειτουργίας.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "guided", "prompt": "Почему заголовок делает более сильный вывод, чем данные? Исправьте его по-гречески и назовите дополнительное сравнение, которое помогло бы проверить объяснение.", "skills": ["reading"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-010-I15", "options": [], "unit_id": "U-B2-010", "version": "0.2.0", "language": "el+ru", "stimulus": "Ένα σχολείο ανακοίνωσε ότι η κατανάλωση νερού μειώθηκε κατά 20% σε σχέση με τον προηγούμενο μήνα. Είχε ξεκινήσει εκστρατεία εξοικονόμησης, αλλά έμεινε και κλειστό για μία εβδομάδα λόγω εργασιών. Δεν υπάρχουν στοιχεία για την κατανάλωση ανά ημέρα λειτουργίας. Μια ανάρτηση έγραψε: «Η εκστρατεία πέτυχε μείωση 20%».", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Модель не исчерпывает допустимые ответы; оценивать сохранение смысла и самостоятельность.", "rubric_id": "U-B2-010-RUBRIC", "error_tags": ["CONTENT_OMISSION"], "answer_type": "open_response", "publishable": false, "source_refs": [{"anchor": "General educational objectives; listening; speaking", "source_id": "R12-KEG-B2", "claim_scope": "Level/task rationale only; original fictional stimuli and keys are author material, not approved by source."}], "item_version": "0.2.0", "privacy_risk": "FICTIONAL_DETAILS_ONLY", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-V01"], "model_response": "Η συνολική κατανάλωση μειώθηκε, αλλά το σχολείο ήταν κλειστό για μία εβδομάδα. Δεν ξέρουμε πόση από τη μείωση οφείλεται στην εκστρατεία. Θα έγραφα: «Μείωση της κατανάλωσης νερού σε μήνα με εκστρατεία και διακοπή λειτουργίας». Χρειάζονται συγκρίσιμα στοιχεία ανά ημέρα λειτουργίας.", "error_tag_policy": "Candidate categories, not automatic learner diagnosis; use criterion evidence; never infer pronunciation from uncertain ASR", "estimated_effort": null, "source_claim_ids": ["R12-B2-DESCRIPTOR"], "success_criteria": ["наблюдаемое снижение отделено от причинного вывода", "учтено закрытие", "осторожный заголовок", "предложено сопоставление по дням работы"], "target_objective": "Извлекать интересы участников и ограничения аргумента", "accepted_variants": [], "canonical_answers": [], "difficulty_estimate": "UNVALIDATED", "response_evaluation": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "estimated_effort_status": "UNKNOWN_PILOT_REQUIRED"}, "prerequisite_ids": ["B1-V01"], "source_claim_ids": ["R12-B2-DESCRIPTOR"], "accepted_alternatives": []}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
