5162	item	U-B2-010-I17	b98ba1a7dda7d189f894195f94658cf2accb420a37ccf98f410ec7374ec83619	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Напишите редакторскую записку: выделите два условия участия, одну нерешённую редакторскую проблему и предложите решение без объявления одной памяти историческим фактом.", "rubric": "U-B2-010-RUBRIC", "item_id": "U-B2-010-I17", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-010", "version": "0.2.0", "criteria": ["добровольность", "отдельное решение о публикации", "различающиеся воспоминания как проблема", "атрибуция вместо ложной исторической уверенности"], "stimulus": "Μια βιβλιοθήκη θέλει να δημιουργήσει αρχείο προφορικών αφηγήσεων από παλιούς και νέους κατοίκους. Η συμμετοχή είναι προαιρετική. Οι αφηγητές θα επιλέγουν αν επιτρέπουν δημόσια ακρόαση ή μόνο διατήρηση της ηχογράφησης χωρίς δημοσίευση. Μερικοί ζητούν συναντήσεις το απόγευμα, επειδή εργάζονται το πρωί. Η ομάδα δεν έχει ακόμη αποφασίσει πώς θα παρουσιάζει διαφορετικές αναμνήσεις για το ίδιο γεγονός.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-010-I17.json", "sha256": "76e7b5829ac94c15a66a1bf0dada24ca737518def7f6fa557b20d79a748c4d78"}, "error_tags": ["CONTENT_OMISSION"], "audio_job_ids": [], "competency_ids": ["B2-V01"], "model_response": "Η συμμετοχή είναι προαιρετική και κάθε αφηγητής επιλέγει αν επιτρέπει δημόσια ακρόαση. Υπάρχει επίσης αίτημα για απογευματινές συναντήσεις. Για τις διαφορετικές αναμνήσεις προτείνω να παρουσιάζονται χωριστά οι αφηγήσεις, με σαφή αναφορά στον αφηγητή. Η προσωπική μαρτυρία δεν πρέπει να εμφανίζεται αυτόματα ως εξακριβωμένο γεγονός.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "guided", "prompt": "Напишите редакторскую записку: выделите два условия участия, одну нерешённую редакторскую проблему и предложите решение без объявления одной памяти историческим фактом.", "skills": ["writing"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-010-I17", "options": [], "unit_id": "U-B2-010", "version": "0.2.0", "language": "el+ru", "stimulus": "Μια βιβλιοθήκη θέλει να δημιουργήσει αρχείο προφορικών αφηγήσεων από παλιούς και νέους κατοίκους. Η συμμετοχή είναι προαιρετική. Οι αφηγητές θα επιλέγουν αν επιτρέπουν δημόσια ακρόαση ή μόνο διατήρηση της ηχογράφησης χωρίς δημοσίευση. Μερικοί ζητούν συναντήσεις το απόγευμα, επειδή εργάζονται το πρωί. Η ομάδα δεν έχει ακόμη αποφασίσει πώς θα παρουσιάζει διαφορετικές αναμνήσεις για το ίδιο γεγονός.", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Модель не исчерпывает допустимые ответы; оценивать сохранение смысла и самостоятельность.", "rubric_id": "U-B2-010-RUBRIC", "error_tags": ["CONTENT_OMISSION"], "answer_type": "open_response", "publishable": false, "source_refs": [{"anchor": "General educational objectives; listening; speaking", "source_id": "R12-KEG-B2", "claim_scope": "Level/task rationale only; original fictional stimuli and keys are author material, not approved by source."}], "item_version": "0.2.0", "privacy_risk": "FICTIONAL_DETAILS_ONLY", "review_status