5167	item	U-B2-014-I13	c47669cb6dfa78c536da1647317e3ca9c73efb1a5e792d4d0ec359dd793f6f9c	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Отредактируйте: «Η τιμή του εισιτηρίου βελτιώθηκε από 8 σε 10 ευρώ». Сохраните числа, но уберите неподтверждённую положительную оценку. Объясните выбор глагола.", "rubric": "U-B2-014-RUBRIC", "item_id": "U-B2-014-I13", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-014", "version": "0.2.0", "criteria": ["αυξήθηκε либо ανέβηκε с тем же смыслом", "8→10 сохранено", "изменение количества отделено от оценки качества"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-014-I13.json", "sha256": "40433ea0aa1ed4c22eb2e1a7abbf9a28acc93d5ace8d139b75fb6cec33166fe0"}, "error_tags": ["VOCAB_SELECTION"], "audio_job_ids": [], "competency_ids": ["B2-V02"], "model_response": "Η τιμή του εισιτηρίου αυξήθηκε από 8 σε 10 ευρώ. Το αυξήθηκε δηλώνει την αλλαγή ποσού, ενώ το βελτιώθηκε περιλαμβάνει θετική αξιολόγηση. Δεν ξέρουμε αν βελτιώθηκε η υπηρεσία.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "guided", "prompt": "Отредактируйте: «Η τιμή του εισιτηρίου βελτιώθηκε από 8 σε 10 ευρώ». Сохраните числа, но уберите неподтверждённую положительную оценку. Объясните выбор глагола.", "skills": ["writing"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-014-I13", "options": [], "unit_id": "U-B2-014", "version": "0.2.0", "language": "el+ru", "stimulus": nu