5168	item	U-B2-014-I14	e9345c02f315eb334c8a7d5624f6c0e08e6913eea126cddc61c6661b389d6918	core	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Сравните два контекста. A: Στη συνεδρίαση η Λένα πήρε τον λόγο και παρουσίασε την πρότασή της. B: Υποσχέθηκε να στείλει το κείμενο σήμερα και κράτησε τον λόγο της. Перефразируйте каждый без λόγος; почему они не взаимозаменяемы?", "rubric": "U-B2-014-RUBRIC", "item_id": "U-B2-014-I14", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-014", "version": "0.2.0", "criteria": ["A вступление в обсуждение", "B выполнение обещания", "различие функции в контексте"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-014-I14.json", "sha256": "762570b526fc704bc94b08890700604569949ccbc2c3e984b51f46abc5646cfc"}, "error_tags": ["CONTENT_OMISSION"], "audio_job_ids": [], "competency_ids": ["B2-V02"], "model_response": "Στην πρώτη περίπτωση η Λένα άρχισε να μιλά στη συνεδρίαση. Στη δεύτερη έκανε αυτό που είχε υποσχεθεί: έστειλε το κείμενο. Το πρώτο αφορά τη συμμετοχή στη συζήτηση, το δεύτερο την τήρηση μιας υπόσχεσης.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "guided", "prompt": "Сравните два контекста. A: Στη συνεδρίαση η Λένα πήρε τον λόγο και παρουσίασε την πρότασή της. B: Υποσχέθηκε να στείλει το κείμενο σήμερα και κράτησε τον λόγο της. Перефразируйте каждый без λόγος; почему они не взаимозаменяемы?", "skills": ["reading"], "status": "A