page=14", "sha256": "b2c569c8349c9150d4a96bf685647657d66bfc7ba08e12b02badddaf301e869a", "pdf_page": 14, "source_id": "PEGP-BANK-1057909", "checked_on": "2026-10-17", "bank_version": "2026/11", "printed_page": 14, "official_topic": 30, "verification_scope": "Actual page text and rendered page inspected; selected fact only, not complete page mastery"}], "competency_id": "PEGP-P04-GEO-001-MC", "prerequisites": ["Прочитать ключевые греческие имена и термин карточки", "Понять вопрос и базовые слова места/времени; при затруднении дать русскую опору до самостоятельной проверки"], "delayed_review": {"D7": "Ποιο όνομα συνδέσαμε με το βορειότερο σημείο της χώρας;", "D28": "Το Ορμένιο βρίσκεται στο βόρειο ή στο δυτικό άκρο της χώρας; Εξήγησε χωρίς κάρτα.", "conditions": "Без карточки и вариантов; ответы оцениваются по предъявленному вопросу, не по строке базового ключа."}, "mastery_criteria": {"fact": "Верно воспроизведена конкретная связь без противоречащего добавления", "observed": false, "retention": "Верные D7 и D28 без подсказки; ошибки → повторное объяснение и новая проверка", "production": "Самостоятельно выполнено именно задание переноса; чтение примера не засчитывается"}, "original_example": "Για το βορειότερο σημείο σημείωσα το Ορμένιο στον Έβρο.", "practice_item_ids": ["PEGP-P04-GEO-001"], "observable_outcome": "Воспроизвести и перенести факт: Για το βορειότερο σημείο σημείωσα το Ορμένιο στον Έβρο.", "independent_transfer": {"model_el": "Το Ορμένιο είναι το βορειότερο σημείο της Ελλάδας.", "prompt_el": "Ένας φίλος μπερδεύει το Ορμένιο με ένα δυτικό νησί. Εξήγησε σε μία πρόταση ποιο βόρειο σημείο μελετήσαμε.", "conditions": "Скрыть пример и ключ; ответить своими словами письменно или устно; в устной версии собеседник задаёт уточнение.", "model_not_exhaustive": true}, "interaction_followup": {"prompt_el": "Μπορείς να το εξηγήσεις με άλλα λόγια;", "evaluation": "Сохранена именно изученная связь; новые неподтверждённые сведения не обязательны."}, "prerequisite_support": {"probe": "Прочитайте и своими словами по-русски объясните: Για το βορειότερο σημείο σημείωσα το Ορμένιο στον Έβρο.", "remediation": "Сначала разобрать имя и ключевую связь с преподавателем; не засчитывать чтение модели как самостоятельное освоение."}}, {"rubric": {"0": "Требуемая фактическая связь отсутствует или неверна.", "1": "Связь дана неполно либо с помощью; требовать только детали, указанные в предъявленном вопросе.", "2": "Самостоятельно и верно передан требуемый факт; достаточное короткое имя/число допустимо.", "fact_anchor": ["1-Β, 2-Α"], "accent_policy": "Ошибка ударения не превращает верный факт в неверный; отметить отдельную языковую коррекцию.", "transfer_anchor": "Δυτικά θα γράψω Ιόνιο Πέλαγος και νότια Λιβυκό Πέλαγος.", "fact_anchor_scope": "BASE_ITEM_ONLY", "language_dimensions": ["понятность смысла", "уместная форма имени/термина", "связность, если требовалась полная фраза"], "transfer_anchor_scope": "NON_EXHAUSTIVE_MODEL_FOR_TRANSFER_ONLY", "language_score_separate": true}, "card_id": "PEGP-P04-GEO-002-CARD", "item_id": "PEGP-P04-GEO-002", "theory_ru": "Для карты страны различаем западную сторону и южную: Ιόνιο и Λιβυκό соответственно. Это географические ориентиры проверенного банка; не утверждение, что любая точка каждого побережья имеет только одно морское название. При ответе на сопоставление нужны обе пары.", "source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057909#page=15", "sha256": "b2c569c8349c9150d4a96bf685647657d66bfc7ba08e12b02badddaf301e869a", "pdf_page": 15, "source_id": "PEGP-BANK-1057909", "checked_on": "2026-10-17", "bank_version": "2026/11", "printed_page": 15, "official_topic": 32, "verification_scope": "Actual page text and rendered page inspected; selected fact only, not complete page mastery"}], "competency_id": "PEGP-P04-GEO-002-MC", "prerequisites": ["Прочитать ключевые греческие имена и термин карточки", "Понять вопрос и базовые слова места/времени; при затруднении