", "source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057909#page=19", "sha256": "b2c569c8349c9150d4a96bf685647657d66bfc7ba08e12b02badddaf301e869a", "pdf_page": 19, "source_id": "PEGP-BANK-1057909", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 19, "official_topic": 41, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}], "competency_id": "PEGP-P05-GEO-002-MC", "prerequisites": ["Basic Greek question comprehension", "Read the names and relation in this card"], "delayed_review": {"D7": "Σε ποια Περιφερειακή Ενότητα βρίσκεται το Αμύνταιο;", "D28": "Ο φίλος σου ταξινομεί το Αμύνταιο και ζητά το όνομα της Περιφερειακής Ενότητας. Απάντησε χωρίς επιλογές.", "conditions": "Without card/options; score only requested relation, not literal base key"}, "mastery_criteria": {"fact": "Correct requested factual relation with no contradiction", "observed": false, "retention": "D7 and D28 completed independently; no observations yet", "production": "Independent completion of transfer task"}, "original_example": "Το Αμύνταιο ανήκει στην Περιφερειακή Ενότητα Φλώρινας.", "practice_item_ids": ["PEGP-P05-GEO-002"], "observable_outcome": "Самостоятельно воспроизвести выбранную связь и применить её в исправлении/объяснении", "independent_transfer": {"prompt_el": "Ένας κατάλογος έχει βάλει το Αμύνταιο στη Φωκίδα. Γράψε τη διορθωμένη καταχώριση.", "conditions": "Hide original card and keys; produce own utterance; do not require details absent from prompt.", "model_not_exhaustive": true}, "prerequisite_support": {"probe": "Объясните по-русски, что именно требуется назвать в основном вопросе; затем прочтите ключевые имена.", "remediation": "Разобрать имя, падеж и отношение с русской опорой; закрыть модель перед самостоятельной попыткой."}}, {"rubric": {"0": "Required relation absent/false", "1": "Partial requested information or assistance", "2": "All requested factual information independently conveyed; equivalent wording accepted", "accent_policy": "Tag stress/form errors separately; do not turn correct fact into incorrect fact.", "language_score_separate": true}, "status": "AUTHORED_DRAFT", "card_id": "PEGP-P05-GEO-003-CARD", "item_id": "PEGP-P05-GEO-003", "theory_ru": "Орестиада относится к региональной единице Эврос. Вопрос требует исправить административную единицу, а не назвать реку или страну. Ответ Έβρου достаточен; полная фраза допустима. Название Эврос может иметь разные референты, поэтому здесь сохраняйте слова Περιφερειακή Ενότητα.", "source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057909#page=20", "sha256": "b2c569c8349c9150d4a96bf685647657d66bfc7ba08e12b02badddaf301e869a", "pdf_page": 20, "source_id": "PEGP-BANK-1057909", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 20, "official_topic": 42, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}], "competency_id": "PEGP-P05-GEO-003-MC", "prerequisites": ["Basic Greek question comprehension", "Read the names and relation in this card"], "delayed_review": {"D7": "Ποια Περιφερειακή Ενότητα συνδέεται με την Ορεστιάδα;", "D28": "Γράψε μία σωστή πρόταση με τις λέξεις Ορεστιάδα και Περιφερειακή Ενότητα.", "conditions": "Without card/options; score only requested relation, not literal base key"}, "mastery_criteria": {"fact": "Correct requested factual relation with no contradiction", "observed": false, "retention": "D7 and D28 completed independently; no observations yet", "production": "Independent completion of transfer task"}, "original_example": "Για την Ορεστιάδα έγραψα «Περιφερειακή Ενότητα Έβρου».", "practice_item_ids": ["PEGP-P05-GEO-003"], "observable_outcome": "Самостоятельно воспроизвести выбранную связь и применить её в исправлении/объяснении", "independent_transfer": {"prompt_el": "Πες σε έναν συμμαθητή πώς θα διορθώσεις την ετικέτα «Ορεστιάδα — Δράμας».", "conditions": "Hide original card and keys; produce own utterance; do not require details absent from prompt.", "model_not_exhaustive": true}, "prerequisite_support": {"probe": "Объясните по-русски, что именно требуется назвать в основном вопросе; затем прочтите ключевые имена.", "remediation": "Разобрать имя, падеж и отношение с русской опорой; закрыть модель перед самостоятельной попыткой."}}, {"rubric": {"0": "Required relation absent/false", "1": "Partial requested information or assistance", "2": "All requested factual information independently conveyed; equivalent wording accepted", "accent_policy": "Tag stress/form errors separately; do not turn correct fact into incorrect fact.", "language_score_separate": true}, "status": "AUTHORED_DRAFT", "card_id": "PEGP-P05-GEO-004-CARD", "item_id": "PEGP-P05-GEO-004", "theory_ru": "Ласити — региональная единица, а Крит — географическое отделение в этой классификации. Не отвечайте названием города: проверяется отношение части и более крупной территории. Карточка не требует перечисления всех единиц Крита.", "source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057909#page=21", "sha256": "b2c569c8349c9150d4a96bf685647657d66bfc7ba08e12b02badddaf301e869a", "pdf_page": 21, "source_id": "PEGP-BANK-1057909", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 21, "official_topic": 45, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}], "competency_id": "PEGP-P05-GEO-004-MC", "prerequisites": ["Basic Greek question comprehension", "Read the names and relation in this card"], "delayed_review": {"D7": "Σε ποιο γεωγραφικό διαμέρισμα ανήκει το Λασίθι;", "D28": "Σε έναν χάρτη το Λασίθι σημειώνεται στην Πελοπόννησο. Διόρθωσε την περιοχή.", "conditions": "Without card/options; score only requested relation, not literal base key"}, "mastery_criteria": {"fact": "Correct requested factual relation with no contradiction", "observed": false, "retention": "D7 and D28 completed independently; no observations yet", "production": "Independent completion of transfer task"}, "original_example": "Το Λασίθι είναι μία από τις Περιφερειακές Ενότητες της Κρήτης.", "practice_item_ids": ["PEGP-P05-GEO-004"], "observable_outcome": "Самостоятельно воспроизвести выбранную связь и применить её в исправлении/объяснении", "independent_transfer": {"prompt_el": "Δώσε σε έναν φίλο σύντομη εξήγηση γιατί το Λασίθι μπαίνει στον φάκελο «Κρήτη».", "conditions": "Hide original card and keys; produce own utterance; do not require details absent from prompt.", "model_not_exhaustive": true}, "prerequisite_support": {"probe": "Объясните по-русски, что именно требуется назвать в основном вопросе; затем прочтите ключевые имена.", "remediation": "Разобрать имя, падеж и отношение с русской опорой; закрыть модель перед самостоятельной попыткой."}}, {"rubric": {"0": "Required relation absent/false", "1": "Partial requested information or assistance", "2": "All requested factual information independently conveyed; equivalent wording accepted", "accent_policy": "Tag stress/form errors separately; do not turn correct fact into incorrect fact.", "language_score_separate": true}, "status": "AUTHORED_DRAFT", "card_id": "PEGP-P05-HIS-001-CARD", "item_id": "PEGP-P05-HIS-001", "theory_ru": "Для периода 1950–1960 банк выделяет эмиграцию многих греков. Слово πολλοί не означает «все» и не даёт точного числа. В задании не требуется перечислять страны назначения или объяснять все причины миграции; эти сведения здесь не подтверждаются.", "source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057908#page=18", "sha256": "250cf4805ff5b41168fbf1ca3a9e17353fcb42cc0470002ca703fc1b3e5691d7", "pdf_page": 18, "source_id": "PEGP-BANK-1057908", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 18, "official_topic": 33, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}], "competency_id": "PEGP-P05-HIS-001-MC", "prerequisites": ["Basic Greek question comprehension", "Read the names and relation in this card"], "delayed_review": {"D7": "Ποιο μεταναστευτικό φαινόμενο συνδέεται με τη δεκαετία 1950–1960;", "D28": "Εξήγησε σε μία φράση γιατί η λέξη «κανένας» δεν ταιριάζει στην κάρτα για την ελληνική μετανάστευση του 1950–1960.", "conditions": "Without card/options; score only requested relation, not literal base key"}, "mastery_criteria": {"fact": "Correct requested factual relation with no contradiction", "observed": false, "retention": "D7 and D28 completed independently; no observations yet", "production": "Independent completion of transfer task"}, "original_example": "Στη δεκαετία 1950–1960 πολλοί Έλληνες έφυγαν στο εξωτερικό.", "practice_item_ids": ["PEGP-P05-HIS-001"], "observable_outcome": "Самостоятельно воспроизвести выбранную связь и применить её в исправлении/объяснении", "independent_transfer": {"prompt_el": "Μια λεζάντα γράφει ότι κανένας Έλληνας δεν μετανάστευσε τη δεκαετία 1950–1960. Διόρθωσέ την χωρίς αριθμούς.", "conditions": "Hide original card and keys; produce own utterance; do not require details absent from prompt.", "model_not_exhaustive": true}, "prerequisite_support": {"probe": "Объясните по-русски, что именно требуется назвать в основном вопросе; затем прочтите ключевые имена.", "remediation": "Разобрать имя, падеж и отношение с русской опорой; закрыть модель перед самостоятельной попыткой."}}, {"rubric": {"0": "Required relation absent/false", "1": "Partial requested information or assistance", "2": "All requested factual information independently conveyed; equivalent wording accepted", "accent_policy": "Tag stress/form errors separately; do not turn correct fact into incorrect fact.", "language_score_separate": true}, "status": "AUTHORED_DRAFT", "card_id": "PEGP-P05-HIS-002-CARD", "item_id": "PEGP-P05-HIS-002", "theory_ru": "Цифлики — крупные земельные владения. В выбранном историческом сюжете после присоединения Фессалии их приобрели состоятельные греки из-за границы. Учебная связь касается этой группы покупателей, а не всех землевладельцев Греции. Не добавляйте дату присоединения: в данной карточке она не проверяется.", "source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057908#page=18", "sha256": "250cf4805ff5b41168fbf1ca3a9e17353fcb42cc0470002ca703fc1b3e5691d7", "pdf_page": 18, "source_id": "PEGP-BANK-1057908", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 18, "official_topic": 34, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}], "competency_id": "PEGP-P05-HIS-002-MC", "prerequisites": ["Basic Greek question comprehension", "Read the names and relation in this card"], "delayed_review": {"D7": "Ποια ομάδα αγόρασε τα μεγάλα αγροκτήματα της Θεσσαλίας μετά την προσάρτηση;", "D28": "Πες με άλλα λόγια ποιοι ήταν οι αγοραστές των τσιφλικιών στην ιστορική κάρτα.", "conditions": "Without card/options; score only requested relation, not literal base key"}, "mastery_criteria": {"fact": "Correct requested factual relation with no contradiction", "observed": false, "retention": "D7 and D28 completed independently; no observations yet", "production": "Independent completion of transfer task"}, "original_example": "Τα θεσσαλικά τσιφλίκια αγοράστηκαν από πλούσιους Έλληνες του εξωτερικού.", "practice_item_ids": ["PEGP-P05-HIS-002"], "observable_outcome": "Самостоятельно воспроизвести выбранную связь и применить её в исправлении/объяснении", "independent_transfer": {"prompt_el": "Διόρθωσε τη σύνοψη «τα μεγάλα θεσσαλικά αγροκτήματα μοιράστηκαν δωρεάν στους επαναστάτες».", "conditions": "Hide original card and keys; produce own utterance; do not require details absent from prompt.", "model_not_exhaustive": true}, "prerequisite_support": {"probe": "Объясните по-русски, что именно требуется назвать в основном вопросе; затем прочтите ключевые имена.", "remediation": "Разобрать имя, падеж и отношение с русской опорой; закрыть модель перед самостоятельной попыткой."}}, {"rubric": {"0": "Required relation absent/false", "1": "Partial requested information or assistance", "2": "All requested factual information independently conveyed; equivalent wording accepted", "accent_policy": "Tag stress/form errors separately; do not turn correct fact into incorrect fact.", "language_score_separate": true}, "status": "AUTHORED_DRAFT", "card_id": "PEGP-P05-HIS-003-CARD", "item_id": "PEGP-P05-HIS-003", "theory_ru": "Две национальные памятные даты в выбранной карточке — 25 марта и 28 октября. Порядок ответа не важен; нужны обе даты, включая месяцы. Не путайте узнавание даты с объяснением всех исторических событий: последнее требует отдельной карточки и источника.", "source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057908#page=19", "sha256": "250cf4805ff5b41168fbf1ca3a9e17353fcb42cc0470002ca703fc1b3e5691d7", "pdf_page": 19, "source_id": "PEGP-BANK-1057908", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 19, "official_topic": 35, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}], "competency_id": "PEGP-P05-HIS-003-MC", "prerequisites": ["Basic Greek question comprehension", "Read the names and relation in this card"], "delayed_review": {"D7": "Ποιες δύο εθνικές επέτειοι μελετήθηκαν;", "D28": "Χωρίς ημερολόγιο, πες τις δύο ημερομηνίες σε έναν φίλο που ετοιμάζει σημειώσεις.", "co