ource_id": "PEGP-BANK-1057908", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 20, "official_topic": 37, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}], "competency_id": "PEGP-P05-HIS-004-MC", "prerequisites": ["Basic Greek question comprehension", "Read the names and relation in this card"], "delayed_review": {"D7": "Με ποιον αιώνα συνδέεται ο πρωθυπουργός Χαρίλαος Τρικούπης στην κάρτα;", "D28": "Οργάνωσε μια καρτέλα με όνομα, πολιτικό αξίωμα και αιώνα για τον Χαρίλαο Τρικούπη.", "conditions": "Without card/options; score only requested relation, not literal base key"}, "mastery_criteria": {"fact": "Correct requested factual relation with no contradiction", "observed": false, "retention": "D7 and D28 completed independently; no observations yet", "production": "Independent completion of transfer task"}, "original_example": "Ο Χαρίλαος Τρικούπης ήταν πρωθυπουργός τον 19ο αιώνα.", "practice_item_ids": ["PEGP-P05-HIS-004"], "observable_outcome": "Самостоятельно воспроизвести выбранную связь и применить её в исправлении/объяснении", "independent_transfer": {"prompt_el": "Μια σημείωση βάζει τον Χαρίλαο Τρικούπη στους πρωθυπουργούς του 20ού αιώνα. Διόρθωσε μόνο τον αιώνα.", "conditions": "Hide original card and keys; produce own utterance; do not require details absent from prompt.", "model_not_exhaustive": true}, "prerequisite_support": {"probe": "Объясните по-русски, что именно требуется назвать в основном вопросе; затем прочтите ключевые имена.", "remediation": "Разобрать имя, падеж и отношение с русской опорой; закрыть модель перед самостоятельной попыткой."}}, {"rubric": {"0": "Required relation absent/false", "1": "Partial requested information or assistance", "2": "All requested factual information independently conveyed; equivalent wording accepted", "accent_policy": "Tag stress/form errors separately; do not turn correct fact into incorrect fact.", "language_score_separate": true}, "status": "AUTHORED_DRAFT", "card_id": "PEGP-P05-CUL-001-CARD", "item_id": "PEGP-P05-CUL-001", "theory_ru": "Проверяемая связь — коронация Константина XI Палеолога в Мистре, в храме Святого Димитрия, 6 января 1449 года. Основное задание спрашивает только место: дата и храм не обязательны для полного балла. Не переносите эту конкретную церемонию на Константинополь лишь из-за титула императора.", "source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057906#page=18", "sha256": "5163ff77c395802de2f24f88cfb65be7cc4681c128c6801e1d6d2566bceaea2d", "pdf_page": 18, "source_id": "PEGP-BANK-1057906", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 18, "official_topic": 29, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}], "competency_id": "PEGP-P05-CUL-001-MC", "prerequisites": ["Basic Greek question comprehension", "Read the names and relation in this card"], "delayed_review": {"D7": "Πού στέφτηκε ο Κωνσταντίνος ΙΑ΄ Παλαιολόγος;", "D28": "Πες σε έναν επισκέπτη ποιος τόπος συνδέεται με τη στέψη του Κωνσταντίνου ΙΑ΄.", "conditions": "Without card/options; score only requested relation, not literal base key"}, "mastery_criteria": {"fact": "Correct requested factual relation with no contradiction", "observed": false, "retention": "D7 and D28 completed independently; no observations yet", "production": "Independent completion of transfer task"}, "original_example": "Η στέψη του Κωνσταντίνου ΙΑ΄ έγινε στον Μυστρά το 1449.", "practice_item_ids": ["PEGP-P05-CUL-001"], "observable_outcome": "Самостоятельно воспроизвести выбранную связь и применить её в исправлении/объяснении", "independent_transfer": {"prompt_el": "Διόρθωσε τη λεζάντα «η στέψη του Κωνσταντίνου ΙΑ΄ έγινε στην Αθήνα», αλλάζοντας μόνο τον τόπο.", "conditions": "Hide original card and keys; produce own utterance; do not require details absent from prompt.", "model_not_exhaustive": true}, "prerequisite_support": {"probe": "Объясните по-русски, что именно требуется назвать в основном вопросе; затем прочтите ключевые имена.", "remediation": "Разобрать имя, падеж и отношение с русской опорой; закрыть модель перед самостоятельной попыткой."}}, {"rubric": {"0": "Required relation absent/false", "1": "Partial requested information or assistance", "2": "All requested factual information independently conveyed; equivalent wording accepted", "accent_policy": "Tag stress/form errors separately; do not turn correct fact into incorrect fact.", "language_score_separate": true}, "status": "AUTHORED_DRAFT", "card_id": "PEGP-P05-CUL-002-CARD", "item_id": "PEGP-P05-CUL-002", "theory_ru": "Неоклассицизм обращается к элементам древнегреческой архитектуры; в источнике выделены колонны преимущественно с ионическими капителями. Слово «преимущественно» важно: это не запрет других ордеров. Карточка даёт словесный признак, но не заменяет распознавание зданий на фотографии. Изображения официального задания не копируются без подтверждения прав.", "source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057906#page=19", "sha256": "5163ff77c395802de2f24f88cfb65be7cc4681c128c6801e1d6d2566bceaea2d", "pdf_page": 19, "source_id": "PEGP-BANK-1057906", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 19, "official_topic": 31, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}], "competency_id": "PEGP-P05-CUL-002-MC", "prerequisites": ["Basic Greek question comprehension", "Read the names and relation in this card"], "delayed_review": {"D7": "Ποιο στοιχείο της αρχαίας αρχιτεκτονικής επανεμφανίζεται στην περιγραφή του Νεοκλασικισμού;", "D28": "Εξήγησε γιατί η λέξη «κυρίως» δεν σημαίνει «αποκλειστικά»