5275	singleton	context_example_fixture	66d0a8c124ee67fbcdb8148725e35565198a116708eb85911865172fc6436848	\N	{"path": "LEARNING_CONTEXT/V5_2/fixtures/context_example.json", "payload": {"id": "UX-DEMO-CONTEXT-001", "tts": null, "level": "A2", "dialogue": [{"greek": "Τι έκανες χθες το βράδυ;", "russian": "Что ты делал вчера вечером?", "speaker": "A"}, {"greek": "Διάβαζα όταν με πήρε τηλέφωνο η Μαρία.", "russian": "Я читал, когда мне позвонила Мария.", "speaker": "B"}], "error_type": "ASPECT_BACKGROUND_EVENT", "greek_text": "Διάβαζα ένα βιβλίο όταν χτύπησε το τηλέφωνο.", "source_kind": "original_educational", "audio_status": "AUDIO_PENDING", "competency_id": "PENDING_CANONICAL_COMPETENCY_ID", "license_proof": null, "review_status": "CONTENT_GATED", "content_version": 1, "transfer_prompt": {"question_ru": "Пока я готовил, зазвонил телефон. Выбери форму для длительного действия.", "variants_gr": [], "canonical_answer_gr": "Μαγείρευα"}, "source_reference": null, "russian_explanation": "Чтение уже происходило, когда зазвонил телефон. Для процесса используется παρατατικός."}}	fa1d2338-6c24-4ed0-a237-31b71680652c	2026-10-29 03:24:11.938033+00
