D-A1-LISTENING-01-AUD01	AUDIO_PENDING_EXTERNAL_EXECUTION	2	99b9de43334a3ba49db269970b68ac571cdb6c369813e46b969bb2211332ec19	Δάφνη: Το μάθημα αρχίζει στις πέντε;\nΟρέστης: Όχι, σήμερα αρχίζει στις έξι.\nΔάφνη: Στις έξι, εντάξει. Θα είμαι εκεί.	[{"text_el": "Το μάθημα αρχίζει στις πέντε;", "segment_id": "D-A1-LISTENING-01-AUD01-C01", "speaker_role": "Δάφνη", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Όχι, σήμερα αρχίζει στις έξι.", "segment_id": "D-A1-LISTENING-01-AUD01-C02", "speaker_role": "Ορέστης", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Στις έξι, εντάξει. Θα είμαι εκεί.", "segment_id": "D-A1-LISTENING-01-AUD01-C03", "speaker_role": "Δάφνη", "measured_end_ms": null, "measured_start_ms": null}]	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": null, "licence": null, "text_el": "Δάφνη: Το μάθημα αρχίζει στις πέντε;\\nΟρέστης: Όχι, σήμερα αρχίζει στις έξι.\\nΔάφνη: Στις έξι, εντάξει. Θα είμαι εκεί.", "version": "0.1.0", "audio_id": "D-A1-LISTENING-01-AUD01", "priority": 2, "register": ["standard_modern_greek", "context_of_source_script"], "segments": [{"text_el": "Το μάθημα αρχίζει στις πέντε;", "segment_id": "D-A1-LISTENING-01-AUD01-C01", "speaker_role": "Δάφνη", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Όχι, σήμερα αρχίζει στις έξι.", "segment_id": "D-A1-LISTENING-01-AUD01-C02", "speaker_role": "Ορέστης", "measured_end_ms": null, "measured_start_ms": null}, {"text_el": "Στις έξι, εντάξει. Θα είμαι εκεί.", "segment_id": "D-A1-LISTENING-01-AUD01-C03", "speaker_role": "Δάφνη", "measured_end_ms": null, "measured_start_ms": null}], "output_path": null, "speaker_role": ["Δάφνη", "Ορέστης"], "verification": {"file_decoded": false, "AUDIO_VERIFIED": false, "HUMAN_VERIFIED": false, "actually_listened": false, "blind_independent_listening": false}, "measured_cues": [], "native_review": {"status": "PENDING", "reviewer_id": null, "evidence_path": null}, "script_rights": {"scope": "Original project