01-SEG006", "speaker_role": "B"}, {"end_ms": null, "text_el": "Τι ώρα;", "start_ms": null, "segment_id": "U-A2-014-AUD01-SEG007", "speaker_role": "A"}, {"end_ms": null, "text_el": "Δεν ξέρω ακόμη.", "start_ms": null, "segment_id": "U-A2-014-AUD01-SEG008", "speaker_role": "B"}], "pronunciation_notes": "Preserve lexical stress, elision, clitics and contrastive negation. Read all numbers in full; do not exaggerate answer-bearing words.", "script_version_hash": "b72aa36dab5641cac2260d9579dd296a7f6a374fa8de0aa8c476046f3f344969", "execution_script_txt": "AUDIO_EXECUTION_PACK/scripts/U-A2-014-AUD01.txt", "source_manifest_hash": "ffca9b55d400f22c9483be752057b2875067ec08054921692369c35e2be11941", "source_manifest_path": "GreekOS_Audio_and_Speaking/assets/U-A2-014-AUD01.json", "planned_delivery_path": "AUDIO/media/U-A2-014-AUD01/delivery.mp3", "expected_prompt_context": {"delivery": "audio-only attempt before transcript; accessible transcript is reading support, not listening score", "linked_tasks": 2, "register_note": "Original GreekOS teaching script; not authentic field recording", "speaker_labels_not_spoken": true}, "intonation_instructions": "Preserve question/statement and negation distinctions; do not add answer clues. Same role keeps a consistent voice.", "source_script_file_hash": "ffca9b55d400f22c9483be752057b2875067ec08054921692369c35e2be11941", "production_segment_policy": "Only recognized role labels removed; punctuation inside utterances retained. Producer must confirm turn boundaries before recording. No role labels spoken. Timing fields deliberately null.", "execution_script_txt_sha256": "7d942091953c783b42a22230a1db4b67a814c9877a3d65b3c8a5cd3826984787"}	e57ba4fa84df87da272f0c56e5fc4980e1f91100455a69dbf4342da249dbaf0e	3261
