U-B2-012-AUD00	AUDIO_PENDING_EXTERNAL_EXECUTION	CORE_AFTER_L01	a416302b54d2f868899f27f67247be84c43387715c5e4a7304618b762ba1c488	Αρχικά είπαμε στις έξι, αλλά θα βρεθούμε στις επτά, επειδή δουλεύω μέχρι τις έξι και μισή.	[]	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": {"status": "EVIDENCE_REQUIRED"}, "licence": {"status": "UNRESOLVED_VOICE_AND_MEDIA_RIGHTS"}, "text_el": "Αρχικά είπαμε στις έξι, αλλά θα βρεθούμε στις επτά, επειδή δουλεύω μέχρι τις έξι και μισή.", "version": "0.1.0", "audio_id": "U-B2-012-AUD00", "priority": "CORE_AFTER_L01", "register": "standard neutral Greek", "segments": [], "output_path": null, "speaker_role": ["narrator"], "verification": {"status": "NOT_EXECUTED"}, "measured_cues": [], "native_review": {"status": "PENDING", "reviewer": null}, "script_rights": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "speaking_rate": "Natural B2 for developed talk; B1 diagnostic and prosody at clear natural pace. No measured rate until recorded.", "voice_profile": {"locale": "el-GR", "identity": "GENERIC_CONSENTED_VOICE", "selection": "PRODUCER_NATIVE_APPROVAL_REQUIRED"}, "state_evidence": {"status": "SCRIPT_ONLY"}, "task_alignment": [{"item_id": "U-B2-012-I01", "item_path": "GreekOS_Academic_Corpus/items/U-B2-012-I01.json", "cue_status": "UNMEASURED_NO_AUDIO", "item_sha256": "98111040b9a7c6c659ca6b376f9a3c75cb2d6e2b35883ccc6c01aaa3fc339a66", "text_alignment_status": "CURRENT_ITEM_REFERENCE_ONLY_NOT_ACOUSTICALLY_VERIFIED"}], "verification_hash": null, "actual_duration_ms": null, "source_script_path": "GreekOS_Audio_and_Speaking/assets/U-B2-012-AUD00.json", "planned_output_path": "AUDIO/media/U-B2-012-AUD00.wav", "production_segments": [{"end_ms": null, "text_el": "Αρχικά είπαμε στις έξι, αλλά θα βρεθούμε στις επτά, επειδή δουλεύω μέχρι τις έξι και μισή.", "start_ms": null, "segment_id": "U-B2-012-AUD00-SEG001", "speaker_role": "narrator"}], "pronunciation_notes": "Preserve Greek lexical stress; no answer-leaking emphasis except explicitly assessed contrast, which requires blind native validation.", "script_version_hash": "a416302b54d2f868899f27f67247be84c43387715c5e4a7304618b762ba1c488", "execution_script_txt": "AUDIO_EXECUTION_PACK/scripts/U-B2-012-AUD00.txt", "source_manifest_hash": "0661421b8b4aaf28d6f587d0b5f3af1efcbea6e973cfbad5129e6a71af8d5f95", "source_manifest_path": "GreekOS_Audio_and_Speaking/assets/U-B2-012-AUD00.json", "planned_delivery_path": "AUDIO/media/U-B2-012-AUD00.mp3", "expected_prompt_context": {"unit_id": "U-B2-012", "task_ids": ["U-B2-012-I01"]}, "intonation_instructions": "Neutral clear B1 prerequisite probe; no answer emphasis. Hide transcript; native review and sound required.", "source_script_file_hash": "0661421b8b4aaf28d6f587d0b5f3af1efcbea6e973cfbad5129e6a71af8d5f95", "production_segment_policy": "Only recognized role labels removed; punctuation inside utterances retained. Producer must confirm turn boundaries before recording. No role labels spoken. Timing fields deliberately null.", "execution_script_txt_sha256": "9f9cb87a8d6c721f47422cbeb345be254bcba6c2f3c01613ec10c80b3992a088"}	114399b59586e89394946436878cbeca43552984518090d80e9075d8981aa613	3323
U-B2-015-AUD01	AUDIO_PENDING_EXTERNAL_EXECUTION	CORE_AFTER_L01	8fe3ae277fb2cb92dbba54dc7fa0962aaf2a2bb84f4e2a656941b5e6540a97ac	Άννα: Ευχαριστώ που ήρθατε. Πρέπει να προτείνουμε πώς θα λειτουργήσει η αίθουσα της γειτονιάς τον επόμενο μήνα. Έχουμε δύο ελεύθερα απογεύματα, την Τρίτη και την Πέμπτη. Αρχικά σκέφτηκα να κάνουμε προβολές ταινιών και τις δύο ημέρες, αλλά θα ήθελα να ακούσω τις ανάγκες σας πριν αποφασίσουμε.\nΜάνος: Οι προβολές είναι ωραία ιδέα, όμως υπάρχουν μαθητές που ψάχνουν ήσυχο χώρο για διάβασμα. Στο σπίτι δεν έχουν όλοι δικό τους δωμάτιο. Θα πρότεινα η Τρίτη να μείνει για ατομική μελέτη. Δεν χρειάζεται να αγοράσουμε πολλά πράγματα· υπάρχουν ήδη τραπέζια και καρέκλες.\nΕλένη: Συμφωνώ ότι η μελέτη είναι σημαντική, αλλά θέλω να προσέξουμε τον φωτισμό. Δύο λάμπες δεν λειτουργούν. Αν δεν επισκευαστούν, δεν θα έλεγα ότι ο χώρος είναι έτοιμος. Επίσης, όποιος αναλάβει την επίβλεψη πρέπει να ξέρει πού βρίσκονται τα κλειδιά και πώς κλείνει το κτίριο.\nΠέτρος: Εγώ μπορώ να βοηθήσω την Τρίτη, όχι όμως κάθε εβδομάδα. Η δουλειά μου αλλάζει ωράριο. Αν στηριχτούμε μόνο σε εμένα, κάποια μέρα μπορεί να μη βρεθεί κανείς να ανοίξει. Θα προτιμούσα να υπάρχει δεύτερος υπεύθυνος και ένα κοινό πρόγραμμα, το οποίο να ελέγχουμε λίγες ημέρες πριν.\nΆννα: Άρα δεν αρκεί να διαλέξουμε δραστηριότητα. Πρέπει να εξασφαλίσουμε και ότι ο χώρος θα ανοίγει κανονικά. Για την Πέμπτη θα μπορούσαμε να κρατήσουμε μια πολιτιστική δραστηριότητα. Τι θα λέγατε για συζήτηση γύρω από μια ταινία, χωρίς δυνατή μουσική μετά;\nΜάνος: Αυτό μου φαίνεται πιο λογικό από δύο ίδιες βραδιές. Θα ήθελα όμως να μην αλλάζει η χρήση της Τρίτης τελευταία στιγμή. Αν οι μαθητές υπολογίζουν ότι θα διαβάσουν εδώ, μια ξαφνική προβολή θα τους δημιουργήσει πρόβλημα. Οι αλλαγές πρέπει να ανακοινώνονται εγκαίρως.\nΕλένη: Δεν έχω αντίρρηση για την Πέμπτη. Προτείνω μόνο να αρχίσουμε με μία δοκιμαστική συνάντηση. Δεν ξέρουμε ακόμη πόσοι θα έρθουν ούτε αν ο προβολέας λειτουργεί σωστά. Μπορώ να τον ελέγξω αύριο, αλλά δεν μπορώ να αναλάβω όλες τις τεχνικές ανάγκες του μήνα.\nΠέτρος: Αν γίνει δοκιμή, θα μπορούσαμε να ζητήσουμε σύντομα σχόλια. Όχι μόνο αν άρεσε η ταινία, αλλά αν η ώρα και ο χώρος ήταν κατάλληλα. Και για τη μελέτη θα ήταν χρήσιμο να ακούσουμε όσους ήρθαν αλλά δεν βρήκαν θέση. Αλλιώς θα μετράμε μόνο τους ικανοποιημένους.\nΆννα: Να συνοψίσω λοιπόν την πρόταση, όχι να την παρουσιάσω ως οριστική απόφαση. Την Τρίτη προτείνουμε μελέτη, εφόσον διορθωθεί ο φωτισμός και βρεθούν δύο υπεύθυνοι. Την Πέμπτη προτείνουμε μία δοκιμαστική πολιτιστική συνάντηση, αφού ελεγχθεί ο προβολέας. Θα στείλουμε το σχέδιο στην επιτροπή του κτιρίου για έγκριση.\nΜάνος: Συμφωνώ με αυτή τη διατύπωση. Να γράψουμε καθαρά ότι περιμένουμε έγκριση, για να μην εμφανιστούν άνθρωποι πριν είμαστε έτοιμοι.\nΕλένη: Θα στείλω αύριο το αποτέλεσμα του τεχνικού ελέγχου. Αν υπάρχει σοβαρή βλάβη, θα χρειαστούμε άλλη λύση.\nΠέτρος: Κι εγώ θα ρωτήσω ποιος μπορεί να μοιραστεί την επίβλεψη. Μέχρι να έχουμε απάντηση, ας μην υποσχεθούμε συγκεκριμένη ημερομηνία έναρξης.	[]	{"status": "AUDIO_PENDING_EXTERNAL_EXECUTION", "consent": {"status": "EVIDENCE_REQUIRED"}, "licence": {"status": "UNRESOLVED_VOICE_AND_MEDIA_RIGHTS"}, "text_el": "Άννα: Ευχαριστώ που ήρθατε. Πρέπει να προτείνουμε πώς θα λειτουργήσει η αίθουσα της γειτονιάς τον επόμενο μήνα. Έχουμε δύο ελεύθερα απογεύματα, την Τρίτη και την Πέμπτη. Αρχικά σκέφτηκα να κάνουμε προβολές ταινιών και τις δύο ημέρες, αλλά θα ήθελα να ακούσω τις ανάγκες σας πριν αποφασίσουμε.\\nΜάνος: Οι προβολές είναι ωραία ιδέα, όμως υπάρχουν μαθητές που ψάχνουν ήσυχο χώρο για διάβασμα. Στο σπίτι δεν έχουν όλοι δικό τους δωμάτιο. Θα πρότεινα η Τρίτη να μείνει για ατομική μελέτη. Δεν χρειάζεται να αγοράσουμε πολλά πράγματα· υπάρχουν ήδη τραπέζια και καρέκλες.\\nΕλένη: Συμφωνώ ότι η μελέτη είναι σημαντική, αλλά θέλω να προσέξουμε τον φωτισμό. Δύο λάμπες δεν λειτουργούν. Αν δεν επισκευαστούν, δεν θα έλεγα ότι ο χώρος είναι έτοιμος. Επίσης, όποιος αναλάβει την επίβλεψη πρέπει να ξέρει πού βρίσκονται τα κ