U-B1-021-RUBRIC	[{"path": "GreekOS_Academic_Corpus/rubrics/U-B1-021-RUBRIC.json", "sha256": "029736b352605ea90448aafd6d713086609116f6070fca7e46713cb67632ba33", "pointer": ""}]	{"scale": {"0": "Required meaning absent/contradicted", "1": "Meaning partly conveyed or achieved with prompt/model", "2": "Criterion independently achieved in intelligible context-appropriate Greek"}, "version": "0.1.0", "feedback": "Name achieved criterion, quote one mismatch, explain effect on meaning, request self-correction before showing model", "no_score": ["No sound for acoustic criterion", "ASR uncertainty", "Technical interruption"], "procedure": "Score each listed criterion separately, quote evidence; separate content/linguistic/acoustic observations. Do not reward merely copying the model.", "rubric_id": "U-B1-021-RUBRIC", "human_review": "PENDING", "valid_variants": "Semantically adequate paraphrases accepted; models illustrative, not exhaustive", "criteria_by_item": {"U-B1-021-I01": ["понятны εισιτήριο/τραπέζι", "нет произвольного переноса ударения", "сообщение целое"], "U-B1-021-I05": ["граница условия", "не разорваны тесные словосочетания"], "U-B1-021-I06": ["день исправлен", "контраст понятен слушателю", "словесные ударения сохранены"], "U-B1-021-I07": ["условие дождя", "внутреннее помещение", "понятная связь частей"], "U-B1-021-I08": ["кто/когда/что", "слышен контраст лица", "запись самостоятельная"], "U-B1-021-I09": ["две условные ветки", "ясная поправка19:00", "смысловые группы", "слушатель восстановил сообщение"], "U-B1-021-I10": ["три вместо двух", "слышное противопоставление", "правильное словесное ударение"], "U-B1-021-I11": ["условие", "ясное окончательное время", "понятная самопоправка", "совпадение деталей у слушателя"]}, "mastery_proposal": "All task-critical facts/functions at 2 and independent transfer; two different contexts; D7 and D28 independently repeated. Author proposal, not calibrated CEFR cutoff."}	b0457936772f4cb87220b819f03f54c4b653486e1c2a03b9b0388179df23302c	2965
KEG-B2-U03-T1	[{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-U03-T1.json", "sha256": "e33607abb73d5338119bb9e5fe45f6e991477d05ee2647aed47896e2e616abe3", "pointer": ""}]	{"text": "(0) Η ομάδα θέλει ότι να συνεργαστεί. Παράδειγμα: αφαιρείται το «ότι».\\n\\n(1) Η οργανωτική ομάδα του φεστιβάλ αποφάσισε να προσθέσει υπότιτλους στις μικρές ταινίες. Η αλλαγή δεν αφορούσε μόνο ξενόγλωσσα έργα, αλλά και ελληνικές παραγωγές, ώστε να γίνουν προσβάσιμες σε ότι περισσότερους θεατές.\\n\\n(2) Πριν αρχίσει η εργασία, ζητήθηκε από τους δημιουργούς να εγκρίνουν τη χρήση των διαλόγων. Οι υπεύθυνοι διευκρίνισαν ότι η άδεια προβολής δεν σήμαινε αυτομάτως ότι και άδεια αλλαγής του υπάρχοντος υλικού.\\n\\n(3) Κάθε εθελοντής ανέλαβε ένα σύντομο απόσπασμα, το οποίο θα ελεγχόταν από δεύτερο άτομο. Η ομάδα προτίμησε αυτή τη διαδικασία από να την απλή συγκέντρωση πολλών ανεξάρτητων μεταγραφών χωρίς κοινά κριτήρια ελέγχου.\\n\\n(4) Οι διάλογοι έπρεπε να διαβάζονται εύκολα, χωρίς να χάνεται ο χαρακτήρας της ομιλίας. Δεν ήταν αρκετό να αποδοθούν σωστά οι λέξεις· χρειαζόταν επίσης προσοχή για στον χρόνο που παρέμενε κάθε υπότιτλος στην οθόνη.\\n\\n(5) Σε μια δοκιμαστική προβολή, οι θεατές σημείωσαν σημεία που δεν προλάβαιναν να διαβάσουν. Οι παρατηρήσεις τους οδήγησαν σε διορθώσεις, παρόλο που η ομάδα είχε ήδη αφιερώσει αρκετές ώρες από στον αρχικό έλεγχο.\\n\\n(6) Οι συντελεστές απέφυγαν να θεωρήσουν τις αλλαγές προσωπική κριτική. Αντίθετα, συζήτησαν για το πώς θα μπορούσαν να βελτιώσουν το αποτέλεσμα, διατηρώντας σημειώσεις ώστε για η επόμενη παραγωγή να ξεκινήσει με σαφέστερες οδηγίες.\\n\\n(7) Μετά το φεστιβάλ, η ομάδα κράτησε τις εγκεκριμένες εκδοχές σε κοινό αρχείο. Η πρόσβαση δόθηκε μόνο σε όσους είχαν συγκεκριμένη εργασία να ολοκληρώσουν, επειδή ότι η μελλοντική χρήση απαιτούσε νέα συνεννόηση με τους δημιουργούς. Οι καταγραφές περιλάμβαναν επίσης την ημερομηνία κάθε έγκρισης και το όνομα του υπευθύνου.", "status": "AUTHOR_COMPLETE_AI_REVIEW_PENDING", "text_id": "KEG-B2-U03-T1", "version": "0.1.1", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "word_count": 247}	d989700c562c84f0a0cf4d7cc27d901e6e5bb4efeb665e407657152f9123b63e	3029
KEG-B2-U03-T2	[{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-U03-T2.json", "sha256": "4f4f442a3ef400cfebd40401aadd338559eeb3e8981bc5fb5b16305cd3afc104", "pointer": ""}]	{"text": "Όταν ανέλαβα την κουζίνα ενός μικρού ξενώνα, με εντυπωσίασε η (0) ___ της ομάδας να δοκιμάσει αλλαγές. Δεν ήθελα να μειώσω τις μερίδες ούτε να περιορίσω τις επιλογές χωρίς συζήτηση. Με απασχολούσαν κυρίως όσα τρόφιμα αγοράζονταν αλλά τελικά δεν χρησιμοποιούνταν.\\nΞεκινήσαμε με μια απλή (1) ___ των ποσοτήτων που περίσσευαν. Δεν καταγράφαμε ονόματα πελατών ή προσωπικές προτιμήσεις. Παρατηρούσαμε μόνο ποια υλικά έμεναν συστηματικά στο τέλος κάθε ημέρας και ποια τελείωναν πριν εξυπηρετηθούν όλοι. Οι πρώτες σημειώσεις έδειξαν ότι η εικόνα διέφερε ανάμεσα στις καθημερινές και στο σαββατοκύριακο.\\nΗ (2) ___ του νέου προγράμματος απαιτούσε συνεργασία με τους προμηθευτές. Ζητήσαμε μικρότερες αλλά συχνότερες παραδόσεις, χωρίς να θεωρούμε δεδομένο ότι όλοι μπορούσαν να αλλάξουν αμέσως τον τρόπο εργασίας τους. Έπρεπε να συμφωνήσουμε σε (3) ___ όρους, ώστε να γνωρίζουμε ποιος αναλάμβανε κάθε έξοδο.\\nΠαράλληλα, οργανώσαμε καλύτερα την αποθήκη. Μια ευδιάκριτη σήμανση έκανε τον έλεγχο πιο (4) ___ και περιόριζε τις άσκοπες αναζητήσεις. Οι εργαζόμενοι δεν χρειαζόταν πλέον να θυμούνται ποιος είχε μετακινήσει κάθε κιβώτιο. Η σειρά χρήσης των προϊόντων γινόταν σαφής σε όποιον άρχιζε τη βάρδια του.\\nΗ αλλαγή δεν στηρίχθηκε σε μια εντυπωσιακή υπόσχεση άμεσου κέρδους. Χρειάστηκε (5) ___ παρακολούθηση και προσαρμογή, ιδιαίτερα όταν άλλαξε ο αριθμός των επισκεπτών. Κάθε εβδομάδα συζητούσαμε τι λειτούργησε και τι δυσκόλεψε την ομάδα, χωρίς να αναζητούμε κάποιον για να κατηγορήσουμε.\\nΤελικά, θεωρήσαμε σημαντικότερη τη (6) ___ της διαδικασίας παρά έναν μεμονωμένο καλό αριθμό. Θέλαμε μια πρακτική που θα μπορούσε να διατηρηθεί και όταν ο αρχικός ενθουσιασμός θα είχε υποχωρήσει. Οι απλές οδηγίες έμειναν διαθέσιμες και για όσους θα προσλαμβάνονταν αργότερα.", "status": "AUTHOR_COMPLETE_AI_REVIEW_PENDING", "text_id": "KEG-B2-U03-T2", "version": "0.1.1", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "word_count": 241}	86080c690925f07e32d4cde157d5c1689da650bd9230a099937e8b78a9691d91	3030
KEG-B2-R03-SUMMARY	[{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-R03-SUMMARY.json", "sha256": "9ce4d8be68b142a2b91b00e9f2a641caa3e599c9cf66a52f236421098a6b34ef", "pointer": ""}]	{"text": "Ο αφηγητής εργάστηκε για ένα (0) καλοκαίρι στον ξενώνα της θείας του. Μια οικογένεια είχε ζητήσει δωμάτιο στο (1) ___, αλλά η καταχώριση ήταν διαφορετική. Το λάθος αποκαλύφθηκε όταν εξετάστηκε το μήνυμα (2) ___. Η θεία πρότεινε διαμονή σε άλλο κατάλυμα και ανέλαβε τη διαφορά (3) ___. Έπειτα συμφώνησαν σε κατάλογο που όριζε πότε ο αφηγητής θα ζητούσε (4) ___. Για τις καθημερινές ανάγκες των επισκεπτών δημιούργησε φύλλο πληροφοριών και βελτίωσε τον (5) ___ του. Με μια αλλόγλωσση ταξιδιώτισσα χρησιμοποίησε απλές φράσεις και έγραψε τις ώρες σε (6) ___. Στο τέλος προτίμησε εργασία σχετική με τις (7) ___ του, αναγνωρίζοντας την αξία όσων είχε μάθει.", "status": "AUTHOR_COMPLETE_AI_REVIEW_PENDING", "text_id": "KEG-B2-R03-SUMMARY", "version": "0.1.0", "based_on": "KEG-B2-R03-TEXT2", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "word_count": 90}	2242ba62ddb29f82a4bbe52202580b26c3913b011ed5f0a401e16a09da5a8b21	3031
KEG-B2-U01-TEXT2	[{"path": "GreekOS_B2_Exam_Bank/texts/KEG-B2-U01-TEXT2.json", "sha256": "c7d4493889ad4808abb316e55ae053384f339edcd316304396394d82c39d7dc5", "pointer": ""}]	{"text": "Όταν μια ομάδα εθελοντών ανέλαβε να οργανώσει μια μικρή έκθεση φωτογραφίας, έδωσε ιδιαίτερη προσοχή στην (0) ___ του χώρου. Δεν αρκούσε να τοποθετήσει εικόνες στους τοίχους. Έπρεπε να σκεφτεί πώς θα κινούνταν οι επισκέπτες και πώς θα καταλάβαιναν τη σχέση ανάμεσα στις διαφορετικές ενότητες.\\nΗ πρώτη (1) ___ των μελών αφορούσε τη σειρά των εικόνων. Άλλοι προτιμούσαν τη χρονολογική παρουσίαση και άλλοι μια θεματική διαδρομή. Ύστερα από συζήτηση συμφώνησαν να συνδυάσουν τις δύο προσεγγίσεις, διατηρώντας όμως σύντομες και σαφείς εξηγήσεις.\\nΓια να γίνει η έκθεση πιο (2) ___ σε ανθρώπους με διαφορετικές ανάγκες, οι λεζάντες γράφτηκαν με μεγάλα γράμματα και τοποθετήθηκαν σε ύψος που μπορούσαν να διαβάσουν περισσότεροι επισκέπτες. Η ομάδα ζήτησε επίσης τη (3) ___ ενός εκπαιδευτικού για την προετοιμασία μιας δραστηριότητας για παιδιά.\\nΗ (4) ___ του εγχειρήματος δεν θα μετριόταν μόνο από τον αριθμό όσων θα έμπαιναν στην αίθουσα. Οι οργανωτές ήθελαν να μάθουν αν οι επισκέπτες κατανοούσαν το θέμα και αν ένιωθαν ότι μπορούσαν να συμμετέχουν στη συζήτηση. Γι’ αυτό ετοίμασαν ένα σύντομο ερωτηματολόγιο, χωρίς να ζητούν προσωπικά στοιχεία.\\nΜετά την πρώτη ημέρα, μια (5) ___ παρατήρηση οδήγησε σε αλλαγή της διαδρομής: δύο λεζάντες δεν φαίνονταν όταν ο χώρος γέμιζε. Η ομάδα τις μετέφερε και συνέχισε να συγκεντρώνει σχόλια. Η τελική (6) ___ θα γινόταν αφού ολοκληρωνόταν η έκθεση, ώστε να ληφθούν υπόψη τόσο οι θετικές εμπειρίες όσο και οι δυσκολίες που είχαν παρουσιαστεί στην πράξη. Οι επισκέπτες μπορούσαν επίσης να αφήσουν ανώνυμα σχόλια για τη σειρά των εικόνων, χωρίς να συμπληρώσουν ολόκληρο το έντυπο.", "format": "word_formation_mcq", "status": "DRAFT", "example": {"gap": "0", "answer": "οργάνωση"}, "text_id": "KEG-B2-U01-TEXT2", "version": "0.1.0", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "surface_greek_word_count": 235}	ef2544f9e26a6cab909ed3508ceee6a31569a23a73d4fa6b478d2259eed915bc	3032
