PEGP-LANG-P05-T01	[{"path": "GreekOS_PEGP_Module/language_support/PEGP-LANG-P05.json", "sha256": "c93a45d1232e3a5e12f90bd8117687a8ef64122916e844fa938781f922e304a6", "pointer": "/stimuli/0"}]	{"origin": "ORIGINAL_GREEKOS_TEXT", "text_el": "Η ομάδα μας ετοιμάζει μια μικρή εκπαιδευτική έκθεση με θέμα «Τόποι και δημιουργοί». Στο πρώτο τραπέζι θα υπάρχουν κάρτες γεωγραφίας. Μία εξηγεί ότι ο Πηνειός διαρρέει την πεδιάδα της Θεσσαλίας. Μια άλλη συνδέει την Ορεστιάδα με την Περιφερειακή Ενότητα Έβρου. Οι επισκέπτες θα διαβάζουν τις κάρτες και θα διορθώνουν δύο λανθασμένες προτάσεις.\\nΣτο δεύτερο τραπέζι θα συζητήσουμε δύο έργα: την «Κοιμωμένη» του Γιαννούλη Χαλεπά και τις «Ομπρέλες» του Γιώργου Ζογγολόπουλου. Δεν θα χρησιμοποιήσουμε φωτογραφίες, επειδή δεν έχουμε ακόμη άδεια για τη χρήση τους. Θα εργαστούμε μόνο με σύντομα δικά μας κείμενα. Επομένως, η δραστηριότητα θα ελέγχει τη σύνδεση τίτλου και δημιουργού, όχι την αναγνώριση εικόνων.\\nΗ συνάντηση της ομάδας θα γίνει την Παρασκευή στις έξι, στην αίθουσα δύο. Αυτή είναι προετοιμασία για την έκθεση, όχι η ημέρα που θα την επισκεφτεί το κοινό. Η ημερομηνία της έκθεσης δεν έχει αποφασιστεί. Όποιος θέλει να βοηθήσει ας μας στείλει ένα σύντομο μήνυμα μέχρι την Πέμπτη, αναφέροντας ποιο τραπέζι προτιμά και γιατί.", "stimulus_id": "PEGP-LANG-P05-T01", "facts_source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057909#page=18", "sha256": "b2c569c8349c9150d4a96bf685647657d66bfc7ba08e12b02badddaf301e869a", "pdf_page": 18, "source_id": "PEGP-BANK-1057909", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 18, "official_topic": 38, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}, {"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057909#page=20", "sha256": "b2c569c8349c9150d4a96bf685647657d66bfc7ba08e12b02badddaf301e869a", "pdf_page": 20, "source_id": "PEGP-BANK-1057909", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 20, "official_topic": 42, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}, {"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057906#page=21", "sha256": "5163ff77c395802de2f24f88cfb65be7cc4681c128c6801e1d6d2566bceaea2d", "pdf_page": 21, "source_id": "PEGP-BANK-1057906", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 21, "official_topic": 33, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}, {"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057906#page=21", "sha256": "5163ff77c395802de2f24f88cfb65be7cc4681c128c6801e1d6d2566bceaea2d", "pdf_page": 21, "source_id": "PEGP-BANK-1057906", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 21, "official_topic": 33, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}], "fictional_details": ["group", "exhibition", "Friday preparation", "room2", "Thursday deadline"]}	6d7e7b96c0a07013d60cbd280298136be8b763f2299939018ad463a14fa4492d	3043
PEGP-LANG-P06-T01	[{"path": "GreekOS_PEGP_Module/language_support/texts/PEGP-LANG-P06-T01.json", "sha256": "d61e5b07a4289cd1c2b25b75961e28069871e4cdab51322988bdd362d8ab4fc9", "pointer": ""}]	{"status": "ORIGINAL_DRAFT", "text_el": "Η ομάδα μελέτης θα συναντηθεί την Παρασκευή στις έξι το απόγευμα στην αίθουσα δύο. Πρώτα θα χωρίσουμε μερικά τοπωνύμια σε ηπειρωτικές και νησιωτικές περιοχές. Η Σίφνος και η Σύρος ανήκουν στη νησιωτική Ελλάδα, ενώ η Καρδίτσα και τα Γρεβενά στην ηπειρωτική. Μετά θα διαβάσουμε μια σύντομη σημείωση για το Νομισματικό Μουσείο και την παλιά κατοικία του Σλήμαν. Δεν θα χρησιμοποιήσουμε φωτογραφίες, επειδή δεν έχουμε ελέγξει τα δικαιώματα χρήσης τους. Κάθε μέλος θα εξηγήσει έναν από τους όρους με δικά του λόγια. Η συνάντηση είναι άσκηση προετοιμασίας της ομάδας, όχι επίσημη εξέταση.", "text_id": "PEGP-LANG-P06-T01", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "fact_source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057909#page=22", "sha256": "b2c569c8349c9150d4a96bf685647657d66bfc7ba08e12b02badddaf301e869a", "pdf_page": 22, "source_id": "PEGP-BANK-1057909", "checked_on": "2026-10-21", "bank_version": "2026/11", "printed_page": 22, "official_topic": 46, "verification_scope": "Selected fact read in retained official PDF text and visually rendered page. Not fresh download, whole-bank audit or legal-rule verification."}, {"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057906#page=22", "sha256": "5163ff77c395802de2f24f88cfb65be7cc4681c128c6801e1d6d2566bceaea2d", "pdf_page": 22, "source_id": "PEGP-BANK-1057906", "checked_on": "2026-10-21", "bank_version": "2026/11", "printed_page": 22, "official_topic": 34, "verification_scope": "Selected fact read in retained official PDF text and visually rendered page. Not fresh download, whole-bank audit or legal-rule verification."}], "fictional_details": "Time, room, study group and procedure are original fictional context, not official exam information"}	f2cb157753c74c5ff89f29162c2c1c36bc523b9036c1699ce3032dfbd146d556	3044
