SC44	[{"path": "GreekOS_Audio_and_Speaking/scenarios/SC44.json", "sha256": "e90838bd3c3d87c0a7391021d05e175312f2ec5a33cda0eb9eccd87ffc2c78ba", "pointer": ""}]	{"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "COMPLETE_CONTENT_READ_BY_AUTHOR_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PRIOR_REVIEW_FOUND_ISSUES_REVIEWER_APPLIED_PATCH_PENDING_ROOT_DELTA"}, "nodes": [{"node_id": "OPEN", "transitions": [{"to": "TWIST", "condition": "Semantic goal achieved with independently formulated response; any suitable wording accepted"}, {"to": "REPAIR", "condition": "Unclear response, explicit clarification or transcript uncertainty"}], "assistant_el": "Η πρόταση που συζητήσαμε αφορά την επέκταση του ωραρίου για έναν δοκιμαστικό μήνα. Πώς θα την εξηγούσες στους συναδέλφους;", "learner_goal_ru": "Передать ограниченный срок, не постоянное изменение.", "acceptable_examples_el": ["Η πρόταση προβλέπει μεγαλύτερο ωράριο μόνο για έναν δοκιμαστικό μήνα, όχι μόνιμη αλλαγή."]}, {"node_id": "TWIST", "transitions": [{"to": "NEGOTIATE", "condition": "Semantic goal achieved with independently formulated response; any suitable wording accepted"}, {"to": "REPAIR", "condition": "Unclear response, explicit clarification or transcript uncertainty"}], "assistant_el": "Η επιτροπή ενημέρωσε την ομάδα που θα στηρίξει το πρόγραμμα. Ποιος θα το στηρίξει, η επιτροπή ή η ομάδα;", "learner_goal_ru": "Назвать группу и при необходимости устранить двусмысленность перефразом.", "acceptable_examples_el": ["Η ομάδα θα στηρίξει το πρόγραμμα. Μπορούμε να πούμε: «Η επιτροπή ενημέρωσε την ομάδα, η οποία θα στηρίξει το πρόγραμμα»."]}, {"node_id": "NEGOTIATE", "transitions": [{"to": "CLOSE", "condition": "Semantic goal achieved with independently formulated response; any suitable wording accepted"}, {"to": "REPAIR", "condition": "Unclear response, explicit clarification or transcript uncertainty"}], "assistant_el": "Η επέκταση εγκρίθηκε υπό τον όρο ότι θα υπάρχουν αρκετοί εθελοντές. Θα ανακοίνωνες ότι το νέο ωράριο είναι οριστικό;", "learner_goal_ru": "Отклонить безусловное объявление с точным обоснованием.", "acceptable_examples_el": ["Όχι. Η έγκριση εξαρτάται από την επάρκεια των εθελοντών και αφορά μόνο τη δοκιμαστική περίοδο."]}, {"node_id": "CLOSE", "transitions": [{"to": "DONE", "condition": "Confirmed learner response fulfils final goal and all branch-specific critical facts; evaluate quoted evidence before marking task success"}, {"to": "REPAIR", "condition": "Final answer unclear, learner asks clarification or ASR uncertain; save return_node=CLOSE"}], "assistant_el": "Δώσε μου τώρα μια σύντομη ανακοίνωση δύο προτάσεων που να διατηρεί αυτές τις προϋποθέσεις.", "learner_goal_ru": "Сжать без потери срока,условия и роли группы.", "acceptable_examples_el": ["Εγκρίθηκε δοκιμαστική επέκταση του ωραρίου για έναν μήνα, εφόσον υπάρχουν αρκετοί εθελοντές. Η ομάδα που ενημερώθηκε από την επιτροπή θα στηρίξει το πρόγραμμα."], "awaits_learner_response": true}, {"node_id": "REPAIR", "transitions": [{"to": "OPEN", "guard": {"return_node": "OPEN", "repair_count_lt": 2}, "condition": "Clarification supplied; repair_count<2 and saved return_node==OPEN; repeat only necessary task fact without supplying learner answer"}, {"to": "TWIST", "guard": {"return_node": "TWIST", "repair_count_lt": 2}, "condition": "Clarification supplied; repair_count<2 and saved return_node==TWIST; repeat only necessary task fact without supplying learner answer"}, {"to": "NEGOTIATE", "guard": {"return_node": "NEGOTIATE", "repair_count_lt": 2}, "condition": "Clarification supplied; repair_count<2 and saved return_node==NEGOTIATE; repeat only necessary task fact without supplying learner answer"}, {"to": "CLOSE", "guard": {"return_node": "CLOSE", "repair_count_lt": 2}, "condition": "Clarification supplied; repair_count<2 and saved return_node==CLOSE; repeat only necessary task fact without supplying learner answer"}, {"to": "RETRY", "condition": "Two unsuccessful repairs OR invalid/missing saved return_node; do not guess a target"}], "assistant_el": "Ποιο σημείο θέλετε να πω ξανά;", "learner_goal_ru": "Назвать непонятую часть; повторить факт короче без выдачи ответа.", "acceptable_examples_el": ["Μπορείτε να το πείτε πιο αργά;"]}, {"node_id": "RETRY", "transitions": [], "assistant_el": "Ας κάνουμε μια μικρή παύση. Μπορούμε να δοκιμάσουμε ξανά.", "learner_goal_ru": "Сохранить помощь и причину остановки; не присваивать самостоятельное освоение.", "acceptable_examples_el": ["Ναι, ας δοκιμάσουμε ξανά."]}, {"node_id": "DONE", "terminal": true, "transitions": [], "assistant_el": "Ευχαριστώ. Ολοκληρώσαμε αυτή την άσκηση.", "learner_goal_ru": "Учебная роль завершена; оценка опирается на уже записанный ответ ученика.", "assessment_policy": "No automatic success from reaching this node; use stored assessed learner evidence and branch outcome", "acceptable_examples_el": ["Ευχαριστώ."], "additional_learner_response_required": false}], "domain": "Сжатое объяснение решения с оговоркой", "rubric": {"scale": "0: смысловой результат не достигнут;1: частично/с помощью;2: все условия самостоятельно; не официальный экзаменационный балл", "language": "Диапазон и точность в пределах уровня; смысл важнее дословного совпадения", "register": "Уместно выбирает вежливость и адресата", "requires": ["evidence_spans", "assistance_level", "confidence", "abstention_reason_if_uncertain"], "interaction": "Отвечает на новую информацию, уточняет и достигает/честно ограничивает результат", "task_success": ["Сохраняет один пробный месяц и условие волонтёров", "Правильно связывает относительное предложение с группой", "Краткость не уничтожает условность; допустимы другие синтаксические решения"], "pronunciation": "Оценивать только по реально прослушанному аудио; по транскрипту NO_SCORE", "item_specific_criteria": [{"criterion": "Сохраняет один пробный месяц и условие волонтёров", "evidence_required": "quote learner turn and task fact", "critical_if_missing": true}, {"criterion": "Правильно связывает относительное предложение с группой", "evidence_required": "quote learner turn and task fact", "critical_if_missing": true}, {"criterion": "Краткость не уничтожает условность; допустимы другие синтаксические решения", "evidence_required": "quote learner turn and task fact", "critical_if_missing": true}]}, "status": "DRAFT", "unit_ids": ["U-B2-008"], "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "audio_file": null, "cefr_level": "B2", "entry_node": "OPEN", "error_tags": {"compression": "CONTENT_OMISSION", "relative_referent": "SYNTAX", "condition_preservation": "COMPREHENSION"}, "hint_limits": {"exam_mode": "Никаких языковых подсказок; допустима организационная реплика без ответа", "practice_mode": "До двух пояснений после запроса; учитывать помощь"}, "scenario_id": "SC44", "source_refs": [{"scope": "Original project communicative design; does not certify individual Greek sentences", "source_id": "PROJECT-BLUEPRINT-V1.2", "evidence_path": "SPEC/GreekOS_Academic_Content_Blueprint_v1_2.zip"}], "facts_policy": "Все имена/суммы/сроки/процедуры — условия учебной роли. Не актуальные правила организаций. Не запрашивать реальные реквизиты.", "script_status": "AUTHORED", "retention_days": [7, 14, 28], "content_version": "0.1.1", "critical_errors": [{"type": "CONTENT_OMISSION", "criterion": "Игнорирует изменившиеся условия, подтверждает невыполнимый результат"}, {"type": "COMPREHENSION", "criterion": "Путает участника, время, сумму или следующий шаг; предварительно исключить ASR ошибку"}], "feedback_policy": {"after_dialogue": "Сначала отметить достигнутый результат; затем максимум3 ошибки: фрагмент → вариант → причина → самокоррекция", "during_free_speech": "Не прерывать мелкими исправлениями, если смысл понятен", "sample_feedback_ru": "Сначала укажите конкретно выполненную цель; затем одну подтверждённую трудность с цитатой. Не применять общий шаблон к отсутствующей ошибке.", "speech_recognition_uncertain": "ASR_UNCERTAIN, score withheld, ask repeat; not grammar/pronunciation penalty"}, "retention_tasks": {"D7": "D7: продление курса разрешено только после набора группы; передайте условие двумя разными синтаксическими способами.", "D28": "D28: сравните два новых сообщения о решении клуба и составьте краткое объяснение, отделив утверждённое от предложенного."}, "branching_status": "AUTHORED", "learner_brief_ru": "Обсуждается условное расписание культурного центра. Предложение расширить вечерние часы принято только для пробного месяца при наличии волонтёров. Нужно объяснить коллеге точный смысл решения и уточнить двусмысленную ссылку.", "transfer_task_ru": "D28: сравните два новых сообщения о решении клуба и составьте краткое объяснение, отделив утверждённое от предложенного.", "off_script_policy": {"unknown_fact": "Сказать, что нужно уточнить; не выдумывать ответ", "max_repair_loops": 2, "transition_ambiguity": "Prefer clarification; do not penalize ASR uncertainty", "unsafe_real_world_emergency": "Прервать учебную роль и дать уместный реальный ответ", "semantically_valid_unlisted_response": "Accept; examples are not exact keys"}, "learning_objective": "Сжатое объяснение решения с оговоркой", "spoken_eval_status": "NOT_VALIDATED", "audio_review_status": "MISSING_AUDIO", "primary_competencies": ["B2-G04", "B2-G08"], "runtime_transition_contract": {"precedence": "ASR uncertainty before semantic scoring", "repair_entry": "Save current active question node before entering REPAIR; increment per-session repair_count when clarification is supplied; do not overwrite saved node with REPAIR", "max_repair_loops": 2, "terminal_success": "Only after confirmed final learner response evaluated; CLOSE is a question/acknowledgement state, DONE is terminal", "plausible_refusal": "Allow terminal outcome declined with reasons; task_success can pass if constraints understood; never force purchase/agreement", "transition_priority": ["technical/ASR uncertainty", "explicit refusal when available", "semantic goal achieved", "clarification or retry"], "return_node_allowed_values": ["OPEN", "TWIST", "NEGOTIATE", "CLOSE"]}}	506167ccdb5228def2af7abb5c79810065e79f64c2f1d937dc509fa643eb3a96	3086
