diagnostic_protocol	{"path": "GreekOS_Academic_Corpus/diagnostics/ENTRY_PROTOCOL.json", "payload": {"id": "ENTRY-P01", "axes": ["listening", "reading", "spoken_interaction", "spoken_production", "writing", "pronunciation", "grammar", "vocabulary"], "scope": "24 коротких пробы A1–B1; не исчерпывают уровень и не измеряют B2", "status": "DRAFT_NOT_VALIDATED", "version": "0.1.0", "item_ids": ["D-A1-GRAMMAR-01", "D-A1-VOCABULARY-01", "D-A1-READING-01", "D-A1-LISTENING-01", "D-A1-WRITING-01", "D-A1-SPOKEN_INTERACTION-01", "D-A1-SPOKEN_PRODUCTION-01", "D-A1-PRONUNCIATION-01", "D-A2-GRAMMAR-01", "D-A2-VOCABULARY-01", "D-A2-READING-01", "D-A2-LISTENING-01", "D-A2-WRITING-01", "D-A2-SPOKEN_INTERACTION-01", "D-A2-SPOKEN_PRODUCTION-01", "D-A2-PRONUNCIATION-01", "D-B1-GRAMMAR-01", "D-B1-VOCABULARY-01", "D-B1-READING-01", "D-B1-LISTENING-01", "D-B1-WRITING-01", "D-B1-SPOKEN_INTERACTION-01", "D-B1-SPOKEN_PRODUCTION-01", "D-B1-PRONUNCIATION-01"], "result_fields": ["axis", "observed_task_id", "task_level", "response_evidence", "assistance", "confidence", "human_review_needed", "candidate_learning_start", "not_observed_reason"], "administration": {"stop": "При двух непосильных заданиях или усталости прекратить ось; предложить отдых/проверку, не обнулять другие оси", "hints": "В измеряемой попытке нет языковых подсказок; помощь создаёт отдельный ASSISTED результат", "start": "A1 по каждому навыку отдельно; подтверждённый прежний уровень позволяет начать с A2 с возможностью вернуться", "retake": "Этот же item не годится как независимое подтверждение после показа ключа; нужна новая holdout версия", "advance": "После понятной самостоятельной попытки предложить следующий уровень того же навыка; это гипотеза маршрута, не статистический cut score", "audio_missing": "Listening/pronunciation не проводить без реального звука; статус NOT_OBSERVED"}, "interpretation": "Не усреднять восемь навыков в один CEFR и не выводить готовность к экзамену. Неравномерный профиль направляет к разным prerequisite и новым независимым пробам.", "corrective_practice_policy": "80/20 только внутри корректирующей практики; новые темы продолжаются. 9 месяцев от индивидуальной даты начала, не от ближайшего экзамена."}}	12492f5de80cd40775e85ecf731ad983b84ef5ac64c712a68f8cc2b51cae9482	5265
u01_joint_adjudication	{"path": "GreekOS_B2_Exam_Bank/U01_JOINT_ADJUDICATION.json", "payload": {"status": "AUTHOR_ANALYSIS_PENDING_INDEPENDENT_AND_EXAMINER", "text_id": "KEG-B2-U01-TEXT3", "version": "0.1.0", "record_id": "GOS-U01-JOINT-06", "text_sha256": "522120af70276575ae75d78809b2976850cfe02e652d0d764556e26230696517", "human_review": "NOT_REVIEWED", "analysis_basis": "Original stimulus plus existing frozen grammar sources; no new official exam scoring assertion.", "scoring_policy": "No automatic rejection of unlisted complete solutions. Route semantic alternatives to examiner; show practice feedback only. Do not sum canonical-only wrong counts into B2 readiness.", "new_source_claim": false, "per_gap_analysis": [{"gap": 1, "reason": "Contrast versus temporal circumstance; both permit the clause.", "canonical": "αλλά", "local_candidate": "όταν"}, {"gap": 2, "reason": "ώστε να introduces intended result/purpose; following να excludes simple γιατί-like substitution.", "canonical": "ώστε"}, {"gap": 3, "reason": "Hypothetical condition versus recurring/expected occurrence, both plausible locally.", "canonical": "αν", "local_candidate": "όταν"}, {"gap": 4, "reason": "Limited family availability motivates longer lending; causal relation explicit.", "canonical": "επειδή"}, {"gap": 5, "reason": "Temporal background versus concessive contrast, both coherent in complete alternative.", "canonical": "όταν", "local_candidate": "αλλά"}, {"gap": 6, "reason": "Comparative περισσότερο ... παρά ...; αντί για may sound redundant but must be reviewed if proposed.", "canonical": "παρά"}, {"gap": 7, "reason": "Degree of feasibility versus whether feasible; both meaningful locally, check reserved bank constraints.", "canonical": "κατά πόσο", "local_candidate": "αν"}], "reserved_example": "ενώ", "canonical_solution": ["αλλά", "ώστε", "αν", "επειδή", "όταν", "παρά", "κατά πόσο"], "uniqueness_certified": false, "alternative_reason_ru": "C1 όταν связывает принятие идеи с моментом постановки условия. C5 αλλά противопоставляет незавершённость испытания подготовке первой записи. Все семь ответов уникальны; ενώ из примера не повторяется. Следовательно, запрет повторов не доказывает единственность исходного ключа.", "use_each_at_most_once": true, "additional_candidate_solutions": [{"reason": "C3 когда вместо если; C5 условное чтение с аористом может быть маркированным, требуется оценка всего дискурса.", "answers": ["αλλά", "ώστε", "όταν", "επειδή", "αν", "παρά", "κατά πόσο"], "decision": "HOLD_FOR_SEMANTIC_REVIEW"}, {"reason": "C7 αν возможно как косвенный вопрос; C5 δηλαδή сомнительно как переформулирование незавершённости. Не принимать только потому, что банк не повторён.", "answers": ["αλλά", "ώστε", "όταν", "επειδή", "δηλαδή", "παρά", "αν"], "decision": "HOLD_FOR_SEMANTIC_REVIEW"}], "defensible_complete_alternative": ["όταν", "ώστε", "αν", "επειδή", "αλλά", "παρά", "κατά πόσο"]}}	2d3d5caf3d1cb0c23d5da6e2074bc79b4cd98805754681830e306e003245cc5e	5266
