U-A1-001	A1	101	Представиться и выбрать εσύ или εσείς	{}	{A1-P01}	{A1-G05,A1-PR01,A1-SI01,A1-V01}	{A1-G05,A1-PR01}	45	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A1-001-RUBRIC"], "unit_id": "U-A1-001", "version": "0.1.2", "sections": {"theory": "theory_ru", "practice": ["U-A1-001-I02", "U-A1-001-I03", "U-A1-001-I04", "U-A1-001-I05", "U-A1-001-I06", "U-A1-001-I07"], "reception": ["U-A1-001-I08", "U-A1-001-I09", "U-A1-001-I10", "U-A1-001-I11"], "retention": ["U-A1-001-I15", "U-A1-001-I16", "U-A1-001-I17"], "diagnostic": ["U-A1-001-I01"], "production": ["U-A1-001-I12", "U-A1-001-I13", "U-A1-001-I14"]}, "title_ru": "Представиться и выбрать εσύ или εσείς", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Греческое είμαι соответствует «быть»: είμαι — я, είσαι — ты, είναι — он/она/оно, είμαστε — мы, είστε — вы, είναι — они. В отличие от русского настоящего времени, связку обычно произносят: Είμαι φοιτητής. Окончание уже указывает на участника, поэтому εγώ не обязательно; оно полезно для противопоставления: Εγώ είμαι φοιτητής, η Άννα είναι δασκάλα. С именем в роли подлежащего часто употребляется артикль: ο Νίκος, η Ελένη. Это не переводится словом «этот».\\n\\nС ровесником при неформальном знакомстве возможны εσύ/είσαι. К незнакомому сотруднику или преподавателю уместно начать с εσείς/είστε: это также обычная форма множественного числа. Выбор зависит от отношений, а не только от возраста. Нельзя автоматически заменять каждое «вы» на формальный единственный контекст. Сравните: Εσύ είσαι ο Πέτρος; и Εσείς είστε η κυρία Παππά;\\n\\nОткуда человек: Είμαι από την Ελλάδα. Где живёт: Μένω στη Θεσσαλονίκη. Это разные сведения; не заменяйте автоматически μένω на είμαι. Для профессии после είμαι здесь достаточно существительного: Είμαι δάσκαλος / δασκάλα. Мы не выводим всё склонение из этого урока. Если реплика непонятна, просьба о повторении — успешная стратегия общения: Συγγνώμη, μπορείτε να το πείτε ξανά; Сначала завершите знакомство, затем разберите одну-две ошибки. Полная парадигма прилагательных не является условием начала общения.\\n\\nГотовые формулы знакомства: Με λένε Άννα — меня зовут Анна; Πώς σε λένε; — знакомому; Πώς σας λένε; / Πώς λέγεστε; — вежливый вопрос. Это не полное спряжение λέω/λέγομαι. Μένουμε — мы живём, готовая форма для диагностического задания.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Είμαι η Άννα. Μένω στην Πάτρα.", "Ο Νίκος είναι φοιτητής. Η Ελένη είναι δασκάλα.", "Εσύ είσαι ο Μάριος; — Ναι, εγώ είμαι.", "Καλημέρα σας. Είστε η κυρία Παππά;", "Συγγνώμη, μπορείτε να το πείτε ξανά;"], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A1-001-I15", "U-A1-001-I16", "U-A1-001-I17"], "spontaneous_followup": {"day": 28, "model": "Καλημέρα σας. Με λένε Άννα. Είμαι από τη Ρωσία. Μένω στην Πάτρα. Πώς σας λένε;", "prompt": "Без образца представьтесь новому преподавателю: имя, происхождение, место проживания; задайте вежливый вопрос об имени.", "criteria": ["три факта", "уместная форма обращения", "самостоятельно"], "observed": false}, "hypothesis_not_official": true}, "source_refs": [{"anchor": "PDF5: личность и είμαι; V214 печатные26–41 — независимое тематическое подтверждение", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Overall spoken interaction / sociolinguistic appropriateness, A1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A1-001-I06", "U-A1-001-I07"], "prerequisites": [], "reading_tasks": ["U-A1-001-I08", "U-A1-001-I09"], "transfer_task": "U-A1-001-I14", "writing_tasks": ["U-A1-001-I12"], "competency_ids": ["A1-G05", "A1-PR01", "A1-SI01", "A1-V01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A1-001-I13"], "errors_taxonomy": ["PRAGMATICS_REGISTER", "VERB_TENSE", "CONTENT_OMISSION"], "guided_practice": ["U-A1-001-I02", "U-A1-001-I03", "U-A1-001-I04", "U-A1-001-I05"], "listening_tasks": ["U-A1-001-I10", "U-A1-001-I11"], "learning_outcome": "Представиться с με λένε и είμαι, указав имя и происхождение", "vocabulary_items": [{"lemma": "φοιτητής", "stress": "φοιτητής", "example": "Ο Άρης είναι φοιτητής.", "inflection": "ο φοιτητής, η φοιτήτρια", "meaning_ru": "студент", "collocations": ["είμαι φοιτητής"]}, {"lemma": "μένω", "stress": "μένω", "example": "Μένω στη Θεσσαλονίκη.", "inflection": "μένω, μένεις, μένει", "meaning_ru": "жить", "collocations": ["μένω στην Πάτρα"]}, {"lemma": "όνομα", "stress": "όνομα", "example": "Το όνομά μου είναι Άννα.", "inflection": "το όνομα, τα ονόματα", "meaning_ru": "имя", "collocations": ["το όνομά μου"]}, {"lemma": "συγγνώμη", "stress": "συγγνώμη", "example": "Συγγνώμη, δεν καταλαβαίνω.", "inflection": "формула", "meaning_ru": "извините", "collocations": ["συγγνώμη, μπορείτε…"]}], "soft_prerequisites": ["A1-P01"], "diagnostic_item_ids": ["U-A1-001-I01"], "learning_objectives": ["Представиться с με λένε и είμαι, указав имя и происхождение", "Выбрать εσύ/εσείς по адресату и согласовать форму είμαι", "Самостоятельно представиться новому собеседнику после отсрочки"], "microcompetency_ids": ["U-A1-001-MC01", "U-A1-001-MC02", "U-A1-001-MC03"], "primary_competencies": ["A1-G05", "A1-PR01"], "learner_data_included": false, "estimated_active_minutes": 45}	1032111bd579689cf53d87fcb8c1b726d1b2ac0096be2086c73e028122f7298c	3107
U-A1-002	A1	102	Кто и кого: ο/τον, η/την, το/το	{A1-G05}	{}	{A1-G01,A1-G02}	{A1-G01,A1-G02}	45	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A1-002-RUBRIC"], "unit_id": "U-A1-002", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-A1-002-I02", "U-A1-002-I03", "U-A1-002-I04", "U-A1-002-I05", "U-A1-002-I06"], "reception": ["U-A1-002-I07", "U-A1-002-I08", "U-A1-002-I09", "U-A1-002-I10"], "retention": ["U-A1-002-I14", "U-A1-002-I15", "U-A1-002-I16"], "diagnostic": ["U-A1-002-I01"], "production": ["U-A1-002-I11", "U-A1-002-I12", "U-A1-002-I13"]}, "title_ru": "Кто и кого: ο/τον, η/την, το/το", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Артикль помогает определить род и роль именной группы. Для знакомых лиц в единственном числе сравним ο φίλος → τον φίλο, η φίλη → τη φίλη, το παιδί → το παιδί. В роли подлежащего используется именительный: Ο φίλος βλέπει την Άννα. После переходного βλέπω прямое дополнение получает винительный: Η Άννα βλέπει τον φίλο. У среднего рода именительный и винительный совпадают: Το παιδί βλέπει το λεωφορείο. Поэтому смысл определяется не одной внешней формой, но глаголом и контекстом.\\nВ мужском роде этой модели исчезает конечное -ς: φίλος → φίλο. Это не правило для любого греческого слова, заканчивающегося на -ς. Женское φίλη и среднее παιδί здесь форму не меняют. Выучите артикль вместе с существительным. Имена тоже часто употребляются с артиклем: ο Νίκος → τον Νίκο, η Άννα → την Άννα.\\nВ современной учебной орфографии τον перед мужским существительным сохраняет ν. У την/τη выбор связан со следующим звуком; в этом уроке ключи допускают τη/την там, где требуется педагогическая терпимость, но отмечают орфографию отдельно. Не превращайте мелкую графическую вариацию в доказательство непонимания роли. Минимальная пара Ο Νίκος βλέπει την Άννα / Η Άννα βλέπει τον Νίκο показывает, как меняется участник действия. Сначала назовите, кто действует, затем кого видит; перестановки слов возможны, поэтому простое правило «первое слово всегда подлежащее» неверно.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Ο Νίκος βλέπει την Άννα.", "Η Άννα βλέπει τον Νίκο.", "Το παιδί περιμένει τον φίλο του.", "Βλέπω τη φίλη μου στο πάρκο."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A1-002-I14", "U-A1-002-I15", "U-A1-002-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF5–6", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction A1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A1-002-I05", "U-A1-002-I06"], "prerequisites": ["A1-G05"], "reading_tasks": ["U-A1-002-I07", "U-A1-002-I08"], "transfer_task": "U-A1-002-I13", "writing_tasks": ["U-A1-002-I11"], "competency_ids": ["A1-G01", "A1-G02"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A1-002-I12"], "errors_taxonomy": ["MORPHOLOGY_CASE", "GENDER_AGREEMENT"], "guided_practice": ["U-A1-002-I02", "U-A1-002-I03", "U-A1-002-I04"], "listening_tasks": ["U-A1-002-I09", "U-A1-002-I10"], "learning_outcome": "Различить действующее лицо и прямое дополнение по ο/τον, η/την, το", "vocabulary_items": [{"lemma": "φίλος", "stress": "φίλος", "example": "Περιμένω τον φίλο μου.", "inflection": "ο φίλος, τον φίλο", "meaning_ru": "друг", "collocations": ["βλέπω τον φίλο"]}, {"lemma": "φίλη", "stress": "φίλη", "example": "Η φίλη μου είναι εδώ.", "inflection": "η φίλη, τη φίλη", "meaning_ru": "подруга", "collocations": ["περιμένω τη φίλη"]}, {"lemma": "παιδί", "stress": "παιδί", "example": "Το παιδί είναι στο πάρκο.", "inflection": "το παιδί, τα παιδιά", "meaning_ru": "ребёнок", "collocations": ["το παιδί περιμένει"]}, {"lemma": "βλέπω", "stress": "βλέπω", "example": "Βλέπω τον Πέτρο.", "inflection": "βλέπω, βλέπεις, βλέπει", "meaning_ru": "видеть", "collocations": ["βλέπω την Άννα"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-002-I01"], "learning_objectives": ["Различить действующее лицо и прямое дополнение по ο/τον, η/την, το", "Образовать винительный φίλος→φίλο и употребить его в описании", "Описать новую сцену с ясными ролями участников"], "microcompetency_ids": ["U-A1-002-MC01", "U-A1-002-MC02", "U-A1-002-MC03"], "primary_competencies": ["A1-G01", "A1-G02"], "learner_data_included": false, "estimated_active_minutes": 45}	8997386ce543184553116324c2926d3b78ab670ea24cecfea9ec9bcc7152dafd	3108
U-A1-003	A1	103	Количество и заказ: один предмет и несколько	{A1-G01}	{}	{A1-G03,A1-V02}	{A1-G03,A1-V02}	45	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A1-003-RUBRIC"], "unit_id": "U-A1-003", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-A1-003-I02", "U-A1-003-I03", "U-A1-003-I04", "U-A1-003-I05", "U-A1-003-I06"], "reception": ["U-A1-003-I07", "U-A1-003-I08", "U-A1-003-I09", "U-A1-003-I10"], "retention": ["U-A1-003-I14", "U-A1-003-I15", "U-A1-003-I16"], "diagnostic": ["U-A1-003-I01"], "production": ["U-A1-003-I11", "U-A1-003-I12", "U-A1-003-I13"]}, "title_ru": "Количество и заказ: один предмет и несколько", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Для покупки нужно различать название товара, количество и цену. В простых моделях ο χυμός → οι χυμοί, η ντομάτα → οι ντομάτες, το μήλο → τα μήλα. Это три конкретные модели, а не универсальное окончание множественного числа. В винительном после θέλω: έναν χυμό, δύο χυμούς; μία ντομάτα, δύο ντομάτες; ένα μήλο, δύο μήλα. Число один согласуется с родом: ένας/μία/ένα; в нашем заказе винительный мужского — έναν.\\nВместо нескольких штук можно попросить вес: ένα κιλό μήλα, μισό κιλό ντομάτες. При этом κιλό называет единицу измерения, а не грамматический род товара. Сравните δύο μήλα и δύο κιλά μήλα: количество товара различается. Вопрос Πόσο κάνει; относится к одному товару или сумме в контексте, Πόσο κάνουν; — к нескольким предметам. Не выводите реальную цену из учебного текста: все цены в этом блоке вымышлены.\\nДесятичную цену можно услышать как δύο ευρώ και πενήντα λεπτά. Проверьте, относится ли она к килограмму или ко всему заказу. Чтение числа без единицы — недостаточное доказательство понимания. После изменения количества переспросите итог: Δύο κιλά, σωστά; и Πόσο κάνουν όλα μαζί;", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Θέλω δύο μήλα.", "Θέλω έναν χυμό και δύο καφέδες.", "Ένα κιλό ντομάτες, παρακαλώ.", "Πόσο κάνουν όλα μαζί;"], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A1-003-I14", "U-A1-003-I15", "U-A1-003-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF5–6", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction A1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A1-003-I05", "U-A1-003-I06"], "prerequisites": ["A1-G01"], "reading_tasks": ["U-A1-003-I07", "U-A1-003-I08"], "transfer_task": "U-A1-003-I13", "writing_tasks": ["U-A1-003-I11"], "competency_ids": ["A1-G03", "A1-V02"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A1-003-I12"], "errors_taxonomy": ["MORPHOLOGY_CASE", "COMPREHENSION"], "guided_practice": ["U-A1-003-I02", "U-A1-003-I03", "U-A1-003-I04"], "listening_tasks": ["U-A1-003-I09", "U-A1-003-I10"], "learning_outcome": "Заказать предметы с числом один и множественным числом", "vocabulary_items": [{"lemma": "μήλο", "stress": "μήλο", "example": "Αγοράζω τρία μήλα.", "inflection": "το μήλο, τα μήλα", "meaning_ru": "яблоко", "collocations": ["δύο μήλα"]}, {"lemma": "χυμός", "stress": "χυμός", "example": "Θέλω έναν χυμό.", "inflection": "ο χυμός, οι χυμοί", "meaning_ru": "сок", "collocations": ["έναν χυμό"]}, {"lemma": "κιλό", "stress": "κιλό", "example": "Μισό κιλό ντομάτες, παρακαλώ.", "inflection": "το κιλό, τα κιλά", "meaning_ru": "килограмм", "collocations": ["μισό κιλό"]}, {"lemma": "λεπτό", "stress": "λεπτό", "example": "Κάνει πενήντα λεπτά.", "inflection": "το λεπτό, τα λεπτά", "meaning_ru": "цент; также минута", "collocations": ["πενήντα λεπτά"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-003-I01"], "learning_objectives": ["Заказать предметы с числом один и множественным числом", "Различить штуки и килограммы и вычислить указанную в тексте сумму", "Исправить неверное количество в реплике продавца"], "microcompetency_ids": ["U-A1-003-MC01", "U-A1-003-MC02", "U-A1-003-MC03"], "primary_competencies": ["A1-G03", "A1-V02"], "learner_data_included": false, "estimated_active_minutes": 45}	30f83ea2861b2cf8b9b91881d1554403e8d5f98b1d42ef96d7e93dcd646fe726	3109
U-A1-004	A1	104	Маршрут и положение: σε, από, με	{A1-G01}	{}	{A1-G09,A1-G07}	{A1-G09,A1-G07}	45	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A1-004-RUBRIC"], "unit_id": "U-A1-004", "version": "0.1.2", "sections": {"theory": "theory_ru", "practice": ["U-A1-004-I02", "U-A1-004-I03", "U-A1-004-I04", "U-A1-004-I05", "U-A1-004-I06"], "reception": ["U-A1-004-I07", "U-A1-004-I08", "U-A1-004-I09", "U-A1-004-I10"], "retention": ["U-A1-004-I14", "U-A1-004-I15", "U-A1-004-I16"], "diagnostic": ["U-A1-004-I01"], "production": ["U-A1-004-I11", "U-A1-004-I12", "U-A1-004-I13"]}, "title_ru": "Маршрут и положение: σε, από, με", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Σε обозначает местонахождение или направление в зависимости от глагола: Είμαι στο σχολείο — я в школе; Πηγαίνω στο σχολείο — иду в школу. Предлог сливается с определённым артиклем винительного: σε + το = στο, σε + τον = στον, σε + την = στην. Слово после него выбирается по собственному роду, а не по русскому переводу. Πού; спрашивает место, από πού; — исходную точку, πώς; — способ.\\nΑπό помогает назвать отправление: Έρχομαι από το κέντρο. Με показывает средство в сочетании με το λεωφορείο. Пешком — με τα πόδια. Не путайте номер автобуса и время отправления. В учебном маршруте данные условные и не заменяют актуальное расписание транспорта.\\nΠηγαίνετε ευθεία и στρίψτε δεξιά можно сначала понимать как готовые инструкции, не заявляя полного освоения императива A2. Если маршрут непонятен, попросите один шаг: Πού είναι η στάση; или Μπορείτε να το πείτε πιο αργά; Правильная стратегия — проверить направление, а не угадывать по знакомому названию. Сравните στο κέντρο (к/в центре) и από το κέντρο (из центра).\\n\\nОриентиры: δίπλα σε — рядом; απέναντι από — напротив; μπροστά σε — перед. Σε сливается с артиклем: δίπλα στην πόρτα, μπροστά στο γραφείο. После από артикль отдельно: απέναντι από την τράπεζα. Подготовка: соедините μπροστά + στο γραφείο (ключ μπροστά στο γραφείο); выберите рядом/напротив для δίπλα (рядом). Затем опишите новый ориентир без подсказки.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Πηγαίνω στο κέντρο.", "Έρχομαι από το σχολείο.", "Μένω στην Πάτρα.", "Πηγαίνω με το λεωφορείο."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A1-004-I14", "U-A1-004-I15", "U-A1-004-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF5–6", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction A1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A1-004-I05", "U-A1-004-I06"], "prerequisites": ["A1-G01"], "reading_tasks": ["U-A1-004-I07", "U-A1-004-I08"], "transfer_task": "U-A1-004-I13", "writing_tasks": ["U-A1-004-I11"], "competency_ids": ["A1-G09", "A1-G07"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A1-004-I12"], "errors_taxonomy": ["MORPHOLOGY_CASE", "COMPREHENSION"], "guided_practice": ["U-A1-004-I02", "U-A1-004-I03", "U-A1-004-I04"], "listening_tasks": ["U-A1-004-I09", "U-A1-004-I10"], "learning_outcome": "Различить место/направление с σε и исходную точку с από", "vocabulary_items": [{"lemma": "στάση", "stress": "στάση", "example": "Περιμένω στη στάση.", "inflection": "η στάση, οι στάσεις", "meaning_ru": "остановка", "collocations": ["στη στάση"]}, {"lemma": "κέντρο", "stress": "κέντρο", "example": "Το γραφείο είναι στο κέντρο.", "inflection": "το κέντρο", "meaning_ru": "центр", "collocations": ["στο κέντρο"]}, {"lemma": "λεωφορείο", "stress": "λεωφορείο", "example": "Πηγαίνω με το λεωφορείο.", "inflection": "το λεωφορείο, τα λεωφορεία", "meaning_ru": "автобус", "collocations": ["με το λεωφορείο"]}, {"lemma": "δεξιά", "stress": "δεξιά", "example": "Η στάση είναι δεξιά.", "inflection": "наречие", "meaning_ru": "направо", "collocations": ["στρίβω δεξιά"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-004-I01"], "learning_objectives": ["Различить место/направление с σε и исходную точку с από", "Назвать средство передвижения с με и слитный предлог с артиклем", "Уточнить маршрут после отрицательного ответа"], "microcompetency_ids": ["U-A1-004-MC01", "U-A1-004-MC02", "U-A1-004-MC03"], "primary_competencies": ["A1-G09", "A1-G07"], "learner_data_included": false, "estimated_active_minutes": 45}	b7ee74d3697a7d831c9edccde7ef5bd3a357181bce3fce9ad9423563ec27911e	3110
U-A1-005	A1	105	Настоящее время: что я делаю и что делаем мы	{A1-G05}	{}	{A1-G06}	{A1-G06}	45	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A1-005-RUBRIC"], "unit_id": "U-A1-005", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-A1-005-I02", "U-A1-005-I03", "U-A1-005-I04", "U-A1-005-I05", "U-A1-005-I06"], "reception": ["U-A1-005-I07", "U-A1-005-I08", "U-A1-005-I09", "U-A1-005-I10"], "retention": ["U-A1-005-I14", "U-A1-005-I15", "U-A1-005-I16"], "diagnostic": ["U-A1-005-I01"], "production": ["U-A1-005-I11", "U-A1-005-I12", "U-A1-005-I13"]}, "title_ru": "Настоящее время: что я делаю и что делаем мы", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "В настоящем времени окончание часто показывает действующее лицо, поэтому местоимение можно опустить: Μένω εδώ = Εγώ μένω εδώ. Для модели γράφω: γράφω, γράφεις, γράφει, γράφουμε, γράφετε, γράφουν. Сравните εγώ γράφω и εμείς γράφουμε. Не добавляйте местоимение в каждый ответ автоматически: оно полезно для противопоставления Εγώ μένω εδώ, αλλά η Άννα μένει αλλού.\\nУ некоторых частотных глаголов другая модель ударения и окончаний: μιλάω/μιλώ, μιλάς, μιλάει/μιλά, μιλάμε/μιλούμε, μιλάτε, μιλάνε/μιλούν. В этом блоке используем разговорную серию μιλάω — μιλάς — μιλάει — μιλάμε — μιλάτε — μιλάνε и признаём указанные варианты. Это не полный разбор второго спряжения: например, μπορώ требует отдельного освоения. Не выводите все глаголы из μιλάω.\\nОтрицание δεν ставится перед глаголом: Δεν μένω εδώ. Вопрос может иметь тот же порядок слов, а на письме заканчивается греческим вопросительным знаком ;: Μένεις εδώ; Настоящее описывает и привычку: Κάθε πρωί διαβάζω. Чтобы проверить понимание, измените лицо без изменения действия. Γράφει и γράφεις различаются адресатом, а не временем. В устном задании важна разборчивость окончаний; по одному текстовому ответу нельзя оценить произношение.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Μένω κοντά στο σχολείο.", "Εμείς διαβάζουμε το πρωί.", "Η Νίκη μιλάει ελληνικά.", "Δεν γράφετε τώρα;"], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A1-005-I14", "U-A1-005-I15", "U-A1-005-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF5–6", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction A1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A1-005-I05", "U-A1-005-I06"], "prerequisites": ["A1-G05"], "reading_tasks": ["U-A1-005-I07", "U-A1-005-I08"], "transfer_task": "U-A1-005-I13", "writing_tasks": ["U-A1-005-I11"], "competency_ids": ["A1-G06"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A1-005-I12"], "errors_taxonomy": ["VERB_AGREEMENT", "NEGATION", "ACCENTUATION"], "guided_practice": ["U-A1-005-I02", "U-A1-005-I03", "U-A1-005-I04"], "listening_tasks": ["U-A1-005-I09", "U-A1-005-I10"], "learning_outcome": "Согласовать настоящее γράφω/μένω/μιλάω с лицом", "vocabulary_items": [{"lemma": "γράφω", "stress": "γράφω", "example": "Γράφουμε ένα μήνυμα.", "inflection": "γράφω, γράφεις, γράφει, γράφουμε, γράφετε, γράφουν", "meaning_ru": "писать", "collocations": ["γράφω ένα μήνυμα"]}, {"lemma": "μένω", "stress": "μένω", "example": "Μένουμε κοντά στο σχολείο.", "inflection": "μένω, μένεις, μένει, μένουμε, μένετε, μένουν", "meaning_ru": "жить; оставаться", "collocations": ["μένω κοντά"]}, {"lemma": "μιλάω", "stress": "μιλάω", "example": "Μιλάμε λίγο ελληνικά.", "inflection": "μιλάω, μιλάς, μιλάει, μιλάμε, μιλάτε, μιλάνε", "meaning_ru": "говорить", "collocations": ["μιλάω ελληνικά"]}, {"lemma": "διαβάζω", "stress": "διαβάζω", "example": "Διαβάζει κάθε πρωί.", "inflection": "διαβάζω, διαβάζεις, διαβάζει, διαβάζουμε, διαβάζετε, διαβάζουν", "meaning_ru": "читать; заниматься", "collocations": ["διαβάζω το πρωί"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-005-I01"], "learning_objectives": ["Согласовать настоящее γράφω/μένω/μιλάω с лицом", "Понять, кто выполняет действие в коротком сообщении", "Описать свои и совместные привычные действия"], "microcompetency_ids": ["U-A1-005-MC01", "U-A1-005-MC02", "U-A1-005-MC03"], "primary_competencies": ["A1-G06"], "learner_data_included": false, "estimated_active_minutes": 45}	1163844eadc08788727432ef0b0abc4325c768f7e300582c0e73df1bec0ddf67	3111
U-A1-006	A1	106	Описать нужный предмет и попросить действие	{A1-G01,A1-G02,A1-G06}	{}	{A1-G04,A1-G12}	{A1-G04,A1-G12}	45	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A1-006-RUBRIC"], "unit_id": "U-A1-006", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-A1-006-I02", "U-A1-006-I03", "U-A1-006-I04", "U-A1-006-I05", "U-A1-006-I06"], "reception": ["U-A1-006-I07", "U-A1-006-I08", "U-A1-006-I09", "U-A1-006-I10"], "retention": ["U-A1-006-I14", "U-A1-006-I15", "U-A1-006-I16"], "diagnostic": ["U-A1-006-I01"], "production": ["U-A1-006-I11", "U-A1-006-I12", "U-A1-006-I13"]}, "title_ru": "Описать нужный предмет и попросить действие", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "В сочетаниях с прилагательным окончание зависит от существительного: ο μικρός φάκελος, η μικρή τσάντα, το μικρό κουτί. В просьбе с θέλω мужской винительный меняется: Θέλω έναν μικρό φάκελο. Женский и средний в этой модели: μια μικρή τσάντα, ένα μικρό κουτί. Во множественном τα μικρά κουτιά относится к нескольким коробкам. Не выбирайте форму прилагательного по русскому роду перевода.\\nΘέλω + предмет сообщает желание: Θέλω ένα κουτί. Θέλω να + глагол сообщает желаемое действие: Θέλω να αγοράσω ένα κουτί. На A1 формы να αγοράσω, να δω, να ρωτήσω осваиваются как ограниченные речевые блоки; полный выбор видовой основы относится к дальнейшему курсу. Μπορώ να δω το κουτί; — просьба разрешить посмотреть. Более вежливое Μπορείτε να το δείξετε; обращено к собеседнику. Не смешивайте могу ли я и можете ли вы.\\nЧтобы уточнить товар, назовите признак: μικρό/μεγάλο, κόκκινο/μπλε. Μπλε в обычном употреблении не изменяется: μια μπλε τσάντα, δύο μπλε τσάντες. Это отдельный пример, а не правило для всех цветов. Если предлагаемый размер не подходит, коротко исправьте просьбу. Важен понятный признак и действие; не требуется безошибочно построить незнакомое склонение.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Θέλω έναν μικρό φάκελο.", "Αυτή η τσάντα είναι μικρή.", "Μπορώ να δω το μεγάλο κουτί;", "Θέλω να αγοράσω μια μπλε τσάντα."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A1-006-I14", "U-A1-006-I15", "U-A1-006-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF5–6", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction A1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A1-006-I05", "U-A1-006-I06"], "prerequisites": ["A1-G01", "A1-G02", "A1-G06"], "reading_tasks": ["U-A1-006-I07", "U-A1-006-I08"], "transfer_task": "U-A1-006-I13", "writing_tasks": ["U-A1-006-I11"], "competency_ids": ["A1-G04", "A1-G12"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A1-006-I12"], "errors_taxonomy": ["ADJECTIVE_AGREEMENT", "REQUEST_FORM", "REFERENCE"], "guided_practice": ["U-A1-006-I02", "U-A1-006-I03", "U-A1-006-I04"], "listening_tasks": ["U-A1-006-I09", "U-A1-006-I10"], "learning_outcome": "Согласовать частотное прилагательное с предметом", "vocabulary_items": [{"lemma": "μικρός", "stress": "μικρός", "example": "Το κουτί είναι μικρό.", "inflection": "μικρός, μικρή, μικρό; маленькие среднего μικρά", "meaning_ru": "маленький", "collocations": ["μικρό κουτί"]}, {"lemma": "μεγάλος", "stress": "μεγάλος", "example": "Η τσάντα είναι μεγάλη.", "inflection": "μεγάλος, μεγάλη, μεγάλο", "meaning_ru": "большой", "collocations": ["μεγάλη τσάντα"]}, {"lemma": "φάκελος", "stress": "φάκελος", "example": "Θέλω έναν φάκελο.", "inflection": "ο φάκελος, τον φάκελο", "meaning_ru": "конверт; папка", "collocations": ["έναν μικρό φάκελο"]}, {"lemma": "κουτί", "stress": "κουτί", "example": "Μπορώ να δω το κουτί;", "inflection": "το κουτί, τα κουτιά", "meaning_ru": "коробка", "collocations": ["ένα μεγάλο κουτί"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-006-I01"], "learning_objectives": ["Согласовать частотное прилагательное с предметом", "Попросить показать предмет через ограниченные блоки θέλω/μπορώ να", "Исправить признак предмета в новой ситуации"], "microcompetency_ids": ["U-A1-006-MC01", "U-A1-006-MC02", "U-A1-006-MC03"], "primary_competencies": ["A1-G04", "A1-G12"], "learner_data_included": false, "estimated_active_minutes": 45}	2c7e5629151f692a2d528d9b9b13294a4f8b8237e07ce87b4a02b93afc5784b1	3112
U-A1-007	A1	107	Алфавит: от написания к чтению	{}	{}	{A1-P01}	{A1-P01}	65	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A1-007-RUBRIC"], "unit_id": "U-A1-007", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-A1-007-I02", "U-A1-007-I03", "U-A1-007-I04", "U-A1-007-I05", "U-A1-007-I06", "U-A1-007-I07", "U-A1-007-I08", "U-A1-007-I19", "U-A1-007-I20"], "reception": ["U-A1-007-I09", "U-A1-007-I10", "U-A1-007-I11", "U-A1-007-I12"], "retention": ["U-A1-007-I16", "U-A1-007-I17", "U-A1-007-I18", "U-A1-007-I22"], "diagnostic": ["U-A1-007-I01"], "production": ["U-A1-007-I13", "U-A1-007-I14", "U-A1-007-I15", "U-A1-007-I21"]}, "title_ru": "Алфавит: от написания к чтению", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "В греческом алфавите 24 буквы. Название буквы нужно для диктовки имени; оно не совпадает со звуком внутри слова. Например, β называется βήτα, но в слове βάζο передаёт [v], а не русское «б». Сначала сравните прописную и строчную форму, затем прочитайте целое слово. Буква σ имеет конечную форму ς: μέσα, κόσμος. Это одна буква, а не два разных звука.\\n\\nПолный справочник пар и названий: Α α άλφα; Β β βήτα; Γ γ γάμμα; Δ δ δέλτα; Ε ε έψιλον; Ζ ζ ζήτα; Η η ήτα; Θ θ θήτα; Ι ι γιώτα; Κ κ κάππα; Λ λ λάμδα; Μ μ μι; Ν ν νι; Ξ ξ ξι; Ο ο όμικρον; Π π πι; Ρ ρ ρο; Σ σ/ς σίγμα; Τ τ ταυ; Υ υ ύψιλον; Φ φ φι; Χ χ χι; Ψ ψ ψι; Ω ω ωμέγα.\\n\\nГласные буквы не означают семь разных гласных звуков: α=[a], ε=[e], η/ι/υ=[i], ο/ω=[o]. Сочетания αι=[e], ει/οι/υι=[i], ου=[u] читаются как одна гласная. В слове παιδί сначала выделите αι, а не читайте α и ι отдельно. Διαλυτικά, две точки, показывают раздельное чтение: Μαΐου — не обычное αι. Ударение над второй буквой сочетания относится ко всему гласному: είναι, ακούω. Систематическая работа с ударением — следующий урок.\\n\\nΜπ в μπαμπάς даёт звонкое [b], ντ в ντομάτα — [d], γκ в γκολ — [g]. Внутри слова у этих сочетаний возможен носовой компонент, а γγ, как в φεγγάρι, также связано со звуком [g]. Не превращайте правило в запрет всех вариантов [mb], [nd], [ŋg]. Ξ читается как [ks], ψ — [ps]; β — [v], ζ — [z], φ — [f]. Для остальных согласных опирайтесь на образец преподавателя; θ, δ, χ, γ подробно отрабатываются отдельно.\\n\\nΑυ и ευ зависят от следующего звука: в αυτό и ευχαριστώ слышим [af], [ef], а в αύριο и ευγενικός — [av], [ev]. Запоминайте пару целых слов, а не механическое правило «перед буквой». Повторяющиеся одинаковые согласные обычно не удваивают длительность: αλλά; γγ рассматривается отдельно.\\n\\nПисьменный ключ проверяет распознавание написания. Он не доказывает правильность произношения. Для речевой попытки запишите имя и несколько слов без чтения модели вслух; преподаватель должен независимо услышать запись. Пока эталонного аудио нет, задания «послушайте» заблокированы, а письменные задания можно выполнять.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Σοφία — η Σοφία, Νίκος — ο Νίκος.", "παιδί: αι → [e]", "είναι: ει → [i], αι → [e]", "που: ου → [u]", "μπαμπάς · ντομάτα · γκολ", "αυτό / αύριο · ευχαριστώ / ευγενικός"], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A1-007-I16", "U-A1-007-I17", "U-A1-007-I18", "U-A1-007-I22"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Историческая уровневая тематическая карта; размещение требует эксперта", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Reception, production, interaction; author mapping, not official cut score", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "§3.2: γράμματα, δίψηφα", "source_id": "N401", "checked_on": "2026-10-14", "claim_scope": "Грамматическое/фонетическое правило; задания оригинальные", "evidence_type": "OFFICIAL_SCHOOL_GRAMMAR_NOT_AUTH_SYLLABUS"}, {"anchor": "Примечания к произношению μπ, ντ, γκ", "source_id": "N403", "checked_on": "2026-10-14", "claim_scope": "Грамматическое/фонетическое правило; задания оригинальные", "evidence_type": "OFFICIAL_SCHOOL_GRAMMAR_NOT_AUTH_SYLLABUS"}], "evidence_map": [{"delayed": ["U-A1-007-I16", "U-A1-007-I22"], "transfer": ["U-A1-007-I13", "U-A1-007-I15"], "source_ids": ["V201", "W322", "N401", "N403"], "prerequisites": [], "mastery_decision": {"rule": "Целевая связь/форма верна в контролируемом задании; самостоятельное применение в новом сообщении и переносе; повтор без подсказок через 7/14/28 дней. Не усреднять критическую смысловую ошибку.", "status": "NOT_ASSESSED", "pronunciation_gate": "ACTUAL_AUDIO_AND_INDEPENDENT_LISTENER_REQUIRED"}, "microcompetency_id": "U-A1-007-MC01", "observable_outcome": "Соотнести 24 прописные и строчные буквы и выделить конечную ς.", "evidence_is_collected": false, "independent_production": ["U-A1-007-I07", "U-A1-007-I19"], "recognition_or_controlled": ["U-A1-007-I01", "U-A1-007-I02", "U-A1-007-I03", "U-A1-007-I19"], "success_criteria_specific": "Соотнести 24 прописные и строчные буквы и выделить конечную ς."}, {"delayed": ["U-A1-007-I17", "U-A1-007-I22"], "transfer": ["U-A1-007-I21", "U-A1-007-I22"], "source_ids":