le": "Το δέμα είναι εδώ.", "inflection": "τα δέματα", "meaning_ru": "посылка", "collocations": ["ένα δέμα"]}, {"lemma": "το γάλα", "stress": "το γάλα", "example": "Θέλω γάλα.", "inflection": "του γάλακτος", "meaning_ru": "молоко", "collocations": ["θέλω γάλα"]}, {"lemma": "το χέρι", "stress": "το χέρι", "example": "Το χέρι μου είναι εδώ.", "inflection": "τα χέρια", "meaning_ru": "рука", "collocations": ["το χέρι μου"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-008-I01"], "learning_objectives": ["Указать ударный слог в знакомых словах и сохранить смысловой контраст.", "Связать разные написания с пятью гласными без русской редукции.", "Осознанно воспроизвести θ/δ и χ/γ; проверить понятность по записи у человека."], "microcompetency_ids": ["U-A1-008-MC01", "U-A1-008-MC02", "U-A1-008-MC03"], "primary_competencies": ["A1-P02"], "learner_data_included": false, "speaking_scenario_ids": ["SC37"], "estimated_active_minutes": 65}	4d47cebc64092148c7335584e516887ec0fefc91cabaf613c8a98d3f6beef56b	3114
U-A1-009	A1	109	Добавить, противопоставить, объяснить: και, αλλά, γιατί	{A1-G05,A1-G06}	{}	{A1-G11}	{A1-G11}	45	{"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "DRAFT", "rubrics": ["U-A1-009-RUBRIC"], "unit_id": "U-A1-009", "version": "0.1.2", "sections": {"theory": "theory_ru", "practice": ["U-A1-009-I02", "U-A1-009-I03", "U-A1-009-I04", "U-A1-009-I05", "U-A1-009-I06", "U-A1-009-I07", "U-A1-009-I08", "U-A1-009-I09"], "reception": ["U-A1-009-I10", "U-A1-009-I11", "U-A1-009-I12", "U-A1-009-I13"], "retention": ["U-A1-009-I17", "U-A1-009-I18", "U-A1-009-I19"], "diagnostic": ["U-A1-009-I01"], "production": ["U-A1-009-I14", "U-A1-009-I15", "U-A1-009-I16"]}, "title_ru": "Добавить, противопоставить, объяснить: και, αλλά, γιατί", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Отдельные правильные предложения ещё не объясняют ваш выбор. Сначала решите, какую связь должен услышать собеседник. Και добавляет: Θέλω τσάι και νερό. Можно соединить слова или сообщения. При общем исполнителе не нужно повторять εγώ. Αλλά отмечает ограничение или неожиданное отличие: Θέλω καφέ, αλλά δεν έχω χρήματα. Желание остаётся, но покупка затруднена.\\nΓιατί вводит объяснение: Μένω εδώ γιατί δουλεύω κοντά. Сначала решение, затем причина. Не переставляйте части механически: «работаю рядом, потому что живу здесь» сообщает другую причинную связь. В вопросе Γιατί μένεις εδώ; это «почему?», а в ответе — «потому что». Греческий вопросительный знак похож на точку с запятой. Сначала ответьте коротко, затем полным предложением.\\nПрочитайте две мысли; назовите связь; соедините их; закройте текст и передайте ситуацию своими словами. Один набор фактов иногда допускает разные отношения. Поэтому в закрытых заданиях обозначено намерение; в свободном ответе другая логичная связь принимается, если выполнено условие. Сравните Έχω χρόνο και έρχομαι — добавление; Έχω χρόνο, αλλά μένω σπίτι — контраст; Έρχομαι γιατί έχω χρόνο — объяснение.\\nДостаточно настоящего времени и знакомых отрицательных фраз; δεν подробно тренируется в U-A1-010. Не включайте все три союза в каждую реплику. Успех — когда партнёр понимает ваш выбор, ограничение и причину, а не просто слышит три союза. После упражнения смените место встречи и причину, чтобы проверить перенос.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Η Ελένη διαβάζει και ο Πέτρος γράφει.", "Θέλω νερό και ένα τσάι.", "Το σπίτι είναι μικρό, αλλά είναι ωραίο.", "Μένω σπίτι γιατί είμαι άρρωστη.", "Γιατί φεύγεις; — Γιατί έχω δουλειά.", "Έχω χρόνο, αλλά το καφέ είναι κλειστό."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "delivery": "Use concrete D7 and D28 scenarios in microcompetencies.json alongside closed retrieval; no observed mastery yet", "item_ids": ["U-A1-009-I17", "U-A1-009-I18", "U-A1-009-I19"], "hypothesis_not_official": true, "independent_followup_micro_ids": ["U-A1-009-MC01", "U-A1-009-MC02", "U-A1-009-MC03"]}, "source_refs": [{"anchor": "A1-G11 historical curricular theme only", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "A1 interaction/production, project mapping", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "§5.1 συμπλεκτικοί/αντιθετικοί; §5.2 αιτιολογικές", "source_id": "N404", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}], "active_recall": ["U-A1-009-I08", "U-A1-009-I09"], "prerequisites": ["A1-G05", "A1-G06"], "reading_tasks": ["U-A1-009-I10", "U-A1-009-I11"], "transfer_task": "U-A1-009-I16", "writing_tasks": ["U-A1-009-I14"], "competency_ids": ["A1-G11"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "reconstruction": {"date": "2026-10-15", "basis": "Saved authoring text and review findings in conversation; reconstructed after workspace cleanup; byte identity to lost drafts not claimed", "previous_unsaved_version": "0.1.0"}, "speaking_tasks": ["U-A1-009-I15"], "errors_taxonomy": ["CONNECTOR_RELATION", "CAUSE_DIRECTION", "MISSING_INDEPENDENT_PRODUCTION"], "guided_practice": ["U-A1-009-I02", "U-A1-009-I03", "U-A1-009-I04", "U-A1-009-I05", "U-A1-009-I06", "U-A1-009-I07"], "listening_tasks": ["U-A1-009-I12", "U-A1-009-I13"], "learning_outcome": "Соединить два факта с και и отличить добавление от противопоставления", "mastery_contract": {"audio": "Не оценивается без аудио", "unaided": "Две самостоятельные реплики без модели", "observed": false, "transfer": "Все условия новой ситуации; целевая форма=2, другие критерии≥1", "retention": "D7/D14/D28 без подсказок плюс новая свободная реплика", "controlled": "≥80% целевых форм; смысловая ошибка требует повторного обучения"}, "vocabulary_items": [{"lemma": "κοντά", "stress": "κοντά", "example": "Δουλεύω κοντά.", "inflection": "наречие", "meaning_ru": "рядом", "collocations": ["δουλεύω κοντά"]}, {"lemma": "κλειστός", "stress": "κλειστός", "example": "Το καφέ είναι κλειστό.", "inflection": "κλειστή, κλειστό", "meaning_ru": "закрытый", "collocations": ["είναι κλειστό"]}, {"lemma": "χρόνος", "stress": "χρόνος", "example": "Έχω χρόνο σήμερα.", "inflection": "ο χρόνος", "meaning_ru": "время", "collocations": ["έχω χρόνο"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-009-I01"], "learning_objectives": ["Соединить два факта с και и отличить добавление от противопоставления", "Объяснить выбор с γιατί, сохранив направление причины", "Без образца договориться о встрече: факт, ограничение, причина"], "microcompetency_ids": ["U-A1-009-MC01", "U-A1-009-MC02", "U-A1-009-MC03"], "primary_competencies": ["A1-G11"], "learner_data_included": false, "estimated_active_minutes": 45}	17c6efd1d895fe5aa1c85896463d01d98108aa224a85520c652b0b920626a6a1	3115
U-A1-010	A1	110	Не делаю и не делай: отрицательная реплика	{A1-G05,A1-G06,A1-G11}	{}	{A1-G08}	{A1-G08}	45	{"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "DRAFT", "rubrics": ["U-A1-010-RUBRIC"], "unit_id": "U-A1-010", "version": "0.1.3", "sections": {"theory": "theory_ru", "practice": ["U-A1-010-I02", "U-A1-010-I03", "U-A1-010-I04", "U-A1-010-I05", "U-A1-010-I06", "U-A1-010-I07", "U-A1-010-I08", "U-A1-010-I09"], "reception": ["U-A1-010-I10", "U-A1-010-I11", "U-A1-010-I12", "U-A1-010-I13"], "retention": ["U-A1-010-I17", "U-A1-010-I18", "U-A1-010-I19"], "diagnostic": ["U-A1-010-I01"], "production": ["U-A1-010-I14", "U-A1-010-I15", "U-A1-010-I16"]}, "title_ru": "Не делаю и не делай: отрицательная реплика", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Όχι — самостоятельное «нет». При отрицании сообщения с глаголом ставим δε(ν): Δεν έχω χρόνο. Не заменяем это на όχι έχω. Κороткое Όχι допустимо, но адресату часто нужно продолжение: Όχι, δεν είμαι ο Νίκος. Είμαι ο Πέτρος. Отрицание исправляет ошибку, второе предложение даёт верную информацию.\\nЗапрет строится с μη(ν): Μην τρέχεις! — не беги; Μην αργείς! — не опаздывай. Δεν τρέχεις сообщает, что ты не бежишь/не бегаешь; Μην τρέχεις! просит остановить действие. Нельзя ставить μην перед любой утвердительной командой. Здесь запоминаем сочетания μην τρέχεις, μην αργείς, μην περιμένεις, μη μιλάς целиком; полная система повеления и вида — позже. Вежливость зависит от контекста: знакомому добавьте σε παρακαλώ.\\nВ школьном правиле конечное ν сохраняется перед гласной и κ, π, τ, γκ, μπ, ντ, τσ, τζ, ξ, ψ: δεν έχω, δεν ξέρω, μην τρέχεις, но δε μένω, μη μιλάς. Различение функции важнее механического поиска буквы. В более широкой практике встречаются варианты; непривычную, но осмысленную форму направляем на проверку, не автоматически штрафуем.\\nТренируйте отдельно отсутствие, отказ и предупреждение. Прочитайте реплику, назовите намерение и произнесите новую фразу без текста. Затем соедините отказ с причиной из U-A1-009. Полезные формулы: Δεν ξέρω — не знаю; Δεν είμαι έτοιμος/έτοιμη — не готов/готова; Αύριο έχω χρόνο — завтра есть время. В тексте чтения αν означает «ли» после δεν ξέρω; это только рецептивная опора. Успех — понятный отказ с продолжением и запрет, не перепутанный с описанием.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Όχι, δεν έχω χρόνο.", "Δεν είμαι η Μαρία. Είμαι η Ελένη.", "Δεν ξέρω.", "Δε μένω εδώ.", "Μην τρέχεις, σε παρακαλώ.", "Μη μιλάς τώρα, σε παρακαλώ."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "delivery": "Use concrete D7 and D28 scenarios in microcompetencies.json alongside closed retrieval; no observed mastery yet", "item_ids": ["U-A1-010-I17", "U-A1-010-I18", "U-A1-010-I19"], "hypothesis_not_official": true, "independent_followup_micro_ids": ["U-A1-010-MC01", "U-A1-010-MC02", "U-A1-010-MC03"]}, "source_refs": [{"anchor": "A1-G08 historical curricular theme only", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "A1 interaction/production, project mapping", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "§5.2 άρνηση δε(ν)/μη(ν); τελικό ν", "source_id": "N404", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}], "active_recall": ["U-A1-010-I08", "U-A1-010-I09"], "prerequisites": ["A1-G05", "A1-G06", "A1-G11"], "reading_tasks": ["U-A1-010-I10", "U-A1-010-I11"], "transfer_task": "U-A1-010-I16", "writing_tasks": ["U-A1-010-I14"], "competency_ids": ["A1-G08"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "reconstruction": {"date": "2026-10-15", "basis": "Saved authoring text and review findings in conversation; reconstructed after workspace cleanup; byte identity to lost drafts not claimed", "previous_unsaved_version": "0.1.0"}, "speaking_tasks": ["U-A1-010-I15"], "errors_taxonomy": ["NEGATIVE_STATEMENT_VS_PROHIBITION", "OXI_AS_VERBAL_NEGATOR", "FINAL_NU", "REFUSAL_WITHOUT_INFORMATION"], "guided_practice": ["U-A1-010-I02", "U-A1-010-I03", "U-A1-010-I04", "U-A1-010-I05", "U-A1-010-I06", "U-A1-010-I07"], "listening_tasks": ["U-A1-010-I12", "U-A1-010-I13"], "learning_outcome": "Отрицать сообщение с δεν и продолжать ответ после όχι", "mastery_contract": {"audio": "Не оценивается без аудио", "unaided": "Две самостоятельные реплики без модели", "observed": false, "transfer": "Все условия новой ситуации; целевая форма=2, другие критерии≥1", "retention": "D7/D14/D28 без подсказок плюс новая свободная реплика", "controlled": "≥80% целевых форм; смысловая ошибка требует повторного обучения"}, "vocabulary_items": [{"lemma": "περιμένω", "stress": "περιμένω", "example": "Μην περιμένεις εδώ.", "inflection": "περιμένεις", "meaning_ru": "ждать", "collocations": ["μην περιμένεις"]}, {"lemma": "τρέχω", "stress": "τρέχω", "example": "Μην τρέχεις στον δρόμο.", "inflection": "τρέχεις", "meaning_ru": "бежать", "collocations": ["μην τρέχεις"]}, {"lemma": "αργώ", "stress": "αργώ", "example": "Μην αργείς, σε παρακαλώ.", "inflection": "αργείς", "meaning_ru": "опаздывать", "collocations": ["μην αργείς"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-010-I01"], "learning_objectives": ["Отрицать сообщение с δεν и продолжать ответ после όχι", "Различить сообщение и запрет в готовых фразах", "Самостоятельно отказаться, исправить информацию, предупредить"], "microcompetency_ids": ["U-A1-010-MC01", "U-A1-010-MC02", "U-A1-010-MC03"], "primary_competencies": ["A1-G08"], "learner_data_included": false, "estimated_active_minutes": 45}	6da3bc2b87db571c57d34ac2192acb05fdd5c227827b6f2ec89b732778a8c77a	3116
U-A1-011	A1	111	Мои вещи и нужное количество	{A1-G01,A1-G02,A1-G03}	{}	{A1-G10}	{A1-G10}	45	{"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "DRAFT", "rubrics": ["U-A1-011-RUBRIC"], "unit_id": "U-A1-011", "version": "0.1.2", "sections": {"theory": "theory_ru", "practice": ["U-A1-011-I02", "U-A1-011-I03", "U-A1-011-I04", "U-A1-011-I05", "U-A1-011-I06", "U-A1-011-I07", "U-A1-011-I08", "U-A1-011-I09"], "reception": ["U-A1-011-I10", "U-A1-011-I11", "U-A1-011-I12", "U-A1-011-I13"], "retention": ["U-A1-011-I17", "U-A1-011-I18", "U-A1-011-I19"], "diagnostic": ["U-A1-011-I01"], "production": ["U-A1-011-I14", "U-A1-011-I15", "U-A1-011-I16"]}, "title_ru": "Мои вещи и нужное количество", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Μου после существительного указывает на мою вещь: το βιβλίο μου. Σου — на вещь собеседника: η τσάντα σου. Род вещи меняет артикль и существительное, но не владельца: ο φίλος μου, η φίλη μου, το βιβλίο μου. Τα βιβλία μου — много моих книг; μας означает «наши», то есть меняет владельцев. Рецептивная подсказка для чтения: του — его, της — её, μας — наши, σας — ваши, τους — их.\\nНе ставьте σου перед существительным по русской модели. Для простого называния берём η τσάντα σου. Подчёркнутое противопоставление может использовать δικός/δική/δικό, но здесь достаточно Αυτό είναι το βιβλίο μου, όχι το βιβλίο σου. После слова с ударением на третьем слоге от конца перед односложным притяжательным появляется дополнительное ударение: το τηλέφωνό μου. Значение владельца не меняется; сначала учите сочетание целиком.\\nКоличество относится к вещам: ένας καφές, μία τσάντα, ένα βιβλίο. После θέλω мужской винительный: έναν καφέ. Два: δύο/δυο для всех родов. Три: τρεις καφέδες/τσάντες, но τρία βιβλία. Четыре: τέσσερις καφέδες/τσάντες, но τέσσερα βιβλία. Пять: πέντε βιβλία, без изменения по роду. Не говорим τρία βιβλίο: существительное тоже во множественном.\\nДля вещества полезны λίγο νερό, ένα μπουκάλι νερό, δύο μπουκάλια νερό. Считаем бутылки. В магазине ένα νερό может означать одну порцию/бутылку воды по ситуации, не абстрактную «одну воду». Сначала установите владельца, затем вид и количество предметов. Исправьте ошибку собеседника и проверьте, понял ли он. Для самостоятельной практики поменяйте предметы и числа. Успех — нужные вещи у нужного человека, а не воспроизведение таблицы.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Το βιβλίο μου είναι εδώ.", "Η τσάντα σου είναι μικρή.", "Τα βιβλία μου είναι εδώ.", "Θέλω έναν καφέ και ένα νερό.", "Έχω τρεις τσάντες και τέσσερα βιβλία.", "Το τηλέφωνό μου είναι στην τσάντα μου."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "delivery": "Use concrete D7 and D28 scenarios in microcompetencies.json alongside closed retrieval; no observed mastery yet", "item_ids": ["U-A1-011-I17", "U-A1-011-I18", "U-A1-011-I19"], "hypothesis_not_official": true, "independent_followup_micro_ids": ["U-A1-011-MC01", "U-A1-011-MC02", "U-A1-011-MC03"]}, "source_refs": [{"anchor": "A1-G10 historical curricular theme only", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "A1 interaction/production, project mapping", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "§5.2 κτητικές", "source_id": "N410", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}, {"anchor": "§4.2 απόλυτα αριθμητικά", "source_id": "N411", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}, {"anchor": "§4.3 εγκλιτικά", "source_id": "N407", "checked_on": "2026-10-14", "claim_scope": "Правило проверено до очистки; примеры оригинальные, не цитаты источника", "evidence_type": "OTHER_ACADEMIC"}], "active_recall": ["U-A1-011-I08", "U-A1-011-I09"], "prerequisites": ["A1-G01", "A1-G02", "A1-G03"], "reading_tasks": ["U-A1-011-I10", "U-A1-011-I11"], "transfer_task": "U-A1-011-I16", "writing_tasks": ["U-A1-011-I14"], "competency_ids": ["A1-G10"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "reconstruction": {"date": "2026-10-15", "basis": "Saved authoring text and review findings in conversation; reconstructed after workspace cleanup; byte identity to lost drafts not claimed", "previous_unsaved_version": "0.1.0"}, "speaking_tasks": ["U-A1-011-I15"], "errors_taxonomy": ["POSSESSOR_VS_OBJECT_NUMBER", "POSSESSIVE_POSITION", "NUMERAL_GENDER_CASE", "COUNT_UNIT", "ENCLITIC_STRESS"], "guided_practice": ["U-A1-011-I02", "U-A1-011-I03", "U-A1-011-I04", "U-A1-011-I05", "U-A1-011-I06", "U-A1-011-I07"], "listening_tasks": ["U-A1-011-I12", "U-A1-011-I13"], "learning_outcome": "Указать владельца с μου/σου независимо от рода вещи", "mastery_contract": {"audio": "Не оценивается без аудио", "unaided": "Две самостоятельные реплики без модели", "observed": false, "transfer": "Все условия новой ситуации; целевая форма=2, другие критерии≥1", "retention": "D7/D14/D28 без подсказок плюс новая свободная реплика", "controlled": "≥80% целевых форм; смысловая ошибка требует повторного обучения"}, "vocabulary_items": [{"lemma": "τσάντα", "stress": "τσάντα", "example": "Η τσάντα μου είναι εδώ.", "inflection": "η τσάντα, οι τσάντες", "meaning_ru": "сумка", "collocations": ["η τσάντα μου"]}, {"lemma": "μπουκάλι", "stress": "μπουκάλι", "example": "Θέλω δύο μπουκάλια νερό.", "inflection": "το μπουκάλι, τα μπουκάλια", "meaning_ru": "бутылка", "collocations": ["ένα μπουκάλι νερό"]}, {"lemma": "τηλέφωνο", "stress": "τηλέφωνο", "example": "Πού είναι το τηλέφωνό σου;", "inflection": "το τηλέφωνο; το τηλέφωνό μου", "meaning_ru": "телефон", "collocations": ["το τηλέφωνό σου"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-011-I01"], "learning_objectives": ["Указать владельца с μου/σου независимо от рода вещи", "Выбрать один/три/четыре по роду и падежу", "Исправить владельца и количество в новом обмене"], "microcompetency_ids": ["U-A1-011-MC01", "U-A1-011-MC02", "U-A1-011-MC03"], "primary_competencies": ["A1-G10"], "learner_data_included": false, "estimated_active_minutes": 45}	a95058fa4ad5ba2d78741cf04d2f28b3e80330f1a084e09f0f81bcfc60cf69f6	3117
U-A1-012	A1	112	Знакомство, семья, учёба и интересы	{A1-G05,A1-G06,A1-G07,A1-G10}	{}	{A1-V01}	{A1-V01}	65	{"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A1-012-RUBRIC"], "unit_id": "U-A1-012", "version": "0.1.0", "title_ru": "Знакомство, семья, учёба и интересы", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "В этом уроке вы представляете себя и другого человека, различаете семейные и учебные роли и поддерживаете короткий разговор об интересах. Используйте вымышленные сведения: реальные фамилии, адреса и данные родственников не нужны. Лексика организована по ситуациям, а не как список для заучивания.\\nЗнакомство: Με λένε Άννα / Είμαι η Άννα. В анкете όνομα — имя, επώνυμο — фамилия. Από πού είσαι; спрашивает о происхождении; Πού μένεις; — о нынешнем месте проживания. Είμαι από την Πάτρα, αλλά μένω στην Αθήνα. Не подменяйте эти два факта друг другом. Πώς σε λένε; — готовый вопрос об имени; формы λένε/λέγομαι здесь не требуют освоения всей парадигмы.\\nСемья: η μητέρα μου, ο πατέρας μου, ο αδελφός μου, η αδελφή μου. Принадлежность ставится после существительного, как в U-A1-011. Έχω έναν αδελφό и Ο αδελφός μου είναι μαθητής решают разные задачи: наличие родственника и его описание. Если не хотите говорить о семье, можно описать вымышленного друга. Не предполагаем, что у каждого есть супруг, дети или братья.\\nУчёба и работа: Είμαι μαθητής/μαθήτρια — школьник/школьница; φοιτητής/φοιτήτρια — студент/студентка вуза. Δουλεύω σε καφέ/σε γραφείο указывает место работы, а Είμαι δάσκαλος/δασκάλα — профессию. В нейтральном назывании профессии после είμαι учим готовое Είμαι δασκάλα. В Ο δάσκαλος είναι εδώ артикль называет конкретного человека. Δεν δουλεύω τώρα — допустимый ответ; не нужно придумывать работу. Для школы: το σχολείο, το μάθημα, ο δάσκαλος. Σπουδάζω — учусь в вузе, готовое употребление без новой грамматической цели.\\nИнтересы: Μου αρέσει η μουσική / το ποδόσφαιρο — мне нравится музыка / футбол. Пока используем этот блок с одним названием; множественное μου αρέσουν систематизируется отдельно. Παίζω ποδόσφαιρο — играю; βλέπω ποδόσφαιρο/αγώνες — смотрю. Человек может делать только одно из двух. Не выводите команду, профессию или характер человека из его увлечения. Η ομάδα μου — моя команда; ο αγώνας — матч. Футбол — вариант персонализации: можно заменить его музыкой, чтением или другим знакомым занятием.\\nСтройте разговор из взаимных реплик: представьтесь, ответьте, задайте встречный вопрос, уточните ошибочное предположение. Εσύ; годится как встречный вопрос после понятной темы. Для восстановления общения: Συγγνώμη, πάλι, παρακαλώ. Сначала произнесите 4–6 фраз без текста, затем проверьте, что не перепутали имя, родство, работу и увлечение. Красивый длинный рассказ с неверными фактами не считается выполнением задачи. Скрипт будущей записи пока используется только как чтение; произношение по печатному ответу не оценивается.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Το όνομά μου είναι Άννα.", "Το επώνυμό μου είναι Δήμου.", "Η οικογένειά μου μένει στην Πάτρα.", "Η μητέρα μου δουλεύει εδώ.", "Ο πατέρας μου είναι γιατρός.", "Έχω έναν αδελφό.", "Η αδελφή μου είναι μαθήτρια.", "Είμαι φοιτήτρια στην Αθήνα.", "Η Άννα είναι δασκάλα.", "Είμαι στη δουλειά.", "Δουλεύω σε γραφείο.", "Ακούω μουσική το βράδυ.", "Παίζω ποδόσφαιρο με φίλους.", "Βλέπω έναν αγώνα στην τηλεόραση.", "Η ομάδα μου παίζει σήμερα.", "Παίζω με φίλους."], "review_plan": {"days": [7, 14, 28], "rule": "Новый ответ без модели; после подсказки сохранять assisted, повторить самостоятельно с новыми данными.", "item_ids": ["U-A1-012-I17", "U-A1-012-I18", "U-A1-012-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Παραγωγή γραπτού λόγου; Αναγνώριση ταυτότητας; Κατοικία, διαμονή; Ελεύθερος χρόνος; Επαγγελματικός χώρος", "source_id": "CP06-A1-S01", "checked_on": "2026-10-17", "claim_scope": "A1 functional domains only. No endorsement of GreekOS tasks, durations or mastery thresholds.", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR"}, {"anchor": "headword φοιτητής, feminine φοιτήτρια, main definition", "source_id": "CP06-A1-S02", "checked_on": "2026-10-17", "claim_scope": "University student meaning and feminine headword only", "evidence_type": "PRIMARY_LEXICOGRAPHIC"}, {"anchor": "επώνυμο το; main definition (line141 in retrieved view)", "source_id": "CP06-A1-S04", "checked_on": "2026-10-17", "claim_scope": "Family name sense only; historical social examples not adopted", "evidence_type": "PRIMARY_LEXICOGRAPHIC"}], "active_recall": ["U-A1-012-I08", "U-A1-012-I09"], "prerequisites": ["A1-G05", "A1-G06", "A1-G07", "A1-G10"], "reading_tasks": ["U-A1-012-I10", "U-A1-012-I11"], "transfer_task": "U-A1-012-I16", "writing_tasks": ["U-A1-012-I14"], "competency_ids": ["A1-V01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; no observed learner mastery", "speaking_tasks": ["U-A1-012-I15"], "errors_taxonomy": ["FACT_SUBSTITUTION", "LEXICAL_ROLE_CONFUSION", "REGISTER_MISMATCH", "UNSUPPORTED_INFERENCE", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A1-012-I02", "U-A1-012-I03", "U-A1-012-I04", "U-A1-012-I05", "U-A1-012-I06", "U-A1-012-I07"], "listening_tasks": ["U-A1-012-I12", "U-A1-012-I13"], "reading_text_el": "Με λένε Ελένη. Είμαι από την Πάτρα και μένω στην Αθήνα. Είμαι φοιτήτρια και δουλεύω σε ένα καφέ το Σάββατο. Ο αδελφός μου, ο Πέτρος, είναι μαθητής. Η μητέρα μου είναι γιατρός. Μου αρέσει η μουσική. Παίζω ποδόσφαιρο την Κυριακή με φίλους, αλλά δεν βλέπω ποδόσφαιρο στην τηλεόραση. Ο Πέτρος βλέπει αγώνες, αλλά δεν παίζει.", "learning_outcome": "Представить личность и семейную/учебную роль без подмены фактов", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "transfer": "I16 + новая самостоятельная речь на I17/I19 по item-specific anchors", "controlled": "≥80% закрытых ответов, затем исправление всех смысловых ошибок"}, "vocabulary_items": [{"lemma": "όνομα", "stress": "όνομα", "example": "Το όνομά μου είναι Άννα.", "inflection": "το όνομα", "meaning_ru": "имя", "collocations": ["το όνομά μου"]}, {"lemma": "επώνυμο", "stress": "επώνυμο", "example": "Το επώνυμό μου είναι Δήμου.", "inflection": "το επώνυμο", "meaning_ru": "фамилия", "collocations": ["όνομα και επώνυμο"]}, {"lemma": "οικογένεια", "stress": "οικογένεια", "example": "Η οικογένειά μου μένει στην Πάτρα.", "inflection": "η οικογένεια", "meaning_ru": "семья", "collocations": ["η οικογένειά μου"]}, {"lemma": "μητέρα", "stress": "μητέρα", "example": "Η μητέρα μου δουλεύει εδώ.", "inflection": "η μητέρα", "meaning_ru": "мать", "collocations": ["η μητέρα μου"]}, {"lemma": "πατέρας", "stress": "πατέρας", "example": "Ο πατέρας μου είναι γιατρός.", "inflection": "ο πατέρας", "meaning_ru": "отец", "collocations": ["ο πατέρας μου"]}, {"lemma": "αδελφός", "stress": "αδελφός", "example": "Έχω έναν αδελφό.", "inflection": "ο αδελφός / η αδελφή", "meaning_ru": "брат / сестра", "collocations": ["ο αδελφός μου"]}, {"lemma": "μαθητής", "stress": "μαθητής", "example": "Η αδελφή μου είναι μαθήτρια.", "inflection": "ο μαθητής / η μαθήτρια", "meaning_ru": "ученик / ученица", "collocations": ["είμαι μαθητής"]}, {"lemma": "φοιτητής", "stress": "φοιτητής", "example": "Είμαι φοιτήτρια στην Αθήνα.", "inflection": "ο φοιτητής / η φοιτήτρια", "meaning_ru": "студент / студентка вуза", "collocations": ["είμαι φοιτήτρια"]}, {"lemma": "δάσκαλος", "stress": "δάσκαλος", "example": "Η Άννα είναι δασκάλα.", "inflection": "ο δάσκαλος / η δασκάλα", "meaning_ru": "учитель / учительница", "collocations": ["είμαι δασκάλα"]}, {"lemma": "δουλειά", "stress": "δουλειά", "example": "Είμαι στη δουλειά.", "inflection": "η δουλειά", "meaning_ru": "работа", "collocations": ["στη δουλειά"]}, {"lemma": "γραφείο", "stress": "γραφείο", "example": "Δουλεύω σε γραφείο.", "inflection": "το γραφείο", "meaning_ru": "офис; письменный стол по контексту", "collocations": ["σε γραφείο"]}, {"lemma": "μουσική", "stress": "μουσική", "example": "Ακούω μουσική το βράδυ.", "inflection": "η μουσική", "meaning_ru": "музыка", "collocations": ["ακούω μουσική"]}, {"lemma": "ποδόσφαιρο", "stress": "ποδόσφαιρο", "example": "Παίζω ποδόσφαιρο με φίλους.", "inflection": "το ποδόσφαιρο", "meaning_ru": "футбол", "collocations": ["παίζω ποδόσφαιρο"]}, {"lemma": "αγώνας", "stress": "αγώνας", "example": "Βλέπω έναν αγώνα στην τηλεόραση.", "inflection": "ο αγώνας / οι αγώνες", "meaning_ru": "матч; состязание", "collocations": ["βλέπω έναν αγώνα"]}, {"lemma": "ομάδα", "stress": "ομάδα", "example": "Η ομάδα μου παίζει σήμερα.", "inflection": "η ομάδα", "meaning_ru": "команда", "collocations": ["η ομάδα μου"]}, {"lemma": "φίλος", "stress": "φίλος", "example": "Παίζω με φίλους.", "inflection": "ο φίλος / η φίλη", "meaning_ru": "друг / подруга", "collocations": ["με φίλους"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-012-I01"], "learning_objectives": ["Представить личность и семейную/учебную роль без подмены фактов", "Различить занятие и интерес: работать, учиться, играть и смотреть", "Поддержать взаимный разговор, исправить предположение и перенести лексику на новую личность"], "microcompetency_ids": ["U-A1-012-MC01", "U-A1-012-MC02", "U-A1-012-MC03"], "prerequisite_support": {"A1-G05": "U-A1-001: είμαι/έχω; при ошибках I01 вернуться к короткому представлению", "A1-G06": "U-A1-005: настоящее время", "A1-G07": "U-A1-004: вопросы", "A1-G10": "U-A1-011: принадлежность"}, "primary_competencies": ["A1-V01"], "learner_data_included": false, "estimated_active_minutes": 65}	4db5f9c5dc035a236073374ccaf8328d1702b5d7a9df36607dc70faf9d9b4cd1	3118
U-A1-013	A1	113	Дом, район, транспорт и обычный день	{A1-G05,A1-G06,A1-G07,A1-G09}	{}	{A1-V03}	{A1-V03}	65	{"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A1-013-RUBRIC"], "unit_id": "U-A1-013", "version": "0.1.2", "title_ru": "Дом, район, транспорт и обычный день", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Цель — описать жильё и ближайшие места так, чтобы другой человек нашёл нужный ориентир, затем рассказать о дороге и обычном дне. Реальный адрес не нужен: все места в заданиях вымышлены. Краткая проверка: умеете ли вы сказать είμαι/μένω, задать Πού…; и соединить σε с артиклем? При затруднении повторите указанные подготовительные уроки.\\nΤο σπίτι — дом или жилище в целом; το διαμέρισμα — квартира. Модель Μένω σε διαμέρισμα описывает тип жилья, Μένω στο κέντρο — район. В описании комнаты используйте το υπνοδωμάτιο, η κουζίνα, το μπάνιο. Το σπίτι έχει μια κουζίνα называет состав жилья; Είμαι στην κουζίνα сообщает, где сейчас человек. Не смешивайте местонахождение и наличие.\\nРаботайте с отношениями между двумя объектами. Δίπλα στο σπίτι — рядом с домом; απέναντι από τον φούρνο — напротив пекарни; μπροστά στο σχολείο — перед школой; κοντά στο κέντρο — недалеко от центра. Последний блок не даёт расстояния в метрах. Если в тексте есть только κοντά, нельзя придумывать «две минуты пешком». Это готовые сочетания на основе уже изученных предлогов, а не новый полный раздел управления. Запоминайте существительное вместе с артиклем: η στάση — στη στάση, το σχολείο — στο σχολείο.\\nΟ φούρνος в описании улицы обычно пекарня, но в кухне может быть духовка. Контекст нужен даже знакомому слову. Η στάση здесь транспортная остановка; другие значения пока не изучаем. Μπροστά στο σχολείο относится к остановке, если именно она названа подлежащим: не переносите это отношение автоматически на дом.\\nМаршрут и транспорт: Πηγαίνω στη δουλειά με το λεωφορείο. Γυρίζω με τα πόδια. Выражение με τα πόδια — пешком, его нельзя переводить как транспортное средство. Утренний и обратный маршрут могут различаться. Πού πηγαίνεις; спрашивает пункт назначения, Πώς πηγαίνεις; — способ. В коротком ответе Με το λεωφορείο достаточно, когда вопрос уже задан.\\nДля распорядка нужны опоры το πρωί, το βράδυ, την Κυριακή. Μαγειρεύω, δουλεύω, γυρίζω — действия; не пытайтесь вывести время каждого из смысла глагола. Соедините 3–5 предложений с και, αλλά. При недостатке информации спросите: Πού ακριβώς; — где именно? Εδώ; — здесь? Повторите ориентир своими словами, чтобы проверить понимание.\\nПрактика проходит от выбора отношения к описанию нового района. При проверке важнее сохранение того, что находится рядом или напротив чего, чем буквальное совпадение с моделью. Сначала самостоятельный ответ, затем сверка. Для переноса изменяются тип жилья, ориентиры и способ поездки. Отложенные задания оценивают новые данные; память текста не заменяет умения. Аудиоскрипт пока не является существующим аудиофайлом.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Μένω σε διαμέρισμα.", "Το σπίτι έχει ένα υπνοδωμάτιο.", "Μαγειρεύω στην κουζίνα.", "Το μπάνιο είναι μικρό.", "Έχει φούρνο στη γειτονιά.", "Αγοράζω ψωμί στον φούρνο.", "Το φαρμακείο είναι απέναντι.", "Περιμένω στη στάση.", "Πηγαίνω με το λεωφορείο.", "Γυρίζω με τα πόδια.", "Δουλεύω το πρωί.", "Μαγειρεύω το βράδυ."], "review_plan": {"days": [7, 14, 28], "rule": "Новый ответ без модели; после подсказки сохранять assisted, повторить самостоятельно с новыми данными.", "item_ids": ["U-A1-013-I17", "U-A1-013-I18", "U-A1-013-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Παραγωγή γραπτού λόγου; Αναγνώριση ταυτότητας; Κατοικία, διαμονή; Ελεύθερος χρόνος; Επαγγελματικός χώρος", "source_id": "CP06-A1-S01", "checked_on": "2026-10-17", "claim_scope": "A1 functional domains only. No endorsement of GreekOS tasks, durations or mastery thresholds.", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR"}, {"anchor": "στάση¹ 1β", "source_id": "CP06-A1-S03", "checked_on": "2026-10-17", "claim_scope": "Transport stop sense only, not political/social senses", "evidence_type": "PRIMARY_LEXICOGRAPHIC"}], "active_recall": ["U-A1-013-I08", "U-A1-013-I09"], "prerequisites": ["A1-G05", "A1-G06", "A1-G07", "A1-G09"], "reading_tasks": ["U-A1-013-I10", "U-A1-013-I11"], "transfer_task": "U-A1-013-I16", "writing_tasks": ["U-A1-013-I14"], "competency_ids": ["A1-V03"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; no observed learner mastery", "speaking_tasks": ["U-A1-013-I15"], "errors_taxonomy": ["FACT_SUBSTITUTION", "LEXICAL_ROLE_CONFUSION", "REGISTER_MISMATCH", "UNSUPPORTED_INFERENCE", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A1-013-I02", "U-A1-013-I03", "U-A1-013-I04", "U-A1-013-I05", "U-A1-013-I06", "U-A1-013-I07"], "listening_tasks": ["U-A1-013-I12", "U-A1-013-I13"], "reading_text_el": "Μένω σε ένα μικρό διαμέρισμα κοντά στο κέντρο. Έχει ένα υπνοδωμάτιο, μια κουζίνα και ένα μπάνιο. Δίπλα στο σπίτι είναι ένας φούρνος. Το φαρμακείο είναι απέναντι από τον φούρνο. Η στάση είναι μπροστά στο σχολείο. Το πρωί πηγαίνω στη δουλειά με το λεωφορείο. Το βράδυ γυρίζω με τα πόδια. Την Κυριακή μένω στο σπίτι και μαγειρεύω.", "learning_outcome": "Назвать жильё, комнаты и ориентиры без домысливания расстояния", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "transfer": "I16 + новая самостоятельная речь на I17/I19 по item-specific anchors", "controlled": "≥80% закрытых ответов, затем исправление всех смысловых ошибок"}, "vocabulary_items": [{"lemma": "διαμέρισμα", "stress": "διαμέρισμα", "example": "Μένω σε διαμέρισμα.", "inflection": "το διαμέρισμα", "meaning_ru": "квартира", "collocations": ["σε διαμέρισμα"]}, {"lemma": "υπνοδωμάτιο", "stress": "υπνοδωμάτιο", "example": "Το σπίτι έχει ένα υπνοδωμάτιο.", "inflection": "το υπνοδωμάτιο", "meaning_ru": "спальня", "collocations": ["ένα υπνοδωμάτιο"]}, {"lemma": "κουζίνα", "stress": "κουζίνα", "example": "Μαγειρεύω στην κουζίνα.", "inflection": "η κουζίνα", "meaning_ru": "кухня", "collocations": ["στην κουζίνα"]}, {"lemma": "μπάνιο", "stress": "μπάνιο", "example": "Το μπάνιο είναι μικρό.", "inflection": "το μπάνιο", "meaning_ru": "ванная", "collocations": ["στο μπάνιο"]}, {"lemma": "γειτονιά", "stress": "γειτονιά", "example": "Έχει φούρνο στη γειτονιά.", "inflection": "η γειτονιά", "meaning_ru": "район рядом с домом", "collocations": ["στη γειτονιά"]}, {"lemma": "φούρνος", "stress": "φούρνος", "example": "Αγοράζω ψωμί στον φούρνο.", "inflection": "ο φούρνος", "meaning_ru": "пекарня; духовка по контексту", "collocations": ["στον φούρνο"]}, {"lemma": "φαρμακείο", "stress": "φαρμακείο", "example": "Το φαρμακείο είναι απέναντι.", "inflection": "το φαρμακείο", "meaning_ru": "аптека", "collocations": ["στο φαρμακείο"]}, {"lemma": "στάση", "stress": "στάση", "example": "Περιμένω στη στάση.", "inflection": "η στάση", "meaning_ru": "остановка", "collocations": ["στη στάση"]}, {"lemma": "λεωφορείο", "stress": "λεωφορείο", "example": "Πηγαίνω με το λεωφορείο.", "inflection": "το λεωφορείο", "meaning_ru": "автобус", "collocations": ["με το λεωφορείο"]}, {"lemma": "πόδια", "stress": "πόδια", "example": "Γυρίζω με τα πόδια.", "inflection": "τα πόδια", "meaning_ru": "ноги; пешком в με τα πόδια", "collocations": ["με τα πόδια"]}, {"lemma": "πρωί", "stress": "πρωί", "example": "Δουλεύω το πρωί.", "inflection": "το πρωί", "meaning_ru": "утро; утром", "collocations": ["το πρωί"]}, {"lemma": "βράδυ", "stress": "βράδυ", "example": "Μαγειρεύω το βράδυ.", "inflection": "το βράδυ", "meaning_ru": "вечер; вечером", "collocations": ["το βράδυ"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-013-I01"], "learning_objectives": ["Назвать жильё, комнаты и ориентиры без домысливания расстояния", "Различить направление, транспорт и время обычного действия", "Объяснить новый маршрут, уточнить место и описать свой день"], "microcompetency_ids": ["U-A1-013-MC01", "U-A1-013-MC02", "U-A1-013-MC03"], "prerequisite_support": {"A1-G05": "U-A1-001: είμαι/έχω", "A1-G06": "U-A1-005: настоящее время", "A1-G07": "U-A1-004: вопросы", "A1-G09": "U-A1-004: предлоги и местоположение; новый пример без модели после повторения."}, "primary_competencies": ["A1-V03"], "learner_data_included": false, "estimated_active_minutes": 65}	652576e6a8395f73cdae288571254380ac5227010c3dc5da6eed59d4536c1faa	3119
U-A1-014	A1	114	Читаем объявления, расписания и сообщения	{A1-G07,A1-G10,A1-V03}	{}	{A1-R01}	{A1-R01}	65	{"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A1-014-RUBRIC"], "unit_id": "U-A1-014", "version": "0.1.2", "title_ru": "Читаем объявления, расписания и сообщения", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Этот урок учит читать короткое объявление, расписание и личное сообщение ради действия: выбрать время, найти комнату, ответить другу. Все расписания здесь учебные, они не описывают реальные организации. Перед началом повторите числа и часы, названия дней, вопросы Πότε; Πού; и лексику соседних мест. Неизвестные αίθουσα, είσοδος, δωρεάν объясняются в словаре до самостоятельной проверки.\\nПервое чтение: посмотрите на заголовок и форму текста. В расписании строки обычно связывают день и интервал; в сообщении имя в начале — адресат, подпись в конце — автор. Это полезная стратегия для наших примеров, не универсальный закон всех текстов. Не нужно переводить каждое слово до ответа на вопрос «что это за текст?». Второе чтение: найдите именно нужную строку и перепишите её ключевой факт своими словами.\\nРазличайте событие и часы работы. Βιβλιοθήκη: 09:00–18:00 не означает, что урок идёт девять часов. Μάθημα: 17:00 указывает начало урока, а не закрытие библиотеки. На наших карточках цифровое время дано в 24-часовом формате: 17:00 соответствует στις πέντε το απόγευμα. В живом сообщении «στις πέντε» без контекста может требовать уточнения. Не выбирайте ближайшее число только потому, что оно знакомо.\\nΑνοιχτά и κλειστά на вывесках сообщают об открытии или закрытии. Здесь их узнаём как готовые обозначения. Δωρεάν означает бесплатно; оно не говорит ни об обязательной записи, ни об отсутствии записи. Если об этом ничего нет, честный ответ: Δεν γράφει — не написано. Также не выводите цену напитка из бесплатного входа на занятие.\\nОтделяйте место человека от места мероприятия. Είμαι στο καφέ δίπλα στη βιβλιοθήκη — человек в кафе; урок при этом может быть в библиотеке. Отделяйте время встречи от начала: от фразы «Я здесь с 16:30, урок в 17:00» нельзя заключить, что урок в 16:30. В задании с отсутствующими данными ищите явное подтверждение, а не правдоподобный вариант. Для ответа часто достаточно 2–5 слов; полное предложение допустимо, если не добавляет ложных сведений.\\nПроверка понимания включает действие: коротко сообщить другу подходящий день, время и комнату, объяснить почему неподходящий вариант не годится. Продуктивные задания опираются на прочитанное, но их балл отражает также письменную/устную передачу фактов; ошибки чтения отмечайте отдельно от ошибок формы. Сначала ответьте без ключа, затем укажите строку-доказательство. В отложенной практике будут другие дни, помещения и часы. Будущие слушательские задания не считаются проверенными на слух, пока записи нет.\\nПеред заданиями со временем используйте CP06-CLOCK-BRIDGE: στις εννέα το πρωί — в 09:00; στις τρεις το απόγευμα — в 15:00; μέχρι τις πέντε — до пяти, μετά τις πέντε — после пяти. Если воспользовались подсказкой, отметьте помощь; затем назовите другое время без образца.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Το Σάββατο είναι ανοιχτά.", "Την Κυριακή είναι κλειστά.", "Η είσοδος είναι δωρεάν.", "Το μάθημα είναι δωρεάν.", "Είμαι στην αίθουσα δύο.", "Το μάθημα είναι στη βιβλιοθήκη.", "Έχω ένα μήνυμα.", "Το μάθημα αρχίζει στις πέντε.", "Σήμερα είναι Τρίτη.", "Είναι ανοιχτά μέχρι τις δύο."], "review_plan": {"days": [7, 14, 28], "rule": "Новый ответ без модели; после подсказки сохранять assisted, повторить самостоятельно с новыми данными.", "item_ids": ["U-A1-014-I17", "U-A1-014-I18", "U-A1-014-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Παραγωγή γραπτού λόγου; Αναγνώριση ταυτότητας; Κατοικία, διαμονή; Ελεύθερος χρόνος; Επαγγελματικός χώρος", "source_id": "CP06-A1-S01", "checked_on": "2026-10-17", "claim_scope": "A1 functional domains only. No endorsement of GreekOS tasks, durations or mastery thresholds.", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR"}], "support_refs": ["GreekOS_Academic_Corpus/support/CP06-CLOCK-BRIDGE.json"], "active_recall": ["U-A1-014-I08", "U-A1-014-I09"], "prerequisites": ["A1-G07", "A1-G10", "A1-V03"], "reading_tasks": ["U-A1-014-I10", "U-A1-014-I11"], "transfer_task": "U-A1-014-I16", "writing_tasks": ["U-A1-014-I14"], "competency_ids": ["A1-R01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; no observed learner mastery", "speaking_tasks": ["U-A1-014-I15"], "errors_taxonomy": ["FACT_SUBSTITUTION", "LEXICAL_ROLE_CONFUSION", "REGISTER_MISMATCH", "UNSUPPORTED_INFERENCE", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A1-014-I02", "U-A1-014-I03", "U-A1-014-I04", "U-A1-014-I05", "U-A1-014-I06", "U-A1-014-I07"], "listening_tasks": ["U-A1-014-I12", "U-A1-014-I13"], "reading_text_el": "ΒΙΒΛΙΟΘΗΚΗ ΓΕΙΤΟΝΙΑΣ\\nΔευτέρα–Παρασκευή: 09:00–18:00. Σάββατο: 10:00–14:00. Κυριακή: κλειστά.\\nΜάθημα ελληνικών: Τρίτη, 17:00, αίθουσα 2. Είσοδος δωρεάν.\\nΜήνυμα: Άννα, σήμερα είναι Τρίτη. Είμαι στο καφέ δίπλα στη βιβλιοθήκη. Το μάθημα αρχίζει στις πέντε. Εγώ είμαι εδώ από τις τέσσερις και μισή. Νίκος.", "learning_outcome": "Найти явные день, время, место и условие в коротком объявлении", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "transfer": "I16 + новая самостоятельная речь на I17/I19 по item-specific anchors", "controlled": "≥80% закрытых ответов, затем исправление всех смысловых ошибок"}, "vocabulary_items": [{"lemma": "ανοιχτά", "stress": "ανοιχτά", "example": "Το Σάββατο είναι ανοιχτά.", "inflection": "ανοιχτά", "meaning_ru": "открыто", "collocations": ["είναι ανοιχτά"]}, {"lemma": "κλειστά", "stress": "κλειστά", "example": "Την Κυριακή είναι κλειστά.", "inflection": "κλειστά", "meaning_ru": "закрыто", "collocations": ["είναι κλειστά"]}, {"lemma": "είσοδος", "stress": "είσοδος", "example": "Η είσοδος είναι δωρεάν.", "inflection": "η είσοδος", "meaning_ru": "вход", "collocations": ["είσοδος δωρεάν"]}, {"lemma": "δωρεάν", "stress": "δωρεάν", "example": "Το μάθημα είναι δωρεάν.", "inflection": "δωρεάν", "meaning_ru": "бесплатно", "collocations": ["είναι δωρεάν"]}, {"lemma": "αίθουσα", "stress": "αίθουσα", "example": "Είμαι στην αίθουσα δύο.", "inflection": "η αίθουσα", "meaning_ru": "зал, аудитория", "collocations": ["στην αίθουσα δύο"]}, {"lemma": "βιβλιοθήκη", "stress": "βιβλιοθήκη", "example": "Το μάθημα είναι στη βιβλιοθήκη.", "inflection": "η βιβλιοθήκη", "meaning_ru": "библиотека", "collocations": ["στη βιβλιοθήκη"]}, {"lemma": "μήνυμα", "stress": "μήνυμα", "example": "Έχω ένα μήνυμα.", "inflection": "το μήνυμα", "meaning_ru": "сообщение", "collocations": ["ένα μήνυμα"]}, {"lemma": "αρχίζει", "stress": "αρχίζει", "example": "Το μάθημα αρχίζει στις πέντε.", "inflection": "αρχίζω / αρχίζει", "meaning_ru": "начинается", "collocations": ["το μάθημα αρχίζει"]}, {"lemma": "σήμερα", "stress": "σήμερα", "example": "Σήμερα είναι Τρίτη.", "inflection": "σήμερα", "meaning_ru": "сегодня", "collocations": ["σήμερα είναι Τρίτη"]}, {"lemma": "μέχρι", "stress": "μέχρι", "example": "Είναι ανοιχτά μέχρι τις δύο.", "inflection": "μέχρι", "meaning_ru": "до", "collocations": ["μέχρι τις δύο"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-014-I01"], "learning_objectives": ["Найти явные день, время, место и условие в коротком объявлении", "Различить автора и адресата, расписание и событие, факт и отсутствие данных", "Передать прочитанное в самостоятельном ответе и действовать по новому сообщению"], "microcompetency_ids": ["U-A1-014-MC01", "U-A1-014-MC02", "U-A1-014-MC03"], "prerequisite_support": {"A1-G07": "U-A1-004: вопросы где/когда", "A1-G10": "U-A1-011: принадлежность и изученные числительные. Для часов: GreekOS_Academic_Corpus/support/CP06-CLOCK-BRIDGE.json; не предполагать, что часы изучены в уроке алфавита.", "A1-V03": "U-A1-013: библиотека, район, ориентиры; vocabulary bridge supplied"}, "primary_competencies": ["A1-R01"], "learner_data_included": false, "estimated_active_minutes": 65}	5ccb8c9c162e0b0c26be212977e7c6a94092894b45fe839e708f5ff621a265d4	3120
U-A1-015	A1	115	Заполняем карточку и пишем короткую записку	{A1-G05,A1-G07,A1-G09,A1-G10,A1-V01,A1-R01}	{}	{A1-W01}	{A1-W01}	65	{"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A1-015-RUBRIC"], "unit_id": "U-A1-015", "version": "0.1.2", "title_ru": "Заполняем карточку и пишем короткую записку", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Вы научитесь заполнять простую карточку и писать короткую записку человеку, который должен найти вас или предмет. Используйте вымышленные сведения. Реальные телефон, адрес, фамилия и документ не нужны. Перед началом нужны вопросы об имени, принадлежность μου/σου, настоящее время и обозначения места/часов из предыдущих уроков. Проверка I01 возвращает к имени и фамилии; при трудностях повторите U-A1-012.\\nВ карточке одно поле — один факт. Όνομα означает имя, επώνυμο — фамилию, πόλη — город, γλώσσα — язык. Для вымышленной Ελένη Δήμου: Όνομα: Ελένη; Επώνυμο: Δήμου. В поле города достаточно Πάτρα. Полное предложение полезно в сообщении: Μένω στην Πάτρα. Не переносите ответ о происхождении в поле нынешнего города, если эти города различаются. Название страны не заменяет город. Не заполняйте отсутствующий телефон выдуманным номером: в этой учебной карточке такого поля нет.\\nЗаписка должна позволять адресату действовать. Обращение в начале показывает, кому вы пишете; подпись в конце — кто пишет. Для наших заданий достаточно простого Γεια σου! либо имени. Изучаем готовые обращения Μαρία, Ελένη; другие формы имён проверяйте отдельно. Затем напишите, где вы сейчас, до какого часа и где нужная вещь. Например: Μαρία, είμαι στη βιβλιοθήκη μέχρι τις έξι. Το βιβλίο σου είναι στο τραπέζι. Ελένη. Подпись не заменяет обращение: перепутанные роли меняют смысл.\\nВыбирайте сведения по цели. «Я в библиотеке до шести» не означает «встречаемся в шесть». Μέχρι τις έξι — конец указанного периода, στις έξι — отдельное время. Не добавляйте будущую встречу, если её нет в условии. Το βιβλίο σου относится к книге адресата, το βιβλίο μου — автора. Повторите предлоги: στο τραπέζι, στη βιβλιοθήκη, στο σπίτι. Переносите точное отношение: на столе не значит рядом со столом.\\nСтройте короткий текст из уже освоенных моделей, а не переводите сложное русское предложение слово за словом. Είμαι…; Το βιβλίο είναι…; Δεν είμαι…; Μένω… достаточны для поставленной задачи. Соединение και уместно, когда добавляет второй факт; αλλά — когда противопоставляет. Время и имена можно сначала выписать отдельно, но итоговую отложенную попытку делайте без образца. Небольшие различия порядка слов не ошибка, если факты и отношения сохранены.\\nПеред отправкой проверьте четыре вещи: адресат и подпись различимы; место и время не перепутаны; принадлежность вещи правильная; все требуемые факты присутствуют. Сначала оцените выполнение задачи, потом формы. Рекомендуемый объём помогает практиковаться, но лишнее слово само по себе не обнуляет ответ. В свободном задании допустим другой корректный текст, а модель не является единственным ключом. После обратной связи перепишите записку для нового адресата и нового места. Это проверяет перенос, а не запоминание.\\nУстная практика нужна для связи письма с общением: продиктуйте вымышленные данные, уточните непонятный факт, затем составьте собственную записку. Пока записи нет, I12/I13 — только подготовленные задания к будущему аудио. Их нельзя оценивать как аудирование, если показан сценарий.\\nПеред заданиями со временем используйте CP06-CLOCK-BRIDGE: στις εννέα το πρωί — в 09:00; στις τρεις το απόγευμα — в 15:00; μέχρι τις πέντε — до пяти, μετά τις πέντε — после пяти. Если воспользовались подсказкой, отметьте помощь; затем назовите другое время без образца.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Συμπληρώνω το δελτίο.", "Αυτό είναι το δελτίο συμμετοχής.", "Μένω στην Πάτρα.", "Μιλάω ελληνικά.", "Γράφω ένα μήνυμα στη Μαρία.", "Συμπληρώνω το όνομα.", "Το βιβλίο είναι στο τραπέζι.", "Είμαι εδώ μέχρι τις έξι."], "review_plan": {"days": [7, 14, 28], "rule": "Новый ответ без модели; после подсказки сохранять assisted, повторить самостоятельно с новыми данными.", "item_ids": ["U-A1-015-I17", "U-A1-015-I18", "U-A1-015-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Παραγωγή γραπτού λόγου; Αναγνώριση ταυτότητας; Κατοικία, διαμονή; Ελεύθερος χρόνος; Επαγγελματικός χώρος", "source_id": "CP06-A1-S01", "checked_on": "2026-10-18", "claim_scope": "A1 functional domains only. No endorsement of GreekOS tasks, durations or mastery thresholds.", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR"}, {"anchor": "επώνυμο το; main definition (line141 in retrieved view)", "source_id": "CP06-A1-S04", "checked_on": "2026-10-18", "claim_scope": "Family name sense only; historical social examples not adopted", "evidence_type": "PRIMARY_LEXICOGRAPHIC"}], "support_refs": ["GreekOS_Academic_Corpus/support/CP06-CLOCK-BRIDGE.json"], "active_recall": ["U-A1-015-I08", "U-A1-015-I09"], "prerequisites": ["A1-G05", "A1-G07", "A1-G09", "A1-G10", "A1-V01", "A1-R01"], "reading_tasks": ["U-A1-015-I10", "U-A1-015-I11"], "transfer_task": "U-A1-015-I16", "writing_tasks": ["U-A1-015-I14"], "competency_ids": ["A1-W01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; no observed learner mastery", "speaking_tasks": ["U-A1-015-I15"], "errors_taxonomy": ["FACT_SUBSTITUTION", "LEXICAL_ROLE_CONFUSION", "REGISTER_MISMATCH", "UNSUPPORTED_INFERENCE", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A1-015-I02", "U-A1-015-I03", "U-A1-015-I04", "U-A1-015-I05", "U-A1-015-I06", "U-A1-015-I07"], "listening_tasks": ["U-A1-015-I12", "U-A1-015-I13"], "reading_text_el": "Δελτίο συμμετοχής\\nΌνομα: Ελένη\\nΕπώνυμο: Δήμου\\nΠόλη: Πάτρα\\nΓλώσσα: ελληνικά\\n\\nΜαρία, σήμερα δεν είμαι στο σπίτι. Είμαι στη βιβλιοθήκη μέχρι τις έξι. Το βιβλίο σου είναι στο τραπέζι. Ελένη.", "learning_outcome": "Заполнить поля имени, фамилии, города и языка по заданным сведениям", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "transfer": "I16 + новая самостоятельная речь на I17/I19 по item-specific anchors", "controlled": "≥80% закрытых ответов, затем исправление всех смысловых ошибок"}, "vocabulary_items": [{"lemma": "δελτίο", "stress": "δελτίο", "example": "Συμπληρώνω το δελτίο.", "inflection": "το δελτίο", "meaning_ru": "бланк, карточка", "collocations": ["δελτίο συμμετοχής"]}, {"lemma": "συμμετοχή", "stress": "συμμετοχή", "example": "Αυτό είναι το δελτίο συμμετοχής.", "inflection": "η συμμετοχή", "meaning_ru": "участие", "collocations": ["δελτίο συμμετοχής"]}, {"lemma": "πόλη", "stress": "πόλη", "example": "Μένω στην Πάτρα.", "inflection": "η πόλη", "meaning_ru": "город", "collocations": ["στην πόλη"]}, {"lemma": "γλώσσα", "stress": "γλώσσα", "example": "Μιλάω ελληνικά.", "inflection": "η γλώσσα", "meaning_ru": "язык", "collocations": ["ελληνική γλώσσα"]}, {"lemma": "γράφω", "stress": "γράφω", "example": "Γράφω ένα μήνυμα στη Μαρία.", "inflection": "γράφω / γράφεις", "meaning_ru": "писать", "collocations": ["γράφω μήνυμα"]}, {"lemma": "συμπληρώνω", "stress": "συμπληρώνω", "example": "Συμπληρώνω το όνομα.", "inflection": "συμπληρώνω / συμπληρώνεις", "meaning_ru": "заполнять", "collocations": ["συμπληρώνω το δελτίο"]}, {"lemma": "τραπέζι", "stress": "τραπέζι", "example": "Το βιβλίο είναι στο τραπέζι.", "inflection": "το τραπέζι", "meaning_ru": "стол", "collocations": ["στο τραπέζι"]}, {"lemma": "μέχρι", "stress": "μέχρι", "example": "Είμαι εδώ μέχρι τις έξι.", "inflection": "μέχρι", "meaning_ru": "до", "collocations": ["μέχρι τις έξι"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-015-I01"], "learning_objectives": ["Заполнить поля имени, фамилии, города и языка по заданным сведениям", "Передать место, время и принадлежность вещи без подмены фактов", "Самостоятельно написать и устно уточнить короткую записку в новом контексте"], "microcompetency_ids": ["U-A1-015-MC01", "U-A1-015-MC02", "U-A1-015-MC03"], "prerequisite_support": {"A1-G05": "U-A1-001: είμαι/έχω", "A1-G07": "U-A1-004: вопросы", "A1-G09": "U-A1-004: предлоги и местоположение; новый пример без модели после повторения.", "A1-G10": "U-A1-011: принадлежность и изученные числительные. Для часов: GreekOS_Academic_Corpus/support/CP06-CLOCK-BRIDGE.json; не предполагать, что часы изучены в уроке алфавита.", "A1-R01": "U-A1-014: автор, адресат, время", "A1-V01": "U-A1-012: имя/фамилия/город"}, "primary_competencies": ["A1-W01"], "learner_data_included": false, "estimated_active_minutes": 65}	f3347c84720f84ea4e49afa826405c0c7900d6056e48319772c307a08e33a812	3121
U-A1-016	A1	116	Знакомство и простая покупка: спросить, уточнить, завершить	{A1-G07,A1-V02}	{}	{A1-SI01}	{A1-SI01}	70	{"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A1-016-RUBRIC"], "unit_id": "U-A1-016", "version": "0.1.1", "title_ru": "Знакомство и простая покупка: спросить, уточнить, завершить", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Задача урока — начать короткий разговор и выполнить простую покупку, сохраняя количество, предмет и цену. Это две связанные, но разные функции: в знакомстве мы обмениваемся личной информацией, в магазине договариваемся о конкретном действии. Не нужно сначала произносить длинный рассказ о себе, чтобы попросить воду. Перед началом проверьте вопросы из U-A1-004 и числа из U-A1-003: Πώς σε λένε; Πόσο κάνει; ένα, δύο, τρία, τέσσερα. Если путаются количество и цена, сначала используйте карточки с отдельными полями «товар / количество / цена», затем уберите карточки.\\nДля знакомства с ровесником: Γεια σου! Με λένε Άννα. Εσένα; Встречный вопрос уместен, когда тема уже ясна. Сотруднику, которого вы не знаете, для этой практики выбираем Γεια σας или Καλημέρα. Готовые пары σε/σας и σου/σας меняют обращение: Πώς σε λένε; — Πώς σας λένε; Δεν καταλαβαίνω — не понимаю. Не объявляем один вариант единственным допустимым во всей Греции: отношения, возраст и обстановка влияют на выбор. В заданиях адресат задан прямо; оцениваем выполнение конкретной роли, а не личность говорящего.\\nВ магазине начните с предмета и количества: Ένα νερό, παρακαλώ. Δύο χυμούς, παρακαλώ. Эти две формы здесь учим как готовые сочетания; полная парадигма существительного не требуется. Для уточнения наличия: Έχετε νερό; Для цены одного выбранного товара: Πόσο κάνει; Для общей стоимости заказа: Πόσο κάνουν όλα μαζί; В коротком заказе название товара с παρακαλώ само по себе может быть достаточной просьбой; не требуем обязательно длинную форму Θα ήθελα. Вводим её как необязательный вежливый готовый блок: Θα ήθελα ένα νερό, παρακαλώ. Это не урок условного наклонения.\\nОтличайте вопрос продавца от нового заказа. Ένα ή δύο; просит выбрать количество. Μικρό ή μεγάλο; — размер. Κρύο ή όχι; — холодный напиток или нет. Если вы не расслышали число, нельзя уверенно подтверждать случайный вариант. Скажите Πάλι, παρακαλώ или Πιο αργά, παρακαλώ; затем повторите услышанное как вопрос: Τρία ευρώ; В этой практике одно повторение допустимо и считается успешным восстановлением общения, но чтение готовой реплики с экрана отмечается как помощь.\\nИсправление должно называть правильный факт. Όχι δύο, ένα, παρακαλώ исправляет количество. Όχι χυμό, νερό, παρακαλώ исправляет предмет. Простое Όχι не сообщает, что именно требуется. Если товара нет, можно выбрать предложенную замену или отказаться: Όχι, ευχαριστώ. Не предполагаем, что покупатель обязан согласиться. Завершение: Ευχαριστώ. Γεια σας. Задания не требуют передачи реальных платёжных данных или совершения покупки.\\nТренируйтесь сначала по ролям, затем меняйте товар, количество и собеседника. Один участник знает, какой товар отсутствует; второй узнаёт это только в разговоре. Проверяем не запомненную последовательность, а способность заметить несовпадение и уточнить. Успешный результат — продавец и покупатель одинаково понимают итоговый заказ. Произношение и понимание на слух оцениваются только по реальному звуку; пока запись отсутствует, транскрипт пригоден для чтения, но балл за аудирование заблокирован.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Γεια σας!", "Με λένε Μαρία. Εσένα;", "Ένα νερό, παρακαλώ.", "Δύο χυμούς, παρακαλώ.", "Πόσο κάνει;", "Πόσο κάνουν όλα μαζί;", "Έχετε νερό;", "Πάλι, παρακαλώ.", "Πιο αργά, παρακαλώ.", "Όχι δύο, ένα, παρακαλώ.", "Όχι, ευχαριστώ.", "Ευχαριστώ. Γεια σας!"], "review_plan": {"days": [7, 14, 28], "rule": "Новый ответ без модели; после подсказки сохранять assisted, повторить самостоятельно с новыми данными.", "item_ids": ["U-A1-016-I17", "U-A1-016-I18", "U-A1-016-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Ειδικοί Εκπαιδευτικοί Στόχοι, L86–88; Παραγωγή προφορικού λόγου, L105–107", "source_id": "CP06-A1-S01", "checked_on": "2026-10-20", "claim_scope": "Functional scope only; no institutional endorsement of original tasks, thresholds, language forms or CEFR mediation descriptor.", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR_REINSPECTED"}], "active_recall": ["U-A1-016-I08", "U-A1-016-I09"], "prerequisites": ["A1-G07", "A1-V02"], "reading_tasks": ["U-A1-016-I10", "U-A1-016-I11"], "transfer_task": "U-A1-016-I16", "writing_tasks": ["U-A1-016-I14"], "competency_ids": ["A1-SI01"], "coverage_claim": "AUTHORED_DRAFT_PARTIAL_MACRO; speaking acoustic evidence and full source audit pending", "speaking_tasks": ["U-A1-016-I15", "U-A1-016-I20"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION", "FACT_SUBSTITUTION", "PRAGMATICS_REGISTER", "ASR_UNCERTAIN", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A1-016-I02", "U-A1-016-I03", "U-A1-016-I04", "U-A1-016-I05", "U-A1-016-I06", "U-A1-016-I07"], "listening_tasks": ["U-A1-016-I12", "U-A1-016-I13"], "reading_text_el": "Πωλήτρια: Καλημέρα!\\nΆννα: Καλημέρα. Ένα νερό και δύο χυμούς, παρακαλώ.\\nΠωλήτρια: Έχουμε μόνο έναν χυμό.\\nΆννα: Εντάξει. Ένα νερό και έναν χυμό. Πόσο κάνουν όλα μαζί;\\nΠωλήτρια: Τρία ευρώ.\\nΆννα: Τρία ευρώ;\\nΠωλήτρια: Ναι.\\nΆννα: Ευχαριστώ. Γεια σας!", "learning_outcome": "Начать знакомство и ответить на простой вопрос", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "transfer": "Unprompted I16 and new D7/D28 with facts preserved, assistance logged", "controlled": "All meaning-changing errors corrected; ≥80% is project heuristic, not official threshold"}, "vocabulary_items": [{"lemma": "το νερό", "stress": "το νερό", "example": "Ένα νερό, παρακαλώ.", "inflection": "το νερό → ένα νερό / δύο νερά", "meaning_ru": "вода", "collocations": ["Ένα νερό, παρακαλώ."]}, {"lemma": "ο χυμός", "stress": "ο χυμός", "example": "Έναν χυμό, παρακαλώ.", "inflection": "ο χυμός → έναν χυμό / δύο χυμούς", "meaning_ru": "сок", "collocations": ["Έναν χυμό, παρακαλώ."]}, {"lemma": "όλα μαζί", "stress": "όλα μαζί", "example": "Πόσο κάνουν όλα μαζί;", "inflection": "Устойчивое сочетание в этой функции", "meaning_ru": "всё вместе", "collocations": ["Πόσο κάνουν όλα μαζί;"]}, {"lemma": "πάλι", "stress": "πάλι", "example": "Πάλι, παρακαλώ.", "inflection": "Неизменяемое наречие", "meaning_ru": "снова", "collocations": ["Πάλι, παρακαλώ."]}, {"lemma": "μικρό / μεγάλο", "stress": "μικρό / μεγάλο", "example": "Μικρό ή μεγάλο;", "inflection": "μικρό/μεγάλο: средний род единственного; μικρά/μεγάλα: множественное", "meaning_ru": "маленькое / большое", "collocations": ["Μικρό ή μεγάλο;"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-016-I01"], "learning_objectives": ["Начать знакомство и ответить на простой вопрос", "Согласовать предмет, количество и цену простой покупки", "Восстановить понимание и самостоятельно изменить заказ"], "microcompetency_ids": ["U-A1-016-MC01", "U-A1-016-MC02", "U-A1-016-MC03"], "prerequisite_support": {"A1-G07": "U-A1-004; entry I01 asks price. If confused, distinguish πού/πόσο then retry with new product.", "A1-V02": "U-A1-003; rehearse1–4 and ευρώ; if quantities fail use labelled cards before independent retry."}, "primary_competencies": ["A1-SI01"], "learner_data_included": false, "estimated_active_minutes": 70}	41d5d6a4d67f22473addcf1bdd24d00c77bb810eb0e67244fa8c4162b3cd6d40	3122
U-A1-017	A1	117	Короткое описание себя и привычного дня	{A1-G06,A1-V01}	{}	{A1-SP01}	{A1-SP01}	70	{"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A1-017-RUBRIC"], "unit_id": "U-A1-017", "version": "0.1.1", "title_ru": "Короткое описание себя и привычного дня", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "В этом уроке вы создаёте короткое устное описание себя и обычного дня. Цель — понятная последовательность знакомых фактов, а не длинное выступление или выученная биография. Используйте вымышленную личность; настоящие адреса, телефон и сведения родственников не нужны. Проверка входа: различите Είμαι δάσκαλος (роль), μένω στην Πάτρα (проживание), δουλεύω το πρωί (действие). При ошибках вернитесь к настоящему времени в U-A1-005 и личной лексике U-A1-012, затем опишите нового человека.\\nПостройте описание из четырёх смысловых опор: кто я; где живу и чем занимаюсь; что обычно делаю утром и вечером; что мне нравится. Имя можно назвать Με λένε Άννα или Είμαι η Άννα. Είμαι από την Αθήνα описывает происхождение, а μένω στην Πάτρα — нынешний город. Один факт не отменяет другой. Не добавляйте происхождение, если карточка его не содержит.\\nДля обычного дня используем уже изученное настоящее: δουλεύω, διαβάζω, ακούω, βλέπω, παίζω. В данном уроке το πρωί и το βράδυ задают повторяющуюся часть дня; σήμερα обозначает именно сегодня. Фраза Σήμερα δεν δουλεύω не означает, что человек никогда не работает. Вместо обычного расписания можно честно сказать Δεν δουλεύω τώρα, если это относится к вашей вымышленной роли. Новые выражения по времени вводятся как готовые блоки: μετά τη δουλειά — после работы; το Σάββατο — в субботу. Из них не следует конкретный час.\\nСвязь между фразами можно показать и простыми словами. Και соединяет совместимые сведения: Δουλεύω και σπουδάζω. Αλλά подчёркивает контраст: Μου αρέσει το ποδόσφαιρο, αλλά δεν παίζω. Это не противоречие: человек может смотреть матчи. Μου αρέσει η μουσική и ακούω μουσική тоже не полностью одинаковые факты: первое — предпочтение, второе — действие. Если требуется назвать оба, произнесите оба. Не требуем сложных союзов ради красивого текста.\\nПеред речью можно выписать четыре ключевых слова, но не готовые предложения. Затем уберите опоры и говорите 30–45 секунд: время здесь ориентир, а не экзаменационный норматив. Короткие паузы и самостоятельное исправление допустимы. Если вы сказали неверный город, исправьте именно его: Όχι στην Αθήνα, στην Πάτρα. Повторение одной фразы пять раз не выполняет пять разных условий. После описания ответьте на один неожиданный уточняющий вопрос, например Τι κάνεις το βράδυ;.\\nСлушатель проверяет факты, а затем форму: понятно ли, кто человек, где живёт, что делает и что любит? Он не должен угадывать недостающие сведения. Произношение нельзя оценить по текстовому ответу; транскрипт показывает только содержание. Незнакомое слово можно заменить знакомым подходящим выражением. При подсказке отмечайте assisted; затем повторите с новой ролью без модели. В D7/D28 меняются город, работа и распорядок, чтобы проверить перенос, а не память рассказа.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Με λένε Σοφία.", "Είμαι από τον Βόλο.", "Μένω στην Πάτρα.", "Είμαι δασκάλα.", "Το πρωί δουλεύω.", "Μετά τη δουλειά διαβάζω.", "Το βράδυ ακούω μουσική.", "Μου αρέσει το ποδόσφαιρο, αλλά δεν παίζω.", "Σήμερα δεν δουλεύω.", "Όχι στην Αθήνα, στην Πάτρα."], "review_plan": {"days": [7, 14, 28], "rule": "Новый ответ без модели; после подсказки сохранять assisted, повторить самостоятельно с новыми данными.", "item_ids": ["U-A1-017-I17", "U-A1-017-I18", "U-A1-017-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Παραγωγή προφορικού λόγου, L105–107", "source_id": "CP06-A1-S01", "checked_on": "2026-10-20", "claim_scope": "Functional scope only; no institutional endorsement of original tasks, thresholds, language forms or CEFR mediation descriptor.", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR_REINSPECTED"}], "active_recall": ["U-A1-017-I08", "U-A1-017-I09"], "prerequisites": ["A1-G06", "A1-V01"], "reading_tasks": ["U-A1-017-I10", "U-A1-017-I11"], "transfer_task": "U-A1-017-I16", "writing_tasks": ["U-A1-017-I14"], "competency_ids": ["A1-SP01"], "coverage_claim": "AUTHORED_DRAFT_PARTIAL_MACRO; speaking acoustic evidence and full source audit pending", "speaking_tasks": ["U-A1-017-I15", "U-A1-017-I20"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION", "FACT_SUBSTITUTION", "PRAGMATICS_REGISTER", "ASR_UNCERTAIN", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A1-017-I02", "U-A1-017-I03", "U-A1-017-I04", "U-A1-017-I05", "U-A1-017-I06", "U-A1-017-I07"], "listening_tasks": ["U-A1-017-I12", "U-A1-017-I13"], "reading_text_el": "Με λένε Σοφία. Είμαι από τον Βόλο, αλλά μένω στην Πάτρα. Είμαι δασκάλα. Το πρωί δουλεύω στο σχολείο. Μετά τη δουλειά διαβάζω στο σπίτι. Το βράδυ ακούω μουσική. Μου αρέσει το ποδόσφαιρο, αλλά δεν παίζω. Βλέπω αγώνες το Σάββατο. Σήμερα δεν δουλεύω.", "learning_outcome": "Представить личность, город и занятие без подмены фактов", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "transfer": "Unprompted I16 and new D7/D28 with facts preserved, assistance logged", "controlled": "All meaning-changing errors corrected; ≥80% is project heuristic, not official threshold"}, "vocabulary_items": [{"lemma": "το πρωί", "stress": "το πρωί", "example": "Το πρωί διαβάζω.", "inflection": "Готовое обстоятельственное сочетание времени", "meaning_ru": "утром", "collocations": ["Το πρωί διαβάζω."]}, {"lemma": "το βράδυ", "stress": "το βράδυ", "example": "Το βράδυ δουλεύω.", "inflection": "Готовое обстоятельственное сочетание времени", "meaning_ru": "вечером", "collocations": ["Το βράδυ δουλεύω."]}, {"lemma": "μετά τη δουλειά", "stress": "μετά τη δουλειά", "example": "Μετά τη δουλειά ακούω μουσική.", "inflection": "Готовое сочетание; η δουλειά → τη δουλειά", "meaning_ru": "после работы", "collocations": ["Μετά τη δουλειά ακούω μουσική."]}, {"lemma": "σήμερα", "stress": "σήμερα", "example": "Σήμερα δεν δουλεύω.", "inflection": "Неизменяемое наречие", "meaning_ru": "сегодня", "collocations": ["Σήμερα δεν δουλεύω."]}, {"lemma": "αλλά", "stress": "αλλά", "example": "Μου αρέσει το ποδόσφαιρο, αλλά δεν παίζω.", "inflection": "Неизменяемый союз", "meaning_ru": "но", "collocations": ["Μου αρέσει το ποδόσφαιρο, αλλά δεν παίζω."]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-017-I01"], "learning_objectives": ["Представить личность, город и занятие без подмены фактов", "Связать действия обычного дня и предпочтения простыми фразами", "Самостоятельно описать новую роль и исправить ошибку"], "microcompetency_ids": ["U-A1-017-MC01", "U-A1-017-MC02", "U-A1-017-MC03"], "prerequisite_support": {"A1-G06": "U-A1-005: настоящее; I01 входная проверка первого лица; при ошибке повторить два глагола с новым субъектом", "A1-V01": "U-A1-012: личность и интересы; I02 различает происхождение/проживание"}, "primary_competencies": ["A1-SP01"], "learner_data_included": false, "estimated_active_minutes": 70}	4acf8f7a56a649c615dd3b4d4274c694f277464bb46497732d016d751f098203	3123
U-A1-018	A1	118	Передать другу время и место встречи	{A1-R01,A1-SI01}	{}	{A1-M01}	{A1-M01}	70	{"qa": {"status": "DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PENDING", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A1-018-RUBRIC"], "unit_id": "U-A1-018", "version": "0.1.1", "title_ru": "Передать другу время и место встречи", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Медиация здесь означает простое посредничество: вы читаете короткое сообщение и передаёте другу нужные время и место. Не нужно переводить каждое слово или объяснять сложную грамматику. Важно сохранить сведения источника и ясно показать, чего источник не сообщает. Используем только учебные события и вымышленных людей. Перед началом проверьте чтение объявления в U-A1-014 и умение уточнить непонятное в U-A1-016.\\nСначала определите задачу друга. Анна спрашивает «Когда и где встреча?» — значит, нужны день, время и место, а не все сведения о погоде или занятиях автора. Выпишите три поля: день / время / место. Время 18:00 передаём как στις έξι το απόγευμα или στις 18:00. Если 09:00 указано явно, нельзя превратить его в вечер. В заданиях без контекста утро/вечер может быть неизвестным: при недостатке данных спросите, а не выбирайте сами.\\nОтделяйте встречу от подготовки. «Είμαι στο καφέ από τις πέντε. Η συνάντηση είναι στις έξι» означает, что автор в кафе с пяти, но встреча в шесть. Так же часы работы библиотеки не обязательно совпадают с мероприятием. Передавая адресату факт, назовите само событие: Η συνάντηση είναι την Τρίτη στις έξι. Так меньше риска, что число относится к другому действию.\\nСохраняйте отношения места. Μπροστά στη βιβλιοθήκη — перед библиотекой, όχι μέσα — не внутри. Δίπλα στο καφέ — рядом с кафе, не обязательно в кафе. Если номер комнаты не указан, нельзя придумать его ради полноты. Прямой ответ Δεν γράφει την αίθουσα сообщает предел знания. Чтобы уточнить, используйте Πού ακριβώς; Σε ποια αίθουσα; Последняя фраза вводится целиком как просьба назвать комнату, без новой парадигмы ποιος.\\nСледите за отправителем и адресатом. В нашем сообщении «Άννα, ... Νίκος» Никос пишет Анне. При передаче третьему человеку достаточно Ο Νίκος γράφει… или Η συνάντηση είναι…; необязательно превращать весь текст в косвенную речь. Не говорите «я буду там», если это обещал автор, а не вы. Проще прямо назвать участника: Ο Νίκος είναι στο καφέ. В упражнениях разрешена передача по-русски для проверки понимания, но там, где указано по-гречески, требуется самостоятельная греческая фраза.\\nЕсли пришло явное исправление, передавайте последнее подтверждённое условие и объясняйте изменение: Όχι την Τρίτη, την Τετάρτη. Старое время не сохраняется автоматически, если новая строка задаёт другое. Если два сообщения противоречат друг другу без явного исправления, уточните; не выдавайте догадку за решение. Слова из задания «исправление» или «новое подтверждение» важны для выбора версии.\\nРаботайте в две попытки: сначала прочитайте и передайте без готовой модели; потом сравните три поля с исходником. Попросите друга повторить ключевые сведения и исправьте только расхождение. Балл за содержание отделяется от балла за язык: правильные цифры с небольшими языковыми ошибками могут сохранить смысл, но неверный день в безупречной фразе проваливает задачу. В D7/D28 используются новые объявления, включая пропущенное поле. Аудиоверсия возможна только после записи и проверки звука.\\nОпора для половины часа: 16:30 — στις τέσσερις και μισή το απόγευμα; 17:30 — στις πέντε και μισή το απόγευμα. Здесь και μισή означает ещё половину часа после названного часа. Перед D7 потренируйте на другом времени, например18:30 — στις έξι και μισή το απόγευμα, затем уберите образец. В письменной передаче допустимо сохранить точные цифры: στις16:30; это сохраняет содержание, но само по себе не доказывает умение устно назвать половину часа.", "cefr_level": "A1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Η συνάντηση είναι την Τρίτη.", "Στις έξι το απόγευμα.", "Μπροστά στη βιβλιοθήκη, όχι μέσα.", "Ο Νίκος είναι στο καφέ.", "Πού ακριβώς;", "Σε ποια αίθουσα;", "Δεν γράφει την αίθουσα.", "Όχι την Τρίτη, την Τετάρτη.", "Στο ίδιο μέρος."], "review_plan": {"days": [7, 14, 28], "rule": "Новый ответ без модели; после подсказки сохранять assisted, повторить самостоятельно с новыми данными.", "item_ids": ["U-A1-018-I17", "U-A1-018-I18", "U-A1-018-I19"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Γενικός Εκπαιδευτικός Στόχος, L83–84; Κατανόηση γραπτού λόγου, L98–100; Παραγωγή προφορικού λόγου,L105", "source_id": "CP06-A1-S01", "checked_on": "2026-10-20", "claim_scope": "Functional scope only; no institutional endorsement of original tasks, thresholds, language forms or CEFR mediation descriptor.", "evidence_type": "OFFICIAL_LEVEL_DESCRIPTOR_REINSPECTED"}], "active_recall": ["U-A1-018-I08", "U-A1-018-I09"], "prerequisites": ["A1-R01", "A1-SI01"], "reading_tasks": ["U-A1-018-I10", "U-A1-018-I11"], "transfer_task": "U-A1-018-I16", "writing_tasks": ["U-A1-018-I14"], "competency_ids": ["A1-M01"], "coverage_claim": "AUTHORED_DRAFT_PARTIAL_MACRO; speaking acoustic evidence and full source audit pending", "speaking_tasks": ["U-A1-018-I15", "U-A1-018-I20"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION", "FACT_SUBSTITUTION", "PRAGMATICS_REGISTER", "ASR_UNCERTAIN", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A1-018-I02", "U-A1-018-I03", "U-A1-018-I04", "U-A1-018-I05", "U-A1-018-I06", "U-A1-018-I07"], "listening_tasks": ["U-A1-018-I12", "U-A1-018-I13"], "reading_text_el": "Άννα, η συνάντηση είναι την Τρίτη στις 18:00 μπροστά στη βιβλιοθήκη. Δεν είναι μέσα στο κτίριο. Εγώ είμαι στο καφέ δίπλα στη βιβλιοθήκη από τις 17:30. Νίκος.\\nΝέο μήνυμα — διόρθωση: Η συνάντηση είναι την Τετάρτη στις 18:00, στο ίδιο μέρος. Νίκος.", "learning_outcome": "Извлечь день, время и место из простого сообщения", "mastery_contract": {"audio": "BLOCKED_MISSING_AUDIO", "observed": false, "transfer": "Unprompted I16 and new D7/D28 with facts preserved, assistance logged", "controlled": "All meaning-changing errors corrected; ≥80% is project heuristic, not official threshold"}, "vocabulary_items": [{"lemma": "η συνάντηση", "stress": "η συνάντηση", "example": "Η συνάντηση είναι στις έξι.", "inflection": "η συνάντηση → τη συνάντηση", "meaning_ru": "встреча", "collocations": ["Η συνάντηση είναι στις έξι."]}, {"lemma": "μπροστά", "stress": "μπροστά", "example": "Μπροστά στο μουσείο.", "inflection": "Неизменяемое наречие; μπροστά σε + место", "meaning_ru": "перед", "collocations": ["Μπροστά στο μουσείο."]}, {"lemma": "μέσα", "stress": "μέσα", "example": "Δεν είναι μέσα.", "inflection": "Неизменяемое наречие; μέσα σε + место", "meaning_ru": "внутри", "collocations": ["Δεν είναι μέσα."]}, {"lemma": "το ίδιο μέρος", "stress": "το ίδιο μέρος", "example": "Η συνάντηση είναι στο ίδιο μέρος.", "inflection": "το μέρος → στο ίδιο μέρος", "meaning_ru": "то же место", "collocations": ["Η συνάντηση είναι στο ίδιο μέρος."]}, {"lemma": "η διόρθωση", "stress": "η διόρθωση", "example": "Νέο μήνυμα: διόρθωση.", "inflection": "η διόρθωση → τη διόρθωση", "meaning_ru": "исправление", "collocations": ["Νέο μήνυμα: διόρθωση."]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A1-018-I01"], "learning_objectives": ["Извлечь день, время и место из простого сообщения", "Передать нужные сведения без подмены автора и без домысливания", "Уточнить пропуск или исправление и проверить понимание друга"], "microcompetency_ids": ["U-A1-018-MC01", "U-A1-018-MC02", "U-A1-018-MC03"], "prerequisite_support": {"A1-R01": "U-A1-014: объявления; I01 входная проверка времени; при ошибке отделить часы работы от события", "A1-SI01": "U-A1-016 раньше в этой партии; I02/I06 проверяют уточнение; сначала восстановить понимание, затем новая попытка"}, "primary_competencies": ["A1-M01"], "learner_data_included": false, "estimated_active_minutes": 70}	3f7fd1faab0cca4b782f6df65f4ae67fef57fb03603e2db8f13632db28005d2c	3124
U-A1-019	A1	119	Понять знакомый вопрос и ответить по существу	{A1-V01}	{}	{A1-L01}	{A1-L01}	70	{"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "COMPLETE_NOT_INDEPENDENT", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A1-019-RUBRIC"], "unit_id": "U-A1-019", "version": "0.1.0", "title_ru": "Понять знакомый вопрос и ответить по существу", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Сначала определите, какую информацию просит собеседник. Πώς σε λένε; — имя, Πού μένεις; — место проживания, Από πού είσαι; — происхождение, Τι δουλειά κάνεις; — работа. Похожая тема не делает ответы взаимозаменяемыми: Μένω στην Πάτρα отвечает о проживании, а Είμαι από τη Γεωργία — о происхождении. Перед уроком проверьте слова о семье, городе и занятиях. Если они незнакомы, вернитесь к A1-V01, затем выполните другой входной вопрос без подсказки.\\nПри первом прослушивании ищите вопросительное слово и знакомую тему. При втором — конкретный факт. Не пытайтесь переводить каждый звук; короткий ответ Στην Πάτρα допустим, если вопрос ясен. Но ответ на Πού μένεις; словом Ναι не передаёт место. Вопрос Μένεις στην Πάτρα; допускает Ναι или Όχι и уточнение. Эти два типа вопросов требуют разных ответов.\\nНе принимайте услышанную реплику за факт о себе. Вы отвечаете из карточки роли, а не повторяете последнюю реплику. Карточка может говорить «происхождение — Кипр; проживание — Афины»: Είμαι από την Κύπρο. Μένω στην Αθήνα. В учебной практике используйте вымышленные сведения. Не требуется сообщать настоящий адрес или профессию.\\nСлушайте отрицание и исправление до конца: Δεν μένω στην Αθήνα. Μένω στην Πάτρα. Первое названное место не обязательно правильный ответ. Если пропущено ключевое слово, попросите повторить: Πάλι, παρακαλώ. Πιο αργά, παρακαλώ. Для проверки: Στην Πάτρα; Реплика уточнения лучше уверенного неверного ответа. Одно повторение фиксируется отдельно от показа готового ответа.\\nПорядок практики: знакомый вопрос с выбором функции → короткий ответ без вариантов → исправление ложного факта → беседа с новым человеком. В аудировании текст закрыт до завершения попытки; затем сравните услышанное с транскриптом и назовите именно пропущенный фрагмент. Чтение транскрипта помогает учиться, но не доказывает понимание звука. Пока аудио отсутствует, доступна только текстовая подготовка, а аудио-оценка заблокирована.\\nВ самостоятельной беседе отвечайте на новый вопрос, а не воспроизводите заученный монолог. Критерии: ответ относится к нужному полю, сохраняет факт роли, понятен адресату. Полное предложение полезно для закрепления, но не является единственным допустимым вариантом. Через семь и двадцать восемь дней используйте другие имена и города; запишите, нужна ли была помощь.", "cefr_level": "A1", "time_basis": "AUTHOR_PLANNING_ESTIMATE_NOT_PILOTED", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Πώς σε λένε;", "Πού μένεις;", "Από πού είσαι;", "Μένεις στην Αθήνα;", "Δεν μένω στην Αθήνα. Μένω στην Πάτρα.", "Πιο αργά, παρακαλώ."], "review_plan": {"days": [7, 28], "rule": "New stimulus, no model shown before attempt; assistance recorded; corrected answer alone is not independent retention", "item_ids": ["U-A1-019-I14", "U-A1-019-I15"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Κατανόηση προφορικού λόγου, paragraphs 1–4 (retrieval lines91–95)", "source_id": "CP08-A1", "checked_on": "2026-10-21", "claim_scope": "Bounded descriptor or phonological principle only; original examples, lesson sequence, rubrics and thresholds are not official"}], "active_recall": ["U-A1-019-I07", "U-A1-019-I08"], "prerequisites": ["A1-V01"], "reading_tasks": ["U-A1-019-I09"], "transfer_task": "U-A1-019-I13", "writing_tasks": ["U-A1-019-I08", "U-A1-019-I12"], "assessment_map": [{"kind": "mcq", "item_id": "U-A1-019-I01", "objective": "Различить функцию знакомого вопроса", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-A1-019-I02", "objective": "Различить функцию знакомого вопроса", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-A1-019-I03", "objective": "Различить функцию знакомого вопроса", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_short", "item_id": "U-A1-019-I04", "objective": "Различить функцию знакомого вопроса", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_short", "item_id": "U-A1-019-I05", "objective": "Различить функцию знакомого вопроса", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "mcq", "item_id": "U-A1-019-I06", "objective": "Извлечь и исправить ключевой факт", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "short", "item_id": "U-A1-019-I07", "objective": "Извлечь и исправить ключевой факт", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "open", "item_id": "U-A1-019-I08", "objective": "Извлечь и исправить ключевой факт", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "read_mcq", "item_id": "U-A1-019-I09", "objective": "Извлечь и исправить ключевой факт", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-A1-019-I10", "objective": "Извлечь и исправить ключевой факт", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "speak", "item_id": "U-A1-019-I11", "objective": "Самостоятельно ответить и восстановить понимание", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "open", "item_id": "U-A1-019-I12", "objective": "Самостоятельно ответить и восстановить понимание", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-A1-019-I13", "objective": "Самостоятельно ответить и восстановить понимание", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_short", "item_id": "U-A1-019-I14", "objective": "Самостоятельно ответить и восстановить понимание", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "speak", "item_id": "U-A1-019-I15", "objective": "Самостоятельно ответить и восстановить понимание", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}], "competency_ids": ["A1-L01"], "coverage_claim": "TEXT_ROUTE_AUTHORED_AUDIO_AND_INDEPENDENT_QA_BLOCKED", "speaking_tasks": ["U-A1-019-I11", "U-A1-019-I15"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION", "FACT_SUBSTITUTION", "ASR_UNCERTAIN", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A1-019-I02", "U-A1-019-I03", "U-A1-019-I04", "U-A1-019-I05", "U-A1-019-I06", "U-A1-019-I09", "U-A1-019-I10"], "listening_tasks": ["U-A1-019-I02", "U-A1-019-I03", "U-A1-019-I04", "U-A1-019-I05", "U-A1-019-I10", "U-A1-019-I13", "U-A1-019-I14"], "mastery_contract": {"open": "Every task-specific content criterion met independently, intelligible response; quote evidence per criterion", "closed": "At least80% on fresh controlled tasks, no uncorrected critical fact errors; project heuristic only", "listening": "Requires verified media, transcript hidden, play count logged", "retention": "Independent D7 and D28; one hint makes assisted evidence", "pronunciation": "Requires actual recording and listening; ASR text alone insufficient"}, "reading_texts_el": [], "vocabulary_items": [{"lemma": "μένω", "stress": "μένω", "example": "Μένω στην Πάτρα.", "inflection": "μένω / μένεις / μένει", "meaning_ru": "жить", "collocations": ["Μένω στην Πάτρα."]}, {"lemma": "από πού", "stress": "από πού", "example": "Από πού είσαι;", "inflection": "неизменяемое сочетание", "meaning_ru": "откуда", "collocations": ["Από πού είσαι;"]}, {"lemma": "πάλι", "stress": "πάλι", "example": "Πάλι, παρακαλώ.", "inflection": "наречие", "meaning_ru": "снова", "collocations": ["Πάλι, παρακαλώ."]}], "diagnostic_item_ids": ["U-A1-019-I01"], "learning_objectives": ["Различить функцию знакомого вопроса", "Извлечь и исправить ключевой факт", "Самостоятельно ответить и восстановить понимание"], "prerequisite_support": {"A1-V01": "Use primary unit from CONTENT_Production_Register_96.csv; if entry task fails, reteach prerequisite and retry on a fresh example before target assessment"}, "primary_competencies": ["A1-L01"], "estimated_active_minutes": 70}	05428d6a65954916f8bfbc28e347aa16968a9bec9522d5b3808b380