 false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-A1-020-I10", "objective": "Извлечь исправленную информацию", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "speak", "item_id": "U-A1-020-I11", "objective": "Передать нужные поля и уточнить неизвестное", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-A1-020-I12", "objective": "Передать нужные поля и уточнить неизвестное", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_short", "item_id": "U-A1-020-I13", "objective": "Передать нужные поля и уточнить неизвестное", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-A1-020-I14", "objective": "Передать нужные поля и уточнить неизвестное", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}], "competency_ids": ["A1-L02"], "coverage_claim": "TEXT_ROUTE_AUTHORED_AUDIO_AND_INDEPENDENT_QA_BLOCKED", "speaking_tasks": ["U-A1-020-I11"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION", "FACT_SUBSTITUTION", "ASR_UNCERTAIN", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A1-020-I02", "U-A1-020-I03", "U-A1-020-I04", "U-A1-020-I05", "U-A1-020-I06", "U-A1-020-I07", "U-A1-020-I09"], "listening_tasks": ["U-A1-020-I02", "U-A1-020-I03", "U-A1-020-I04", "U-A1-020-I05", "U-A1-020-I06", "U-A1-020-I10", "U-A1-020-I12", "U-A1-020-I13", "U-A1-020-I14"], "mastery_contract": {"open": "Every task-specific content criterion met independently, intelligible response; quote evidence per criterion", "closed": "At least80% on fresh controlled tasks, no uncorrected critical fact errors; project heuristic only", "listening": "Requires verified media, transcript hidden, play count logged", "retention": "Independent D7 and D28; one hint makes assisted evidence", "pronunciation": "Requires actual recording and listening; ASR text alone insufficient"}, "reading_texts_el": [], "vocabulary_items": [{"lemma": "η αίθουσα", "stress": "η αίθουσα", "example": "Το μάθημα είναι στην αίθουσα δύο.", "inflection": "την αίθουσα / οι αίθουσες", "meaning_ru": "аудитория", "collocations": ["Το μάθημα είναι στην αίθουσα δύο."]}, {"lemma": "φεύγω", "stress": "φεύγω", "example": "Το λεωφορείο φεύγει στις τρεις.", "inflection": "φεύγω / φεύγει", "meaning_ru": "уходить, отправляться", "collocations": ["Το λεωφορείο φεύγει στις τρεις."]}, {"lemma": "σήμερα", "stress": "σήμερα", "example": "Σήμερα αρχίζουμε στις έξι.", "inflection": "наречие", "meaning_ru": "сегодня", "collocations": ["Σήμερα αρχίζουμε στις έξι."]}], "diagnostic_item_ids": ["U-A1-020-I01"], "learning_objectives": ["Различить номер и время", "Извлечь исправленную информацию", "Передать нужные поля и уточнить неизвестное"], "prerequisite_support": {"A1-V02": "Use primary unit from CONTENT_Production_Register_96.csv; if entry task fails, reteach prerequisite and retry on a fresh example before target assessment"}, "primary_competencies": ["A1-L02"], "estimated_active_minutes": 70}	e1bf134269f2c1dcff392a3825002eb9a8635a319679f0428b2bc65be26db226	3126
U-A2-001	A2	201	Одно завершённое событие: ενεργητικός αόριστος	{A1-G06}	{}	{A2-G03,A2-SP01,A2-W01}	{A2-G03}	45	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A2-001-RUBRIC"], "unit_id": "U-A2-001", "version": "0.1.2", "sections": {"theory": "theory_ru", "practice": ["U-A2-001-I02", "U-A2-001-I03", "U-A2-001-I04", "U-A2-001-I05", "U-A2-001-I06", "U-A2-001-I07"], "reception": ["U-A2-001-I08", "U-A2-001-I09", "U-A2-001-I10", "U-A2-001-I11"], "retention": ["U-A2-001-I15", "U-A2-001-I16", "U-A2-001-I17"], "diagnostic": ["U-A2-001-I01"], "production": ["U-A2-001-I12", "U-A2-001-I13", "U-A2-001-I14"]}, "title_ru": "Одно завершённое событие: ενεργητικός αόριστος", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Αόριστος представляет событие целиком: Χτες αγόρασα ένα εισιτήριο. Это не обязательно короткое действие: Δούλεψα εκεί δύο χρόνια тоже может описывать законченный отрезок. Слова χτες и πέρσι помогают понять время, но сами по себе не определяют выбор вида во всех контекстах. В этом уроке ситуации специально заданы как целостные завершённые события. Систематическое сравнение с παρατατικός оставлено A2 в U-A2-008.\\n\\nЧастотная активная модель: αγόρασα, αγόρασες, αγόρασε, αγοράσαμε, αγοράσατε, αγόρασαν. Ударение нужно учить вместе с формой, а не сохранять механически из настоящего. В некоторых глаголах появляется начальное έ-: γράφω → έγραψα, но γράψαμε. Нельзя добавлять έ- к любому глаголу. Другие формы меняют основу: πηγαίνω → πήγα, βλέπω → είδα, παίρνω → πήρα. Заучиваем их в коротких сообщениях.\\n\\nОтрицание перед глаголом: Δεν πήγα στο γραφείο. Вопрос не требует отдельного вспомогательного глагола: Πότε πήγες; Сравните Κάθε μέρα αγοράζω ψωμί (обычная практика) и Χτες αγόρασα ψωμί (одно событие). Подлежащее часто понятно по окончанию. В рассказе сначала обозначьте время и событие, затем следствие: Χτες αγόρασα μια λάμπα, αλλά δεν λειτουργεί. Это языковая учебная ситуация, а не утверждение о правилах возврата товаров.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Χτες αγόρασα ένα εισιτήριο.", "Η Άννα έγραψε ένα μήνυμα.", "Πήγαμε στο μουσείο το Σάββατο.", "Δεν είδα τον Νίκο χτες.", "Κάθε μέρα παίρνω το λεωφορείο. Χτες πήρα ταξί."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A2-001-I15", "U-A2-001-I16", "U-A2-001-I17"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF7: активный аорист; не переносить систематический imperfect с B1", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Sustained monologue describing experience / correspondence, A2", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A2-001-I06", "U-A2-001-I07"], "prerequisites": ["A1-G06"], "reading_tasks": ["U-A2-001-I08", "U-A2-001-I09"], "transfer_task": "U-A2-001-I14", "writing_tasks": ["U-A2-001-I12"], "competency_ids": ["A2-G03", "A2-SP01", "A2-W01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A2-001-I13"], "errors_taxonomy": ["VERB_TENSE", "ORTHOGRAPHY_ACCENT", "CONTENT_OMISSION"], "guided_practice": ["U-A2-001-I02", "U-A2-001-I03", "U-A2-001-I04", "U-A2-001-I05"], "listening_tasks": ["U-A2-001-I10", "U-A2-001-I11"], "learning_outcome": "Образовать частотный активный аорист в заданном лице", "vocabulary_items": [{"lemma": "αγοράζω", "stress": "αγοράζω", "example": "Αγόρασα δύο εισιτήρια.", "inflection": "αόριστος αγόρασα", "meaning_ru": "покупать", "collocations": ["αγοράζω εισιτήριο"]}, {"lemma": "γράφω", "stress": "γράφω", "example": "Έγραψα στη Μαρία.", "inflection": "αόριστος έγραψα", "meaning_ru": "писать", "collocations": ["γράφω μήνυμα"]}, {"lemma": "πηγαίνω", "stress": "πηγαίνω", "example": "Πήγα στο μουσείο.", "inflection": "αόριστος πήγα", "meaning_ru": "идти/ехать", "collocations": ["πηγαίνω στο μουσείο"]}, {"lemma": "απόδειξη", "stress": "απόδειξη", "example": "Έχω την απόδειξη μαζί μου.", "inflection": "η απόδειξη, οι αποδείξεις", "meaning_ru": "чек", "collocations": ["έχω την απόδειξη"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A2-001-I01"], "learning_objectives": ["Образовать частотный активный аорист в заданном лице", "Понять последовательность отдельных завершённых событий", "Самостоятельно рассказать о завершённой покупке и её результате"], "microcompetency_ids": ["U-A2-001-MC01", "U-A2-001-MC02", "U-A2-001-MC03"], "primary_competencies": ["A2-G03"], "learner_data_included": false, "estimated_active_minutes": 45}	f39f7193ff3d003c976194a5efaa83170aa29f3e9cd3bb4182b19cedcbc62317	3127
U-A2-002	A2	202	Планы и просьбы: θα и να с совершенной основой	{A2-G03,A1-G12}	{}	{A2-G05,A2-G06}	{A2-G05,A2-G06}	45	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A2-002-RUBRIC"], "unit_id": "U-A2-002", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-A2-002-I02", "U-A2-002-I03", "U-A2-002-I04", "U-A2-002-I05", "U-A2-002-I06"], "reception": ["U-A2-002-I07", "U-A2-002-I08", "U-A2-002-I09", "U-A2-002-I10"], "retention": ["U-A2-002-I14", "U-A2-002-I15", "U-A2-002-I16"], "diagnostic": ["U-A2-002-I01"], "production": ["U-A2-002-I11", "U-A2-002-I12", "U-A2-002-I13"]}, "title_ru": "Планы и просьбы: θα и να с совершенной основой", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Θα + личная форма передаёт будущее, а να после θέλω, μπορώ, πρέπει вводит желаемое, возможное или необходимое действие. Здесь учимся представить действие целиком: θα γράψω, θέλω να γράψω, πρέπει να στείλω. Формы пишутся без прошедшей аугментации: έγραψα, но θα γράψω; έστειλα, но να στείλω. Это не механическое удаление первого слога любого аориста: нерегулярные основы учатся отдельно, πήγα → θα πάω.\\nСравните Θέλω να κλείσω ένα ραντεβού (хочу записаться) и Θα κλείσω ένα ραντεβού (сообщаю о плане). Отрицание зависит от конструкции: Δεν θα πάω; Θέλω να μην αργήσω. Частое Не могу выражается Δεν μπορώ να… — отрицание относится к возможности. Μην не заменяет δεν перед любым глаголом.\\nВ A1 такие просьбы могли быть готовыми формулами. Этот урок систематизирует выбор основы для нескольких частотных глаголов; полное видовое противопоставление и сложные случаи не считаются закрытыми. Если сотрудник сообщает ограничение, измените план: Μπορώ να έρθω την Τρίτη; Это учебная ролевая ситуация, не обещание доступности реальной услуги.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Θα γράψω ένα μήνυμα.", "Θέλω να κλείσω ένα ραντεβού.", "Δεν μπορώ να έρθω αύριο.", "Πρέπει να στείλουμε την αίτηση."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A2-002-I14", "U-A2-002-I15", "U-A2-002-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF7–8", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction A2", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A2-002-I05", "U-A2-002-I06"], "prerequisites": ["A2-G03", "A1-G12"], "reading_tasks": ["U-A2-002-I07", "U-A2-002-I08"], "transfer_task": "U-A2-002-I13", "writing_tasks": ["U-A2-002-I11"], "competency_ids": ["A2-G05", "A2-G06"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A2-002-I12"], "errors_taxonomy": ["VERB_ASPECT", "VERB_TENSE", "SYNTAX"], "guided_practice": ["U-A2-002-I02", "U-A2-002-I03", "U-A2-002-I04"], "listening_tasks": ["U-A2-002-I09", "U-A2-002-I10"], "learning_outcome": "Выразить единичный план через θα и совершенную основу", "vocabulary_items": [{"lemma": "κλείνω", "stress": "κλείνω", "example": "Θέλω να κλείσω ραντεβού.", "inflection": "έκλεισα; θα κλείσω", "meaning_ru": "записывать/закрывать", "collocations": ["κλείνω ραντεβού"]}, {"lemma": "έρχομαι", "stress": "έρχομαι", "example": "Μπορώ να έρθω την Τρίτη.", "inflection": "ήρθα; θα έρθω", "meaning_ru": "приходить", "collocations": ["έρχομαι την Τρίτη"]}, {"lemma": "αίτηση", "stress": "αίτηση", "example": "Θα στείλω την αίτηση.", "inflection": "η αίτηση, οι αιτήσεις", "meaning_ru": "заявление", "collocations": ["στέλνω αίτηση"]}, {"lemma": "ραντεβού", "stress": "ραντεβού", "example": "Το ραντεβού είναι αύριο.", "inflection": "το ραντεβού; неизменяемое", "meaning_ru": "встреча по записи", "collocations": ["κλείνω ραντεβού"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A2-002-I01"], "learning_objectives": ["Выразить единичный план через θα и совершенную основу", "Построить просьбу с να и отрицание с μην", "Изменить план после нового ограничения собеседника"], "microcompetency_ids": ["U-A2-002-MC01", "U-A2-002-MC02", "U-A2-002-MC03"], "primary_competencies": ["A2-G05", "A2-G06"], "learner_data_included": false, "estimated_active_minutes": 45}	4df871cdd1591fe968599038602bd7b45eeac6f317d5e93557d7c072822f0de3	3128
U-A2-003	A2	203	Кому принадлежит вещь: родительный	{A1-G01,A1-G02}	{}	{A2-G01}	{A2-G01}	45	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A2-003-RUBRIC"], "unit_id": "U-A2-003", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-A2-003-I02", "U-A2-003-I03", "U-A2-003-I04", "U-A2-003-I05", "U-A2-003-I06"], "reception": ["U-A2-003-I07", "U-A2-003-I08", "U-A2-003-I09", "U-A2-003-I10"], "retention": ["U-A2-003-I14", "U-A2-003-I15", "U-A2-003-I16"], "diagnostic": ["U-A2-003-I01"], "production": ["U-A2-003-I11", "U-A2-003-I12", "U-A2-003-I13"]}, "title_ru": "Кому принадлежит вещь: родительный", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Родительный помогает назвать владельца: το βιβλίο του φίλου, η τσάντα της φίλης, το δωμάτιο του παιδιού. Артикль владельца становится του/της/του. У мужского -ος в нашей модели родительный -ου: ο φίλος → του φίλου. У женского -η появляется -ς: η φίλη → της φίλης. У среднего παιδί — παιδιού с перемещением ударения. Не переносите эту модель автоматически на все существительные.\\nКороткие μου/σου/του/της после существительного тоже выражают принадлежность: το κινητό μου. Ударение и место важны; формы полноценного местоимения δικός вводятся в другом блоке. Вопрос Ποιανού είναι; может задаваться о владельце. В ответе Это телефон Марии: Είναι το κινητό της Μαρίας.\\nНе путайте владельца с предметом: в το κλειδί του γραφείου грамматический род του определяется словом γραφείο, а не κλειδί. Частотные объявления о потерянной вещи требуют сообщить описание и осторожно проверить владельца; в учебной роли не запрашиваются реальные банковские или паспортные данные.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Αυτό είναι το βιβλίο του φίλου μου.", "Η τσάντα της Μαρίας είναι εδώ.", "Το δωμάτιο του παιδιού είναι μικρό.", "Ποιανού είναι αυτό το κινητό;"], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A2-003-I14", "U-A2-003-I15", "U-A2-003-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF7–8", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction A2", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A2-003-I05", "U-A2-003-I06"], "prerequisites": ["A1-G01", "A1-G02"], "reading_tasks": ["U-A2-003-I07", "U-A2-003-I08"], "transfer_task": "U-A2-003-I13", "writing_tasks": ["U-A2-003-I11"], "competency_ids": ["A2-G01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A2-003-I12"], "errors_taxonomy": ["MORPHOLOGY_CASE", "ORTHOGRAPHY_ACCENT"], "guided_practice": ["U-A2-003-I02", "U-A2-003-I03", "U-A2-003-I04"], "listening_tasks": ["U-A2-003-I09", "U-A2-003-I10"], "learning_outcome": "Назвать владельца через родительный существительного", "vocabulary_items": [{"lemma": "κλειδί", "stress": "κλειδί", "example": "Βρήκα το κλειδί του σπιτιού.", "inflection": "το κλειδί, του κλειδιού", "meaning_ru": "ключ", "collocations": ["το κλειδί του σπιτιού"]}, {"lemma": "κινητό", "stress": "κινητό", "example": "Το κινητό μου είναι εδώ.", "inflection": "το κινητό, του κινητού", "meaning_ru": "мобильный телефон", "collocations": ["το κινητό μου"]}, {"lemma": "τσάντα", "stress": "τσάντα", "example": "Η τσάντα της Μαρίας είναι μπλε.", "inflection": "η τσάντα, της τσάντας", "meaning_ru": "сумка", "collocations": ["η τσάντα της Μαρίας"]}, {"lemma": "ποιανού", "stress": "ποιανού", "example": "Ποιανού είναι το βιβλίο;", "inflection": "вопросительная форма", "meaning_ru": "чей/кому принадлежит", "collocations": ["ποιανού είναι"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A2-003-I01"], "learning_objectives": ["Назвать владельца через родительный существительного", "Различить владельца и предмет в письменном и устном сообщении", "Уточнить принадлежность нового предмета в диалоге"], "microcompetency_ids": ["U-A2-003-MC01", "U-A2-003-MC02", "U-A2-003-MC03"], "primary_competencies": ["A2-G01"], "learner_data_included": false, "estimated_active_minutes": 45}	3fd734ee13247fc8d2cf258e704aa7bf1c5dcb59b51f792e29dcdaf1a27037a2	3129
U-A2-004	A2	204	Сравнить два варианта жилья	{A1-G04}	{}	{A2-G09,A2-R01}	{A2-G09,A2-R01}	45	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A2-004-RUBRIC"], "unit_id": "U-A2-004", "version": "0.1.2", "sections": {"theory": "theory_ru", "practice": ["U-A2-004-I02", "U-A2-004-I03", "U-A2-004-I04", "U-A2-004-I05", "U-A2-004-I06"], "reception": ["U-A2-004-I07", "U-A2-004-I08", "U-A2-004-I09", "U-A2-004-I10"], "retention": ["U-A2-004-I14", "U-A2-004-I15", "U-A2-004-I16"], "diagnostic": ["U-A2-004-I01"], "production": ["U-A2-004-I11", "U-A2-004-I12", "U-A2-004-I13"]}, "title_ru": "Сравнить два варианта жилья", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Для базового сравнения используем πιο + прилагательное и από для второго объекта: Το δωμάτιο Α είναι πιο μεγάλο από το Β. После από существительное/местоимение оформляется как соответствующее дополнение; здесь работаем с названиями вариантов. Прилагательное согласуется с тем, что сравниваем: πιο μικρό δωμάτιο, πιο μικρή κουζίνα. Πιο не меняется.\\nПри равенстве возможна модель τόσο…όσο: Το Α είναι τόσο φωτεινό όσο το Β. Для A2 достаточно сначала понимать её и применять в ограниченном наборе; синтетические/нерегулярные сравнения и ограничения относятся к более позднему расширению. Самое дешёвое среди набора: το πιο φτηνό. Но «дешевле» не равняется «лучше» для любого человека.\\nЧтобы выбрать жильё, сравните одинаковые величины: месячная аренда с месячной арендой, время пути одним способом. Если в объявлении не указаны коммунальные расходы, не включайте их в доказанную итоговую цену. В учебном кейсе все суммы вымышлены. Отделяйте факт от предпочтения: Το Α είναι πιο φτηνό, αλλά προτιμώ το Β γιατί είναι κοντά στο μάθημα.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Το Α είναι πιο φτηνό από το Β.", "Η κουζίνα είναι πιο μικρή.", "Το δωμάτιο είναι τόσο φωτεινό όσο το άλλο.", "Προτιμώ το Β γιατί είναι κοντά στο μάθημα."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A2-004-I14", "U-A2-004-I15", "U-A2-004-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF7–8", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction A2", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A2-004-I05", "U-A2-004-I06"], "prerequisites": ["A1-G04"], "reading_tasks": ["U-A2-004-I07", "U-A2-004-I08"], "transfer_task": "U-A2-004-I13", "writing_tasks": ["U-A2-004-I11"], "competency_ids": ["A2-G09", "A2-R01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A2-004-I12"], "errors_taxonomy": ["GENDER_AGREEMENT", "COMPREHENSION", "CONTENT_OMISSION"], "guided_practice": ["U-A2-004-I02", "U-A2-004-I03", "U-A2-004-I04"], "listening_tasks": ["U-A2-004-I09", "U-A2-004-I10"], "remaining_scope": ["Нерегулярные сравнительные формы: отдельное продолжение, не освоены здесь"], "learning_outcome": "Сравнить жильё с πιο…από и понять изученный пример μεγαλύτερη", "vocabulary_items": [{"lemma": "φτηνός", "stress": "φτηνός", "example": "Το σπίτι είναι πιο φτηνό.", "inflection": "φτηνός, φτηνή, φτηνό", "meaning_ru": "дешёвый", "collocations": ["πιο φτηνό σπίτι"]}, {"lemma": "φωτεινός", "stress": "φωτεινός", "example": "Θέλω ένα φωτεινό δωμάτιο.", "inflection": "φωτεινός, φωτεινή, φωτεινό", "meaning_ru": "светлый", "collocations": ["φωτεινό δωμάτιο"]}, {"lemma": "ενοίκιο", "stress": "ενοίκιο", "example": "Το ενοίκιο είναι τετρακόσια ευρώ.", "inflection": "το ενοίκιο, τα ενοίκια", "meaning_ru": "аренда", "collocations": ["μηνιαίο ενοίκιο"]}, {"lemma": "προτιμώ", "stress": "προτιμώ", "example": "Προτιμώ το δεύτερο δωμάτιο.", "inflection": "προτιμώ, προτιμάς", "meaning_ru": "предпочитать", "collocations": ["προτιμώ το δεύτερο"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A2-004-I01"], "learning_objectives": ["Сравнить жильё с πιο…από и понять изученный пример μεγαλύτερη", "Извлечь цену и ограничения из объявления", "Обосновать выбор по двум заданным потребностям"], "microcompetency_ids": ["U-A2-004-MC01", "U-A2-004-MC02", "U-A2-004-MC03"], "primary_competencies": ["A2-G09", "A2-R01"], "learner_data_included": false, "estimated_active_minutes": 45}	7339a54567e1c4b1e49ed71ad29f02e57775c6adddc2c0b85aab052b3890b314	3130
U-A2-005	A2	205	Объектные клитики и короткие инструкции	{A1-G02,A2-G06}	{}	{A2-G02,A2-G07}	{A2-G02,A2-G07}	45	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A2-005-RUBRIC"], "unit_id": "U-A2-005", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-A2-005-I02", "U-A2-005-I03", "U-A2-005-I04", "U-A2-005-I05", "U-A2-005-I06"], "reception": ["U-A2-005-I07", "U-A2-005-I08", "U-A2-005-I09", "U-A2-005-I10"], "retention": ["U-A2-005-I14", "U-A2-005-I15", "U-A2-005-I16"], "diagnostic": ["U-A2-005-I01"], "production": ["U-A2-005-I11", "U-A2-005-I12", "U-A2-005-I13"]}, "title_ru": "Объектные клитики и короткие инструкции", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Если предмет уже назван, его можно заменить безударным местоимением: Βλέπω τον φάκελο → Τον βλέπω; βλέπω την τσάντα → τη βλέπω; βλέπω το κουτί → το βλέπω. Во множественном τους φακέλους → τους, τις τσάντες → τις, τα κουτιά → τα. Выбирайте род и число греческого существительного. В Την ξέρω клитика может обозначать и человека.\\nПеред обычной личной формой местоимение ставится до глагола: Το ανοίγω. После положительного императива — после: Άνοιξέ το. Дополнительное ударение в Άνοιξέ το связано с присоединением безударного местоимения к форме с ударением на третьем слоге от конца; оно не произвольное украшение. В Γράψ’ το сокращённая форма имеет другую графику. Для начальной практики используем Άνοιξέ το / Κλείσ’ το и πλήρη Άνοιξε την πόρτα.\\nОтрицательная инструкция отличается: Μην το ανοίξεις. Здесь местоимение опять перед глаголом. Не используйте *μην άνοιξε как автоматический отрицательный вариант императива. Вежливая альтернатива Μπορείτε να το ανοίξετε; полезна с незнакомым взрослым, а Άνοιξέ το может быть естественным в близком общении или инструкции. Регистр оценивается по ситуации, а не по наличию одного слова παρακαλώ.\\nПеред заменой проверьте, нет ли двух возможных предметов одного рода. Если есть, повторите существительное. Этот урок вводит одиночный прямой объект; двойные клитики «кому+что» изучаются отдельно.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Βλέπω την τσάντα. Τη βλέπω.", "Άνοιξε το παράθυρο. Άνοιξέ το.", "Μην το ανοίξεις ακόμη.", "Μπορείτε να το κλείσετε;"], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A2-005-I14", "U-A2-005-I15", "U-A2-005-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF7–8", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction A2", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-A2-005-I05", "U-A2-005-I06"], "prerequisites": ["A1-G02", "A2-G06"], "reading_tasks": ["U-A2-005-I07", "U-A2-005-I08"], "transfer_task": "U-A2-005-I13", "writing_tasks": ["U-A2-005-I11"], "competency_ids": ["A2-G02", "A2-G07"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-A2-005-I12"], "errors_taxonomy": ["CLITIC_POSITION", "IMPERATIVE", "ACCENTUATION"], "guided_practice": ["U-A2-005-I02", "U-A2-005-I03", "U-A2-005-I04"], "listening_tasks": ["U-A2-005-I09", "U-A2-005-I10"], "learning_outcome": "Заменить прямой объект одиночной клитикой", "vocabulary_items": [{"lemma": "ανοίγω", "stress": "ανοίγω", "example": "Άνοιξέ το, παρακαλώ.", "inflection": "άνοιξα; άνοιξε; να ανοίξω", "meaning_ru": "открывать", "collocations": ["ανοίγω το παράθυρο"]}, {"lemma": "κλείνω", "stress": "κλείνω", "example": "Μπορείτε να την κλείσετε;", "inflection": "έκλεισα; κλείσε; να κλείσω", "meaning_ru": "закрывать", "collocations": ["κλείνω την πόρτα"]}, {"lemma": "φέρνω", "stress": "φέρνω", "example": "Φέρε τα βιβλία.", "inflection": "έφερα; φέρε; να φέρω", "meaning_ru": "приносить", "collocations": ["φέρνω τα βιβλία"]}, {"lemma": "παράθυρο", "stress": "παράθυρο", "example": "Το παράθυρο είναι κλειστό.", "inflection": "το παράθυρο, τα παράθυρα", "meaning_ru": "окно", "collocations": ["ανοίγω το παράθυρο"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A2-005-I01"], "learning_objectives": ["Заменить прямой объект одиночной клитикой", "Различить порядок клитики в утверждении, приказе и запрете", "Дать новые инструкции с понятным объектом"], "microcompetency_ids": ["U-A2-005-MC01", "U-A2-005-MC02", "U-A2-005-MC03"], "primary_competencies": ["A2-G02", "A2-G07"], "learner_data_included": false, "estimated_active_minutes": 45}	449dfc69cfd8fb9d5eb214aa2c8da2ce7c556e0f1517d9cbe7dce531cc9b4856	3131
U-A2-006	A2	206	Настоящее: εργάζομαι и έρχομαι	{A1-G06}	{}	{A2-G08}	{A2-G08}	65	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-A2-006-RUBRIC"], "unit_id": "U-A2-006", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-A2-006-I02", "U-A2-006-I03", "U-A2-006-I04", "U-A2-006-I05", "U-A2-006-I06", "U-A2-006-I07", "U-A2-006-I08", "U-A2-006-I19", "U-A2-006-I20"], "reception": ["U-A2-006-I09", "U-A2-006-I10", "U-A2-006-I11", "U-A2-006-I12"], "retention": ["U-A2-006-I16", "U-A2-006-I17", "U-A2-006-I18", "U-A2-006-I22"], "diagnostic": ["U-A2-006-I01"], "production": ["U-A2-006-I13", "U-A2-006-I14", "U-A2-006-I15", "U-A2-006-I21"]}, "title_ru": "Настоящее: εργάζομαι и έρχομαι", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Форма на -μαι относится к медиопассивной морфологии, но не означает автоматически «со мной делают действие». Εργάζομαι означает «работаю», έρχομαι — «прихожу/иду сюда». В Εργάζομαι σε ένα ξενοδοχείο человек работает сам; не нужно придумывать скрытого исполнителя. Различайте внешний вид формы и значение целого глагола.\\n\\nВыучите две парадигмы по лицам: εγώ εργάζομαι, εσύ εργάζεσαι, αυτός/αυτή εργάζεται, εμείς εργαζόμαστε, εσείς εργάζεστε, αυτοί/αυτές εργάζονται. Для έρχομαι: έρχομαι, έρχεσαι, έρχεται, ερχόμαστε, έρχεστε, έρχονται. Обратите внимание на ударение в εργαζόμαστε и ερχόμαστε. Не выводите все шесть форм механически из русского «мы/вы» и не добавляйте активное -ουμε к основе εργάζ-.\\n\\nЛичное местоимение часто не требуется: Εργάζομαι εδώ уже означает «я». Если называете двух людей, нужен множественный глагол: Η Άννα και ο Πέτρος εργάζονται μαζί. При вежливом обращении к одному человеку используйте форму εσείς: Πότε έρχεστε; Это не свидетельство того, что собеседников несколько.\\n\\nНастоящее описывает обычное расписание: Έρχομαι κάθε Τρίτη. С указанием времени оно может выражать договорённость: Έρχομαι αύριο στις δέκα. Контекст определяет, говорим ли о привычке или ближайшем плане. В этом уроке не требуется строить прошедшие формы этих глаголов: они изучаются отдельно.\\n\\nОтрицание стоит перед личной формой: Δεν εργάζομαι την Κυριακή. Вопрос часто сохраняет порядок слов: Έρχεσαι αύριο; В ответе не повторяйте вопросительную форму: Ναι, έρχομαι. Для места работы используйте σε: σε ένα γραφείο, στο γραφείο. Движение έρχομαι связано с приходом к говорящему/собеседнику или согласованной точке: Έρχομαι στο σπίτι σου. Πηγαίνω обычно направляет движение к другой точке; выбор зависит от перспективы, поэтому это не абсолютное географическое правило.\\n\\nПри самостоятельной речи назовите человека, место и время, затем проверьте лицо глагола. Если партнёр меняет время встречи, дайте новый ответ, а не воспроизводите выученный монолог. Успех — понятное согласование реального расписания, а не только шесть форм подряд.", "cefr_level": "A2", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Εργάζομαι σε ένα μικρό ξενοδοχείο.", "Η αδελφή μου εργάζεται στο κέντρο.", "Εμείς εργαζόμαστε μαζί.", "Εσείς εργάζεστε σήμερα;", "Τα παιδιά έρχονται στις έξι.", "Έρχεσαι σπίτι μου; — Ναι, έρχομαι."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-A2-006-I16", "U-A2-006-I17", "U-A2-006-I18", "U-A2-006-I22