 "guided_practice": ["U-A2-006-I02", "U-A2-006-I03", "U-A2-006-I04", "U-A2-006-I05", "U-A2-006-I06"], "listening_tasks": ["U-A2-006-I11", "U-A2-006-I12"], "pedagogy_review": {"scope": "full explanation, contrast, model, controlled practice, recall, reception, independent output, repair, transfer, delayed retrieval", "status": "AUTHOR_REVIEWED_NOT_INDEPENDENT", "open_blockers": ["INDEPENDENT_GREEK_REVIEW", "AUDIO_NOT_PRODUCED", "LEARNER_PILOT_NOT_RUN"]}, "learning_outcome": "Выбрать личную форму εργάζομαι / έρχομαι для шести лиц.", "vocabulary_items": [{"lemma": "εργάζομαι", "stress": "εργάζομαι", "example": "Εργάζομαι εδώ.", "inflection": "εργαζόμαστε", "meaning_ru": "работать", "collocations": ["εργάζομαι σε γραφείο"]}, {"lemma": "έρχομαι", "stress": "έρχομαι", "example": "Ερχόμαστε στις οκτώ.", "inflection": "ερχόμαστε", "meaning_ru": "приходить", "collocations": ["έρχομαι στην ώρα μου"]}, {"lemma": "το ωράριο", "stress": "το ωράριο", "example": "Το ωράριο αλλάζει.", "inflection": "του ωραρίου", "meaning_ru": "расписание работы", "collocations": ["το ωράριο εργασίας"]}, {"lemma": "η βάρδια", "stress": "η βάρδια", "example": "Έχω πρωινή βάρδια.", "inflection": "οι βάρδιες", "meaning_ru": "смена", "collocations": ["πρωινή βάρδια"]}, {"lemma": "μαζί", "stress": "μαζί", "example": "Εργαζόμαστε μαζί.", "inflection": "наречие", "meaning_ru": "вместе", "collocations": ["εργαζόμαστε μαζί"]}, {"lemma": "το ραντεβού", "stress": "το ραντεβού", "example": "Το ραντεβού είναι αύριο.", "inflection": "несклоняемое", "meaning_ru": "встреча/запись", "collocations": ["κλείνω ραντεβού"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-A2-006-I01"], "learning_objectives": ["Выбрать личную форму εργάζομαι / έρχομαι для шести лиц.", "Описать расписание и договориться о приходе, не приписывая формам пассивного смысла.", "Исправить несогласование и самостоятельно перенести модели на новую встречу."], "microcompetency_ids": ["U-A2-006-MC01", "U-A2-006-MC02", "U-A2-006-MC03"], "prima