cabulary_items": [{"lemma": "γράφω", "stress": "γράφω", "example": "Χθες έγραψα ένα μήνυμα.", "inflection": "έγραψα / γράψαμε", "meaning_ru": "писать", "collocations": ["Χθες έγραψα ένα μήνυμα."]}, {"lemma": "το μάθημα", "stress": "το μάθημα", "example": "Τα μαθήματα αρχίζουν στις έξι.", "inflection": "το μάθημα / τα μαθήματα", "meaning_ru": "урок", "collocations": ["Τα μαθήματα αρχίζουν στις έξι."]}, {"lemma": "αύριο", "stress": "αύριο", "example": "Έρχεται αύριο;", "inflection": "наречие", "meaning_ru": "завтра", "collocations": ["Έρχεται αύριο;"]}], "diagnostic_item_ids": ["U-A2-016-I01"], "learning_objectives": ["Различить письменное и акустическое свидетельство", "Сохранить ударение изменённых форм", "Передать вопросительное намерение и смысловые группы"], "prerequisite_support": {"A1-P02": "Use primary unit from CONTENT_Production_Register_96.csv; if entry task fails, reteach prerequisite and retry on a fresh example before target assessment", "A2-G03": "Use primary unit from CONTENT_Production_Register_96.csv; if entry task fails, reteach prerequisite and retry on a fresh example before target assessment"}, "primary_competencies": ["A2-P01"], "estimated_active_minutes": 70}	f1b336b97bcc8fde8045cca1bb363ea0110ca94c4cfff16b62a8a0e2f09e970b	3142
U-A2-017	A2	217	Бытовой диалог: запрос, альтернатива и итог	{A1-L01,A2-V01}	{}	{A2-L01}	{A2-L01}	70	{"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "COMPLETE_NOT_INDEPENDENT", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A2-017-RUBRIC"], "unit_id": "U-A2-017", "version": "0.1.0", "title_ru": "Бытовой диалог: запрос, альтернатива и итог", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Короткий диалог содержит не только факты, но и действия: человек просит, сотрудник уточняет, предлагает замену, собеседник соглашается или отказывается. Сначала установите цель разговора. Затем отделите первоначальное желание от достигнутой договорённости. Если человек хотел вторник, но согласился на четверг, в заметке об итоге нужен четверг. Одного узнавания знакомого слова «вторник» недостаточно.\\nНа входе повторите бытовую лексику A2-V01 и понимание простых вопросов A1-L01. Слово ραντεβού здесь означает заранее согласованную встречу или приём. Вопрос Υπάρχει ώρα την Τρίτη; ещё не доказывает запись. Ответ Την Τρίτη δεν γίνεται исключает этот вариант; Μπορείτε την Πέμπτη; предлагает альтернативу. Только последующее Ναι, την Πέμπτη στις δέκα подтверждает выбор в рамках учебной ситуации.\\nРаботайте с тремя колонками: запрос — препятствие — итог. Причина отказа может быть названа или отсутствовать. Не дополняйте «нет свободного времени» догадками о болезни, ремонте или празднике. Уточняйте, кто должен сделать следующий шаг: Θα σας τηλεφωνήσω говорит сотрудник о своём действии, Τηλεφωνήστε μας ζητά звонка от клиента. Эти фразы вводятся в контексте, не как полный урок будущего времени и повелительного наклонения.\\nВ магазине различайте отсутствие товара, отсутствие нужного размера и отсутствие нужного цвета. Если продавец предлагает синюю сумку вместо чёрной, согласие на синий цвет не означает изменение количества. В заданиях новые слова объясняются до первого прослушивания, но итоговая договорённость не показывается. При повторном прослушивании ищите точное место изменения.\\nПересказ должен сохранять факты, но не обязан копировать реплики. «Έκλεισα ραντεβού για την Πέμπτη στις δέκα» допустимо после явного подтверждения. Если разговор прервался раньше, скажите, что встреча ещё не подтверждена. Не путайте неуслышанный ответ с отказом. В самостоятельной роли задайте вопрос, отреагируйте на неожиданную замену и подтвердите результат или вежливо откажитесь.\\nДля проверки аудирования необходимо реальное аудио с двумя различимыми голосами. На подготовительном чтении отмечайте участников, а при прослушивании скрывайте имена ролей и транскрипт. Разные виды помощи фиксируются отдельно. На D7/D28 меняются предмет разговора и данные: оцениваем перенос стратегии, а не запоминание диалога.", "cefr_level": "A2", "time_basis": "AUTHOR_PLANNING_ESTIMATE_NOT_PILOTED", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Θα ήθελα ένα ραντεβού την Τρίτη.", "Την Τρίτη δεν υπάρχει διαθέσιμη ώρα.", "Μπορείτε την Πέμπτη στις δέκα;", "Ναι, την Πέμπτη στις δέκα.", "Δεν έχουμε μαύρη τσάντα.", "Τότε θα πάρω την μπλε."], "review_plan": {"days": [7, 28], "rule": "New stimulus, no model shown before attempt; assistance recorded; corrected answer alone is not independent retention", "item_ids": ["U-A2-017-I12", "U-A2-017-I13"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Κατανόηση προφορικού λόγου, paragraphs 1–2 (lines87–89)", "source_id": "CP08-A2", "checked_on": "2026-10-21", "claim_scope": "Bounded descriptor or phonological principle only; original examples, lesson sequence, rubrics and thresholds are not official"}], "active_recall": ["U-A2-017-I08"], "prerequisites": ["A1-L01", "A2-V01"], "reading_tasks": ["U-A2-017-I07"], "transfer_task": "U-A2-017-I11", "writing_tasks": ["U-A2-017-I09"], "assessment_map": [{"kind": "mcq", "item_id": "U-A2-017-I01", "objective": "Понять цель и участников", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-A2-017-I02", "objective": "Понять цель и участников", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_short", "item_id": "U-A2-017-I03", "objective": "Понять цель и участников", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-A2-017-I04", "objective": "Понять цель и участников", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_short", "item_id": "U-A2-017-I05", "objective": "Понять цель и участников", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-A2-017-I06", "objective": "Отличить предложение от итоговой договорённости", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "read_mcq", "item_id": "U-A2-017-I07", "objective": "Отличить предложение от итоговой договорённости", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "short", "item_id": "U-A2-017-I08", "objective": "Отличить предложение от итоговой договорённости", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "open", "item_id": "U-A2-017-I09", "objective": "Отличить предложение от итоговой договорённости", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "speak", "item_id": "U-A2-017-I10", "objective": "Перенести уточнение и подтверждение в новую ситуацию", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-A2-017-I11", "objective": "Перенести уточнение и подтверждение в новую ситуацию", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-A2-017-I12", "objective": "Перенести уточнение и подтверждение в новую ситуацию", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "speak", "item_id": "U-A2-017-I13", "objective": "Перенести уточнение и подтверждение в новую ситуацию", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}], "competency_ids": ["A2-L01"], "coverage_claim": "TEXT_ROUTE_AUTHORED_AUDIO_AND_INDEPENDENT_QA_BLOCKED", "speaking_tasks": ["U-A2-017-I10", "U-A2-017-I13"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION", "FACT_SUBSTITUTION", "ASR_UNCERTAIN", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A2-017-I02", "U-A2-017-I03", "U-A2-017-I04", "U-A2-017-I05", "U-A2-017-I06", "U-A2-017-I07"], "listening_tasks": ["U-A2-017-I02", "U-A2-017-I03", "U-A2-017-I04", "U-A2-017-I05", "U-A2-017-I06", "U-A2-017-I11", "U-A2-017-I12"], "mastery_contract": {"open": "Every task-specific content criterion met independently, intelligible response; quote evidence per criterion", "closed": "At least80% on fresh controlled tasks, no uncorrected critical fact errors; project heuristic only", "listening": "Requires verified media, transcript hidden, play count logged", "retention": "Independent D7 and D28; one hint makes assisted evidence", "pronunciation": "Requires actual recording and listening; ASR text alone insufficient"}, "reading_texts_el": [], "vocabulary_items": [{"lemma": "το ραντεβού", "stress": "το ραντεβού", "example": "Έχω ραντεβού την Πέμπτη.", "inflection": "неизменяемое: τα ραντεβού", "meaning_ru": "согласованная встреча", "collocations": ["Έχω ραντεβού την Πέμπτη."]}, {"lemma": "διαθέσιμος", "stress": "διαθέσιμος", "example": "Υπάρχει διαθέσιμη ώρα;", "inflection": "διαθέσιμη / διαθέσιμο", "meaning_ru": "доступный", "collocations": ["Υπάρχει διαθέσιμη ώρα;"]}, {"lemma": "η τσάντα", "stress": "η τσάντα", "example": "Θα πάρω την μπλε τσάντα.", "inflection": "την τσάντα / οι τσάντες", "meaning_ru": "сумка", "collocations": ["Θα πάρω την μπλε τσάντα."]}], "diagnostic_item_ids": ["U-A2-017-I01"], "learning_objectives": ["Понять цель и участников", "Отличить предложение от итоговой договорённости", "Перенести уточнение и подтверждение в новую ситуацию"], "prerequisite_support": {"A1-L01": "Use primary unit from CONTENT_Production_Register_96.csv; if entry task fails, reteach prerequisite and retry on a fresh example before target assessment", "A2-V01": "Use primary unit from CONTENT_Production_Register_96.csv; if entry task fails, reteach prerequisite and retry on a fresh example before target assessment"}, "primary_competencies": ["A2-L01"], "estimated_active_minutes": 70}	3a22488a3d8063c3037bf5fe1ce3aadaccae1d26f21fef233adc6461c47e5e99	3143
U-A2-018	A2	218	Сообщения и инструкции: порядок, условие, следующий шаг	{A1-L02,A2-G07}	{}	{A2-L02}	{A2-L02}	70	{"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "COMPLETE_NOT_INDEPENDENT", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A2-018-RUBRIC"], "unit_id": "U-A2-018", "version": "0.1.0", "title_ru": "Сообщения и инструкции: порядок, условие, следующий шаг", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "В инструкции сначала найдите конечную цель: получить материалы, войти в помещение, отправить сообщение. Затем выделите действия в порядке выполнения. Πρώτα — сначала, μετά — затем, στο τέλος — в конце. Слова помогают, но слушайте содержание: сначала взять номер, затем ждать — не то же самое, что сразу подойти к стойке. Урок использует учебные процедуры, а не действующие правила учреждений.\\nПредпосылки — A1-L02 и связки A2-G07. Если ученик не различает время и место, сначала повторяем их на коротком сообщении. Затем вводим трёхшаговую инструкцию. В записи основные действия следуют в логичном порядке без сложных отступлений. Сделайте заметку глагол + объект: γράφω όνομα, παίρνω αριθμό, περιμένω. Запись не обязана повторять форму обращения сотрудника.\\nОтделяйте обязательный шаг от условного: Αν δεν λάβετε μήνυμα, τηλεφωνήστε μας означает звонить при отсутствии сообщения. Это не безусловное «всем звонить». Μην κλείσετε τη σελίδα запрещает закрывать страницу на данном этапе. Нельзя игнорировать отрицание, даже если глагол знаком. Мы не оцениваем юридическую правильность процедуры: только соблюдение условий вымышленной задачи.\\nПроверяйте исполнителя и предел инструкции. «Στείλτε μας το αρχείο» — действие адресата; «Θα σας στείλουμε μήνυμα» — обещание отправителя. Получение сообщения ещё не доказывает успешное окончание всех этапов, если это не сказано. Если часть звука потеряна, отметьте конкретный неизвестный шаг и запросите повтор. Не заполняйте пробел обычным, но не названным действием.\\nПосле двух прослушиваний перескажите последовательность другому человеку. Убираем несущественные приветствия, сохраняем порядок, отрицание и условие. Проверяем понимание также действием на безопасной имитации: разложить карточки шагов или выбрать следующее действие. Не выполнять реальные платежи и не вводить настоящие документы.\\nОбратная связь указывает первое место, где последовательность изменилась, затем просит исправить её самостоятельно. Случайная перестановка двух независимых действий не ошибка, если текст допускает оба порядка; наши задания с единственным ключом явно обозначают последовательность. На D7/D28 используются новые инструкции. До готового аудио чтение сценария остаётся отдельным подготовительным режимом.", "cefr_level": "A2", "time_basis": "AUTHOR_PLANNING_ESTIMATE_NOT_PILOTED", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Πρώτα γράψτε το όνομά σας.", "Μετά πάρτε έναν αριθμό.", "Περιμένετε να σας καλέσουμε.", "Αν δεν λάβετε μήνυμα, τηλεφωνήστε μας.", "Μην κλείσετε τη σελίδα."], "review_plan": {"days": [7, 28], "rule": "New stimulus, no model shown before attempt; assistance recorded; corrected answer alone is not independent retention", "item_ids": ["U-A2-018-I12", "U-A2-018-I13"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Κατανόηση προφορικού λόγου, paragraphs 1–2 (lines87–89)", "source_id": "CP08-A2", "checked_on": "2026-10-21", "claim_scope": "Bounded descriptor or phonological principle only; original examples, lesson sequence, rubrics and thresholds are not official"}], "active_recall": ["U-A2-018-I08"], "prerequisites": ["A1-L02", "A2-G07"], "reading_tasks": ["U-A2-018-I07"], "transfer_task": "U-A2-018-I11", "writing_tasks": ["U-A2-018-I09"], "assessment_map": [{"kind": "mcq", "item_id": "U-A2-018-I01", "objective": "Восстановить последовательность", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-A2-018-I02", "objective": "Восстановить последовательность", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_short", "item_id": "U-A2-018-I03", "objective": "Восстановить последовательность", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-A2-018-I04", "objective": "Восстановить последовательность", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-A2-018-I05", "objective": "Восстановить последовательность", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_mcq", "item_id": "U-A2-018-I06", "objective": "Сохранить условие и отрицание", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "read_mcq", "item_id": "U-A2-018-I07", "objective": "Сохранить условие и отрицание", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "short", "item_id": "U-A2-018-I08", "objective": "Сохранить условие и отрицание", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "open", "item_id": "U-A2-018-I09", "objective": "Сохранить условие и отрицание", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "speak", "item_id": "U-A2-018-I10", "objective": "Передать инструкцию и уточнить пробел", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-A2-018-I11", "objective": "Передать инструкцию и уточнить пробел", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-A2-018-I12", "objective": "Передать инструкцию и уточнить пробел", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "listen_open", "item_id": "U-A2-018-I13", "objective": "Передать инструкцию и уточнить пробел", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}], "competency_ids": ["A2-L02"], "coverage_claim": "TEXT_ROUTE_AUTHORED_AUDIO_AND_INDEPENDENT_QA_BLOCKED", "speaking_tasks": ["U-A2-018-I10"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION", "FACT_SUBSTITUTION", "ASR_UNCERTAIN", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A2-018-I02", "U-A2-018-I03", "U-A2-018-I04", "U-A2-018-I05", "U-A2-018-I06", "U-A2-018-I07"], "listening_tasks": ["U-A2-018-I02", "U-A2-018-I03", "U-A2-018-I04", "U-A2-018-I05", "U-A2-018-I06", "U-A2-018-I11", "U-A2-018-I12", "U-A2-018-I13"], "mastery_contract": {"open": "Every task-specific content criterion met independently, intelligible response; quote evidence per criterion", "closed": "At least80% on fresh controlled tasks, no uncorrected critical fact errors; project heuristic only", "listening": "Requires verified media, transcript hidden, play count logged", "retention": "Independent D7 and D28; one hint makes assisted evidence", "pronunciation": "Requires actual recording and listening; ASR text alone insufficient"}, "reading_texts_el": [], "vocabulary_items": [{"lemma": "πρώτα", "stress": "πρώτα", "example": "Πρώτα ανοίξτε το αρχείο.", "inflection": "наречие", "meaning_ru": "сначала", "collocations": ["Πρώτα ανοίξτε το αρχείο."]}, {"lemma": "μετά", "stress": "μετά", "example": "Μετά γράψτε το όνομά σας.", "inflection": "наречие в данном контексте", "meaning_ru": "затем", "collocations": ["Μετά γράψτε το όνομά σας."]}, {"lemma": "περιμένω", "stress": "περιμένω", "example": "Περιμένετε εδώ.", "inflection": "περιμένετε", "meaning_ru": "ждать", "collocations": ["Περιμένετε εδώ."]}], "diagnostic_item_ids": ["U-A2-018-I01"], "learning_objectives": ["Восстановить последовательность", "Сохранить условие и отрицание", "Передать инструкцию и уточнить пробел"], "prerequisite_support": {"A1-L02": "Use primary unit from CONTENT_Production_Register_96.csv; if entry task fails, reteach prerequisite and retry on a fresh example before target assessment", "A2-G07": "Use primary unit from CONTENT_Production_Register_96.csv; if entry task fails, reteach prerequisite and retry on a fresh example before target assessment"}, "primary_competencies": ["A2-L02"], "estimated_active_minutes": 70}	3cb44a0d9bb2404e6310a188e928dd7ec763c637f1a79b4520b4c2927f5e70c1	3144
U-A2-019	A2	219	Передать другому человеку условия короткого объявления	{A2-R01,A2-SP01}	{}	{A2-M01}	{A2-M01}	70	{"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "author_self_review": "COMPLETE_NOT_INDEPENDENT", "independent_linguistic_review": "PENDING"}, "status": "DRAFT", "rubrics": ["U-A2-019-RUBRIC"], "unit_id": "U-A2-019", "version": "0.1.0", "title_ru": "Передать другому человеку условия короткого объявления", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "Посредничество в этом уроке — помочь конкретному человеку понять нужные условия объявления. Это не перевод каждого слова и не свободное сочинение. Сначала выясните, что нужно адресату: время, место, цена, запись или список вещей. Затем найдите эти факты в тексте. Если друг хочет прийти с ребёнком, а возраст в объявлении не указан, нельзя обещать участие ребёнка.\\nПредпосылки — понимание короткого текста A2-R01 и связное простое высказывание A2-SP01. Входное задание проверяет выделение времени и места. Если ученик просто копирует весь текст, попросите убрать приветствия и оставить три нужных поля. При этом нельзя удалить ограничение μόνο, προθεσμία или условие εγγραφή απαραίτητη: коротко не означает неточно.\\nСравните «Είσοδος δωρεάν» и «Απαραίτητη η εγγραφή». Бесплатный вход не отменяет предварительной записи. «Φέρτε νερό» означает взять воду с собой, а не купить воду у организатора. «Σε περίπτωση βροχής» вводит условие; запасное место не заменяет основное при любой погоде. В наших объявлениях факты вымышлены, чтобы тренировать язык без актуальных юридических или организационных обещаний.\\nПодстройте передачу информации под адресата. Друг, который уже знает название мероприятия, может не нуждаться в повторе заголовка, но должен узнать время и необходимость записи. Незнакомому человеку полезно сначала назвать событие. Допустимы разные греческие формулировки: «Χρειάζεται εγγραφή» и «Πρέπει να κάνεις εγγραφή» передают одно условие. Не требуем дословной копии и оцениваем точность смысла.\\nНеизвестное обозначайте прямо: «Δεν γράφει πόσο διαρκεί». Если адресат спрашивает длительность, которой нет, предложите уточнить её у организатора, а не вычисляйте по похожим мероприятиям. Отделяйте факты объявления от вашего совета. «Καλύτερα να ρωτήσεις» — совет, а не новое условие участия.\\nПрактикуйте письменное сообщение, устный пересказ и ответ на уточняющий вопрос. Сначала разрешено выделять факты цветом; самостоятельный перенос выполняется с новым объявлением и без модели ответа. D7/D28 проверяют новые условия, в том числе отмену или перенос. Содержательные критерии оцениваются отдельно от произношения: для последнего нужна запись; чтение вслух известного текста не заменяет самостоятельный пересказ.", "cefr_level": "A2", "time_basis": "AUTHOR_PLANNING_ESTIMATE_NOT_PILOTED", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Η είσοδος είναι δωρεάν, αλλά χρειάζεται εγγραφή.", "Η συνάντηση είναι το Σάββατο στις δέκα.", "Φέρε νερό μαζί σου.", "Δεν γράφει πόσο διαρκεί.", "Αν βρέχει, θα συναντηθούμε στην αίθουσα."], "review_plan": {"days": [7, 28], "rule": "New stimulus, no model shown before attempt; assistance recorded; corrected answer alone is not independent retention", "item_ids": ["U-A2-019-I11", "U-A2-019-I12"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Κατανόηση προφορικού λόγου, paragraphs 1–2 (lines87–89)", "source_id": "CP08-A2", "checked_on": "2026-10-21", "claim_scope": "Bounded descriptor or phonological principle only; original examples, lesson sequence, rubrics and thresholds are not official"}], "active_recall": ["U-A2-019-I06"], "prerequisites": ["A2-R01", "A2-SP01"], "reading_tasks": ["U-A2-019-I01", "U-A2-019-I02", "U-A2-019-I05", "U-A2-019-I09"], "transfer_task": "U-A2-019-I10", "writing_tasks": ["U-A2-019-I04", "U-A2-019-I06", "U-A2-019-I07", "U-A2-019-I10", "U-A2-019-I11"], "assessment_map": [{"kind": "read_mcq", "item_id": "U-A2-019-I01", "objective": "Выделить нужные адресату условия", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "read_mcq", "item_id": "U-A2-019-I02", "objective": "Выделить нужные адресату условия", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "short", "item_id": "U-A2-019-I03", "objective": "Выделить нужные адресату условия", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "open", "item_id": "U-A2-019-I04", "objective": "Выделить нужные адресату условия", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "read_mcq", "item_id": "U-A2-019-I05", "objective": "Сохранить обязательность и неизвестность", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "open", "item_id": "U-A2-019-I06", "objective": "Сохранить обязательность и неизвестность", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "open", "item_id": "U-A2-019-I07", "objective": "Сохранить обязательность и неизвестность", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "speak", "item_id": "U-A2-019-I08", "objective": "Сохранить обязательность и неизвестность", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "read_mcq", "item_id": "U-A2-019-I09", "objective": "Передать новый текст своими словами", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "open", "item_id": "U-A2-019-I10", "objective": "Передать новый текст своими словами", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "open", "item_id": "U-A2-019-I11", "objective": "Передать новый текст своими словами", "audio_required": false, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}, {"kind": "speak", "item_id": "U-A2-019-I12", "objective": "Передать новый текст своими словами", "audio_required": true, "mastery_evidence": "Independent attempt + task-specific criteria; no credit for transcript reading as listening"}], "competency_ids": ["A2-M01"], "coverage_claim": "TEXT_ROUTE_AUTHORED_AUDIO_AND_INDEPENDENT_QA_BLOCKED", "speaking_tasks": ["U-A2-019-I08", "U-A2-019-I12"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION", "FACT_SUBSTITUTION", "ASR_UNCERTAIN", "ASSISTED_NOT_INDEPENDENT"], "guided_practice": ["U-A2-019-I02", "U-A2-019-I03", "U-A2-019-I04", "U-A2-019-I05", "U-A2-019-I09"], "listening_tasks": [], "mastery_contract": {"open": "Every task-specific content criterion met independently, intelligible response; quote evidence per criterion", "closed": "At least80% on fresh controlled tasks, no uncorrected critical fact errors; project heuristic only", "listening": "Requires verified media, transcript hidden, play count logged", "retention": "Independent D7 and D28; one hint makes assisted evidence", "pronunciation": "Requires actual recording and listening; ASR text alone insufficient"}, "reading_texts_el": ["Περίπατος στη γειτονιά. Σάββατο, 10:00. Συνάντηση μπροστά στη βιβλιοθήκη. Συμμετοχή δωρεάν. Εγγραφή μέχρι την Πέμπτη. Φέρτε νερό."], "vocabulary_items": [{"lemma": "η εγγραφή", "stress": "η εγγραφή", "example": "Χρειάζεται εγγραφή.", "inflection": "την εγγραφή / οι εγγραφές", "meaning_ru": "запись, регистрация", "collocations": ["Χρειάζεται εγγραφή."]}, {"lemma": "δωρεάν", "stress": "δωρεάν", "example": "Η είσοδος είναι δωρεάν.", "inflection": "наречие", "meaning_ru": "бесплатно", "collocations": ["Η είσοδος είναι δωρεάν."]}, {"lemma": "μαζί", "stress": "μαζί", "example": "Φέρε νερό μαζί σου.", "inflection": "неизменяемое", "meaning_ru": "вместе, с собой в сочетании", "collocations": ["Φέρε νερό μαζί σου."]}], "diagnostic_item_ids": ["U-A2-019-I01"], "learning_objectives": ["Выделить нужные адресату условия", "Сохранить обязательность и неизвестность", "Передать новый текст своими словами"], "prerequisite_support": {"A2-R01": "Use primary unit from CONTENT_Production_Register_96.csv; if entry task fails, reteach prerequisite and retry on a fresh example before target assessment", "A2-SP01": "Use primary unit from CONTENT_Production_Register_96.csv; if entry task fails, reteach prerequisite and retry on a fresh example before target assessment"}, "primary_competencies": ["A2-M01"], "estimated_active_minutes": 70}	884d56e7ddd0a2569668764371fca45b5cd5dfd9d44e0e350b2a088107a0d9a8	3145
U-A2-020	A2	220	Приглашение, отказ, смягчённая просьба и исправление	{A1-PR01,A2-SI01}	{}	{A2-PR01}	{A2-PR01}	65	{"qa": {"status": "AUTHORED_DRAFT", "publishable": false, "human_review": "NOT_REVIEWED", "source_review": "BOUNDED_SOURCE_ONLY", "answer_key_review": "AUTHOR_ONLY", "linguistic_review": "AUTHOR_ONLY"}, "rubrics": ["U-A2-020-RUBRIC"], "unit_id": "U-A2-020", "version": "0.1.0", "title_ru": "Приглашение, отказ, смягчённая просьба и исправление", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "theory_ru": "В приглашении нужны действие, время и место: «Θέλεις να πάμε για καφέ την Κυριακή;». Адресат должен понимать, какое решение от него требуется. Между друзьями естественны θέλεις, μπορείς, πάμε; с незнакомым человеком или в более официальном контакте можно выбрать θα θέλατε, μπορείτε. Множественное число здесь может выражать вежливое обращение к одному человеку. Не переключайте εσύ/εσείς внутри короткого сообщения без причины.\\nСогласие должно прояснять договорённость. «Ναι, ευχαρίστως. Στις έξι έξω από το μουσείο;» не только выражает желание, но и проверяет детали. «Ίσως» не является подтверждённым согласием. Если план зависит от работы или транспорта, прямо скажите, когда сможете ответить. Не обещайте прийти, если только собираетесь проверить возможность.\\nОтказывать можно кратко и доброжелательно: благодарность → ясная невозможность → при желании короткая причина или другой вариант. «Ευχαριστώ για την πρόσκληση, αλλά δεν μπορώ το Σάββατο. Μπορώ την Κυριακή». Причина не обязательна и не должна раскрывать личные сведения. Не нужно придумывать болезнь или семейную историю ради вежливости. Предложение другого времени полезно, когда вы действительно хотите встретиться.\\nПросьба отличается от приказа. «Μπορείτε να μιλήσετε λίγο πιο αργά, παρακαλώ;» даёт собеседнику понятное действие. «Θα ήθελα…» — удобная вежливая формула; здесь используем её как знакомый образец, не изучаем всю систему условных форм. Выбор одного слова παρακαλώ сам по себе не гарантирует уместного тона: содержание и ситуация тоже важны.\\nИсправляя ошибку в деталях, сначала обозначьте поправку: «Συγγνώμη, εννοούσα την Πέμπτη, όχι την Τρίτη». Затем повторите правильную договорённость целиком. Это надёжнее, чем сказать только «όχι», после которого непонятно, что отменено. Если ошибку сделал собеседник, можно мягко проверить: «Στις επτά είπαμε, σωστά;». Не приписывайте ему плохих намерений.\\nПеред уроком проверьте простое обращение и обмен временем из A1-PR01/A2-SI01. После образцов закройте их и создайте своё приглашение, отказ и уточнение. В устном задании оценивается реальная запись; текст показывает содержание, но не интонацию. Наша цель — ясная взаимная договорённость, а не единственный обязательный шаблон.", "cefr_level": "A2", "time_basis": "AUTHOR_SESSION_PLANNING_NOT_PILOTED", "examples_el": ["Θέλεις να πάμε μια βόλτα;", "Ευχαριστώ, αλλά δεν μπορώ σήμερα.", "Μπορείτε να το επαναλάβετε, παρακαλώ;", "Συγγνώμη, εννοούσα στις επτά, όχι στις έξι."], "review_plan": {"D7": ["U-A2-020-I10"], "D28": ["U-A2-020-I11"], "days": [7, 28], "policy": "First attempt without model or original text unless task provides new source. Assisted success does not close retention; failures schedule focused explanation then new-context retry.", "item_ids": ["U-A2-020-I10", "U-A2-020-I11"]}, "source_refs": [{"anchor": "Written production100–101; oral interaction104–105", "source_id": "CP08-A2", "checked_on": "2026-10-22", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "active_recall": ["U-A2-020-I07", "U-A2-020-I08"], "prerequisites": ["A1-PR01", "A2-SI01"], "reading_tasks": ["U-A2-020-I02", "U-A2-020-I05"], "transfer_task": "U-A2-020-I09", "writing_tasks": ["U-A2-020-I01", "U-A2-020-I07", "U-A2-020-I11"], "assessment_map": [{"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-A2-020-I01", "U-A2-020-I02", "U-A2-020-I04"], "objective": "Различать приглашение, согласие, отказ и просьбу"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-A2-020-I03", "U-A2-020-I05", "U-A2-020-I06", "U-A2-020-I10"], "objective": "Выбирать обращение и исправлять детали без двусмысленности"}, {"mastery": "Independent task-critical criteria plus transfer and delayed evidence; no score can certify whole CEFR level", "item_ids": ["U-A2-020-I07", "U-A2-020-I08", "U-A2-020-I09", "U-A2-020-I11"], "objective": "Самостоятельно согласовать или вежливо отклонить встречу"}], "competency_ids": ["A2-PR01"], "speaking_tasks": ["U-A2-020-I08", "U-A2-020-I09", "U-A2-020-I10"], "entry_probe_ids": ["U-A2-020-I01"], "errors_taxonomy": ["COMPREHENSION", "CONTENT_OMISSION"], "guided_practice": ["U-A2-020-I02", "U-A2-020-I03", "U-A2-020-I04", "U-A2-020-I05", "U-A2-020-I06"], "listening_tasks": [], "modality_status": "AUDIO_PENDING", "vocabulary_items": [{"lemma": "η πρόσκληση", "stress": "η πρόσκληση", "example": "Ευχαριστώ για την πρόσκληση.", "inflection": "της πρόσκλησης; οι προσκλήσεις", "collocations": ["ευχαριστώ για την πρόσκληση"]}, {"lemma": "ευχαρίστως", "stress": "ευχαρίστως", "example": "Ναι, ευχαρίστως θα έρθω.", "inflection": "άκλιτο", "collocations": ["ναι, ευχαρίστως"]}, {"lemma": "εννοώ", "stress": "εννοώ", "example": "Εννοούσα αύριο, όχι σήμερα.", "inflection": "εννοούσα", "collocations": ["εννοώ την Πέμπτη"]}], "learning_objectives": ["Различать приглашение, согласие, отказ и просьбу", "Выбирать обращение и исправлять детали без двусмысленности", "Самостоятельно согласовать или вежливо отклонить встречу"], "prerequisite_policy": "Diagnose before instruction; failure routes to primary unit(s) from96 register. Authored prerequisite is not evidence of learner mastery. Retry with fresh example.", "primary_competencies": ["A2-PR01"], "estimated_active_minutes": 65}	fbcd81e145b77e2753fc76117ec4f11c08d1903e125a5c433e858e0579450634	3146
U-B1-001	B1	301	Что будет уже сделано к сроку: συντελεσμένος μέλλοντας	{A2-G03,A2-G05}	{}	{B1-G05,B1-G03,B1-W01}	{B1-G05}	45	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B1-001-RUBRIC"], "unit_id": "U-B1-001", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-B1-001-I02", "U-B1-001-I03", "U-B1-001-I04", "U-B1-001-I05", "U-B1-001-I06", "U-B1-001-I07"], "reception": ["U-B1-001-I08", "U-B1-001-I09", "U-B1-001-I10", "U-B1-001-I11"], "retention": ["U-B1-001-I15", "U-B1-001-I16", "U-B1-001-I17"], "diagnostic": ["U-B1-001-I01"], "production": ["U-B1-001-I12", "U-B1-001-I13", "U-B1-001-I14"]}, "title_ru": "Что будет уже сделано к сроку: συντελεσμένος μέλλοντας", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Форма θα έχω + неизменяемая форма вроде γράψει показывает результат, завершённый к будущему ориентиру: Μέχρι την Παρασκευή θα έχω γράψει την αναφορά. Изменяется έχω: θα έχω, θα έχεις, θα έχει, θα έχουμε, θα έχετε, θα έχουν. Слово γράψει здесь не согласуется с лицом или числом. Та же неизменяемая часть встречается в έχω γράψει и είχα γράψει, но временная точка различается: результат сейчас, до прошлого момента, до будущего момента.\\n\\nСравните три взгляда на одну работу. Αύριο στις έξι θα γράφω την αναφορά — в шесть работа будет в процессе. Αύριο θα γράψω την αναφορά — действие представлено как целое. Μέχρι αύριο στις έξι θα έχω γράψει την αναφορά — к шести результат будет достигнут. Простое будущее тоже может употребляться со сроком. Поэтому наличие μέχρι не делает остальные формы всегда неграмматичными: в упражнениях ниже прямо требуется подчеркнуть предшествующее завершение.\\n\\nЧастотные сочетания: θα έχω τελειώσει, θα έχουμε στείλει, θα έχει φύγει. Отрицание: δεν θα έχω τελειώσει. Вопрос: Θα έχεις στείλει το μήνυμα μέχρι τότε; Не нужно добавлять второе θα перед неизменяемой частью. В учебных переговорах отделяйте подтверждённый срок от предположения: Ελπίζω ότι θα έχω τελειώσει… выражает надежду, а не гарантию. Узел дополняет исходный B1-G05: это новая явная микроцель, а не молчаливая замена perfect/pluperfect.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Μέχρι τις οκτώ θα έχω τελειώσει τη δουλειά.", "Όταν φτάσεις, θα έχουμε ετοιμάσει το φαγητό.", "Αύριο στις οκτώ θα δουλεύω ακόμη.", "Αύριο θα στείλω την αίτηση.", "Δεν θα έχουν φύγει μέχρι τότε."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B1-001-I15", "U-B1-001-I16", "U-B1-001-I17"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF10; V226 печатные290/292, V234 PDF30", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Goal-oriented cooperation / correspondence, B1; грамматическая последовательность по историческому AUTH", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "PDF30, ответы к290–291", "source_id": "V234", "checked_on": "2026-10-13", "claim_scope": "Подтверждает присутствие трёх будущих форм в ΚΛΙΚ B1", "evidence_type": "PUBLISHER_PREVIEW"}], "active_recall": ["U-B1-001-I06", "U-B1-001-I07"], "prerequisites": ["A2-G03", "A2-G05"], "reading_tasks": ["U-B1-001-I08", "U-B1-001-I09"], "transfer_task": "U-B1-001-I14", "writing_tasks": ["U-B1-001-I12"], "competency_ids": ["B1-G05", "B1-G03", "B1-W01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B1-001-I13"], "errors_taxonomy": ["VERB_ASPECT", "VERB_TENSE", "CONTENT_OMISSION"], "guided_practice": ["U-B1-001-I02", "U-B1-001-I03", "U-B1-001-I04", "U-B1-001-I05"], "listening_tasks": ["U-B1-001-I10", "U-B1-001-I11"], "learning_outcome": "Выразить ожидаемый результат к будущему сроку через θα έχω + совершенную форму", "vocabulary_items": [{"lemma": "τελειώνω", "stress": "τελειώνω", "example": "Θα έχω τελειώσει την αναφορά.", "inflection": "τελείωσα; έχω τελειώσει", "meaning_ru": "заканчивать", "collocations": ["τελειώνω την αναφορά"]}, {"lemma": "προθεσμία", "stress": "προθεσμία", "example": "Η προθεσμία είναι την Παρασκευή.", "inflection": "η προθεσμία, οι προθεσμίες", "meaning_ru": "крайний срок", "collocations": ["μέχρι την προθεσμία"]}, {"lemma": "στέλνω", "stress": "στέλνω", "example": "Θα έχουμε στείλει την αίτηση.", "inflection": "έστειλα; έχω στείλει", "meaning_ru": "отправлять", "collocations": ["στέλνω την αίτηση"]}, {"lemma": "μέχρι τότε", "stress": "μέχρι τότε", "example": "Μέχρι τότε θα έχω επιστρέψει.", "inflection": "наречное сочетание", "meaning_ru": "к тому моменту", "collocations": ["θα έχω τελειώσει μέχρι τότε"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B1-001-I01"], "learning_objectives": ["Выразить ожидаемый результат к будущему сроку через θα έχω + совершенную форму", "Различить процесс, целое событие и достигнутый к сроку результат", "Согласовать новый срок с проверяемым результатом"], "microcompetency_ids": ["U-B1-001-MC01", "U-B1-001-MC02", "U-B1-001-MC03"], "primary_competencies": ["B1-G05"], "learner_data_included": false, "estimated_active_minutes": 45}	3a4e2d4f441f4ebc5733cedd140b0927ced4573d7