U-B1-002	B1	302	Фон и событие: παρατατικός и αόριστος	{A2-G03}	{}	{B1-G03,A2-G04}	{B1-G03}	45	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B1-002-RUBRIC"], "unit_id": "U-B1-002", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-B1-002-I02", "U-B1-002-I03", "U-B1-002-I04", "U-B1-002-I05", "U-B1-002-I06"], "reception": ["U-B1-002-I07", "U-B1-002-I08", "U-B1-002-I09", "U-B1-002-I10"], "retention": ["U-B1-002-I14", "U-B1-002-I15", "U-B1-002-I16"], "diagnostic": ["U-B1-002-I01"], "production": ["U-B1-002-I11", "U-B1-002-I12", "U-B1-002-I13"]}, "title_ru": "Фон и событие: παρατατικός и αόριστος", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "В рассказе выбор вида показывает, как говорящий представляет действие. Παρατατικός описывает разворачивающийся процесс, повторение или фон: Διάβαζα όταν χτύπησε το τηλέφωνο. Αόριστος представляет событие целиком: Διάβασα το μήνυμα και απάντησα. Длительность сама по себе не определяет время: Έμεινα εκεί τρία χρόνια охватывает весь завершённый период, хотя он длинный. Κάθε μέρα часто поддерживает повторительный фон, но не заменяет понимания контекста.\\nДля γράφω сравните έγραφα и έγραψα; для διαβάζω — διάβαζα и διάβασα. Не образуйте все формы заменой одной буквы: έβλεπα/είδα имеют разные основы. В прошедшем множественного γράφαμε/γράψαμε начальное έ- обычно отсутствует, поскольку меняется место ударения. Учите звучащую форму, а не механически добавляйте аугмент.\\nВ предложении Όταν έφτασα, η Άννα μαγείρευε приготовление уже шло в момент прихода; оно не объявлено завершённым. В Η Άννα μαγείρεψε και έφυγε представлены два целых события. Фон не означает, что действие никогда не закончилось: просто конец не находится в фокусе. Для проверки спросите: мы описываем обстановку или продвигаем цепочку событий? В собственном рассказе допустимы разные ракурсы при сохранении смысла. Ключ с единственным ответом используйте только там, где ракурс явно задан.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Περίμενα όταν άρχισε η βροχή.", "Περίμενα μισή ώρα και μετά έφυγα.", "Κάθε βράδυ έβλεπα τους φίλους μου.", "Χτες είδα τη Δανάη μόνο για λίγο."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B1-002-I14", "U-B1-002-I15", "U-B1-002-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF9–11", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction B1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-B1-002-I05", "U-B1-002-I06"], "prerequisites": ["A2-G03"], "reading_tasks": ["U-B1-002-I07", "U-B1-002-I08"], "transfer_task": "U-B1-002-I13", "writing_tasks": ["U-B1-002-I11"], "competency_ids": ["B1-G03", "A2-G04"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B1-002-I12"], "errors_taxonomy": ["ASPECT", "TENSE", "NARRATIVE_SEQUENCE"], "guided_practice": ["U-B1-002-I02", "U-B1-002-I03", "U-B1-002-I04"], "listening_tasks": ["U-B1-002-I09", "U-B1-002-I10"], "learning_outcome": "Различить процессуальный фон и целое событие в рассказе", "vocabulary_items": [{"lemma": "γράφω", "stress": "γράφω", "example": "Έγραφα όταν ήρθε η Άννα.", "inflection": "έγραφα / έγραψα; γράφαμε / γράψαμε", "meaning_ru": "писать", "collocations": ["γράφω ένα μήνυμα"]}, {"lemma": "βλέπω", "stress": "βλέπω", "example": "Είδα τον Λεωνίδα.", "inflection": "έβλεπα / είδα", "meaning_ru": "видеть", "collocations": ["βλέπω έναν φίλο"]}, {"lemma": "φτάνω", "stress": "φτάνω", "example": "Όταν έφτασα, έβρεχε.", "inflection": "έφτανα / έφτασα", "meaning_ru": "прибывать", "collocations": ["φτάνω στον σταθμό"]}, {"lemma": "βρέχει", "stress": "βρέχει", "example": "Έβρεχε όλο το πρωί.", "inflection": "έβρεχε / έβρεξε", "meaning_ru": "идёт дождь", "collocations": ["άρχισε να βρέχει"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B1-002-I01"], "learning_objectives": ["Различить процессуальный фон и целое событие в рассказе", "Образовать έγραφα/έγραψα и έβλεπα/είδα по заданному ракурсу", "Рассказать о новом происшествии с фоном, событием и реакцией"], "level_override_note": "A2-G04 is legacy macro ID only. Systematic teaching placed at B1 according to v3/V201 PDF10; original registry unchanged.", "microcompetency_ids": ["U-B1-002-MC01", "U-B1-002-MC02", "U-B1-002-MC03"], "primary_competencies": ["B1-G03"], "learner_data_included": false, "estimated_active_minutes": 45}	690f5a19a037d7e3ec2b858241dd5ad2c4bb58edc6048f2c4263cedc9e030788	3148
U-B1-003	B1	303	Передать сообщение и вопрос: ότι, αν, πότε	{B1-G03,A2-G05}	{}	{B1-G09}	{B1-G09}	45	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B1-003-RUBRIC"], "unit_id": "U-B1-003", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-B1-003-I02", "U-B1-003-I03", "U-B1-003-I04", "U-B1-003-I05", "U-B1-003-I06"], "reception": ["U-B1-003-I07", "U-B1-003-I08", "U-B1-003-I09", "U-B1-003-I10"], "retention": ["U-B1-003-I14", "U-B1-003-I15", "U-B1-003-I16"], "diagnostic": ["U-B1-003-I01"], "production": ["U-B1-003-I11", "U-B1-003-I12", "U-B1-003-I13"]}, "title_ru": "Передать сообщение и вопрос: ότι, αν, πότε", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Косвенная речь передаёт содержание, не сохраняя реплику как цитату. Сообщение вводится ότι/πως: Η Ελένη είπε ότι δεν μπορούσε να έρθει. Вопрос да/нет вводится αν: Με ρώτησε αν είχα χρόνο. Вопрос со специальным словом сохраняет его: Ρώτησε πότε αρχίζει το μάθημα. Αν здесь означает «ли», а не условие «если».\\nМестоимения и указания времени выбираются по точке зрения рассказчика. Εγώ θα έρθω αύριο, сказанное Марией в понедельник, во вторничном отчёте может стать Η Μαρία είπε ότι θα ερχόταν σήμερα. Но это не автоматическое преобразование каждого αύριο в την επόμενη μέρα: при пересказе в тот же день αύριο может оставаться точным. В греческом нет обязательного механического согласования времён по английской схеме. Решает реальная временная связь: Μου είπε ότι μένει στην Πάτρα естественно, если проживание актуально.\\nИзменение лица зависит от того, кто именно говорит. Με ρώτησε: «Έχεις χρόνο;» → Με ρώτησε αν είχα χρόνο. Сохраняйте источник и степень уверенности: είπε, ρώτησε, πρότεινε — разные действия. Нельзя превращать вопрос «Будет ли готово?» в обещание «Будет готово». После пересказа адресат должен различить подтверждённый факт, вопрос и предложение.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Η Νίκη είπε ότι μένει στην Πάτρα.", "Με ρώτησε αν είχα χρόνο.", "Ρώτησα πότε αρχίζει το μάθημα.", "Ο Στέλιος είπε πως θα μας τηλεφωνήσει."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B1-003-I14", "U-B1-003-I15", "U-B1-003-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF9–11", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction B1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-B1-003-I05", "U-B1-003-I06"], "prerequisites": ["B1-G03", "A2-G05"], "reading_tasks": ["U-B1-003-I07", "U-B1-003-I08"], "transfer_task": "U-B1-003-I13", "writing_tasks": ["U-B1-003-I11"], "competency_ids": ["B1-G09"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B1-003-I12"], "errors_taxonomy": ["INDIRECT_SPEECH", "REFERENCE", "UNSUPPORTED_INFERENCE"], "guided_practice": ["U-B1-003-I02", "U-B1-003-I03", "U-B1-003-I04"], "listening_tasks": ["U-B1-003-I09", "U-B1-003-I10"], "learning_outcome": "Передать сообщение с ότι/πως и общий вопрос с αν", "vocabulary_items": [{"lemma": "ρωτάω", "stress": "ρωτάω", "example": "Με ρώτησε αν μπορώ.", "inflection": "ρώτησα, ρώτησε", "meaning_ru": "спрашивать", "collocations": ["ρωτάω αν"]}, {"lemma": "λέω", "stress": "λέω", "example": "Είπε ότι θα έρθει.", "inflection": "είπα, είπε", "meaning_ru": "сказать", "collocations": ["λέω ότι"]}, {"lemma": "επιβεβαιώνω", "stress": "επιβεβαιώνω", "example": "Δεν επιβεβαίωσε την ώρα.", "inflection": "επιβεβαίωσα", "meaning_ru": "подтверждать", "collocations": ["επιβεβαιώνω την ώρα"]}, {"lemma": "προτείνω", "stress": "προτείνω", "example": "Πρότεινε να περιμένουμε.", "inflection": "πρότεινα", "meaning_ru": "предлагать", "collocations": ["προτείνω μια λύση"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B1-003-I01"], "learning_objectives": ["Передать сообщение с ότι/πως и общий вопрос с αν", "Сохранить референтов и точку отсчёта времени при пересказе", "Не превращать вопрос или неподтверждённый план в факт"], "microcompetency_ids": ["U-B1-003-MC01", "U-B1-003-MC02", "U-B1-003-MC03"], "primary_competencies": ["B1-G09"], "learner_data_included": false, "estimated_active_minutes": 45}	dc8cbe52e55290f3092e793d53d3aa0715ace882bd0f4e2dcfd59659131a579f	3149
U-B1-004	B1	304	Кому и что: двойные клитики	{A2-G02,A2-G06,A2-G07}	{}	{B1-G02,B1-G06}	{B1-G02,B1-G06}	45	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B1-004-RUBRIC"], "unit_id": "U-B1-004", "version": "0.1.1", "sections": {"theory": "theory_ru", "practice": ["U-B1-004-I02", "U-B1-004-I03", "U-B1-004-I04", "U-B1-004-I05", "U-B1-004-I06"], "reception": ["U-B1-004-I07", "U-B1-004-I08", "U-B1-004-I09", "U-B1-004-I10"], "retention": ["U-B1-004-I14", "U-B1-004-I15", "U-B1-004-I16"], "diagnostic": ["U-B1-004-I01"], "production": ["U-B1-004-I11", "U-B1-004-I12", "U-B1-004-I13"]}, "title_ru": "Кому и что: двойные клитики", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Безударные местоимения заменяют уже понятные из контекста объекты. В Η Άννα έδωσε το βιβλίο στον Πέτρο прямой объект — βιβλίο, получатель — Πέτρος. Пересказ: Του το έδωσε. В обычном личном предложении сначала идёт родительный косвенного объекта μου/σου/του/της/μας/σας/τους, затем винительный τον/την/το/τους/τις/τα, затем глагол. Артикль и клитика могут выглядеть одинаково, но выполняют разные функции.\\nВ положительном повелительном местоимения стоят после глагола: Δώσε μου το βιβλίο → Δώσ’ μου το. Для ясного учебного образца используем Πες μου την ώρα → Πες μου την. Некоторые сочетания после императива допускают вариацию порядка; этот урок не объявляет единственный шаблон универсальным. Отрицательное побуждение строится с μη(ν) и формой с местоимениями перед глаголом: Μη μου το δώσεις ακόμη. Не переносите положительный порядок автоматически.\\nПолезно начать с надёжных контрастов: Μου το δίνεις / Να μου το δώσεις / Μη μου το δώσεις. В πλήρη форме объясните, кому и что передают; только затем сокращайте. При двух возможных референтах лучше повторить имя или предмет. У местоимений после ударного глагола возможны дополнительные ударения, например Δώσε μού το. Орфографическая вычитка таких сочетаний обязательна; предпочтительный учебный пример здесь Δώσ’ μου το избегает спорного обобщения.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Του το έστειλα χτες.", "Να μου το δώσεις αύριο.", "Μη μου το δώσεις ακόμη.", "Δώσ’ μου το, παρακαλώ."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B1-004-I14", "U-B1-004-I15", "U-B1-004-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF9–11", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction B1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-B1-004-I05", "U-B1-004-I06"], "prerequisites": ["A2-G02", "A2-G06", "A2-G07"], "reading_tasks": ["U-B1-004-I07", "U-B1-004-I08"], "transfer_task": "U-B1-004-I13", "writing_tasks": ["U-B1-004-I11"], "competency_ids": ["B1-G02", "B1-G06"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B1-004-I12"], "errors_taxonomy": ["CLITIC_ORDER", "REFERENCE", "ACCENTUATION"], "guided_practice": ["U-B1-004-I02", "U-B1-004-I03", "U-B1-004-I04"], "listening_tasks": ["U-B1-004-I09", "U-B1-004-I10"], "learning_outcome": "Заменить ясные прямой и косвенный объекты двумя клитиками", "vocabulary_items": [{"lemma": "δίνω", "stress": "δίνω", "example": "Της το έδωσα.", "inflection": "έδωσα; δώσε", "meaning_ru": "давать", "collocations": ["δίνω κάτι σε κάποιον"]}, {"lemma": "στέλνω", "stress": "στέλνω", "example": "Σας το έστειλα.", "inflection": "έστειλα; στείλε", "meaning_ru": "отправлять", "collocations": ["στέλνω ένα αρχείο"]}, {"lemma": "επιστρέφω", "stress": "επιστρέφω", "example": "Θα σου το επιστρέψω.", "inflection": "επέστρεψα; επιστρέφω κάτι", "meaning_ru": "возвращать", "collocations": ["επιστρέφω το βιβλίο"]}, {"lemma": "παραλήπτης", "stress": "παραλήπτης", "example": "Ποιος είναι ο παραλήπτης;", "inflection": "ο παραλήπτης, οι παραλήπτες", "meaning_ru": "получатель", "collocations": ["το όνομα του παραλήπτη"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B1-004-I01"], "learning_objectives": ["Заменить ясные прямой и косвенный объекты двумя клитиками", "Различить положение клитик в личной форме, побуждении и запрете", "Исправить получателя предмета в новом диалоге"], "microcompetency_ids": ["U-B1-004-MC01", "U-B1-004-MC02", "U-B1-004-MC03"], "primary_competencies": ["B1-G02", "B1-G06"], "learner_data_included": false, "estimated_active_minutes": 45}	008b452418c64fdf540c9a1a493107cabb56d47235a426978d10ace3f87886bc	3150
U-B1-005	B1	305	Родительный множественного: формы и связи	{A2-G01,A1-G03}	{}	{B1-G01}	{B1-G01}	45	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B1-005-RUBRIC"], "unit_id": "U-B1-005", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-B1-005-I02", "U-B1-005-I03", "U-B1-005-I04", "U-B1-005-I05", "U-B1-005-I06"], "reception": ["U-B1-005-I07", "U-B1-005-I08", "U-B1-005-I09", "U-B1-005-I10"], "retention": ["U-B1-005-I14", "U-B1-005-I15", "U-B1-005-I16"], "diagnostic": ["U-B1-005-I01"], "production": ["U-B1-005-I11", "U-B1-005-I12", "U-B1-005-I13"]}, "title_ru": "Родительный множественного: формы и связи", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Родительный множественного имеет общий артикль των, но форма существительного требует знания модели и ударения. Сравним οι φίλοι → των φίλων, οι μαθητές → των μαθητών, τα παιδιά → των παιδιών, οι πόλεις → των πόλεων. Нельзя просто добавить -ων к видимой форме именительного и сохранить любое ударение. Полезно учить пару целиком: οι πόλεις / των πόλεων.\\nВ группе η πρόταση των μαθητών главное слово — πρόταση, а родительный указывает, чья это идея. Сказуемое согласуется с главным словом: Η πρόταση των μαθητών είναι ενδιαφέρουσα. Во множественном Οι προτάσεις των μαθητών είναι ενδιαφέρουσες. Близость μαθητών к глаголу не делает его подлежащим. Прилагательное внутри зависимой группы тоже согласуется: των νέων μαθητών; его окончание не следует за πρόταση.\\nРодительный выражает не только принадлежность вещи человеку. В το κέντρο της πόλης он связывает части пространственного описания; в η προστασία των παιδιών обозначает объект заботы. Значение устанавливается всей группой, поэтому русский перевод с «у» не является универсальным.\\nДля самостоятельного письма надёжнее применить знакомую модель, чем создавать незнакомую форму по аналогии. При неизвестном исключении допустима временная перефразировка и проверка словаря. Здесь отрабатываются четыре частотные модели; нерегулярные γεγονός/προϊόν и прилагательные на -ής изучаются в отдельном B2 блоке.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Η πρόταση των μαθητών είναι ενδιαφέρουσα.", "Τα παιχνίδια των παιδιών είναι εδώ.", "Συγκρίνουμε τα κέντρα των πόλεων.", "Οι φίλοι των νέων μαθητών περιμένουν έξω."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B1-005-I14", "U-B1-005-I15", "U-B1-005-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF9–11", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction B1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-B1-005-I05", "U-B1-005-I06"], "prerequisites": ["A2-G01", "A1-G03"], "reading_tasks": ["U-B1-005-I07", "U-B1-005-I08"], "transfer_task": "U-B1-005-I13", "writing_tasks": ["U-B1-005-I11"], "competency_ids": ["B1-G01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B1-005-I12"], "errors_taxonomy": ["GENITIVE_PLURAL", "AGREEMENT", "ACCENTUATION"], "guided_practice": ["U-B1-005-I02", "U-B1-005-I03", "U-B1-005-I04"], "listening_tasks": ["U-B1-005-I09", "U-B1-005-I10"], "learning_outcome": "Образовать родительный множественного четырёх изученных моделей", "vocabulary_items": [{"lemma": "μαθητής", "stress": "μαθητής", "example": "Ακούσαμε την πρόταση των μαθητών.", "inflection": "ο μαθητής, οι μαθητές, των μαθητών", "meaning_ru": "ученик", "collocations": ["πρόταση των μαθητών"]}, {"lemma": "παιδί", "stress": "παιδί", "example": "Τα παιχνίδια των παιδιών είναι εδώ.", "inflection": "το παιδί, τα παιδιά, των παιδιών", "meaning_ru": "ребёнок", "collocations": ["παιχνίδια των παιδιών"]}, {"lemma": "πόλη", "stress": "πόλη", "example": "Μελετάμε τα κέντρα των πόλεων.", "inflection": "η πόλη, οι πόλεις, των πόλεων", "meaning_ru": "город", "collocations": ["κέντρα των πόλεων"]}, {"lemma": "πρόταση", "stress": "πρόταση", "example": "Η πρόταση είναι σαφής.", "inflection": "η πρόταση, οι προτάσεις, των προτάσεων", "meaning_ru": "предложение", "collocations": ["εξέταση των προτάσεων"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B1-005-I01"], "learning_objectives": ["Образовать родительный множественного четырёх изученных моделей", "Найти главное слово группы и согласовать с ним сказуемое", "Употребить родительный в новом сообщении"], "microcompetency_ids": ["U-B1-005-MC01", "U-B1-005-MC02", "U-B1-005-MC03"], "primary_competencies": ["B1-G01"], "learner_data_included": false, "estimated_active_minutes": 45}	b4122018d230fae401dfd422be7c4976f1ffbc545eb52130d1b437d517bb168f	3151
U-B1-006	B1	306	Реальное условие и план действий	{A2-G05,A2-G06,A2-G03}	{}	{B1-G07}	{B1-G07}	45	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B1-006-RUBRIC"], "unit_id": "U-B1-006", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-B1-006-I02", "U-B1-006-I03", "U-B1-006-I04", "U-B1-006-I05", "U-B1-006-I06"], "reception": ["U-B1-006-I07", "U-B1-006-I08", "U-B1-006-I09", "U-B1-006-I10"], "retention": ["U-B1-006-I14", "U-B1-006-I15", "U-B1-006-I16"], "diagnostic": ["U-B1-006-I01"], "production": ["U-B1-006-I11", "U-B1-006-I12", "U-B1-006-I13"]}, "title_ru": "Реальное условие и план действий", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Αν вводит условие, при котором выполняется другое действие. Αν βρέξει, θα μείνουμε μέσα оставляет дождь возможным будущим событием. В условной части нет необходимости добавлять θα: в этой базовой модели используем αν + совершенную форму, затем θα + совершенную форму. Отрицательное условие строится с δεν: Αν δεν έρθει, θα αρχίσουμε χωρίς αυτόν. Не переносите μην из конструкции να механически.\\nУсловие может описывать повторяющуюся связь: Αν έχω χρόνο, διαβάζω. Здесь нет обещания одного будущего действия. Когда событие ожидается как часть плана, когда подходит όταν: Όταν τελειώσει η συνάντηση, θα τηλεφωνήσω. Αν оставляет сам факт под вопросом; όταν организует время предполагаемого события. Это смысловой контраст, а не запрет на употребление όταν в любых неопределённых обстоятельствах.\\nДля совместного плана важно договориться о действиях в обеих ветках. Если зал свободен — встречаемся там; если нет — переносим встречу или выбираем другое место. Не обещайте подтверждённую бронь на основании условного предложения. Глагол θα мог бы обозначать будущее внутри пересказа, но в этом уроке отрабатывается базовый прямой план.\\nВ разговоре сначала сформулируйте условие, затем понятный результат и того, кто проверяет условие. Допустим и обратный порядок: Θα μείνουμε μέσα αν βρέξει. Запятая на письме не является главным критерием понимания; важнее не перепутать условие и уже известный факт.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Αν βρέξει, θα μείνουμε μέσα.", "Αν δεν έρθει η Άννα, θα της τηλεφωνήσω.", "Όταν τελειώσει η συνάντηση, θα φύγουμε.", "Θα περιμένουμε αν χρειαστεί."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B1-006-I14", "U-B1-006-I15", "U-B1-006-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF9–11", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction B1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-B1-006-I05", "U-B1-006-I06"], "prerequisites": ["A2-G05", "A2-G06", "A2-G03"], "reading_tasks": ["U-B1-006-I07", "U-B1-006-I08"], "transfer_task": "U-B1-006-I13", "writing_tasks": ["U-B1-006-I11"], "competency_ids": ["B1-G07"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B1-006-I12"], "errors_taxonomy": ["CONDITIONAL", "NEGATION", "FACT_VS_PLAN"], "guided_practice": ["U-B1-006-I02", "U-B1-006-I03", "U-B1-006-I04"], "listening_tasks": ["U-B1-006-I09", "U-B1-006-I10"], "learning_outcome": "Построить условный план с αν и отрицанием δεν", "vocabulary_items": [{"lemma": "χρειάζομαι", "stress": "χρειάζομαι", "example": "Θα βοηθήσω αν χρειαστεί.", "inflection": "θα χρειαστώ; χρειαστεί безлично", "meaning_ru": "нуждаться; понадобиться", "collocations": ["αν χρειαστεί"]}, {"lemma": "ελεύθερος", "stress": "ελεύθερος", "example": "Η αίθουσα είναι ελεύθερη.", "inflection": "ελεύθερος, ελεύθερη, ελεύθερο", "meaning_ru": "свободный", "collocations": ["ελεύθερη αίθουσα"]}, {"lemma": "μεταφέρω", "stress": "μεταφέρω", "example": "Θα μεταφέρουμε τη συνάντηση.", "inflection": "μετέφερα; θα μεταφέρω", "meaning_ru": "переносить", "collocations": ["μεταφέρω τη συνάντηση"]}, {"lemma": "επιβεβαιώνω", "stress": "επιβεβαιώνω", "example": "Θα επιβεβαιώσω την κράτηση.", "inflection": "επιβεβαίωσα; θα επιβεβαιώσω", "meaning_ru": "подтверждать", "collocations": ["επιβεβαιώνω την κράτηση"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B1-006-I01"], "learning_objectives": ["Построить условный план с αν и отрицанием δεν", "Отличить условный план от подтверждённого события", "Согласовать действия при двух возможных исходах"], "microcompetency_ids": ["U-B1-006-MC01", "U-B1-006-MC02", "U-B1-006-MC03"], "primary_competencies": ["B1-G07"], "learner_data_included": false, "estimated_active_minutes": 45}	afb90e5971bd628e7d14e9ae86bbe9310bca86229f5c23b11297daf69ecfed5b	3152
U-B1-007	B1	307	Связное письмо: опыт, причина и запрос	{A2-G03,A2-G05,B1-G10}	{}	{B1-W01}	{B1-W01}	45	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B1-007-RUBRIC"], "unit_id": "U-B1-007", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-B1-007-I02", "U-B1-007-I03", "U-B1-007-I04", "U-B1-007-I05", "U-B1-007-I06"], "reception": ["U-B1-007-I07", "U-B1-007-I08", "U-B1-007-I09", "U-B1-007-I10"], "retention": ["U-B1-007-I14", "U-B1-007-I15", "U-B1-007-I16"], "diagnostic": ["U-B1-007-I01"], "production": ["U-B1-007-I11", "U-B1-007-I12", "U-B1-007-I13"]}, "title_ru": "Связное письмо: опыт, причина и запрос", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "В письме B1 адресат должен понять, зачем вы пишете, что произошло и чего вы ждёте в ответ. Полезная структура: обращение → краткая ситуация → опыт с причиной оценки → конкретный запрос → завершение. Это рабочая опора, а не обязательный шаблон для любого жанра. Письмо знакомому Γεια σου, Ρέα допускает более разговорный тон, чем Αγαπητή κυρία... Не смешивайте в одном письме ты и вежливое вы без причины.\\nОпыт описывается понятной последовательностью. Χτες πήγα... сначала устанавливает событие, затем επειδή/γι’ αυτό связывают причину и результат. Κι ещё одной связки недостаточно, если адресат не понимает, к чему относится местоимение. Назовите предмет или человека повторно, когда это снимает двусмысленность.\\nЗапрос должен быть исполнимым: Μπορείτε να μου πείτε αν υπάρχει άλλο τμήμα; яснее, чем γενικό Θέλω βοήθεια без уточнения. Укажите нужный параметр — день, время, формат ответа, — но не выдумывайте обязательство организации. В модели ниже цены и расписание не сообщаются, потому что автор их не знает.\\nПеред отправкой проверьте четыре вещи: все пункты задания раскрыты; обращение соответствует отношениям; причины относятся к своей оценке; просьба не выглядит уже полученным подтверждением. Орфографические ошибки исправляйте после смыслового прохода. Краткий образец помогает понять структуру, но его нельзя запоминать как единственно допустимый ответ на новое задание.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Σας γράφω για να ζητήσω πληροφορίες.", "Το μάθημα μου άρεσε, επειδή είχαμε χρόνο για συζήτηση.", "Δεν μπορώ να έρχομαι την Τρίτη, γι’ αυτό αναζητώ άλλο τμήμα.", "Μπορείτε να μου πείτε ποιες άλλες ώρες υπάρχουν;"], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B1-007-I14", "U-B1-007-I15", "U-B1-007-I16"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "V201 PDF9–11", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Авторское соответствие reception / production / interaction B1", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}], "active_recall": ["U-B1-007-I05", "U-B1-007-I06"], "prerequisites": ["A2-G03", "A2-G05", "B1-G10"], "reading_tasks": ["U-B1-007-I07", "U-B1-007-I08"], "transfer_task": "U-B1-007-I13", "writing_tasks": ["U-B1-007-I11"], "competency_ids": ["B1-W01"], "coverage_claim": "PARTIAL_MACRO_COVERAGE; audio and human QA blocked", "speaking_tasks": ["U-B1-007-I12"], "errors_taxonomy": ["REGISTER", "COHESION", "TASK_COMPLETION"], "guided_practice": ["U-B1-007-I02", "U-B1-007-I03", "U-B1-007-I04"], "listening_tasks": ["U-B1-007-I09", "U-B1-007-I10"], "learning_outcome": "Написать связное письмо об опыте и запросе", "vocabulary_items": [{"lemma": "πληροφορία", "stress": "πληροφορία", "example": "Θα ήθελα πληροφορίες για το τμήμα.", "inflection": "η πληροφορία, οι πληροφορίες", "meaning_ru": "сведения", "collocations": ["ζητάω πληροφορίες"]}, {"lemma": "τμήμα", "stress": "τμήμα", "example": "Υπάρχει άλλο τμήμα;", "inflection": "το τμήμα, τα τμήματα", "meaning_ru": "группа; отделение", "collocations": ["άλλο τμήμα"]}, {"lemma": "διαθέσιμος", "stress": "διαθέσιμος", "example": "Ποιες ώρες είναι διαθέσιμες;", "inflection": "διαθέσιμος, διαθέσιμη, διαθέσιμο", "meaning_ru": "доступный", "collocations": ["διαθέσιμη ώρα"]}, {"lemma": "αναζητώ", "stress": "αναζητώ", "example": "Αναζητώ ένα πρωινό τμήμα.", "inflection": "αναζητώ, αναζητάς; αναζήτησα", "meaning_ru": "искать", "collocations": ["αναζητώ λύση"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B1-007-I01"], "learning_objectives": ["Написать связное письмо об опыте и запросе", "Обосновать оценку и причину изменения", "Сохранить регистр и отделить просьбу от подтверждения"], "microcompetency_ids": ["U-B1-007-MC01", "U-B1-007-MC02", "U-B1-007-MC03"], "primary_competencies": ["B1-W01"], "learner_data_included": false, "estimated_active_minutes": 45}	eee039511377687ccc20d5ae5903ccb2e7467c0056802888c22710852c0739b8	3153
U-B1-008	B1	308	Объясняем причину, цель и результат	{A2-G11,A2-G06}	{}	{B1-G10}	{B1-G10}	65	{"qa": {"status": "AUTO_VALIDATED", "publishable": false, "audio_review": "MISSING_AUDIO", "human_review": "NOT_REVIEWED", "human_reviewer": null, "author_self_review": "DONE_NOT_INDEPENDENT", "automatic_validation": "PASS", "independent_linguistic_review": "NOT_REVIEWED"}, "status": "AUTO_VALIDATED", "rubrics": ["U-B1-008-RUBRIC"], "unit_id": "U-B1-008", "version": "0.1.0", "sections": {"theory": "theory_ru", "practice": ["U-B1-008-I02", "U-B1-008-I03", "U-B1-008-I04", "U-B1-008-I05", "U-B1-008-I06", "U-B1-008-I07", "U-B1-008-I08", "U-B1-008-I19", "U-B1-008-I20"], "reception": ["U-B1-008-I09", "U-B1-008-I10", "U-B1-008-I11", "U-B1-008-I12"], "retention": ["U-B1-008-I16", "U-B1-008-I17", "U-B1-008-I18", "U-B1-008-I22"], "diagnostic": ["U-B1-008-I01"], "production": ["U-B1-008-I13", "U-B1-008-I14", "U-B1-008-I15", "U-B1-008-I21"]}, "title_ru": "Объясняем причину, цель и результат", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "reviewers": [], "theory_ru": "Сначала определите связь между событиями. Причина отвечает на «почему это произошло?»: Έμεινα σπίτι επειδή έβρεχε. Дождь объясняет решение остаться. Цель отвечает на «зачем действовал человек?»: Έφυγα νωρίς για να προλάβω το λεωφορείο. Намерение не доказывает успех: можно добавить αλλά τελικά το έχασα. Последовательность двух событий сама по себе не доказывает причинность.\\n\\nΕπειδή вводит предложение с личной формой. В отрицательном факте употребляем δεν: Δεν ήρθα επειδή δεν αισθανόμουν καλά. Вынесенная вперёд причина обычно отделяется запятой: Επειδή έβρεχε, μείναμε μέσα. Не переводите русское «потому» отдельным местоимением без нужной связи.\\n\\nΓια να вводит цель и требует формы после να. Законченную цель выражает, например, για να διαβάσω το μήνυμα; повторяющуюся — για να διαβάζω κάθε βράδυ. Отрицательная цель: για να μην αργήσω. Субъекты могут отличаться: Μίλησα αργά για να με καταλάβουν όλοι. Не согласовывайте второй глагол автоматически с первым.\\n\\nΓι’ αυτό связывает уже названную причину со следующим решением или следствием: Το λεωφορείο χάλασε. Γι’ αυτό αργήσαμε. Это отдельное обстоятельственное выражение, а не замена επειδή внутри любой конструкции. При перестройке сохраните направление причинности: Αργήσαμε επειδή χάλασε το λεωφορείο.\\n\\nΏστε вводит результат; конструкцию выбирают вместе со значением. Ήταν τόσο δυνατός ο θόρυβος, ώστε δεν ακούσαμε την ανακοίνωση: здесь прямо сообщён фактический результат. В Μίλησε αρκετά δυνατά ώστε να τον ακούσουν όλοι конструкция с να описывает достаточное условие/ожидаемый эффект; нельзя из одного να вывести, что все действительно услышали. В этом уроке для однозначного сообщения о случившемся используйте ώστε + личную форму с контекстом факта, а намерение обозначайте για να.\\n\\nПри проверке сначала перескажите смысл без связки, затем выберите форму. Одна грамматически правильная связка не компенсирует перевёрнутую причину. В собственной речи объясните решение, обозначьте цель и отдельно сообщите, достигнута ли она. Если собеседник не понял, уточните γεγονός ή στόχος — факт это или цель.", "cefr_level": "B1", "auth_status": "AUTH_2026_UNVERIFIED", "examples_el": ["Ακύρωσα τη βόλτα επειδή έβρεχε.", "Πήγα στη βιβλιοθήκη για να δουλέψω ήσυχα.", "Πήρα σημειώσεις για να μην ξεχάσω τις οδηγίες.", "Δεν υπήρχαν εισιτήρια. Γι’ αυτό γυρίσαμε σπίτι.", "Η αίθουσα ήταν τόσο μικρή, ώστε αρκετοί έμειναν όρθιοι.", "Έστειλα το αρχείο για να το ελέγξει η Άννα, αλλά δεν το έχει ανοίξει ακόμη."], "review_plan": {"days": [7, 14, 28], "rule": "Сначала новая самостоятельная попытка без подсказок. При помощи — assisted evidence, не mastery.", "item_ids": ["U-B1-008-I16", "U-B1-008-I17", "U-B1-008-I18", "U-B1-008-I22"], "hypothesis_not_official": true}, "source_refs": [{"anchor": "Историческая уровневая тематическая карта; размещение требует эксперта", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Reception, production, interaction; author mapping, not official cut score", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "§5.2: αιτιολογικές, τελικές, αποτελεσματικές", "source_id": "N404", "checked_on": "2026-10-14", "claim_scope": "Грамматическое/фонетическое правило; задания оригинальные", "evidence_type": "OFFICIAL_SCHOOL_GRAMMAR_NOT_AUTH_SYLLABUS"}], "evidence_map": [{"delayed": ["U-B1-008-I16", "U-B1-008-I22"], "transfer": ["U-B1-008-I13", "U-B1-008-I15"], "source_ids": ["V201", "W322", "N404"], "prerequisites": ["A2-G11", "A2-G06"], "mastery_decision": {"rule": "Целевая связь/форма верна в контролируемом задании; самостоятельное применение в новом сообщении и переносе; повтор без подсказок через 7/14/28 дней. Не усреднять критическую смысловую ошибку.", "status": "NOT_ASSESSED", "pronunciation_gate": "NOT_INFERRED_FROM_TRANSCRIPT"}, "microcompetency_id": "U-B1-008-MC01", "observable_outcome": "Различить причину, намерение и фактическое следствие в сообщении.", "evidence_is_collected": false, "independent_production": ["U-B1-008-I07", "U-B1-008-I19"], "recognition_or_controlled": ["U-B1-008-I01", "U-B1-008-I02", "U-B1-008-I03", "U-B1-008-I19"], "success_criteria_specific": "Различить причину, намерение и фактическое следствие в сообщении."}, {"delayed": ["U-B1-008-I17", "U-B1-008-I22"], "transfer": ["U-B1-008-I13", "U-B1-008-I15"], "source_ids": ["V201", "W322", "N404"], "prerequisites": ["A2-