, "speaking_tasks": ["U-B1-008-I14", "U-B1-008-I21"], "errors_taxonomy": ["CAUSE_RESULT_REVERSED", "PURPOSE_AS_FACT", "DEN_AFTER_PURPOSE", "SUBJECT_SHIFT"], "guided_practice": ["U-B1-008-I02", "U-B1-008-I03", "U-B1-008-I04", "U-B1-008-I05", "U-B1-008-I06"], "listening_tasks": ["U-B1-008-I11", "U-B1-008-I12"], "pedagogy_review": {"scope": "full explanation, contrast, model, controlled practice, recall, reception, independent output, repair, transfer, delayed retrieval", "status": "AUTHOR_REVIEWED_NOT_INDEPENDENT", "open_blockers": ["INDEPENDENT_GREEK_REVIEW", "AUDIO_NOT_PRODUCED", "LEARNER_PILOT_NOT_RUN"]}, "learning_outcome": "Различить причину, намерение и фактическое следствие в сообщении.", "vocabulary_items": [{"lemma": "ακυρώνω", "stress": "ακυρώνω", "example": "Ακύρωσα τη συνάντηση.", "inflection": "ακύρωσα", "meaning_ru": "отменять", "collocations": ["ακυρώνω μια συνάντηση"]}, {"lemma": "προλαβαίνω", "stress": "προλαβαίνω", "example": "Έφυγα νωρίς για να προλάβω.", "inflection": "πρόλαβα", "meaning_ru": "успевать", "collocations": ["προλαβαίνω το λεωφορείο"]}, {"lemma": "ο στόχος", "stress": "ο στόχος", "example": "Ο στόχος δεν επιτεύχθηκε.", "inflection": "του στόχου", "meaning_ru": "цель", "collocations": ["πετυχαίνω έναν στόχο"]}, {"lemma": "η αιτία", "stress": "η αιτία", "example": "Η βροχή ήταν η αιτία.", "inflection": "της αιτίας", "meaning_ru": "причина", "collocations": ["η αιτία της καθυστέρησης"]}, {"lemma": "το αποτέλεσμα", "stress": "το αποτέλεσμα", "example": "Το αποτέλεσμα ήταν θετικό.", "inflection": "του αποτελέσματος", "meaning_ru": "результат", "collocations": ["το τελικό αποτέλεσμα"]}, {"lemma": "η ανακοίνωση", "stress": "η ανακοίνωση", "example": "Δεν άκουσα την ανακοίνωση.", "inflection": "της ανακοίνωσης", "meaning_ru": "объявление", "collocations": ["ακούω την ανακοίνωση"]}], "soft_prerequisites": [], "diagnostic_item_ids": ["U-B1-008-I01"], "learning_objectives": ["Различить причину, намерение и фактическое следствие в сообщении.", "По