KEG-B2-P01-W01	keg_b2	\N	open_response	B2	exam_holdout	\N	f	REVIEW_REQUIRED	{B2-W01,B2-G07}	{}	{}	\N	{"type": "open_response", "level": "B2", "answer": [], "module": "keg_b2", "prompt": "Γράψτε περίπου 200 λέξεις σε έναν φίλο σας. Συμμετείχατε σε ανταλλαγή αντικειμένων στο κέντρο της γειτονιάς. Περιγράψτε την οργάνωση, τι σας άρεσε προσωπικά, μία δυσκολία και αν προτείνετε στον φίλο σας να έρθει την επόμενη φορά και γιατί. Μη χρησιμοποιήσετε το πραγματικό σας όνομα.", "rubric": "RUB-KEG-WRITING-PROJECT", "item_id": "KEG-B2-P01-W01", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "rubric_review", "official_score": false, "ai_score_calibrated": false, "evidence_spans_required": true, "unlisted_plausible_answer": "ACCEPT_IF_TASK_FULFILLED"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": null, "version": "0.1.3", "criteria": ["объяснение организации", "личная оценка с основанием", "одна трудность", "обоснованная рекомендация"], "stimulus": null, "canonical": {"path": "GreekOS_B2_Exam_Bank/items/KEG-B2-P01-W01.json", "sha256": "24bcb35ef94c566a062c3e2ae82cd0a8bf5f7a7f053ab7b66dc9522d5f019e56"}, "error_tags": null, "audio_job_ids": [], "competency_ids": ["B2-W01", "B2-G07"], "model_response": "Αγαπητέ Μάνο,\\nΤο Σάββατο πήγα σε μια ανταλλαγή αντικειμένων στο κέντρο της γειτονιάς και σκέφτηκα ότι θα σε ενδιέφερε. Οι συμμετέχοντες έφερναν πράγματα που δεν χρησιμοποιούσαν πια και μπορούσαν να διαλέξουν κάτι χρήσιμο από τα τραπέζια. Δεν επρόκειτο για αγορά, γι’ αυτό οι διοργανωτές εξηγούσαν από την αρχή τους κανόνες.\\nΕγώ πήγα με μερικά βιβλία και βρήκα ένα φωτιστικό για το γραφείο μου. Περισσότερο από τα αντικείμενα, όμως, μου άρεσε ότι μίλησα με ανθρώπους που μένουν πολύ κοντά μου και δεν τους είχα γνωρίσει. Μια γειτόνισσα μάλιστα μας έδειξε πώς επισκευάζει μικρά ξύλινα έπιπλα αντί να τα πετάει.\\nΥπήρξε και μια δυσκολία. Στην αρχή δεν ήταν σαφές ποια αντικείμενα είχαν ήδη κρατηθεί και δύο άτομα διάλεξαν το ίδιο τραπεζάκι. Οι εθελοντές έλυσαν το θέμα ήρεμα, αλλά θα βοηθούσαν μερικές απλές ετικέτες. Επίσης, ο χώρος γέμισε γρήγορα, οπότε την επόμενη φορά θα πήγαινα νωρίτερα.\\nΝομίζω ότι αξίζει να έρθεις, ιδιαίτερα αφού θέλεις να αδειάσεις την αποθήκη σου. Δεν χρειάζεται να φέρεις πολλά πράγματα, μόνο κάτι σε καλή κατάσταση. Αν θέλεις, μπορούμε πρώτα να ρωτήσουμε τους διοργανωτές τι δέχονται και να πάμε μαζί στην επόμενη συνάντηση. Θα είναι και μια ωραία ευκαιρία να τα πούμε από κοντά.\\nΦιλικά,\\nΑλέξης", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "exam_holdout", "time": "shared85minutes", "level": "B2", "points": 10, "prompt": "Γράψτε περίπου 200 λέξεις σε έναν φίλο σας. Συμμετείχατε σε ανταλλαγή αντικειμένων στο κέντρο της γειτονιάς. Περιγράψτε την οργάνωση, τι σας άρεσε προσωπικά, μία δυσκολία και αν προτείνετε στον φίλο σας να έρθει την επόμενη φορά και γιατί. Μη χρησιμοποιήσετε το πραγματικό σας όνομα.", "skills": ["writing"], "status": "DRAFT", "item_id": "KEG-B2-P01-W01", "section": "writing", "unit_id": null, "version": "0.1.3", "language": "el", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Два разных жанра; образец авторский и не оценён официальным экзаменатором.", "rubric_id": "RUB-KEG-WRITING-PROJECT", "answer_type": "open_response", "exam_family": "KEG_B2", "publishable": false, "source_refs": ["V241", "V243"], "exam_form_id": "KEG-B2-P01", "human_review": "NOT_REVIEWED", "item_