ethod": "rubric_review", "official_score": false, "ai_score_calibrated": false, "evidence_spans_required": true, "unlisted_plausible_answer": "ACCEPT_IF_TASK_FULFILLED"}, "automatic_validation": "PASS", "task_specific_rubric": [{"0": "Отсутствует или противоречит условию", "1": "Упомянуто без достаточного пояснения/с частичной потерей смысла", "2": "Ясно выполнено и подкреплено относящимся к задаче пояснением", "criterion": "объяснение организации", "evidence_span_required": true}, {"0": "Отсутствует или противоречит условию", "1": "Упомянуто без достаточного пояснения/с частичной потерей смысла", "2": "Ясно выполнено и подкреплено относящимся к задаче пояснением", "criterion": "личная оценка с основанием", "evidence_span_required": true}, {"0": "Отсутствует или противоречит условию", "1": "Упомянуто без достаточного пояснения/с частичной потерей смысла", "2": "Ясно выполнено и подкреплено относящимся к задаче пояснением", "criterion": "одна трудность", "evidence_span_required": true}, {"0": "Отсутствует или противоречит условию", "1": "Упомянуто без достаточного пояснения/с частичной потерей смысла", "2": "Ясно выполнено и подкреплено относящимся к задаче пояснением", "criterion": "обоснованная рекомендация", "evidence_span_required": true}]}, "prerequisite_ids": [], "source_claim_ids": ["CP09-INHERITED-KEG-B2-P01-W01-1", "CP09-INHERITED-KEG-B2-P01-W01-2"], "accepted_alternatives": []}	20c27266366797ee43f517664b7291702a1fba3c9bfd929800b10e1e641365d9	3380
KEG-B2-P01-W02	keg_b2	\N	open_response	B2	exam_holdout	\N	f	REVIEW_REQUIRED	{B2-W02,B2-G07}	{}	{}	\N	{"type": "open_response", "level": "B2", "answer": [], "module": "keg_b2", "prompt": "Γράψτε επίσημη επιστολή περίπου 200 λέξεων προς την επιτροπή του τοπικού αναγνωστηρίου. Η επιτροπή εξετάζει ήσυχες βραδινές ώρες και δωρεάν ζώνη ομαδικής εργασίας. Εξηγήστε τα οφέλη και των δύο, τη σύγκρουση αναγκών και προτείνετε έναν δίκαιο δοκιμαστικό τρόπο λειτουργίας. Οι προτάσεις είναι υποθετικές· μην επινοήσετε αποτελέσματα έρευνας. Μη χρησιμοποιήσετε το πραγματικό σας όνομα.", "rubric": "RUB-KEG-WRITING-PROJECT", "item_id": "KEG-B2-P01-W02", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "rubric_review", "official_score": false, "ai_score_calibrated": false, "evidence_spans_required": true, "unlisted_plausible_answer": "ACCEPT_IF_TASK_FULFILLED"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": null, "version": "0.1.3", "criteria": ["польза тихих часов", "польза групповой зоны", "конфликт интересов", "обоснованный пробный порядок", "официальный адресат и вежливый формальный регистр"], "stimulus": null, "canonical": {"path": "GreekOS_B2_Exam_Bank/items/KEG-B2-P01-W02.json", "sha256": "3e32ffadc76922dbd003d17813ee6f3a87adf4881a650e1016d08b9ba3759a24"}, "error_tags": null, "audio_job_ids": [], "competency_ids": ["B2-W02", "B2-G07"], "model_response": "Αξιότιμα μέλη της επιτροπής,\\nΗ συζήτηση για το ωράριο και τη χρήση του τοπικού αναγνωστηρίου δεν αφορά μόνο τους μαθητές. Ο χώρος εξυπηρετεί ανθρώπους με διαφορετικές ανάγκες, από εργαζομένους που διαβάζουν το βράδυ μέχρι μικρές ομάδες που προετοιμάζουν μια παρουσίαση. Μια δίκαιη απόφαση οφείλει να λάβει υπόψη αυτή την ποικιλία.\\nΟι ήσυχες βραδινές ώρες θα έδιναν μια δυνατότητα συγκέντρωσης σε όσους δεν διαθέτουν κατάλληλο χώρο στο σπίτι. Αντίστοιχα, μια δωρεάν ζώνη συνεργασίας θα επέτρεπε σε ομάδες να συζητούν χωρίς να χρειάζεται να πληρώνουν για μια ιδιωτική αίθουσα. Και οι δύο χρήσεις έχουν, επομένως, σαφή κοινωνική αξία.\\nΗ δυσκολία εμφανίζεται όταν πραγματοποιούνται ταυτόχρονα στον ίδιο μικρό χώρο. Δεν αρκεί να ζητήσουμε από όλους να μιλούν χαμηλόφωνα, αν μια δραστηριότητα απαιτεί συζήτηση ενώ μια άλλη απόλυτη ησυχία. Χρειάζεται σαφής κατανομή του χρόνου ή, εφόσον είναι πρακτικά δυνατό, διαχωρισμός των αιθουσών.\\nΠροτείνω μια δοκιμή τεσσάρων εβδομάδων με ορισμένα απογεύματα για συνεργασία και άλλα για ατομική μελέτη. Το πρόγραμμα πρέπει να ανακοινωθεί εγκαίρως, ενώ οι κρατήσεις για τις ομάδες να είναι απλές και διαφανείς. Στο τέλος, οι χρήστες και το προσωπικό μπορούν να καταγράψουν δυσκολίες και προτάσεις. Μόνο τότε θα έχει νόημα μια μονιμότερη απόφαση, βασισμένη στην πραγματική λειτουργία του χώρου και όχι σε υποθέσεις.\\nΜε εκτίμηση,\\nΈνας κάτοικος της περιοχής", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "exam_holdout", "time": "shared85minutes", "level": "B2", "points": 10, "prompt": "Γράψτε επίσημη επιστολή περίπου 200 λέξεων προς την επιτροπή του τοπικού αναγνωστηρίου. Η επιτροπή εξετάζει ήσυχες βραδινές ώρες και δωρεάν ζώνη ομαδικής εργασίας. Εξηγήστε τα οφέλη και των δύο, τη σύγκρουση αναγκών και προτείνετε έναν δίκαιο δοκιμαστικό τρόπο λειτουργίας. Οι προτάσεις είναι υποθετικές· μην επινοήσετε αποτελέσματα έρευνας. Μη χρησιμοποιήσετε το πραγματικό σας όνομα.", "skills": ["writing"], "status": "DRAFT", "item_id": "KEG-B2-P01-W02", "section": "writing", "unit_id": null, "version": "0.1.3", "language": "el", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Два разных жанра; образец авторский и не оценён официальным экзаменатором.", "rubric_id": "RUB-KEG-WRITING-PROJECT", "answer_type": "open_response", "exam_family": "KEG_B2", "publishable": false, "source_refs": ["V241", "V243"], "exam_form_id": "KEG-B2-P01", "human_review": "NOT_REVIEWED", "item_version": "0.1.3", "review_status": "DRAFT", "scoring_limit": "Descriptive project rubric only; no official 10-point conversion; teacher calibration absent", "competency_ids": ["B2-W02", "B2-G07"], "model_response": "Αξιότιμα μέλη της επιτροπής,\\nΗ συζήτηση για το ωράριο και τη χρήση του τοπικού αναγνωστηρίου δεν αφορά μόνο τους μαθητές. Ο χώρος εξυπηρετεί ανθρώπους με διαφορετικές ανάγκες, από εργαζομένους που διαβάζουν το βράδυ μέχρι μικρές ομάδες που προετοιμάζουν μια παρουσίαση. Μια δίκαιη απόφαση οφείλει να λάβει υπόψη αυτή την ποικιλία.\\nΟι ήσυχες βραδινές ώρες θα έδιναν μια δυνατότητα συγκέντρωσης σε όσους δεν διαθέτουν κατάλληλο χώρο στο σπίτι. Αντίστοιχα, μια δωρεάν ζώνη συνεργασίας θα επέτρεπε σε ομάδες να συζητούν χωρίς να χρειάζεται να πληρώνουν για μια ιδιωτική αίθουσα. Και οι δύο χρήσεις έχουν, επομένως, σαφή κοινωνική αξία.\\nΗ δυσκολία εμφανίζεται όταν πραγματοποιούνται ταυτόχρονα στον ίδιο μικρό χώρο. Δεν αρκεί να ζητήσουμε από όλους να μιλούν χαμηλόφωνα, αν μια δραστηριότητα απαιτεί συζήτηση ενώ μια άλλη απόλυτη ησυχία. Χρειάζεται σαφής κατανομή του χρόνου ή, εφόσον είναι πρακτικά δυνατό, διαχωρισμός των αιθουσών.\\nΠροτείνω μια δοκιμή τεσσάρων εβδομάδων με ορισμένα απογεύματα για συνεργασία και άλλα για ατομική μελέτη. Το πρόγραμμα πρέπει να ανακοινωθεί εγκαίρως, ενώ οι κρατήσεις για τις ομάδες να είναι απλές και διαφανείς. Στο τέλος, οι χρήστες και το προσωπικό μπορούν να καταγράψουν δυσκολίες και προτάσεις. Μόνο τότε θα έχει νόημα μια μονιμότερη απόφαση, βασισμένη στην πραγματική λειτουργία του χώρου και όχι σε υποθέσεις.\\nΜε εκτίμηση,\\nΈνας κάτοικος της περιοχής", "success_criteria": ["польза тихих часов", "польза групповой зоны", "конфликт интересов", "обоснованный пробный порядок", "официальный адресат и вежливый формальный регистр"], "accepted_variants": [], "canonical_answers": [], "prompt_ru_support": "Напишите официальное письмо комитету читального зала (около200 слов). Объясните пользу тихих вечерних часов и пользу групповой работы, рассмотрите конфликт между потребностями посетителей и предложите пробный порядок организации пространства или времени с оценкой результата. Следуйте всем условиям греческой инструкции; используйте условное имя.", "source_provenance": "original_authoring", "model_is_exhaustive": false, "response_evaluation": {"method": "rubric_review", "official_score": false, "ai_score_calibrated": false, "evidence_spans_required": true, "unlisted_plausible_answer": "ACCEPT_IF_TASK_FULFILLED"}, "automatic_validation": "PASS", "task_specific_rubric": [{"0": "Отсутствует или противоречит условию", "1": "Упомянуто без достаточного пояснения/с частичной потерей смысла", "2": "Ясно выполнено и подкреплено относящимся к задаче пояснением", "criterion": "польза тихих часов", "evidence_span_required": true}, {"0": "Отсутствует или противоречит условию", "1": "Упомянуто без достаточного пояснения/с частичной потерей смысла", "2": "Ясно выполнено и подкреплено относящимся к задаче пояснением", "criterion": "польза групповой зоны", "evidence_span_required": true}, {"0": "Отсутствует или противоречит условию", "1": "Упомянуто без достаточного пояснения/с частичной потерей смысла", "2": "Ясно выполнено и подкреплено относящимся к задаче пояснением", "criterion": "конфликт интересов", "evidence_span_required": true}, {"0": "Отсутствует или противоречит условию", "1": "Упомянуто без достаточного пояснения/с частичной потерей смысла", "2": "Ясно выполнено и подкреплено относящимся к задаче пояснением", "criterion": "обоснованный пробный порядок", "evidence_span_required": true}, {"0":