KEG-B2-S01-I1	keg_b2	\N	open_response	B2	exam_holdout	\N	t	REVIEW_REQUIRED	{B2-SI01}	{}	{}	\N	{"type": "open_response", "level": "B2", "answer": [], "module": "keg_b2", "prompt": "Συζητήστε σε ζευγάρι πώς θα χρησιμοποιηθεί μία διαθέσιμη αίθουσα για δύο απογεύματα την εβδομάδα. Ο υποψήφιος Α προτιμά ήσυχη ατομική μελέτη. Ο υποψήφιος Β προτιμά συζητήσεις μικρών ομάδων. Δεν υπάρχει δεύτερη αίθουσα. Καταλήξτε σε κοινή πρόταση και διευκρινίστε πώς θα αξιολογηθεί μετά από έναν μήνα.", "rubric": "RUB-KEG-SPEAKING-PROJECT", "item_id": "KEG-B2-S01-I1", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": null, "version": "0.1.1", "criteria": ["ανταπόκριση στο επιχείρημα του άλλου", "τεκμηριωμένη θέση", "εφικτός συμβιβασμός", "κοινό σχέδιο επανεξέτασης"], "stimulus": null, "canonical": {"path": "GreekOS_B2_Exam_Bank/items/KEG-B2-S01-I1.json", "sha256": "3a81cd5323f016ead56387440f7ff188d5d52bec6946a9a32d9cbefbea19a5cc"}, "error_tags": null, "audio_job_ids": [], "competency_ids": ["B2-SI01"], "model_response": "Α: Για μένα προτεραιότητα είναι η ησυχία, γιατί ορισμένοι δεν έχουν κατάλληλο χώρο στο σπίτι. Β: Το καταλαβαίνω, αλλά και οι ομάδες χρειάζονται χώρο για να προετοιμάζουν εργασίες. Α: Θα μπορούσαμε να χωρίσουμε τα δύο απογεύματα; Το ένα για ατομική μελέτη και το άλλο για συνεργασία. Β: Συμφωνώ, αρκεί να ανακοινώσουμε καθαρά το πρόγραμμα. Α: Ας δοκιμάσουμε για έναν μήνα και μετά ας συγκεντρώσουμε σχόλια. Β: Ωραία. Αν μια χρήση έχει πολύ μεγαλύτερη ζήτηση, θα ξαναδούμε την κατανομή.", "requires_audio": true, "estimated_effort": 