U-A2-013-I10	core	U-A2-013	short_answer	A2	course_practice	reading	f	EXACT_WITH_REVIEW_FALLBACK	{A2-SI01}	{A1-PR01,A2-V02}	{}	{COMPREHENSION}	{"type": "short_answer", "level": "A2", "answer": ["Το μικρό βιβλίο."], "module": "core", "prompt": "По тексту: какая из двух книг нужна Нине? Ответьте по-гречески.", "rubric": null, "item_id": "U-A2-013-I10", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "EXACT_WITH_REVIEW_FALLBACK", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-A2-013", "version": "0.1.1", "criteria": [], "stimulus": {"text_el": "Η Νίνα πηγαίνει στη βιβλιοθήκη για ένα βιβλίο ελληνικών. Η υπάλληλος της δίνει δύο βιβλία. Η Νίνα εξηγεί ότι χρειάζεται μόνο το μικρό βιβλίο, όχι το μεγάλο. Η υπάλληλος λέει ότι πρέπει να το επιστρέψει την Πέμπτη. Η Νίνα δεν ακούει καλά και ρωτά: «Την Τρίτη ή την Πέμπτη;» Η υπάλληλος επαναλαμβάνει: «Την Πέμπτη, μέχρι τις έξι το απόγευμα». Η Νίνα δουλεύει μέχρι τις πέντε, αλλά μπορεί να πάει μετά τη δουλειά. Πριν φύγει, επιβεβαιώνει την ημέρα και την ώρα. Δεν ζητά να αλλάξει η ημέρα επιστροφής."}, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-A2-013-I10.json", "sha256": "87783a9a4cda5d27c1e439ba882bee11b0799d04f7450d56f323b298ef10413f"}, "error_tags": ["COMPREHENSION"], "audio_job_ids": [], "competency_ids": ["A2-SI01"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "A2", "stage": "reading", "prompt": "По тексту: какая из двух книг нужна Нине? Ответьте по-гречески.", "skills": ["reading"], "status": "AUTHORED_DRAFT", "item_id": "U-A2-013-