U-B1-001-I12	core	U-B1-001	open_response	B1	course_practice	writing	f	REVIEW_REQUIRED	{B1-G05}	{A2-G03,A2-G05}	{}	\N	{"type": "open_response", "level": "B1", "answer": [], "module": "core", "prompt": "Напишите коллеге 70–90 слов: что будет закончено к четвергу, что вы будете делать вечером в четверг и что зависит от чужого подтверждения. Используйте все три временные перспективы по смыслу.", "rubric": "U-B1-001-RUBRIC", "item_id": "U-B1-001-I12", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B1-001", "version": "0.1.1", "criteria": ["Три перспективы различимы", "Оговорка об условии не превращена в обещание", "Адресат понимает сроки"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B1-001-I12.json", "sha256": "7f477fb7899a9661f04c835fc8ea32d7173e1d38e91990e2123824d783812d28"}, "error_tags": null, "audio_job_ids": [], "competency_ids": ["B1-G05"], "model_response": "Μαρία, μέχρι την Πέμπτη θα έχω τελειώσει το κείμενο και θα έχω συγκεντρώσει τις φωτογραφίες. Το βράδυ θα ελέγχω τις τελευταίες λεπτομέρειες μαζί με τον Πέτρο. Την Παρασκευή θα στείλουμε το αρχείο, αν έχουμε την έγκριση της ομάδας. Δεν μπορώ ακόμη να επιβεβαιώσω την ώρα της συνάντησης. Περιμένω απάντηση από τη γραμματεία. Αν αλλάξει κάτι, θα σε ενημερώσω αμέσως, ώστε να οργανώσεις κι εσύ τη δουλειά σου.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B1", "stage": "writing", "prompt": "Напишите коллеге 70–90 слов: что будет закончено к четвергу, что вы будете делать вечером в четверг и что зависит от чужого подтверждения. Используйте все три временные перспективы по смыслу.", "skills": ["writing"], "status": "DRAFT", "item_id": "U-B1-001-I12", "options": [], "unit_id": "U-B1-001", "version": "0.1.1", "language": "el+ru", "stimulus": null, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Оценить передаваемый смысл по условиям задания; образец не единственный допустимый ответ.", "rubric_id": "U-B1-001-RUBRIC", "answer_type": "open_response", "publishable": false, "source_refs": [{"anchor": "V201 PDF10; V226 печатные290/292, V234 PDF30", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Goal-oriented cooperation / correspondence, B1; грамматическая последовательность по историческому AUTH", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "PDF30, ответы к290–291", "source_id": "V234", "checked_on": "2026-10-13", "claim_scope": "Подтверждает присутствие трёх будущих форм в ΚΛΙΚ B1", "evidence_type": "PUBLISHER_PREVIEW"}], "human_review": "NOT_REVIEWED", "item_version": "0.1.1", "review_status": "DRAFT", "competency_ids": ["B1-G05"], "model_response": "Μαρία, μέχρι την Πέμπτη θα έχω τελειώσει το κείμενο και θα έχω συγκεντρώσει τις φωτογραφίες. Το βράδυ θα ελέγχω τις τελευταίες λεπτομέρειες μαζί με τον Πέτρο. Την Παρασκευή θα στείλουμε το αρχείο, αν έχουμε την έγκριση της ομάδας. Δεν μπορώ ακόμη να επιβεβαιώσω