U-B1-017-I10	core	U-B1-017	mcq	B1	course_practice	reading	f	CHOICE_KEY	{B1-R01}	{A2-R01,B1-G08}	{}	{COMPREHENSION}	{"type": "mcq", "level": "B1", "answer": ["Να υπάρχει χώρος για συνεργασία μικρών ομάδων."], "module": "core", "prompt": "Ποιος είναι ο κύριος σκοπός της αλλαγής στη βιβλιοθήκη;", "rubric": "U-B1-017-RUBRIC", "item_id": "U-B1-017-I10", "options": ["Να υπάρχει χώρος για συνεργασία μικρών ομάδων.", "Να γίνονται μαθήματα με πληρωμή σε όλο το κτίριο.", "Να καταργηθεί η ησυχία στον μεγάλο χώρο."], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "CHOICE_KEY", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B1-017", "version": "0.1.0", "criteria": [], "stimulus": {"text": "Μια βιβλιοθήκη με περισσότερο χώρο για συνεργασία\\nΗ δημοτική βιβλιοθήκη της φανταστικής πόλης Αλκυόνας αλλάζει τη χρήση μιας μικρής αίθουσας. Από τη Δευτέρα 2 Νοεμβρίου, η αίθουσα που μέχρι τώρα χρησιμοποιούσαν μόνο οι υπάλληλοι θα είναι διαθέσιμη για μικρές ομάδες μελέτης. Οι επισκέπτες θα μπορούν να συζητούν εκεί χαμηλόφωνα, ενώ στον μεγάλο χώρο ανάγνωσης θα συνεχίσει να ισχύει η ησυχία.\\nΗ υπεύθυνη εξηγεί ότι η αλλαγή απαντά σε αιτήματα μαθητών και εργαζομένων που προετοιμάζουν κοινές εργασίες. Δεν σημαίνει όμως ότι όλες οι δραστηριότητες θα μεταφερθούν στη νέα αίθουσα. Τα ατομικά μαθήματα με πληρωμή δεν επιτρέπονται. Οι ομάδες πρέπει να έχουν από δύο έως τέσσερα άτομα και να κλείνουν την αίθουσα μία ημέρα νωρίτερα. Η χρήση είναι δωρεάν, αλλά κάθε ομάδα μπορεί να μείνει μέχρι δύο ώρες.\\nΤην πρώτη εβδομάδα η αίθουσα θα ανοίγει μόνο από τις τέσσερις μέχρι τις επτά το απόγευμα. Αργότερα μπορεί να προστεθούν πρωινές ώρες, αν υπάρχουν αρκετοί εθελοντές. Προς το παρόν δεν έχει ληφθεί τέτοια απόφαση. Η βιβλιοθήκη θα ζητήσει σχόλια από τους επισκέπτες στο τέλος του μήνα. «Θέλουμε να δούμε αν ο χώρος βοηθά πραγματικά τη συνεργασία», λέει η υπεύθυνη. Οι ενδιαφερόμενοι μπορούν να ζητήσουν πληροφορίες στο γραφείο υποδοχής. Το κείμενο δεν αναφέρει λειτουργία της αίθουσας την Κυριακή.", "origin": "ORIGINAL_GREEKOS_TEXT"}, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B1-017-I10.json", "sha256": "0fd27c7001db8cd84ed89500fc01a1816f3b0e2a3cfd705537da315a98323e61"}, "error_tags": ["COMPREHENSION"], "audio_job_ids": [], "competency_ids": ["B1-R01"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B1", "stage": "reading", "prompt": "Ποιος είναι ο κύριος σκοπός της αλλαγής στη βιβλιοθήκη;", "status": "AUTHORED_DRAFT", "item_id": "U-B1-017-I10", "options": ["Να υπάρχει χώρος για συνεργασία μικρών ομάδων.", "Να γίνονται μαθήματα με πληρωμή σε όλο το κτίριο.", "Να καταργηθεί η ησυχία στον μεγάλο χώρο."], "qa_risk": "HIGH", "unit_id": "U-B1-017", "version": "0.1.0", "language": "el+ru", "stimulus": {"text": "Μια βιβλιοθήκη με περισσότερο χώρο για συνεργασία\\nΗ δημοτική βιβλιοθήκη της φανταστικής πόλης Αλκυόνας αλλάζει τη χρήση μιας μικρής αίθουσας. Από τη Δευτέρα 2 Νοεμβρίου, η αίθουσα που μέχρι τώρα χρησιμοποιούσαν μόνο οι υπάλληλοι θα είναι διαθέσιμη για μικρές ομάδες μελέτης. Οι επισκέπτες θα μπορούν να συζητούν εκεί χαμηλόφωνα, ενώ στον μεγάλο χώρο ανάγνωσης θα συνεχίσει να ισχύει η ησυχία.\\nΗ υπεύθυνη εξηγεί ότι η αλλαγή απαντά σε αιτήματα μαθητών και εργαζομένων που προετοιμάζουν κοινές εργασίες. Δεν σημαίνει όμως ότι όλες οι δραστηριότητες θα μεταφερθούν στη νέα αίθουσα. Τα ατομικά μαθήματα με πληρωμή δεν επιτρέπονται. Οι ομάδες πρέπει να έχουν από δύο έως τέσσερα άτομα και να κλείνουν την αίθουσα μία ημέρα νωρίτερα. Η χρήση είναι δωρεάν, αλλά κάθε ομάδα μπορεί να μείνει μέχρι δύο ώρες.\\nΤην πρώτη εβδομάδα η αίθουσα θα ανοίγει μόνο από τις τέσσερις μέχρι τις επτά το απόγευμα. Αργότερα μπορεί να προστεθούν πρωινές ώρες, αν υπάρχουν αρκετοί εθελοντές. Προς το παρόν δεν έχει ληφθεί τέτοια απόφαση. Η βιβλιοθήκη θα ζητήσει σχόλια από τους επισκέπτες στο τέλος του μήνα. «Θέλουμε να δούμε αν ο χώρος βοηθά πραγματικά τη συνεργασία», λέει η υπεύθυνη. Οι ενδιαφερόμενοι μπορούν να ζητήσουν πληροφορίες στο γραφείο υποδοχής. Το κείμενο δεν αναφέρει λειτουργία της αίθουσας την Κυριακή.", "origin": "ORIGINAL_GREEKOS_TEXT"}, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Главная цель названа в заголовке и объяснении; платныеуроки запрещены, тихийзал сохраняется.", "rubric_id": "U-B1-017-RUBRIC", "error_tags": ["COMPREHENSION"], "answer_type": "mcq", "source_refs": [{"anchor": "Reading lines92–96; production98–103; education/work139–145; travel147–152", "source_id": "CP07-B1-S02", "checked_on": "2026-10-20", "claim_scope": "B1 functional scope: main idea/details of familiar texts, routine institutional and travel communication, explanatory circumlocution. No approval of particular GreekOS item, time or mastery threshold."}], "item_version": "0.1.0", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B1-R01"], "accepted_variants": [], "canonical_answers": ["Να υπάρχει χώρος για συνεργασία μικρών ομάδων."], "source_provenance": "ORIGINAL_PROJECT_CONTENT; source claims bounded", "response_evaluation": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}}, "prerequisite_ids": ["A2-R01", "B1-G08"], "source_claim_ids": ["CP08-INHERITED-U-B1-017-I10-01"], "accepted_alternatives": []}	75874142c3f165cd3e78ad4a681c85091b3d27ccd9d89a9f412058de6c036be2	4629
U-B1-017-I11	core	U-B1-017	open_response	B1	course_practice	reading	f	REVIEW_REQUIRED	{B1-R01}	{A2-R01,B1-G08}	{}	{COMPREHENSION}	{"type": "open_response", "level": "B1", "answer": [], "module": "core", "prompt": "Друг хочет прийти один на три часа в первую неделю утром. Объясните по тексту три препятствия и предложите допустимый вариант.", "rubric": "U-B1-017-RUBRIC", "item_id": "U-B1-017-I11", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B1-017", "version": "0.1.0", "criteria": ["группа2–4", "максимум2часа", "перваянеделя16–19", "вариант соблюдаетусловия и бронь"], "stimulus": {"text": "Μια βιβλιοθήκη με περισσότερο χώρο για συνεργασία\\nΗ δημοτική βιβλιοθήκη της φανταστικής πόλης Αλκυόνας αλλάζει τη χρήση μιας μικρής αίθουσας. Από τη Δευτέρα 2 Νοεμβρίου, η αίθουσα που μέχρι τώρα χρησιμοποιούσαν μόνο οι υπάλληλοι θα είναι διαθέσιμη για μικρές ομάδες μελέτης. Οι επισκέπτες θα μπορούν να συζητούν εκεί χαμηλόφωνα, ενώ στον μεγάλο χώρο ανάγνωσης θα συνεχίσει να ισχύει η ησυχία.\\nΗ υπεύθυνη εξηγεί ότι η αλλαγή απαντά σε αιτήματα μαθητών και εργαζομένων που προετοιμάζουν κοινές εργασίες. Δεν σημαίνει όμως ότι όλες οι δραστηριότητες θα μεταφερθούν στη νέα αίθουσα. Τα ατομικά μαθήματα με πληρωμή δεν επιτρέπονται. Οι ομάδες πρέπει να έχουν από δύο έως τέσσερα άτομα και να κλείνουν την αίθουσα μία ημέρα νωρίτερα. Η χρήση είναι δωρεάν, αλλά κάθε ομάδα μπορεί να μείνει μέχρι δύο ώρες.\\nΤην πρώτη εβδομάδα η αίθουσα θα ανοίγει μόνο από τις τέσσερις μέχρι τις επτά το απόγευμα. Αργότερα μπορεί να προστεθούν πρωινές ώρες, αν υπάρχουν αρκετοί εθελοντές. Προς το παρόν δεν έχει ληφθεί τέτοια απόφαση. Η βιβλιοθήκη θα ζητήσει σχόλια από τους επισκέπτες στο τέλος του μήνα. «Θέλουμε να δούμε αν ο χώρος βοηθά πραγματικά τη συνεργασία», λέει η υπεύθυνη. Οι ενδιαφερόμενοι μπορούν να ζητήσουν πληροφορίες στο γραφείο υποδοχής. Το κείμενο δεν αναφέρει λειτουργία της αίθουσας την Κυριακή.", "origin": "ORIGINAL_GREEKOS_TEXT"}, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B1-017-I11.json", "sha256": "fe57f9073f1e97b2f8956c6aee59fe71bc1da5433158fbd30a1f3fb254bceaa3"}, "error_tags": ["COMPREHENSION"], "audio_job_ids": [], "competency_ids": ["B1-R01"], "model_response": "Η αίθουσα είναι για ομάδες δύο έως τεσσάρων ατόμων, μέχρι δύο ώρες και την πρώτη εβδομάδα μόνο το απόγευμα. Μπορείς να πας με έναν φίλο, αφού κλείσετε την αίθουσα μία ημέρα νωρίτερα, για παράδειγμα από τις τέσσερις έως τις έξι.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B1", "stage": "reading", "prompt": "Друг хочет прийти один на три часа в первую неделю утром. Объясните по тексту три препятствия и предложите допустимый вариант.", "status": "AUTHORED_DRAFT", "item_id": "U-B1-017-I11", "options": [], "qa_risk": "HIGH", "unit_id": "U-B1-017", "version": "0.1.0", "language": "el+ru", "stimulus": {"text": "Μια βιβλιοθήκη με περισσότερο χώρο για συνεργασία\\nΗ δημοτική βιβλιοθήκη της φανταστικής πόλης Αλκυόνας αλλάζει τη χρήση μιας μικρής αίθουσας. Από τη Δευτέρα 2 Νοεμβρίου, η αίθουσα που μέχρι τώρα χρησιμοποιούσαν μόνο οι υπάλληλοι θα είναι διαθέσιμη για μικρές ομάδες μελέτης. Οι επισκέπτες θα μπορούν να συζητούν εκεί χαμηλόφωνα, ενώ στον μεγάλο χώρο ανάγνωσης θα συνεχίσει να ισχύει η ησυχία.\\nΗ υπεύθυνη εξηγεί ότι η αλλαγή απαντά σε αιτήματα μαθητών και εργαζομένων που προετοιμάζουν κοινές εργασίες. Δεν σημαίνει όμως ότι όλες οι δραστηριότητες θα μεταφερθούν στη νέα αίθουσα. Τα ατομικά μαθήματα με πληρωμή δεν επιτρέπονται. Οι ομάδες πρέπει να έχουν από δύο έως τέσσερα άτομα και να κλείνουν την αίθουσα μία ημέρα νωρίτερα. Η χρήση είναι δωρεάν, αλλά κάθε ομάδα μπορεί να μείνει μέχρι δύο ώρες.\\nΤην πρώτη εβδομάδα η αίθουσα θα ανοίγει μόνο από τις τέσσερις μέχρι τις επτά το απόγευμα. Αργότερα μπορεί να προστεθούν πρωινές ώρες, αν υπάρχουν αρκετοί εθελοντές. Προς το παρόν δεν έχει ληφθεί τέτοια απόφαση. Η βιβλιοθήκη θα ζητήσει σχόλια από τους επισκέπτες στο τέλος του μήνα. «Θέλουμε να δούμε αν ο χώρος βοηθά πραγματικά τη συνεργασία», λέει η υπεύθυνη. Οι ενδιαφερόμενοι μπορούν να ζητήσουν πληροφορίες στο γραφείο υποδοχής. Το κείμενο δεν αναφέρει λειτουργία της αίθουσας την Κυριακή.", "origin": "ORIGINAL_GREEKOS_TEXT"}, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Допустимый вариант не обязан использовать16–18, но должен укладываться в16–19.", "rubric_id": "U-B1-017-RUBRIC", "error_tags": ["COMPREHENSION"], "answer_type": "open_response", "source_refs": [{"anchor": "Reading lines92–96; production98–103; education/work139–145; travel147–152", "source_id": "CP07-B1-S02", "checked_on": "2026-10-20", "claim_scope": "B1 functional scope: main idea/details of familiar texts, routine institutional and travel communication, explanatory circumlocution. No approval of particular GreekOS item, time or mastery threshold."}], "item_version": "0.1.0", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B1-R01"], "model_response": "Η αίθουσα είναι για ομάδες δύο έως τεσσάρων ατόμων, μέχρι δύο ώρες και την πρώτη εβδομάδα μόνο το απόγευμα. Μπορείς να πας με έναν φίλο, αφού κλείσετε την αίθουσα μία ημέρα νωρίτερα, για παράδειγμα από τις τέσσερις έως τις έξι.", "success_criteria": ["группа2–4", "максимум2часа", "перваянеделя16–19", "вариант соблюдаетусловия и бронь"], "accepted_variants": [], "canonical_answers": [], "source_provenance": "ORIGINAL_PROJECT_CONTENT; source claims bounded", "response_evaluation": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}}, "prerequisite_ids": ["A2-R01", "B1-G08"], "source_claim_ids": ["CP08-INHERITED-U-B1-017-I11-01"], "accepted_alternatives": []}	ef99fcb6a53e58dfd653af61df2ab24290a0baf2a14757d7379915445b85806d	4630
U-B1-017-I12	core	U-B1-017	short_answer	B1	course_practice	listening	t	EXACT_WITH_REVIEW_FALLBACK	{B1-R01}	{A2-R01,B1-G08}	{U-B1-017-AUD01}	{COMPREHENSION}	{"type": "short_answer", "level": "B1", "answer": ["Όχι."], "module": "core", "prompt": "После будущей записи: нужна ли бронь для самой встречи о новой комнате?", "rubric": "U-B1-017-RUBRIC", "item_id": "U-B1-017-I12", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "EXACT_WITH_REVIEW_FALLBACK", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B1-017", "version": "0.1.0", "criteria": [], "stimulus": {"text": "Υπάλληλος: Η συνάντηση για τη νέα αίθουσα θα γίνει την Πέμπτη στις έξι το απόγευμα.\\nΕπισκέπτρια: Πρέπει να κάνουμε κράτηση για να έρθουμε στη συνάντηση;\\nΥπάλληλος: Όχι, για τη συνάντηση δεν χρειάζεται κράτηση. Για τη χρήση της αίθουσας από ομάδα, όμως, χρειάζεται.\\nΕπισκέπτρια: Θα αποφασιστούν τότε οι πρωινές ώρες;\\nΥπάλληλος: Όχι απαραίτητα. Θα ακούσουμε πρώτα τις προτάσεις των επισκεπτών.", "asset_id": "U-B1-017-AUD01"}, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B1-017-I12.json", "sha256": "03c82b9e971b1ab37b58d24cd7bc19665f7d130fe2602e1d501d345a76357220"}, "error_tags": ["COMPREHENSION"], "audio_job_ids": ["U-B1-017-AUD01"], "competency_ids": ["B1-R01"], "model_response": null, "requires_audio": true, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B1", "stage": "listening_script", "prompt": "После будущей записи: нужна ли бронь для самой встречи о новой комнате?", "status": "AUTHORED_DRAFT", "item_id": "U-B1-017-I12", "options": [], "qa_risk": "HIGH", "