U-B1-019-I02	core	U-B1-019	mcq	B1	course_practice	guided_practice	f	CHOICE_KEY	{B1-L02}	{A2-L02,B1-G03}	{U-B1-019-AUD01}	{COMPREHENSION}	{"type": "mcq", "level": "B1", "answer": ["Брать книги."], "module": "core", "prompt": "Для чего Анна сначала приходила?", "rubric": null, "item_id": "U-B1-019-I02", "options": ["Брать книги.", "Работать каждый день.", "Учить журналиста."], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "CHOICE_KEY", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B1-019", "version": "0.1.0", "criteria": [], "stimulus": {"text_el": "Δημοσιογράφος: Πώς ξεκίνησες να βοηθάς στη βιβλιοθήκη; Άννα: Στην αρχή πήγαινα μόνο για να δανειστώ βιβλία. Μια μέρα είδα μια ανακοίνωση για εθελοντές και μίλησα με την υπεύθυνη. Νόμιζα ότι θα χρειαζόταν να έρχομαι κάθε μέρα, αλλά μου εξήγησε ότι δύο ώρες την εβδομάδα ήταν αρκετές. Δημοσιογράφος: Ήταν εύκολη η πρώτη μέρα; Άννα: Όχι ακριβώς. Δεν ήξερα πού βρίσκονταν όλα τα βιβλία και φοβόμουν μήπως δώσω λάθος πληροφορία. Ένας άλλος εθελοντής μου έδειξε τον κατάλογο. Μετά από λίγες συναντήσεις ένιωθα πιο άνετα. Τώρα βοηθάω τους επισκέπτες να βρουν αυτό που ψάχνουν. Δημοσιογράφος: Θα το πρότεινες σε κάποιον άλλο; Άννα: Ναι, αρκεί να ρωτήσει πρώτα τι ακριβώς χρειάζεται. Δεν χρειάζεται να ξέρει τα πάντα από την πρώτη μέρα. Είναι όμως σημαντικό να ενημερώνει εγκαίρως αν δεν μπορεί να έρθει.", "display_policy": "AFTER_ATTEMPT_ONLY"}, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B1-019-I02.json", "sha256": "5383c3aefe0d9d8eb2a2f7ec6f70994d85311a2144592e3a9405b08115ee4655"}, "error_tags": ["COMPREHENSION"], "audio_job_ids": ["U-B1-019-AUD01"], "competency_ids": ["B1-L02"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B1", "stage": "guided", "prompt": "Для чего Анна сначала приходила?", "skills": ["listen_mcq"], "status": "DRAFT", "item_id": "U-B1-019-I02", "options": ["Брать книги.", "Работать каждый день.", "Учить журналиста."], "unit_id": "U-B1-019", "version": "0.1.0", "audio_id": "U-B1-019-AUD01", "language": "el+ru", "stimulus": {"text_el": "Δημοσιογράφος: Πώς ξεκίνησες να βοηθάς στη βιβλιοθήκη; Άννα: Στην αρχή πήγαινα μόνο για να δανειστώ βιβλία. Μια μέρα είδα μια ανακοίνωση για εθελοντές και μίλησα με την υπεύθυνη. Νόμιζα ότι θα χρειαζόταν να έρχομαι κάθε μέρα, αλλά μου εξήγησε ότι δύο ώρες την εβδομάδα ήταν αρκετές. Δημοσιογράφος: Ήταν εύκολη η πρώτη μέρα; Άννα: Όχι ακριβώς. Δεν ήξερα πού βρίσκονταν όλα τα βιβλία και φοβόμουν μήπως δώσω λάθος πληροφορία. Ένας άλλος εθελοντής μου έδειξε τον κατάλογο. Μετά από λίγες συναντήσεις ένιωθα πιο άνετα. Τώρα βοηθάω τους επισκέπτες να βρουν αυτό που ψάχνουν. Δημοσιογράφος: Θα το πρότεινες σε κάποιον άλλο; Άννα: Ναι, αρκεί να ρωτήσει πρώτα τι ακριβώς χρειάζεται. Δεν χρειάζεται να ξέρει τα πάντα από την πρώτη μέρα. Είναι όμως σημαντικό να ενημερώνει εγκαίρως αν δεν μπορεί να έρθει.", "display_policy": "AFTER_ATTEMPT_ONLY"}, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Волонтёрство возникло позже.", "error_tags": ["COMPREHENSION"], "answer_type": "mcq", "source_refs": [{"anchor": "Κατανόηση/Παραγωγή προφορικού λόγου, lines86–102", "source_id": "CP08-B1", "c