U-B2-005-I13	core	U-B2-005	open_response	B2	course_practice	writing	f	REVIEW_REQUIRED	{B2-G06}	{A1-G09,B1-G01}	{}	\N	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Напишите официальное письмо 120–150 слов: задержка из-за поломки, подача через платформу, подпись по регламенту, просьба о подтверждении. Используйте 4 изученные конструкции; не выдумывайте закон или официальный срок.", "rubric": "U-B2-005-RUBRIC", "item_id": "U-B2-005-I13", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-005", "version": "0.1.0", "criteria": ["4 уместные связи и падежи", "факты сохранены", "ясная просьба и регистр"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-005-I13.json", "sha256": "fa9e9161a6119039221c37c8581ba41b322928a9480a3c390cb6faed6f6c5cd1"}, "error_tags": null, "audio_job_ids": [], "competency_ids": ["B2-G06"], "model_response": "Αξιότιμη κυρία,\\nΣας γράφω σχετικά με την αίτησή μου για συμμετοχή στο σεμινάριο. Λόγω της βλάβης που παρουσιάστηκε χθες, δεν μπόρεσα να ολοκληρώσω την υποβολή της. Σήμερα έστειλα τα δικαιολογητικά μέσω της πλατφόρμας και έλαβα έναν αριθμό καταχώρισης. Σύμφωνα με τον κανονισμό του σεμιναρίου, πρόσθεσα και την υπογραφή μου στο έντυπο. Ωστόσο, δεν έχω λάβει ακόμη μήνυμα επιβεβαίωσης. Με βάση τα στοιχεία που εμφανίζονται στον λογαριασμό μου, το αρχείο έχει αποθηκευτεί, αλλά δεν γνωρίζω αν έχει ελεγχθεί. Θα μπορούσατε να επιβεβαιώσετε την παραλαβή και να με ενημερώσετε αν χρειάζεται κάποια επιπλέον ενέργεια; Δεν έχω στείλει δεύτερη αίτηση, ώστε να αποφύγω τη διπλή καταχώριση. Αν απαιτείται νέα υποβολή, παρακαλώ να μου εξηγήσετε ποια διαδικασία πρέπει να ακολουθήσω. Σας ευχαριστώ για τον χρόνο και τη βοήθειά σας.\\nΜε εκτίμηση,\\nΆννα Δημητρίου", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "writing", "prompt": "Напишите официальное письмо 120–150 слов: задержка из-за поломки, подача через платформу, подпись по регламенту, просьба о подтверждении. Используйте 4 изученные конструкции; не выдумывайте закон или официальный срок.", "skills": ["writing"], "status": "DRAFT", "item_id": "U-B2-005-I13", "options": [], "unit_id": "U-B2-005", "version": "0.1.0", "language": "el+ru", "stimulus": null, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Оценить передаваемый смысл по условиям задания; образец не единственный допустимый ответ.", "rubric_id": "U-B2-005-RUBRIC", "answer_type": "open_response", "publishable": false, "source_refs": [{"anchor": "Историческая уровневая тематическая карта; размещение требует эксперта", "source_id": "V201", "checked_on": "2026-10-13", "claim_scope": "Уровневая тема; не дословный источник авторских фраз", "evidence_type": "HISTORICAL_AUTH_VERIFIED"}, {"anchor": "Reception, production, interaction; author mapping, not official cut score", "source_id": "W322", "checked_on": "2026-10-13", "claim_scope": "Функциональное авторское сопоставление", "evidence_type": "CEFR"}, {"anchor": "§8: προθέσεις; λόγιες, σύνθετες конструкции", "source_id": "N408", "checked_on": "2026-10-14", "claim_scope": "Грамматическое/фонетическое правило; задания оригинальные", "evidence_type": "OFFICIAL_SCHOOL_GRAMMAR_NOT_AUTH_SYLLABUS"}], "human_review": "NOT_REVIEWED", "item_version": "0.1.0", "activity_type": "independent_writing", "review_status": "DRAFT", "competency_ids": ["B2-G06"], "model_response": "Αξιότιμη κυρία,\\nΣας γράφω σχετικά με την αίτησή μου για συμμετοχή στο σεμινάριο. Λόγω της βλάβης που παρουσιάστηκε χθες, δεν μπόρεσα να ολοκληρώσω την υποβολή της. Σήμερα έστειλα τα δικαιολογητικά μέσω της πλατφόρμας και έλαβα έναν αριθμό καταχώρισης. Σύμφωνα με τον κανονισμό του σεμιναρίου, πρόσθεσα και την υπογραφή μου στο έντυπο. Ωστόσο, δεν έχω λάβει ακόμη μήνυμα επιβεβαίωσης. Με βάση τα στοιχεία που εμφανίζονται στον λογαριασμό μου, το αρχείο έχει αποθηκευτεί, αλλά δεν γνωρίζω αν έχει ελεγχθεί. Θα μπορούσατε να επιβεβαιώσετε την παραλαβή και να με ενημερώσετε αν χρειάζεται κάποια επιπλέον ενέργεια; Δεν έχω στείλει δεύτερη αίτηση, ώστε να αποφύγω τη διπλή καταχώριση. Αν απαιτείται νέα υποβολή, παρακαλώ να μου εξηγήσετε ποια διαδικασία πρέπει να ακολουθήσω. Σας ευχαριστώ για τον χρόνο και τη βοήθειά σας.\\nΜε εκτίμηση,\\nΆννα Δημητρίου", "success_criteria": ["4 уместные связи и падежи", "факты сохранены", "ясная просьба и регистр"], "accepted_variants": [], "canonical_answers": [], "source_provenance": "original_authoring", "difficulty_estimate": "AUTHOR_ESTIMATE_NOT_CALIBRATED", "response_evaluation": {"method": "rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "automatic_validation": "PASS", "administration_status": "AUTHOR_CANDIDATE_HUMAN_QA_PENDING", "independence_requirement": "NO_HINTS_FIRST_ATTEMPT"}, "prerequisite_ids": ["A1-G09", "B1-G01"], "source_claim_ids": ["CP08-INHERITED-U-B2-005-I13-01", "CP08-INHERITED-U-B2-005-I13-02", "CP08-INHERITED-U-B2-005-I13-03"], "accepted_alternatives": []}	e31980bb34665