U-B2-006-I10	core	U-B2-006	short_answer	B2	course_practice	reading	f	EXACT_WITH_REVIEW_FALLBACK	{B2-G02}	{B1-G04,B1-G05,A2-G03}	{}	\N	{"type": "short_answer", "level": "B2", "answer": ["Οι ημερομηνίες."], "module": "core", "prompt": "По тексту: что оставалось непроверенным после правки заголовков?", "rubric": "U-B2-006-RUBRIC", "item_id": "U-B2-006-I10", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "EXACT_WITH_REVIEW_FALLBACK", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-006", "version": "0.1.1", "criteria": [], "stimulus": "Η ομάδα του περιοδικού ετοιμάζει ένα μικρό αφιέρωμα στη γειτονιά. Τη Δευτέρα η συντάκτρια διόρθωνε τα κείμενα όταν ο φωτογράφος έστειλε ένα νέο αρχείο. Οι τίτλοι διορθώθηκαν την ίδια μέρα, αλλά οι ημερομηνίες δεν ελέγχθηκαν. Την Τρίτη ο υπεύθυνος έγραψε στην ομάδα: «Έχουμε διορθώσει τους τίτλους. Πρέπει όμως να ελέγξουμε τις ημερομηνίες πριν στείλουμε το αρχείο στο τυπογραφείο». Μια συνεργάτιδα διάβασε γρήγορα το μήνυμα και ανακοίνωσε ότι όλα ήταν έτοιμα. Ο υπεύθυνος της ζήτησε να διορθώσει την ανακοίνωση. Δεν ήθελε να αποδώσει ευθύνη σε κάποιο συγκεκριμένο πρόσωπο· ήθελε να γίνει σαφές ποια εργασία εκκρεμούσε. Πρότεινε να ελέγχονται οι ημερομηνίες από δύο άτομα στο τέλος κάθε έκδοσης. Για το συγκεκριμένο τεύχος, η Μαρία προσφέρθηκε να κάνει τον έλεγχο το απόγευμα. Η πρότασή της έγινε δεκτή, αλλά εκείνη τη στιγμή ο έλεγχος δεν είχε ακόμη ολοκληρωθεί.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-006-I10.json", "sha256": "97d10c2a0b99c6bc3561f9b550635229686a5c7f4d24eea281803329d6c3f41c"}, "error_tags": null, "audio_job_ids":