U-B2-006-I14	core	U-B2-006	open_response	B2	course_practice	writing	f	REVIEW_REQUIRED	{B2-G02}	{B1-G04,B1-G05,A2-G03}	{}	\N	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Напишите 100–130 слов команде: вчера правили афишу, заголовок уже исправлен Марией, часы ещё проверяются; попросите коллегу закончить к 15:00; отправка только после его подтверждения. Не обвиняйте неизвестного автора ошибки.", "rubric": "U-B2-006-RUBRIC", "item_id": "U-B2-006-I14", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-006", "version": "0.1.1", "criteria": ["Процесс/готовый результат/незавершённая проверка различены", "Мария агент только правки заголовка", "Вежливая просьба и срок", "Отправка обусловлена подтверждением"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-006-I14.json", "sha256": "43017092e6bec9beb15e7fa91937eb25499c249c1e3ece3771ae52f9d8691fa8"}, "error_tags": null, "audio_job_ids": [], "competency_ids": ["B2-G02"], "model_response": "Καλημέρα σε όλους. Σας γράφω για την αφίσα της αυριανής εκδήλωσης. Χτες δουλεύαμε πάνω στο κείμενο όταν λάβαμε το νέο πρόγραμμα. Ο τίτλος έχει ήδη διορθωθεί από τη Μαρία, αλλά οι ώρες ελέγχονται ακόμη. Δεν μπορούμε επομένως να στείλουμε την αφίσα τώρα. Νίκο, θα μπορούσες να ολοκληρώσεις τον έλεγχο μέχρι τις τρεις και να μας στείλεις ένα σύντομο μήνυμα; Μόλις έχουμε την επιβεβαίωσή σου, θα προχωρήσουμε στην αποστολή. Δεν γνωρίζουμε ποιος έγραψε την παλιά ώρα και δεν χρειάζεται να κάνουμε υποθέσεις. Προτείνω στο εξής να ελέγχουμε όλοι το τελευταίο αρχείο, ώστε να μη χρησιμοποιούμε διαφορετικές εκδοχές. Αν χρειάζεσαι βοήθεια, ενημέρωσέ με εγκαίρως. Ευχαριστώ πολύ για τη συνεργασία.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "writing", "prompt": "Напишите 100–130 слов команде: вчера правили афишу, заголовок уже исправлен Марией, часы ещё проверяются; попросите коллегу закончить к 15:00; отправка только после его подтверждения. Не обвиняйте неизвестного автора ошибки.", "skills": ["writing"], "status": "DRAFT", "item_id": "U-B2-006-I14", "options": [], "unit_id": "U-B2-006", "version": "0.1.1", "language": "el+ru", "stimulus": null, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Сохранить смысл и грамматические отношения; допустимый незаписанный вариант направляется на проверку без автоматического штрафа.", "rubric_id": "U-B2-006-RUBRIC", "answer_type": "open_response", "source_refs": [{"anchor": "§6.2α lines 10–18; §6.2ε lines 79–109", "source_id": "N405", "checked_on": "2026-10-19", "claim_scope": ["Morphological voice differs from semantic disposition", "Aspect categories and active/passive λύνω paradigms; διορθώνω explicitly listed in same class"], "evidence_type": "OFFICIAL_GRAMMAR_OR_DICTIONARY", "evidence_record": "B06-S02", "evidence_status": "SOURCE_PASS_BOUNDED_CLAIMS"}], "item_version": "0.1.1", "review_status": "DRAFT", "competency_ids": ["B2-G02"], "model_response": "Καλημέρα σε όλους. Σας γράφω για την αφίσα της αυριανής εκδήλωσης. Χτες δουλεύαμε πάνω στο κείμενο όταν λάβαμε το νέο πρόγραμμα. Ο τίτλος έχει ήδη διορθωθεί από τη Μαρία, αλλά οι ώρες ελέγχονται ακόμη. Δεν μπορούμε επομένως να στείλουμε την αφίσα τώρα. Νίκο, θα μπορούσες να ολοκληρώσεις τον έλεγχο μέχρι τις τρεις και να μας στείλεις ένα σύντομο μήνυμα; Μόλις έχουμε την επιβεβαίωσή σου, θα προχωρήσουμε στην αποστολή. Δεν γνωρίζουμε ποιος έγραψε την παλιά ώρα και δεν χρειάζεται να κάνουμε υποθέσεις. Προτείνω στο εξής να ελέγχουμε όλοι το τελευταίο αρχείο, ώστε να μη χρησιμοποιούμε διαφορετικές εκδοχές. Αν χρειάζεσαι βοήθεια, ενημέρωσέ με εγκαίρως. Ευχαριστώ πολύ για τη συνεργασία.", "success_criteria": ["Процесс/готовый результат/незавершённая проверка различены", "Мария агент только правки заголовка", "Вежливая просьба и срок", "Отправка обусловлена подтверждением"], "accepted_variants": [], "canonical_answers": [], "source_provenance": "original_authoring", "difficulty_estimate": "AUTHOR_ESTIMATE_NOT_CALIBRATED", "response_evaluation": {"method": "rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}}, "prerequisite_ids": ["B1-G04", "B1-G05", "A2-G03"], "source_claim_ids": ["CP08-INHERITED-U-B2-006-I14-01"], "accepted_alternatives": []}	4f8f7836698bcacd0e418b76f1fa6c4d976b7ba73a06967d9a70f927775bf7d6	4821
