assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Разные субъекты требуют явного различения: проверку выполнили вы, отправку — коллега. В одном предложении допустима временная придаточная конструкция с явным подлежащим.", "rubric_id": "U-B2-007-RUBRIC", "error_tags": ["SYNTAX", "CONTENT_OMISSION"], "answer_type": "open_response", "source_refs": [{"anchor": "§6.2ι lines251–255", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S01", "source_id": "N405", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}, {"anchor": "§2 lines13–23,37–43", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S02", "source_id": "N-F07-PART", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}], "item_version": "0.1.2", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-G04"], "model_response": "Αφού έλεγξα τη διεύθυνση, ο συνάδελφός μου έστειλε το μήνυμα.", "source_claim_ids": ["F07-B2-S01", "F07-B2-S02"], "success_criteria": ["Проверил адрес говорящий", "Отправил коллега", "Проверка предшествует отправке"], "accepted_variants": [], "canonical_answers": [], "source_provenance": "Original GreekOS teaching task; narrow source claims only", "difficulty_estimate": "B2_AUTHOR_ESTIMATE_NOT_CALIBRATED", "response_evaluation": {"method": "semantic_rubric_with_abstention", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}}, "prerequisite_ids": ["B1-G12", "B2-G02"], "source_claim_ids": ["F07-B2-S01", "F07-B2-S02"], "accepted_alternati