U-B2-007-I10	core	U-B2-007	mcq	B2	course_practice	reading	f	CHOICE_KEY	{B2-G04}	{B1-G12,B2-G02}	{}	{COMPREHENSION}	{"type": "mcq", "level": "B2", "answer": ["Δεν είχε ακόμη ελέγξει τα πρωτότυπα."], "module": "core", "prompt": "По тексту об архиве: почему Λένα не исправила подписи сразу?", "rubric": "U-B2-007-RUBRIC", "item_id": "U-B2-007-I10", "options": ["Δεν είχε ακόμη ελέγξει τα πρωτότυπα.", "Δεν είχε βρει κανένα λάθος.", "Είχε ήδη λάβει άδεια ανάρτησης."], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "CHOICE_KEY", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-007", "version": "0.1.0", "criteria": [], "stimulus": {"text": "Η μικρή ομάδα του δημοτικού αρχείου ετοιμάζει μια ψηφιακή έκθεση για την καθημερινή ζωή της γειτονιάς. Διαβάζοντας τις περιγραφές, η Λένα εντόπισε δύο φωτογραφίες με λανθασμένη ημερομηνία. Δεν άλλαξε τις λεζάντες μόνη της, επειδή δεν είχε ακόμη ελέγξει τα πρωτότυπα. Ο Άρης, έχοντας συγκρίνει τα πρωτότυπα με τον κατάλογο, επιβεβαίωσε τη σωστή χρονολογία. Οι διορθωμένες λεζάντες στάλθηκαν έπειτα στη συντονίστρια. Η ομάδα αποφάσισε να διατηρήσει και ένα αντίγραφο της προηγούμενης έκδοσης, ώστε να είναι ορατή η αλλαγή.\\nΣτην τελική σημείωση αναφέρεται ότι το υλικό είναι ελεγμένο, όχι όμως έτοιμο για δημόσια ανάρτηση. Μένει να επιβεβαιωθεί η άδεια χρήσης των φωτογραφιών. Μια συνεργάτιδα πρότεινε να συντομεύσουν τη σημείωση σε «Έτοιμο υλικό». Η συντονίστρια διαφώνησε: μια πιο σύντομη διατύπωση δεν πρέπει να δίνει στον επισκέπτη λανθασμένη εικόνα. Ζήτησε λοιπόν δύο χωριστές πληροφορίες, μία για τον έλεγχο και μία για την άδεια. Το χρονοδιάγραμμα της έκθεσης θα ανακοινωθεί μόνο αφού ολοκληρωθεί αυτή η διαδικασία."}, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-007-I10.json", "sha256": "bc7c6acf87cdef20ca752897e7818d264a2038f7d4d209a7088c5f64aa707d1e"}, "error_tags": ["COMPREHENSION"], "audio_job_ids": [], "competency_ids": ["B2-G04"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "reading", "prompt": "По тексту об архиве: почему Λένα не исправила подписи сразу?", "skills": ["reading"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-007-I10", "options": ["Δεν είχε ακόμη ελέγξει τα πρωτότυπα.", "Δεν είχε βρει κανένα λάθος.", "Είχε ήδη λάβει άδεια ανάρτησης."], "qa_risk": "HIGH", "unit_id": "U-B2-007", "version": "0.1.0", "language": "el+ru", "stimulus": {"text": "Η μικρή ομάδα του δημοτικού αρχείου ετοιμάζει μια ψηφιακή έκθεση για την καθημερινή ζωή της γειτονιάς. Διαβάζοντας τις περιγραφές, η Λένα εντόπισε δύο φωτογραφίες με λανθασμένη ημερομηνία. Δεν άλλαξε τις λεζάντες μόνη της, επειδή δεν είχε ακόμη ελέγξει τα πρωτότυπα. Ο Άρης, έχοντας συγκρίνει τα πρωτότυπα με τον κατάλογο, επιβεβαίωσε τη σωστή χρονολογία. Οι διορθωμένες λεζάντες στάλθηκαν έπειτα στη συντονίστρια. Η ομάδα αποφάσισε να διατηρήσει και ένα αντίγραφο της προηγούμενης έκδοσης, ώστε να είναι ορατή η αλλαγή.\\nΣτην τελική σημείωση αναφέρεται ότι το υλικό είναι ελεγμένο, όχι όμως έτοιμο για δημόσια ανάρτηση. Μένει να επιβεβαιωθεί η άδεια χρήσης των φωτογραφιών. Μια συνεργάτιδα πρότεινε να συντομεύσουν τη σημείωση σε «Έτοιμο υλικό». Η συντονίστρια διαφώνησε: μια πιο σύντομη διατύπωση δεν πρέπει να δίνει στον επισκέπτη λανθασμένη εικόνα. Ζήτησε λοιπόν δύο χωριστές πληροφορίες, μία για τον έλεγχο και μία για την άδεια. Το χρονοδιάγραμμα της έκθεσης θα ανακοινωθεί μόνο αφού ολοκληρωθεί αυτή η διαδικασία."}, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Явно назван непроведённый ею контроль оригиналов.", "rubric_id": "U-B2-007-RUBRIC", "error_tags": ["COMPREHENSION"], "answer_type": "mcq", "source_refs": [{"anchor": "§6.2ι lines251–255", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S01", "source_id": "N405", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}, {"anchor": "§2 lines13–23,37–43", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S02", "source_id": "N-F07-PART", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}], "item_version": "0.1.0", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-G04"], "model_response": null, "source_claim_ids": ["F07-B2-S01", "F07-B2-S02"], "success_criteria": [], "accepted_variants": [], "canonical_answers": ["Δεν είχε ακόμη ελέγξει τα πρωτότυπα."], "source_provenance": "Original GreekOS teaching task; narrow source claims only", "difficulty_estimate": "B2_AUTHOR_ESTIMATE_NOT_CALIBRATED", "response_evaluation": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}}, "prerequisite_ids": ["B1-G12", "B2-G02"], "source_claim_ids": ["F07-B2-S01", "F07-B2-S02"], "accepted_alternatives": []}	d88e566959148cc3ab401dba44cbfc3c4d2dc42e0177e2287418983067d08279	4836
U-B2-007-I11	core	U-B2-007	open_response	B2	course_practice	reading	f	REVIEW_REQUIRED	{B2-G04}	{B1-G12,B2-G02}	{}	{COMPREHENSION,CONTENT_OMISSION}	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "По тексту: объясните по-гречески, почему «Έτοιμο υλικό» вводит в заблуждение. Назовите завершённый и незавершённый этап.", "rubric": "U-B2-007-RUBRIC", "item_id": "U-B2-007-I11", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "semantic_rubric_with_abstention", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-007", "version": "0.1.0", "criteria": ["Проверка материала завершена", "Разрешение фотографий ещё не подтверждено", "Готовность к публикации не следует из проверки"], "stimulus": {"text": "Η μικρή ομάδα του δημοτικού αρχείου ετοιμάζει μια ψηφιακή έκθεση για την καθημερινή ζωή της γειτονιάς. Διαβάζοντας τις περιγραφές, η Λένα εντόπισε δύο φωτογραφίες με λανθασμένη ημερομηνία. Δεν άλλαξε τις λεζάντες μόνη της, επειδή δεν είχε ακόμη ελέγξει τα πρωτότυπα. Ο Άρης, έχοντας συγκρίνει τα πρωτότυπα με τον κατάλογο, επιβεβαίωσε τη σωστή χρονολογία. Οι διορθωμένες λεζάντες στάλθηκαν έπειτα στη συντονίστρια. Η ομάδα αποφάσισε να διατηρήσει και ένα αντίγραφο της προηγούμενης έκδοσης, ώστε να είναι ορατή η αλλαγή.\\nΣτην τελική σημείωση αναφέρεται ότι το υλικό είναι ελεγμένο, όχι όμως έτοιμο για δημόσια ανάρτηση. Μένει να επιβεβαιωθεί η άδεια χρήσης των φωτογραφιών. Μια συνεργάτιδα πρότεινε να συντομεύσουν τη σημείωση σε «Έτοιμο υλικό». Η συντονίστρια διαφώνησε: μια πιο σύντομη διατύπωση δεν πρέπει να δίνει στον επισκέπτη λανθασμένη εικόνα. Ζήτησε λοιπόν δύο χωριστές πληροφορίες, μία για τον έλεγχο και μία για την άδεια. Το χρονοδιάγραμμα της έκθεσης θα ανακοινωθεί μόνο αφού ολοκληρωθεί αυτή η διαδικασία."}, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-007-I11.json", "sha256": "15b5e12929bb4b126c0f0e577edf5fa463807772e6777075dee2c7b8ce459680"}, "error_tags": ["COMPREHENSION", "CONTENT_OMISSION"], "audio_job_ids": [], "competency_ids": ["B2-G04"], "model_response": "Το υλικό έχει ελεγχθεί, αλλά η άδεια χρήσης των φωτογραφιών δεν έχει επιβεβαιωθεί. Άρα δεν είναι ακόμη έτοιμο για δημόσια ανάρτηση.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "reading", "prompt": "По тексту: объясните по-гречески, почему «Έτοιμο υλικό» вводит в заблуждение. Назовите завершённый и незавершённый этап.", "skills": ["reading"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-007-I11", "options": [], "qa_risk": "HIGH", "unit_id": "U-B2-007", "version": "0.1.0", "language": "el+ru", "stimulus": {"text": "Η μικρή ομάδα του δημοτικού αρχείου ετοιμάζει μια ψηφιακή έκθεση για την καθημερινή ζωή της γειτονιάς. Διαβάζοντας τις περιγραφές, η Λένα εντόπισε δύο φωτογραφίες με λανθασμένη ημερομηνία. Δεν άλλαξε τις λεζάντες μόνη της, επειδή δεν είχε ακόμη ελέγξει τα πρωτότυπα. Ο Άρης, έχοντας συγκρίνει τα πρωτότυπα με τον κατάλογο, επιβεβαίωσε τη σωστή χρονολογία. Οι διορθωμένες λεζάντες στάλθηκαν έπειτα στη συντονίστρια. Η ομάδα αποφάσισε να διατηρήσει και ένα αντίγραφο της προηγούμενης έκδοσης, ώστε να είναι ορατή η αλλαγή.\\nΣτην τελική σημείωση αναφέρεται ότι το υλικό είναι ελεγμένο, όχι όμως έτοιμο για δημόσια ανάρτηση. Μένει να επιβεβαιωθεί η άδεια χρήσης των φωτογραφιών. Μια συνεργάτιδα πρότεινε να συντομεύσουν τη σημείωση σε «Έτοιμο υλικό». Η συντονίστρια διαφώνησε: μια πιο σύντομη διατύπωση δεν πρέπει να δίνει στον επισκέπτη λανθασμένη εικόνα. Ζήτησε λοιπόν δύο χωριστές πληροφορίες, μία για τον έλεγχο και μία για την άδεια. Το χρονοδιάγραμμα της έκθεσης θα ανακοινωθεί μόνο αφού ολοκληρωθεί αυτή η διαδικασία."}, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Требуется сопоставить два состояния, а не просто процитировать причастие.", "rubric_id": "U-B2-007-RUBRIC", "error_tags": ["COMPREHENSION", "CONTENT_OMISSION"], "answer_type": "open_response", "source_refs": [{"anchor": "§6.2ι lines251–255", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S01", "source_id": "N405", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}, {"anchor": "§2 lines13–23,37–43", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S02", "source_id": "N-F07-PART", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}], "item_version": "0.1.0", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-G04"], "model_response": "Το υλικό έχει ελεγχθεί, αλλά η άδεια χρήσης των φωτογραφιών δεν έχει επιβεβαιωθεί. Άρα δεν είναι ακόμη έτοιμο για δημόσια ανάρτηση.", "source_claim_ids": ["F07-B2-S01", "F07-B2-S02"], "success_criteria": ["Проверка материала завершена", "Разрешение фотографий ещё не подтверждено", "Готовность к публикации не следует из проверки"], "accepted_variants": [], "canonical_answers": [], "source_provenance": "Original GreekOS teaching task; narrow source claims only", "difficulty_estimate": "B2_AUTHOR_ESTIMATE_NOT_CALIBRATED", "response_evaluation": {"method": "semantic_rubric_with_abstention", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PE