U-B2-007-I14	core	U-B2-007	open_response	B2	course_practice	writing	f	REVIEW_REQUIRED	{B2-G04}	{B1-G12,B2-G02}	{}	{VERB_ASPECT,GENDER_AGREEMENT,CONTENT_OMISSION,PRAGMATICS_REGISTER}	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Напишите редактору 100–130 греческих слов. Дано: вы сверили список гостей; три имени исправлены; два адреса электронной почты ещё не подтверждены; приглашения пока не отправлены. Сообщите статус, предложите безопасный следующий шаг и попросите подтверждение адресов. Уместно используйте одну конструкцию с έχοντας и одну согласуемую форму. Не выдумывайте сроки.", "rubric": "U-B2-007-RUBRIC", "item_id": "U-B2-007-I14", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "semantic_rubric_with_abstention", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-007", "version": "0.1.0", "criteria": ["Все четыре исходных факта сохранены", "Безопасный следующий шаг и просьба подтвердить адреса", "Одна έχοντας-конструкция и согласуемая форма без подмены субъекта", "100–130 слов ориентир; отдельная оценка содержания и формы"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-007-I14.json", "sha256": "ad4ef3bbbe15d87765964ac6392953ea8d61963ad20841ba853bc561e72f1765"}, "error_tags": ["VERB_ASPECT", "GENDER_AGREEMENT", "CONTENT_OMISSION", "PRAGMATICS_REGISTER"], "audio_job_ids": [], "competency_ids": ["B2-G04"], "model_response": "Έχοντας ελέγξει τον κατάλογο των καλεσμένων, σας στέλνω μια σύντομη ενημέρωση. Τρία ονόματα έχουν διορθωθεί και εμφανίζονται πλέον σωστά στη νέα έκδοση. Ωστόσο, δύο διευθύνσεις ηλεκτρονικού ταχυδρομείου δεν έχουν ακόμη επιβεβαιωθεί. Οι προσκλήσεις δεν έχουν σταλεί, ώστε να αποφύγουμε την αποστολή τους σε λάθος παραλήπτες. Προτείνω να κρατήσουμε τον διορθωμένο κατάλογο ως προσωρινή έκδοση και να ολοκληρώσουμε πρώτα τον έλεγχο των διευθύνσεων. Θα μπορούσατε να ζητήσετε επιβεβαίωση από τους δύο καλεσμένους ή να μας δώσετε κάποιον άλλο τρόπο επικοινωνίας μαζί τους; Μόλις έχουμε τα σωστά στοιχεία, μπορούμε να αποφασίσουμε μαζί πότε θα γίνει η αποστολή. Δεν θα σημειώσω συγκεκριμένη ημερομηνία πριν λάβουμε την απάντησή τους.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "writing", "prompt": "Напишите редактору 100–130 греческих слов. Дано: вы сверили список гостей; три имени исправлены; два адреса электронной почты ещё не подтверждены; приглашения пока не отправлены. Сообщите статус, предложите безопасный следующий шаг и попросите подтверждение адресов. Уместно используйте одну конструкцию с έχοντας и одну согласуемую форму. Не выдумывайте сроки.", "skills": ["writing"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-007-I14", "options": [], "qa_risk": "HIGH", "unit_id": "U-B2-007", "version": "0.1.0", "language": "el+ru", "stimulus": null, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Модель — один вариант; объём не заменяет содержание.", "rubric_id": "U-B2-007-RUBRIC", "error_tags": ["VERB_ASPECT", "GENDER_AGREEMENT", "CONTENT_OMISSION", "PRAGMATICS_REGISTER"], "answer_type": "open_response", "source_refs": [{"anchor": "§6.2ι lines251–255", "status": "SOURCE_SCOPED",