U-B2-008-I10	core	U-B2-008	mcq	B2	course_practice	reading	f	CHOICE_KEY	{B2-G08}	{B1-G08,B1-G09}	{}	{COMPREHENSION}	{"type": "mcq", "level": "B2", "answer": ["Μπορεί να επικοινωνήσει με τη γραμματεία, χωρίς εγγύηση θέσης."], "module": "core", "prompt": "По тексту о мастерской: какое действие доступно человеку, который ещё не записался, и гарантирует ли оно место?", "rubric": "U-B2-008-RUBRIC", "item_id": "U-B2-008-I10", "options": ["Μια διαθέσιμη θέση.", "Η επισκευή κάθε συσκευής.", "Μπορεί να επικοινωνήσει με τη γραμματεία, χωρίς εγγύηση θέσης."], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "CHOICE_KEY", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-008", "version": "0.1.1", "criteria": [], "stimulus": {"text": "Το κέντρο της γειτονιάς ανακοίνωσε ότι το εργαστήριο επισκευής μικρών αντικειμένων θα γίνει σε δύο ομάδες. Οι ενδιαφερόμενοι που έχουν ήδη συμπληρώσει τη φόρμα θα λάβουν μήνυμα για την ώρα της συνάντησης. Όσοι δεν έχουν ακόμη δηλώσει συμμετοχή μπορούν να επικοινωνήσουν με τη γραμματεία, αλλά δεν υπάρχει εγγύηση ότι θα βρεθεί διαθέσιμη θέση.\\nΗ υπεύθυνη εξήγησε πως η αλλαγή έγινε επειδή ο χώρος είναι μικρός. Ζήτησε από τους συμμετέχοντες να μην φέρουν μεγάλες ηλεκτρικές συσκευές. Η τεχνίτρια με την οποία συνεργάζεται το κέντρο θα παρουσιάσει απλές επισκευές, ενώ ένας εθελοντής θα καταγράφει τις ερωτήσεις. Η τεχνίτρια, της οποίας η πρόταση αποτέλεσε τη βάση του προγράμματος, τόνισε ότι ο σκοπός δεν είναι να επισκευαστούν όλα τα αντικείμενα μέσα σε μία συνάντηση.\\nΈνα σύντομο μήνυμα στα κοινωνικά δίκτυα έγραφε ότι «όλοι θα εξυπηρετηθούν αμέσως». Η γραμματεία ζήτησε να διορθωθεί, γιατί ούτε η άμεση εξυπηρέτηση ούτε η αποδοχή κάθε συσκευής είχαν ανακοινωθεί. Στη νέα εκδοχή οι ενδιαφερόμενοι παραπέμπονται στη φόρμα και στην επικοινωνία με τη γραμματεία για τις εκκρεμείς ερωτήσεις."}, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-008-I10.json", "sha256": "85bb179cd3569eb84919064337c18e797d4559af5a1933cf48b30c872289a20f"}, "error_tags": ["COMPREHENSION"], "audio_job_ids": [], "competency_ids": ["B2-G08"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "reading", "prompt": "По тексту о мастерской: какое действие доступно человеку, который ещё не записался, и гарантирует ли оно место?", "skills": ["reading"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-008-I10", "options": ["Μια διαθέσιμη θέση.", "Η επισκευή κάθε συσκευής.", "Μπορεί να επικοινωνήσει με τη γραμματεία, χωρίς εγγύηση θέσης."], "qa_risk": "HIGH", "unit_id": "U-B2-008", "version": "0.1.1", "language": "el+ru", "stimulus": {"text": "Το κέντρο της γειτονιάς ανακοίνωσε ότι το εργαστήριο επισκευής μικρών αντικειμένων θα γίνει σε δύο ομάδες. Οι ενδιαφερόμενοι που έχουν ήδη συμπληρώσει τη φόρμα θα λάβουν μήνυμα για την ώρα της συνάντησης. Όσοι δεν έχουν ακόμη δηλώσει συμμετοχή μπορούν να επικοινωνήσουν με τη γραμματεία, αλλά δεν υπάρχει εγγύηση ότι θα βρεθεί διαθέσιμη θέση.\\nΗ υπεύθυνη εξήγησε πως η αλλαγή έγινε επειδή ο χώρος είναι μικρός. Ζήτησε από τους συμμετέχοντες να μην φέρουν μεγάλες ηλεκτρικές συσκευές. Η τεχνίτρια με την οποία συνεργάζεται το κέντρο θα παρουσιάσει απλές επισκευές, ενώ ένας εθελοντής θα καταγράφει τις ερωτήσεις. Η τεχνίτρια, της οποίας η πρόταση αποτέλεσε τη βάση του προγράμματος, τόνισε ότι ο σκοπός δεν είναι να επισκευαστούν όλα τα αντικείμενα μέσα σε μία συνάντηση.\\nΈνα σύντομο μήνυμα στα κοινωνικά δίκτυα έγραφε ότι «όλοι θα εξυπηρετηθούν αμέσως». Η γραμματεία ζήτησε να διορθωθεί, γιατί ούτε η άμεση εξυπηρέτηση ούτε η αποδοχή κάθε συσκευής είχαν ανακοινωθεί. Στη νέα εκδοχή οι ενδιαφερόμενοι παραπέμπονται στη φόρμα και στην επικοινωνία με τη γραμματεία για τις εκκρεμείς ερωτήσεις."}, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Текст разрешает контакт, но не гарантирует место или ремонт.", "rubric_id": "U-B2-008-RUBRIC", "error_tags": ["COMPREHENSION"], "answer_type": "mcq", "source_refs": [{"anchor": "§5.6 lines65–75", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S03", "source_id": "N410", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}, {"anchor": "§5.2α lines18–24", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S04", "source_id": "N404", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}, {"anchor": "§5.2γ lines52–55", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S05", "source_id": "N404", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_SCOPED"}], "item_version": "0.1.1", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-G08"], "model_response": null, "source_claim_ids": ["F07-B2-S03", "F07-B2-S04", "F07-B2-S05"], "success_criteria": [], "accepted_variants": [], "canonical_answers": ["Μπορεί να επικοινωνήσει με τη γραμματεία, χωρίς εγγύηση θέσης."], "source_provenance": "Original GreekOS teaching task; narrow source claims only", "difficulty_estimate": "B2_AUTHOR_ESTIMATE_NOT_CALIBRATED", "response_evaluation": {"method": "key_with_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer":