U-B2-008-I14	core	U-B2-008	open_response	B2	course_practice	writing	f	REVIEW_REQUIRED	{B2-G08}	{B1-G08,B1-G09}	{}	{SYNTAX,PRAGMATICS_REGISTER,CONTENT_OMISSION}	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Напишите 100–130 слов группе участников. Факты: организатор сообщил, что встреча переносится в онлайн; только зарегистрированные получат ссылку; время пока не подтверждено; он попросил не распространять старое объявление. Передайте сообщение и просьбу разными конструкциями, объясните ограничение группы и предложите способ уточнить время.", "rubric": "U-B2-008-RUBRIC", "item_id": "U-B2-008-I14", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "semantic_rubric_with_abstention", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-008", "version": "0.1.0", "criteria": ["Сохранены четыре исходных факта", "Сообщение с ότι/πως и просьба с να μην различены", "Ссылка только зарегистрированным", "Способ уточнения без выдуманной даты", "100–130 слов ориентир"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-008-I14.json", "sha256": "c406dbcc55281e0b7cbfda2acf4a04e3bdd1d0c5b944abd990a39a06e6bf208b"}, "error_tags": ["SYNTAX", "PRAGMATICS_REGISTER", "CONTENT_OMISSION"], "audio_job_ids": [], "competency_ids": ["B2-G08"], "model_response": "Ο διοργανωτής μάς ενημέρωσε ότι η συνάντηση θα γίνει διαδικτυακά. Οι συμμετέχοντες που έχουν ήδη εγγραφεί θα λάβουν τον σύνδεσμο για τη σύνδεση. Η ώρα δεν έχει ακόμη επιβεβαιωθεί, γι’ αυτό δεν πρέπει να θεωρήσουμε ότι ισχύει το προηγούμενο πρόγραμμα. Ο διοργανωτής ζήτησε επίσης να μην προωθούμε την παλιά ανακοίνωση, ώστε να αποφύγουμε τη σύγχυση. Αν έχετε απορία σχετικά με την ώρα, προτείνω να επικοινωνήσετε μαζί του ή να περιμένετε το νέο μήνυμα της ομάδας. Δεν γνωρίζουμε ακόμη πότε ακριβώς θα σταλεί αυτή η ενημέρωση. Παρακαλώ ελέγξτε τα μηνύματά σας πριν από τη συνάντηση και ενημερώστε μας αν έχετε εγγραφεί αλλά δεν λάβετε σύνδεσμο. Έτσι θα μπορέσουμε να εντοπίσουμε το πρόβλημα χωρίς να κυκλοφορούν διαφορετικές εκδοχές του προγράμματος.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "writing", "prompt": "Напишите 100–130 слов группе участников. Факты: организатор сообщил, что встреча переносится в онлайн; только зарегистрированные получат ссылку; время пока не подтверждено; он попросил не распространять старое объявление. Передайте сообщение и просьбу разными конструкциями, объясните ограничение группы и предложите способ уточнить время.", "skills": ["writing"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-008-I14", "options": [], "qa_risk": "HIGH", "unit_id": "U-B2-008", "version": "0.1.0", "language": "el+ru", "stimulus": null, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Модель не исчерпывает допустимые формулировки; оценивать точность ограничений.", "rubric_id": "U-B2-008-RUBRIC", "error_tags": ["SYNTAX", "PRAGMATICS_REGISTER", "CONTENT_OMISSION"], "answer_type": "open_response", "source_refs": [{"anchor": "§5.6 lines65–75", "status": "SOURCE_SCOPED", "claim_id": "F07-B2-S03", "source_id": "N410", "checked_on": "2026-10-20", "evidence_type": "PRIMARY_GRAMMAR_S