U-B2-010-I02	core	U-B2-010	mcq	B2	course_practice	guided_practice	f	CHOICE_KEY	{B2-V01}	{B1-V01}	{}	{COMPREHENSION}	{"type": "mcq", "level": "B2", "answer": ["δοκιμαστικές πολιτιστικές συναντήσεις"], "module": "core", "prompt": "Что планируется в Певки?", "rubric": null, "item_id": "U-B2-010-I02", "options": ["μόνιμη απαγόρευση εκδηλώσεων", "δοκιμαστικές πολιτιστικές συναντήσεις", "υποχρεωτική συνδρομή"], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_semantic_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "CHOICE_KEY", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-010", "version": "0.1.0", "criteria": [], "stimulus": "Στη φανταστική συνοικία Πεύκη μια ομάδα κατοίκων προτείνει να χρησιμοποιείται η αυλή του παλιού σχολείου για δωρεάν πολιτιστικές συναντήσεις. Η ιδέα συνδυάζει προβολές ταινιών, ανταλλαγή βιβλίων και εργαστήρια επισκευής. Οι διοργανωτές υποστηρίζουν ότι έτσι θα περιοριστούν τα απορρίμματα και θα γνωριστούν οι γείτονες. Δεν έχουν όμως μετρήσει ακόμη την ποσότητα των αντικειμένων που θα επαναχρησιμοποιηθούν.\\nΣτην ανακοίνωσή τους ζητούν εθελοντές και μικρές δωρεές. Διευκρινίζουν ότι η οικονομική ενίσχυση δεν αποτελεί προϋπόθεση συμμετοχής. Μια κάτοικος συμφωνεί με τον κοινωνικό στόχο, αλλά φοβάται ότι η δυνατή μουσική θα δυσκολεύει όσους εργάζονται νωρίς. Προτείνει να τελειώνουν οι εκδηλώσεις στις εννέα. Άλλοι ζητούν πρόσβαση χωρίς σκαλοπάτια και αναλυτικό πρόγραμμα, ώστε να μπορούν να σχεδιάσουν την επίσκεψή τους.\\nΈνα τοπικό ιστολόγιο δημοσίευσε τίτλο «Η γειτονιά λύνει οριστικά το πρόβλημα των απορριμμάτων». Στο ίδιο άρθρο, ωστόσο, αναφέρεται ότι πρόκειται για δοκιμή ενός μήνα. Η ομάδα απάντησε ότι θα αξιολογήσει την προσέλευση, τα έξοδα και τα παράπονα πριν αποφασίσει αν θα συνεχίσει. Η επιτυχία θα εξαρτηθεί όχι μόνο από τον αριθμό επισκεπτών αλλά και από το αν διαφορετικές ομάδες κατοίκων μπορούν πραγματικά να συμμετέχουν.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-010-I02.json", "sha256": "671dc43af3605df615aa04d0228b55e599016fbac1ed28b8cd63dadb60cfac2b"}, "error_tags": ["COMPREHENSION"], "audio_job_ids": [], "competency_ids": ["B2-V01"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "guided", "prompt": "Что планируется в Певки?", "skills": ["reading"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-010-I02", "options": ["μόνιμη απαγόρευση εκδηλώσεων", "δοκιμαστικές πολιτιστικές συναντήσεις", "υποχρεωτική συνδρομή"], "unit_id": "U-B2-010", "version": "0.1.0", "language": "el+ru", "stimulus": "Στη φανταστική συνοικία Πεύκη μια ομάδα κατοίκων προτείνει να χρησιμοποιείται η αυλή του παλιού σχολείου για δωρεάν πολιτιστικές συναντήσεις. Η ιδέα συνδυάζει προβολές ταινιών, ανταλλαγή βιβλίων και εργαστήρια επισκευής. Οι διοργανωτές υποστηρίζουν ότι έτσι θα περιοριστούν τα απορρίμματα και θα γνωριστούν οι γείτονες. Δεν έχουν όμως μετρήσει ακόμη την ποσότητα των αντικειμένων που θα επαναχρησιμοποιηθούν.\\nΣτην ανακοίνωσή τους ζητούν εθελοντές και μικρές δωρεές. Διευκρινίζουν ότι η οικονομική ενίσχυση δεν αποτελεί προϋπόθεση συμμετοχής. Μια κάτοικος συμφωνεί με τον κοινωνικό στόχο, αλλά φοβάται ότι η δυνατή μουσική θα δυσκολεύει όσους εργάζονται νωρίς. Προτείνει να τελειώνουν οι εκδηλώσεις στις εννέα. Άλλοι ζητούν πρόσβαση χωρίς σκαλοπάτια και αναλυτικό πρόγραμμα, ώστε να μπορούν να σχεδιάσουν την επίσκεψή τους.\\nΈνα τοπικό ιστολόγιο δημοσίευσε τίτλο «Η γειτονιά λύνει οριστικά το πρόβλημα των απορριμμάτων». Στο ίδιο άρθρο, ωστόσο, αναφέρεται ότι πρόκειται για δοκιμή ενός μήνα. Η ομάδα απάντησε ότι θα αξιολογήσει την προσέλευση, τα έξοδα και τα παράπονα πριν αποφασίσει αν θα συνεχίσει. Η επιτυχία θα εξαρτηθεί όχι μόνο από τον αριθμό επισκεπτών αλλά και από το αν διαφορετικές ομάδες κατοίκων μπορούν πραγματικά να συμμετέχουν.", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Это пробный проект, не окончательное решение.", "error_tags": ["COMPREHENSION"], "answer_type": "mcq", "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-22", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "item_version": "0.1.0", "privacy_risk": "FICTIONAL_DETAILS_ONLY", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-V01"], "error_tag_policy": "Candidate categories, not automatic learner diagnosis; use criterion evidence; never infer pronunciation from uncertain ASR", "estimated_effort": null, "source_claim_ids": ["U-B2-010-SCOPE"], "target_objective": "Извлекать интересы участников и ограничения аргумента", "accepted_variants": [], "canonical_answers": ["δοκιμαστικές πολιτιστικές συναντήσεις"], "difficulty_estimate": "UNVALIDATED", "response_evaluation": {"method": "key_with_semantic_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "estimated_effort_status": "EDITOR_OR_PILOT_DECISION_REQUIRED"}, "prerequisite_ids": ["B1-V01"], "source_claim_ids": ["U-B2-010-SCOPE"], "accepted_alternatives": []}	0057569206e5b9c9e0cb9b85a84287fc7dc06959f43f3a3d4fb892d1cf9ba5d8	4881
