ικρότερες ομάδες, αν μπορούμε να χρησιμοποιήσουμε τον χώρο δύο φορές. Μόλις έμαθα ότι η πρώτη συνάντηση θα αρχίσει στις επτά, όχι στις έξι. Ας ελέγξουμε αν προλαβαίνουμε και τη δεύτερη ομάδα.", "error_tag_policy": "Candidate categories, not automatic learner diagnosis; use criterion evidence; never infer pronunciation from uncertain ASR", "estimated_effort": null, "source_claim_ids": ["U-B2-016-SCOPE"], "success_criteria": ["ограничение 12 вместо 24 учтено", "собственная поправка или обновление времени ясно отделены от исходного плана", "связный вывод", "слушатель восстановил окончательный план"], "target_objective": "Самостоятельно исправлять значимую ошибку без разрушения речи", "accepted_variants": [], "canonical_answers": [], "scoring_constraint": "No acoustic score from text or ASR alone; transcription may support content-only feedback", "difficulty_estimate": "UNVALIDATED", "response_evaluation": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "estimated_effort_status": "EDITOR_OR_PILOT_DECISION_REQUIRED"}, "prerequisite_ids": ["B1-P01", "B2-SP01"], "source_claim_ids": ["U-B2-016-SCOPE"], "accepted_alternatives": []}	1e11b840fbd6ce77b65049fd00aaef9ba40207306b01789c91c6a585e5471331	4959
U-B2-017-I01	core	U-B2-017	open_response	B2	course_practice	reading	f	REVIEW_REQUIRED	{B2-R01}	{B1-R01,B2-G08}	{}	{CONDITION_LOSS_CANDIDATE}	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Διάβασε: «Η δοκιμή φαίνεται χρήσιμη, εφόσον υπάρχει προσωπικό». Τι υποστηρίζεται και τι δεν εγγυάται ο συντάκτης;", "rubric": "U-B2-017-RUBRIC", "item_id": "U-B2-017-I01", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-017", "version": "0.1.0", "criteria": ["условие сохранено", "отсутствие гарантии указано"], "stimulus": null, "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-017-I01.json", "sha256": "44c2011b69503118c22e1b00816b049b6b68e2d3c51673f6da80880889f334b7"}, "error_tags": ["CONDITION_LOSS_CANDIDATE"], "audio_job_ids": [], "competency_ids": ["B2-R01"], "model_response": "Υποστηρίζεται μια δοκιμή υπό τον όρο ότι υπάρχει προσωπικό. Δεν εγγυάται την επιτυχία της.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "diagnostic", "prompt": "Διάβασε: «Η δοκιμή φαίνεται χρήσιμη, εφόσον υπάρχει προσωπικό». Τι υποστηρίζεται και τι δεν εγγυάται ο συντάκτης;", "skills": ["reading"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-017-I01", "options": [], "unit_id": "U-B2-017", "version": "0.1.0", "language": "el+ru", "stimulus": null, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "