U-B2-017-I02	core	U-B2-017	mcq	B2	course_practice	guided_practice	f	CHOICE_KEY	{B2-R01}	{B1-R01,B2-G08}	{}	{AUTHOR_STANCE_CANDIDATE}	{"type": "mcq", "level": "B2", "answer": ["Να δοκιμαστεί το ωράριο με όρους και αξιολόγηση."], "module": "core", "prompt": "Ποια είναι η βασική θέση του άρθρου;", "rubric": null, "item_id": "U-B2-017-I02", "options": ["Να δοκιμαστεί το ωράριο με όρους και αξιολόγηση.", "Να παραταθεί αμέσως το ωράριο όλων των βιβλιοθηκών.", "Να καταργηθεί κάθε βραδινή λειτουργία.", "Να αντικατασταθεί ο δανεισμός με ψηφιακές υπηρεσίες."], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "key_with_semantic_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "CHOICE_KEY", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-017", "version": "0.1.0", "criteria": [], "stimulus": "Μια βιβλιοθήκη που μένει ανοιχτή\\n[1] Όταν ανακοινώθηκε ότι η βιβλιοθήκη της γειτονιάς θα λειτουργούσε δύο βράδια την εβδομάδα, αρκετοί κάτοικοι μίλησαν για περιττή δαπάνη. Κατά τη γνώμη τους, όποιος θέλει να δανειστεί ένα βιβλίο μπορεί να το κάνει το πρωί. Η άποψη αυτή, όμως, θεωρεί δεδομένο ότι όλοι διαθέτουν τον ίδιο ελεύθερο χρόνο. Για έναν εργαζόμενο με σπαστό ωράριο ή για έναν γονέα που φροντίζει μικρά παιδιά, η πρωινή πρόσβαση συχνά υπάρχει μόνο στα χαρτιά.\\n[2] Η πρόταση δεν προβλέπει απλώς περισσότερο χρόνο δανεισμού. Προβλέπει έναν ήσυχο χώρο μελέτης και υποστήριξη για όσους δυσκολεύονται να αναζητήσουν πληροφορίες στο διαδίκτυο. Δεν σημαίνει ότι οι υπάλληλοι θα συμπληρώνουν προσωπικές αιτήσεις αντί των επισκεπτών. Θα τους δείχνουν πώς να εντοπίζουν μια αξιόπιστη πηγή και πώς να αποφεύγουν την κοινοποίηση προσωπικών δεδομένων. Έτσι, η βιβλιοθήκη θα μπορούσε να καλύψει ανάγκες που δεν αντιμετωπίζονται με έναν απλό δανεισμό.\\n[3] Υπάρχουν, βέβαια, βάσιμες αντιρρήσεις. Το επιπλέον ωράριο απαιτεί προσωπικό, θέρμανση και ασφαλή επιστροφή των εργαζομένων. Αν στηριχθεί αποκλειστικά σε απλήρωτη εθελοντική εργασία, δύσκολα θα διατηρηθεί. Ούτε αρκεί να μετρηθεί ο αριθμός των επισκεπτών την πρώτη εβδομάδα: μια εκδήλωση εγκαινίων μπορεί να γεμίσει τον χώρο χωρίς να αποδεικνύει σταθερή ανάγκη. Χρειάζονται στοιχεία για επαναλαμβανόμενες επισκέψεις, για τις υπηρεσίες που χρησιμοποιούνται και για ανθρώπους που εξακολουθούν να αποκλείονται.\\n[4] Γι’ αυτό προτείνουμε μια τρίμηνη δοκιμή, με εξασφαλισμένη αμοιβή του προσωπικού και δημόσια αξιολόγηση. Οι κάτοικοι θα μπορούν να προτείνουν διαφορετικές ημέρες, χωρίς να αναμένεται ότι μία λύση θα εξυπηρετεί τους πάντες. Αν διαπιστωθεί μικρή προσέλευση, πρέπει πρώτα να εξεταστούν η ενημέρωση και η συγκοινωνιακή σύνδεση, προτού κριθεί αποτυχημένο το μέτρο. Αντίστοιχα, η μεγάλη προσέλευση δεν δικαιολογεί από μόνη της οποιοδήποτε κόστος.\\n[5] Η βιβλιοθήκη δεν μπορεί να λύσει όλα τα προβλήματα της γειτονιάς. Μπορεί, ωστόσο, να δοκιμάσει έναν πιο δίκαιο τρόπο πρόσβασης στη γνώση. Το ερώτημα δεν είναι αν ένα βραδινό ωράριο είναι πάντοτε καλό ή κακό, αλλά υπό ποιες προϋποθέσεις προσφέρει ουσιαστικό όφελος. Η υπεύθυνη απόφαση χρειάζεται και κοινωνικό στόχο και ειλικρινή αποτίμηση των περιορισμών της.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-017-I02.json", "sha256": "4fd3b3dacc8202b50db3b4c95b22c075555e2ecb3098047b8f2972fd5dcf4006"}, "error_tags": ["AUTHOR_STANCE_CANDIDATE"], "audio_job_ids": [], "competency_ids": ["B2-R01"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "guided", "prompt": "Ποια είναι η βασική θέση του άρθρου;", "skills": ["reading"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-017-I02", "options": ["Να δοκιμαστεί το ωράριο με όρους και αξιολόγηση.", "Να παραταθεί αμέσως το ωράριο όλων των βιβλιοθηκών.", "Να καταργηθεί κάθε βραδινή λειτουργία.", "Να αντικατασταθεί ο δανεισμός με ψηφιακές υπηρεσίες."], "unit_id": "U-B2-017", "version": "0.1.0", "language": "el+ru", "stimulus": "Μια βιβλιοθήκη που μένει ανοιχτή\\n[1] Όταν ανακοινώθηκε ότι η βιβλιοθήκη της γειτονιάς θα λειτουργούσε δύο βράδια την εβδομάδα, αρκετοί κάτοικοι μίλησαν για περιττή δαπάνη. Κατά τη γνώμη τους, όποιος θέλει να δανειστεί ένα βιβλίο μπορεί να το κάνει το πρωί. Η άποψη αυτή, όμως, θεωρεί δεδομένο ότι όλοι διαθέτουν τον ίδιο ελεύθερο χρόνο. Για έναν εργαζόμενο με σπαστό ωράριο ή για έναν γονέα που φροντίζει μικρά παιδιά, η πρωινή πρόσβαση συχνά υπάρχει μόνο στα χαρτιά.\\n[2] Η πρόταση δεν προβλέπει απλώς περισσότερο χρόνο δανεισμού. Προβλέπει έναν ήσυχο χώρο μελέτης και υποστήριξη για όσους δυσκολεύονται να αναζητήσουν πληροφορίες στο διαδίκτυο. Δεν σημαίνει ότι οι υπάλληλοι θα συμπληρώνουν προσωπικές αιτήσεις αντί των επισκεπτών. Θα τους δείχνουν πώς να εντοπίζουν μια αξιόπιστη πηγή και πώς να αποφεύγουν την κοινοποίηση προσωπικών δεδομένων. Έτσι, η βιβλιοθήκη θα μπορούσε να καλύψει ανάγκες που δεν αντιμετωπίζονται με έναν απλό δανεισμό.\\n[3] Υπάρχουν, βέβαια, βάσιμες αντιρρήσεις. Το επιπλέον ωράριο απαιτεί προσωπικό, θέρμανση και ασφαλή επιστροφή των εργαζομένων. Αν στηριχθεί αποκλειστικά σε απλήρωτη εθελοντική εργασία, δύσκολα θα διατηρηθεί. Ούτε αρκεί να μετρηθεί ο αριθμός των επισκεπτών την πρώτη εβδομάδα: μια εκδήλωση εγκαινίων μπορεί να γεμίσει τον χώρο χωρίς να αποδεικνύει σταθερή ανάγκη. Χρειάζονται στοιχεία για επαναλαμβανόμενες επισκέψεις, για τις υπηρεσίες που χρησιμοποιούνται και για ανθρώπους που εξακολουθούν να αποκλείονται.\\n[4] Γι’ αυτό προτείνουμε μια τρίμηνη δοκιμή, με εξασφαλισμένη αμοιβή του προσωπικού και δημόσια αξιολόγηση. Οι κάτοικοι θα μπορούν να προτείνουν διαφορετικές ημέρες, χωρίς να αναμένεται ότι μία λύση θα εξυπηρετεί τους πάντες. Αν διαπιστωθεί μικρή προσέλευση, πρέπει πρώτα να εξεταστούν η ενημέρωση και η συγκοινωνιακή σύνδεση, προτού κριθεί αποτυχημένο το μέτρο. Αντίστοιχα, η μεγάλη προσέλευση δεν δικαιολογεί από μόνη της οποιοδήποτε κόστος.\\n[5] Η βιβλιοθήκη δεν μπορεί να λύσει όλα τα προβλήματα της γειτονιάς. Μπορεί, ωστόσο, να δοκιμάσει έναν πιο δίκαιο τρόπο πρόσβασης στη γνώση. Το ερώτημα δεν είναι αν ένα βραδινό ωράριο είναι πάντοτε καλό ή κακό, αλλά υπό ποιες προϋποθέσεις προσφέρει ουσιαστικό όφελος. Η υπεύθυνη απόφαση χρειάζεται και κοινωνικό στόχο και ειλικρινή αποτίμηση των περιορισμών της.", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Το συμπέρασμα της §5 συνδυάζεται με την πρόταση της §4. Η καθολική επέκταση, η απόρριψη και ο αποκλειστικά ψηφιακός στόχος δεν υποστηρίζονται.", "error_tags": ["AUTHOR_STANCE_CANDIDATE"], "answer_type": "mcq", "publishable": false, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "item_version": "0.1.0", "privacy_risk": "FICTIONAL_DETAILS_ONLY", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-R01"], "error_tag_policy": "Item-specific author hypothesis; actual learner error requires quoted response evidence and human/assessor decision. ASR uncertainty excluded.", "estimated_effort": null, "source_claim_ids": ["U-B2-017-SCOPE"], "target_objective": "Различать позицию, аргумент, ограничение и недоказанный вывод", "accepted_variants": [], "canonical_answers": ["Να δοκιμαστεί το ωράριο με όρους και αξιολόγηση."], "difficulty_estimate": "UNVALIDATED", "response_evaluation": {"method": "key_with_semantic_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "estimated_effort_status": "EDITOR_OR_PILOT_DECISION_REQUIRED"}, "prerequisite_ids": ["B1-R01", "B2-G08"], "source_claim_ids": ["U-B2-017-SCOPE"], "accepted_alternatives": []}	07819e42965d6554e24b429ba6bb9306f7460f39a96fbe4b1e2d9f6ae84d91f3	4961
