 null, "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Η καταγραφή εξηγεί το επόμενο αποτέλεσμα· οι άλλες επιλογές αναιρούν το κείμενο ή δεν συνδέονται.", "error_tags": ["DISCOURSE_RELATION_CANDIDATE"], "answer_type": "mcq", "publishable": false, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "item_version": "0.1.0", "privacy_risk": "FICTIONAL_DETAILS_ONLY", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-R02"], "error_tag_policy": "Item-specific author hypothesis; actual learner error requires quoted response evidence and human/assessor decision. ASR uncertainty excluded.", "estimated_effort": null, "source_claim_ids": ["U-B2-022-SCOPE"], "target_objective": "Восстанавливать связи и отсылки между предложениями", "accepted_variants": [], "canonical_answers": ["Παράλληλα αποφασίστηκε να καταγράφονται όσοι δεν εξυπηρετούνται."], "difficulty_estimate": "UNVALIDATED", "response_evaluation": {"method": "key_with_semantic_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "estimated_effort_status": "EDITOR_OR_PILOT_DECISION_REQUIRED"}, "prerequisite_ids": ["B2-R01", "B2-G07"], "source_claim_ids": ["U-B2-022-SCOPE"], "accepted_alternatives": []}	3d90747748f566d61bd017ca9b7b8ea94a94cbbff5f3c7d2b64e8a126726b6e0	5022
U-B2-022-I05	core	U-B2-022	open_response	B2	course_practice	guided_practice	f	REVIEW_REQUIRED	{B2-R02}	{B2-R01,B2-G07}	{}	{CAUSAL_OVERCLAIM_CANDIDATE}	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Γιατί η περίληψη «Το εργαστήριο απέδειξε ότι ο εθελοντισμός μειώνει τα απορρίμματα» είναι ανακριβής; Διόρθωσέ την.", "rubric": "U-B2-022-RUBRIC", "item_id": "U-B2-022-I05", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-022", "version": "0.1.0", "criteria": ["отсутствие измеренного результата", "сохранена ограниченная польза", "нет новой гиперболы"], "stimulus": "Μαθαίνοντας να επισκευάζουμε\\n[1] Ένα μικρό εργαστήριο επισκευών άρχισε να λειτουργεί σε έναν χώρο της γειτονιάς. Οι συμμετέχοντες φέρνουν χαλασμένα καθημερινά αντικείμενα και προσπαθούν να τα επισκευάσουν με καθοδήγηση. Ο στόχος δεν είναι να αντικατασταθούν οι επαγγελματίες τεχνίτες, αλλά να μάθουν οι πολίτες πότε μια απλή παρέμβαση είναι ασφαλής και πότε χρειάζεται ειδικός.\\n[2] Η πρώτη δυσκολία ήταν η λανθασμένη προσδοκία ότι κάθε αντικείμενο θα επισκευαζόταν δωρεάν. Οι οργανωτές διευκρίνισαν ότι προσφέρεται χρόνος και γνώση, όχι εγγύηση αποτελέσματος. Αν χρειάζονται ανταλλακτικά, ο ιδιοκτήτης ενημερώνεται για το πιθανό κόστος πριν αποφασίσει. Καμία εργασία που απαιτεί ειδική άδεια δεν πραγματοποιείται από ανειδίκευτους συμμετέχοντες.\\n[3] Το σημαντικότερο όφελος δεν ήταν πάντα ένα αντικείμενο που λειτουργούσε ξανά. Μερικοί έμαθαν να περιγράφουν με ακρίβεια το πρόβλημα, άλλοι κατάλαβαν γιατί μια επισκευή δεν ήταν οικονομικά λογική. Αυτή η γνώση μπορεί να βοηθήσει και σε μελλοντική αγορά. Ωστόσο, οι οργανωτές δεν έχουν ακόμη στοιχεία που να δείχνουν αν μειώθηκαν συνολικά τα απορρίμματα της περιοχής.\\n[4] Για να συνεχιστεί η δράση, χρειάζεται σταθερός χώρος και οργάνωση των ραντεβού. Η μεγάλη συμμετοχή μιας ημέρας δημιουργεί ενθουσιασμό, αλλά μπορεί να οδηγήσει σε βιαστικές παρεμβάσεις αν δεν υπάρχουν αρκετοί καθοδηγητές. Γι’ αυτό αποφασίστηκε περιορισμένος αριθμός θέσεων και καταγραφή των αιτημάτων που δεν εξυπηρετούνται.\\n[5] Η πρωτοβουλία δείχνει ότι η περιβαλλοντική εκπαίδευση μπορεί να συνδεθεί με πρακτικές δεξιότητες. Δεν αποδεικνύει, όμως, ότι κάθε επισκευή συμφέρει ούτε ότι ο εθελοντισμός αρκεί για όλα. Η αξία της θα κριθεί από την ασφάλεια, τη σταθερότητα και όσα οι συμμετέχοντες μπορούν πλέον να κάνουν ή να εξηγήσουν μόνοι τους.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-022-I05.json", "sha256": "f4a9cda7891545390def1be7f62d3abc4259755da92491ce6aa9e91e207851ac"}, "error_tags": ["CAUSAL_OVERCLAIM_CANDIDATE"], "audio_job_ids": [], "competency_ids": ["B2-R02"], "model_response": "Δεν υπάρχουν στοιχεία συνολικής μείωσης απορριμμάτων. Το εργαστήριο συνδέει περιβαλλοντική εκπαίδευση με πρακτικές δεξιότητες, χωρίς να αποδεικνύει ότι ο εθελοντισμός αρκεί.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "guided", "prompt": "Γιατί η περίληψη «Το εργαστήριο απέδειξε ότι ο εθελοντισμός μειώνει τα απορρίμματα» είναι ανακριβής; Διόρθωσέ την.", "skills": ["writing"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-022-I05", "options": [], "unit_id": "U-B2-022", "version": "0.1.0", "language": "el+ru", "stimulus": "Μαθαίνοντας να επισκευάζουμε\\n[1] Ένα μικρό εργαστήριο επισκευών άρχισε να λειτουργεί σε έναν χώρο της γειτονιάς. Οι συμμετέχοντες φέρνουν χαλασμένα καθημερινά αντικείμενα και προσπαθούν να τα επισκευάσουν με καθοδήγηση. Ο στόχος δεν είναι να αντικατασταθούν οι επαγγελμα