 "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Αρχική εντύπωση, αντίθεση, συμπέρασμα.", "error_tags": ["DISCOURSE_ORDER_CANDIDATE"], "answer_type": "short_answer", "publishable": false, "source_refs": [{"anchor": "General objectives lines81–88; listening92–95; reading97–98", "source_id": "CP09-B2", "checked_on": "2026-10-24", "claim_scope": "Bounded grammatical principle or level descriptor only; original Greek examples/tasks and scoring are author proposals, not source-approved."}], "item_version": "0.1.0", "privacy_risk": "FICTIONAL_DETAILS_ONLY", "review_status": "AUTHOR_SELF_REVIEWED_NOT_INDEPENDENT", "competency_ids": ["B2-R02"], "error_tag_policy": "Item-specific author hypothesis; actual learner error requires quoted response evidence and human/assessor decision. ASR uncertainty excluded.", "estimated_effort": null, "source_claim_ids": ["U-B2-022-SCOPE"], "target_objective": "Восстанавливать связи и отсылки между предложениями", "accepted_variants": ["Β Γ Α", "Β, Γ, Α"], "canonical_answers": ["Β-Γ-Α"], "difficulty_estimate": "UNVALIDATED", "response_evaluation": {"method": "key_with_semantic_review_fallback", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "estimated_effort_status": "EDITOR_OR_PILOT_DECISION_REQUIRED"}, "prerequisite_ids": ["B2-R01", "B2-G07"], "source_claim_ids": ["U-B2-022-SCOPE"], "accepted_alternatives": ["Β Γ Α", "Β, Γ, Α"]}	e50f04e3be5a7401efc25ee11a9f06b49dc3dbc6fefe5468558e6c616b2ddcfe	5024
U-B2-022-I07	core	U-B2-022	open_response	B2	course_practice	active_recall	f	REVIEW_REQUIRED	{B2-R02}	{B2-R01,B2-G07}	{}	{SUMMARY_FIDELITY_CANDIDATE}	{"type": "open_response", "level": "B2", "answer": [], "module": "core", "prompt": "Γράψε περίληψη 110–140 λέξεων για ενημερωτικό δελτίο. Διατήρησε στόχο, οφέλη και δύο περιορισμούς. Μην προσθέσεις προσωπική σύσταση.", "rubric": "U-B2-022-RUBRIC", "item_id": "U-B2-022-I07", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "analytic_rubric_review", "normalization": ["NFC", "trim", "casefold", "collapse_whitespace"], "strip_accents": false, "model_is_exhaustive": false, "unlisted_plausible_answer": "REVIEW_REQUIRED_NO_AUTOMATIC_PENALTY"}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": "U-B2-022", "version": "0.1.0", "criteria": ["στόχος", "οφέλη", "δύο περιορισμοί", "σύνδεση και όχι κατάλογος", "χωρίς προσωπική γνώμη"], "stimulus": "Μαθαίνοντας να επισκευάζουμε\\n[1] Ένα μικρό εργαστήριο επισκευών άρχισε να λειτουργεί σε έναν χώρο της γειτονιάς. Οι συμμετέχοντες φέρνουν χαλασμένα καθημερινά αντικείμενα και προσπαθούν να τα επισκευάσουν με καθοδήγηση. Ο στόχος δεν είναι να αντικατασταθούν οι επαγγελματίες τεχνίτες, αλλά να μάθουν οι πολίτες πότε μια απλή παρέμβαση είναι ασφαλής και πότε χρειάζεται ειδικός.\\n[2] Η πρώτη δυσκολία ήταν η λανθασμένη προσδοκία ότι κάθε αντικείμενο θα επισκευαζόταν δωρεάν. Οι οργανωτές διευκρίνισαν ότι προσφέρεται χρόνος και γνώση, όχι εγγύηση αποτελέσματος. Αν χρειάζονται ανταλλακτικά, ο ιδιοκτήτης ενημερώνεται για το πιθανό κόστος πριν αποφασίσει. Καμία εργασία που απαιτεί ειδική άδεια δεν πραγματοποιείται από ανειδίκευτους συμμετέχοντες.\\n[3] Το σημαντικότερο όφελος δεν ήταν πάντα ένα αντικείμενο που λειτουργούσε ξανά. Μερικοί έμαθαν να περιγράφουν με ακρίβεια το πρόβλημα, άλλοι κατάλαβαν γιατί μια επισκευή δεν ήταν οικονομικά λογική. Αυτή η γνώση μπορεί να βοηθήσει και σε μελλοντική αγορά. Ωστόσο, οι οργανωτές δεν έχουν ακόμη στοιχεία που να δείχνουν αν μειώθηκαν συνολικά τα απορρίμματα της περιοχής.\\n[4] Για να συνεχιστεί η δράση, χρειάζεται σταθερός χώρος και οργάνωση των ραντεβού. Η μεγάλη συμμετοχή μιας ημέρας δημιουργεί ενθουσιασμό, αλλά μπορεί να οδηγήσει σε βιαστικές παρεμβάσεις αν δεν υπάρχουν αρκετοί καθοδηγητές. Γι’ αυτό αποφασίστηκε περιορισμένος αριθμός θέσεων και καταγραφή των αιτημάτων που δεν εξυπηρετούνται.\\n[5] Η πρωτοβουλία δείχνει ότι η περιβαλλοντική εκπαίδευση μπορεί να συνδεθεί με πρακτικές δεξιότητες. Δεν αποδεικνύει, όμως, ότι κάθε επισκευή συμφέρει ούτε ότι ο εθελοντισμός αρκεί για όλα. Η αξία της θα κριθεί από την ασφάλεια, τη σταθερότητα και όσα οι συμμετέχοντες μπορούν πλέον να κάνουν ή να εξηγήσουν μόνοι τους.", "canonical": {"path": "GreekOS_Academic_Corpus/items/U-B2-022-I07.json", "sha256": "fbe026750424e99a850fac495fbcb69e236ff90e2980a35e9cb5049a95292d7b"}, "error_tags": ["SUMMARY_FIDELITY_CANDIDATE"], "audio_job_ids": [], "competency_ids": ["B2-R02"], "model_response": "Ενδεικτικός πυρήνας: Το εργαστήριο προσφέρει καθοδήγηση και βοηθά τους συμμετέχοντες να κατανοήσουν πότε χρειάζεται ειδικός. Δεν εγγυάται αποτέλεσμα ούτε διαθέτει ακόμη στοιχεία για συνολική μείωση απορριμμάτων. Η συνέχεια απαιτεί ασφαλή οργάνωση.", "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "course_practice", "level": "B2", "stage": "independent", "prompt": "Γράψε περίληψη 110–140 λέξεων για ενημερωτικό δελτίο. Διατήρησε στόχο, οφέλη και δύο περιορισμούς. Μην προσθέσεις προσωπική σύσταση.", "skills": ["writing"], "status": "AUTHORED_DRAFT", "item_id": "U-B2-022-I07", "options": [], "unit_id": "U-B2-022", "version": "0.1.0", "language": "el+ru", "stimulus": "Μαθαίνοντας να επισκευάζουμε\\n[1] Ένα μικρό εργαστήριο επισκευών άρχισε να λειτουργεί σε έναν χώρο της γειτονιάς. Οι συμμετέχοντες φέρνουν χαλασμένα καθημερινά