KEG-B2-S02-I1	keg_b2	\N	open_response	B2	exam_holdout	\N	f	REVIEW_REQUIRED	{B2-SI01}	{}	{}	{}	{"type": "open_response", "level": "B2", "answer": [], "module": "keg_b2", "prompt": "Συζητήστε σε ζευγάρι. Η ομάδα σας διαθέτει χρήματα για μία μόνο εκπαιδευτική δράση το επόμενο τρίμηνο. Μπορεί να επιλέξει είτε ένα εντατικό σαββατοκύριακο είτε έξι σύντομες απογευματινές συναντήσεις. Το συνολικό κόστος είναι ίδιο. Καταλήξτε σε αιτιολογημένη πρόταση. Αν διαφωνείτε, διευκρινίστε σε ποια σημεία και ποιον συμβιβασμό θα μπορούσατε να δεχτείτε.", "rubric": "RUB-KEG-SPEAKING-PROJECT", "item_id": "KEG-B2-S02-I1", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "descriptive_rubric_with_evidence", "unlisted_valid_positions": "ACCEPT_WHEN_JUSTIFIED", "official_point_conversion": null, "audio_required_for_phonology": true, "automatic_final_score_allowed": false}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": null, "version": "0.1.0", "criteria": ["σαφής θέση με αιτιολόγηση", "ουσιαστική αντίδραση στο επιχείρημα του άλλου", "ερώτηση διευκρίνισης ή έλεγχος κατανόησης", "διαπραγμάτευση εφαρμόσιμης λύσης χωρίς απαίτηση συμφωνίας"], "stimulus": null, "canonical": {"path": "GreekOS_B2_Exam_Bank/items/KEG-B2-S02-I1.json", "sha256": "84a2c4bc6b0e3dd66f21f01648dcd004bd8ba90e981e007b3f5b880d15b286be"}, "error_tags": [], "audio_job_ids": [], "competency_ids": ["B2-SI01"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "exam_holdout", "level": "B2", "points": null, "prompt": "Συζητήστε σε ζευγάρι. Η ομάδα σας διαθέτει χρήματα για μία μόνο εκπαιδευτική δράση το επόμενο τρίμηνο. Μπορεί να επιλέξει είτε ένα εντατικό σαββατοκύριακο είτε έξι σύντομες απογευματινές συναντήσεις. Το συνολικό κόστος είναι ίδιο. Καταλήξτε σε αιτιολογημένη πρόταση. Αν 