KEG-B2-S03-I1	keg_b2	\N	open_response	B2	exam_holdout	\N	f	REVIEW_REQUIRED	{B2-SI01}	{}	{}	{}	{"type": "open_response", "level": "B2", "answer": [], "module": "keg_b2", "prompt": "Συζητήστε σε ζευγάρι. Η λέσχη σας θα εκδώσει ένα περιοδικό με κείμενα των μελών. Υπάρχουν χρήματα μόνο για μία μορφή: έντυπη έκδοση σε μικρό αριθμό αντιτύπων ή ψηφιακή έκδοση με προσβάσιμη μορφοποίηση. Η πρώτη έκδοση πρέπει να ετοιμαστεί σε δύο μήνες. Καταλήξτε σε αιτιολογημένη πρόταση. Αν διαφωνείτε, διευκρινίστε σε ποια σημεία και ποιον συμβιβασμό θα μπορούσατε να δεχτείτε.", "rubric": "RUB-KEG-SPEAKING-PROJECT", "item_id": "KEG-B2-S03-I1", "options": [], "release": {"state": "CONTENT_GATED", "learner_access": false, "review_required": true, "automatic_mastery": false}, "scoring": {"policy": {"method": "descriptive_rubric_with_evidence", "unlisted_valid_positions": "ACCEPT_WHEN_JUSTIFIED", "official_point_conversion": null, "audio_required_for_phonology": true, "automatic_final_score_allowed": false}, "strategy": "REVIEW_REQUIRED", "unlisted_answer": "HOLD_FOR_REVIEW_NO_PENALTY", "automatic_final_score_allowed": false}, "unit_id": null, "version": "0.1.0", "criteria": ["σαφής θέση με αιτιολόγηση", "ουσιαστική αντίδραση στο επιχείρημα του άλλου", "ερώτηση διευκρίνισης ή έλεγχος κατανόησης", "διαπραγμάτευση εφαρμόσιμης λύσης χωρίς απαίτηση συμφωνίας"], "stimulus": null, "canonical": {"path": "GreekOS_B2_Exam_Bank/items/KEG-B2-S03-I1.json", "sha256": "2bb9525c9b8bf2bd066b8c9a450159ec53dd3ae518e03fc5bbc5fcddc9efd826"}, "error_tags": [], "audio_job_ids": [], "competency_ids": ["B2-SI01"], "model_response": null, "requires_audio": false, "estimated_effort": null, "original_payload": {"pool": "exam_holdout", "level": "B2", "points": null, "prompt": "Συζητήστε σε ζευγάρι. Η λέσχη σας θα εκδώσει ένα περιοδικό με κείμενα των μελών. Υπάρχουν χρήματα μόνο για μία μορφή: έντυπη έκδοση σε μικρό αριθμό αντιτύπων ή ψηφιακή έκδοση με προσβάσιμη μορφοποίηση. Η πρώτη έκδοση πρέπει να ετοιμαστεί σε δύο μήνες. Καταλήξτε σε αιτιολογημένη πρόταση. Αν διαφωνείτε, διευκρινίστε σε ποια σημεία και ποιον συμβιβασμό θα μπορούσατε να δεχτείτε.", "skills": ["speaking"], "status": "AUTHOR_COMPLETE_AI_REVIEW_PENDING", "item_id": "KEG-B2-S03-I1", "unit_id": null, "version": "0.1.0", "licensing": {"originator": "GreekOS AI-assisted original authoring", "allowed_uses": ["project editing", "review", "future project publication after QA"], "license_type": "ORIGINAL_PROJECT_CONTENT", "derivative_allowed": true, "third_party_assets": false, "permission_evidence": "Создано по заданию владельца GreekOS; чужие главы и записи не воспроизводятся", "copyright_exclusivity_claimed": false, "commercial_web_distribution_allowed": true}, "rationale": "Assess individual contribution, not agreement with prescribed policy. No automatic failure for reasoned disagreement.", "rubric_id": "RUB-KEG-SPEAKING-PROJECT", "role_cards": {"A": "Προτιμάτε μικρή έντυπη έκδοση, επειδή αρκετά μέλη δεν χρησιμοποιούν συχνά υπολογιστή και θέλετε να διαβάζουν το περιοδικό σε συναντήσεις. Αναγνωρίστε ότι τα αντίτυπα είναι περιορισμένα. Εξηγήστε πώς θα μοιραστούν δίκαια και εξετάστε τα επιχειρήματα υπέρ της ψηφιακής μορφής.", "B": "Προτιμάτε ψηφιακή έκδοση, ώστε να διαβάζεται από μέλη που ζουν μακριά και να διορθώνεται εύκολα. Δεν θεωρείτε ότι όλοι έχουν ίδια πρόσβαση στην τεχνολογία. Προτείνετε υποστήριξη για αυτούς που δυσκολεύονται και συζητήστε ποια λύση είναι εφικτή μέσα στους δύο μήνες."}, "answer_type": "open_response", "exam_family": "KEG_B2", "publishable": false, "source_refs": ["V241"], "exam_form_id": "KEG-B2-S03", "human_review": "NOT_REVIEWED", "competency_ids": ["B2-SI01"], "source_claim_ids": ["EXAM11-OFFICIAL-B2-STRUCTURE"], "success_criteria": ["σαφής θέση με αιτιολόγηση", "ουσιαστική αντίδραση στο επιχείρημα του άλλου", "ερώτηση διευκρίνισης ή έλεγχος κατανόησης", "διαπραγμάτευση εφαρμόσιμης λύσης χωρίς απαίτηση συμφωνίας"], "accepted_variants": [], "canonical_answers": [], "response_evaluation": {"method": "descriptive_rubric_with_evidence", "unlisted_valid_positions": "ACCEPT_WHEN_JUSTIFIED", "official_point_conversion": null, "audio_required_for_phonology": true, "automatic_final_score_allowed": false}, "section_points_total": 20}, "prerequisite_ids": [], "source_claim_ids": ["EXAM11-OFFICIAL-B2-STRUCTURE"], "accepted_alternatives": []}	3a6c0eae35f9bb91a8870e15ae57227ca07905c2291019018bbfba70ac997f53	5157
