 "PEGP-BANK-1057906", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 21, "official_topic": 33, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}], "competency_id": "PEGP-P05-CUL-003-MC", "prerequisites": ["Basic Greek question comprehension", "Read the names and relation in this card"], "delayed_review": {"D7": "Ποιος δημιούργησε την «Κοιμωμένη»;", "D28": "Σύνδεσε προφορικά τον Γιαννούλη Χαλεπά με το έργο που μελετήσαμε.", "conditions": "Without card/options; score only requested relation, not literal base key"}, "mastery_criteria": {"fact": "Correct requested factual relation with no contradiction", "observed": false, "retention": "D7 and D28 completed independently; no observations yet", "production": "Independent completion of transfer task"}, "original_example": "Στη σημείωση για την «Κοιμωμένη» έγραψα το όνομα του Γιαννούλη Χαλεπά.", "practice_item_ids": ["PEGP-P05-CUL-003"], "observable_outcome": "Самостоятельно воспроизвести выбранную связь и применить её в исправлении/объяснении", "independent_transfer": {"prompt_el": "Ένας κατάλογος αποδίδει την «Κοιμωμένη» στον Ζογγολόπουλο. Διόρθωσε τον δημιουργό.", "conditions": "Hide original card and keys; produce own utterance; do not require details absent from prompt.", "model_not_exhaustive": true}, "prerequisite_support": {"probe": "Объясните по-русски, что именно требуется назвать в основном вопросе; затем прочтите ключевые имена.", "remediation": "Разобрать имя, падеж и отношение с русской опорой; закрыть модель перед самостоятельной попыткой."}}, {"rubric": {"0": "Required relation absent/false", "1": "Partial requested information or assistance", "2": "All requested factual information independently conveyed; equivalent wording accepted", "accent_policy": "Tag stress/form errors separately; do not turn correct fact into incorrect fact.", "language_score_separate": true}, "status": "AUTHORED_DRAFT", "card_id": "PEGP-P05-CUL-004-CARD", "item_id": "PEGP-P05-CUL-004", "theory_ru": "«Ομπρέλες» — название произведения Йоргоса Зонголопулоса. Сохраняйте пару «название — автор», не подменяйте её похожим именем другого скульптора. Эта карточка не подтверждает визуальное распознавание или местоположение произведения: такие вопросы здесь не задаются.", "source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057906#page=21", "sha256": "5163ff77c395802de2f24f88cfb65be7cc4681c128c6801e1d6d2566bceaea2d", "pdf_page": 21, "source_id": "PEGP-BANK-1057906", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 21, "official_topic": 33, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}], "competency_id": "PEGP-P05-CUL-004-MC", "prerequisites": ["Basic Greek question comprehension", "Read the names and relation in this card"], "delayed_review": {"D7": "Ποιος είναι ο δημιουργός των «Ομπρελών» στην κάρτα;", "D28": "Πες σε έναν φίλο δύο ζεύγη: Χαλεπάς — έργο και Ζογγολόπουλος — έργο.", "conditions": "Without card/options; score only requested relation, not literal base key"}, "mastery_criteria": {"fact": "Correct requested factual relation with no contradiction", "observed": false, "retention": "D7 and D28 completed independently; no observations yet", "production": "Independent completion of transfer task"}, "original_example": "Οι «Ομπρέλες» συνδέονται με τον Γιώργο Ζογγολόπουλο.", "practice_item_ids": ["PEGP-P05-CUL-004"], "observable_outcome": "Самостоятельно воспроизвести выбранную связь и применить её в исправлении/объяснении", "independent_transfer": {"prompt_el": "Διόρθωσε μια καρτέλα που αποδίδει τις «Ομπρέλες» στον Χαλεπά.", "conditions": "Hide original card and keys; produce own utterance; do not require details absent from prompt.", "model_not_exhaustive": true}, "prerequisite_support": {"probe": "Объясните по-русски, что именно требуется назвать в основном вопросе; затем прочтите ключевые имена.", "remediation": "Разобрать имя, падеж и отношение с русской опорой; закрыть модель перед самостоятельной попыткой."}}, {"rubric": {"0": "Required relation absent/false", "1": "Partial requested information or assistance", "2": "All requested factual information independently conveyed; equivalent wording accepted", "accent_policy": "Tag stress/form errors separately; do not turn correct fact into incorrect fact.", "language_score_separate": true}, "status": "AUTHORED_DRAFT", "card_id": "PEGP-P05-INS-001-CARD", "item_id": "PEGP-P05-INS-001", "theory_ru": "Дата первоначального вступления Греции в Совет Европы — 9 августа 1949 года. Совет Европы не равен Европейскому союзу или его Совету. Формулировка «первоначальное вступление» не утверждает непрерывность членства с этой даты. Изучаем историческую дату, не современные условия членства или гражданства.", "source_refs": [{"url": "https://exetaseis-ithageneia.ypes.gr/PAPYROS/services/CustomServices/getExamTopic/1057910#page=18", "sha256": "1f09beeb569cae5ac98d86a44f3d130ab3581eeb9e94edf2dcdae470ea379e0f", "pdf_page": 18, "source_id": "PEGP-BANK-1057910", "checked_on": "2026-10-20", "bank_version": "2026/11", "printed_page": 18, "official_topic": 33, "verification_scope": "Selected fact and answer actually read in retained PDF text and rendered page; no whole-bank completeness or current session guarantee"}], "competency_id": "PEGP-P05-INS-001-MC", "prerequisites": ["Basic Greek question comprehension", "Read the names and relation in this card"], "delayed_review": {"D7": "Ποιο έτος εντάχθηκε πρώτη φορά η Ελλάδα στο Συμβούλιο της Ευρώπης;", "D28": "Δώσε ολόκληρη την ημερομηνία της πρώτης ένταξης, όπως τη μελετήσαμε.", "conditions": "Without card/options; score only requested relation, not literal base key"}, "mastery_criteria": {"fact": "Correct requested factual relation with no contradiction", "obse