RG-0001	καλά	{"id": "RG-0001", "region": {"tag": "Greece", "evidence_strength": "general_dictionary"}, "safety": {"sexual": false, "outdated": "UNASSESSED_NOT_ASSUMED", "offensive": false, "disrespect": false, "child_delivery": "No automatic offensive/familiar expression production; neutral alternatives available", "flag_semantics": "Potential contextual risk; not a claim that every sense/token is offensive", "receptive_only": false, "profanity_level": 0, "register_mismatch": true, "potential_disrespect_risk": false}, "version": "0.1.3", "audience": {"currentness": "CURRENT_PEDAGOGICAL_ATTESTATION_2026_NOT_FREQUENCY", "time_period": "1998 dictionary; web edition undated; 2026-08-28", "age_evidence": "unknown; do not label youth slang without evidence"}, "category": "pragmatic_contrast", "contexts": [{"pitfall": "Удивление может прозвучать как упрёк; уточните смысл, а не угадывайте по знаку !.", "setting": "Original teaching situation", "relationship": "friends unless task specifies formal", "example_original": "Α: Πώς είσαι σήμερα;\\nΒ: Καλά, ευχαριστώ. Κοιμήθηκα αρκετά.", "neutral_alternative": "Είμαι καλά, ευχαριστώ. Κοιμήθηκα αρκετά.", "risk_interpretation": "Judge this context and relationship; card risk flags are caution indicators, not categorical offensiveness."}, {"pitfall": "No invariant translation inferred from spelling alone", "setting": "Contrast", "relationship": "context-specific", "example_original": "Α: Έχασα πάλι το κλειδί.\\nΒ: Καλά, πώς έγινε αυτό;", "neutral_alternative": "Πώς έχασες πάλι το κλειδί;", "risk_interpretation": "Judge this context and relationship; card risk flags are caution indicators, not categorical offensiveness."}], "meanings": [{"intent": "See contrast contexts", "gloss_ru": "Нейтрально «хорошо» о состоянии; согласие или удивление определяется продолжением и подачей. Одно написание не задаёт единственный тон.", "polarity": "context_dependent", "tone_audio_required": true}], "register": ["neutral"], "licensing": {"originator":